+  toggle(force) {
+    this.checked = force === undefined ? !this.checked : force;
+    if (this.itemId) writeFavorite(this.itemId, this.checked);
+    return this.checked;
+  }
+
+  #render() {
+    const { checked, disabled } = this;
+    this.#input.checked = checked;
+    this.#input.disabled = disabled;
+    this.#labelText.textContent = this.label;
+    this.#itemNameText.textContent = this.itemName ? ` ${this.itemName}` : '';
