--- /dev/null
+++ b/src/lib/webmcp.ts
@@ -0,0 +1,50 @@
+import type React from 'react';
+
+/**
+ * WebMCP declarative form API helpers.
+ * Browsers without WebMCP ignore the `tool*` attributes and the extra
+ * SubmitEvent members, so everything here degrades to a normal form.
+ */
+
+/** SubmitEvent extended with the WebMCP members (agentInvoked / respondWith). */
+export interface AgentSubmitEvent extends SubmitEvent {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+}
+
+/** Spreadable WebMCP form attributes (cast because React's types don't know them yet). */
+export function toolFormAttrs(opts: {
+  name: string;
+  description: string;
+  autoSubmit?: boolean;
+}): Record<string, string> {
+  return {
+    toolname: opts.name,
+    tooldescription: opts.description,
+    ...(opts.autoSubmit ? { toolautosubmit: '' } : {}),
+  };
+}
+
+/** Spreadable `toolparamdescription` attribute for an input/fieldset. */
+export function toolParamAttrs(description: string): Record<string, string> {
+  return { toolparamdescription: description };
+}
+
+/**
+ * Runs a form submission and, if an agent invoked it, hands the resulting
+ * message back to the agent. `respondWith` must be called synchronously while
+ * the submit event is dispatching, so it's called before awaiting anything.
+ */
+export function handleAgentAwareSubmit(
+  e: React.FormEvent<HTMLFormElement>,
+  submit: (data: FormData) => Promise<string>,
+): void {
+  e.preventDefault();
+  const native = e.nativeEvent as AgentSubmitEvent;
+  // Read from the DOM: an agent fills the inputs directly, which may not
+  // trigger React's onChange, so component state can be stale.
+  const result = submit(new FormData(e.currentTarget));
+  if (native.agentInvoked && typeof native.respondWith === 'function') {
+    native.respondWith(result);
+  }
+}
