diff --git a/src/utils/webmcp.ts b/src/utils/webmcp.ts
new file mode 100644
index 0000000..d1105bc
--- /dev/null
+++ b/src/utils/webmcp.ts
@@ -0,0 +1,89 @@
+import { useEffect, useRef } from 'react';
+
+/**
+ * Minimal typings + helpers for the WebMCP API (`navigator.modelContext`),
+ * which lets a page expose client-side functionality as tools to AI agents.
+ * https://github.com/webmachinelearning/webmcp
+ */
+
+export interface ToolResult {
+  content: Array<{ type: 'text'; text: string }>;
+  isError?: boolean;
+}
+
+export interface ModelContextTool<TInput = any> {
+  name: string;
+  description: string;
+  inputSchema?: Record<string, unknown>;
+  annotations?: { readOnlyHint?: boolean };
+  execute: (input: TInput, client?: unknown) => Promise<ToolResult> | ToolResult;
+}
+
+interface ModelContext {
+  registerTool: (
+    tool: ModelContextTool,
+    options?: { signal?: AbortSignal },
+  ) => { unregister?: () => void } | void;
+  unregisterTool?: (name: string) => void;
+}
+
+declare global {
+  interface Navigator {
+    modelContext?: ModelContext;
+  }
+}
+
+export const textResult = (text: string, isError = false): ToolResult => ({
+  content: [{ type: 'text', text }],
+  ...(isError ? { isError: true } : {}),
+});
+
+/**
+ * Registers a WebMCP tool for the lifetime of the calling component.
+ * `execute` always calls the latest closure, so it can safely use current state/setters.
+ * No-op in browsers without WebMCP support.
+ */
+export function useWebMCPTool<TInput>(tool: ModelContextTool<TInput>) {
+  const executeRef = useRef(tool.execute);
+  executeRef.current = tool.execute;
+
+  const { name, description } = tool;
+  const schemaKey = JSON.stringify(tool.inputSchema ?? null);
+  const annotationsKey = JSON.stringify(tool.annotations ?? null);
+
+  useEffect(() => {
+    const modelContext = typeof navigator !== 'undefined' ? navigator.modelContext : undefined;
+    if (!modelContext?.registerTool) return;
+
+    const controller = new AbortController();
+    let registration: { unregister?: () => void } | void;
+    try {
+      registration = modelContext.registerTool(
+        {
+          name,
+          description,
+          inputSchema: JSON.parse(schemaKey) ?? undefined,
+          annotations: JSON.parse(annotationsKey) ?? undefined,
+          execute: (input, client) => executeRef.current(input as TInput, client),
+        },
+        { signal: controller.signal },
+      );
+    } catch (err) {
+      console.warn(`[WebMCP] Failed to register tool "${name}":`, err);
+      return;
+    }
+
+    return () => {
+      controller.abort();
+      try {
+        if (registration && typeof registration.unregister === 'function') {
+          registration.unregister();
+        } else {
+          modelContext.unregisterTool?.(name);
+        }
+      } catch {
+        // Already unregistered (e.g. via the abort signal).
+      }
+    };
+  }, [name, description, schemaKey, annotationsKey]);
+}

