+  function addRipple(event, strength) {
+    const rect = canvas.getBoundingClientRect();
+    const i = nextRipple * 4;
+    ripples[i] = (event.clientX - rect.left) / rect.width;
+    ripples[i + 1] = (event.clientY - rect.top) / rect.height;
+    ripples[i + 2] = now();
+    ripples[i + 3] = strength;
+    nextRipple = (nextRipple + 1) % MAX_RIPPLES;
+  }
+
+  // Passive listeners: never block clicks, selection or scrolling.
+  canvas.addEventListener('pointerdown', (e) => addRipple(e, 1), { passive: true });
+  canvas.addEventListener('pointermove', (e) => {
+    const t = now();
+    if (t - lastMoveRipple < 0.14) return;
+    lastMoveRipple = t;
+    addRipple(e, 0.35);
+  }, { passive: true });
+
+  // --- Sizing (device pixels, observer created once, outside onpaint) ----
+  const resizeObserver = new ResizeObserver(([entry]) => {
+    const dpc = entry.devicePixelContentBoxSize;
+    const w = dpc ? dpc[0].inlineSize : Math.round(entry.contentRect.width * devicePixelRatio);
+    const h = dpc ? dpc[0].blockSize : Math.round(entry.contentRect.height * devicePixelRatio);
+    if (w === canvas.width && h === canvas.height) return;
+    canvas.width = w;
+    canvas.height = h;
+    needsUpload = true;
+    canvas.requestPaint();
+  });
