+    if (needsUpload || (event.changedElements && event.changedElements.length > 0)) {
+      try {
+        if (uploadElementWebGL(gl, canvas, texture, content, textureState)) {
+          hasTexture = true;
+          needsUpload = false;
+        }
+      } catch (err) {
+        console.error('texElementSubImage2D copy failed:', err);
+      }
+    }
+
+    gl.viewport(0, 0, canvas.width, canvas.height);
+    gl.clearColor(0, 0, 0, 0);
+    gl.clear(gl.COLOR_BUFFER_BIT);
+
+    if (hasTexture) {
+      gl.useProgram(program);
+      gl.bindVertexArray(vao);
+      gl.activeTexture(gl.TEXTURE0);
+      gl.bindTexture(gl.TEXTURE_2D, texture);
+      gl.uniform1i(loc.tex, 0);
+      gl.uniformMatrix4fv(loc.mvp, false, mvp);
+      gl.uniform2f(loc.res, canvas.width, canvas.height);
+      gl.uniform1f(loc.time, now());
+      gl.uniform1f(loc.motion, reducedMotion.matches ? 0 : 1);
+      gl.uniform4fv(loc.ripples, ripples);
+      gl.drawArrays(gl.TRIANGLES, 0, 6);
+    }
+
+    // Keep the live DOM exactly where its (undistorted) pixels are, so text
+    // stays selectable and the "Order Now" link stays clickable/focusable.
+    canvas.updateElementGeometry(content, {
+      canvasTransform: computeCanvasTransform(canvas, content, mvp),
+    });
+  };
+
+  // --- Animation loop: pauses off-screen and for reduced motion ---------
+  let onScreen = true;
+  let rafId = 0;
+
+  function frame() {
+    canvas.requestPaint();
+    rafId = requestAnimationFrame(frame);
+  }
+  function updateLoop() {
+    const shouldRun = onScreen && !reducedMotion.matches;
+    if (shouldRun && !rafId) {
+      rafId = requestAnimationFrame(frame);
+    } else if (!shouldRun && rafId) {
+      cancelAnimationFrame(rafId);
+      rafId = 0;
+    }
+    canvas.requestPaint(); // repaint once with the current motion setting
+  }
+
+  reducedMotion.addEventListener('change', updateLoop);
+
+  if ('contentVisibility' in document.documentElement.style) {
+    hero.addEventListener('contentvisibilityautostatechange', (e) => {
+      onScreen = !e.skipped;
+      updateLoop();
+    });
+  } else {
+    new IntersectionObserver(([entry]) => {
+      onScreen = entry.isIntersecting;
+      updateLoop();
+    }, { rootMargin: '200px' }).observe(hero);
+  }
+
+  updateLoop();
+}
+
+// ---------------------------------------------------------------------------
+// Helpers
+
+function createProgram(gl, vsSource, fsSource) {
+  const compile = (type, src) => {
+    const shader = gl.createShader(type);
+    gl.shaderSource(shader, src);
+    gl.compileShader(shader);
+    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
+      throw new Error(gl.getShaderInfoLog(shader) || 'Shader compile failed');
+    }
+    return shader;
+  };
+  const program = gl.createProgram();
+  gl.attachShader(program, compile(gl.VERTEX_SHADER, vsSource));
+  gl.attachShader(program, compile(gl.FRAGMENT_SHADER, fsSource));
+  gl.linkProgram(program);
+  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
+    throw new Error(gl.getProgramInfoLog(program) || 'Program link failed');
+  }
+  return program;
+}
+
+// Element size in canvas grid pixels, or null if it has no paint record yet.
+function getElementImageSize(canvas, element) {
+  let elementImage;
+  try {
+    elementImage = canvas.captureElementImage(element);
+  } catch {
+    canvas.requestPaint(); // retry on the next paint event
+    return null;
+  }
+  const width = Math.ceil(elementImage.width);
+  const height = Math.ceil(elementImage.height);
+  elementImage.close();
+  return width > 0 && height > 0 ? { width, height } : null;
+}
+
+// Allocates (mutable) texture storage only on first use or when the size changes.
+function allocateElementTexture(gl, texture, state, width, height) {
+  gl.bindTexture(gl.TEXTURE_2D, texture);
+  if (state.width === width && state.height === height) return;
+  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
+  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
+  state.width = width;
+  state.height = height;
