+/*
+ * Daily Grind client-side analytics.
+ *
+ * Records page views and click interactions, coalescing events into a single
+ * deferred background request:
+ *   - Each event (re)starts a debounce timer (DEBOUNCE_MS). Rapid interactions
+ *     therefore collapse into one request once activity settles.
+ *   - MAX_WAIT_MS caps how long events can sit in the queue under continuous
+ *     activity, and MAX_BATCH forces a flush if the queue grows large.
+ *   - When the page is hidden or unloaded (e.g. the user clicked a link and is
+ *     navigating away) the queue is flushed immediately with sendBeacon, which
+ *     the browser delivers in the background without delaying navigation.
+ *
+ * Privacy: only paths (no query strings or fragments, which may contain tokens),
+ * element tags/ids/classes and short link/button labels are sent. Users with
+ * Do Not Track / Global Privacy Control enabled are not tracked.
+ */
+(function () {
+  'use strict';
+
+  var ENDPOINT = '/api/analytics';
+  var DEBOUNCE_MS = 2000;
+  var MAX_WAIT_MS = 10000;
+  var MAX_BATCH = 50;
+  var MAX_QUEUE = 500;
+
+  if (
+    navigator.doNotTrack === '1' ||
+    window.doNotTrack === '1' ||
+    navigator.globalPrivacyControl === true
+  ) {
+    return;
+  }
+
+  var queue = [];
+  var debounceTimer = null;
+  var maxWaitTimer = null;
+  var sessionId = getSessionId();
+
+  function getSessionId() {
+    var key = 'dg_analytics_sid';
+    try {
+      var id = sessionStorage.getItem(key);
+      if (!id) {
+        id = randomId();
+        sessionStorage.setItem(key, id);
+      }
+      return id;
+    } catch (e) {
+      return randomId();
+    }
+  }
+
+  function randomId() {
+    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
+    return Date.now().toString(36) + Math.random().toString(36).slice(2);
+  }
+
+  // Strip query string and hash; only keep same-origin paths, or origin+path
+  // for external URLs.
+  function cleanUrl(href) {
+    try {
+      var u = new URL(href, location.href);
+      return u.origin === location.origin ? u.pathname : u.origin + u.pathname;
+    } catch (e) {
+      return null;
+    }
+  }
+
+  function clearTimers() {
+    clearTimeout(debounceTimer);
+    clearTimeout(maxWaitTimer);
+    debounceTimer = null;
+    maxWaitTimer = null;
+  }
+
+  function schedule() {
+    if (queue.length >= MAX_BATCH) {
+      flush(false);
+      return;
+    }
+    clearTimeout(debounceTimer);
+    debounceTimer = setTimeout(function () { flush(false); }, DEBOUNCE_MS);
+    if (!maxWaitTimer) {
+      maxWaitTimer = setTimeout(function () { flush(false); }, MAX_WAIT_MS);
+    }
+  }
