+    (function () {
+      const form = document.getElementById('order-form');
+      const sweetness = form.elements.sweetness;
+      const sweetnessOut = document.getElementById('sweetness-out');
+      const shots = form.elements.shots;
+      const caffeine = document.getElementById('caffeine');
+      const total = document.getElementById('order-total');
+      const date = form.elements.pickup_date;
+      const sweetLabels = ['None', 'Light', 'Regular', 'Sweet', 'Extra'];
+
+      // Pickup can be booked today through two weeks out.
+      const toISO = (d) => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
+      const today = new Date();
+      const later = new Date(today);
+      later.setDate(today.getDate() + 14);
+      date.min = toISO(today);
+      date.max = toISO(later);
+      date.defaultValue = toISO(today);
+
+      const price = (el) => parseFloat(el && el.dataset.price) || 0;
+
+      function update() {
+        const v = Number(sweetness.value);
+        sweetnessOut.value = sweetLabels[v];
+        sweetness.style.setProperty('--fill', (v / Number(sweetness.max)) * 100 + '%');
+
+        const n = Math.min(Math.max(Number(shots.value) || 0, 0), 6);
+        caffeine.value = n;
+        caffeine.textContent = n + ' shots';
+
+        let sum = price(form.elements.drink.selectedOptions[0]) +
+          price(form.querySelector('input[name="size"]:checked')) +
+          price(form.elements.milk.selectedOptions[0]) +
+          Math.max(n - 2, 0) * 0.75;
+        form.querySelectorAll('input[name="extras"]:checked').forEach((el) => { sum += price(el); });
