+  <script type="module">
+    // Maple Oat Latte promotion countdown.
+    // Dates are wall-clock midnights interpreted in the visitor's own time zone.
+    if (typeof Temporal === 'undefined') {
+      const { Temporal } = await import('https://esm.sh/temporal-polyfill@0.3');
+      globalThis.Temporal = Temporal;
+    }
+
+    const formatDuration = (duration) => {
+      if (typeof Intl.DurationFormat !== 'undefined') {
+        return duration.toLocaleString(undefined, { style: 'long' });
+      }
+      // Minimal fallback for engines without Intl.DurationFormat.
+      return ['days', 'hours']
+        .filter((unit) => duration[unit] !== 0 || unit === 'hours')
+        .map((unit) => new Intl.NumberFormat(undefined, {
+          style: 'unit', unit: unit.slice(0, -1), unitDisplay: 'long',
+        }).format(duration[unit]))
+        .join(', ');
+    };
+
+    const renderPromoTimer = (el) => {
+      const timeZone = Temporal.Now.timeZoneId();
+      const now = Temporal.Now.zonedDateTimeISO(timeZone);
+      const start = Temporal.PlainDate.from(el.dataset.start).toZonedDateTime({ timeZone });
+      const end = Temporal.PlainDate.from(el.dataset.end).toZonedDateTime({ timeZone });
+      const opts = { largestUnit: 'day', smallestUnit: 'hour', roundingMode: 'trunc' };
+
+      const remainingEl = el.querySelector('.promo-remaining');
+      const elapsedEl = el.querySelector('.promo-elapsed');
+      const dateFmt = { dateStyle: 'long', timeStyle: 'short' };
+      const endLabel = end.toLocaleString(undefined, dateFmt);
+      const startLabel = start.toLocaleString(undefined, dateFmt);
+
+      if (Temporal.ZonedDateTime.compare(now, start) < 0) {
+        el.dataset.state = 'upcoming';
+        const untilStart = now.until(start, opts);
+        remainingEl.innerHTML = `Offer starts in <strong>${formatDuration(untilStart)}</strong>.`;
+        elapsedEl.hidden = true;
+        return;
+      }
+
+      const elapsed = now.since(start, opts);
+      const remaining = now.until(end, opts);
+
+      if (remaining.sign <= 0) {
+        el.dataset.state = 'ended';
+        remainingEl.innerHTML = `This offer ended on <time datetime="${end.toPlainDate()}">${endLabel}</time>.`;
+        const sinceEnd = now.since(end, opts);
+        elapsedEl.innerHTML = `Ran for <strong>${formatDuration(end.since(start, opts))}</strong>; ended <strong>${formatDuration(sinceEnd)}</strong> ago.`;
+      } else {
+        el.dataset.state = 'active';
+        remainingEl.innerHTML = `<strong><time datetime="${remaining}">${formatDuration(remaining)}</time></strong> left &mdash; ends <time datetime="${end.toPlainDate()}">${endLabel}</time>.`;
+        elapsedEl.innerHTML = `Promotion started <strong><time datetime="${elapsed}">${formatDuration(elapsed)}</time></strong> ago (<time datetime="${start.toPlainDate()}">${startLabel}</time>).`;
+      }
+      elapsedEl.hidden = false;
+    };
+
+    document.querySelectorAll('.promo-timer').forEach(renderPromoTimer);
+  </script>
+
 </body>

