+  <script>
+    /*
+     * Location-agnostic ("floating") preferences.
+     *
+     * The pickup time and anniversary are stored exactly as the user picked them:
+     * plain "HH:MM" and "YYYY-MM-DD" strings, with no time zone or UTC offset attached.
