+      var timeInput = document.getElementById('pickup-time');
+      var dateInput = document.getElementById('coffee-anniversary');
+      var summary = document.getElementById('prefs-summary');
+      var banner = document.getElementById('prefs-banner');
+      var lastReminderDay = null;
+
+      function pad(n) { return (n < 10 ? '0' : '') + n; }
+
+      function isValidDate(str) {
+        var m = DATE_RE.exec(str);
+        if (!m) return false;
+        var y = +m[1], mo = +m[2], d = +m[3];
+        var leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
+        var days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
+        return d <= days;
+      }
+
+      // Format "HH:MM" -> "8:05 AM" purely by string arithmetic (no Date / time zone).
+      function formatTime(str) {
+        var m = TIME_RE.exec(str);
+        if (!m) return str;
+        var h = +m[1];
+        var suffix = h < 12 ? 'AM' : 'PM';
+        var h12 = h % 12 === 0 ? 12 : h % 12;
+        return h12 + ':' + m[2] + ' ' + suffix;
+      }
+
+      // Format "YYYY-MM-DD" -> "March 14, 2021" purely by string parsing.
+      function formatDate(str) {
+        var m = DATE_RE.exec(str);
+        if (!m) return str;
+        return MONTHS[+m[2] - 1] + ' ' + (+m[3]) + ', ' + m[1];
