+          dayKey: n.getFullYear() + '-' + pad(n.getMonth() + 1) + '-' + pad(n.getDate())
+        };
+      }
+
+      function load() {
+        try {
+          var raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
+          if (!raw || typeof raw !== 'object') return null;
+          return {
+            pickupTime: TIME_RE.test(raw.pickupTime) ? raw.pickupTime : '',
+            coffeeAnniversary: isValidDate(raw.coffeeAnniversary) ? raw.coffeeAnniversary : ''
+          };
+        } catch (e) {
+          return null;
+        }
+      }
