+        if (prefs.pickupTime) parts.push('Daily pickup reminder: ' + formatTime(prefs.pickupTime) + ' (local time, wherever you are)');
+        if (prefs.coffeeAnniversary) parts.push('Coffee anniversary: ' + formatDate(prefs.coffeeAnniversary));
