+  <script>
+    (() => {
+      const STORAGE_KEY = 'dailyGrindOrder';
+      const countEl = document.getElementById('order-count');
+      const statusEl = document.getElementById('order-status');
+      const fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+
+      const load = () => {
+        try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; } catch { return []; }
+      };
+      const save = (order) => {
+        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(order)); } catch { /* storage unavailable */ }
+      };
+      const renderCount = (order) => {
+        countEl.textContent = order.reduce((n, line) => n + line.qty, 0);
+      };
+
+      let order = load();
+      renderCount(order);
+
+      document.querySelectorAll('.order-form').forEach((form) => {
+        const price = form.querySelector('.price');
+        const button = form.querySelector('.add-btn');
+        let resetTimer;
+
+        const updatePrice = () => {
+          const selected = form.querySelector('input[name="size"]:checked');
+          price.value = fmt.format(Number(selected.dataset.price));
+        };
+        form.addEventListener('change', updatePrice);
+        updatePrice();
+
+        form.addEventListener('submit', (event) => {
+          event.preventDefault();
+          const selected = form.querySelector('input[name="size"]:checked');
+          const { item, name } = form.dataset;
+          const size = selected.value;
+          const existing = order.find((line) => line.item === item && line.size === size);
+          if (existing) {
+            existing.qty += 1;
+          } else {
+            order.push({ item, name, size, price: Number(selected.dataset.price), qty: 1 });
+          }
+          save(order);
+          renderCount(order);
+
+          statusEl.textContent = `Added a ${size} ${name} to your order.`;
+          button.classList.add('added');
+          button.firstChild.textContent = 'Added ✓';
+          clearTimeout(resetTimer);
+          resetTimer = setTimeout(() => {
+            button.classList.remove('added');
+            button.firstChild.textContent = 'Add to order';
+          }, 1600);
+        });
+      });
+    })();
+  </script>
