+  <script>
+    (function () {
+      var STORAGE_KEY = 'dailyGrindOrder';
+      var countEl = document.querySelector('.order-count');
+      var toast = document.querySelector('.toast');
+      var toastTimer;
+
+      function loadOrder() {
+        try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
+        catch (e) { return []; }
+      }
+
+      function saveOrder(order) {
+        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(order)); } catch (e) { /* storage unavailable */ }
+      }
+
+      function renderCount(order) {
+        var total = order.reduce(function (n, line) { return n + line.qty; }, 0);
+        countEl.dataset.count = total;
+        countEl.innerHTML = '<span class="visually-hidden">Items: </span>' + total;
+      }
+
+      function showToast(msg) {
+        toast.textContent = msg;
+        toast.classList.add('show');
+        clearTimeout(toastTimer);
+        toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 2500);
+      }
+
+      renderCount(loadOrder());
+
+      document.querySelectorAll('.drink-card').forEach(function (card) {
+        var form = card.querySelector('.drink-form');
+        var priceEl = card.querySelector('.drink-price');
+        var button = card.querySelector('.add-btn');
+        var name = card.querySelector('h3').textContent;
+        var img = card.querySelector('.drink-media img');
