+    (function () {
+      var carousel = document.querySelector('.carousel');
+      if (!carousel) return;
+      var items = Array.prototype.slice.call(carousel.querySelectorAll('.carousel-item'));
+
+      function setSnapped(target) {
+        items.forEach(function (item) {
+          item.classList.toggle('is-snapped', item === target);
+        });
+      }
+
+      // Pick the item whose center is closest to the carousel's center.
+      function updateFromPosition() {
+        var rect = carousel.getBoundingClientRect();
+        var center = rect.left + rect.width / 2;
+        var closest = null;
+        var best = Infinity;
+        items.forEach(function (item) {
+          var r = item.getBoundingClientRect();
+          var dist = Math.abs(r.left + r.width / 2 - center);
+          if (dist < best) { best = dist; closest = item; }
+        });
+        setSnapped(closest);
+      }
+
+      if ('onscrollsnapchange' in window) {
+        carousel.addEventListener('scrollsnapchange', function (e) {
+          var target = e.snapTargetInline;
+          if (target) setSnapped(target.closest('.carousel-item'));
+        });
+      } else if ('onscrollend' in window) {
+        carousel.addEventListener('scrollend', updateFromPosition);
+      } else {
+        var timer;
+        carousel.addEventListener('scroll', function () {
+          clearTimeout(timer);
+          timer = setTimeout(updateFromPosition, 100);
+        }, { passive: true });
+      }
+
+      window.addEventListener('resize', updateFromPosition);
+      updateFromPosition();
+    })();
+  </script>
