diff --git a/delivery-notes.js b/delivery-notes.js
new file mode 100644
index 0000000..a3f4b94
--- /dev/null
+++ b/delivery-notes.js
@@ -0,0 +1,430 @@
+// Encrypted delivery notes for The Daily Grind.
+//
+// Envelope encryption flow:
+//   1. The shop (recipient) holds a non-extractable key pair persisted in IndexedDB
+//      and publishes only its public key bytes.
+//   2. For every note the customer's browser imports that public key, establishes a
+//      fresh one-time shared key (KEM encapsulation, or ephemeral-static key agreement
+//      on older browsers) and encrypts the note with an AEAD cipher, binding the
+//      order ID and suite as additional authenticated data.
+//   3. Only { capsule, iv, ciphertext } leaves the browser — never the plaintext.
+//
+// NOTE: This static demo generates the shop key pair locally so the round trip can be
+// shown on one page. In production the private key lives only on the shop's device and
+// customers fetch the published public key from the server.
+
+const ENVELOPE_VERSION = 1;
+const HKDF_INFO = new TextEncoder().encode('daily-grind/delivery-notes/v1');
+
+const SUITES = {
+  HYBRID_PQ: 'MLKEM768-X25519+ChaCha20-Poly1305',
+  X25519: 'X25519+HKDF-SHA256+AES-GCM',
+  P256: 'ECDH-P256+HKDF-SHA256+AES-GCM',
+};
+
+const SUITE_LABELS = {
+  [SUITES.HYBRID_PQ]: 'Hybrid post-quantum (ML-KEM-768 + X25519) with ChaCha20-Poly1305',
+  [SUITES.X25519]: 'Classical X25519 key agreement with HKDF and AES-256-GCM',
+  [SUITES.P256]: 'Classical ECDH P-256 key agreement with HKDF and AES-256-GCM',
+};
+
+// Public key sizes used to pick the algorithm when importing raw bytes.
+const PUBLIC_KEY_SUITES = {
+  1216: SUITES.HYBRID_PQ,
+  32: SUITES.X25519,
+  65: SUITES.P256,
+};
+
+/* ---------------------------------------------------------------------------
+ * Byte helpers (Uint8Array.prototype.toBase64 is not yet available everywhere)
+ * ------------------------------------------------------------------------- */
+
+function toBase64(bytes) {
+  if (typeof bytes.toBase64 === 'function') return bytes.toBase64();
+  let binary = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(binary);
+}
+
+function fromBase64(text) {
+  if (typeof Uint8Array.fromBase64 === 'function') return Uint8Array.fromBase64(text);
+  return Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
+}
+
+/* ---------------------------------------------------------------------------
+ * Capability detection
+ * ------------------------------------------------------------------------- */
+
+function supportsPostQuantumEnvelope() {
+  return (
+    typeof globalThis.SubtleCrypto?.supports === 'function' &&
+    SubtleCrypto.supports('encapsulateKey', 'MLKEM768-X25519', 'ChaCha20-Poly1305') &&
+    SubtleCrypto.supports('decapsulateKey', 'MLKEM768-X25519', 'ChaCha20-Poly1305')
+  );
+}
+
+async function supportsX25519() {
+  try {
+    await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+    return true;
+  } catch {
+    return false;
+  }
+}
+
+async function pickSuite() {
+  if (supportsPostQuantumEnvelope()) return SUITES.HYBRID_PQ;
+  if (await supportsX25519()) return SUITES.X25519;
+  return SUITES.P256;
+}
+
+function agreementAlgorithm(suite) {
+  return suite === SUITES.X25519 ? { name: 'X25519' } : { name: 'ECDH', namedCurve: 'P-256' };
+}
+
+/* ---------------------------------------------------------------------------
+ * Shop (recipient) key management, persisted in IndexedDB
+ * ------------------------------------------------------------------------- */
+
+const DB_NAME = 'daily-grind-delivery-notes';
+const STORE = 'keys';
+const KEY_ID = 'shop-recipient-key';
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const request = indexedDB.open(DB_NAME, 1);
+    request.onupgradeneeded = () => request.result.createObjectStore(STORE);
+    request.onsuccess = () => resolve(request.result);
+    request.onerror = () => reject(request.error);
+  });
+}
+
+async function idb(mode, fn) {
+  const db = await openDb();
+  try {
+    return await new Promise((resolve, reject) => {
+      const tx = db.transaction(STORE, mode);
+      const request = fn(tx.objectStore(STORE));
+      tx.oncomplete = () => resolve(request.result);
+      tx.onerror = () => reject(tx.error);
+      tx.onabort = () => reject(tx.error);
+    });
+  } finally {
+    db.close();
+  }
+}
+
+async function generateRecipientKeys(suite) {
+  // Private keys are non-extractable: they can be structured-cloned into IndexedDB
+  // but their bytes can never be exported by script.
+  let keyPair;
+  if (suite === SUITES.HYBRID_PQ) {
+    keyPair = await crypto.subtle.generateKey('MLKEM768-X25519', false, [
+      'encapsulateKey',
+      'decapsulateKey',
+    ]);
+  } else {
+    keyPair = await crypto.subtle.generateKey(agreementAlgorithm(suite), false, ['deriveBits']);
+  }
+  const format = suite === SUITES.HYBRID_PQ ? 'raw-public' : 'raw';
+  const publicKeyBytes = new Uint8Array(await crypto.subtle.exportKey(format, keyPair.publicKey));
+  return { suite, keyPair, publicKeyBytes, createdAt: new Date().toISOString() };
+}
+
+async function loadOrCreateRecipient({ rotate = false } = {}) {
+  const suite = await pickSuite();
+  if (!rotate) {
+    try {
+      const stored = await idb('readonly', (store) => store.get(KEY_ID));
+      if (stored?.suite === suite && stored.keyPair?.privateKey) return stored;
+    } catch (error) {
+      console.warn('Could not read stored shop key; generating a new one.', error);
+    }
+  }
+  const record = await generateRecipientKeys(suite);
+  try {
+    await idb('readwrite', (store) => store.put(record, KEY_ID));
+  } catch (error) {
+    console.warn('Could not persist shop key; it will last for this session only.', error);
+  }
+  return record;
+}
+
+/* ---------------------------------------------------------------------------
+ * Shared-key establishment
+ * ------------------------------------------------------------------------- */
+
+async function deriveAesKey(privateKey, peerPublicKey, suite, salt) {
+  const sharedSecret = await crypto.subtle.deriveBits(
+    { ...agreementAlgorithm(suite), public: peerPublicKey },
+    privateKey,
+    256,
+  );
+  const hkdfKey = await crypto.subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  return crypto.subtle.deriveKey(
+    { name: 'HKDF', hash: 'SHA-256', salt, info: HKDF_INFO },
+    hkdfKey,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    ['encrypt', 'decrypt'],
+  );
+}
+
+/** Sender side: produce a one-time AEAD key plus the capsule the shop needs to recover it. */
+async function encapsulate(recipientPublicKeyBytes) {
+  const suite = PUBLIC_KEY_SUITES[recipientPublicKeyBytes.byteLength];
+  if (!suite) throw new Error('Unrecognised shop public key.');
+
+  if (suite === SUITES.HYBRID_PQ) {
+    const publicKey = await crypto.subtle.importKey(
+      'raw-public',
+      recipientPublicKeyBytes,
+      'MLKEM768-X25519',
+      true,
+      ['encapsulateKey'],
+    );
+    const { sharedKey, ciphertext } = await crypto.subtle.encapsulateKey(
+      'MLKEM768-X25519',
+      publicKey,
+      'ChaCha20-Poly1305',
+      false,
+      ['encrypt'],
+    );
+    return { suite, sharedKey, capsule: new Uint8Array(ciphertext) };
+  }
+
+  // Classical fallback: ephemeral-static key agreement. The ephemeral public key is the capsule.
+  const algorithm = agreementAlgorithm(suite);
+  const publicKey = await crypto.subtle.importKey('raw', recipientPublicKeyBytes, algorithm, true, []);
+  const ephemeral = await crypto.subtle.generateKey(algorithm, false, ['deriveBits']);
+  const capsule = new Uint8Array(await crypto.subtle.exportKey('raw', ephemeral.publicKey));
+  // Salt binds the derived key to both public keys involved in this exchange.
+  const salt = concatBytes(capsule, recipientPublicKeyBytes);
+  const sharedKey = await deriveAesKey(ephemeral.privateKey, publicKey, suite, salt);
+  return { suite, sharedKey, capsule };
+}
+
+/** Recipient side: recover the one-time AEAD key from the capsule. */
+async function decapsulate(recipient, suite, capsule) {
+  if (suite !== recipient.suite) throw new Error('This note was sealed for a different shop key.');
+
+  if (suite === SUITES.HYBRID_PQ) {
+    return crypto.subtle.decapsulateKey(
+      'MLKEM768-X25519',
+      recipient.keyPair.privateKey,
+      capsule,
+      'ChaCha20-Poly1305',
+      false,
+      ['decrypt'],
+    );
+  }
+
+  const ephemeralPublicKey = await crypto.subtle.importKey(
+    'raw',
+    capsule,
+    agreementAlgorithm(suite),
+    true,
+    [],
+  );
+  const salt = concatBytes(capsule, recipient.publicKeyBytes);
+  return deriveAesKey(recipient.keyPair.privateKey, ephemeralPublicKey, suite, salt);
+}
+
+function concatBytes(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.byteLength, 0));
+  let offset = 0;
+  for (const part of parts) {
+    out.set(part, offset);
+    offset += part.byteLength;
+  }
+  return out;
+}
+
+/* ---------------------------------------------------------------------------
+ * Authenticated encryption of the note
+ * ------------------------------------------------------------------------- */
+
+function associatedData({ v, suite, orderId }) {
+  // Unencrypted metadata is authenticated: changing any of it makes decryption fail.
+  return new TextEncoder().encode(JSON.stringify({ v, suite, orderId }));
+}
+
+async function sealNote(recipientPublicKeyBytes, orderId, plaintext) {
+  const { suite, sharedKey, capsule } = await encapsulate(recipientPublicKeyBytes);
+  const header = { v: ENVELOPE_VERSION, suite, orderId };
+  const iv = crypto.getRandomValues(new Uint8Array(12)); // fresh 96-bit IV per message
+  const ciphertext = new Uint8Array(
+    await crypto.subtle.encrypt(
+      { name: sharedKey.algorithm.name, iv, additionalData: associatedData(header) },
+      sharedKey,
+      new TextEncoder().encode(plaintext),
+    ),
+  );
+  return {
+    ...header,
+    capsule: toBase64(capsule),
+    iv: toBase64(iv),
+    ciphertext: toBase64(ciphertext),
+  };
+}
+
+async function openNote(recipient, envelope) {
+  if (envelope?.v !== ENVELOPE_VERSION) throw new Error('Unsupported envelope version.');
+  const key = await decapsulate(recipient, envelope.suite, fromBase64(envelope.capsule));
+  const plaintext = await crypto.subtle.decrypt(
+    {
+      name: key.algorithm.name,
+      iv: fromBase64(envelope.iv),
+      additionalData: associatedData(envelope),
+    },
+    key,
+    fromBase64(envelope.ciphertext),
+  );
+  return new TextDecoder().decode(plaintext);
+}
+
+/* ---------------------------------------------------------------------------
+ * UI wiring
+ * ------------------------------------------------------------------------- */
+
+const form = document.getElementById('delivery-note-form');
+const fieldset = document.getElementById('delivery-note-fields');
+const noteInput = document.getElementById('delivery-note');
+const orderInput = document.getElementById('order-id');
+const envelopeField = document.getElementById('envelope-field');
+const status = document.getElementById('delivery-note-status');
+const suiteBadge = document.getElementById('crypto-suite');
+const fingerprintEl = document.getElementById('shop-key-fingerprint');
+const envelopeOutput = document.getElementById('envelope-output');
+const inboxForm = document.getElementById('shop-inbox-form');
+const inboxInput = document.getElementById('inbox-envelope');
+const inboxStatus = document.getElementById('inbox-status');
+const decryptedOutput = document.getElementById('decrypted-note');
+const rotateButton = document.getElementById('rotate-key');
+const tamperButton = document.getElementById('tamper-envelope');
+
+let recipient;
+
+async function fingerprint(bytes) {
+  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
+  return Array.from(digest.subarray(0, 8), (b) => b.toString(16).padStart(2, '0'))
+    .join('')
+    .match(/.{4}/g)
+    .join(' ');
+}
+
+async function showRecipient() {
+  suiteBadge.textContent = SUITE_LABELS[recipient.suite];
+  suiteBadge.dataset.pq = String(recipient.suite === SUITES.HYBRID_PQ);
+  fingerprintEl.textContent = await fingerprint(recipient.publicKeyBytes);
+}
+
+function setStatus(el, message, kind = 'info') {
+  el.textContent = message;
+  el.dataset.kind = kind;
+}
+
+async function init() {
+  if (!globalThis.isSecureContext || !globalThis.crypto?.subtle) {
+    setStatus(status, 'Encrypted notes need a secure (HTTPS) connection. Please reload over HTTPS.', 'error');
+    return;
+  }
+  try {
+    recipient = await loadOrCreateRecipient();
+    await showRecipient();
+    fieldset.disabled = false;
+    setStatus(status, 'Ready. Your note is encrypted on this device before it is sent.');
+  } catch (error) {
+    console.error(error);
+    setStatus(status, 'Encryption is unavailable in this browser, so notes are turned off.', 'error');
+  }
+}
+
+noteInput.addEventListener('input', () => noteInput.setCustomValidity(''));
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (!form.reportValidity()) {
+    form.querySelector(':invalid')?.focus();
+    return;
+  }
+
+  const submitButton = form.querySelector('button[type="submit"]');
+  submitButton.disabled = true;
+  setStatus(status, 'Encrypting…');
+  try {
+    // Customers only ever use the shop's *public* key bytes.
+    const envelope = await sealNote(recipient.publicKeyBytes, orderInput.value.trim(), noteInput.value);
+    const serialized = JSON.stringify(envelope, null, 2);
+    envelopeField.value = JSON.stringify(envelope);
+    noteInput.value = ''; // drop the plaintext from the page as soon as it's sealed
+    envelopeOutput.textContent = serialized;
+    inboxInput.value = serialized;
+    tamperButton.hidden = false;
+    // This static demo has no backend; a real deployment would POST `envelopeField` here:
+    // await fetch(form.action, { method: 'POST', body: new FormData(form) });
+    setStatus(status, `Note sealed for order ${envelope.orderId}. Only the shop can read it.`, 'success');
+  } catch (error) {
+    console.error(error);
+    setStatus(status, 'Could not encrypt your note. Please try again.', 'error');
+  } finally {
+    submitButton.disabled = false;
+  }
+});
+
+inboxForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  decryptedOutput.textContent = '';
+  let envelope;
+  try {
+    envelope = JSON.parse(inboxInput.value);
+  } catch {
+    setStatus(inboxStatus, 'That is not a valid sealed note (JSON expected).', 'error');
+    return;
+  }
+  try {
+    const note = await openNote(recipient, envelope);
+    decryptedOutput.textContent = note; // textContent: never interpret customer input as HTML
+    setStatus(inboxStatus, `Verified and decrypted note for order ${envelope.orderId}.`, 'success');
+  } catch (error) {
+    console.error(error);
+    const tampered = error?.name === 'OperationError';
+    setStatus(
+      inboxStatus,
+      tampered
+        ? 'Authentication failed: this note was altered or sealed for a different key.'
+        : `Could not open note: ${error.message}`,
+      'error',
+    );
+  }
+});
+
+tamperButton.addEventListener('click', () => {
+  try {
+    const envelope = JSON.parse(inboxInput.value);
+    // Change the order ID: the ciphertext is untouched, but the AAD no longer matches.
+    envelope.orderId = `${envelope.orderId}-X`;
+    inboxInput.value = JSON.stringify(envelope, null, 2);
+    setStatus(inboxStatus, 'Order ID altered. Try decrypting to see the tamper check.', 'info');
+  } catch {
+    setStatus(inboxStatus, 'Seal a note first.', 'error');
+  }
+});
+
+rotateButton.addEventListener('click', async () => {
+  rotateButton.disabled = true;
+  try {
+    recipient = await loadOrCreateRecipient({ rotate: true });
+    await showRecipient();
+    setStatus(inboxStatus, 'Shop key rotated. Notes sealed for the old key can no longer be opened.', 'info');
+  } catch (error) {
+    console.error(error);
+    setStatus(inboxStatus, 'Key rotation failed.', 'error');
+  } finally {
+    rotateButton.disabled = false;
+  }
+});
+
+init();
