+import {
+  SUITES, MAX_NOTE_CHARS, encryptNote, decryptNote, generateRecipientKeyPair,
+  validatePublicKey, fromB64u,
+} from './note-crypto.js';
+
+// The shop publishes its delivery-note public keys here: { keys: [{ kid, suite, publicKey (base64url) }] }
+const KEY_DIRECTORY_URL = '/api/delivery-notes/keys';
+const SUBMIT_URL = '/api/delivery-notes';
+
+const $ = (id) => document.getElementById(id);
+const form = $('dn-form');
+const noteEl = $('dn-note');
+const orderEl = $('dn-order');
+const suiteEl = $('dn-suite');
+const counterEl = $('dn-counter');
+const statusEl = $('dn-status');
+const keyInfoEl = $('dn-key-info');
+const resultEl = $('dn-result');
+const envelopeEl = $('dn-envelope');
+const copyBtn = $('dn-copy');
+const verifyBtn = $('dn-verify');
+const submitBtn = $('dn-submit');
+
+let recipients = {}; // suite -> { kid, suite, publicKey }
+let demoSecretKeys = null; // suite -> secretKey (only in demo mode)
+let lastEnvelope = null;
+
+function setStatus(msg, kind = 'info') {
+  statusEl.textContent = msg;
+  statusEl.dataset.kind = kind;
+}
+
+async function loadRecipientKeys() {
+  try {
+    const res = await fetch(KEY_DIRECTORY_URL, { cache: 'no-store', credentials: 'same-origin' });
+    if (!res.ok) throw new Error(`HTTP ${res.status}`);
+    const data = await res.json();
+    const found = {};
+    for (const k of data.keys ?? []) {
+      if (!SUITES[k.suite] || found[k.suite]) continue;
+      try {
+        found[k.suite] = { kid: String(k.kid), suite: k.suite, publicKey: validatePublicKey(k.suite, fromB64u(k.publicKey)) };
+      } catch { /* skip malformed key */ }
+    }
+    if (!Object.keys(found).length) throw new Error('no usable keys');
+    recipients = found;
+    demoSecretKeys = null;
+    keyInfoEl.textContent = 'Using The Daily Grind’s published delivery-note keys.';
+    keyInfoEl.dataset.kind = 'ok';
+  } catch {
+    // No key directory reachable (e.g. static preview): fall back to an ephemeral demo key pair
+    // whose secret half lives only in this tab so the full encrypt/decrypt flow can be shown.
+    recipients = {};
+    demoSecretKeys = {};
+    for (const suite of Object.keys(SUITES)) {
+      const kp = generateRecipientKeyPair(suite);
+      const kid = `demo-${suite}-${Date.now().toString(36)}`;
+      recipients[suite] = { kid, suite, publicKey: kp.publicKey };
+      demoSecretKeys[suite] = kp.secretKey;
+    }
+    keyInfoEl.textContent = 'Demo mode: shop key directory unavailable, so a temporary key pair was generated in this tab. Notes encrypted now can only be read here.';
+    keyInfoEl.dataset.kind = 'warn';
+  }
+
+  for (const opt of suiteEl.options) opt.disabled = !recipients[opt.value];
+  if (!recipients[suiteEl.value]) {
+    const first = [...suiteEl.options].find((o) => !o.disabled);
+    if (first) suiteEl.value = first.value;
+  }
+  submitBtn.disabled = !Object.keys(recipients).length;
+}
+
+function updateCounter() {
+  counterEl.textContent = `${noteEl.value.length} / ${MAX_NOTE_CHARS}`;
+}
+
+async function trySubmit(envelope) {
+  if (demoSecretKeys) return false;
+  try {
+    const res = await fetch(SUBMIT_URL, {
+      method: 'POST',
+      credentials: 'same-origin',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify(envelope),
+    });
+    return res.ok;
+  } catch {
+    return false;
+  }
+}
+
+form.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  const recipient = recipients[suiteEl.value];
+  if (!recipient) return setStatus('No key available for the selected protection level.', 'error');
+
+  submitBtn.disabled = true;
+  setStatus('Encrypting in your browser…');
+  try {
+    const envelope = await encryptNote(recipient, noteEl.value, orderEl.value.trim());
+    lastEnvelope = envelope;
+    noteEl.value = ''; // don't keep plaintext around in the DOM
+    updateCounter();
+
+    envelopeEl.value = JSON.stringify(envelope, null, 2);
+    resultEl.hidden = false;
+    verifyBtn.hidden = !demoSecretKeys;
+
+    const sent = await trySubmit(envelope);
+    setStatus(
+      sent
+        ? `Encrypted with ${SUITES[envelope.suite].short} + AES-256-GCM and attached to your order.`
+        : `Encrypted with ${SUITES[envelope.suite].short} + AES-256-GCM. ${demoSecretKeys ? 'Demo mode: nothing was sent.' : 'Could not reach the server — copy the envelope below to retry.'}`,
+      sent || demoSecretKeys ? 'ok' : 'warn',
+    );
+  } catch (err) {
+    setStatus(err.message || 'Encryption failed.', 'error');
+  } finally {
+    submitBtn.disabled = false;
+  }
+});
+
+verifyBtn.addEventListener('click', async () => {
+  if (!lastEnvelope || !demoSecretKeys) return;
+  try {
+    const text = await decryptNote(lastEnvelope, demoSecretKeys[lastEnvelope.suite]);
+    setStatus(`Shop-side check passed (authentication tag verified). Decrypted note: “${text}”`, 'ok');
+  } catch {
+    setStatus('Decryption failed: envelope was modified or the key does not match.', 'error');
+  }
+});
+
+copyBtn.addEventListener('click', async () => {
+  try {
+    await navigator.clipboard.writeText(envelopeEl.value);
+    copyBtn.textContent = 'Copied!';
+    setTimeout(() => { copyBtn.textContent = 'Copy envelope'; }, 1500);
+  } catch {
+    envelopeEl.select();
+  }
+});
+
+noteEl.maxLength = MAX_NOTE_CHARS;
+noteEl.addEventListener('input', updateCounter);
+updateCounter();
+
+if (!window.isSecureContext || !window.crypto?.subtle) {
+  submitBtn.disabled = true;
+  setStatus('Encrypted notes need a secure (HTTPS) connection.', 'error');
+} else {
+  loadRecipientKeys();
+}
