new file mode 100644
index 0000000..77be52b
--- /dev/null
+++ b/js/note-crypto.js
@@ -0,0 +1,226 @@
+// Encrypted delivery notes: hybrid / post-quantum key establishment + AES-256-GCM.
+//
+// Envelope format (v1):
+//   1. Establish a fresh 32-byte shared secret with the shop's public key using one of:
+//        - "xwing"    : X-Wing hybrid KEM (ML-KEM-768 + X25519, SHA3-256 combiner)  [default]
+//        - "mlkem768" : ML-KEM-768 (FIPS 203), post-quantum only
+//        - "x25519"   : ephemeral-static X25519 key agreement (classical), DHKEM-style
+//   2. Derive an AES-256-GCM key with HKDF-SHA-256, domain-separated by suite and key id.
+//   3. Encrypt the length-padded note; the header (version, suite, key id, KEM ciphertext,
+//      order reference) is bound as additional authenticated data.
+//
+// Only the envelope ever leaves the browser. Plaintext and shared secrets stay in memory.
+
+import { xwing, ml_kem768, x25519 } from '../vendor/noble-pq.min.js';
+
+const VERSION = 1;
+const PROTOCOL_LABEL = 'DailyGrind/DeliveryNotes/v1';
+const PAD_BLOCK = 256;
+export const MAX_NOTE_CHARS = 1000;
+
+const te = new TextEncoder();
+const td = new TextDecoder('utf-8', { fatal: true });
+
+// ---------- encoding helpers ----------
+
+export function toB64u(bytes) {
+  let s = '';
+  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
+  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromB64u(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new Error('Invalid base64url data');
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (str.length % 4)) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+function concat(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let o = 0;
+  for (const p of parts) { out.set(p, o); o += p.length; }
+  return out;
+}
+
+// ---------- key establishment suites ----------
+
+function x25519Kem() {
+  // DHKEM-style wrapper so X25519 exposes the same encapsulate/decapsulate interface.
+  const bind = (dh, enc, pkR) => concat(te.encode('x25519-dhkem'), dh, enc, pkR);
+  const checkNonZero = (dh) => {
+    if (dh.every((b) => b === 0)) throw new Error('X25519 produced an all-zero shared secret');
+    return dh;
+  };
+  return {
+    keygen() {
+      const secretKey = x25519.utils.randomSecretKey();
+      return { secretKey, publicKey: x25519.getPublicKey(secretKey) };
+    },
+    encapsulate(pkR) {
+      const eSk = x25519.utils.randomSecretKey();
+      const enc = x25519.getPublicKey(eSk);
+      const dh = checkNonZero(x25519.getSharedSecret(eSk, pkR));
+      eSk.fill(0);
+      return { cipherText: enc, sharedSecret: bind(dh, enc, pkR) };
+    },
+    decapsulate(enc, skR) {
+      const dh = checkNonZero(x25519.getSharedSecret(skR, enc));
+      return bind(dh, enc, x25519.getPublicKey(skR));
+    },
+  };
+}
+
+export const SUITES = {
+  xwing: {
+    label: 'Hybrid post-quantum — X-Wing (ML-KEM-768 + X25519)',
+    short: 'X-Wing hybrid',
+    kem: xwing,
+    publicKeyLength: 1216,
+    cipherTextLength: 1120,
+  },
+  mlkem768: {
+    label: 'Post-quantum — ML-KEM-768 (FIPS 203)',
+    short: 'ML-KEM-768',
+    kem: ml_kem768,
+    publicKeyLength: 1184,
+    cipherTextLength: 1088,
+  },
+  x25519: {
+    label: 'Classical — X25519 key agreement',
+    short: 'X25519',
+    kem: x25519Kem(),
+    publicKeyLength: 32,
+    cipherTextLength: 32,
+  },
+};
+
+function getSuite(id) {
+  if (!Object.prototype.hasOwnProperty.call(SUITES, id)) throw new Error(`Unsupported suite: ${id}`);
+  return SUITES[id];
+}
+
+export function validatePublicKey(suiteId, publicKey) {
+  const suite = getSuite(suiteId);
+  if (!(publicKey instanceof Uint8Array) || publicKey.length !== suite.publicKeyLength) {
+    throw new Error(`Invalid ${suite.short} public key length`);
+  }
+  return publicKey;
+}
+
+// ---------- symmetric layer ----------
+
+async function deriveAeadKey(sharedSecret, suiteId, kid) {
+  const ikm = await crypto.subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  return crypto.subtle.deriveKey(
+    {
+      name: 'HKDF',
+      hash: 'SHA-256',
+      salt: te.encode(PROTOCOL_LABEL),
+      info: te.encode(`${PROTOCOL_LABEL}|aead-key|${suiteId}|${kid}`),
+    },
+    ikm,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    ['encrypt', 'decrypt'],
+  );
+}
+
+// Fixed, ordered serialisation of the header so both sides compute identical AAD.
+function headerAad(h) {
+  return te.encode(JSON.stringify([h.v, h.suite, h.kid, h.enc, h.orderRef]));
+}
+
+// ISO/IEC 7816-4 padding to a multiple of PAD_BLOCK so ciphertext length leaks less.
+function pad(bytes) {
+  const total = Math.ceil((bytes.length + 1) / PAD_BLOCK) * PAD_BLOCK;
+  const out = new Uint8Array(total);
+  out.set(bytes);
+  out[bytes.length] = 0x80;
+  return out;
+}
+
+function unpad(bytes) {
+  let i = bytes.length - 1;
+  while (i >= 0 && bytes[i] === 0) i--;
+  if (i < 0 || bytes[i] !== 0x80) throw new Error('Invalid padding');
+  return bytes.subarray(0, i);
+}
+
+// ---------- public API ----------
+
+/**
+ * Encrypt a delivery note to a recipient public key.
+ * @param {{suite: string, kid: string, publicKey: Uint8Array}} recipient
+ * @param {string} note
+ * @param {string} orderRef  bound as AAD (not secret)
+ */
+export async function encryptNote(recipient, note, orderRef = '') {
+  if (!window.isSecureContext || !crypto?.subtle) {
+    throw new Error('Encryption requires a secure (HTTPS) context with Web Crypto support.');
+  }
+  if (typeof note !== 'string' || note.trim() === '') throw new Error('Note is empty.');
+  if (note.length > MAX_NOTE_CHARS) throw new Error(`Note exceeds ${MAX_NOTE_CHARS} characters.`);
+
+  const suite = getSuite(recipient.suite);
+  validatePublicKey(recipient.suite, recipient.publicKey);
+
+  const { cipherText: kemCt, sharedSecret } = suite.kem.encapsulate(recipient.publicKey);
+  try {
+    const key = await deriveAeadKey(sharedSecret, recipient.suite, recipient.kid);
+    const header = {
+      v: VERSION,
+      suite: recipient.suite,
+      kid: String(recipient.kid),
+      enc: toB64u(kemCt),
+      orderRef: String(orderRef),
+    };
+    const iv = crypto.getRandomValues(new Uint8Array(12));
+    const plaintext = pad(te.encode(note));
+    const ct = new Uint8Array(
+      await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData: headerAad(header), tagLength: 128 }, key, plaintext),
+    );
+    plaintext.fill(0);
+    return { ...header, alg: 'A256GCM', iv: toB64u(iv), ct: toB64u(ct) };
+  } finally {
+    sharedSecret.fill(0);
+  }
+}
+
+/**
+ * Decrypt an envelope with the recipient secret key (shop side / demo verification).
+ */
+export async function decryptNote(envelope, secretKey) {
+  if (!envelope || envelope.v !== VERSION || envelope.alg !== 'A256GCM') {
+    throw new Error('Unsupported envelope version or algorithm');
+  }
+  const suite = getSuite(envelope.suite);
+  const kemCt = fromB64u(envelope.enc);
+  if (kemCt.length !== suite.cipherTextLength) throw new Error('Invalid encapsulation length');
+  const iv = fromB64u(envelope.iv);
+  if (iv.length !== 12) throw new Error('Invalid IV length');
+
+  const sharedSecret = suite.kem.decapsulate(kemCt, secretKey);
+  try {
+    const key = await deriveAeadKey(sharedSecret, envelope.suite, envelope.kid);
+    const pt = new Uint8Array(
+      await crypto.subtle.decrypt(
+        { name: 'AES-GCM', iv, additionalData: headerAad(envelope), tagLength: 128 },
+        key,
+        fromB64u(envelope.ct),
+      ),
+    );
+    return td.decode(unpad(pt));
+  } finally {
+    sharedSecret.fill(0);
+  }
+}
+
+/** Generate a recipient key pair (used only for the in-browser demo key). */
+export function generateRecipientKeyPair(suiteId) {
+  return getSuite(suiteId).kem.keygen();
+}
