+   header/nav styling is always applied before a page (or its view transition)
+   is first shown. */
+
+:root {
+  --primary: #4e342e;
+  --primary-dark: #3e2723;
+  --secondary: #d7ccc8;
+  --accent: #ffab40;
+  --text: #3e2723;
+  --light: #fafafa;
+  --surface: #ffffff;
+  --shadow: rgba(0, 0, 0, 0.1);
+  color-scheme: light;
+}
+
+:root[data-theme="dark"] {
+  --primary: #3e2723;
+  --primary-dark: #2a1b17;
+  --secondary: #2b2422;
+  --text: #efe7e3;
+  --light: #1a1412;
+  --surface: #261e1b;
+  --shadow: rgba(0, 0, 0, 0.45);
+  color-scheme: dark;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+body {
+  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+  line-height: 1.6;
+  color: var(--text);
+  background-color: var(--light);
+}
+
+/* ---------- Navigation ---------- */
+nav {
+  background: var(--primary);
+  color: white;
+  padding: 1rem 5%;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  position: sticky;
+  top: 0;
+  z-index: 1000;
+  view-transition-name: site-header;
+}
+
+.logo {
+  font-size: 1.5rem;
+  font-weight: bold;
+  letter-spacing: 1px;
+  color: white;
+  text-decoration: none;
+}
+
+nav ul {
+  display: flex;
+  list-style: none;
+}
+
+nav ul li {
+  margin-left: 20px;
+}
+
+nav a {
+  color: white;
+  text-decoration: none;
+  font-size: 0.9rem;
+  transition: color 0.3s;
+}
+
+nav a:hover,
+nav ul a[aria-current="page"] {
+  color: var(--accent);
+}
+
+.logout-link {
+  border: 1px solid var(--accent);
+  padding: 5px 12px;
+  border-radius: 4px;
+}
+
+/* ---------- Hero ---------- */
+.hero {
+  height: 60vh;
+  background: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
+    var(--hero-image, url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80'));
+  background-color: var(--primary-dark);
+  background-size: cover;
+  background-position: center;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  color: white;
+  text-align: center;
+  padding: 0 20px;
+  view-transition-name: hero;
+}
+
+.hero h1 {
+  font-size: 3rem;
+  margin-bottom: 1rem;
+  view-transition-name: hero-title;
+  width: fit-content;
+}
+
+/* Shorter hero for secondary pages */
+.hero.hero--compact {
+  height: 32vh;
+}
+
+.hero.hero--compact h1 {
+  font-size: 2.4rem;
+  margin-bottom: 0.5rem;
+}
+
+/* ---------- Content ---------- */
+.container {
+  max-width: 1100px;
+  margin: 40px auto;
+  padding: 0 20px;
+  view-transition-name: page-content;
+}
+
+.section-title {
+  text-align: center;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+  gap: 20px;
+  margin-top: 20px;
+}
+
+.card {
+  background: var(--surface);
+  padding: 20px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px var(--shadow);
+  text-align: center;
+}
+
+.card h3 {
+  margin-bottom: 10px;
+  color: var(--text);
+}
+
+.card .price {
+  font-weight: bold;
+  color: var(--accent);
+  margin-top: 8px;
+}
+
+.btn {
+  display: inline-block;
+  background: var(--primary);
+  color: white;
+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  margin-top: 15px;
+  transition: background 0.3s;
+}
+
+.btn:hover {
+  background: var(--primary-dark);
+}
+
+.menu-section + .menu-section {
+  margin-top: 48px;
+}
+
+/* ---------- Footer ---------- */
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+  view-transition-name: site-footer;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+/* =========================================================
+   Cross-document page transitions (View Transitions API, L2)
+   Both the old and new page must opt in for the transition to run.
+   Browsers without support simply navigate normally.
+   ========================================================= */
+@view-transition {
+  navigation: auto;
+}
+
+/* Header stays visually anchored: no fade, just morph if size changes. */
+::view-transition-old(site-header),
+::view-transition-new(site-header) {
+  animation: none;
+  mix-blend-mode: normal;
+}
+
+/* Hero morphs between the full-height (home) and compact (subpage) versions. */
+::view-transition-group(hero),
+::view-transition-group(hero-title) {
+  animation-duration: 450ms;
+  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
+}
+
+::view-transition-old(hero),
+::view-transition-new(hero) {
+  height: 100%;
+  object-fit: cover;
+  overflow: clip;
+}
+
+/* Main content slides + fades. */
+@keyframes dg-fade-out {
+  to { opacity: 0; }
+}
+
+@keyframes dg-fade-in {
+  from { opacity: 0; }
+}
+
+@keyframes dg-slide-out {
+  to { transform: translateY(-16px); }
+}
+
+@keyframes dg-slide-in {
+  from { transform: translateY(24px); }
+}
+
+::view-transition-old(page-content) {
+  animation: 180ms cubic-bezier(0.4, 0, 1, 1) both dg-fade-out,
+    300ms cubic-bezier(0.4, 0, 0.2, 1) both dg-slide-out;
+}
+
+::view-transition-new(page-content) {
+  animation: 320ms cubic-bezier(0, 0, 0.2, 1) 90ms both dg-fade-in,
+    320ms cubic-bezier(0.4, 0, 0.2, 1) 90ms both dg-slide-in;
+}
+
+/* Footer may still be streaming in on the new page; just crossfade it. */
+::view-transition-old(site-footer) {
+  animation: 150ms ease-out both dg-fade-out;
+}
+
+::view-transition-new(site-footer) {
+  animation: 250ms ease-in 150ms both dg-fade-in;
+}
+
+::view-transition-group(root) {
+  animation-duration: 300ms;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  ::view-transition-group(*),
+  ::view-transition-old(*),
+  ::view-transition-new(*) {
+    animation: none !important;
+  }
+}
+
+@media (max-width: 640px) {
+  nav {
+    flex-direction: column;
+    gap: 8px;
+  }
+
+  nav ul {
+    flex-wrap: wrap;
+    justify-content: center;
+  }
+
+  nav ul li {
+    margin: 0 8px;
+  }
+
+  .hero h1 {
+    font-size: 2.2rem;
+  }
+}

