new file mode 100644
index 0000000..990863b
--- /dev/null
+++ b/smallpt-worker.js
@@ -0,0 +1,31 @@
+// Module worker: runs one smallpt Wasm instance that renders a band of rows
+// progressively and posts each accumulated pass back to the page.
+import createSmallpt from './wasm/smallpt.js';
+
+const modulePromise = createSmallpt();
+let currentJob = 0;
+
+self.onmessage = async ({ data }) => {
+  const job = ++currentJob;
+  const { runId, width, height, y0, y1, passes, seed, colors } = data;
+  const m = await modulePromise;
+  if (job !== currentJob) return;
+
+  if (!m._sp_init(width, height, y0, y1)) {
+    self.postMessage({ runId, error: 'Could not allocate render buffers.' });
+    return;
+  }
+  for (const [index, [r, g, b]] of colors) m._sp_set_color(index, r, g, b);
+  m._sp_reset(seed >>> 0);
+
+  const byteLength = width * (y1 - y0) * 4;
+  for (let pass = 1; pass <= passes; pass++) {
+    const ptr = m._sp_render_pass();
+    // Read HEAPU8 fresh: memory growth may have replaced the buffer.
+    const pixels = m.HEAPU8.slice(ptr, ptr + byteLength);
+    self.postMessage({ runId, y0, pass, pixels }, [pixels.buffer]);
+    // Yield so a newer job's message can preempt this one.
+    await new Promise((resolve) => setTimeout(resolve, 0));
+    if (job !== currentJob) return;
+  }
+};
