+#!/usr/bin/env bash
+# Builds smallpt.cpp into an ES6 Wasm module for use in a Web Worker.
+# Requires Emscripten (em++) on PATH.
+set -euo pipefail
+cd "$(dirname "$0")"
+mkdir -p ../wasm
+em++ -c smallpt.cpp -o smallpt.o -O3 -flto -Wall -Werror
+em++ smallpt.o -o ../wasm/smallpt.js \
+  -O3 -flto --closure=1 \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_sp_init,_sp_num_spheres,_sp_set_color,_sp_reset,_sp_render_pass \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+rm -f smallpt.o
