+// ---- WebAssembly API -------------------------------------------------------
+// The image is W x H; this instance renders the horizontal band of output rows
+// [Y0, Y1) (row 0 = top), so several workers can split one frame.
+static int W = 0, H = 0, Y0 = 0, Y1 = 0, passes = 0;
+static unsigned seed = 0;
+static Vec *accum = nullptr;     // running radiance sum, 4 subpixels per pixel
+static uint8_t *rgba = nullptr;  // tone-mapped RGBA8 band, top row first
+
+static size_t bandPixels() { return (size_t)W * (Y1 - Y0); }
+
+extern "C" {
+
+// (Re)allocate buffers for rows [y0, y1) of a w*h image. Returns 1 on success.
+EMSCRIPTEN_KEEPALIVE int sp_init(int w, int h, int y0, int y1) {
+  if (w <= 0 || h <= 0 || y0 < 0 || y1 > h || y0 >= y1) return 0;
+  size_t n = (size_t)w * (y1 - y0);
+  if (n != bandPixels()) {
+    free(accum);
+    free(rgba);
+    accum = (Vec *)malloc(sizeof(Vec) * n * 4);
+    rgba = (uint8_t *)malloc(n * 4);
+    if (!accum || !rgba) { W = H = Y0 = Y1 = 0; return 0; }
+  }
+  W = w; H = h; Y0 = y0; Y1 = y1;
+  passes = 0;
+  memset((void *)accum, 0, sizeof(Vec) * n * 4);
+  return 1;
+}
+
+EMSCRIPTEN_KEEPALIVE int sp_num_spheres() { return numSpheres; }
+
+EMSCRIPTEN_KEEPALIVE void sp_set_color(int i, double r, double g, double b) {
+  if (i >= 0 && i < numSpheres) spheres[i].c = Vec(r, g, b);
+}
+
+// Clears the accumulation buffer; seed decorrelates noise between runs.
+EMSCRIPTEN_KEEPALIVE void sp_reset(unsigned s) {
+  seed = s;
+  passes = 0;
+  if (accum) memset((void *)accum, 0, sizeof(Vec) * bandPixels() * 4);
+}
+
+// Renders one pass (one sample per 2x2 subpixel), accumulates it, and returns
+// a pointer to the band's W*(Y1-Y0)*4 RGBA8 pixels.
+EMSCRIPTEN_KEEPALIVE uint8_t *sp_render_pass() {
+  if (!accum) return nullptr;
+  const int w = W, h = H;
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm());  // cam pos, dir
+  Vec cx = Vec(w * .5135 / h), cy = (cx % cam.d).norm() * .5135;
+  for (int row = Y0; row < Y1; row++) {
+    const int y = h - row - 1;  // smallpt's y runs bottom-up
+    unsigned short Xi[3] = {(unsigned short)(passes * 7919 + seed), (unsigned short)(seed >> 16),
+                            (unsigned short)(y * y * y)};
+    for (unsigned short x = 0; x < w; x++) {
+      const size_t i = (size_t)(row - Y0) * w + x;
+      for (int sy = 0; sy < 2; sy++)      // 2x2 subpixel rows
+        for (int sx = 0; sx < 2; sx++) {  // 2x2 subpixel cols
+          double r1 = 2 * erand48(Xi), dx = r1 < 1 ? sqrt(r1) - 1 : 1 - sqrt(2 - r1);
+          double r2 = 2 * erand48(Xi), dy = r2 < 1 ? sqrt(r2) - 1 : 1 - sqrt(2 - r2);
+          Vec d = cx * (((sx + .5 + dx) / 2 + x) / w - .5) + cy * (((sy + .5 + dy) / 2 + y) / h - .5) + cam.d;
+          Vec &a = accum[i * 4 + sy * 2 + sx];
+          a = a + radiance(Ray(cam.o + d * 140, d.norm()), 0, Xi);
+        }
+    }
+  }
+  passes++;
+  const double inv = 1.0 / passes;
+  const size_t n = bandPixels();
+  for (size_t i = 0; i < n; i++) {
+    Vec c;
+    for (int s = 0; s < 4; s++) {  // clamp after averaging, as smallpt does
+      Vec r = accum[i * 4 + s] * inv;
+      c = c + Vec(clamp(r.x), clamp(r.y), clamp(r.z)) * .25;
+    }
+    rgba[i * 4 + 0] = (uint8_t)toInt(c.x);
+    rgba[i * 4 + 1] = (uint8_t)toInt(c.y);
+    rgba[i * 4 + 2] = (uint8_t)toInt(c.z);
+    rgba[i * 4 + 3] = 255;
+  }
+  return rgba;
+}
+
+}  // extern "C"
