+        { name: 'Ceiling', color: [.75, .75, .75], kind: 'wall' },
+        { name: 'Mirror ball', color: [.999, .999, .999], kind: 'ball' },
+        { name: 'Glass ball', color: [.999, .999, .999], kind: 'ball' },
+        { name: 'Light', color: [0, 0, 0], kind: 'hidden' },        // emissive only
+      ];
+
+      const canvas = document.getElementById('smallpt-canvas');
+      const ctx = canvas.getContext('2d');
+      const status = document.getElementById('smallpt-status');
+      const swatches = document.getElementById('smallpt-swatches');
+      const randomizeBtn = document.getElementById('smallpt-randomize');
+      const resetBtn = document.getElementById('smallpt-reset');
+
+      if (typeof WebAssembly !== 'object' || typeof Worker !== 'function') {
+        status.textContent = 'Sorry, your browser does not support WebAssembly workers.';
+        randomizeBtn.disabled = resetBtn.disabled = true;
+        return;
+      }
+
+      const worker = new Worker('smallpt/worker.js');
+      let renderId = 0;
+
+      function hslToRgb(h, s, l) {
+        const k = n => (n + h * 12) % 12;
+        const a = s * Math.min(l, 1 - l);
+        const f = n => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
+        return [f(0), f(8), f(4)];
+      }
+      const rand = (lo, hi) => lo + Math.random() * (hi - lo);
+
+      function randomColors() {
+        return SPHERES.map(s => {
+          if (s.kind === 'wall') return hslToRgb(Math.random(), rand(0.35, 0.9), rand(0.3, 0.6)).map(v => Math.min(v, 0.95));
+          // Keep balls bright so they still read as mirror/glass, just tinted.
+          if (s.kind === 'ball') return hslToRgb(Math.random(), rand(0.3, 0.9), rand(0.6, 0.8)).map(v => Math.min(v, 0.999));
+          return null; // leave hidden wall & light untouched
+        });
+      }
+
+      function showSwatches(colors) {
+        swatches.innerHTML = '';
+        SPHERES.forEach((s, i) => {
+          if (s.kind === 'hidden') return;
+          const c = (colors && colors[i]) || s.color;
+          const el = document.createElement('span');
+          el.className = 'swatch';
+          const dot = document.createElement('i');
+          dot.style.background = `rgb(${c.map(v => Math.round(Math.pow(v, 1 / 2.2) * 255)).join(',')})`;
+          el.append(dot, s.name);
+          swatches.append(el);
+        });
+      }
+
+      function render(colors) {
+        renderId++;
+        showSwatches(colors);
+        status.textContent = 'Tracing first samples…';
+        worker.postMessage({
+          type: 'render', id: renderId, width: WIDTH, height: HEIGHT, maxSpp: MAX_SPP,
+          seed: (Math.random() * 2 ** 32) >>> 0, colors,
+        });
+      }
+
+      worker.onmessage = ({ data }) => {
+        if (data.type === 'frame') {
+          if (data.id !== renderId) return; // stale frame from a cancelled render
+          ctx.putImageData(new ImageData(new Uint8ClampedArray(data.pixels), data.width, data.height), 0, 0);
+          const secs = (data.ms / 1000).toFixed(1);
+          status.textContent = data.done
+            ? `Done: ${data.spp} samples/pixel in ${secs}s`
+            : `Rendering… ${data.spp} / ${MAX_SPP} samples/pixel (${secs}s)`;
+        } else if (data.type === 'error') {
+          status.textContent = 'Render failed: ' + data.message;
+        }
+      };
+      worker.onerror = e => { status.textContent = 'Render failed: ' + (e.message || 'worker error'); };
+
+      randomizeBtn.addEventListener('click', () => render(randomColors()));
+      resetBtn.addEventListener('click', () => render(null));
+
+      render(null); // classic smallpt scene on load
+    })();
+  </script>
+
 </body>

 </html>
