+// Compiles src/smallpt.cpp -> smallpt/smallpt.wasm using @yowasp/clang
+// (Clang/LLD + wasi-libc, itself compiled to WebAssembly, so no native
+// Emscripten/LLVM install is needed). Run: npm run build:wasm
+import { readFile, writeFile, mkdir } from 'node:fs/promises';
+import { runClang } from '@yowasp/clang';
+
+const src = await readFile(new URL('../src/smallpt.cpp', import.meta.url), 'utf8');
+const args = [
+  'clang++', '--target=wasm32-wasip1', '-O3', '-ffast-math',
+  '-fno-exceptions', '-fno-rtti',
+  '-mexec-model=reactor',          // library-style module: exports + _initialize
+  '-Wl,--strip-all', '-Wl,--gc-sections',
+  '-Wl,-z,stack-size=1048576',     // radiance() recursion for glass is deep-ish
+  'smallpt.cpp', '-o', 'smallpt.wasm',
+];
+const out = await runClang(args, { 'smallpt.cpp': src });
+const wasm = out['smallpt.wasm'];
+if (!wasm) throw new Error('compilation produced no output');
+await mkdir(new URL('../smallpt/', import.meta.url), { recursive: true });
+await writeFile(new URL('../smallpt/smallpt.wasm', import.meta.url), wasm);
+
+const mod = await WebAssembly.compile(wasm);
+console.log(`smallpt/smallpt.wasm: ${wasm.length} bytes`);
+console.log('imports:', WebAssembly.Module.imports(mod).map(i => `${i.module}.${i.name}`).join(', ') || '(none)');
+console.log('exports:', WebAssembly.Module.exports(mod).map(e => e.name).join(', '));
