--- /dev/null
+++ b/smallpt/worker.js
@@ -0,0 +1,68 @@
+// Runs the smallpt WebAssembly module off the main thread and streams
+// progressively refined frames back to the page.
+//
+// in:  { type: 'render', width, height, maxSpp, seed, colors }  colors: [[r,g,b]|null, ...] or null (= classic scene)
+// out: { type: 'ready', sphereCount }
+//      { type: 'frame', id, width, height, spp, ms, pixels (ArrayBuffer RGBA), done }
+//      { type: 'error', message }
+
+const ROWS_PER_CHUNK = 8;
+
+let exportsP = null;
+let currentJob = 0;
+
+async function load() {
+  const url = new URL('smallpt.wasm', self.location.href);
+  const res = await fetch(url);
+  if (!res.ok) throw new Error(`failed to fetch smallpt.wasm (${res.status})`);
+  // Use arrayBuffer() rather than instantiateStreaming so we don't depend on
+  // the static server sending the application/wasm MIME type.
+  const { instance } = await WebAssembly.instantiate(await res.arrayBuffer(), {});
+  const e = instance.exports;
+  e._initialize();
+  postMessage({ type: 'ready', sphereCount: e.sphere_count() });
+  return e;
+}
+
+// Yield to the event loop so a newer 'render' message can cancel this job.
+// (MessageChannel avoids the ~4ms clamp that nested setTimeout(0) gets.)
+const yieldChannel = new MessageChannel();
+const yieldQueue = [];
+yieldChannel.port1.onmessage = () => yieldQueue.shift()();
+const yieldToEvents = () => new Promise(r => { yieldQueue.push(r); yieldChannel.port2.postMessage(0); });
+
+async function render(job, msg) {
+  const e = await exportsP;
+  const { width: W, height: H, maxSpp, seed, colors } = msg;
+
+  e.reset_sphere_colors();
+  if (colors) colors.forEach((c, i) => { if (c) e.set_sphere_color(i, c[0], c[1], c[2]); });
+
+  const ptr = e.init(W, H, seed >>> 0);
+  if (!ptr) throw new Error('out of memory');
+  const t0 = performance.now();
+  let spp = 0;
+  while (spp < maxSpp) {
+    for (let y = 0; y < H; y += ROWS_PER_CHUNK) {
+      e.render_rows(y, Math.min(H, y + ROWS_PER_CHUNK));
+      await yieldToEvents();
+      if (job !== currentJob) return; // superseded
+    }
+    spp = e.finish_pass();
+    // Re-create the view each time: memory.buffer is replaced if it grows.
+    const pixels = new Uint8ClampedArray(e.memory.buffer, ptr, W * H * 4).slice().buffer;
+    postMessage({
+      type: 'frame', id: msg.id, width: W, height: H, spp,
+      ms: performance.now() - t0, pixels, done: spp >= maxSpp,
+    }, [pixels]);
+  }
+}
+
+self.onmessage = ({ data }) => {
+  if (data.type !== 'render') return;
+  const job = ++currentJob;
+  render(job, data).catch(err => postMessage({ type: 'error', message: String(err && err.message || err) }));
+};
+
+exportsP = load();
+exportsP.catch(err => postMessage({ type: 'error', message: String(err && err.message || err) }));
