+++ b/src/smallpt.cpp
@@ -0,0 +1,202 @@
+// smallpt, a Path Tracer by Kevin Beason, 2008
+// http://www.kevinbeason.com/smallpt/  (MIT license, see LICENSE-smallpt.txt)
+//
+// WebAssembly port. The geometry, materials and radiance() estimator below are
+// smallpt's originals, unchanged. Only the program driver differs:
+//   * main()/PPM file output were replaced by exported functions that render
+//     the image progressively (one 2x2-subpixel sample per call) into an RGBA
+//     buffer that JavaScript reads straight out of linear memory.
+//   * sphere colors can be overwritten from JavaScript (set_sphere_color).
+//   * erand48() is provided locally so the build doesn't depend on libc's
+//     availability of the SVID rand48 family.
+//   * the OpenMP pragma was dropped (wasm here is single-threaded; the page
+//     runs it inside a Web Worker instead so the UI stays responsive).
+#include <math.h>
+#include <stdlib.h>
+
+#define EXPORT(name) extern "C" __attribute__((export_name(#name)))
+
+// --- erand48: identical algorithm to POSIX (48-bit LCG, a=0x5DEECE66D, c=0xB)
+static double erand48_local(unsigned short xsubi[3]) {
+  unsigned long long x = ((unsigned long long)xsubi[2] << 32) |
+                         ((unsigned long long)xsubi[1] << 16) | xsubi[0];
+  x = (x * 0x5DEECE66DULL + 0xBULL) & 0xFFFFFFFFFFFFULL;
+  xsubi[0] = (unsigned short)(x);
+  xsubi[1] = (unsigned short)(x >> 16);
+  xsubi[2] = (unsigned short)(x >> 32);
+  return (double)x / 281474976710656.0; // 2^48
+}
+#define erand48 erand48_local
+
+struct Vec {        // Usage: time ./smallpt 5000 && xv image.ppm
+  double x, y, z;                  // position, also color (r,g,b)
+  Vec(double x_=0, double y_=0, double z_=0){ x=x_; y=y_; z=z_; }
+  Vec operator+(const Vec &b) const { return Vec(x+b.x,y+b.y,z+b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x-b.x,y-b.y,z-b.z); }
+  Vec operator*(double b) const { return Vec(x*b,y*b,z*b); }
+  Vec mult(const Vec &b) const { return Vec(x*b.x,y*b.y,z*b.z); }
+  Vec& norm(){ return *this = *this * (1/sqrt(x*x+y*y+z*z)); }
+  double dot(const Vec &b) const { return x*b.x+y*b.y+z*b.z; } // cross:
+  Vec operator%(Vec&b){return Vec(y*b.z-z*b.y,z*b.x-x*b.z,x*b.y-y*b.x);}
+};
+struct Ray { Vec o, d; Ray(Vec o_, Vec d_) : o(o_), d(d_) {} };
+enum Refl_t { DIFF, SPEC, REFR };  // material types, used in radiance()
+struct Sphere {
+  double rad;       // radius
+  Vec p, e, c;      // position, emission, color
+  Refl_t refl;      // reflection type (DIFFuse, SPECular, REFRactive)
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_):
+    rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const { // returns distance, 0 if nohit
+    Vec op = p-r.o; // Solve t^2*d.d + 2*t*(o-p).d + (o-p).(o-p)-R^2 = 0
+    double t, eps=1e-4, b=op.dot(r.d), det=b*b-op.dot(op)+rad*rad;
+    if (det<0) return 0; else det=sqrt(det);
+    return (t=b-det)>eps ? t : ((t=b+det)>eps ? t : 0);
+  }
+};
+Sphere spheres[] = {//Scene: radius, position, emission, color, material
+  Sphere(1e5, Vec( 1e5+1,40.8,81.6), Vec(),Vec(.75,.25,.25),DIFF),//Left
+  Sphere(1e5, Vec(-1e5+99,40.8,81.6),Vec(),Vec(.25,.25,.75),DIFF),//Rght
+  Sphere(1e5, Vec(50,40.8, 1e5),     Vec(),Vec(.75,.75,.75),DIFF),//Back
+  Sphere(1e5, Vec(50,40.8,-1e5+170), Vec(),Vec(),           DIFF),//Frnt
+  Sphere(1e5, Vec(50, 1e5, 81.6),    Vec(),Vec(.75,.75,.75),DIFF),//Botm
+  Sphere(1e5, Vec(50,-1e5+81.6,81.6),Vec(),Vec(.75,.75,.75),DIFF),//Top
+  Sphere(16.5,Vec(27,16.5,47),       Vec(),Vec(1,1,1)*.999, SPEC),//Mirr
+  Sphere(16.5,Vec(73,16.5,78),       Vec(),Vec(1,1,1)*.999, REFR),//Glas
+  Sphere(600, Vec(50,681.6-.27,81.6),Vec(12,12,12),  Vec(), DIFF) //Lite
+};
+static const int NUM_SPHERES = sizeof(spheres)/sizeof(Sphere);
+static Vec default_colors[NUM_SPHERES];
+static bool defaults_saved = false;
+
+inline double clamp(double x){ return x<0 ? 0 : x>1 ? 1 : x; }
+inline int toInt(double x){ return int(pow(clamp(x),1/2.2)*255+.5); }
+inline bool intersect(const Ray &r, double &t, int &id){
+  double n=sizeof(spheres)/sizeof(Sphere), d, inf=t=1e20;
+  for(int i=int(n);i--;) if((d=spheres[i].intersect(r))&&d<t){t=d;id=i;}
+  return t<inf;
+}
+Vec radiance(const Ray &r, int depth, unsigned short *Xi){
+  double t;                               // distance to intersection
+  int id=0;                               // id of intersected object
+  if (!intersect(r, t, id)) return Vec(); // if miss, return black
+  const Sphere &obj = spheres[id];        // the hit object
+  Vec x=r.o+r.d*t, n=(x-obj.p).norm(), nl=n.dot(r.d)<0?n:n*-1, f=obj.c;
+  double p = f.x>f.y && f.x>f.z ? f.x : f.y>f.z ? f.y : f.z; // max refl
+  if (++depth>5) { if (erand48(Xi)<p) f=f*(1/p); else return obj.e; } //R.R.
+  if (obj.refl == DIFF){                  // Ideal DIFFUSE reflection
+    double r1=2*M_PI*erand48(Xi), r2=erand48(Xi), r2s=sqrt(r2);
+    Vec w=nl, u=((fabs(w.x)>.1?Vec(0,1):Vec(1))%w).norm(), v=w%u;
+    Vec d = (u*cos(r1)*r2s + v*sin(r1)*r2s + w*sqrt(1-r2)).norm();
+    return obj.e + f.mult(radiance(Ray(x,d),depth,Xi));
+  } else if (obj.refl == SPEC)            // Ideal SPECULAR reflection
+    return obj.e + f.mult(radiance(Ray(x,r.d-n*2*n.dot(r.d)),depth,Xi));
+  Ray reflRay(x, r.d-n*2*n.dot(r.d));     // Ideal dielectric REFRACTION
+  bool into = n.dot(nl)>0;                // Ray from outside going in?
+  double nc=1, nt=1.5, nnt=into?nc/nt:nt/nc, ddn=r.d.dot(nl), cos2t;
+  if ((cos2t=1-nnt*nnt*(1-ddn*ddn))<0)    // Total internal reflection
+    return obj.e + f.mult(radiance(reflRay,depth,Xi));
+  Vec tdir = (r.d*nnt - n*((into?1:-1)*(ddn*nnt+sqrt(cos2t)))).norm();
+  double a=nt-nc, b=nt+nc, R0=a*a/(b*b), c = 1-(into?-ddn:tdir.dot(n));
+  double Re=R0+(1-R0)*c*c*c*c*c,Tr=1-Re,P=.25+.5*Re,RP=Re/P,TP=Tr/(1-P);
+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+// ---------------------------------------------------------------------------
+// WebAssembly driver (replaces smallpt's main()).
+//
+// The original main() loops over rows, for each pixel takes `samps` samples in
+// each of 2x2 subpixels, clamps each subpixel and averages them into c[i].
+// Here a "pass" is one sample per subpixel (4 spp) over the whole image; the
+// per-subpixel radiance is accumulated across passes so that after N passes
+// the result equals the original program run with `samps = N`.
+// ---------------------------------------------------------------------------
+static int W = 0, H = 0, passes = 0;
+static unsigned seed_hi = 0;
+static Vec *accum = 0;            // W*H*4 subpixel radiance sums
+static unsigned char *rgba = 0;   // W*H*4 bytes, top row first
+static Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+static Vec cx, cy;
+
+static void save_defaults() {
+  if (defaults_saved) return;
+  for (int i = 0; i < NUM_SPHERES; i++) default_colors[i] = spheres[i].c;
+  defaults_saved = true;
+}
+
+EXPORT(sphere_count) int sphere_count() { return NUM_SPHERES; }
+
+EXPORT(set_sphere_color) void set_sphere_color(int i, double r, double g, double b) {
+  save_defaults();
+  if (i >= 0 && i < NUM_SPHERES) spheres[i].c = Vec(r, g, b);
+}
+
+EXPORT(reset_sphere_colors) void reset_sphere_colors() {
+  save_defaults();
+  for (int i = 0; i < NUM_SPHERES; i++) spheres[i].c = default_colors[i];
+}
+
+// Allocates buffers for a w*h image and clears accumulated samples.
+// Returns a pointer (offset into linear memory) to the RGBA output buffer.
+EXPORT(init) unsigned char *init(int w, int h, unsigned seed) {
+  save_defaults();
+  if (w != W || h != H) {
+    free(accum); free(rgba);
+    W = w; H = h;
+    accum = (Vec *)malloc(sizeof(Vec) * W * H * 4);
+    rgba = (unsigned char *)malloc((size_t)W * H * 4);
+    if (!accum || !rgba) { W = H = 0; return 0; }
+  }
+  for (int i = 0; i < W * H * 4; i++) accum[i] = Vec();
+  for (int i = 0; i < W * H * 4; i++) rgba[i] = (i & 3) == 3 ? 255 : 0;
+  cx = Vec(W*.5135/H); cy = (cx%cam.d).norm()*.5135;
+  passes = 0;
+  seed_hi = seed;
+  return rgba;
+}
+
+// Traces one sample per subpixel for rows [y0, y1) (smallpt's y: 0 = bottom).
+// Call with increasing row ranges covering 0..H, then finish_pass().
+EXPORT(render_rows) void render_rows(int y0, int y1) {
+  if (!accum) return;
+  for (int y = y0; y < y1 && y < H; y++) {
+    // Original seeds Xi = {0,0,y*y*y}; we mix in the pass number and a
+    // user seed so successive passes / runs use different random streams.
+    unsigned short Xi[3] = {(unsigned short)(passes * 7919u + seed_hi),
+                            (unsigned short)(seed_hi >> 16),
+                            (unsigned short)(y*y*y)};
+    for (int x = 0; x < W; x++)
+      for (int sy = 0; sy < 2; sy++)
+        for (int sx = 0; sx < 2; sx++) {
+          double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+          Vec d = cx*(((sx+.5 + dx)/2 + x)/W - .5) +
+                  cy*(((sy+.5 + dy)/2 + y)/H - .5) + cam.d;
+          Vec &a = accum[((y*W) + x)*4 + sy*2 + sx];
+          a = a + radiance(Ray(cam.o+d*140,d.norm()),0,Xi);
+        } // Camera rays are pushed ^^^^^ forward to start in interior
+  }
+}
+
+// Completes a pass and refreshes the RGBA buffer. Returns total spp so far.
+EXPORT(finish_pass) int finish_pass() {
+  if (!accum) return 0;
+  passes++;
+  double inv = 1.0 / passes;
+  for (int y = 0; y < H; y++)
+    for (int x = 0; x < W; x++) {
+      Vec c;
+      for (int s = 0; s < 4; s++) {
+        Vec r = accum[((y*W) + x)*4 + s] * inv;
+        c = c + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+      }
+      unsigned char *px = rgba + (((H-y-1)*W) + x)*4; // flip: row 0 = top
+      px[0] = (unsigned char)toInt(c.x);
+      px[1] = (unsigned char)toInt(c.y);
+      px[2] = (unsigned char)toInt(c.z);
+      px[3] = 255;
+    }
+  return passes * 4;
+}

