diff --git a/scripts/build-smallpt.sh b/scripts/build-smallpt.sh
new file mode 100755
index 0000000..8869ab4
--- /dev/null
+++ b/scripts/build-smallpt.sh
@@ -0,0 +1,23 @@
+#!/usr/bin/env bash
+# Compiles src/wasm/smallpt/smallpt.cpp to an ES6 WebAssembly module.
+# Requires Emscripten (em++) on PATH, e.g. `source /path/to/emsdk_env.sh`.
+# The generated smallpt.js / smallpt.wasm are committed, so `pnpm build`
+# does not need Emscripten installed.
+set -euo pipefail
+DIR="$(cd "$(dirname "$0")/../src/wasm/smallpt" && pwd)"
+OBJ="$(mktemp -d)"
+trap 'rm -rf "$OBJ"' EXIT
+
+em++ -c "$DIR/smallpt.cpp" -o "$OBJ/smallpt.o" -O3 -flto -Wall -Werror
+
+em++ "$OBJ/smallpt.o" -o "$DIR/smallpt.js" \
+  -O3 -flto --closure=1 \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_smallpt_init,_smallpt_reset,_smallpt_set_color,_smallpt_sphere_count,_smallpt_pass,_smallpt_image \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+
+echo "Built $DIR/smallpt.js and $DIR/smallpt.wasm"
diff --git a/src/components/SmallptRender.astro b/src/components/SmallptRender.astro
new file mode 100644
index 0000000..cf04f54
--- /dev/null
+++ b/src/components/SmallptRender.astro
@@ -0,0 +1,193 @@
+---
+// Client-side path tracing: Kevin Beason's smallpt compiled to WebAssembly
+// (src/wasm/smallpt) and run in a Web Worker, drawn progressively to a canvas.
+const WIDTH = 320;
+const HEIGHT = 240;
+const PASSES = 50; // 4 samples per pixel per pass -> 200 spp
+---
+
+<section class="p-4 md:p-6" data-smallpt data-width={WIDTH} data-height={HEIGHT} data-passes={PASSES}>
+  <h2 class="text-3xl font-bold border-b-2 border-gray-900 pb-2 mb-6 lg:mb-8">Lab: Path Tracing in Your Browser</h2>
+
+  <div class="grid md:grid-cols-[minmax(0,3fr)_minmax(0,2fr)] gap-6 items-start">
+    <figure class="m-0">
+      <canvas
+        width={WIDTH}
+        height={HEIGHT}
+        role="img"
+        aria-label="Path-traced Cornell box with a mirror sphere and a glass sphere"
+        class="block w-full h-auto aspect-[4/3] bg-gray-900"
+        data-smallpt-canvas></canvas>
+      <progress class="block w-full h-1.5 mt-2 accent-amber-400" max={PASSES} value="0" data-smallpt-progress
+      ></progress>
+      <figcaption class="mt-2 text-sm text-gray-600" data-smallpt-status>Waiting to render…</figcaption>
+    </figure>
+
+    <div class="space-y-4">
+      <p class="text-gray-800">
+        This image is being rendered right now, on your device. It comes from
+        <a class="underline hover:text-amber-500" href="http://www.kevinbeason.com/smallpt/" rel="noopener"
+          >smallpt</a
+        >, Kevin Beason's 99-line C++ global illumination renderer, compiled to WebAssembly and running in a
+        background worker. Each pass adds four more light paths per pixel, so the noise clears up as you watch.
+      </p>
+
+      <button
+        type="button"
+        class="inline-flex items-center gap-2 rounded bg-gray-900 px-4 py-2 font-semibold text-white hover:bg-amber-500 hover:text-gray-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-500 disabled:opacity-50"
+        data-smallpt-button
+        disabled>
+        Re-render with random colors
+      </button>
+
+      <ul class="grid grid-cols-2 gap-x-4 gap-y-1 text-sm text-gray-700" aria-label="Sphere colors" data-smallpt-swatches>
+      </ul>
+    </div>
+  </div>
+</section>
+
+<script>
+  import type { RGB, RenderRequest, WorkerMessage } from '../wasm/smallpt/protocol';
+
+  // Sphere indices in smallpt.cpp. The front wall (3, behind the camera) and
+  // the light (8) keep their original values.
+  const SPHERES: { index: number; label: string; kind: 'diffuse' | 'tint' }[] = [
+    { index: 0, label: 'Left wall', kind: 'diffuse' },
+    { index: 1, label: 'Right wall', kind: 'diffuse' },
+    { index: 2, label: 'Back wall', kind: 'diffuse' },
+    { index: 4, label: 'Floor', kind: 'diffuse' },
+    { index: 5, label: 'Ceiling', kind: 'diffuse' },
+    { index: 6, label: 'Mirror ball', kind: 'tint' },
+    { index: 7, label: 'Glass ball', kind: 'tint' },
+  ];
+
+  // smallpt's original scene colors.
+  const DEFAULT_COLORS: Record<number, RGB> = {
+    0: [0.75, 0.25, 0.25],
+    1: [0.25, 0.25, 0.75],
+    2: [0.75, 0.75, 0.75],
+    4: [0.75, 0.75, 0.75],
+    5: [0.75, 0.75, 0.75],
+    6: [0.999, 0.999, 0.999],
+    7: [0.999, 0.999, 0.999],
+  };
+
+  function hslToRgb(h: number, s: number, l: number): RGB {
+    const f = (n: number) => {
+      const k = (n + h * 12) % 12;
+      return l - s * Math.min(l, 1 - l) * Math.max(-1, Math.min(k - 3, 9 - k, 1));
+    };
+    return [f(0), f(8), f(4)];
+  }
+
+  function randomColor(kind: 'diffuse' | 'tint'): RGB {
+    const h = Math.random();
+    // Diffuse surfaces stay below ~0.85 albedo so the box doesn't blow out;
+    // mirror/glass get light tints so they still read as reflective.
+    return kind === 'diffuse'
+      ? hslToRgb(h, 0.45 + Math.random() * 0.45, 0.35 + Math.random() * 0.2)
+      : hslToRgb(h, 0.5 + Math.random() * 0.5, 0.7 + Math.random() * 0.1);
+  }
+
+  // Display swatches in sRGB, matching smallpt's gamma 2.2 output.
+  const toCss = ([r, g, b]: RGB) => `rgb(${[r, g, b].map((c) => Math.round(Math.pow(c, 1 / 2.2) * 255)).join(' ')})`;
+
+  let teardown: (() => void) | undefined;
+
+  function setup() {
+    teardown?.();
+    teardown = undefined;
+
+    const root = document.querySelector<HTMLElement>('[data-smallpt]');
+    if (!root) return;
+    const canvas = root.querySelector<HTMLCanvasElement>('[data-smallpt-canvas]')!;
+    const button = root.querySelector<HTMLButtonElement>('[data-smallpt-button]')!;
+    const status = root.querySelector<HTMLElement>('[data-smallpt-status]')!;
+    const progress = root.querySelector<HTMLProgressElement>('[data-smallpt-progress]')!;
+    const swatches = root.querySelector<HTMLUListElement>('[data-smallpt-swatches]')!;
+    const ctx = canvas.getContext('2d')!;
+    const width = Number(root.dataset.width);
+    const height = Number(root.dataset.height);
+    const passes = Number(root.dataset.passes);
+
+    let worker: Worker | undefined;
+    let renderId = 0;
+
+    function showSwatches(colors: Record<number, RGB>) {
+      swatches.replaceChildren(
+        ...SPHERES.map(({ index, label }) => {
+          const li = document.createElement('li');
+          li.className = 'flex items-center gap-2';
+          const chip = document.createElement('span');
+          chip.className = 'inline-block size-3.5 rounded-full border border-gray-400';
+          chip.style.background = toCss(colors[index]);
+          li.append(chip, label);
+          return li;
+        }),
+      );
+    }
+
+    function render(colors: Record<number, RGB>) {
+      worker ??= createWorker();
+      const id = ++renderId;
+      const list: (RGB | null)[] = Array.from({ length: 9 }, (_, i) => colors[i] ?? null);
+      const request: RenderRequest = { id, width, height, passes, colors: list };
+      worker.postMessage(request);
+      showSwatches(colors);
+      progress.value = 0;
+      status.textContent = 'Starting renderer…';
+      button.disabled = false;
+    }
+
+    function createWorker() {
+      const w = new Worker(new URL('../wasm/smallpt/worker.ts', import.meta.url), { type: 'module' });
+      w.onmessage = ({ data }: MessageEvent<WorkerMessage>) => {
+        if (data.id !== renderId) return; // stale frame from a cancelled render
+        if (data.type === 'error') {
+          status.textContent = `Render failed: ${data.message}`;
+          return;
+        }
+        ctx.putImageData(new ImageData(data.pixels, width, height), 0, 0);
+        progress.value = data.pass;
+        const spp = data.pass * 4;
+        status.textContent =
+          data.pass === data.passes
+            ? `Done: ${spp} samples per pixel, ${width}×${height}.`
+            : `Rendering… ${spp} samples per pixel (pass ${data.pass}/${data.passes}, ${Math.round(data.ms)} ms/pass)`;
+      };
+      w.onerror = (e) => {
+        status.textContent = `Render failed: ${e.message || 'could not start the WebAssembly worker'}`;
+      };
+      return w;
+    }
+
+    const onClick = () => {
+      const colors: Record<number, RGB> = {};
+      for (const { index, kind } of SPHERES) colors[index] = randomColor(kind);
+      render(colors);
+    };
+    button.addEventListener('click', onClick);
+
+    // Only spin up the CPU-heavy renderer once the section is on screen.
+    const observer = new IntersectionObserver((entries) => {
+      if (entries.some((e) => e.isIntersecting)) {
+        observer.disconnect();
+        render(DEFAULT_COLORS);
+      }
+    });
+    observer.observe(root);
+
+    teardown = () => {
+      observer.disconnect();
+      button.removeEventListener('click', onClick);
+      worker?.terminate();
+    };
+  }
+
+  // Re-run on every page load, including ClientRouter navigations.
+  document.addEventListener('astro:page-load', setup);
+  document.addEventListener('astro:before-swap', () => {
+    teardown?.();
+    teardown = undefined;
+  });
+</script>
