diff --git a/src/wasm/smallpt/protocol.ts b/src/wasm/smallpt/protocol.ts
new file mode 100644
index 0000000..101e02c
--- /dev/null
+++ b/src/wasm/smallpt/protocol.ts
@@ -0,0 +1,16 @@
+/** Messages exchanged between the page and the smallpt Web Worker. */
+export type RGB = [number, number, number];
+
+export interface RenderRequest {
+  id: number;
+  width: number;
+  height: number;
+  /** Each pass traces 4 samples per pixel (2x2 subpixels). */
+  passes: number;
+  /** Albedo per sphere index; `null` keeps the current color. */
+  colors: (RGB | null)[];
+}
+
+export type WorkerMessage =
+  | { type: 'progress'; id: number; pass: number; passes: number; ms: number; pixels: Uint8ClampedArray<ArrayBuffer> }
+  | { type: 'error'; id: number; message: string };
diff --git a/src/wasm/smallpt/smallpt.cpp b/src/wasm/smallpt/smallpt.cpp
new file mode 100644
index 0000000..bf64800
--- /dev/null
+++ b/src/wasm/smallpt/smallpt.cpp
@@ -0,0 +1,159 @@
+// smallpt, a Path Tracer by Kevin Beason, 2008
+// http://www.kevinbeason.com/smallpt/  (MIT license, see LICENSE.smallpt)
+//
+// WebAssembly port: the scene, ray/sphere intersection, and radiance()
+// integrator are unchanged from the original. The differences are:
+//   * main() + PPM file output were replaced by exported functions so
+//     JavaScript can render progressively, one sample pass at a time, and
+//     read back an RGBA8 buffer for a <canvas>.
+//   * Sphere albedo colors can be set from JavaScript (smallpt_set_color).
+//   * OpenMP is dropped (single wasm thread inside a Web Worker).
+//   * Recursion is capped at a large depth to stay within the wasm stack.
+#include <math.h>
+#include <stdlib.h>
+#include <stdint.h>
+#include <emscripten/emscripten.h>
+
+struct Vec {
+  double x, y, z;
+  Vec(double x_ = 0, double y_ = 0, double z_ = 0) { x = x_; y = y_; z = z_; }
+  Vec operator+(const Vec &b) const { return Vec(x + b.x, y + b.y, z + b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x - b.x, y - b.y, z - b.z); }
+  Vec operator*(double b) const { return Vec(x * b, y * b, z * b); }
+  Vec mult(const Vec &b) const { return Vec(x * b.x, y * b.y, z * b.z); }
+  Vec &norm() { return *this = *this * (1 / sqrt(x * x + y * y + z * z)); }
+  double dot(const Vec &b) const { return x * b.x + y * b.y + z * b.z; }
+  Vec operator%(const Vec &b) const { return Vec(y * b.z - z * b.y, z * b.x - x * b.z, x * b.y - y * b.x); }
+};
+struct Ray { Vec o, d; Ray(Vec o_, Vec d_) : o(o_), d(d_) {} };
+enum Refl_t { DIFF, SPEC, REFR };
+struct Sphere {
+  double rad; Vec p, e, c; Refl_t refl;
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_) : rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const {
+    Vec op = p - r.o;
+    double t, eps = 1e-4, b = op.dot(r.d), det = b * b - op.dot(op) + rad * rad;
+    if (det < 0) return 0; else det = sqrt(det);
+    return (t = b - det) > eps ? t : ((t = b + det) > eps ? t : 0);
+  }
+};
+// Scene: radius, position, emission, color, material
+static Sphere spheres[] = {
+  Sphere(1e5, Vec( 1e5 + 1, 40.8, 81.6), Vec(), Vec(.75, .25, .25), DIFF), // Left
+  Sphere(1e5, Vec(-1e5 + 99, 40.8, 81.6), Vec(), Vec(.25, .25, .75), DIFF), // Rght
+  Sphere(1e5, Vec(50, 40.8, 1e5),         Vec(), Vec(.75, .75, .75), DIFF), // Back
+  Sphere(1e5, Vec(50, 40.8, -1e5 + 170),  Vec(), Vec(),              DIFF), // Frnt
+  Sphere(1e5, Vec(50, 1e5, 81.6),         Vec(), Vec(.75, .75, .75), DIFF), // Botm
+  Sphere(1e5, Vec(50, -1e5 + 81.6, 81.6), Vec(), Vec(.75, .75, .75), DIFF), // Top
+  Sphere(16.5, Vec(27, 16.5, 47),         Vec(), Vec(1, 1, 1) * .999, SPEC), // Mirr
+  Sphere(16.5, Vec(73, 16.5, 78),         Vec(), Vec(1, 1, 1) * .999, REFR), // Glas
+  Sphere(600, Vec(50, 681.6 - .27, 81.6), Vec(12, 12, 12), Vec(),    DIFF)  // Lite
+};
+static const int numSpheres = sizeof(spheres) / sizeof(Sphere);
+
+static inline double clamp(double x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
+static inline int toInt(double x) { return int(pow(clamp(x), 1 / 2.2) * 255 + .5); }
+static inline bool intersect(const Ray &r, double &t, int &id) {
+  double d, inf = t = 1e20;
+  for (int i = numSpheres; i--;) if ((d = spheres[i].intersect(r)) && d < t) { t = d; id = i; }
+  return t < inf;
+}
+
+static Vec radiance(const Ray &r, int depth, unsigned short *Xi) {
+  double t; int id = 0;
+  if (!intersect(r, t, id)) return Vec();
+  const Sphere &obj = spheres[id];
+  Vec x = r.o + r.d * t, n = (x - obj.p).norm(), nl = n.dot(r.d) < 0 ? n : n * -1, f = obj.c;
+  double p = f.x > f.y && f.x > f.z ? f.x : f.y > f.z ? f.y : f.z; // max refl
+  if (++depth > 5) { if (erand48(Xi) < p && depth < 128) f = f * (1 / p); else return obj.e; } // R.R.
+  if (obj.refl == DIFF) {                 // Ideal DIFFUSE reflection
+    double r1 = 2 * M_PI * erand48(Xi), r2 = erand48(Xi), r2s = sqrt(r2);
+    Vec w = nl, u = ((fabs(w.x) > .1 ? Vec(0, 1) : Vec(1)) % w).norm(), v = w % u;
+    Vec d = (u * cos(r1) * r2s + v * sin(r1) * r2s + w * sqrt(1 - r2)).norm();
+    return obj.e + f.mult(radiance(Ray(x, d), depth, Xi));
+  } else if (obj.refl == SPEC)            // Ideal SPECULAR reflection
+    return obj.e + f.mult(radiance(Ray(x, r.d - n * 2 * n.dot(r.d)), depth, Xi));
+  Ray reflRay(x, r.d - n * 2 * n.dot(r.d)); // Ideal dielectric REFRACTION
+  bool into = n.dot(nl) > 0;                // Ray from outside going in?
+  double nc = 1, nt = 1.5, nnt = into ? nc / nt : nt / nc, ddn = r.d.dot(nl), cos2t;
+  if ((cos2t = 1 - nnt * nnt * (1 - ddn * ddn)) < 0)    // Total internal reflection
+    return obj.e + f.mult(radiance(reflRay, depth, Xi));
+  Vec tdir = (r.d * nnt - n * ((into ? 1 : -1) * (ddn * nnt + sqrt(cos2t)))).norm();
+  double a = nt - nc, b = nt + nc, R0 = a * a / (b * b), c = 1 - (into ? -ddn : tdir.dot(n));
+  double Re = R0 + (1 - R0) * c * c * c * c * c, Tr = 1 - Re, P = .25 + .5 * Re, RP = Re / P, TP = Tr / (1 - P);
+  return obj.e + f.mult(depth > 2 ? (erand48(Xi) < P ?   // Russian roulette
+    radiance(reflRay, depth, Xi) * RP : radiance(Ray(x, tdir), depth, Xi) * TP) :
+    radiance(reflRay, depth, Xi) * Re + radiance(Ray(x, tdir), depth, Xi) * Tr);
+}
+
+// ---------------------------------------------------------------------------
+// Progressive rendering API exported to JavaScript.
+// ---------------------------------------------------------------------------
+static int W = 0, H = 0, passes = 0;
+static Vec *accum = nullptr;      // sum of per-pass radiance, per pixel
+static uint8_t *rgba = nullptr;   // display buffer, RGBA8, top row first
+
+extern "C" {
+
+// Allocate buffers for a w x h image and reset accumulation.
+EMSCRIPTEN_KEEPALIVE int smallpt_init(int w, int h) {
+  free(accum); free(rgba);
+  W = w; H = h; passes = 0;
+  accum = (Vec *)calloc((size_t)w * h, sizeof(Vec));
+  rgba = (uint8_t *)malloc((size_t)w * h * 4);
+  return accum && rgba;
+}
+
+// Clear accumulated samples (e.g. after changing colors).
+EMSCRIPTEN_KEEPALIVE void smallpt_reset() {
+  passes = 0;
+  for (int i = 0; i < W * H; i++) accum[i] = Vec();
+}
+
+// Set the diffuse/specular color of sphere `i` (0..numSpheres-1).
+EMSCRIPTEN_KEEPALIVE void smallpt_set_color(int i, double r, double g, double b) {
+  if (i >= 0 && i < numSpheres) spheres[i].c = Vec(r, g, b);
+}
+
+EMSCRIPTEN_KEEPALIVE int smallpt_sphere_count() { return numSpheres; }
+
+// Trace one pass: 2x2 subpixels with tent filter, 1 sample each (4 spp),
+// exactly as in smallpt's main loop. Returns the total passes so far.
+EMSCRIPTEN_KEEPALIVE int smallpt_pass() {
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm()); // cam pos, dir
+  Vec cx = Vec(W * .5135 / H), cy = (cx % cam.d).norm() * .5135;
+  for (int y = 0; y < H; y++) {
+    unsigned short Xi[3] = {0, (unsigned short)(y * y * y), (unsigned short)(passes * 7919 + y)};
+    for (unsigned short x = 0; x < W; x++) {
+      Vec c;
+      for (int sy = 0; sy < 2; sy++)
+        for (int sx = 0; sx < 2; sx++) {
+          double r1 = 2 * erand48(Xi), dx = r1 < 1 ? sqrt(r1) - 1 : 1 - sqrt(2 - r1);
+          double r2 = 2 * erand48(Xi), dy = r2 < 1 ? sqrt(r2) - 1 : 1 - sqrt(2 - r2);
+          Vec d = cx * (((sx + .5 + dx) / 2 + x) / W - .5) +
+                  cy * (((sy + .5 + dy) / 2 + y) / H - .5) + cam.d;
+          // Accumulate unclamped radiance; clamping happens at tone-mapping
+          // so the progressive average converges like smallpt's final image.
+          c = c + radiance(Ray(cam.o + d * 140, d.norm()), 0, Xi) * .25;
+        }
+      accum[(H - y - 1) * W + x] = accum[(H - y - 1) * W + x] + c;
+    }
+  }
+  passes++;
+  return passes;
+}
+
