+/// <reference lib="webworker" />
+import createSmallpt from './smallpt.js';
+import type { RenderRequest, WorkerMessage } from './protocol';
+
+declare const self: DedicatedWorkerGlobalScope;
+
+const modulePromise = createSmallpt();
+let current = 0;
+
+const post = (msg: WorkerMessage, transfer: Transferable[] = []) => self.postMessage(msg, transfer);
+const yieldToEventLoop = () => new Promise((resolve) => setTimeout(resolve, 0));
+
+self.onmessage = async ({ data }: MessageEvent<RenderRequest>) => {
+  const { id, width, height, passes, colors } = data;
+  current = id;
+  try {
+    const wasm = await modulePromise;
+    if (current !== id) return;
+
+    if (!wasm._smallpt_init(width, height)) throw new Error('Out of memory');
+    colors.forEach((c, i) => c && wasm._smallpt_set_color(i, c[0], c[1], c[2]));
+
+    const byteLength = width * height * 4;
+    for (let pass = 1; pass <= passes; pass++) {
+      const start = performance.now();
+      wasm._smallpt_pass();
+      const ptr = wasm._smallpt_image();
+      // Re-read HEAPU8 after the call: memory growth detaches old buffers.
+      const pixels = new Uint8ClampedArray(wasm.HEAPU8.buffer, ptr, byteLength).slice();
+      post({ type: 'progress', id, pass, passes, ms: performance.now() - start, pixels }, [pixels.buffer]);
+
+      // Let a newer render request (e.g. the user clicked again) cancel this one.
+      await yieldToEventLoop();
+      if (current !== id) return;
+    }
+  } catch (err) {
+    post({ type: 'error', id, message: err instanceof Error ? err.message : String(err) });
+  }
+};

