+// Web Worker that runs the smallpt WebAssembly module (compiled from
+// wasm/smallpt.cpp) for a subset of image rows and streams progressive
+// results back to the page after every pass (4 samples per pixel each).
+self.onmessage = async ({ data }) => {
+  const { module, width, height, colors, rows, passes } = data;
+  const instance = await WebAssembly.instantiate(module, {});
+  const e = instance.exports;
+  e._initialize();
+  const ptr = e.init(width, height);
+  e.reset_colors();
+  colors.forEach(([r, g, b], i) => e.set_sphere_color(i, r, g, b));
+
+  const rowBytes = width * 4;
+  for (let pass = 0; pass < passes; pass++) {
+    const out = new Uint8ClampedArray(rows.length * rowBytes);
+    for (let k = 0; k < rows.length; k++) {
+      const row = rows[k];                 // canvas row, 0 = top
+      e.render_row(height - 1 - row, pass); // smallpt counts y from the bottom
+      out.set(new Uint8Array(e.memory.buffer, ptr + row * rowBytes, rowBytes), k * rowBytes);
+    }
+    self.postMessage({ pass, rows, pixels: out }, [out.buffer]);
+  }
+};
