+---
+// Client-side path tracing: smallpt (Kevin Beason) compiled to WebAssembly.
+// Source: wasm/smallpt.cpp, build: `pnpm run build:wasm` -> public/wasm/smallpt.wasm
+const base = import.meta.env.BASE_URL.replace(/\/?$/, '/');
+const WIDTH = 400;
+const HEIGHT = 300;
+const PASSES = 100; // 4 spp per pass -> 400 spp
+---
+<section class="p-4 md:p-6" id="smallpt">
+  <h2 class="text-3xl font-bold border-b-2 border-gray-900 pb-2 mb-6">Rendered in Your Browser</h2>
+  <div class="grid gap-6 md:grid-cols-[minmax(0,3fr)_minmax(0,2fr)] items-start">
+    <figure>
+      <canvas
+        data-smallpt-canvas
+        data-base={base}
+        data-width={WIDTH}
+        data-height={HEIGHT}
+        data-passes={PASSES}
+        width={WIDTH}
+        height={HEIGHT}
+        class="w-full h-auto bg-black aspect-[4/3]"
+        aria-label="Path-traced image of the smallpt Cornell box scene"
+      ></canvas>
+      <figcaption class="mt-2 text-xs text-gray-500" data-smallpt-status aria-live="polite">Loading WebAssembly…</figcaption>
+    </figure>
+    <div>
+      <p class="text-gray-700 mb-4">
+        This image is generated live on your device by
+        <a class="underline hover:text-amber-500" href="http://www.kevinbeason.com/smallpt/" target="_blank" rel="noopener">smallpt</a>,
+        Kevin Beason's 99-line C++ global-illumination path tracer, compiled to WebAssembly. The
+        image starts noisy and gets cleaner with every pass as more light paths are traced, using
+        several Web Workers in parallel.
+      </p>
+      <div class="flex flex-wrap gap-2 mb-4">
+        <button type="button" data-smallpt-random
+          class="bg-gray-900 text-white text-sm font-semibold px-4 py-2 hover:bg-amber-500 transition-colors disabled:opacity-50">
+          Re-render with random colors
+        </button>
+        <button type="button" data-smallpt-reset
+          class="border border-gray-900 text-gray-900 text-sm font-semibold px-4 py-2 hover:bg-gray-100 transition-colors disabled:opacity-50">
+          Original colors
+        </button>
+      </div>
+      <ul class="grid grid-cols-2 gap-x-4 gap-y-1 text-sm text-gray-700" data-smallpt-legend></ul>
+    </div>
+  </div>
+</section>
+
+<script>
+  type RGB = [number, number, number];
+
+  // Index order matches the spheres[] array in wasm/smallpt.cpp.
+  const SPHERES = ['Left wall', 'Right wall', 'Back wall', 'Front wall', 'Floor', 'Ceiling', 'Mirror ball', 'Glass ball', 'Light'];
+  const DEFAULT_COLORS: RGB[] = [
+    [0.75, 0.25, 0.25], [0.25, 0.25, 0.75], [0.75, 0.75, 0.75], [0, 0, 0],
+    [0.75, 0.75, 0.75], [0.75, 0.75, 0.75], [0.999, 0.999, 0.999], [0.999, 0.999, 0.999], [0, 0, 0],
+  ];
+  const LEGEND = [0, 1, 2, 4, 5, 6, 7]; // spheres whose colors are visible / randomized
+
+  let modulePromise: Promise<WebAssembly.Module> | null = null;
+  let workers: Worker[] = [];
+
+  function loadModule(base: string) {
+    if (!modulePromise) {
+      const url = `${base}wasm/smallpt.wasm`;
+      modulePromise = WebAssembly.compileStreaming(fetch(url))
+        .catch(() => fetch(url).then((r) => r.arrayBuffer()).then((b) => WebAssembly.compile(b)));
+      modulePromise.catch(() => { modulePromise = null; });
+    }
+    return modulePromise;
+  }
+
+  function stopWorkers() {
+    workers.forEach((w) => w.terminate());
+    workers = [];
+  }
+
+  function hslToRgb(h: number, s: number, l: number): RGB {
+    const k = (n: number) => (n + h * 12) % 12;
+    const a = s * Math.min(l, 1 - l);
+    const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
+    return [f(0), f(8), f(4)];
+  }
+
+  function scaleTo(c: RGB, max: number): RGB {
+    const m = Math.max(...c, 1e-6);
+    return c.map((v) => (v / m) * max) as RGB;
+  }
+
+  function randomColors(): RGB[] {
+    const colors = DEFAULT_COLORS.map((c) => [...c] as RGB);
+    const rand = (lo: number, hi: number) => lo + Math.random() * (hi - lo);
+    // Diffuse walls: any hue, kept below 0.85 reflectance so the image converges well.
+    for (const i of [0, 1, 2, 4, 5]) {
+      colors[i] = scaleTo(hslToRgb(Math.random(), rand(0.3, 0.9), rand(0.35, 0.6)), rand(0.55, 0.85));
+    }
+    // Mirror and glass: light tints (max channel 0.999 like the original).
+    for (const i of [6, 7]) {
+      colors[i] = scaleTo(hslToRgb(Math.random(), rand(0.3, 1), rand(0.6, 0.8)), 0.999);
+    }
+    return colors;
+  }
+
+  // Same gamma mapping smallpt uses for its output (toInt()).
+  const toCss = (c: RGB) => `rgb(${c.map((v) => Math.round(Math.pow(Math.min(1, Math.max(0, v)), 1 / 2.2) * 255)).join(',')})`;
+
+  function renderLegend(el: HTMLElement, colors: RGB[]) {
+    el.innerHTML = '';
+    for (const i of LEGEND) {
+      const li = document.createElement('li');
+      li.className = 'flex items-center gap-2';
+      const chip = document.createElement('span');
+      chip.className = 'inline-block w-4 h-4 border border-gray-300 shrink-0';
+      chip.style.background = toCss(colors[i]);
+      li.append(chip, SPHERES[i]);
+      el.append(li);
+    }
+  }
+
+  function setup() {
+    const canvas = document.querySelector<HTMLCanvasElement>('[data-smallpt-canvas]');
+    if (!canvas) return;
+    const status = document.querySelector<HTMLElement>('[data-smallpt-status]')!;
+    const legend = document.querySelector<HTMLElement>('[data-smallpt-legend]')!;
+    const randomBtn = document.querySelector<HTMLButtonElement>('[data-smallpt-random]')!;
+    const resetBtn = document.querySelector<HTMLButtonElement>('[data-smallpt-reset]')!;
+    const base = canvas.dataset.base!;
+    const width = Number(canvas.dataset.width);
+    const height = Number(canvas.dataset.height);
+    const passes = Number(canvas.dataset.passes);
+    const ctx = canvas.getContext('2d')!;
+    let runId = 0;
+
+    async function render(colors: RGB[]) {
+      const id = ++runId;
+      stopWorkers();
+      renderLegend(legend, colors);
+      status.textContent = 'Loading WebAssembly…';
+      let module: WebAssembly.Module;
+      try {
+        module = await loadModule(base);
+      } catch (err) {
+        status.textContent = `Could not load the WebAssembly module: ${err}`;
+        return;
+      }
+      if (id !== runId) return;
+
+      const image = ctx.createImageData(width, height);
+      const count = Math.max(1, Math.min(navigator.hardwareConcurrency || 4, 16, height));
+      const donePasses = new Array(count).fill(0);
+      const start = performance.now();
+      let drawQueued = false;
+
+      const updateStatus = () => {
+        const pass = Math.min(...donePasses);
+        const secs = ((performance.now() - start) / 1000).toFixed(1);
+        status.textContent = pass >= passes
+          ? `Done: ${pass * 4} samples per pixel, ${width}×${height}, ${secs}s on ${count} worker${count > 1 ? 's' : ''}.`
+          : `Path tracing… pass ${pass}/${passes} (${pass * 4} spp), ${secs}s, ${count} worker${count > 1 ? 's' : ''}`;
+      };
+
+      for (let k = 0; k < count; k++) {
+        const worker = new Worker(`${base}wasm/smallpt-worker.js`);
+        const rows: number[] = [];
+        for (let y = k; y < height; y += count) rows.push(y);
+        worker.onmessage = ({ data }: MessageEvent<{ pass: number; rows: number[]; pixels: Uint8ClampedArray }>) => {
+          if (id !== runId) return;
+          data.rows.forEach((row, j) => {
+            image.data.set(data.pixels.subarray(j * width * 4, (j + 1) * width * 4), row * width * 4);
+          });
+          donePasses[k] = data.pass + 1;
+          if (donePasses[k] >= passes) worker.terminate();
+          if (!drawQueued) {
+            drawQueued = true;
+            requestAnimationFrame(() => {
+              drawQueued = false;
+              if (id !== runId) return;
+              ctx.putImageData(image, 0, 0);
+              updateStatus();
+            });
+          }
+        };
+        worker.onerror = (e) => {
+          if (id === runId) status.textContent = `Renderer error: ${e.message}`;
+        };
+        worker.postMessage({ module, width, height, colors, rows, passes });
+        workers.push(worker);
+      }
+    }
+
+    randomBtn.addEventListener('click', () => render(randomColors()));
+    resetBtn.addEventListener('click', () => render(DEFAULT_COLORS));
+    render(DEFAULT_COLORS);
+  }
+
+  // Works with Astro's <ClientRouter /> (runs on first load and on every navigation).
+  document.addEventListener('astro:page-load', setup);
+  document.addEventListener('astro:before-swap', stopWorkers);
+</script>
