+// Compiles wasm/smallpt.cpp to public/wasm/smallpt.wasm using the YoWASP
+// Clang/LLD toolchain (itself running as WebAssembly in Node, no emsdk needed).
+// Usage: pnpm run build:wasm
+import { readFile, writeFile, mkdir } from 'node:fs/promises';
+import { runClang } from '@yowasp/clang';
+
+const src = await readFile(new URL('./smallpt.cpp', import.meta.url), 'utf8');
+const out = await runClang([
+  'clang++', '--target=wasm32-wasip1', '-O3', '-ffast-math', '-fno-exceptions', '-fno-rtti',
+  '-mexec-model=reactor', '-Wl,-z,stack-size=4194304', '-Wl,--strip-all',
+  'smallpt.cpp', '-o', 'smallpt.wasm',
+], { 'smallpt.cpp': src });
+
+const outDir = new URL('../public/wasm/', import.meta.url);
+await mkdir(outDir, { recursive: true });
+await writeFile(new URL('smallpt.wasm', outDir), out['smallpt.wasm']);
+console.log(`wrote public/wasm/smallpt.wasm (${out['smallpt.wasm'].length} bytes)`);
