+static int W = 0, H = 0;
+static uint8_t *pixels = 0;   // RGBA8, top row first (canvas order)
+static double *accum = 0;     // per-subpixel (2x2) sum of radiance, RGB
+static const Vec defaultColors[] = {
+  Vec(.75,.25,.25), Vec(.25,.25,.75), Vec(.75,.75,.75), Vec(),
+  Vec(.75,.75,.75), Vec(.75,.75,.75), Vec(1,1,1)*.999, Vec(1,1,1)*.999, Vec()
+};
