+// (Re)allocates and clears the buffers. Returns a pointer to the RGBA buffer.
+EXPORT(init) uint8_t *init(int w, int h) {
+  free(pixels); free(accum);
+  W = w; H = h;
+  pixels = (uint8_t *)calloc((size_t)w * h * 4, 1);
+  accum = (double *)calloc((size_t)w * h * 12, sizeof(double));
+  return pixels;
