+EXPORT(sphere_count) int sphere_count() { return numSpheres; }
+EXPORT(set_sphere_color) void set_sphere_color(int i, double r, double g, double b) {
+  if (i >= 0 && i < numSpheres) spheres[i].c = Vec(r, g, b);
+}
+EXPORT(reset_colors) void reset_colors() {
+  for (int i = 0; i < numSpheres; i++) spheres[i].c = defaultColors[i];
+}
+
+// Adds pass number `pass` (0-based) for image row y (counted from the bottom,
+// as in smallpt). The loop body is smallpt's main(); after n passes the output
+// is identical in form to smallpt run with samps = n (radiance is averaged per
+// subpixel first, then clamped, then the 4 subpixels are box-filtered).
+EXPORT(render_row) void render_row(int y, int pass) {
+  int w = W, h = H;
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+  unsigned short Xi[3]={(unsigned short)pass,(unsigned short)(pass*31337u),(unsigned short)(y*y*y)};
+  double inv = 1.0/(pass+1);
+  for (int x=0; x<w; x++) {               // Loop cols
+    size_t i = (size_t)(h-y-1)*w + x;
+    double *a = accum + i*12;
+    Vec c;
+    for (int sy=0; sy<2; sy++)            // 2x2 subpixel rows
+      for (int sx=0; sx<2; sx++, a+=3){   // 2x2 subpixel cols
+        double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+        double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+        Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+        r = radiance(Ray(cam.o+d*140,d.norm()),0,Xi); // pushed forward to start in interior
+        if (pass == 0) { a[0] = a[1] = a[2] = 0; }
+        a[0] += r.x; a[1] += r.y; a[2] += r.z;
+        c = c + Vec(clamp(a[0]*inv),clamp(a[1]*inv),clamp(a[2]*inv))*.25;
+      }
+    uint8_t *px = pixels + i*4;
+    px[0] = toInt(c.x); px[1] = toInt(c.y); px[2] = toInt(c.z); px[3] = 255;
+  }
+}

