+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>Load</title>
+</head>
+<body>
+<button type="button" id="load">Load data</button>
+<pre id="out" aria-live="polite"></pre>
+<script>
+  const out = document.getElementById('out');
+
+  document.getElementById('load').addEventListener('click', async () => {
+    // Background analytics: low priority so it doesn't compete with critical data.
+    fetch('/api/analytics', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ click: 1 }),
+      priority: 'low',
+      keepalive: true
+    }).catch(() => {});
+
+    // Mission-critical data: high priority.
+    try {
+      const res = await fetch('/api/data', { priority: 'high' });
+      if (!res.ok) throw new Error(`HTTP ${res.status}`);
+      out.textContent = await res.text();
+    } catch (err) {
+      out.textContent = `Error: ${err.message}`;
+    }
+  });
+</script>
+</body>
+</html>

