+      let initialState = '';
+      let allowClose = false;
+      let lastTrigger = null;
+      let toastTimer = null;
+
+      const money = (n) => '$' + n.toFixed(2);
+      const sizesFor = (drink) => drink.sizes || DEFAULT_SIZES;
+
+      Object.entries(DRINKS).forEach(([key, d]) => {
+        drinkSelect.add(new Option(d.name, key));
+      });
+
+      function makeChoice(name, value, label, checked) {
+        const wrap = document.createElement('label');
+        wrap.className = 'choice';
+        const input = document.createElement('input');
+        input.type = 'radio';
+        input.name = name;
+        input.value = value;
+        input.checked = checked;
+        const span = document.createElement('span');
+        span.textContent = label;
+        wrap.append(input, span);
+        return wrap;
+      }
+
+      function renderDrink(key) {
+        const drink = DRINKS[key];
+        drinkSelect.value = key;
+        titleEl.textContent = drink.name;
+        metaEl.textContent = drink.meta + ' · from ' + money(drink.basePrice);
+        descEl.textContent = drink.description;
+        media.style.backgroundImage = 'url("' + drink.image + '")';
+        media.setAttribute('aria-label', drink.name);
+
+        sizeChoices.replaceChildren(...sizesFor(drink).map((s, i) => {
+          const label = s.delta ? s.label + ' (+' + money(s.delta) + ')' : s.label;
