+          row.className = 'check-row';
+          const input = document.createElement('input');
+          input.type = 'checkbox';
+          input.name = 'extras';
+          input.value = x.id;
+          row.append(input, document.createTextNode(x.label + (x.price ? ' (+' + money(x.price) + ')' : '')));
+          return row;
+        }));
+
+        updateTotal();
+      }
+
+      function getState() {
+        const data = new FormData(form);
+        return JSON.stringify({
+          drink: data.get('drink'),
+          size: data.get('size'),
+          milk: data.get('milk'),
+          extras: data.getAll('extras').sort(),
+          quantity: String(data.get('quantity') || '').trim(),
+          notes: String(data.get('notes') || '').trim()
+        });
+      }
+
+      function getQuantity() {
+        const q = parseInt(qtyInput.value, 10);
+        return Number.isFinite(q) ? Math.min(Math.max(q, 1), 20) : 1;
+      }
+
+      function computeTotal() {
+        const drink = DRINKS[drinkSelect.value];
+        const data = new FormData(form);
+        const size = sizesFor(drink).find((s) => s.id === data.get('size'));
+        const extras = data.getAll('extras')
+          .map((id) => drink.extras.find((x) => x.id === id))
+          .filter(Boolean)
+          .reduce((sum, x) => sum + x.price, 0);
+        return (drink.basePrice + (size ? size.delta : 0) + extras) * getQuantity();
+      }
+
+      function updateTotal() {
+        totalEl.textContent = money(computeTotal());
+      }
+
+      const isDirty = () => getState() !== initialState;
+
+      function showDiscardPrompt() {
+        footerMain.hidden = true;
+        discardPanel.hidden = false;
+        keepEditingBtn.focus();
+      }
+
+      function hideDiscardPrompt(returnFocus) {
+        discardPanel.hidden = true;
+        footerMain.hidden = false;
+        if (returnFocus) form.querySelector('button[type="submit"]').focus();
+      }
+
+      function forceClose() {
+        hideDiscardPrompt(false);
+        allowClose = true;
+        dialog.close();
+      }
+
+      // Every dismissal path (Esc, backdrop, ×, Cancel) goes through here.
+      function requestClose() {
+        if (!discardPanel.hidden) {
+          // Prompt already showing; dismissal attempts still require explicit "Discard changes".
+          keepEditingBtn.focus();
+          return;
+        }
+        if (isDirty()) {
+          showDiscardPrompt();
+        } else {
+          forceClose();
+        }
+      }
+
+      function openDialog(key, trigger) {
+        lastTrigger = trigger || null;
+        form.reset();
+        renderDrink(key);
+        hideDiscardPrompt(false);
+        initialState = getState();
+        allowClose = false;
+        dialog.showModal();
+        dialog.querySelector('.dialog-body').scrollTop = 0;
+        document.getElementById('drink-dialog-close').focus();
+      }
+
+      document.querySelectorAll('[data-drink-dialog]').forEach((el) => {
+        el.addEventListener('click', (e) => {
+          if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return; // allow open-in-new-tab
+          e.preventDefault();
+          openDialog(el.dataset.drinkDialog, el);
+        });
+      });
+
+      drinkSelect.addEventListener('change', () => {
+        renderDrink(drinkSelect.value);
+      });
+
+      form.addEventListener('input', updateTotal);
+      form.addEventListener('change', updateTotal);
+
+      // Escape key: intercept before the browser turns it into a close request.
+      dialog.addEventListener('keydown', (e) => {
+        if (e.key === 'Escape') {
+          e.preventDefault();
+          e.stopPropagation();
+          requestClose();
+        }
+      });
+
+      // Other close requests (e.g. Android back gesture).
+      dialog.addEventListener('cancel', (e) => {
+        e.preventDefault();
+        requestClose();
+      });
+
+      // Backdrop click: the <dialog> itself is only the target when clicking outside the form.
+      let pointerDownOnBackdrop = false;
+      dialog.addEventListener('pointerdown', (e) => {
+        pointerDownOnBackdrop = e.target === dialog;
+      });
+      dialog.addEventListener('click', (e) => {
+        if (e.target === dialog && pointerDownOnBackdrop) requestClose();
+        pointerDownOnBackdrop = false;
+      });
+
+      document.getElementById('drink-dialog-close').addEventListener('click', requestClose);
+      document.getElementById('drink-cancel').addEventListener('click', requestClose);
+      keepEditingBtn.addEventListener('click', () => hideDiscardPrompt(true));
+      discardBtn.addEventListener('click', forceClose);
+
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        qtyInput.value = getQuantity();
+        const drink = DRINKS[drinkSelect.value];
+        const data = new FormData(form);
+        const size = sizesFor(drink).find((s) => s.id === data.get('size'));
+        const qty = getQuantity();
+        const total = computeTotal();
+        forceClose();
+        showToast('Added ' + qty + ' × ' + (size ? size.label.split(' ')[0] + ' ' : '') +
+          drink.name + ' to your order (' + money(total) + ')');
+      });
+
+      dialog.addEventListener('close', () => {
+        // Safety net: if the browser closed the dialog without going through requestClose
+        // (e.g. a non-cancelable close request) while there are unsaved changes, reopen it.
+        if (!allowClose && isDirty()) {
+          dialog.showModal();
+          showDiscardPrompt();
+          return;
+        }
+        allowClose = false;
+        if (lastTrigger && document.contains(lastTrigger)) lastTrigger.focus();
+        lastTrigger = null;
+      });
+
+      function showToast(message) {
+        toast.textContent = message;
+        toast.classList.add('show');
+        clearTimeout(toastTimer);
+        toastTimer = setTimeout(() => toast.classList.remove('show'), 3500);
+      }
+    })();
+  </script>
+
 </body>

