+// Digital signing & verification for Daily Grind receipts and gift vouchers.
+//
+// Prefers post-quantum ML-DSA-65 (FIPS 204) via WebCrypto, falling back to
+// Ed25519, then ECDSA P-256/SHA-256 on browsers without those algorithms.
+// The issuer's private key is generated non-extractable and persisted in
+// IndexedDB, so it never leaves the browser's crypto implementation.
+
+const TOKEN_VERSION = 'DG-SIG-1';
+const ISSUER = 'The Daily Grind Coffee Co.';
+
+// Domain-separation contexts: a receipt signature can never be replayed as a voucher.
+const CONTEXTS = {
+  receipt: 'daily-grind/receipt/v1',
+  voucher: 'daily-grind/voucher/v1',
+};
+
+const MENU = {
+  'maple-oat-latte': { name: 'Maple Oat Latte', unitCents: 575 },
+  'dark-roast-espresso': { name: 'Dark Roast Espresso', unitCents: 350 },
+  'cold-brew': { name: 'Cold Brew', unitCents: 495 },
+};
+
+const encoder = new TextEncoder();
+
+/* ---------- Encoding helpers ---------- */
+
+function toBase64Url(bytes) {
+  if (typeof bytes.toBase64 === 'function') {
+    return bytes.toBase64({ alphabet: 'base64url', omitPadding: true });
+  }
+  let bin = '';
+  for (const b of bytes) bin += String.fromCharCode(b);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+function fromBase64Url(str) {
+  if (typeof str !== 'string') throw new TypeError('Expected a base64url string');
+  if (typeof Uint8Array.fromBase64 === 'function') {
+    return Uint8Array.fromBase64(str, { alphabet: 'base64url' });
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/');
+  const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
+  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
+}
+
+async function fingerprint(publicKeyBytes) {
+  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', publicKeyBytes));
+  return Array.from(digest.slice(0, 16), (b) => b.toString(16).padStart(2, '0'))
+    .join('')
+    .match(/.{4}/g)
+    .join(':');
+}
+
+const formatCents = (cents) =>
+  new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100);
+
+/* ---------- Signature suites ---------- */
+
+// Classical algorithms ignore `context`, so prepend a length-prefixed context
+// header to keep domain separation consistent across all suites.
+function frameWithContext(payloadBytes, contextBytes) {
+  if (contextBytes.byteLength > 255) {
+    throw new DOMException('Context must not exceed 255 bytes', 'OperationError');
+  }
+  const framed = new Uint8Array(1 + contextBytes.byteLength + payloadBytes.byteLength);
+  framed[0] = contextBytes.byteLength;
+  framed.set(contextBytes, 1);
+  framed.set(payloadBytes, 1 + contextBytes.byteLength);
+  return framed;
+}
+
+const SUITES = {
+  'ML-DSA-65': {
+    label: 'ML-DSA-65 (post-quantum, FIPS 204)',
+    generate: () => crypto.subtle.generateKey('ML-DSA-65', false, ['sign', 'verify']),
+    exportPublic: (key) => crypto.subtle.exportKey('raw-public', key),
+    importPublic: (bytes) =>
+      crypto.subtle.importKey('raw-public', bytes, 'ML-DSA-65', true, ['verify']),
+    sign: (key, data, ctx) => crypto.subtle.sign({ name: 'ML-DSA-65', context: ctx }, key, data),
+    verify: (key, sig, data, ctx) =>
+      crypto.subtle.verify({ name: 'ML-DSA-65', context: ctx }, key, sig, data),
+  },
+  Ed25519: {
+    label: 'Ed25519 (classical)',
+    generate: () => crypto.subtle.generateKey('Ed25519', false, ['sign', 'verify']),
+    exportPublic: (key) => crypto.subtle.exportKey('raw', key),
+    importPublic: (bytes) => crypto.subtle.importKey('raw', bytes, 'Ed25519', true, ['verify']),
+    sign: (key, data, ctx) => crypto.subtle.sign('Ed25519', key, frameWithContext(data, ctx)),
+    verify: (key, sig, data, ctx) =>
+      crypto.subtle.verify('Ed25519', key, sig, frameWithContext(data, ctx)),
+  },
+  'ECDSA-P256-SHA256': {
+    label: 'ECDSA P-256 / SHA-256 (classical)',
+    generate: () =>
+      crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign', 'verify']),
+    exportPublic: (key) => crypto.subtle.exportKey('raw', key),
+    importPublic: (bytes) =>
+      crypto.subtle.importKey('raw', bytes, { name: 'ECDSA', namedCurve: 'P-256' }, true, [
+        'verify',
+      ]),
+    sign: (key, data, ctx) =>
+      crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, frameWithContext(data, ctx)),
+    verify: (key, sig, data, ctx) =>
+      crypto.subtle.verify(
+        { name: 'ECDSA', hash: 'SHA-256' },
+        key,
+        sig,
+        frameWithContext(data, ctx),
+      ),
+  },
+};
+
+function supportsPostQuantum() {
+  return (
+    typeof globalThis.SubtleCrypto?.supports === 'function' &&
+    SubtleCrypto.supports('sign', 'ML-DSA-65')
+  );
+}
+
+async function generateIssuerKey() {
+  const order = supportsPostQuantum()
+    ? ['ML-DSA-65', 'Ed25519', 'ECDSA-P256-SHA256']
+    : ['Ed25519', 'ECDSA-P256-SHA256'];
+  for (const suite of order) {
+    try {
+      const keyPair = await SUITES[suite].generate();
+      const publicKeyBytes = new Uint8Array(await SUITES[suite].exportPublic(keyPair.publicKey));
+      return { suite, keyPair, publicKeyBytes };
+    } catch {
+      // Algorithm unavailable in this browser; try the next suite.
+    }
+  }
+  throw new Error('This browser does not support any WebCrypto signature algorithm.');
+}
+
+/* ---------- Key persistence (IndexedDB stores CryptoKey objects natively) ---------- */
+
+const DB_NAME = 'daily-grind-signing';
+const STORE = 'keys';
+const KEY_ID = 'issuer';
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, 1);
+    req.onupgradeneeded = () => req.result.createObjectStore(STORE);
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+}
+
+async function idb(mode, fn) {
+  const db = await openDb();
+  try {
+    return await new Promise((resolve, reject) => {
+      const tx = db.transaction(STORE, mode);
+      const req = fn(tx.objectStore(STORE));
+      tx.oncomplete = () => resolve(req.result);
+      tx.onerror = tx.onabort = () => reject(tx.error);
+    });
+  } finally {
+    db.close();
+  }
+}
+
+async function loadOrCreateIssuerKey() {
+  try {
+    const stored = await idb('readonly', (s) => s.get(KEY_ID));
+    if (stored && SUITES[stored.suite] && stored.keyPair?.privateKey) return stored;
+  } catch {
+    // IndexedDB unavailable (e.g. private mode restrictions); use an ephemeral key.
+  }
+  const fresh = await generateIssuerKey();
+  try {
+    await idb('readwrite', (s) => s.put(fresh, KEY_ID));
+  } catch {
+    fresh.ephemeral = true;
+  }
+  return fresh;
+}
+
+/* ---------- Sign & verify tokens ---------- */
+
+async function signDocument(issuer, document) {
+  const context = CONTEXTS[document.type];
+  if (!context) throw new Error(`Unknown document type: ${document.type}`);
+  const payload = JSON.stringify(document);
+  const signature = new Uint8Array(
+    await SUITES[issuer.suite].sign(
+      issuer.keyPair.privateKey,
+      encoder.encode(payload),
+      encoder.encode(context),
+    ),
+  );
+  return JSON.stringify(
+    {
+      v: TOKEN_VERSION,
+      alg: issuer.suite,
+      kid: issuer.fingerprint,
+      pub: toBase64Url(issuer.publicKeyBytes),
+      payload,
+      sig: toBase64Url(signature),
+    },
+    null,
+    2,
+  );
+}
+
+/**
+ * Returns { state: 'trusted' | 'untrusted' | 'invalid', reason, document? }.
+ * The signature is checked against the key embedded in the token, and that key
+ * is then compared to the pinned issuer key — a valid signature from any other
+ * key proves integrity but not that The Daily Grind issued it.
+ */
+async function verifyToken(issuer, tokenText) {
+  let token;
+  try {
+    token = JSON.parse(tokenText);
+  } catch {
+    return { state: 'invalid', reason: 'Token is not valid JSON.' };
+  }
+  if (token?.v !== TOKEN_VERSION) {
+    return { state: 'invalid', reason: 'Unrecognised token format.' };
+  }
+  if (typeof token.payload !== 'string') {
+    return { state: 'invalid', reason: 'Token is missing its signed payload.' };
+  }
+  const suite = Object.hasOwn(SUITES, token.alg) ? SUITES[token.alg] : null;
+  if (!suite) return { state: 'invalid', reason: `Unsupported algorithm “${token.alg}”.` };
+
+  let document;
+  try {
+    document = JSON.parse(token.payload);
+  } catch {
+    return { state: 'invalid', reason: 'Signed payload is not valid JSON.' };
+  }
+  const context = Object.hasOwn(CONTEXTS, document?.type) ? CONTEXTS[document.type] : null;
+  if (!context) return { state: 'invalid', reason: 'Unknown document type.' };
+
+  let publicKeyBytes, signatureBytes, publicKey;
+  try {
+    publicKeyBytes = fromBase64Url(token.pub);
+    signatureBytes = fromBase64Url(token.sig);
+  } catch {
+    return { state: 'invalid', reason: 'Public key or signature is not valid base64url.' };
+  }
+  try {
+    publicKey = await suite.importPublic(publicKeyBytes);
+  } catch (err) {
+    return {
+      state: 'invalid',
+      reason:
+        err?.name === 'NotSupportedError'
+          ? `This browser cannot verify ${token.alg} signatures.`
+          : 'Embedded public key is malformed.',
+    };
+  }
+
+  let valid = false;
+  try {
+    valid = await suite.verify(
+      publicKey,
+      signatureBytes,
+      encoder.encode(token.payload),
+      encoder.encode(context),
+    );
+  } catch {
+    valid = false;
+  }
+  if (!valid) {
+    return {
+      state: 'invalid',
+      reason: 'Signature does not match — this document has been altered or forged.',
+    };
+  }
+
+  const signerFingerprint = await fingerprint(publicKeyBytes);
+  if (token.alg !== issuer.suite || signerFingerprint !== issuer.fingerprint) {
+    return {
+      state: 'untrusted',
+      reason: `Signature is intact, but it was made by an unknown key (${signerFingerprint}), not The Daily Grind.`,
+      document,
+      signerFingerprint,
+      alg: token.alg,
+    };
+  }
+
+  if (document.type === 'voucher' && Date.parse(document.expiresAt) < Date.now()) {
+    return {
+      state: 'invalid',
+      reason: 'Authentic voucher, but it has expired.',
+      document,
+      signerFingerprint,
+      alg: token.alg,
+    };
+  }
+
+  return {
+    state: 'trusted',
+    reason: `Authentic ${document.type} issued by ${ISSUER}.`,
+    document,
+    signerFingerprint,
+    alg: token.alg,
+  };
