+/* ---------- Document builders ---------- */
+
+function buildReceipt(form) {
+  const data = new FormData(form);
+  const items = Object.entries(MENU)
+    .map(([sku, { name, unitCents }]) => ({
+      sku,
+      name,
+      qty: Number.parseInt(data.get(sku), 10) || 0,
+      unitCents,
+    }))
+    .filter((item) => item.qty > 0);
+  return {
+    type: 'receipt',
+    id: crypto.randomUUID(),
+    issuer: ISSUER,
+    issuedAt: new Date().toISOString(),
+    customer: String(data.get('customer')).trim(),
+    items,
+    totalCents: items.reduce((sum, i) => sum + i.qty * i.unitCents, 0),
+    currency: 'USD',
+  };
+}
+
+function voucherCode() {
+  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
+  const bytes = crypto.getRandomValues(new Uint8Array(12));
+  const chars = Array.from(bytes, (b) => alphabet[b % alphabet.length]).join('');
+  return `DG-${chars.slice(0, 4)}-${chars.slice(4, 8)}-${chars.slice(8)}`;
+}
+
+function buildVoucher(form) {
+  const data = new FormData(form);
+  const issued = new Date();
+  const expires = new Date(issued);
+  expires.setFullYear(expires.getFullYear() + 1);
+  return {
+    type: 'voucher',
+    id: crypto.randomUUID(),
+    code: voucherCode(),
+    issuer: ISSUER,
+    issuedAt: issued.toISOString(),
+    expiresAt: expires.toISOString(),
+    recipient: String(data.get('recipient')).trim(),
+    sender: String(data.get('sender')).trim(),
+    amountCents: Number.parseInt(data.get('amount'), 10),
+    currency: 'USD',
+    message: String(data.get('message') ?? '').trim(),
+  };
+}
+
+/* ---------- UI ---------- */
+
+function describeDocument(doc) {
+  if (doc.type === 'receipt') {
+    const items = Array.isArray(doc.items)
+      ? doc.items.map((i) => `${i.qty} × ${i.name}`).join(', ')
+      : '—';
+    return [
+      ['Receipt', doc.id],
+      ['Customer', doc.customer],
+      ['Items', items],
+      ['Total', formatCents(doc.totalCents)],
+      ['Issued', new Date(doc.issuedAt).toLocaleString()],
+    ];
+  }
+  return [
+    ['Voucher code', doc.code],
+    ['Value', formatCents(doc.amountCents)],
+    ['To', doc.recipient],
+    ['From', doc.sender],
+    ...(doc.message ? [['Message', doc.message]] : []),
+    ['Expires', new Date(doc.expiresAt).toLocaleDateString()],
+  ];
+}
+
+function renderResult(output, result) {
+  output.replaceChildren();
+  output.dataset.state = result.state;
+  const icon = { trusted: '✅', untrusted: '⚠️', invalid: '❌' }[result.state];
+  const heading = document.createElement('strong');
+  heading.textContent = `${icon} ${result.reason}`;
+  output.append(heading);
+
+  if (!result.document) return;
+  const dl = document.createElement('dl');
+  const rows = [
+    ...describeDocument(result.document),
+    ['Algorithm', SUITES[result.alg]?.label ?? result.alg],
+    ['Signer key', result.signerFingerprint],
+  ];
+  for (const [term, value] of rows) {
+    const dt = document.createElement('dt');
+    const dd = document.createElement('dd');
+    dt.textContent = term;
+    dd.textContent = String(value ?? '—');
+    dl.append(dt, dd);
+  }
+  output.append(dl);
+}
+
+async function init() {
+  const keyInfo = document.getElementById('key-info');
+  const receiptForm = document.getElementById('receipt-form');
+  const voucherForm = document.getElementById('voucher-form');
+  const verifyForm = document.getElementById('verify-form');
+  const tokenField = verifyForm.elements.token;
+  const output = document.getElementById('verify-result');
+  const copyButton = document.getElementById('copy-token');
+  const signButtons = [receiptForm, voucherForm].map((f) => f.querySelector('button'));
+
+  if (!globalThis.crypto?.subtle) {
+    keyInfo.textContent =
+      'Digital signatures require a secure (HTTPS) context with WebCrypto support.';
+    signButtons.forEach((b) => (b.disabled = true));
+    verifyForm.querySelector('button[type="submit"]').disabled = true;
+    return;
+  }
+
+  signButtons.forEach((b) => (b.disabled = true));
+  let issuer;
+  try {
+    issuer = await loadOrCreateIssuerKey();
+    issuer.fingerprint = await fingerprint(issuer.publicKeyBytes);
+  } catch (err) {
+    keyInfo.textContent = `Unable to prepare a signing key: ${err.message}`;
+    return;
+  }
+  signButtons.forEach((b) => (b.disabled = false));
+
+  keyInfo.replaceChildren(
+    'Issuer key: ',
+    Object.assign(document.createElement('strong'), { textContent: SUITES[issuer.suite].label }),
+    ' · fingerprint ',
+    Object.assign(document.createElement('code'), { textContent: issuer.fingerprint }),
+    issuer.ephemeral ? ' · (temporary key — storage unavailable)' : '',
+  );
+
+  // Require at least one item on a receipt.
+  const qtyInputs = Object.keys(MENU).map((sku) => receiptForm.elements[sku]);
+  const checkItems = () => {
+    const any = qtyInputs.some((i) => Number(i.value) > 0);
+    qtyInputs[0].setCustomValidity(any ? '' : 'Add at least one drink to the order.');
+  };
+  qtyInputs.forEach((i) => i.addEventListener('input', checkItems));
+  checkItems();
+
+  const handleSign = (form, build) => {
+    form.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      const button = form.querySelector('button');
+      button.disabled = true;
+      try {
+        tokenField.value = await signDocument(issuer, build(form));
+        renderResult(output, await verifyToken(issuer, tokenField.value));
+      } catch (err) {
+        renderResult(output, { state: 'invalid', reason: `Signing failed: ${err.message}` });
+      } finally {
+        button.disabled = false;
+      }
+    });
+  };
+  handleSign(receiptForm, buildReceipt);
+  handleSign(voucherForm, buildVoucher);
+
+  verifyForm.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    renderResult(output, await verifyToken(issuer, tokenField.value.trim()));
+  });
+
+  // Clear stale results as soon as the token is edited.
+  tokenField.addEventListener('input', () => {
+    output.replaceChildren();
+    delete output.dataset.state;
+  });
+
+  copyButton.addEventListener('click', async () => {
+    if (!tokenField.value) return;
+    try {
+      await navigator.clipboard.writeText(tokenField.value);
+      copyButton.textContent = 'Copied!';
+    } catch {
+      tokenField.select();
+      copyButton.textContent = 'Press Ctrl+C';
+    }
+    setTimeout(() => (copyButton.textContent = 'Copy token'), 1500);
+  });
+}
