+// Daily Grind document signing core.
+//
+// Signs and verifies coffee order receipts and gift vouchers in the browser
+// using asymmetric keys. Supported algorithms:
+//   - ES256            ECDSA P-256 / SHA-256 (WebCrypto)
+//   - Ed25519          EdDSA (WebCrypto, where the browser supports it)
+//   - ML-DSA-65        FIPS 204 post-quantum signature (vendored @noble/post-quantum)
+//   - ES256+ML-DSA-65  Hybrid: both signatures are produced and BOTH must verify
+//
+// Envelope format (serialised as "DGSIG1." + base64url(JSON)):
+//   { v, type, alg, kid, pub, payload, sig }
+// The signed bytes are the canonical JSON of { ctx, v, type, alg, kid, payload },
+// so the algorithm, signer fingerprint and document type are all covered by the
+// signature (no algorithm/type confusion, no key substitution).
+//
+// A valid signature only proves integrity and possession of the private key
+// that matches the *embedded* public key. Authenticity additionally requires
+// that key's fingerprint to be trusted — see verifyToken().
+
+import { ml_dsa65 } from '../vendor/noble-ml-dsa.js';
+
+export const TOKEN_PREFIX = 'DGSIG1.';
+const ENVELOPE_VERSION = 1;
+const SIGN_CONTEXT = 'daily-grind/signed-document/v1';
+const PQ_CONTEXT = new TextEncoder().encode('daily-grind/v1');
+const MAX_TOKEN_LENGTH = 64 * 1024;
+
+const ECDSA_GEN = { name: 'ECDSA', namedCurve: 'P-256' };
+const ECDSA_SIGN = { name: 'ECDSA', hash: 'SHA-256' };
+const ED25519 = { name: 'Ed25519' };
+
+export const ALGORITHMS = {
+  ES256: { label: 'ECDSA P-256 (classical)', quantumResistant: false, parts: ['ec'] },
+  Ed25519: { label: 'Ed25519 (classical)', quantumResistant: false, parts: ['ed'] },
+  'ML-DSA-65': { label: 'ML-DSA-65 (post-quantum, FIPS 204)', quantumResistant: true, parts: ['pq'] },
+  'ES256+ML-DSA-65': { label: 'Hybrid ECDSA P-256 + ML-DSA-65', quantumResistant: true, parts: ['ec', 'pq'] },
+};
+
+export const DOC_TYPES = ['receipt', 'voucher'];
+
+// ---------------------------------------------------------------------------
+// Encoding helpers
+// ---------------------------------------------------------------------------
+
+const enc = new TextEncoder();
+const dec = new TextDecoder('utf-8', { fatal: true });
+
+export function b64uEncode(bytes) {
+  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
+  let s = '';
