+    /* Seasonal Favorites carousel */
+    .carousel {
+      max-width: 480px;
+      margin: 20px auto 0;
+    }
+
+    .carousel-viewport {
+      /* Clips sliding cards; scoped view transitions inherit this clip */
+      overflow: clip;
+      border-radius: 8px;
+      padding: 4px;
+    }
+
+    .carousel-viewport > .card:not([hidden]) {
+      view-transition-name: slide;
+    }
+
+    .carousel-controls {
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
+      gap: 1rem;
+      margin-top: 15px;
+    }
+
+    .carousel-btn {
+      font: inherit;
+      background: white;
+      color: var(--primary);
+      border: 2px solid var(--primary);
+      border-radius: 5px;
+      padding: 8px 16px;
+      cursor: pointer;
+      transition: background 0.3s, color 0.3s;
+    }
+
+    .carousel-btn:hover {
+      background: var(--primary);
+      color: white;
+    }
+
+    .carousel-btn:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    .carousel-status {
+      font-size: 0.9rem;
+    }
+
+    @keyframes slide-to-left {
+      to { transform: translateX(-100%); }
+    }
+
+    @keyframes slide-from-right {
+      from { transform: translateX(100%); }
+    }
+
+    @keyframes slide-to-right {
+      to { transform: translateX(100%); }
+    }
+
+    @keyframes slide-from-left {
+      from { transform: translateX(-100%); }
+    }
+
+    .carousel-viewport::view-transition-group(slide),
+    .carousel-viewport::view-transition-old(slide),
+    .carousel-viewport::view-transition-new(slide) {
+      animation-duration: 0.4s;
+      animation-timing-function: ease-in-out;
+      animation-fill-mode: both;
+    }
+
+    .carousel-viewport:active-view-transition-type(forward)::view-transition-old(slide) {
+      animation-name: slide-to-left;
+    }
+
+    .carousel-viewport:active-view-transition-type(forward)::view-transition-new(slide) {
+      animation-name: slide-from-right;
+    }
+
