+    const slides = Array.from(root.querySelectorAll<HTMLElement>('.top-stories-slide'));
+    const prev = root.querySelector<HTMLButtonElement>('.top-stories-prev')!;
+    const next = root.querySelector<HTMLButtonElement>('.top-stories-next')!;
