@@ -0,0 +1,92 @@
+import { useState } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface TopStory {
+  id: string;
+  title: string;
+  href: string;
+  date: string;
+}
+
+interface Props {
+  stories: TopStory[];
+}
+
+type Direction = 'next' | 'prev' | null;
+
+export default function TopStoriesCarousel({ stories }: Props) {
+  const [index, setIndex] = useState(0);
+  // Bumped on every navigation so the story element remounts and replays its
+  // animation, even if the same index is reached again (e.g. with 1–2 stories).
+  const [step, setStep] = useState(0);
+  const [direction, setDirection] = useState<Direction>(null);
+
+  const count = stories.length;
+  if (count === 0) return null;
+
+  const go = (dir: Exclude<Direction, null>) => {
+    setDirection(dir);
+    setIndex((i) => (dir === 'next' ? (i + 1) % count : (i - 1 + count) % count));
+    setStep((s) => s + 1);
+  };
+
+  const story = stories[index];
+  const animationClass =
+    direction === 'next'
+      ? 'top-story-enter-from-right'
+      : direction === 'prev'
+        ? 'top-story-enter-from-left'
+        : '';
+
+  const buttonClass =
+    'shrink-0 p-2 rounded-full border border-gray-300 text-gray-700 hover:text-amber-500 hover:border-amber-400 ' +
+    'focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-400 disabled:opacity-40 disabled:pointer-events-none cursor-pointer';
+
+  return (
+    <section
+      className="flex items-center gap-4"
+      aria-roledescription="carousel"
+      aria-label="Top Stories"
+    >
+      <button
+        type="button"
+        className={buttonClass}
+        onClick={() => go('prev')}
+        disabled={count < 2}
+        aria-label="Previous story"
+      >
+        <ChevronLeftIcon className="h-5 w-5" />
+      </button>
+
+      <div className="relative flex-1 min-w-0 overflow-hidden">
+        <div
+          key={step}
+          className={`text-center ${animationClass}`}
+          role="group"
+          aria-roledescription="slide"
+          aria-label={`${index + 1} of ${count}`}
+          aria-live="polite"
+        >
+          <a href={story.href}>
+            <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer truncate">
+              {story.title}
+            </h3>
+          </a>
+          <span className="text-xs text-gray-500">
+            {story.date} · {index + 1} / {count}
+          </span>
+        </div>
+      </div>
+
+      <button
+        type="button"
+        className={buttonClass}
+        onClick={() => go('next')}
+        disabled={count < 2}
+        aria-label="Next story"
+      >
+        <ChevronRightIcon className="h-5 w-5" />
+      </button>
+    </section>
+  );
+}
