+      });
+
+      /* ---------- Order controls ---------- */
+      const form = document.getElementById('qo-body');
+      const qty = document.getElementById('qo-qty');
+      const linePrice = document.getElementById('qo-line-price');
+      const cartEl = document.getElementById('qo-cart');
+      const cartList = document.getElementById('qo-cart-list');
+      const totalEl = document.getElementById('qo-total');
+      const badge = document.getElementById('qo-badge');
+      const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+      const cart = [];
+
+      const clampQty = () => {
+        const n = Math.round(Number(qty.value)) || 1;
+        qty.value = Math.min(12, Math.max(1, n));
+        return Number(qty.value);
+      };
+
+      function currentItem() {
+        const drink = form.drink.selectedOptions[0];
+        const size = form.querySelector('input[name="size"]:checked');
+        const milk = form.milk.selectedOptions[0];
+        const unit = Number(drink.dataset.price) + Number(size.dataset.upcharge) +
+          (milk.value === 'oat' || milk.value === 'almond' ? 0.6 : 0);
+        const q = clampQty();
+        const name = drink.textContent.split(' — ')[0];
+        const milkLabel = milk.value === 'whole' ? '' : `, ${milk.textContent.split(' (')[0].toLowerCase()}`;
