+        function endDrag(e) {
+          if (pointerId !== e.pointerId) return;
+          if (handle.hasPointerCapture(pointerId)) handle.releasePointerCapture(pointerId);
+          pointerId = null;
+          panel.classList.remove('is-dragging');
+          const rect = panel.getBoundingClientRect();
+          place(rect.left, rect.top, true);
+        }
+        handle.addEventListener('pointerup', endDrag);
+        handle.addEventListener('pointercancel', endDrag);
+
+        // Keyboard support: arrow keys move the panel (Shift = bigger steps)
+        handle.addEventListener('keydown', function (e) {
+          if (e.target !== handle) return;
+          const step = e.shiftKey ? 50 : 10;
+          const d = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] }[e.key];
+          if (!d) return;
+          e.preventDefault();
+          const rect = panel.getBoundingClientRect();
+          place(rect.left + d[0], rect.top + d[1], true);
+        });
+
+        // Keep the panel on-screen when the viewport or panel size changes
+        function reclamp() {
+          if (!hasCustomPosition()) return;
+          const rect = panel.getBoundingClientRect();
+          place(rect.left, rect.top, false);
+        }
+        window.addEventListener('resize', reclamp);
+        panel.addEventListener('qo:resize', reclamp);
+      }
+
+      document.querySelectorAll('[data-draggable]').forEach(initDraggable);
+
+      /* ---------- Quick-order controls ---------- */
+      const panel = document.getElementById('quick-order');
+      const form = document.getElementById('qo-form');
+      const drinkSel = document.getElementById('qo-drink');
+      const milkSel = document.getElementById('qo-milk');
+      const shotChk = document.getElementById('qo-shot');
+      const qtyOut = document.getElementById('qo-qty');
+      const decBtn = document.getElementById('qo-dec');
+      const incBtn = document.getElementById('qo-inc');
+      const addBtn = document.getElementById('qo-add');
+      const itemsList = document.getElementById('qo-items');
+      const emptyMsg = document.getElementById('qo-empty');
+      const totalEl = document.getElementById('qo-total');
+      const badge = document.getElementById('qo-badge');
+      const checkoutBtn = document.getElementById('qo-checkout');
+      const statusEl = document.getElementById('qo-status');
+      const toggleBtn = document.getElementById('qo-toggle');
+
+      const STORAGE_CART = 'dailyGrind.quickOrder.cart';
+      const STORAGE_COLLAPSED = 'dailyGrind.quickOrder.collapsed';
+      const MIN_QTY = 1, MAX_QTY = 10;
+      let qty = 1;
+      let cart = [];
+
+      try {
+        const saved = JSON.parse(localStorage.getItem(STORAGE_CART) || '[]');
+        if (Array.isArray(saved)) cart = saved.filter(function (i) {
+          return i && typeof i.name === 'string' && typeof i.unit === 'number' && typeof i.qty === 'number';
+        });
+      } catch (e) { /* ignore */ }
+
+      const fmt = function (n) { return '$' + n.toFixed(2); };
+
+      function currentSelection() {
+        const drinkOpt = drinkSel.options[drinkSel.selectedIndex];
+        const sizeInput = form.querySelector('input[name="size"]:checked');
+        const milkOpt = milkSel.options[milkSel.selectedIndex];
+        const unit = parseFloat(drinkOpt.dataset.price) +
+          parseFloat(sizeInput.dataset.extra) +
+          parseFloat(milkOpt.dataset.extra) +
+          (shotChk.checked ? 0.75 : 0);
+        const name = drinkOpt.textContent.split(' — ')[0];
+        const opts = [sizeInput.value, milkSel.value === 'None' ? 'No milk' : milkSel.value + ' milk'];
+        if (shotChk.checked) opts.push('Extra shot');
+        return { name: name, details: opts.join(', '), unit: Math.round(unit * 100) / 100 };
+      }
+
+      function updatePreview() {
+        qtyOut.textContent = qty;
+        decBtn.disabled = qty <= MIN_QTY;
+        incBtn.disabled = qty >= MAX_QTY;
+        addBtn.textContent = 'Add to Cart — ' + fmt(currentSelection().unit * qty);
+      }
+
+      function saveCart() {
+        try { localStorage.setItem(STORAGE_CART, JSON.stringify(cart)); } catch (e) { /* ignore */ }
+      }
+
+      function renderCart() {
+        itemsList.textContent = '';
+        let total = 0, count = 0;
+        cart.forEach(function (item, idx) {
+          total += item.unit * item.qty;
+          count += item.qty;
+          const li = document.createElement('li');
+          const info = document.createElement('div');
+          const title = document.createElement('span');
+          title.textContent = item.qty + '× ' + item.name;
+          const small = document.createElement('small');
+          small.textContent = item.details;
+          info.append(title, small);
+          const right = document.createElement('div');
+          right.style.whiteSpace = 'nowrap';
+          const price = document.createElement('span');
+          price.textContent = fmt(item.unit * item.qty) + ' ';
+          const rm = document.createElement('button');
+          rm.type = 'button';
+          rm.className = 'qo-remove';
+          rm.innerHTML = '&times;';
+          rm.setAttribute('aria-label', 'Remove ' + item.name);
+          rm.addEventListener('click', function () {
