+        totalEl.textContent = fmt(total);
+        badge.textContent = count;
+        checkoutBtn.setAttribute('aria-disabled', cart.length ? 'false' : 'true');
+        panel.dispatchEvent(new Event('qo:resize'));
+      }
+
+      let statusTimer;
+      function announce(msg) {
+        statusEl.textContent = msg;
+        clearTimeout(statusTimer);
+        statusTimer = setTimeout(function () { statusEl.textContent = ''; }, 2500);
+      }
+
+      decBtn.addEventListener('click', function () { if (qty > MIN_QTY) { qty--; updatePreview(); } });
+      incBtn.addEventListener('click', function () { if (qty < MAX_QTY) { qty++; updatePreview(); } });
+      form.addEventListener('change', updatePreview);
+
+      form.addEventListener('submit', function (e) {
+        e.preventDefault();
+        const sel = currentSelection();
+        const existing = cart.find(function (i) { return i.name === sel.name && i.details === sel.details; });
+        if (existing) {
+          existing.qty = Math.min(existing.qty + qty, 99);
+        } else {
+          cart.push({ name: sel.name, details: sel.details, unit: sel.unit, qty: qty });
+        }
+        saveCart();
+        renderCart();
+        announce('Added ' + qty + '× ' + sel.name + ' to your cart.');
+        qty = 1;
+        updatePreview();
+      });
+
+      checkoutBtn.addEventListener('click', function () {
+        if (!cart.length) return;
+        window.location.href = '/order-online';
+      });
+
+      function setCollapsed(collapsed) {
+        panel.classList.toggle('is-collapsed', collapsed);
+        toggleBtn.setAttribute('aria-expanded', String(!collapsed));
+        toggleBtn.setAttribute('aria-label', (collapsed ? 'Expand' : 'Minimize') + ' quick order panel');
+        toggleBtn.innerHTML = collapsed ? '+' : '&minus;';
+        try { localStorage.setItem(STORAGE_COLLAPSED, collapsed ? '1' : '0'); } catch (e) { /* ignore */ }
+        panel.dispatchEvent(new Event('qo:resize'));
+      }
+      toggleBtn.addEventListener('click', function () {
+        setCollapsed(!panel.classList.contains('is-collapsed'));
+      });
+
+      let startCollapsed = false;
+      try { startCollapsed = localStorage.getItem(STORAGE_COLLAPSED) === '1'; } catch (e) { /* ignore */ }
+      setCollapsed(startCollapsed);
+      updatePreview();
+      renderCart();
+    })();
+  </script>
+
 </body>

 </html>

