+      --star-focus: #4e342e;
+      --star-error: #c62828;
+      display: inline-block;
+      outline: none;
+      border-radius: 6px;
+      cursor: pointer;
+      -webkit-tap-highlight-color: transparent;
+    }
+    :host([hidden]) { display: none; }
+    :host(:focus-visible) .stars {
+      outline: 2px solid var(--star-focus);
+      outline-offset: 3px;
+    }
+    :host(:disabled) {
+      cursor: not-allowed;
+      opacity: 0.45;
+    }
+    .stars {
+      display: inline-flex;
+      gap: 0.15rem;
+      border-radius: 6px;
+      padding: 2px;
+    }
+    .star {
+      width: var(--star-size);
+      height: var(--star-size);
+      display: block;
+      fill: var(--star-empty);
+      transition: fill 0.15s, transform 0.15s;
+    }
+    .star.on { fill: var(--star-color); }
+    :host(:not(:disabled)) .star:hover { transform: scale(1.12); }
+    .error {
+      display: none;
+      color: var(--star-error);
+      font-size: 0.85rem;
+      margin-top: 0.25rem;
+    }
+    :host(:state(show-error)) .error { display: block; }
+    :host(:state(show-error)) .star:not(.on) {
+      stroke: var(--star-error);
+      stroke-width: 1;
+    }
+    @media (prefers-reduced-motion: reduce) {
+      .star { transition: none; }
+    }
+  </style>
+  <div class="stars" part="stars"></div>
+  <div class="error" part="error" aria-hidden="true"></div>
+`;
