+  #internals;
+  #value = 0;
+  #hover = 0;
+  #dirty = false; // true once the user (or script) changes the value
+  #disabled = false;
+  #starsEl;
+  #errorEl;
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals();
+    this.#internals.role = 'slider';
