+    import { onCLS, onINP, onLCP, onFCP, onTTFB } from 'https://unpkg.com/web-vitals@5/dist/web-vitals.js?module';
+
+    const ANALYTICS_ENDPOINT = '/path/to/analytics/endpoint';
+
+    // One snapshot per page view. Every metric update replaces the pending
+    // deferred request with the latest full snapshot, so whatever is sent
+    // when the user leaves contains the final metric values.
+    let pageView = { id: crypto.randomUUID(), url: location.href, metrics: {} };
+    let controller = null;
+
+    function queueBeacon() {
+      controller?.abort();
+      controller = new AbortController();
+      try {
+        fetchLater(ANALYTICS_ENDPOINT, {
+          method: 'POST',
+          headers: { 'content-type': 'application/json' },
+          body: JSON.stringify(pageView),
+          signal: controller.signal,
+        });
+      } catch (error) {
