+
+.nav-flyout {
+  /* Override the UA popover centering and tether the panel under the nav bar. */
+  position-anchor: --main-nav;
+  inset: auto;
+  top: anchor(bottom);
+  left: anchor(left);
+  right: anchor(right);
+  width: auto;
+  margin: 0;
+  padding: 0;
+  border: 0;
+}
+
+/* Fallback for browsers without CSS anchor positioning: JS writes the nav's rect into custom properties. */
+@supports not (anchor-name: --a) {
+  .nav-flyout {
+    top: var(--flyout-top, 0px);
+    left: var(--flyout-left, 0px);
+    right: auto;
+    width: var(--flyout-width, 100%);
+  }
+}
+
+/* Popover polyfill support: combine with :is() so browsers lacking :popover-open don't drop the rule. */
+@supports not selector(:popover-open) {
+  [popover]:not(.\:popover-open) {
+    display: none;
+  }
+}
+
+[popover]:is(:popover-open, .\:popover-open) {
+  display: block;
