@@ -0,0 +1,60 @@
+import { useEffect, useRef } from 'react';
+
+/**
+ * Opens a native <dialog> as a modal as soon as it mounts and reports when it closes.
+ *
+ * The browser handles focus containment, the inert page, the top layer, Esc / back-gesture
+ * dismissal and focus return to the invoker. Light dismiss uses `closedby="any"` on the element;
+ * this hook only adds a click-outside fallback where `closedby` is unsupported.
+ */
+export function useModalDialog(onClose: () => void) {
+    const dialogRef = useRef<HTMLDialogElement>(null);
+    const onCloseRef = useRef(onClose);
+    onCloseRef.current = onClose;
+
+    useEffect(() => {
+        const dialog = dialogRef.current;
+        if (!dialog) return;
+
+        if (!dialog.open) {
+            dialog.showModal();
+            // React's `autoFocus` doesn't emit the HTML attribute the dialog focusing steps look for,
+            // so move initial focus to the element marked with data-autofocus ourselves.
+            dialog.querySelector<HTMLElement>('[data-autofocus]')?.focus();
+        }
+
+        const handleClose = () => onCloseRef.current();
+        dialog.addEventListener('close', handleClose);
+
+        // Fallback light dismiss for browsers without <dialog closedby>.
+        // Test the pointer position rather than event.target: the dialog is also the target for
+        // clicks on its own padding, so a target check would close on those.
+        let cleanupFallback = () => {};
+        if (!('closedBy' in HTMLDialogElement.prototype)) {
+            const isOutside = (e: PointerEvent) => {
+                const r = dialog.getBoundingClientRect();
+                return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
+            };
+            let pressedOutside = false;
+            const onDown = (e: PointerEvent) => { pressedOutside = isOutside(e); };
+            const onUp = (e: PointerEvent) => { if (pressedOutside && isOutside(e)) dialog.close(); };
+            dialog.addEventListener('pointerdown', onDown);
+            dialog.addEventListener('pointerup', onUp);
+            cleanupFallback = () => {
+                dialog.removeEventListener('pointerdown', onDown);
+                dialog.removeEventListener('pointerup', onUp);
+            };
+        }
+
+        return () => {
+            dialog.removeEventListener('close', handleClose);
+            cleanupFallback();
+            if (dialog.open) dialog.close();
+        };
+    }, []);
+
+    return dialogRef;
+}
+
+/** `closedby` isn't in React's DOM typings yet; spread this onto the <dialog>. */
+export const lightDismiss = { closedby: 'any' } as Record<string, string>;

