new file mode 100644
index 0000000..4b4fca8
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,78 @@
+import React, { useEffect, useRef } from 'react';
+
+interface Props {
+  open: boolean;
+  onClose: () => void;
+  /** id of the element that labels the dialog (usually its heading) */
+  labelledBy: string;
+  closeLabel?: string;
+  children: React.ReactNode;
+}
+
+/**
+ * Thin wrapper around the native <dialog> element opened with showModal().
+ *
+ * The browser provides: top-layer rendering, ::backdrop, inert background,
+ * focus containment, Escape-to-close and focus restoration to the invoking
+ * control on close. We only add light-dismiss (backdrop click) and an initial
+ * focus target via `data-autofocus`.
+ */
+export default function Modal({ open, onClose, labelledBy, closeLabel = 'Close', children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+
+    if (open && !dialog.open) {
+      dialog.showModal();
+      // React's `autoFocus` runs before the dialog is shown, so focus explicitly.
+      dialog.querySelector<HTMLElement>('[data-autofocus]')?.focus();
+    } else if (!open && dialog.open) {
+      dialog.close();
+    }
+  }, [open]);
+
+  // Keep React state in sync when the dialog is closed natively (Escape, form[method=dialog]).
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    const handleClose = () => onClose();
+    dialog.addEventListener('close', handleClose);
+    return () => dialog.removeEventListener('close', handleClose);
+  }, [onClose]);
+
+  // Light dismiss: a click whose target is the <dialog> itself landed on the backdrop.
+  const handleClick = (event: React.MouseEvent<HTMLDialogElement>) => {
+    if (event.target === event.currentTarget) {
+      event.currentTarget.close();
+    }
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      className="modal"
+      aria-labelledby={labelledBy}
+      onClick={handleClick}
+      // Native light dismiss where supported; the click handler above is the fallback.
+      {...{ closedby: 'any' }}
+    >
+      {/* Inner wrapper stops backdrop detection from triggering on content clicks */}
+      <div className="relative">
+        <form method="dialog">
+          <button
+            type="submit"
+            aria-label={closeLabel}
+            className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow-md text-gray-500 hover:text-amber-400 hover:scale-110 transition-transform z-10 focus-visible:outline-2 focus-visible:outline-amber-400"
+          >
+            <svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+            </svg>
+          </button>
+        </form>
+        {open && children}
+      </div>
+    </dialog>
+  );
+}
