@@ -0,0 +1,28 @@
+// Minimal service worker for The Daily Grind web app.
+// Network-first with an offline fallback to the cached home page.
+const CACHE = 'daily-grind-v1';
+const PRECACHE = ['/', '/index.html', '/manifest.webmanifest', '/icon.svg'];
+
+self.addEventListener('install', (event) => {
+  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)));
+  self.skipWaiting();
+});
+
+self.addEventListener('activate', (event) => {
+  event.waitUntil(
+    caches.keys().then((keys) =>
+      Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))
+    )
+  );
+  self.clients.claim();
+});
+
+self.addEventListener('fetch', (event) => {
+  const { request } = event;
+  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
+  event.respondWith(
+    fetch(request).catch(() =>
+      caches.match(request).then((res) => res || (request.mode === 'navigate' ? caches.match('/') : Response.error()))
+    )
+  );
+});

