+            console.warn('Service worker registration failed:', err));
+        });
+      }
+
+      if (isInstalled()) return;
+
+      // Web Install API: navigator.install() opens the browser's native install consent dialog.
+      const hasWebInstall = typeof navigator.install === 'function';
+      if (hasWebInstall) showButton();
+
+      // Fallback: the beforeinstallprompt event (Chromium-based browsers).
+      window.addEventListener('beforeinstallprompt', (event) => {
+        event.preventDefault(); // Show our own button instead of the default mini-infobar.
+        deferredPrompt = event;
+        showButton();
+      });
+
+      window.addEventListener('appinstalled', () => {
+        deferredPrompt = null;
+        hideButton();
+        setStatus('The Daily Grind app is installed. Enjoy!');
+      });
+
+      installBtn.addEventListener('click', async () => {
+        installBtn.disabled = true;
+        setStatus('');
+        try {
+          if (hasWebInstall) {
+            // Installs the current document's web app (as described by its manifest).
+            await navigator.install();
+            hideButton();
+            setStatus('The Daily Grind app is installed. Enjoy!');
+          } else if (deferredPrompt) {
+            deferredPrompt.prompt();
+            const { outcome } = await deferredPrompt.userChoice;
+            deferredPrompt = null; // A prompt can only be used once.
+            if (outcome === 'accepted') {
+              hideButton();
+            } else {
+              hideButton(); // Re-shown if the browser fires beforeinstallprompt again.
+              setStatus('Installation cancelled. You can install anytime from your browser menu.');
+            }
+          }
+        } catch (err) {
+          if (err && err.name === 'AbortError') {
+            setStatus('Installation cancelled.');
+          } else {
+            console.warn('Install failed:', err);
+            setStatus('Installation isn’t available right now. Try your browser’s menu to install.');
+          }
+        } finally {
+          installBtn.disabled = false;
+        }
+      });
+    })();
+  </script>
+
