+/**
+ * Client-side interaction paint monitoring for The Daily Grind homepage.
+ *
+ * Measures how long it takes from a user interaction to the moment the
+ * resulting visual update is painted on screen, for:
+ *   - clicks inside the navigation bar          (region: "nav")
+ *   - the "Order Now" hero button               (region: "order-now")
+ *   - the "Seasonal Favorites" cards            (region: "seasonal-card")
+ *   - client-side view switches (soft navs)     (kind:   "soft-navigation")
+ *
+ * Tracked elements opt in with a `data-perf-region` attribute.
+ *
+ * Primary APIs (progressive enhancement, Chromium 151+):
+ *   - 'interaction-contentful-paint' — paints attributed to an interaction,
+ *     including async paints after fetch()/await/setTimeout.
+ *   - 'soft-navigation' — client-side route changes, with FCP/LCP.
+ * Fallback (Baseline Event Timing): 'event' entries give interaction to
+ * *next* paint, which is reported when the richer entries are unavailable.
+ *
+ * Reports are dispatched as a `perf:interaction-paint` CustomEvent on window,
+ * logged to the console, and — if `data-endpoint` is set on the script tag —
+ * batched and sent with navigator.sendBeacon when the page is hidden.
+ */
+
+(() => {
+'use strict';
+
+const scriptEl = document.currentScript || document.querySelector('script[data-perf-monitor]');
+const ENDPOINT = scriptEl?.dataset.endpoint || null;
+
+const supported = (type) =>
+  typeof PerformanceObserver !== 'undefined' &&
+  PerformanceObserver.supportedEntryTypes?.includes(type);
+
+const HAS_ICP = supported('interaction-contentful-paint');
+const HAS_SOFT_NAV = supported('soft-navigation');
+const HAS_EVENT_TIMING = supported('event');
+
+/** Max distance (ms) between a recorded input timestamp and an entry's startTime. */
+const MATCH_WINDOW_MS = 50;
+
+const round = (n) => (typeof n === 'number' ? Math.round(n * 10) / 10 : null);
+
+// ---------------------------------------------------------------------------
+// Attribution: which tracked region did an interaction start in?
+// ---------------------------------------------------------------------------
+
+function describeTarget(node) {
+  const el = node instanceof Element ? node : node?.parentElement;
+  const regionEl = el?.closest?.('[data-perf-region]');
+  if (!regionEl) return null;
+  const link = el.closest('a, button');
+  const card = el.closest('.card');
+  return {
+    region: regionEl.dataset.perfRegion,
+    label:
+      regionEl.dataset.perfLabel ||
+      card?.querySelector('h3')?.textContent.trim() ||
+      link?.textContent.trim() ||
+      null,
+    href: link?.getAttribute('href') || null,
+  };
+}
+
+/** interactionId -> attribution, filled from Event Timing entries. */
+const attributionById = new Map();
+/** Recent raw inputs (timestamp + attribution) for when Event Timing has no entry. */
+const recentInputs = [];
+
+function rememberInput(event) {
+  if (!event.isTrusted) return;
+  const info = describeTarget(event.target);
+  if (!info) return;
+  recentInputs.push({ time: event.timeStamp, info });
+  if (recentInputs.length > 20) recentInputs.shift();
+}
+
+// Capture phase so app handlers that stopPropagation can't hide the input.
+for (const type of ['pointerdown', 'keydown', 'click']) {
+  addEventListener(type, rememberInput, { capture: true, passive: true });
+}
+
+function attributionFor(interactionId, startTime) {
+  if (interactionId && attributionById.has(interactionId)) {
+    return attributionById.get(interactionId);
+  }
+  let best = null;
+  let bestDelta = MATCH_WINDOW_MS;
+  for (const input of recentInputs) {
+    const delta = Math.abs(input.time - startTime);
+    if (delta <= bestDelta) {
+      best = input.info;
+      bestDelta = delta;
+    }
+  }
+  return best;
+}
+
+// ---------------------------------------------------------------------------
+// Reporting
+// ---------------------------------------------------------------------------
+
+const queue = [];
+
+function report(record) {
+  queue.push(record);
+  console.debug('[perf]', record.kind, record.region ?? '', `${record.duration}ms`, record);
+  dispatchEvent(new CustomEvent('perf:interaction-paint', { detail: record }));
+}
+
+function flush() {
+  if (!queue.length) return;
+  const payload = JSON.stringify({ page: location.pathname, entries: queue.splice(0) });
+  if (ENDPOINT && navigator.sendBeacon) {
+    navigator.sendBeacon(ENDPOINT, new Blob([payload], { type: 'application/json' }));
+  }
+}
+
+// ---------------------------------------------------------------------------
+// 1. Event Timing — attribution source + next-paint fallback
+// ---------------------------------------------------------------------------
+
+/** interactionId -> pending next-paint record (fallback mode only). */
+const nextPaintById = new Map();
+
+if (HAS_EVENT_TIMING) {
+  new PerformanceObserver((list) => {
+    for (const entry of list.getEntries()) {
+      if (!entry.interactionId) continue;
+      const info = describeTarget(entry.target) || attributionFor(0, entry.startTime);
+      if (!info) continue;
+      if (!attributionById.has(entry.interactionId)) {
+        attributionById.set(entry.interactionId, info);
+      }
+
+      if (HAS_ICP) continue; // richer measurement comes from ICP entries.
+
+      // Fallback: keep the longest event per interaction (INP-style).
+      const prev = nextPaintById.get(entry.interactionId);
+      if (!prev || entry.duration > prev.duration) {
+        nextPaintById.set(entry.interactionId, {
+          kind: 'interaction-next-paint',
+          ...info,
+          interactionId: entry.interactionId,
+          eventType: entry.name,
+          startTime: round(entry.startTime),
+          duration: round(entry.duration),
+          inputDelay: round(entry.processingStart - entry.startTime),
+          processingTime: round(entry.processingEnd - entry.processingStart),
+          presentationDelay: round(entry.startTime + entry.duration - entry.processingEnd),
+        });
+      }
+    }
+    // Emit after the batch so all events of one interaction are merged.
+    if (!HAS_ICP) {
+      for (const record of nextPaintById.values()) report(record);
+      nextPaintById.clear();
+    }
+  }).observe({ type: 'event', buffered: true, durationThreshold: 16 });
+}
+
+// ---------------------------------------------------------------------------
+// 2. Interaction Contentful Paint — interaction to final visual update
+// ---------------------------------------------------------------------------
+
+/** interactionId -> latest (largest) ICP record, finalized on next interaction / hide. */
+const pendingIcp = new Map();
+
+function finalizeIcp() {
+  for (const record of pendingIcp.values()) report(record);
+  pendingIcp.clear();
+}
+
+if (HAS_ICP) {
+  new PerformanceObserver((list) => {
+    for (const entry of list.getEntries()) {
+      const info = attributionFor(entry.interactionId, entry.startTime);
+      if (!info) continue; // not one of the tracked UI regions.
+
+      // A new interaction means earlier ones are done painting.
+      for (const id of pendingIcp.keys()) {
+        if (id !== entry.interactionId) {
+          report(pendingIcp.get(id));
+          pendingIcp.delete(id);
+        }
+      }
+
+      const lcp = entry.largestContentfulPaint;
+      pendingIcp.set(entry.interactionId, {
+        kind: 'interaction-contentful-paint',
+        ...info,
+        interactionId: entry.interactionId,
+        startTime: round(entry.startTime),
+        // duration = presentationTime - startTime: interaction to on-screen paint.
+        duration: round(entry.duration),
+        paintedElement: lcp?.element ? lcp.element.tagName.toLowerCase() + (lcp.element.id ? `#${lcp.element.id}` : '') : null,
+        paintedSize: lcp?.size ?? null,
+      });
+    }
+  }).observe({ type: 'interaction-contentful-paint', buffered: true });
+}
+
+// ---------------------------------------------------------------------------
+// 3. Soft navigations — client-side view switches (FCP + LCP of the new view)
+// ---------------------------------------------------------------------------
+
+let activeSoftNav = null;
+let activeSoftNavLcp = null;
+
+function finalizeSoftNav() {
+  if (!activeSoftNav) return;
+  const info = attributionFor(activeSoftNav.interactionId, activeSoftNav.startTime);
+  report({
+    kind: 'soft-navigation',
+    ...(info || {}),
+    url: activeSoftNav.name,
+    navigationId: activeSoftNav.navigationId,
+    interactionId: activeSoftNav.interactionId,
+    startTime: round(activeSoftNav.startTime),
+    // duration = first contentful paint of the new view, from interaction start.
+    duration: round(activeSoftNav.duration),
+    fcp: round(activeSoftNav.duration),
+    lcp: round(activeSoftNavLcp?.duration ?? null),
+  });
+  activeSoftNav = null;
+  activeSoftNavLcp = null;
+}
+
+if (HAS_SOFT_NAV && HAS_ICP) {
+  new PerformanceObserver((list) => {
+    for (const entry of list.getEntries()) {
+      finalizeSoftNav();
+      activeSoftNav = entry;
+      // Include paints that happened before the URL was updated.
+      activeSoftNavLcp = entry.getLargestInteractionContentfulPaint?.() ?? null;
+    }
+  }).observe({ type: 'soft-navigation', buffered: true });
+
+  // Match by interactionId (not navigationId) to keep later, unrelated paints out.
+  new PerformanceObserver((list) => {
+    for (const entry of list.getEntries()) {
+      if (activeSoftNav && entry.interactionId === activeSoftNav.interactionId) {
+        activeSoftNavLcp = entry;
+      }
+    }
+  }).observe({ type: 'interaction-contentful-paint', buffered: true });
+}
+
+// ---------------------------------------------------------------------------
+// Finalize and send when the page is hidden (covers unload, tab switch, bfcache).
+// ---------------------------------------------------------------------------
+
+addEventListener('visibilitychange', () => {
+  if (document.visibilityState === 'hidden') {
+    finalizeIcp();
+    finalizeSoftNav();
+    flush();
+  }
+});
+addEventListener('pagehide', () => {
+  finalizeIcp();
+  finalizeSoftNav();
+  flush();
+});
+})();

