+/*
+ * Daily Grind client-side performance monitor
+ * --------------------------------------------
+ * Measures how long it takes from a user interaction until the resulting
+ * visual update has been painted, for:
+ *
+ *   - clicks on elements tagged with  data-perf-target="..."
+ *     (navigation bar, "Order Now" button, "Seasonal Favorites" cards)
+ *   - client-side view switches (history.pushState / replaceState, popstate,
+ *     hashchange, or an explicit DailyGrindPerf.viewSwitch() call)
+ *   - clicks that trigger a full page navigation (measured on the next page,
+ *     click -> first contentful paint, when that page also loads this script)
+ *
+ * Measurement strategy
+ *   - Clicks: the Event Timing API (PerformanceObserver type "event") gives the
+ *     browser's own input -> next-paint duration. It only reports entries
+ *     >= 16ms, so a requestAnimationFrame + MessageChannel "after next frame"
+ *     probe is used as a fallback / for browsers without Event Timing.
+ *   - View switches: after the switch, every DOM mutation schedules a new
+ *     after-paint probe; the switch is complete once the DOM has been quiet
+ *     for QUIET_MS. Duration = last painted frame - interaction start.
+ *
+ * Output
+ *   - performance.measure() entries named "dg:<type>:<target>" (DevTools)
+ *   - window.DailyGrindPerf.entries (in-memory buffer)
+ *   - "dailygrind:perf" CustomEvent on window for each metric
+ *   - console.debug when ?perfdebug is in the URL or
+ *     localStorage["dg-perf-debug"] === "1"
+ *   - navigator.sendBeacon(endpoint) batches if the script tag has
+ *     data-endpoint="/some/url" (flushed on hide / pagehide / batch size)
+ */
+(function () {
+  'use strict';
+
+  if (typeof window === 'undefined' || !window.performance || window.DailyGrindPerf) return;
+
+  var perf = window.performance;
+  var script = document.currentScript;
+  var ENDPOINT = script && script.getAttribute('data-endpoint');
+  var SAMPLE_RATE = parseFloat((script && script.getAttribute('data-sample-rate')) || '1');
+  var QUIET_MS = 300;          // DOM quiet period that ends a view switch
+  var VIEW_MAX_MS = 10000;     // hard cap for a view switch measurement
+  var CLICK_SETTLE_MS = 1000;  // time to wait for Event Timing entries
+  var LINK_WINDOW_MS = 1000;   // max gap between click and view switch to link them
+  var BATCH_SIZE = 10;
+  var NAV_KEY = 'dg-perf-pending-nav';
+
+  var sampled = Math.random() < (isNaN(SAMPLE_RATE) ? 1 : SAMPLE_RATE);
+  var debug = /[?&]perfdebug\b/.test(location.search);
+  try { debug = debug || localStorage.getItem('dg-perf-debug') === '1'; } catch (e) { /* storage blocked */ }
+
+  var entries = [];
+  var queue = [];
+  var pendingClicks = [];   // clicks awaiting their paint measurement
+  var lastClick = null;     // most recent tracked click (for view-switch linking)
+  var activeView = null;    // in-flight view switch measurement
+
+  // ---------------------------------------------------------------- helpers
+
+  function round(n) { return Math.round(n * 10) / 10; }
+
+  function pathOf(url) {
+    try {
+      var u = new URL(url, location.href);
+      return u.origin === location.origin ? u.pathname + u.hash : u.origin + u.pathname;
+    } catch (e) { return String(url); }
+  }
+
+  // Calls cb(timestamp) right after the next frame has been produced.
+  // rAF runs just before paint; a message posted from rAF is delivered in the
+  // task after the frame, which is a good approximation of "pixels painted".
+  function afterNextPaint(cb) {
+    requestAnimationFrame(function () {
+      var ch = new MessageChannel();
+      ch.port1.onmessage = function () { cb(perf.now()); };
+      ch.port2.postMessage(null);
+    });
+  }
+
+  function describeTarget(el) {
+    var label = el.getAttribute('data-perf-label') ||
+      (el.querySelector('h3') && el.querySelector('h3').textContent) ||
+      el.textContent || '';
+    return label.replace(/\s+/g, ' ').trim().slice(0, 60);
+  }
+
+  function report(metric) {
+    metric.page = location.pathname;
+    metric.ts = Date.now();
+    entries.push(metric);
+
+    try {
+      perf.measure('dg:' + metric.type + ':' + metric.target, {
+        start: metric.startTime,
+        duration: Math.max(0, metric.duration),
+        detail: metric
+      });
+    } catch (e) { /* older browsers: measure() without options */ }
+
+    try { window.dispatchEvent(new CustomEvent('dailygrind:perf', { detail: metric })); } catch (e) { /* ignore */ }
+    if (debug) console.debug('[DailyGrindPerf]', metric.type, metric.target, metric.duration + 'ms', metric);
+
+    if (ENDPOINT && sampled) {
+      queue.push(metric);
+      if (queue.length >= BATCH_SIZE) flush();
+    }
+  }
+
+  function flush() {
+    if (!ENDPOINT || !queue.length) return;
+    var body = JSON.stringify({ metrics: queue.splice(0, queue.length) });
+    var sent = false;
+    try { sent = navigator.sendBeacon && navigator.sendBeacon(ENDPOINT, new Blob([body], { type: 'application/json' })); } catch (e) { /* ignore */ }
+    if (!sent) {
+      try { fetch(ENDPOINT, { method: 'POST', body: body, keepalive: true, headers: { 'Content-Type': 'application/json' } }); } catch (e) { /* ignore */ }
+    }
+  }
