+// Barista order board: queued → brewing → ready.
+// Columns are rendered independently; a move only touches the source and
+// target columns (each isolated with CSS containment), never the whole board.
+
+const STORAGE_KEY = 'daily-grind-orders-v1';
+const STATUSES = ['queued', 'brewing', 'ready'];
+const LABELS = { queued: 'Queued', brewing: 'Brewing', ready: 'Ready' };
+const ACTIONS = {
+  queued: { prev: null, next: 'Start brewing →' },
+  brewing: { prev: '← Back to queue', next: 'Mark ready →' },
+  ready: { prev: '← Back to brewing', next: 'Picked up ✓' },
+};
+
+const board = document.getElementById('board');
+const form = document.getElementById('order-form');
+const live = document.getElementById('board-live');
+const template = document.getElementById('card-template');
