+  return [
+    { id: 1, customer: 'Sam', drink: 'Maple Oat Latte', size: 'Large', notes: 'Extra hot', status: 'queued', placed: now - 2 * min },
+    { id: 2, customer: 'Priya', drink: 'Cold Brew', size: 'Medium', notes: 'Light ice', status: 'queued', placed: now - 3 * min },
+    { id: 3, customer: 'Jordan', drink: 'Flat White', size: 'Small', notes: '', status: 'queued', placed: now - 4 * min },
+    { id: 4, customer: 'Mei', drink: 'Chai Latte', size: 'Medium', notes: 'Oat milk', status: 'brewing', placed: now - 6 * min },
+    { id: 5, customer: 'Alex', drink: 'Dark Roast Espresso', size: 'Small', notes: 'Double shot', status: 'brewing', placed: now - 7 * min },
+    { id: 6, customer: 'Rosa', drink: 'Mocha', size: 'Large', notes: 'No whip', status: 'ready', placed: now - 10 * min },
+  ];
+}
+
+function loadOrders() {
+  try {
+    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
+    if (Array.isArray(saved)) return saved.filter((o) => STATUSES.includes(o.status));
+  } catch {
