+  card.querySelector('.order-no').textContent = `#${order.id}`;
+  const time = card.querySelector('time');
+  time.dateTime = new Date(order.placed).toISOString();
+  time.textContent = timeFormat.format(order.placed);
+  card.querySelector('.drink').textContent = `${order.size} ${order.drink}`;
+  card.querySelector('.customer').textContent = `for ${order.customer}`;
+  const notes = card.querySelector('.notes');
+  notes.textContent = order.notes ?? '';
+  notes.hidden = !order.notes;
+  card
+    .querySelector('.handle')
+    .setAttribute('aria-label', `Move order #${order.id}, ${order.size} ${order.drink} for ${order.customer}`);
+  return card;
+}
