+  const { card, startX, startY, startScrollX, startScrollY, lastX, lastY } = drag;
+  const dx = lastX - startX + (scrollX - startScrollX);
+  const dy = lastY - startY + (scrollY - startScrollY);
+  card.style.translate = `${dx}px ${dy}px`;
+
+  // Several containers: hit-test for the column under the pointer.
+  const hit = document.elementFromPoint(lastX, lastY)?.closest('.board-column');
+  if (hit && board.contains(hit)) drag.targetList = hit.querySelector('.card-list');
+  updateDropSpot();
+}
+
+function updateDropSpot() {
+  const { card, targetList: list, lastY } = drag;
+  const rect = list.getBoundingClientRect();
+  const y = Math.min(Math.max(lastY - rect.top - list.clientTop + list.scrollTop, 0), list.scrollHeight);
+
+  // Compare with layout midpoints (ignores in-flight translate animations).
+  const siblings = cardsIn(list).filter((c) => c !== card);
+  const reference = siblings.find((c) => c.offsetTop + c.offsetHeight / 2 > y) ?? null;
+
+  const isNoop = list === card.parentElement && (reference === card || reference === nextCard(card));
+  if (isNoop) {
+    drag.reference = undefined;
+    marker.remove();
+    return;
+  }
+  drag.reference = reference;
+
+  const gap = parseFloat(getComputedStyle(list).rowGap) || 0;
+  const prev = reference ? prevCardExcluding(reference, card) : siblings.at(-1);
+  let markerY;
+  if (reference && prev) markerY = (prev.offsetTop + prev.offsetHeight + reference.offsetTop) / 2;
+  else if (reference) markerY = reference.offsetTop - gap / 2;
+  else if (prev) markerY = prev.offsetTop + prev.offsetHeight + gap / 2;
+  else markerY = list.clientHeight / 2;
+
+  if (marker.parentElement !== list) list.append(marker);
+  marker.style.setProperty('--drop-y', `${markerY}px`);
+}
+
+function prevCardExcluding(card, excluded) {
+  let el = prevCard(card);
+  while (el === excluded) el = prevCard(el);
+  return el;
+}
+
+function autoScroll(time) {
+  if (!drag) return;
+  const dt = drag.lastFrame ? Math.min(time - drag.lastFrame, 50) : 16;
+  drag.lastFrame = time;
+  const zone = Math.min(drag.card.offsetHeight, innerHeight / 3);
+  const navHeight = document.querySelector('nav')?.offsetHeight ?? 0;
+  const top = navHeight + zone;
+  const bottom = innerHeight - zone;
+  let depth = 0;
+  if (drag.lastY < top) depth = -(top - drag.lastY);
+  else if (drag.lastY > bottom) depth = drag.lastY - bottom;
+
+  if (depth) {
+    const speed = Math.min(Math.abs(depth) / zone, 2) * 0.9; // px per ms, capped
+    const before = scrollY;
+    scrollBy(0, Math.sign(depth) * speed * dt);
+    if (scrollY !== before) updateDrag();
+  }
+  drag.raf = requestAnimationFrame(autoScroll);
