+  const { card } = d;
+  card.getAnimations().forEach((a) => a.finish());
+  const releasedRect = card.getBoundingClientRect();
+  card.style.translate = '';
+
+  const moved = commit && d.reference !== undefined;
+  if (moved) {
+    moveCard(card, d.targetList, d.reference, { fromRect: releasedRect });
+    announce(`${cardName(card)} moved to ${positionMessage(card)}.`);
+  } else {
+    if (!commit) announce(`Move cancelled. ${cardName(card)} stays in ${positionMessage(card)}.`);
+    card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
+    flyBack(card, releasedRect);
+  }
+  d.handle.focus({ preventScroll: true });
+
+  // Keep the card raised until it settles; ignore if re-grabbed meanwhile.
+  const settle = () => {
+    if (drag?.card === card) return;
+    card.classList.remove('is-lifted');
+    d.column.classList.remove('is-drag-source');
+  };
+  const running = card.getAnimations();
+  if (running.length) Promise.all(running.map((a) => a.finished.catch(() => {}))).then(settle);
+  else settle();
+}
+
+function flyBack(card, fromRect) {
+  if (reducedMotion.matches) return;
+  const to = card.getBoundingClientRect();
+  const dx = fromRect.left - to.left;
+  const dy = fromRect.top - to.top;
+  if (dx || dy) {
+    card.animate({ translate: [`${dx}px ${dy}px`, '0 0'] }, { duration: 220, easing: 'cubic-bezier(.2,.7,.3,1)' });
+  }
+}
+
+// ---------- Keyboard grab–move–drop on the handle ----------
+
+board.addEventListener('keydown', (event) => {
+  if (drag && event.key === 'Escape') {
+    event.preventDefault();
+    endDrag(false);
+    return;
+  }
+  const handle = event.target.closest('.handle');
+  if (!handle) return;
+  const card = handle.closest('.card');
+
+  if (event.key === ' ' || event.key === 'Enter') {
+    event.preventDefault();
+    if (keyGrab) dropKeyGrab();
+    else startKeyGrab(handle, card);
+    return;
+  }
+  if (!keyGrab || keyGrab.card !== card) return;
+
+  if (event.key === 'Escape') {
+    event.preventDefault();
+    const { originList, originNext } = keyGrab;
+    const ref = originNext?.parentElement === originList ? originNext : null;
+    if (card.parentElement !== originList || nextCard(card) !== ref) moveCard(card, originList, ref);
+    endKeyGrab();
+    announce(`Move cancelled. ${cardName(card)} returned to ${positionMessage(card)}.`);
+    return;
+  }
+
+  const list = card.parentElement;
+  const status = statusOf(card);
+  let target = null;
+  let reference;
+
+  if (event.key === 'ArrowUp') {
+    const prev = prevCard(card);
+    if (prev) [target, reference] = [list, prev];
+  } else if (event.key === 'ArrowDown') {
+    const next = nextCard(card);
+    if (next) [target, reference] = [list, nextCard(next)];
+  } else if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
+    const rtl = getComputedStyle(board).direction === 'rtl';
+    const step = (event.key === 'ArrowRight') !== rtl ? 1 : -1;
+    const toStatus = STATUSES[STATUSES.indexOf(status) + step];
+    if (toStatus) {
+      target = columns[toStatus].list;
+      const index = cardsIn(list).indexOf(card);
+      reference = cardsIn(target)[index] ?? null; // keep roughly the same row
+    }
+  } else {
+    return;
+  }
+  event.preventDefault();
+  if (!target) return; // boundary: no valid destination that way
+  moveCard(card, target, reference);
+  announce(`${positionMessage(card)}.`);
+});
+
+function startKeyGrab(handle, card) {
+  card.getAnimations().forEach((a) => a.finish());
