+  );
+}
+
+function dropKeyGrab() {
+  const { card, originList, originNext } = keyGrab;
+  const changed = card.parentElement !== originList || nextCard(card) !== originNext;
+  endKeyGrab();
+  announce(changed ? `Dropped ${cardName(card)} in ${positionMessage(card)}.` : `Dropped ${cardName(card)}. Position unchanged.`);
+}
+
+function endKeyGrab() {
+  keyGrab.handle.setAttribute('aria-pressed', 'false');
+  keyGrab.card.classList.remove('is-grabbed');
+  keyGrab = null;
+}
+
+board.addEventListener('focusout', (event) => {
