+  dropKeyGrab();
+});
+
+// Reveal the whole card (not just the handle) when keyboard focus enters it.
+board.addEventListener('focusin', (event) => {
+  const card = event.target.closest('.card');
+  if (!card || !event.target.matches(':focus-visible') || card.getAnimations().length) return;
+  card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
+});
+
+// ---------- Init ----------
+
+const orders = loadOrders();
+nextId = orders.reduce((max, o) => Math.max(max, o.id), 0) + 1;
+for (const status of STATUSES) {
+  renderColumn(status, orders.filter((o) => o.status === status));
+}

