+        var order = state.columns[found.status].splice(found.index, 1)[0];
+        var target = state.columns[toStatus];
+        if (toIndex == null || toIndex > target.length) toIndex = target.length;
+        target.splice(toIndex, 0, order);
+        save();
+        // Only the affected columns re-render.
+        columns[found.status].render();
+        if (toStatus !== found.status) columns[toStatus].render();
+        if (refocus) {
+          var card = columns[toStatus].el.querySelector('.card[data-order-id="' + id + '"]');
+          if (card) card.focus();
+        }
+      }
+
+      function removeOrder(id) {
+        var found = findOrder(id);
+        if (!found) return;
+        state.columns[found.status].splice(found.index, 1);
+        save();
+        columns[found.status].render();
+      }
+
+      document.getElementById('order-form').addEventListener('submit', function (e) {
+        e.preventDefault();
+        var nameInput = document.getElementById('order-customer');
+        var customer = nameInput.value.trim();
+        if (!customer) return;
+        state.columns.queued.push({
+          id: state.nextId++,
+          customer: customer,
+          drink: document.getElementById('order-drink').value,
+          size: document.getElementById('order-size').value
+        });
+        save();
+        columns.queued.render();
+        nameInput.value = '';
+        nameInput.focus();
+      });
+
+      STATUSES.forEach(function (s) { columns[s].render(); });
+    })();
+  </script>
