+    const p = transform.transformPoint(new DOMPoint(x, y, 0, 1));
+    return p.w > 0 ? [p.x / p.w, p.y / p.w] : null;
+  };
+  const a = project(0, 0);
+  const b = project(width, 0);
+  const c = project(0, height);
+  if (!a || !b || !c) return false;
+  return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]) > 0;
