+
+// Column-major perspective matrix (DOMMatrix's 16-value form is column-major).
+function perspective(fovDeg, aspect, near, far) {
+  const f = 1 / Math.tan((fovDeg * Math.PI) / 360);
+  const nf = 1 / (near - far);
+  return new DOMMatrix([
+    f / aspect, 0, 0, 0,
+    0, f, 0, 0,
+    0, 0, (far + near) * nf, -1,
+    0, 0, 2 * far * near * nf, 0,
+  ]);
+}
+
+function normalize(v) {
+  const len = Math.hypot(...v);
+  return v.map((x) => x / len);
+}
+
+function labelTexture(gl, width, height, draw) {
+  const label = document.createElement('canvas');
+  label.width = width;
+  label.height = height;
+  draw(label.getContext('2d'), width, height);
+  const texture = gl.createTexture();
+  gl.bindTexture(gl.TEXTURE_2D, texture);
+  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, label);
+  gl.generateMipmap(gl.TEXTURE_2D);
+  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
+  return texture;
+}
+
+function kraft(ctx, w, h) {
+  ctx.fillStyle = '#c8a27a';
+  ctx.fillRect(0, 0, w, h);
+  // Subtle cardboard fibres.
+  ctx.globalAlpha = 0.08;
+  for (let i = 0; i < 400; i++) {
+    ctx.fillStyle = i % 2 ? '#5d4037' : '#fff3e0';
+    ctx.fillRect(Math.random() * w, Math.random() * h, 1 + Math.random() * 14, 1);
+  }
+  ctx.globalAlpha = 1;
+  ctx.strokeStyle = '#8d6e63';
+  ctx.lineWidth = 6;
+  ctx.strokeRect(3, 3, w - 6, h - 6);
+}
+
+function bean(ctx, x, y, r, angle) {
+  ctx.save();
+  ctx.translate(x, y);
+  ctx.rotate(angle);
+  ctx.fillStyle = '#4e342e';
+  ctx.beginPath();
+  ctx.ellipse(0, 0, r, r * 0.68, 0, 0, Math.PI * 2);
+  ctx.fill();
+  ctx.strokeStyle = '#c8a27a';
+  ctx.lineWidth = r * 0.14;
+  ctx.beginPath();
+  ctx.moveTo(-r * 0.8, 0);
+  ctx.quadraticCurveTo(0, r * 0.3, r * 0.8, 0);
+  ctx.stroke();
+  ctx.restore();
+}
+
+function drawBackLabel(ctx, w, h) {
+  kraft(ctx, w, h);
+  ctx.fillStyle = '#4e342e';
+  ctx.textAlign = 'center';
+  ctx.font = 'bold 44px "Segoe UI", sans-serif';
+  ctx.fillText('THE DAILY', w / 2, h * 0.36);
+  ctx.fillText('GRIND', w / 2, h * 0.36 + 52);
+  bean(ctx, w / 2 - 50, h * 0.6, 30, -0.4);
+  bean(ctx, w / 2 + 50, h * 0.6, 30, 0.4);
+  ctx.font = '24px "Segoe UI", sans-serif';
+  ctx.fillText('Ethically sourced · Locally roasted', w / 2, h * 0.8);
+}
+
+function drawSideLabel(ctx, w, h) {
+  kraft(ctx, w, h);
+  ctx.save();
+  ctx.translate(w / 2, h / 2);
+  ctx.rotate(-Math.PI / 2);
+  ctx.fillStyle = '#4e342e';
+  ctx.textAlign = 'center';
+  ctx.textBaseline = 'middle';
+  ctx.font = 'bold 40px "Segoe UI", sans-serif';
+  ctx.fillText('FRESH ROASTED', 0, -24);
+  ctx.font = '26px "Segoe UI", sans-serif';
+  ctx.fillText('SMALL BATCH', 0, 30);
+  ctx.restore();
+}

