+      const DEFAULT_STATE = Object.freeze({ category: 'all', sort: 'featured', reverse: false, group: false });
+
+      const currency = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+      const timeFmt = new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit', second: '2-digit' });
+
+      // ----- DOM references -----
+      const $ = (id) => document.getElementById(id);
+      const controls = $('menu-controls');
+      const categorySelect = $('category-select');
+      const sortSelect = $('sort-select');
+      const reverseToggle = $('reverse-toggle');
+      const groupToggle = $('group-toggle');
+      const menuList = $('menu-list');
+      const menuStatus = $('menu-status');
+      const milkSelect = $('milk-select');
+      const noteInput = $('order-note');
