+          category: VALID.category.includes(category) ? category : DEFAULT_STATE.category,
+          sort: VALID.sort.includes(sort) ? sort : DEFAULT_STATE.sort,
+          reverse: parseBool(params.get('reverse')),
+          group: parseBool(params.get('group')),
+        };
+      }
+
+      function stateFromControls() {
+        return {
+          category: VALID.category.includes(categorySelect.value) ? categorySelect.value : DEFAULT_STATE.category,
+          sort: VALID.sort.includes(sortSelect.value) ? sortSelect.value : DEFAULT_STATE.sort,
+          reverse: reverseToggle.checked,
+          group: groupToggle.checked,
+        };
+      }
+
+      function applyStateToControls(state) {
+        categorySelect.value = state.category;
+        sortSelect.value = state.sort;
+        reverseToggle.checked = state.reverse;
+        groupToggle.checked = state.group;
+      }
+
+      function writeStateToUrl(state) {
+        const url = new URL(window.location.href);
+        const params = url.searchParams;
+        params.set('category', state.category);
+        params.set('sort', state.sort);
+        params.set('reverse', state.reverse ? '1' : '0');
+        params.set('group', state.group ? '1' : '0');
+        if (url.href !== window.location.href) {
+          history.replaceState(history.state, '', url);
+        }
+      }
+
+      // ----- Derive the visible list without mutating MENU -----
+      function getVisibleItems(state) {
+        const filtered = state.category === 'all'
+          ? MENU.filter(() => true)
+          : MENU.filter((item) => item.category === state.category);
+        const comparators = {
+          featured: (a, b) => a.featured - b.featured,
+          'price-asc': (a, b) => a.price - b.price || a.featured - b.featured,
+          'price-desc': (a, b) => b.price - a.price || a.featured - b.featured,
