+        show(message, true);
+      };
+
+      const languageName = (code) => {
+        try {
+          return displayNames.of(code) || code;
+        } catch {
+          return code;
+        }
+      };
+
+      if (!('LanguageDetector' in self)) {
+        disableDetection('Language detection is not supported in this browser.');
+        return;
+      }
+
+      LanguageDetector.availability().then((availability) => {
+        if (availability === 'unavailable') {
+          disableDetection('Language detection is unavailable on this device.');
+        }
+      }).catch(() => {
+        disableDetection('Language detection is unavailable on this device.');
+      });
+
+      // create() must run inside the user gesture (the submit/click) in case
+      // the model still needs to be downloaded.
+      const getDetector = () => {
+        detectorPromise ??= LanguageDetector.create({
+          monitor(m) {
+            m.addEventListener('downloadprogress', (e) => {
+              show(`Downloading language model… ${Math.round(e.loaded * 100)}%`);
+            });
+          },
+        }).catch((err) => {
+          detectorPromise = null;
+          throw err;
+        });
+        return detectorPromise;
+      };
+
+      form.addEventListener('submit', async (event) => {
+        event.preventDefault();
+        const text = textarea.value.trim();
+        if (!text) {
+          show('Please enter a message first.', true);
+          textarea.focus();
+          return;
+        }
+
+        button.disabled = true;
+        show('Detecting…');
+        try {
+          const detector = await getDetector();
+          const [top] = await detector.detect(text);
+          if (!top || top.detectedLanguage === 'und') {
+            show('Sorry, we couldn\u2019t determine the language of this message.', true);
+          } else {
+            const pct = Math.round(top.confidence * 100);
+            const shortNote = text.split(/\s+/).length < 4
+              ? ' (short messages may be less accurate)'
+              : '';
+            show(`Detected language: ${languageName(top.detectedLanguage)} (${pct}% confidence)${shortNote}`);
+          }
+        } catch (err) {
+          console.error(err);
+          show('Language detection failed. Please try again.', true);
+        } finally {
+          button.disabled = false;
+        }
+      });
+    })();
+  </script>
+
 </body>

