+  <script>
+    (function () {
+      var form = document.getElementById('feedback-form');
+      var textarea = document.getElementById('feedback-message');
+      var button = document.getElementById('detect-btn');
+      var result = document.getElementById('detect-result');
+
+      var displayNames = null;
+      try { displayNames = new Intl.DisplayNames(['en'], { type: 'language' }); } catch (e) { }
+
+      function languageName(code) {
+        try { return (displayNames && displayNames.of(code)) || code; } catch (e) { return code; }
+      }
+
+      // Unique-script languages, checked by share of letters.
+      var SCRIPTS = [
+        ['ja', /[぀-ヿ]/g],
+        ['ko', /[가-힯ᄀ-ᇿ]/g],
+        ['zh', /[一-鿿]/g],
+        ['ar', /[؀-ۿ]/g],
+        ['he', /[֐-׿]/g],
+        ['el', /[Ͱ-Ͽ]/g],
+        ['th', /[฀-๿]/g],
+        ['hi', /[ऀ-ॿ]/g],
+        ['ru', /[Ѐ-ӿ]/g]
+      ];
+
+      // Common function words for Latin-script languages.
+      var STOPWORDS = {
+        en: 'the and is it to of was in that for with this you my very but not are have had great coffee good',
+        es: 'el la los las de que y en un una es muy por para con no pero fue mi su lo me gracias',
+        fr: 'le la les de des et est un une que pour pas avec très mais je mon ma nous vous était merci',
+        de: 'der die das und ist nicht ein eine ich mit sehr aber war für zu auf es sie wir danke',
+        it: 'il lo la gli le di che e è un una per non con molto ma era mi sono grazie',
+        pt: 'o a os as de que e é um uma para não com muito mas foi meu minha obrigado você',
+        nl: 'de het een en is van niet ik met zeer maar was voor op dat zijn heel bedankt',
+        sv: 'och är det att en ett inte jag med mycket men var för på som tack',
+        pl: 'i w nie jest to na że się z bardzo ale był dla jak dziękuję',
+        tr: 've bir bu çok için ile ama değil ben de da teşekkürler güzel'
+      };
+      var STOPSETS = {};
+      Object.keys(STOPWORDS).forEach(function (k) {
+        STOPSETS[k] = new Set(STOPWORDS[k].split(' '));
+      });
+
+      // Offline heuristic used when the browser has no built-in detector.
+      function heuristicDetect(text) {
+        var letters = (text.match(/\p{L}/gu) || []).length;
+        if (!letters) return null;
+
+        // Kana implies Japanese even when mixed with kanji.
+        var kana = (text.match(SCRIPTS[0][1]) || []).length;
+        if (kana > 0 && kana / letters > 0.1) return { code: 'ja', confidence: 0.9 };
+
+        for (var i = 1; i < SCRIPTS.length; i++) {
+          var count = (text.match(SCRIPTS[i][1]) || []).length;
+          if (count / letters > 0.5) {
+            var code = SCRIPTS[i][0];
+            if (code === 'ru' && /[іїєґ]/i.test(text)) code = 'uk';
+            if (code === 'ar' && /[پچژگ]/.test(text)) code = 'fa';
+            return { code: code, confidence: 0.85 };
+          }
+        }
+
+        var words = text.toLowerCase().match(/\p{L}+/gu) || [];
+        var best = null, bestScore = 0, total = 0;
+        Object.keys(STOPSETS).forEach(function (lang) {
+          var score = 0;
+          words.forEach(function (w) { if (STOPSETS[lang].has(w)) score++; });
+          total += score;
+          if (score > bestScore) { bestScore = score; best = lang; }
+        });
+        if (!best) return null;
+        return { code: best, confidence: bestScore / Math.max(total, 1) };
+      }
+
+      var detectorPromise = null;
+      function getBuiltInDetector() {
+        if (!('LanguageDetector' in self)) return Promise.resolve(null);
+        if (!detectorPromise) {
+          detectorPromise = LanguageDetector.availability()
+            .then(function (a) { return a === 'unavailable' ? null : LanguageDetector.create(); })
+            .catch(function () { return null; });
+        }
+        return detectorPromise;
+      }
+
+      function detect(text) {
