+          if (!detector) return heuristicDetect(text);
+          return detector.detect(text).then(function (results) {
+            var top = results && results[0];
+            if (!top || top.detectedLanguage === 'und') return heuristicDetect(text);
+            return { code: top.detectedLanguage, confidence: top.confidence };
+          });
+        }).catch(function () { return heuristicDetect(text); });
+      }
+
+      function show(message, isError, lang) {
+        result.textContent = '';
+        result.classList.toggle('error', !!isError);
+        if (!lang) { result.textContent = message; return; }
+        result.append('Detected language: ');
+        var strong = document.createElement('strong');
+        strong.textContent = languageName(lang.code);
+        result.append(strong);
+        result.append(' (' + lang.code + ', ' + Math.round(lang.confidence * 100) + '% confidence)');
+      }
+
+      form.addEventListener('submit', function (event) {
+        event.preventDefault();
+        var text = textarea.value.trim();
+        if (!text) {
+          show('Please enter a message first.', true);
+          textarea.focus();
+          return;
+        }
+        button.disabled = true;
+        show('Detecting…');
+        detect(text).then(function (lang) {
+          if (lang) show('', false, lang);
+          else show("Sorry, we couldn't identify the language of this message.", true);
+        }).finally(function () {
+          button.disabled = false;
+        });
+      });
