diff --git a/barista-ai.js b/barista-ai.js
new file mode 100644
--- a/barista-ai.js
+++ b/barista-ai.js
@@ -0,0 +1,423 @@
+// On-device AI features for The Daily Grind, powered by the built-in Prompt API (LanguageModel).
+// Model output is always rendered via textContent — it is untrusted and must never be parsed as HTML.
+
+const MODEL_OPTIONS = {
+  expectedInputs: [{ type: 'text', languages: ['en'] }],
+  expectedOutputs: [{ type: 'text', languages: ['en'] }],
+};
+
+const BARISTA_SYSTEM_PROMPT = `You are a friendly, concise barista at The Daily Grind coffee shop.
+You only answer questions about these two drinks:
+
+Maple Oat Latte: espresso with creamy steamed oat milk and a hint of pure Vermont maple syrup.
+Dairy-free (oat milk), vegan, contains oats. Available hot or iced. Sizes 12oz, 16oz, 20oz.
+Medium caffeine (double shot, ~130mg in 16oz). Seasonal item.
+
+Cold Brew: our house coffee steeped in cold water for 18 hours for maximum smoothness and low acidity.
+Served over ice, black by default; milk, oat milk, or maple syrup can be added. High caffeine (~200mg in 16oz).
+Dairy-free and vegan when served black. Available year-round.
+
+If asked about anything else, politely say you can only help with the Maple Oat Latte and Cold Brew.
+Keep answers under 120 words. Use plain text, no markdown.`;
+
+const SENTIMENT_SYSTEM_PROMPT = `You analyze customer feedback for a coffee shop.
+Return a sentiment score from -1 (very negative) to 1 (very positive) and a single category.`;
+
+const SENTIMENT_SCHEMA = {
+  type: 'object',
+  properties: {
+    score: { type: 'number', minimum: -1, maximum: 1 },
+    category: { type: 'string', enum: ['positive', 'neutral', 'negative', 'mixed'] },
+  },
+  required: ['score', 'category'],
+  additionalProperties: false,
+};
+
+const MAX_BRANCHES = 3;
+
+const $ = (id) => document.getElementById(id);
+
+const statusBox = $('model-status');
+const statusText = $('model-status-text');
+const progressEl = $('model-progress');
+const progressLabel = $('model-progress-label');
+
+// ---------- Session registry & cleanup ----------
+
+const state = {
+  baristaBase: null, // system prompt only; cloned for new conversations/branches
+  baristaChat: null, // the active conversation
+  sentimentBase: null, // system prompt only; cloned per analysis
+  branches: [], // { id, label, session }
+  nextBranchId: 1,
+  pending: new Map(), // dedupe concurrent create() calls
+};
+
+const activeControllers = new Set();
+
+function destroyAllSessions() {
+  for (const controller of activeControllers) controller.abort();
+  activeControllers.clear();
+  for (const { session } of state.branches) session.destroy();
+  state.branches = [];
+  state.baristaChat?.destroy();
+  state.baristaBase?.destroy();
+  state.sentimentBase?.destroy();
+  state.baristaChat = state.baristaBase = state.sentimentBase = null;
+  state.pending.clear();
+}
+
+// Free device memory when leaving. If restored from bfcache, sessions are lazily recreated.
+addEventListener('pagehide', destroyAllSessions);
+addEventListener('pageshow', (e) => {
+  if (e.persisted) {
+    renderBranches();
+    updateMainContext();
+  }
+});
+
+// ---------- Availability & creation ----------
+
+function setStatus(message) {
+  statusBox.hidden = false;
+  statusText.textContent = message;
+}
+
+async function checkAvailability() {
+  if (!('LanguageModel' in self)) return 'unsupported';
+  try {
+    return await LanguageModel.availability(MODEL_OPTIONS);
+  } catch {
+    return 'unavailable';
+  }
+}
+
+function unavailableMessage(availability) {
+  return availability === 'unsupported'
+    ? 'On-device AI is not supported in this browser. Try a recent version of Chrome on desktop.'
+    : 'The on-device AI model is not available on this device.';
+}
+
+/**
+ * Creates a session after verifying availability. Shows download progress when needed.
+ * Must be called from a user gesture if the model still needs downloading.
+ */
+async function createSession(systemPrompt) {
+  const availability = await checkAvailability();
+  if (availability === 'unsupported' || availability === 'unavailable') {
+    throw new Error(unavailableMessage(availability));
+  }
+
+  const needsDownload = availability !== 'available';
+  if (needsDownload) {
+    setStatus('Downloading the on-device AI model…');
+    progressEl.hidden = progressLabel.hidden = false;
+    progressEl.value = 0;
+  }
+
+  const session = await LanguageModel.create({
+    ...MODEL_OPTIONS,
+    initialPrompts: [{ role: 'system', content: systemPrompt }],
+    monitor(m) {
+      m.addEventListener('downloadprogress', (e) => {
+        progressEl.value = e.loaded;
+        progressEl.setAttribute('aria-valuetext', `${Math.round(e.loaded * 100)}%`);
+      });
+    },
+  });
+
+  if (needsDownload) {
+    progressEl.hidden = progressLabel.hidden = true;
+    setStatus('On-device AI model ready.');
+  }
+  return session;
+}
+
+// Lazily get (or create once) a named base session.
+function getBase(key, systemPrompt) {
+  if (state[key]) return Promise.resolve(state[key]);
+  if (!state.pending.has(key)) {
+    const p = createSession(systemPrompt)
+      .then((session) => {
+        state[key] = session;
+        return session;
+      })
+      .finally(() => state.pending.delete(key));
+    state.pending.set(key, p);
+  }
+  return state.pending.get(key);
+}
+
+function watchOverflow(session, onOverflow) {
+  // Event name varies across implementations.
+  session.addEventListener?.('contextoverflow', onOverflow);
+  session.addEventListener?.('quotaoverflow', onOverflow);
+}
+
+async function getBaristaChat() {
+  if (state.baristaChat) return state.baristaChat;
+  const base = await getBase('baristaBase', BARISTA_SYSTEM_PROMPT);
+  // Clone the clean base so the base stays reusable for future conversations/branches.
+  state.baristaChat = await base.clone();
+  watchOverflow(state.baristaChat, () => {
+    $('main-context').textContent = 'The conversation is long; the oldest messages are being dropped.';
+  });
+  return state.baristaChat;
+}
+
+// Pre-warm only when the model is already downloaded (download needs a user gesture).
+let prewarmed = false;
+async function prewarm() {
+  if (prewarmed) return;
+  prewarmed = true;
+  if ((await checkAvailability()) !== 'available') return;
+  getBase('baristaBase', BARISTA_SYSTEM_PROMPT).catch(() => {});
+  getBase('sentimentBase', SENTIMENT_SYSTEM_PROMPT).catch(() => {});
+}
+for (const id of ['barista-question', 'feedback-text']) {
+  $(id).addEventListener('focus', prewarm, { once: true });
+}
+
+// ---------- Streaming helper ----------
+
+function contextInfo(session) {
+  const used = session.contextUsage ?? session.inputUsage;
+  const total = session.contextWindow ?? session.inputQuota;
+  return { used, total };
+}
+
+async function streamInto(session, prompt, outputEl, signal) {
+  outputEl.textContent = '';
+  outputEl.setAttribute('aria-busy', 'true');
+  try {
+    const stream = session.promptStreaming(prompt, { signal });
+    for await (const chunk of stream) outputEl.append(chunk);
+    if (!outputEl.textContent.trim()) outputEl.textContent = 'No answer was returned. Please try rephrasing.';
+  } finally {
+    outputEl.setAttribute('aria-busy', 'false');
+  }
+}
+
+function showError(outputEl, err) {
+  if (err?.name === 'AbortError') {
+    outputEl.append(' (stopped)');
+    return;
+  }
+  const message =
+    err?.name === 'NotAllowedError'
+      ? 'Please click the button again to allow the AI model to download.'
+      : err?.message || 'Something went wrong. Please try again.';
+  outputEl.textContent = `Sorry — ${message}`;
+  outputEl.setAttribute('aria-busy', 'false');
+}
+
+// ---------- Ask the Barista ----------
+
+const baristaForm = $('barista-form');
+const askBtn = $('ask-the-barista');
+const stopBtn = $('barista-stop');
+const answerEl = $('barista-answer');
+let baristaController = null;
+
+baristaForm.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  const question = $('barista-question').value.trim();
+  if (!question) return;
+
+  askBtn.disabled = true;
+  answerEl.setAttribute('aria-busy', 'true');
+  answerEl.textContent = 'Checking the on-device model…';
+  baristaController = new AbortController();
+  activeControllers.add(baristaController);
+
+  try {
+    const session = await getBaristaChat();
+    stopBtn.hidden = false;
+    await streamInto(session, question, answerEl, baristaController.signal);
+    updateMainContext();
+  } catch (err) {
+    showError(answerEl, err);
+  } finally {
+    activeControllers.delete(baristaController);
+    baristaController = null;
+    const hadFocus = document.activeElement === stopBtn;
+    stopBtn.hidden = true;
+    askBtn.disabled = false;
+    if (hadFocus) askBtn.focus();
+  }
+});
+
+stopBtn.addEventListener('click', () => baristaController?.abort());
+
+// ---------- Customer Feedback Analyzer ----------
+
+const sentimentBtn = $('sentiment-btn');
+const sentimentResult = $('sentiment-result');
+
+sentimentBtn.addEventListener('click', async () => {
+  const feedback = $('feedback-text').value.trim();
+  if (!feedback) {
+    sentimentResult.textContent = 'Please enter some customer feedback to analyze.';
+    $('feedback-text').focus();
+    return;
+  }
+
+  sentimentBtn.disabled = true;
+  sentimentResult.setAttribute('aria-busy', 'true');
+  sentimentResult.textContent = 'Analyzing…';
+  let task = null;
+  const controller = new AbortController();
+  activeControllers.add(controller);
+
+  try {
+    const base = await getBase('sentimentBase', SENTIMENT_SYSTEM_PROMPT);
+    // Clone per analysis so unrelated reviews never share context; destroy right after.
+    task = await base.clone();
+    const raw = await task.prompt(`Customer feedback:\n"""${feedback}"""`, {
+      responseConstraint: SENTIMENT_SCHEMA,
+      signal: controller.signal,
+    });
+    const data = JSON.parse(raw);
+    sentimentResult.textContent = JSON.stringify(
+      { score: Math.round(data.score * 100) / 100, category: data.category },
+      null,
+      2,
+    );
+  } catch (err) {
+    if (err instanceof SyntaxError) {
+      sentimentResult.textContent = 'Sorry — the model returned an unexpected response. Please try again.';
+    } else {
+      showError(sentimentResult, err);
+    }
+  } finally {
+    task?.destroy();
+    activeControllers.delete(controller);
+    sentimentResult.setAttribute('aria-busy', 'false');
+    sentimentBtn.disabled = false;
+  }
+});
+
+// ---------- Conversation Branching ----------
+
+const cloneBtn = $('clone-btn');
+const branchList = $('branch-list');
+const branchForm = $('branch-form');
+const branchSelect = $('branch-select');
+const branchAnswer = $('branch-answer');
+$('max-branches').textContent = String(MAX_BRANCHES);
+
+function formatUsage(session) {
+  const { used, total } = contextInfo(session);
+  if (typeof used !== 'number' || typeof total !== 'number' || !total) return null;
+  return { used, total, text: `${used.toLocaleString()} / ${total.toLocaleString()} tokens used` };
+}
+
+function updateMainContext() {
+  const el = $('main-context');
+  const usage = state.baristaChat && formatUsage(state.baristaChat);
+  el.textContent = usage ? `Active conversation: ${usage.text}` : '';
+}
+
+function destroyBranch(id) {
+  const idx = state.branches.findIndex((b) => b.id === id);
+  if (idx === -1) return;
+  const [branch] = state.branches.splice(idx, 1);
+  branch.session.destroy();
+}
+
+function renderBranches() {
+  branchList.replaceChildren();
+  const previous = branchSelect.value;
+  branchSelect.replaceChildren();
+
+  for (const branch of state.branches) {
+    const li = document.createElement('li');
+    const title = document.createElement('strong');
+    title.textContent = branch.label;
+    li.append(title);
+
+    const usage = formatUsage(branch.session);
+    if (usage) {
+      const meterId = `branch-meter-${branch.id}`;
+      const label = document.createElement('label');
+      label.htmlFor = meterId;
+      label.textContent = `Context: ${usage.text}`;
+      const meter = document.createElement('meter');
+      meter.id = meterId;
+      meter.min = 0;
+      meter.max = usage.total;
+      meter.low = usage.total * 0.6;
+      meter.high = usage.total * 0.85;
+      meter.optimum = 0;
+      meter.value = usage.used;
+      li.append(label, meter);
+    }
+
+    const discard = document.createElement('button');
+    discard.type = 'button';
+    discard.className = 'secondary';
+    discard.textContent = `Discard ${branch.label}`;
+    discard.addEventListener('click', () => {
+      destroyBranch(branch.id);
+      renderBranches();
+      cloneBtn.focus();
+    });
+    li.append(discard);
+    branchList.append(li);
+
+    branchSelect.append(new Option(branch.label, String(branch.id)));
+  }
+
+  if (state.branches.some((b) => String(b.id) === previous)) branchSelect.value = previous;
+  branchForm.hidden = state.branches.length === 0;
+}
+
+cloneBtn.addEventListener('click', async () => {
+  cloneBtn.disabled = true;
+  branchAnswer.textContent = '';
+  try {
+    // Branch from the active conversation (or a fresh one from the base if none yet).
+    const source = await getBaristaChat();
+    const session = await source.clone();
+    const id = state.nextBranchId++;
+    const branch = { id, label: `Branch ${id}`, session };
+    watchOverflow(session, renderBranches);
+    state.branches.push(branch);
+
+    // Clean up the oldest branches beyond the limit to free device memory.
+    while (state.branches.length > MAX_BRANCHES) {
+      state.branches.shift().session.destroy();
+    }
+
+    renderBranches();
+    branchSelect.value = String(id);
+    updateMainContext();
+  } catch (err) {
+    showError(branchAnswer, err);
+  } finally {
+    cloneBtn.disabled = false;
+  }
+});
+
+branchForm.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  const id = Number(branchSelect.value);
+  const branch = state.branches.find((b) => b.id === id);
+  const question = $('branch-question').value.trim();
+  if (!branch || !question) return;
+
+  const askBranchBtn = $('branch-ask');
+  askBranchBtn.disabled = true;
+  const controller = new AbortController();
+  activeControllers.add(controller);
+  try {
+    await streamInto(branch.session, question, branchAnswer, controller.signal);
+    branchAnswer.prepend(`${branch.label}: `);
+  } catch (err) {
+    showError(branchAnswer, err);
+  } finally {
+    activeControllers.delete(controller);
+    askBranchBtn.disabled = false;
+    renderBranches();
+  }
+});

