--- a/ai.js
+++ b/ai.js
@@ -0,0 +1,621 @@
+// On-device AI features for The Daily Grind, built on the browser's built-in
+// Prompt API (`LanguageModel`, e.g. Gemini Nano in Chrome).
+//
+// Practices followed:
+//  - Feature-detect and call `LanguageModel.availability()` before `create()`.
+//  - Declare expected input/output modalities + languages (same options for
+//    availability() and create(), so the answer is accurate).
+//  - Surface model download progress via the `monitor` option.
+//  - Create sessions lazily from a user gesture, reuse a primed "base" session and
+//    `clone()` it per task so the system prompt isn't re-processed and context
+//    doesn't pile up between unrelated requests.
+//  - Make every operation cancellable with AbortController.
+//  - Track context usage, react to context overflow, and `destroy()` sessions as
+//    soon as they're no longer needed (and on page hide).
+
+const LM = globalThis.LanguageModel;
+
+const MODEL_OPTIONS = {
+  expectedInputs: [{ type: 'text', languages: ['en'] }],
+  expectedOutputs: [{ type: 'text', languages: ['en'] }],
+};
+
+const MENU_FACTS = `
+Menu facts (the only drinks you may discuss in detail):
+- Maple Oat Latte (seasonal): double shot of our house espresso, steamed oat milk,
+  and real Vermont maple syrup. Lightly sweet, nutty, cozy. Dairy-free and vegan.
+  Sizes 12oz / 16oz / 20oz. About 130 mg caffeine in a 16oz. Available hot or iced.
+  Can be made less sweet or with an extra shot.
+- Cold Brew: coarse-ground single-origin beans steeped in cold water for 18 hours,
+  then filtered. Very smooth, low acidity, chocolatey notes. Served over ice, black
+  by default; milk or maple syrup can be added. About 200 mg caffeine in a 16oz.
+`.trim();
+
+// ---------------------------------------------------------------------------
+// Shared helpers
+// ---------------------------------------------------------------------------
+
+const $ = (id) => document.getElementById(id);
+
+function setStatus(el, message, isError = false) {
+  el.textContent = message;
+  el.classList.toggle('error', isError);
+}
+
+/** Context usage, tolerant of both the current and older property names. */
+function usageOf(session) {
+  const used = session.contextUsage ?? session.inputUsage ?? 0;
+  const total = session.contextWindow ?? session.inputQuota ?? 0;
+  return { used, total, ratio: total ? used / total : 0 };
+}
+
+function onOverflow(session, handler) {
+  // `contextoverflow` is the current name; `quotaoverflow` was used previously.
+  session.addEventListener?.('contextoverflow', handler);
+  session.addEventListener?.('quotaoverflow', handler);
+}
+
+function isAbort(err) {
+  return err?.name === 'AbortError';
+}
+
+/**
+ * Check availability, then create a session while reporting download progress.
+ * Throws with a user-friendly message if the model can't be used.
+ */
+async function createSession(createOptions, { progressEl, statusEl, signal } = {}) {
+  if (!LM) {
+    throw new Error(
+      'Built-in AI is not supported in this browser. Try a recent version of Chrome with on-device AI enabled.'
+    );
+  }
+
+  const availability = await LM.availability(MODEL_OPTIONS);
+  if (availability === 'unavailable') {
+    throw new Error('The on-device model is unavailable on this device.');
+  }
+
+  if (availability === 'downloadable' || availability === 'downloading') {
+    setStatus(statusEl, 'Downloading the on-device model… this only happens once.');
+    if (progressEl) {
+      progressEl.hidden = false;
+      progressEl.removeAttribute('value'); // indeterminate until first event
+    }
+  } else {
+    setStatus(statusEl, 'Preparing the barista…');
+  }
+
+  try {
+    return await LM.create({
+      ...MODEL_OPTIONS,
+      ...createOptions,
+      signal,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => {
+          if (!progressEl) return;
+          progressEl.hidden = false;
+          progressEl.value = e.loaded; // 0..1
+          setStatus(statusEl, `Downloading model… ${Math.round(e.loaded * 100)}%`);
+          if (e.loaded >= 1) setStatus(statusEl, 'Download complete. Loading model…');
+        });
+      },
+    });
+  } finally {
+    if (progressEl) progressEl.hidden = true;
+  }
+}
+
+/**
+ * Lazily create one primed base session and share the in-flight promise so
+ * concurrent clicks don't create duplicates.
+ */
+function lazySession(buildOptions) {
+  let promise = null;
+  return {
+    get(ui) {
+      if (!promise) {
+        promise = createSession(buildOptions(), ui);
+        promise.catch(() => {
+          promise = null; // allow retry after failures
+        });
+      }
+      return promise;
+    },
+    async destroy() {
+      const p = promise;
+      promise = null;
+      if (p) {
+        try {
+          (await p).destroy();
+        } catch {
+          /* creation failed or already destroyed */
+        }
+      }
+    },
+  };
+}
+
+// Track every live controller/session so we can clean up on page hide.
+const liveControllers = new Set();
+function trackController() {
+  const c = new AbortController();
+  liveControllers.add(c);
+  return {
+    controller: c,
+    release: () => liveControllers.delete(c),
+  };
+}
+
+// ---------------------------------------------------------------------------
+// 1. Ask the Barista — streaming answers
+// ---------------------------------------------------------------------------
+
+const baristaBase = lazySession(() => ({
+  initialPrompts: [
+    {
+      role: 'system',
+      content: `You are a friendly, concise barista at The Daily Grind coffee shop.
+Answer customer questions ONLY about the Maple Oat Latte and the Cold Brew using the facts below.
+If asked about anything else, politely say you can only help with those two drinks.
+Keep answers under 120 words. Never invent prices.
+
+${MENU_FACTS}`,
+    },
+  ],
+}));
+
+{
+  const askBtn = $('ask-the-barista');
+  const stopBtn = $('barista-stop');
+  const questionEl = $('barista-question');
+  const answerEl = $('barista-answer');
+  const statusEl = $('barista-status');
+  const progressEl = $('barista-progress');
+  let current = null;
+
+  // Reflect availability up front (no download is triggered by this call).
+  (async () => {
+    if (!LM) {
+      setStatus(statusEl, 'Built-in AI is not supported in this browser.', true);
+      return;
+    }
+    try {
+      const a = await LM.availability(MODEL_OPTIONS);
+      const messages = {
+        available: 'On-device barista is ready.',
+        downloadable: 'The on-device model will download on first use.',
+        downloading: 'The on-device model is downloading…',
+        unavailable: 'The on-device model is unavailable on this device.',
+      };
+      setStatus(statusEl, messages[a] ?? '', a === 'unavailable');
+      if (a === 'unavailable') askBtn.disabled = true;
+    } catch {
+      /* ignore — we'll re-check on click */
+    }
+  })();
+
+  stopBtn.addEventListener('click', () => current?.controller.abort());
+
+  askBtn.addEventListener('click', async () => {
+    const question = questionEl.value.trim();
+    if (!question) {
+      setStatus(statusEl, 'Please type a question first.', true);
+      questionEl.focus();
+      return;
+    }
+
+    current?.controller.abort();
+    const tracked = trackController();
+    current = tracked;
+    const { signal } = tracked.controller;
+
+    askBtn.disabled = true;
+    stopBtn.hidden = false;
+    answerEl.textContent = '';
+    let session = null;
+
+    try {
+      const base = await baristaBase.get({ progressEl, statusEl, signal });
+      // Clone the primed base so each question starts fresh without
+      // re-processing the system prompt or accumulating unrelated history.
+      session = await base.clone({ signal });
+
+      setStatus(statusEl, 'The barista is thinking…');
+      const stream = session.promptStreaming(question, { signal });
+      for await (const chunk of stream) {
+        answerEl.append(chunk); // chunks are incremental deltas
+      }
+      setStatus(statusEl, 'Enjoy! Ask another question anytime.');
+    } catch (err) {
+      if (isAbort(err)) {
+        setStatus(statusEl, 'Stopped.');
+      } else {
+        console.error(err);
+        setStatus(statusEl, err.message || 'Something went wrong.', true);
+      }
+    } finally {
+      session?.destroy();
+      tracked.release();
+      if (current === tracked) current = null;
+      askBtn.disabled = false;
+      stopBtn.hidden = true;
+    }
+  });
+}
+
+// ---------------------------------------------------------------------------
+// 2. Customer Feedback Analyzer — structured JSON output
+// ---------------------------------------------------------------------------
+
+const SENTIMENT_SCHEMA = {
+  type: 'object',
+  properties: {
+    score: {
+      type: 'number',
+      minimum: -1,
+      maximum: 1,
+      description: 'Sentiment from -1 (very negative) to 1 (very positive).',
+    },
+    category: {
+      type: 'string',
+      enum: ['positive', 'neutral', 'negative'],
+    },
+  },
+  required: ['score', 'category'],
+  additionalProperties: false,
+};
+
+const sentimentBase = lazySession(() => ({
+  initialPrompts: [
+    {
+      role: 'system',
+      content:
+        'You analyze customer feedback for a coffee shop. For each review, return a sentiment ' +
+        'score between -1 and 1 and a category of "positive", "neutral", or "negative".',
+    },
+  ],
+}));
+
+{
+  const btn = $('sentiment-btn');
+  const inputEl = $('feedback-input');
+  const resultEl = $('sentiment-result');
+  const statusEl = $('sentiment-status');
+  const progressEl = $('sentiment-progress');
+  let current = null;
+
+  btn.addEventListener('click', async () => {
+    const feedback = inputEl.value.trim();
+    if (!feedback) {
+      setStatus(statusEl, 'Please paste some customer feedback first.', true);
+      inputEl.focus();
+      return;
+    }
+
+    current?.controller.abort();
+    const tracked = trackController();
+    current = tracked;
+    const { signal } = tracked.controller;
+
+    btn.disabled = true;
+    resultEl.textContent = '';
+    let session = null;
+
+    try {
+      const base = await sentimentBase.get({ progressEl, statusEl, signal });
+      session = await base.clone({ signal }); // independent, disposable analysis
+      setStatus(statusEl, 'Analyzing…');
+
+      const raw = await session.prompt(`Review:\n"""${feedback}"""`, {
+        responseConstraint: SENTIMENT_SCHEMA,
+        signal,
+      });
+
+      const parsed = JSON.parse(raw);
+      const score = Math.max(-1, Math.min(1, Number(parsed.score)));
+      const category = ['positive', 'neutral', 'negative'].includes(parsed.category)
+        ? parsed.category
+        : 'neutral';
+      const result = { score: Number(score.toFixed(2)), category };
+
+      renderSentiment(resultEl, result);
+      setStatus(statusEl, 'Analysis complete.');
+    } catch (err) {
+      if (isAbort(err)) {
+        setStatus(statusEl, 'Cancelled.');
+      } else {
+        console.error(err);
+        const msg =
+          err instanceof SyntaxError ? 'The model returned an unexpected format. Please try again.' : err.message;
+        setStatus(statusEl, msg || 'Something went wrong.', true);
+      }
+    } finally {
+      session?.destroy();
+      tracked.release();
+      if (current === tracked) current = null;
+      btn.disabled = false;
+    }
+  });
+
+  function renderSentiment(el, result) {
+    el.replaceChildren();
+    const row = document.createElement('div');
+    row.className = 'sentiment-result';
+
+    const badge = document.createElement('span');
+    badge.className = `badge ${result.category}`;
+    badge.textContent = result.category;
+
+    const score = document.createElement('strong');
+    score.textContent = `Score: ${result.score}`;
+
+    row.append(badge, score);
+
+    const pre = document.createElement('pre');
+    pre.textContent = JSON.stringify(result, null, 2);
+
+    el.append(row, pre);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// 3. Conversation Branching — clone sessions, track context, clean up
+// ---------------------------------------------------------------------------
+
+// Cleanup hook for the branching section, used by the global pagehide handler.
+const branching = {};
+
+{
+  const MAX_BRANCHES = 4; // keep memory bounded; oldest inactive branches are destroyed
+  const NEAR_FULL = 0.9;
+
+  const sendBtn = $('branch-send');
+  const cloneBtn = $('clone-btn');
+  const resetBtn = $('branch-reset');
+  const inputEl = $('branch-input');
+  const listEl = $('branch-list');
+  const outputEl = $('branch-output');
+  const statusEl = $('branch-status');
+  const progressEl = $('branch-progress');
+
+  /** @type {{id:number,name:string,session:any,transcript:string,lastUsed:number,overflowed:boolean}[]} */
+  let branches = [];
+  let activeId = null;
+  let nextId = 1;
+  let busy = null; // tracked controller for in-flight work
+  let rootPromise = null;
+
+  const active = () => branches.find((b) => b.id === activeId) ?? null;
+
+  function addBranch(session, name, transcript = '') {
+    const branch = {
+      id: nextId++,
+      name,
+      session,
+      transcript,
+      lastUsed: performance.now(),
+      overflowed: false,
+    };
+    onOverflow(session, () => {
+      branch.overflowed = true;
+      setStatus(
+        statusEl,
+        `"${branch.name}" exceeded its context window — the oldest messages were dropped.`,
+        true
+      );
+      render();
+    });
+    branches.push(branch);
+    activeId = branch.id;
+    branch.pruned = pruneBranches();
+    render();
+    return branch;
+  }
+
+  function destroyBranch(branch) {
+    try {
+      branch.session.destroy();
+    } catch {
+      /* already destroyed */
+    }
+    branches = branches.filter((b) => b !== branch);
+  }
+
+  /** Destroy least-recently-used inactive branches beyond the limit. */
+  function pruneBranches() {
+    const removed = [];
+    while (branches.length > MAX_BRANCHES) {
+      const candidates = branches
+        .filter((b) => b.id !== activeId)
+        .sort((a, b) => a.lastUsed - b.lastUsed);
+      if (!candidates.length) break;
+      removed.push(candidates[0].name);
+      destroyBranch(candidates[0]);
+    }
+    return removed;
+  }
+
+  async function ensureRoot(signal) {
+    if (active()) return active();
+    if (!rootPromise) {
+      rootPromise = createSession(
+        {
+          initialPrompts: [
+            {
+              role: 'system',
+              content: `You are a warm, concise barista at The Daily Grind. Help customers pick drinks and chat about coffee. Keep replies under 100 words.\n\n${MENU_FACTS}`,
+            },
+          ],
+        },
+        { progressEl, statusEl, signal }
+      )
+        .then((session) => addBranch(session, 'Main'))
+        .finally(() => {
+          rootPromise = null;
+        });
+    }
+    return rootPromise;
+  }
+
+  function render() {
+    listEl.replaceChildren(
+      ...branches.map((b) => {
+        const li = document.createElement('li');
+        li.className = b.id === activeId ? 'active' : '';
+        li.tabIndex = 0;
+        li.setAttribute('role', 'button');
+        li.setAttribute('aria-pressed', String(b.id === activeId));
+
+        const { used, total, ratio } = usageOf(b.session);
+        const label = document.createElement('span');
+        label.textContent =
+          `${b.name}${b.id === activeId ? ' (active)' : ''} — ` +
+          `${used.toLocaleString()} / ${total ? total.toLocaleString() : '?'} tokens` +
+          (b.overflowed ? ' ⚠ overflowed' : ratio >= NEAR_FULL ? ' ⚠ nearly full' : '');
+
+        const bar = document.createElement('div');
+        bar.className = 'usage-bar';
+        bar.title = `${Math.round(ratio * 100)}% of context window used`;
+        const fill = document.createElement('span');
+        fill.style.width = `${Math.min(100, ratio * 100)}%`;
+        if (ratio >= NEAR_FULL) fill.style.background = '#e53935';
+        bar.append(fill);
+
+        li.append(label, bar);
+        const select = () => {
+          if (busy) return;
+          activeId = b.id;
+          b.lastUsed = performance.now();
+          outputEl.textContent = b.transcript;
+          render();
+        };
+        li.addEventListener('click', select);
+        li.addEventListener('keydown', (e) => {
+          if (e.key === 'Enter' || e.key === ' ') {
+            e.preventDefault();
+            select();
+          }
+        });
+        return li;
+      })
+    );
+    cloneBtn.disabled = !!busy;
+    sendBtn.disabled = !!busy;
+  }
+
+  function begin() {
+    busy?.controller.abort();
+    busy = trackController();
+    render();
+    return busy;
+  }
+
+  function end(tracked) {
+    tracked.release();
+    if (busy === tracked) busy = null;
+    render();
+  }
+
+  sendBtn.addEventListener('click', async () => {
+    const message = inputEl.value.trim();
+    if (!message) {
+      setStatus(statusEl, 'Type a message for the active branch.', true);
+      inputEl.focus();
+      return;
+    }
+    const tracked = begin();
+    const { signal } = tracked.controller;
+
+    try {
+      const branch = await ensureRoot(signal);
+      const { used, total } = usageOf(branch.session);
+
+      // Warn ahead of time if this prompt would overflow the context window.
+      const measure = branch.session.measureContextUsage ?? branch.session.measureInputUsage;
+      if (measure && total) {
+        const cost = await measure.call(branch.session, message, { signal });
+        if (used + cost > total) {
+          setStatus(statusEl, 'This branch is almost full; older messages will be dropped. Consider cloning a fresh branch.', true);
+        }
+      }
+
+      branch.lastUsed = performance.now();
+      branch.transcript += `${branch.transcript ? '\n\n' : ''}You: ${message}\nBarista: `;
+      outputEl.textContent = branch.transcript;
+      inputEl.value = '';
+      setStatus(statusEl, `Replying in "${branch.name}"…`);
+
+      for await (const chunk of branch.session.promptStreaming(message, { signal })) {
+        branch.transcript += chunk;
+        if (branch.id === activeId) outputEl.textContent = branch.transcript;
+      }
+      setStatus(statusEl, `Reply added to "${branch.name}".`);
+    } catch (err) {
+      if (isAbort(err)) setStatus(statusEl, 'Cancelled.');
+      else {
+        console.error(err);
+        setStatus(statusEl, err.message || 'Something went wrong.', true);
+      }
+    } finally {
+      end(tracked);
+    }
+  });
+
+  cloneBtn.addEventListener('click', async () => {
+    const tracked = begin();
+    const { signal } = tracked.controller;
+
+    try {
+      const source = await ensureRoot(signal);
+      // clone() copies the conversation so far into an independent session.
+      const copy = await source.session.clone({ signal });
+      const branch = addBranch(copy, `Branch ${nextId}`, source.transcript);
+      outputEl.textContent = branch.transcript;
+      const { used, total } = usageOf(copy);
+      const cleaned = branch.pruned.length
+        ? ` Cleaned up unused session(s): ${branch.pruned.join(', ')}.`
+        : '';
+      setStatus(
+        statusEl,
+        `Cloned "${source.name}" → "${branch.name}" (${used.toLocaleString()} / ${total ? total.toLocaleString() : '?'} tokens in context).${cleaned}`
+      );
+    } catch (err) {
+      if (isAbort(err)) setStatus(statusEl, 'Cancelled.');
+      else {
+        console.error(err);
+        setStatus(statusEl, err.message || 'Could not clone the session.', true);
+      }
+    } finally {
+      end(tracked);
+    }
+  });
+
+  function resetAll() {
+    busy?.controller.abort();
+    branches.slice().forEach(destroyBranch);
+    branches = [];
+    activeId = null;
+    outputEl.textContent = '';
+    render();
+  }
+
+  resetBtn.addEventListener('click', () => {
+    resetAll();
+    setStatus(statusEl, 'All sessions destroyed.');
+  });
+
+  branching.resetAll = resetAll;
+  render();
+}
+
+// ---------------------------------------------------------------------------
+// Global cleanup — free model resources when the page goes away
+// ---------------------------------------------------------------------------
+
+window.addEventListener('pagehide', () => {
+  liveControllers.forEach((c) => c.abort());
+  liveControllers.clear();
+  baristaBase.destroy();
+  sentimentBase.destroy();
+  branching.resetAll?.();
+});

