+  <script type="module">
+    // Equipment connection panel — uses Local Network Access (local-network / loopback-network).
+    const DEVICES = {
+      brewer: {
+        permission: 'local-network',
+        addressSpace: 'local',
+        label: 'brewer',
+        url: (form) => `http://${form.elements.address.value.trim()}/api/status`,
+        offlineHelp: 'Make sure the brewer is powered on and that you are connected to the shop Wi-Fi.',
+      },
+      helper: {
+        permission: 'loopback-network',
+        addressSpace: 'loopback',
+        label: 'Brew Helper',
+        url: (form) => `http://127.0.0.1:${Number(form.elements.port.value)}/status`,
+        offlineHelp: 'Make sure the Daily Grind Brew Helper app is running on this computer.',
+      },
+    };
+
+    // Never query the legacy 'local-network-access' name: it can crash older Chrome renderers.
+    async function watchPermission(name, onChange) {
+      if (!navigator.permissions?.query) return 'prompt';
+      try {
+        const status = await navigator.permissions.query({ name });
+        status.addEventListener('change', () => onChange(status.state));
+        return status.state;
+      } catch {
+        return 'prompt'; // Unrecognised permission (Firefox/Safari): just try on user click.
+      }
+    }
+
+    function setPermissionUI(card, name, state) {
+      const badge = card.querySelector(`[data-permission-status="${name}"]`);
+      badge.textContent = state === 'prompt' ? 'ask' : state;
+      badge.dataset.state = state;
+      card.querySelector(`[data-remediation="${name}"]`).hidden = state !== 'denied';
+    }
+
+    function showResult(card, tone, message, data) {
+      const out = card.querySelector('.result');
+      out.dataset.tone = tone;
+      out.replaceChildren(document.createTextNode(message));
+      if (data && typeof data === 'object') {
+        const dl = document.createElement('dl');
+        for (const [key, value] of Object.entries(data).slice(0, 8)) {
+          if (value !== null && typeof value === 'object') continue;
+          const dt = document.createElement('dt');
+          const dd = document.createElement('dd');
+          dt.textContent = key;            // textContent only: never trust device output as HTML
+          dd.textContent = String(value);
+          dl.append(dt, dd);
+        }
+        if (dl.childElementCount) out.append(dl);
+      }
+    }
+
+    async function connect(card, device) {
+      const form = card.querySelector('form');
+      const button = card.querySelector('[data-action="connect"]');
+      if (!form.reportValidity()) return;
+
+      button.disabled = true;
+      showResult(card, 'info', `Connecting to ${device.label}…`);
+      try {
+        const response = await fetch(device.url(form), {
+          method: 'GET',
+          mode: 'cors',
+          credentials: 'omit',
+          cache: 'no-store',
+          targetAddressSpace: device.addressSpace, // Mixed-content exemption + address-space check
+          signal: AbortSignal.timeout(8000),
+        });
+        if (!response.ok) throw new Error(`HTTP ${response.status}`);
+        const type = response.headers.get('content-type') ?? '';
+        const data = type.includes('application/json') ? await response.json() : null;
+        showResult(card, 'ok', `Connected to ${device.label}.`, data);
+      } catch (err) {
+        const state = await watchPermission(device.permission, () => {});
+        setPermissionUI(card, device.permission, state);
+        let msg;
+        if (state === 'denied') msg = 'Permission was denied. See the steps below to allow access.';
+        else if (err.name === 'TimeoutError') msg = `The ${device.label} did not respond in time. ${device.offlineHelp}`;
+        else msg = `Couldn't reach the ${device.label}. ${device.offlineHelp}`;
+        showResult(card, 'error', msg);
+      } finally {
+        button.disabled = false;
+      }
+    }
+
+    const secure = window.isSecureContext;
+    document.getElementById('insecure-notice').hidden = secure;
+
+    for (const card of document.querySelectorAll('.device-card')) {
+      const device = DEVICES[card.dataset.device];
+      const button = card.querySelector('[data-action="connect"]');
+      const form = card.querySelector('form');
+
+      if (!secure) {
