+      try {
+        const response = await fetch(parsed.href, {
+          method: 'GET',
+          mode: 'cors',
+          credentials: 'omit',
+          cache: 'no-store',
+          referrerPolicy: 'no-referrer',
+          headers: { Accept: 'application/json, text/plain;q=0.9' },
+          // Exempts http:// from mixed-content blocking (once permitted) and makes the
+          // browser verify the resolved IP really is in the declared address space.
+          targetAddressSpace: target.id,
+          signal: AbortSignal.any([controller.signal, AbortSignal.timeout(REQUEST_TIMEOUT_MS)]),
+        });
+        const latencyMs = Math.round(performance.now() - started);
+        const text = await response.text();
+        let body = text;
+        try {
+          body = JSON.stringify(JSON.parse(text), null, 2);
+        } catch {
+          /* not JSON; show as text */
+        }
+        if (body.length > MAX_BODY_CHARS) body = `${body.slice(0, MAX_BODY_CHARS)}\n… (truncated)`;
+
+        if (!response.ok) {
+          setConn({
+            kind: 'error',
+            message: `Reached the endpoint, but it responded with HTTP ${response.status}.`,
+            hint: 'Check the path in the URL and the endpoint logs.',
+          });
+          return;
+        }
+        setConn({ kind: 'connected', status: response.status, latencyMs, body, at: new Date() });
+      } catch (err) {
+        if (controller.signal.aborted) {
+          return; // Superseded by a newer attempt or unmounted.
+        }
+        const timedOut = err instanceof DOMException && err.name === 'TimeoutError';
+        // Re-check permission: a denial surfaces as a generic TypeError.
+        const status = await queryLnaPermission(target.permission);
+        if (status) setPermission(status.state);
+        const denied = status?.state === 'denied';
+        setConn({
+          kind: 'error',
+          message: timedOut
+            ? `No response within ${REQUEST_TIMEOUT_MS / 1000} seconds.`
+            : denied
+              ? 'Your browser blocked the connection.'
+              : 'Could not connect.',
+          hint: denied
+            ? 'Re-enable access in site settings (see below), then try again.'
+            : target.id === 'local'
+              ? 'Make sure the device is powered on, on the same Wi-Fi network as this computer, and allows CORS requests from this site.'
+              : 'Make sure the companion CLI is running on this machine, listening on that port, and allows CORS requests from this site.',
+        });
+      } finally {
+        if (abortRef.current === controller) abortRef.current = null;
+      }
+    },
+    [target],
+  );
