+          />
+          <button
+            type="submit"
+            disabled={busy || permission === 'denied'}
+            className="rounded bg-gray-900 px-4 py-2 text-sm font-semibold text-white hover:bg-amber-500 hover:text-gray-900 disabled:cursor-not-allowed disabled:bg-gray-400"
+          >
+            {busy ? 'Connecting…' : conn.kind === 'connected' ? 'Reconnect' : 'Connect'}
+          </button>
+        </div>
+        {validationError && (
+          <p id={errorId} className="text-sm text-red-700">
+            {validationError}
+          </p>
+        )}
+        {permission === 'prompt' && conn.kind === 'idle' && (
