+            <li>Open <strong>Site settings</strong>.</li>
+            <li>
+              Set <strong>{target.id === 'local' ? 'Local network' : 'Loopback network'}</strong> to <em>Allow</em> (or{' '}
+              <em>Ask</em>), then return here.
+            </li>
+          </ol>
+        </div>
+      )}
+    </section>
+  );
+}
+
+export default function DiagnosticsConnectionWidget() {
+  const [secure, setSecure] = useState(true);
+  useEffect(() => setSecure(window.isSecureContext), []);
+
+  return (
+    <div className="space-y-4">
+      {!secure && (
+        <div role="alert" className="rounded border border-red-300 bg-red-50 p-3 text-sm text-red-900">
+          This page isn’t loaded over HTTPS. Browsers deny local and loopback network access from insecure pages —
+          reload the site using <code>https://</code>.
