+interface PanelState {
+  status: Status;
+  lastAction?: DiagnosticsPath;
+  result?: ProbeResult;
+  validationError?: string;
+}
+
+function StatusBadge({ status }: { status: Status }) {
+  const styles: Record<Status, string> = {
+    idle: 'bg-gray-100 text-gray-600',
+    connecting: 'bg-amber-100 text-amber-800',
+    connected: 'bg-green-100 text-green-800',
+    error: 'bg-red-100 text-red-700',
+  };
+  const labels: Record<Status, string> = {
+    idle: 'Not connected',
+    connecting: 'Connecting…',
+    connected: 'Connected',
+    error: 'Connection failed',
+  };
+  return (
+    <span
+      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-semibold ${styles[status]}`}
+      role="status"
+      aria-live="polite"
+    >
+      <span
+        className={`h-1.5 w-1.5 rounded-full ${
+          status === 'connected'
+            ? 'bg-green-600'
+            : status === 'error'
+              ? 'bg-red-600'
+              : status === 'connecting'
+                ? 'bg-amber-500 animate-pulse'
+                : 'bg-gray-400'
+        }`}
+        aria-hidden="true"
+      />
+      {labels[status]}
+    </span>
+  );
+}
+
+function ResultView({ state }: { state: PanelState }) {
+  if (state.validationError) {
+    return (
+      <p className="mt-4 rounded-md bg-red-50 p-3 text-sm text-red-700" role="alert">
+        {state.validationError}
+      </p>
+    );
+  }
+  const r = state.result;
+  if (!r) return null;
+
+  // Rendered strictly as text inside <pre>; React escapes the content, so a
+  // malicious device cannot inject markup into the page.
+  const body = r.json !== undefined ? JSON.stringify(r.json, null, 2) : r.text;
