+
+export default function DiagnosticsConnect() {
+  // Rendered with client:only, so localStorage is available on first render.
+  const [initial] = useState<SavedSettings>(() => loadSettings());
+
+  return (
+    <div className="space-y-6" data-skip-tracking="true">
+      <div className="flex gap-3 rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">
+        <ShieldCheckIcon className="h-5 w-5 flex-none" aria-hidden="true" />
+        <div>
+          <p className="font-semibold">Your browser connects directly — nothing goes through our servers.</p>
+          <p className="mt-1">
+            Requests are only sent when you click a button, only to the address you enter, and never include cookies.
+            Your browser may ask for permission to access devices on your local network; you can revoke it at any time
+            in site settings.
+          </p>
+        </div>
+      </div>
+
+      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
+        <LanDevicePanel initial={initial} />
+        <CompanionCliPanel initial={initial} />
+      </div>
+
+      <details className="rounded-lg border border-gray-200 p-5 text-sm text-gray-700">
+        <summary className="flex cursor-pointer items-center gap-2 font-semibold text-gray-900">
+          <SignalIcon className="h-5 w-5" aria-hidden="true" />
+          Endpoint requirements for device firmware &amp; CLI authors
+        </summary>
+        <ul className="mt-3 list-disc space-y-1.5 pl-5">
+          <li>
+            Serve <code>GET /diagnostics/v1/status</code> and <code>GET /diagnostics/v1/ping</code> returning JSON.
+          </li>
+          <li>
+            Answer CORS preflight (<code>OPTIONS</code>) with <code>Access-Control-Allow-Origin</code> set to this
+            site's exact origin (never <code>*</code>), <code>Access-Control-Allow-Headers: Authorization, Accept</code>,
+            and <code>Access-Control-Allow-Private-Network: true</code>.
+          </li>
+          <li>
+            Check the <code>Origin</code> header on every request and reject unknown origins — other websites can
+            send requests to your LAN too.
+          </li>
+          <li>
+            The companion CLI should bind to <code>127.0.0.1</code> only, require the{' '}
+            <code>Authorization: Bearer &lt;token&gt;</code> header, and generate a fresh random token on each start.
+          </li>
+          <li>Keep these endpoints read-only; the widget never sends state-changing requests.</li>
+        </ul>
+      </details>
+    </div>
+  );
+}
