+  await import('https://unpkg.com/@oddbird/popover-polyfill@latest/dist/popover.min.js');
+}
+
+/* ------------------------------------------------------------------ */
+/* Order menus: clone the template into each seasonal card            */
+/* ------------------------------------------------------------------ */
+
+const template = document.getElementById('order-menu-template');
+for (const card of document.querySelectorAll('.card[data-drink]')) {
+  const html = template.innerHTML.replaceAll('{d}', card.dataset.drink);
+  const actions = card.querySelector('.card-actions');
+  actions.insertAdjacentHTML('beforeend', html);
+  actions.querySelector('[data-link="details"]').href = card.dataset.href;
+  actions.querySelector('.order-trigger').setAttribute('aria-describedby', `${card.dataset.drink}-selection`);
+  card.querySelector('.selection').id = `${card.dataset.drink}-selection`;
+}
+
+/* ------------------------------------------------------------------ */
+/* Generic menu behavior                                               */
+/* ------------------------------------------------------------------ */
+
+const MENU_GROUP = '[focusgroup~="menu"]';
+const nativeFocusgroup = 'focusGroup' in HTMLElement.prototype;
+const nativeInvokers = 'commandForElement' in HTMLButtonElement.prototype;
+const anchorSupported = CSS.supports('position-area', 'block-end');
+const toggleSource = typeof ToggleEvent !== 'undefined' && 'source' in ToggleEvent.prototype;
+const canHover = matchMedia('(hover: hover)');
+
+const triggers = [...document.querySelectorAll('button[commandfor]')]
+  .filter(t => document.getElementById(t.getAttribute('commandfor'))?.querySelector(`:scope > ${MENU_GROUP}`));
+const menus = triggers.map(t => document.getElementById(t.getAttribute('commandfor')));
+const triggerOf = new Map(menus.map((m, i) => [m, triggers[i]]));
+
+const menuFor = trigger => document.getElementById(trigger.getAttribute('commandfor'));
+const isOpen = menu => menu.matches(':is(:popover-open, .\\:popover-open)');
+const isSubmenuTrigger = trigger => !!trigger.parentElement.closest(MENU_GROUP);
+const groupOf = menu => menu.querySelector(`:scope > ${MENU_GROUP}`);
+const ownItems = group => [...group.querySelectorAll('button, a[href]')]
+  .filter(i => i.closest('[focusgroup]') === group)
+  .filter(i => !i.disabled && i.getAttribute('aria-disabled') !== 'true');
+const rootMenuOf = el => {
+  let menu = el.closest('[popover]');
+  while (menu) {
+    const parent = triggerOf.get(menu)?.parentElement.closest('[popover]');
+    if (!parent || !triggerOf.has(parent)) return menu;
+    menu = parent;
+  }
+  return null;
+};
