+/* Fallbacks ---------------------------------------------------------- */
+
+if (!nativeInvokers) {
+  // popovertarget has longer support (and is covered by the popover polyfill).
+  for (const t of triggers) t.setAttribute('popovertarget', t.getAttribute('commandfor'));
+}
+
+if (anchorSupported && !toggleSource) {
