+      }
+    });
+
+    trigger.addEventListener('pointerleave', event => startBridge(menu, event));
+  }
+}
+
+addEventListener('blur', () => { windowRefocus = true; });
+addEventListener('focus', () => setTimeout(() => { windowRefocus = false; }));
+
+/* Close menus that no longer contain focus ------------------------------ */
+
+document.addEventListener('focusin', event => {
+  const target = event.target;
+  for (const menu of menus) {
+    if (isOpen(menu) && !menu.contains(target) && triggerOf.get(menu) !== target) {
+      menu.hidePopover();
+    }
+  }
+});
+
+/* Keyboard inside menus ---------------------------------------------------- */
+
+document.addEventListener('keydown', event => { lastKey = event.key; }, true);
+
+for (const group of document.querySelectorAll(MENU_GROUP)) {
+  const menu = group.parentElement;
+
+  group.addEventListener('keydown', event => {
+    // Ignore events from nested submenus; they have their own handler.
+    if (event.target.closest(MENU_GROUP) !== group) return;
+    const items = ownItems(group);
+    const current = items.indexOf(event.target);
+    const trigger = triggerOf.get(menu);
+    const nested = trigger && isSubmenuTrigger(trigger);
+
+    switch (event.key) {
+      case 'ArrowDown':
+      case 'ArrowUp':
+        if (nativeFocusgroup || current < 0) return;
+        event.preventDefault();
+        focusItem(items[(current + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length]);
+        break;
+      case 'Home':
+      case 'End':
+        event.preventDefault();
+        focusItem(event.key === 'Home' ? items[0] : items.at(-1));
+        break;
+      case 'ArrowLeft':
+        if (!nested) return;
+      // fall through
+      case 'Escape':
+        // Close one level and return focus to its trigger.
+        event.preventDefault();
+        event.stopPropagation();
+        closeMenu(menu);
+        break;
+      case 'Tab': {
+        // Leave the menu system from the root trigger; don't step through items.
+        const root = rootMenuOf(menu);
+        if (root) closeMenu(root);
+        break;
+      }
+    }
+  });
+
+  // Hover follows focus (no ring for pointer focus).
+  group.addEventListener('pointermove', event => {
+    const item = event.target.closest('button, a[href]');
+    if (!item || item.closest('[focusgroup]') !== group || item === document.activeElement) return;
+    // The move that leaves a trigger may hit-test a sibling before the bridge exists.
+    if (!item.contains(document.elementFromPoint(event.clientX, event.clientY))) return;
+    pointerFocus = true;
+    item.focus({ preventScroll: true });
+    pointerFocus = false;
+  });
+}
+
+/* Safe triangle from a submenu trigger to its submenu ---------------------- */
+
+function startBridge(submenu, event) {
+  if (!canHover.matches || !isOpen(submenu)) return;
+  const rect = submenu.getBoundingClientRect();
+  const left = event.clientX < rect.left;
+  if (!left && event.clientX <= rect.right) return; // --below: no side edge
+  submenu.style.setProperty('--pointer-x', `${event.clientX - rect.left}px`);
+  submenu.style.setProperty('--pointer-y', `${event.clientY - rect.top}px`);
+  submenu.dataset.bridge = '';
+  let timer;
+  let lastX = event.clientX;
+  const stop = () => {
+    clearTimeout(timer);
+    submenu.removeEventListener('pointermove', extend);
+    submenu.removeAttribute('data-bridge');
+  };
+  const extend = ({ target, clientX }) => {
+    if (target !== submenu || (left ? clientX < lastX : clientX > lastX)) return stop();
+    lastX = clientX;
+    clearTimeout(timer);
+    timer = setTimeout(stop, 300);
+  };
+  timer = setTimeout(stop, 300);
+  submenu.addEventListener('pointermove', extend);
+  submenu.addEventListener('toggle', stop, { once: true });
+}
+
+/* Links inside menus close everything (same-page anchors keep the page). */
+document.addEventListener('click', event => {
+  const link = event.target.closest(`${MENU_GROUP} a[href]`);
+  if (link) closeAllFrom(link);
+});
+
+/* ------------------------------------------------------------------ */
+/* Order customization                                                 */
+/* ------------------------------------------------------------------ */
+
+const LABELS = {
+  size: { small: 'Small', medium: 'Medium', large: 'Large' },
+  milk: { none: '', whole: 'whole milk', skim: 'skim milk', oat: 'oat milk', almond: 'almond milk' },
+  syrup: { none: '', maple: 'maple', vanilla: 'vanilla', caramel: 'caramel', hazelnut: 'hazelnut' },
+};
+const EXTRAS = { extraShot: 'extra shot', decaf: 'decaf', whip: 'whipped cream' };
+
+const toast = document.getElementById('toast');
+const bagCount = document.getElementById('bag-count');
+let bag = 0;
+let toastTimer;
+
+function announce(message) {
+  toast.textContent = message;
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => { toast.textContent = ''; }, 3500);
+}
+
+function defaults(card) {
+  return {
+    size: card.dataset.size,
+    milk: card.dataset.milk,
+    syrup: card.dataset.syrup,
+    extraShot: false,
+    decaf: false,
+    whip: false,
+    favorite: card.dataset.favorite === 'true',
+  };
+}
+
+const state = new Map();
+
+function describe(s) {
+  const parts = [LABELS.size[s.size]];
+  if (s.milk !== 'none') parts.push(LABELS.milk[s.milk]);
+  if (s.syrup !== 'none') parts.push(`${LABELS.syrup[s.syrup]} syrup`);
+  for (const [key, label] of Object.entries(EXTRAS)) if (s[key]) parts.push(label);
+  return parts.join(' · ');
+}
+
+function render(card) {
+  const s = state.get(card);
+  for (const item of card.querySelectorAll('[data-option]')) {
+    item.setAttribute('aria-checked', String(s[item.dataset.option] === item.dataset.value));
+  }
+  for (const item of card.querySelectorAll('[data-toggle]')) {
+    item.setAttribute('aria-checked', String(!!s[item.dataset.toggle]));
+  }
+  card.querySelector('.selection').textContent = `Your order: ${describe(s)}${s.favorite ? ' ★' : ''}`;
+}
+
+for (const card of document.querySelectorAll('.card[data-drink]')) {
+  state.set(card, defaults(card));
+  render(card);
+
+  card.addEventListener('click', async event => {
+    const item = event.target.closest(`${MENU_GROUP} button`);
+    if (!item || item.hasAttribute('commandfor')) return;
+    const s = state.get(card);
+    const name = card.dataset.name;
+    const fromKeyboard = event.detail === 0;
+
+    if (item.dataset.option) {
+      // Pick-one: radios close the menu on Enter, Space, or click.
+      s[item.dataset.option] = item.dataset.value;
+      render(card);
+      closeAllFrom(item, 300);
+      return;
+    }
+
+    if (item.dataset.toggle) {
+      // On/off: Space keeps the menu open, Enter and click close it.
+      s[item.dataset.toggle] = !s[item.dataset.toggle];
+      render(card);
+      if (item.dataset.toggle === 'favorite') {
+        announce(s.favorite ? `${name} saved to favorites` : `${name} removed from favorites`);
+      }
+      if (!(fromKeyboard && lastKey === ' ')) closeAllFrom(item, 300);
+      return;
+    }
+
+    switch (item.dataset.action) {
+      case 'add':
+        bag += 1;
+        bagCount.textContent = bag;
+        bagCount.setAttribute('aria-label', `${bag} ${bag === 1 ? 'item' : 'items'} in order`);
+        announce(`Added ${name} (${describe(s)}) to your order`);
+        break;
+      case 'reset':
+        state.set(card, { ...defaults(card), favorite: s.favorite });
+        render(card);
+        announce(`${name} reset to default`);
+        break;
+      case 'share': {
+        const url = new URL(card.dataset.href, location.href).href;
+        closeAllFrom(item);
+        try {
+          if (navigator.share) await navigator.share({ title: name, url });
+          else { await navigator.clipboard.writeText(url); announce(`Link to ${name} copied`); }
+        } catch { /* share dismissed */ }
+        return;
+      }
+    }
+    closeAllFrom(item);
+  });
+}

