+                        options: PUMPS.map((p) => ({ value: p, label: `${p} pump${p === '1' ? '' : 's'}` })) },
+                    ],
+                  },
+                ],
+              },
+            ],
+          },
+          sep,
+          { type: 'checkbox', key: 'iced', label: drink.alwaysIced ? 'Served iced' : 'Make it iced',
+            checked: s.iced, disabled: drink.alwaysIced },
+          { type: 'checkbox', key: 'decaf', label: 'Decaf' },
+          sep,
+          { label: 'Add to Order', key: 'add', action: 'add', className: 'mi-primary' },
+          { label: 'Save as Favorite', action: 'favorite' },
+          { label: 'Reset to Default', action: 'reset' },
+          link('View Details', drink.href),
+        ];
+      }
+
+      document.querySelectorAll('.card[data-drink]').forEach((card) => {
+        const drink = DRINKS[card.dataset.drink];
+        if (!drink) return;
+        const state = { ...drink.defaults };
+        const summary = card.querySelector('.card-summary');
+        const button = card.querySelector('.dd > button');
+        button.setAttribute('aria-label', `Customize and order ${drink.name}`);
+
+        const menu = new MenuButton(button, buildCustomizeMenu(drink, state), {
+          label: `${drink.name} options`,
+          onChange(key, value) {
+            state[key] = value;
+            sync();
+          },
+          onAction(action) {
+            if (action === 'add') {
+              addToBag();
+              toast(`Added ${drink.name} (${money(priceOf(drink, state))}) to your bag`);
+            } else if (action === 'favorite') {
+              toast(`Saved your ${drink.name} as a favorite`);
+            } else if (action === 'reset') {
+              Object.assign(state, drink.defaults);
+              ['size', 'milk', 'syrup', 'pumps'].forEach((k) => menu.setRadio(k, state[k]));
+              ['shot', 'whip', 'iced', 'decaf'].forEach((k) => menu.setChecked(k, state[k]));
+              sync();
+              toast(`${drink.name} reset to default`);
+            }
+          },
+        });
+
+        function sync() {
+          const price = money(priceOf(drink, state));
+          summary.innerHTML = '';
+          summary.append(describe(state));
+          const priceEl = document.createElement('span');
+          priceEl.className = 'card-price';
+          priceEl.textContent = price;
+          summary.append(priceEl);
+
+          menu.setHint('sizeMenu', find(SIZES, state.size).short);
+          menu.setHint('milkMenu', find(MILKS, state.milk).label);
+          menu.setHint('syrupMenu', find(SYRUPS, state.syrup).label);
+          menu.setHint('pumpsMenu', state.syrup === 'none' ? '' : state.pumps);
+          menu.setDisabled('pumpsMenu', state.syrup === 'none');
+          menu.setHint('add', price);
+        }
+
+        sync();
+      });
+    })();
+  </script>
 </body>

 </html>

