@@ -0,0 +1,45 @@
+// Imports user configuration from the previous origin after the installed app
+// moves here. Web App Origin Migration only transfers the installation
+// (OS shortcuts, icons); origin-bound storage must be copied separately.
+(() => {
+  const OLD_ORIGIN = 'https://dailygrind.example.com';
+  const PREFIX = 'dg:';
+  const DONE_KEY = 'dg:migration:imported';
+  const TIMEOUT_MS = 10000;
+
+  try {
+    if (localStorage.getItem(DONE_KEY)) return;
+  } catch {
+    return;
+  }
+
+  const iframe = document.createElement('iframe');
+  iframe.src = `${OLD_ORIGIN}/migration-bridge.html`;
+  iframe.hidden = true;
+  iframe.setAttribute('aria-hidden', 'true');
+  iframe.tabIndex = -1;
+
+  const cleanup = () => {
+    window.removeEventListener('message', onMessage);
+    clearTimeout(timer);
+    iframe.remove();
+  };
+
+  function onMessage(event) {
+    if (event.origin !== OLD_ORIGIN || event.source !== iframe.contentWindow) return;
+    const data = event.data;
+    if (!data || data.type !== 'dg-settings-migration' || typeof data.settings !== 'object') return;
+
+    for (const [key, value] of Object.entries(data.settings ?? {})) {
+      if (!key.startsWith(PREFIX) || key === DONE_KEY || typeof value !== 'string') continue;
+      // Never clobber settings the user has already changed on the new origin.
+      if (localStorage.getItem(key) === null) localStorage.setItem(key, value);
+    }
+    localStorage.setItem(DONE_KEY, new Date().toISOString());
+    cleanup();
+  }
+
+  window.addEventListener('message', onMessage);
+  const timer = setTimeout(cleanup, TIMEOUT_MS);
+  document.body.append(iframe);
+})();
