+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <title>Daily Grind settings bridge</title>
+  <meta name="robots" content="noindex">
+</head>
+<body>
+  <script>
+    // Hands user configuration stored on the old origin to the new origin.
+    // Loaded in a hidden iframe by https://app.dailygrind.example.com/.
+    // The targetOrigin restricts delivery to the new origin only.
+    (() => {
+      const NEW_ORIGIN = 'https://app.dailygrind.example.com';
+      const PREFIX = 'dg:';
+      if (window.parent === window) return;
+
+      const settings = {};
+      try {
+        for (let i = 0; i < localStorage.length; i++) {
+          const key = localStorage.key(i);
+          if (key && key.startsWith(PREFIX)) settings[key] = localStorage.getItem(key);
+        }
+      } catch {
+        // Storage unavailable; send an empty payload so the parent can finish.
+      }
+      window.parent.postMessage({ type: 'dg-settings-migration', settings }, NEW_ORIGIN);
+    })();
+  </script>
+</body>
+</html>

