--- /dev/null
+++ b/migration.js
@@ -0,0 +1,123 @@
+/*
+ * Origin migration for The Daily Grind installed web app.
+ *
+ * OLD_ORIGIN -> NEW_ORIGIN
+ *
+ * 1. OS-level integration (install, window mode, jump-list/dock shortcuts,
+ *    permissions) is moved by the browser's native PWA migration:
+ *      - legacy.webmanifest (served on OLD_ORIGIN) declares `migrate_to`
+ *      - manifest.webmanifest (served on NEW_ORIGIN) declares `migrate_from`
+ *      - /.well-known/web-app-origin-association on OLD_ORIGIN authorises it
+ *    Shortcut URLs are origin-relative and identical in both manifests.
+ *
+ * 2. User configuration lives in origin-scoped localStorage, which the browser
+ *    does NOT move. When the app is opened on OLD_ORIGIN we hand the stored
+ *    settings to NEW_ORIGIN in the URL fragment (never sent to any server) and
+ *    NEW_ORIGIN imports them without clobbering anything already set there.
+ */
+(function () {
+  'use strict';
+
+  var OLD_ORIGIN = 'https://dailygrind.example';
+  var NEW_ORIGIN = 'https://app.thedailygrind.coffee';
+  var HANDOFF_PARAM = 'dg-migrate';
+  var MIGRATED_FLAG = 'dg:migrated-at';
+
+  var origin = window.location.origin;
+  var isOld = origin === OLD_ORIGIN;
+  var isNew = origin === NEW_ORIGIN;
+
+  // Pick the right manifest synchronously, before the browser fetches it.
+  if (isOld) {
+    var link = document.querySelector('link[rel="manifest"]');
+    if (link) link.href = '/legacy.webmanifest';
+  }
+
+  function encode(obj) {
+    var bytes = new TextEncoder().encode(JSON.stringify(obj));
+    var bin = '';
+    bytes.forEach(function (b) { bin += String.fromCharCode(b); });
+    return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+  }
+
+  function decode(str) {
+    var b64 = str.replace(/-/g, '+').replace(/_/g, '/');
+    while (b64.length % 4) b64 += '=';
+    var bin = atob(b64);
+    var bytes = new Uint8Array(bin.length);
+    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
+    return JSON.parse(new TextDecoder().decode(bytes));
+  }
+
+  function snapshotSettings() {
+    var data = {};
+    try {
+      for (var i = 0; i < localStorage.length; i++) {
+        var key = localStorage.key(i);
+        if (key && key !== MIGRATED_FLAG) data[key] = localStorage.getItem(key);
+      }
+    } catch (e) { /* storage unavailable */ }
+    return data;
+  }
+
+  function isStandalone() {
+    return window.matchMedia('(display-mode: standalone)').matches ||
+      window.matchMedia('(display-mode: window-controls-overlay)').matches ||
+      window.navigator.standalone === true;
+  }
+
+  function targetUrl() {
+    var path = window.location.pathname + window.location.search;
+    var hash = '#' + HANDOFF_PARAM + '=' + encode({ v: 1, settings: snapshotSettings() });
+    return NEW_ORIGIN + path + hash;
+  }
+
+  // ---- NEW origin: import handed-off settings --------------------------------
+  if (isNew) {
+    var m = window.location.hash.match(new RegExp('[#&]' + HANDOFF_PARAM + '=([^&]+)'));
+    if (m) {
+      try {
+        var payload = decode(m[1]);
+        var settings = (payload && payload.settings) || {};
+        Object.keys(settings).forEach(function (key) {
+          if (localStorage.getItem(key) === null) localStorage.setItem(key, settings[key]);
+        });
+        localStorage.setItem(MIGRATED_FLAG, new Date().toISOString());
+      } catch (e) {
+        console.warn('[migration] could not import settings', e);
+      }
+      history.replaceState(null, '', window.location.pathname + window.location.search);
+    }
+    return;
+  }
+
+  // ---- OLD origin: forward users (and their settings) to the new origin -----
+  if (!isOld) return; // local dev / other hosts: no-op
+
+  // Installed app windows go straight to the new origin; the browser's native
+  // migration replaces the installed app, and settings ride along.
+  if (isStandalone()) {
+    window.location.replace(targetUrl());
+    return;
+  }
+
+  // Browser tabs get a non-blocking notice with a link that carries settings.
+  document.addEventListener('DOMContentLoaded', function () {
+    var bar = document.createElement('div');
+    bar.setAttribute('role', 'status');
+    bar.style.cssText = 'background:#ffab40;color:#3e2723;text-align:center;' +
+      'padding:10px 16px;font-size:0.95rem;';
+    var a = document.createElement('a');
+    a.textContent = 'Continue on our new site';
+    a.style.cssText = 'color:#3e2723;font-weight:bold;margin-left:8px;';
+    a.href = NEW_ORIGIN + window.location.pathname + window.location.search;
+    a.addEventListener('click', function (ev) {
+      ev.preventDefault();
+      window.location.href = targetUrl();
+    });
+    bar.appendChild(document.createTextNode('The Daily Grind has moved to ' +
+      NEW_ORIGIN.replace(/^https?:\/\//, '') + '. Your settings come with you.'));
+    bar.appendChild(a);
+    document.body.insertBefore(bar, document.body.firstChild);
+  });
+})();
diff --git a/sw.js b/sw.js
new file mode 100644
index 0000000..83f9968
--- /dev/null
+++ b/sw.js
@@ -0,0 +1,32 @@
+// Minimal service worker: makes the app installable and keeps it working offline.
+const CACHE = 'daily-grind-v1';
+const ASSETS = ['/', '/index.html', '/migration.js', '/icons/icon-192.png', '/icons/icon-512.png'];
+
+self.addEventListener('install', (event) => {
+  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
+});
+
+self.addEventListener('activate', (event) => {
+  event.waitUntil(
+    caches.keys()
+      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
+      .then(() => self.clients.claim())
+  );
+});
+
+self.addEventListener('fetch', (event) => {
+  const req = event.request;
+  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
+  // Network first so migration changes (manifests, redirects) roll out immediately.
+  event.respondWith(
+    fetch(req)
+      .then((res) => {
+        if (res.ok) {
+          const copy = res.clone();
+          caches.open(CACHE).then((c) => c.put(req, copy));
+        }
+        return res;
+      })
+      .catch(() => caches.match(req).then((r) => r || (req.mode === 'navigate' ? caches.match('/') : undefined)))
+  );
+});

