+      // If a disabled button had focus, move focus to its sibling so keyboard users aren't stranded.
+      [prevBtn, nextBtn].forEach(function (btn) {
+        btn.addEventListener('click', function () {
+          setTimeout(function () {
+            if (btn.disabled && document.activeElement === btn) {
+              (btn === prevBtn ? nextBtn : prevBtn).focus();
+            }
+          }, 450);
+        });
+      });
