+      var scrollRaf;
+      track.addEventListener('scroll', function () {
+        cancelAnimationFrame(scrollRaf);
+        scrollRaf = requestAnimationFrame(updateControls);
+      }, { passive: true });
+      window.addEventListener('resize', updateControls);
