+          case 'ArrowRight': e.preventDefault(); scrollToIndex(currentIndex() + 1); break;
+          case 'ArrowLeft': e.preventDefault(); scrollToIndex(currentIndex() - 1); break;
+          case 'PageDown': e.preventDefault(); page(1); break;
+          case 'PageUp': e.preventDefault(); page(-1); break;
+          case 'Home': e.preventDefault(); scrollToIndex(0); break;
+          case 'End': e.preventDefault(); scrollToIndex(slides.length - 1); break;
+        }
+      });
+
+      // Bring a card fully into view when something inside it receives keyboard focus.
+      track.addEventListener('focusin', function (e) {
+        var slide = e.target.closest && e.target.closest('.carousel-track > li');
+        if (!slide) return;
