+          dialog.classList.remove('is-opening');
+          currentAnim = null;
+        };
+      }
+
+      function finishClose() {
+        closing = false;
+        dialog.classList.remove('is-closing');
+        if (dialog.open) dialog.close();
+      }
+
+      function closeDialog() {
+        if (!dialog.open || closing) return;
+        closing = true;
+        if (currentAnim) currentAnim.cancel();
+
+        var target = opener && document.body.contains(opener) ? opener : null;
+        if (reduceMotion.matches || !supportsClip() || !target) { finishClose(); return; }
+
+        dialog.classList.add('is-closing');
+        var to = insetFromButton(target);
+        currentAnim = dialog.animate([
+          { clipPath: 'inset(0px 0px 0px 0px round 12px)', opacity: 1 },
+          { clipPath: to, opacity: 0.6 }
+        ], { duration: 300, easing: 'cubic-bezier(0.55, 0, 0.75, 0.2)' });
