+// Small local subset of the community AAGUID registry:
+// https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/refs/heads/main/combined_aaguid.json
+// The server should resolve AAGUIDs at registration time and persist `name` / `providerIcon`;
+// this map is only used to show a friendly provider label next to user-renamed passkeys.
+export const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export const AAGUIDS = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager' },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain' },
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': { name: 'iCloud Keychain (Managed)' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password' },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden' },
+  '531126d6-e717-415c-9320-3d9aa6981239': { name: 'Dashlane' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello' },
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': { name: 'Windows Hello' },
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': { name: 'Windows Hello' },
+  'adce0002-35bc-c60a-648b-0b25f1f05503': { name: 'Chrome on Mac' },
+  'b5397666-4885-aa6b-cebf-e52262a439a2': { name: 'Chromium Browser' },
+  '771b48fd-d3d4-4f74-9232-fc157ab0507a': { name: 'Edge on Mac' },
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': { name: 'YubiKey 5 Series' },
+  'ee882879-721c-4913-9775-3dfcce97072a': { name: 'YubiKey 5 Series' },
+  'fa2b99dc-9e39-4257-8f92-4a30d23c4118': { name: 'YubiKey 5 Series with NFC' },
+};
+
+export function lookupProvider(aaguid) {
+  if (!aaguid || aaguid === ZERO_AAGUID) return null;
+  return AAGUIDS[aaguid] ?? null;
+}
diff --git a/assets/js/account/passkey-api.js b/assets/js/account/passkey-api.js
new file mode 100644
index 0000000..df82bab
--- /dev/null
+++ b/assets/js/account/passkey-api.js
@@ -0,0 +1,204 @@
+// Passkey / account API client.
+//
+// Real backend contract (all routes require an authenticated session cookie):
+//   GET    /api/credentials                    -> { rpId, userId, user: { name, displayName }, credentials: [...] }
+//   PUT    /api/credential/:id   { name }      -> updated credential
+//   DELETE /api/credential/:id                 -> { success: true }
+//   PUT    /api/user   { name, displayName }   -> { name, displayName, rpId, userId }
+//   POST   /api/passkey/registration/options   -> PublicKeyCredentialCreationOptionsJSON
+//   POST   /api/passkey/registration/verify    (RegistrationResponseJSON) -> stored credential
+//
+// Credential shape: { id, name, aaguid, providerIcon?, registeredAt, lastUsedAt? }
+// `id`, `userId` MUST be unpadded Base64URL strings; timestamps are epoch milliseconds.
+//
+// Until the backend ships these routes, the account page sets data-api="mock" and an
+// in-browser mock (persisted in localStorage) stands in for the server.
+
+export class UnauthorizedError extends Error {}
+
+export function bytesToBase64Url(bytes) {
+  let bin = '';
+  for (const b of new Uint8Array(bytes)) bin += String.fromCharCode(b);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function base64UrlToBytes(value) {
+  const b64 = value.replace(/-/g, '+').replace(/_/g, '/');
+  const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
+  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
+}
+
+// ---------- HTTP implementation ----------
+
+async function request(method, url, body) {
+  const res = await fetch(url, {
+    method,
+    credentials: 'same-origin',
+    headers: body ? { 'Content-Type': 'application/json' } : undefined,
+    body: body ? JSON.stringify(body) : undefined,
+  });
+  if (res.status === 401) throw new UnauthorizedError('Not signed in');
+  if (!res.ok) {
+    let message = `Request failed (${res.status})`;
+    try {
+      message = (await res.json()).error ?? message;
+    } catch {}
+    throw new Error(message);
+  }
+  return res.json();
+}
+
+const httpApi = {
+  listCredentials: () => request('GET', '/api/credentials'),
+  renameCredential: (id, name) => request('PUT', `/api/credential/${encodeURIComponent(id)}`, { name }),
+  deleteCredential: (id) => request('DELETE', `/api/credential/${encodeURIComponent(id)}`),
+  updateUser: (details) => request('PUT', '/api/user', details),
+  registrationOptions: () => request('POST', '/api/passkey/registration/options'),
+  verifyRegistration: (json) => request('POST', '/api/passkey/registration/verify', json),
+};
+
+// ---------- Mock implementation (prototype only) ----------
+
+const MOCK_KEY = 'dailygrind.mock-passkeys.v1';
+// Simulates the server's configured RP ID (on a real backend this is server config, never guessed client-side).
+const MOCK_RP_ID = location.hostname;
+const enc = (s) => bytesToBase64Url(new TextEncoder().encode(s));
+const DAY = 86_400_000;
+
+function mockSeed() {
+  const now = Date.now();
+  return {
+    user: { name: 'jamie@example.com', displayName: 'Jamie Rivera', passkeyUserId: enc('dg-user-10482') },
+    credentials: [
+      {
+        id: enc('cred-pixel-8'),
+        name: 'Google Password Manager',
+        aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+        registeredAt: now - 210 * DAY,
+        lastUsedAt: now - 2 * DAY,
+      },
+      {
+        id: enc('cred-macbook'),
+        name: 'Work MacBook',
+        aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+        registeredAt: now - 95 * DAY,
+        lastUsedAt: now - 40 * DAY,
+      },
+      {
+        id: enc('cred-yubikey-5c'),
+        name: 'YubiKey 5 Series',
+        aaguid: 'ee882879-721c-4913-9775-3dfcce97072a',
+        registeredAt: now - 400 * DAY,
+      },
+    ],
+  };
+}
+
+function load() {
+  try {
+    const raw = localStorage.getItem(MOCK_KEY);
+    if (raw) return JSON.parse(raw);
+  } catch {}
+  const seed = mockSeed();
+  save(seed);
+  return seed;
+}
+
+function save(db) {
+  try {
+    localStorage.setItem(MOCK_KEY, JSON.stringify(db));
+  } catch {}
+}
+
+const delay = () => new Promise((r) => setTimeout(r, 250));
+let pendingChallenge = null;
+
+const mockApi = {
+  async listCredentials() {
+    await delay();
+    const db = load();
+    return {
+      rpId: MOCK_RP_ID,
+      userId: db.user.passkeyUserId,
+      user: { name: db.user.name, displayName: db.user.displayName },
+      credentials: db.credentials,
+    };
+  },
+  async renameCredential(id, name) {
+    await delay();
+    const db = load();
+    const cred = db.credentials.find((c) => c.id === id);
+    if (!cred) throw new Error('Credential not found.');
+    cred.name = name;
+    save(db);
+    return cred;
+  },
+  async deleteCredential(id) {
+    await delay();
+    const db = load();
+    const before = db.credentials.length;
+    db.credentials = db.credentials.filter((c) => c.id !== id);
+    if (db.credentials.length === before) throw new Error('Credential not found.');
+    save(db);
+    return { success: true };
+  },
+  async updateUser({ name, displayName }) {
+    await delay();
+    const db = load();
+    db.user.name = name;
+    db.user.displayName = displayName;
+    save(db);
+    return { name, displayName, rpId: MOCK_RP_ID, userId: db.user.passkeyUserId };
+  },
+  async registrationOptions() {
+    await delay();
+    const db = load();
+    pendingChallenge = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
+    return {
+      challenge: pendingChallenge,
+      rp: { id: MOCK_RP_ID, name: 'The Daily Grind' },
+      user: { id: db.user.passkeyUserId, name: db.user.name, displayName: db.user.displayName },
+      pubKeyCredParams: [
+        { type: 'public-key', alg: -7 },
+        { type: 'public-key', alg: -257 },
+      ],
+      excludeCredentials: db.credentials.map((c) => ({ type: 'public-key', id: c.id })),
+      // No authenticatorAttachment so security keys can be registered too.
+      authenticatorSelection: { residentKey: 'required', userVerification: 'preferred' },
+      timeout: 300_000,
+    };
+  },
+  async verifyRegistration(json) {
+    await delay();
+    // A real server verifies challenge, origin, and attestation here.
+    if (!pendingChallenge) throw new Error('No registration in progress.');
+    pendingChallenge = null;
+    const aaguid = readAaguid(json.response?.authenticatorData);
+    const { lookupProvider } = await import('./aaguids.js');
+    const cred = {
+      id: json.id,
+      name: lookupProvider(aaguid)?.name ?? 'Passkey',
+      aaguid,
+      registeredAt: Date.now(),
+    };
+    const db = load();
+    db.credentials.push(cred);
+    save(db);
+    return cred;
+  },
+};
+
+// authenticatorData layout: rpIdHash(32) | flags(1) | signCount(4) | aaguid(16) | ...
+function readAaguid(authenticatorData) {
+  try {
+    const bytes = base64UrlToBytes(authenticatorData).slice(37, 53);
+    const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
+    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+  } catch {
+    return '00000000-0000-0000-0000-000000000000';
+  }
+}
+
+export function createApi(mode) {
+  return mode === 'mock' ? mockApi : httpApi;
+}
