+import { createApi, UnauthorizedError, bytesToBase64Url, base64UrlToBytes } from './passkey-api.js';
+import { lookupProvider } from './aaguids.js';
+
+const root = document.getElementById('passkeys');
+const api = createApi(root.dataset.api);
+
+const listEl = document.getElementById('passkey-list');
+const emptyEl = document.getElementById('passkey-empty');
+const loadingEl = document.getElementById('passkey-loading');
+const statusEl = document.getElementById('passkey-status');
+const createBtn = document.getElementById('create-passkey');
+const unsupportedEl = document.getElementById('passkey-unsupported');
+const syncNoteEl = document.getElementById('passkey-sync-note');
+
+const renameDialog = document.getElementById('rename-dialog');
+const renameForm = renameDialog.querySelector('form');
+const renameInput = document.getElementById('rename-input');
+const renameError = document.getElementById('rename-error');
+
