+const deleteSyncHint = document.getElementById('delete-sync-hint');
+
+const profileForm = document.getElementById('profile-form');
+const profileStatus = document.getElementById('profile-status');
+
+const dateFmt = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+
+/** @type {{ rpId: string, userId: string, user: {name: string, displayName: string}, credentials: any[] } | null} */
+let state = null;
+let activeCredentialId = null;
+
+const signalsSupported = Boolean(window.PublicKeyCredential?.signalAllAcceptedCredentials);
+
+// ---------- Signal API sync ----------
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+function isValidBase64Url(value) {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+async function syncAcceptedCredentials({ rpId, userId, credentials }) {
+  if (!window.PublicKeyCredential?.signalAllAcceptedCredentials) return;
+  const allAcceptedCredentialIds = credentials.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !allAcceptedCredentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL IDs are required.');
+    return;
+  }
+  try {
+    // rpId always comes from the server, never window.location.hostname.
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+async function syncCurrentUserDetails({ rpId, userId, name, displayName }) {
+  if (!window.PublicKeyCredential?.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
+
+// ---------- Rendering ----------
+
+function announce(message, el = statusEl) {
+  el.textContent = '';
+  // Re-set on next frame so repeated identical messages are still announced.
+  requestAnimationFrame(() => (el.textContent = message));
+}
+
+function keyIcon() {
+  const ns = 'http://www.w3.org/2000/svg';
+  const svg = document.createElementNS(ns, 'svg');
+  svg.setAttribute('viewBox', '0 0 24 24');
+  svg.setAttribute('aria-hidden', 'true');
+  svg.classList.add('passkey-icon');
+  const path = document.createElementNS(ns, 'path');
+  path.setAttribute('fill', 'currentColor');
+  path.setAttribute(
+    'd',
+    'M7 14a2 2 0 1 1 0-4 2 2 0 0 1 0 4Zm5.65-4A6 6 0 1 0 12.65 14H17v4h4v-4h2v-4H12.65Z'
+  );
+  svg.append(path);
+  return svg;
+}
+
+function renderCredential(cred) {
+  const tpl = document.getElementById('passkey-item-template');
+  const li = tpl.content.firstElementChild.cloneNode(true);
+  li.dataset.id = cred.id;
+
+  const iconSlot = li.querySelector('.passkey-icon-slot');
+  if (cred.providerIcon) {
+    const img = document.createElement('img');
+    img.src = cred.providerIcon;
+    img.alt = '';
+    img.width = 32;
+    img.height = 32;
+    img.className = 'passkey-icon';
+    iconSlot.append(img);
+  } else {
+    iconSlot.append(keyIcon());
+  }
+
+  li.querySelector('.passkey-name').textContent = cred.name || 'Passkey';
+
+  const provider = lookupProvider(cred.aaguid);
+  const providerEl = li.querySelector('.passkey-provider');
+  if (provider && provider.name !== cred.name) {
+    providerEl.textContent = provider.name;
+  } else {
+    providerEl.remove();
+  }
+
+  const registered = li.querySelector('.passkey-registered');
+  registered.textContent = dateFmt.format(cred.registeredAt);
+  registered.dateTime = new Date(cred.registeredAt).toISOString();
+
+  const used = li.querySelector('.passkey-used');
+  if (cred.lastUsedAt) {
+    used.textContent = dateFmt.format(cred.lastUsedAt);
+    used.dateTime = new Date(cred.lastUsedAt).toISOString();
+  } else {
+    used.replaceWith('Never');
+  }
+
+  const label = cred.name || 'passkey';
+  li.querySelector('[data-action="rename"]').setAttribute('aria-label', `Rename ${label}`);
+  li.querySelector('[data-action="delete"]').setAttribute('aria-label', `Delete ${label}`);
+  return li;
+}
+
+function render() {
+  loadingEl.hidden = true;
+  const creds = [...state.credentials].sort((a, b) => (b.lastUsedAt ?? b.registeredAt) - (a.lastUsedAt ?? a.registeredAt));
+  listEl.replaceChildren(...creds.map(renderCredential));
+  listEl.hidden = creds.length === 0;
+  emptyEl.hidden = creds.length !== 0;
+  document.getElementById('passkey-count').textContent = creds.length ? `(${creds.length})` : '';
+
+  profileForm.elements.name.value = state.user.name;
+  profileForm.elements.displayName.value = state.user.displayName;
+}
+
+async function refresh() {
+  state = await api.listCredentials();
+  render();
+}
+
+function handleError(err, el = statusEl) {
+  if (err instanceof UnauthorizedError) {
+    location.assign(`/login?next=${encodeURIComponent(location.pathname)}`);
+    return;
+  }
+  console.warn(err);
+  announce(err.message || 'Something went wrong. Please try again.', el);
+}
+
+function findCredential(id) {
+  return state?.credentials.find((c) => c.id === id);
+}
+
+// ---------- Rename ----------
+
+function openRename(id) {
+  const cred = findCredential(id);
+  if (!cred) return;
+  activeCredentialId = id;
+  renameInput.value = cred.name ?? '';
+  renameError.textContent = '';
+  renameDialog.showModal();
+  renameInput.select();
+}
+
+renameForm.addEventListener('submit', async (event) => {
+  if (event.submitter?.value !== 'save') return; // Cancel: let method="dialog" close it.
+  event.preventDefault();
+  const name = renameInput.value.trim();
+  if (!name) {
+    renameError.textContent = 'Enter a name for this passkey.';
+    renameInput.focus();
+    return;
+  }
+  const submit = event.submitter;
+  submit.disabled = true;
+  try {
+    // Nickname changes are server-side labels only; no Signal API call needed.
+    await api.renameCredential(activeCredentialId, name);
+    await refresh();
+    renameDialog.close();
+    announce(`Passkey renamed to “${name}”.`);
+    listEl.querySelector(`[data-id="${CSS.escape(activeCredentialId)}"] [data-action="rename"]`)?.focus();
+  } catch (err) {
+    handleError(err, renameError);
+  } finally {
+    submit.disabled = false;
+  }
+});
+
+// ---------- Delete ----------
+
+function openDelete(id) {
+  const cred = findCredential(id);
+  if (!cred) return;
+  activeCredentialId = id;
+  deleteNameEl.textContent = cred.name || 'this passkey';
+  deleteError.textContent = '';
+  deleteSyncHint.hidden = signalsSupported;
+  deleteDialog.showModal();
+}
+
+deleteForm.addEventListener('submit', async (event) => {
+  if (event.submitter?.value !== 'delete') return;
+  event.preventDefault();
+  const submit = event.submitter;
+  const removed = findCredential(activeCredentialId);
+  submit.disabled = true;
+  try {
+    await api.deleteCredential(activeCredentialId);
+    await refresh();
+    deleteDialog.close();
+    // Tell the password manager which credentials remain valid so the deleted one is hidden/removed.
+    await syncAcceptedCredentials(state);
+    announce(`“${removed?.name ?? 'Passkey'}” was deleted.`);
+    (listEl.querySelector('[data-action="rename"]') ?? createBtn).focus();
+  } catch (err) {
+    handleError(err, deleteError);
+  } finally {
+    submit.disabled = false;
+  }
+});
+
+listEl.addEventListener('click', (event) => {
+  const button = event.target.closest('button[data-action]');
+  if (!button) return;
+  const id = button.closest('[data-id]').dataset.id;
+  if (button.dataset.action === 'rename') openRename(id);
+  else if (button.dataset.action === 'delete') openDelete(id);
+});
+
+// ---------- Profile (username / display name) ----------
+
+profileForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  const name = profileForm.elements.name.value.trim();
+  const displayName = profileForm.elements.displayName.value.trim();
+  const submit = profileForm.querySelector('[type="submit"]');
+  submit.disabled = true;
+  try {
+    const updated = await api.updateUser({ name, displayName });
+    state.user = { name: updated.name, displayName: updated.displayName };
+    await syncCurrentUserDetails({ rpId: updated.rpId, userId: updated.userId, name: updated.name, displayName: updated.displayName });
+    announce(
+      signalsSupported ? 'Profile saved and updated in your password manager.' : 'Profile saved.',
+      profileStatus
+    );
+  } catch (err) {
+    handleError(err, profileStatus);
+  } finally {
+    submit.disabled = false;
+  }
+});
+
+// ---------- Create passkey ----------
+
+async function isPasskeySupported() {
+  if (!window.PublicKeyCredential) return false;
+  try {
+    if (PublicKeyCredential.getClientCapabilities) {
+      const caps = await PublicKeyCredential.getClientCapabilities();
+      return Boolean(caps.passkeyPlatformAuthenticator);
+    }
+    // Lightweight fallback for browsers without getClientCapabilities().
+    return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+  } catch {
+    return false;
+  }
+}
+
+function parseCreationOptions(json) {
+  if (PublicKeyCredential.parseCreationOptionsFromJSON) {
+    return PublicKeyCredential.parseCreationOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: base64UrlToBytes(json.challenge),
+    user: { ...json.user, id: base64UrlToBytes(json.user.id) },
+    excludeCredentials: (json.excludeCredentials ?? []).map((c) => ({ ...c, id: base64UrlToBytes(c.id) })),
+  };
+}
+
+function credentialToJSON(cred) {
+  if (typeof cred.toJSON === 'function') {
+    try {
+      return cred.toJSON();
+    } catch {}
+  }
+  return {
+    id: cred.id,
+    rawId: bytesToBase64Url(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? undefined,
+    clientExtensionResults: cred.getClientExtensionResults(),
+    response: {
+      clientDataJSON: bytesToBase64Url(cred.response.clientDataJSON),
+      attestationObject: bytesToBase64Url(cred.response.attestationObject),
+      authenticatorData: bytesToBase64Url(cred.response.getAuthenticatorData()),
+      transports: cred.response.getTransports?.() ?? [],
+    },
+  };
+}
+
+createBtn.addEventListener('click', async () => {
+  createBtn.disabled = true;
+  try {
+    const options = parseCreationOptions(await api.registrationOptions());
+    const credential = await navigator.credentials.create({ publicKey: options });
+    const saved = await api.verifyRegistration(credentialToJSON(credential));
+    await refresh();
+    announce(`Passkey “${saved.name}” created.`);
+  } catch (err) {
+    if (err?.name === 'NotAllowedError' || err?.name === 'AbortError') {
+      announce('Passkey creation was cancelled.');
+    } else if (err?.name === 'InvalidStateError') {
+      announce('This device already has a passkey for your account.');
+    } else {
+      handleError(err);
+    }
+  } finally {
+    createBtn.disabled = false;
+  }
+});
+
+// ---------- Init ----------
+
+async function init() {
+  syncNoteEl.hidden = !signalsSupported;
+  isPasskeySupported().then((supported) => {
+    createBtn.hidden = !supported;
+    unsupportedEl.hidden = supported;
+  });
+
+  try {
+    await refresh();
+    // Keep the browser / password manager in sync with the server on every visit.
+    await syncAcceptedCredentials(state);
+  } catch (err) {
+    loadingEl.hidden = true;
+    handleError(err);
+  }
+}
+
+init();

