+++ b/assets/passkeys.js
@@ -0,0 +1,526 @@
+/*
+ * Passkey management for /account.
+ *
+ * Expected account API (same-origin, cookie session):
+ *   GET    /api/account                 -> { userId, name, displayName }
+ *                                          userId: base64url WebAuthn user handle
+ *   GET    /api/account/passkeys        -> { passkeys: [Passkey] }
+ *   PATCH  /api/account/passkeys/:id    body { name }  -> Passkey
+ *   DELETE /api/account/passkeys/:id    -> 204
+ *
+ *   Passkey = {
+ *     id,                 // server record id
+ *     credentialId,       // base64url WebAuthn credential ID
+ *     name,               // user-facing nickname
+ *     createdAt,          // ISO 8601
+ *     lastUsedAt,         // ISO 8601 | null
+ *     providerName,       // e.g. "Google Password Manager" (from AAGUID) | null
+ *     backedUp,           // boolean: synced passkey
+ *     currentSession      // boolean: used to sign in to this session
+ *   }
+ *
+ * A 401 redirects to /login. If the API is unreachable (static preview
+ * hosting), the page falls back to a local preview mode with sample data and
+ * never signals the browser's authenticator.
+ *
+ * Browser sync uses the WebAuthn Signal API so that deleted passkeys are
+ * removed/hidden from the user's password manager and account details stay
+ * current:
+ *   PublicKeyCredential.signalAllAcceptedCredentials()
+ *   PublicKeyCredential.signalCurrentUserDetails()
+ */
+(function () {
+  'use strict';
+
+  var API_BASE = '/api/account';
+  var NAME_MAX = 64;
+  var DEMO_STORAGE_KEY = 'dailygrind.demoPasskeys';
+  var RP_ID = window.location.hostname;
+
+  var state = {
+    user: null,
+    passkeys: [],
+    demo: false,
+    renameTarget: null,
+    deleteTarget: null
+  };
+
+  var $ = function (id) { return document.getElementById(id); };
+  var els = {};
+
+  // ---------------------------------------------------------------------------
+  // API layer
+  // ---------------------------------------------------------------------------
+
+  function ApiError(message, status) {
+    this.name = 'ApiError';
+    this.message = message;
+    this.status = status;
+  }
+  ApiError.prototype = Object.create(Error.prototype);
+
+  function csrfToken() {
+    var meta = document.querySelector('meta[name="csrf-token"]');
+    return meta ? meta.getAttribute('content') : null;
+  }
+
+  function request(method, path, body) {
+    var headers = { 'Accept': 'application/json' };
+    if (body !== undefined) headers['Content-Type'] = 'application/json';
+    if (method !== 'GET') {
+      var token = csrfToken();
+      if (token) headers['X-CSRF-Token'] = token;
+    }
+    return fetch(API_BASE + path, {
+      method: method,
+      credentials: 'same-origin',
+      headers: headers,
+      body: body === undefined ? undefined : JSON.stringify(body)
+    }).then(function (res) {
+      if (res.status === 401) {
+        window.location.href = '/login?next=' + encodeURIComponent('/account#security');
+        throw new ApiError('Your session has expired. Please sign in again.', 401);
+      }
+      if (res.status === 204) return null;
+      var isJson = (res.headers.get('Content-Type') || '').indexOf('application/json') !== -1;
+      var parsed = isJson ? res.json() : Promise.resolve(null);
+      return parsed.then(function (data) {
+        if (!res.ok) {
+          var msg = (data && (data.message || data.error)) || 'Request failed (' + res.status + ').';
+          throw new ApiError(msg, res.status);
+        }
+        if (!isJson) throw new ApiError('Unexpected response from the server.', res.status);
+        return data;
+      });
+    }, function () {
+      throw new ApiError('Network error. Check your connection and try again.', 0);
+    });
+  }
+
+  var remoteApi = {
+    getUser: function () { return request('GET', ''); },
+    list: function () {
+      return request('GET', '/passkeys').then(function (d) { return (d && d.passkeys) || []; });
+    },
+    rename: function (id, name) {
+      return request('PATCH', '/passkeys/' + encodeURIComponent(id), { name: name });
+    },
+    remove: function (id) {
+      return request('DELETE', '/passkeys/' + encodeURIComponent(id));
+    }
+  };
+
+  // Local preview data so the UI is usable on static hosting without a backend.
+  var demoApi = (function () {
+    var day = 86400000;
+    var now = Date.now();
+    var seed = [
+      { id: 'pk_demo_1', credentialId: 'ZGVtby1jcmVkLTE', name: 'MacBook Pro', providerName: 'iCloud Keychain',
+        createdAt: new Date(now - 220 * day).toISOString(), lastUsedAt: new Date(now - 600000).toISOString(),
+        backedUp: true, currentSession: true },
+      { id: 'pk_demo_2', credentialId: 'ZGVtby1jcmVkLTI', name: 'Pixel 8', providerName: 'Google Password Manager',
+        createdAt: new Date(now - 95 * day).toISOString(), lastUsedAt: new Date(now - 6 * day).toISOString(),
+        backedUp: true, currentSession: false },
+      { id: 'pk_demo_3', credentialId: 'ZGVtby1jcmVkLTM', name: 'YubiKey 5C', providerName: 'YubiKey 5 Series',
+        createdAt: new Date(now - 400 * day).toISOString(), lastUsedAt: null,
+        backedUp: false, currentSession: false }
+    ];
+    function load() {
+      try {
+        var raw = window.localStorage.getItem(DEMO_STORAGE_KEY);
+        if (raw) return JSON.parse(raw);
+      } catch (e) { /* ignore */ }
+      return seed.slice();
+    }
+    function save(list) {
+      try { window.localStorage.setItem(DEMO_STORAGE_KEY, JSON.stringify(list)); } catch (e) { /* ignore */ }
+    }
+    function delay(v) { return new Promise(function (r) { setTimeout(function () { r(v); }, 250); }); }
+    return {
+      getUser: function () {
+        return delay({ userId: 'ZGVtby11c2Vy', name: 'customer@example.com', displayName: 'Coffee Lover' });
+      },
+      list: function () { return delay(load()); },
+      rename: function (id, name) {
+        var list = load();
+        var item = list.filter(function (p) { return p.id === id; })[0];
+        if (!item) return Promise.reject(new ApiError('Passkey not found.', 404));
+        item.name = name;
+        save(list);
+        return delay(item);
+      },
+      remove: function (id) {
+        save(load().filter(function (p) { return p.id !== id; }));
+        return delay(null);
+      }
+    };
+  })();
+
+  function api() { return state.demo ? demoApi : remoteApi; }
+
+  // ---------------------------------------------------------------------------
+  // Browser authenticator sync (WebAuthn Signal API)
+  // ---------------------------------------------------------------------------
+
+  function signalSupported(method) {
+    return typeof window.PublicKeyCredential !== 'undefined' &&
+      typeof window.PublicKeyCredential[method] === 'function';
+  }
+
+  function canSync() {
+    return !state.demo && state.user && typeof state.user.userId === 'string' && state.user.userId.length > 0;
+  }
+
+  // Tells the browser/password manager the full set of credential IDs the
+  // server still accepts for this user. Any other passkey for this user on
+  // this RP is hidden or removed by the authenticator.
+  function syncAcceptedCredentials() {
+    if (!canSync() || !signalSupported('signalAllAcceptedCredentials')) return Promise.resolve(false);
+    var ids = state.passkeys
+      .map(function (p) { return p.credentialId; })
+      .filter(function (id) { return typeof id === 'string' && id.length > 0; });
+    return window.PublicKeyCredential.signalAllAcceptedCredentials({
+      rpId: RP_ID,
+      userId: state.user.userId,
+      allAcceptedCredentialIds: ids
+    }).then(function () { return true; }, function (err) {
+      console.warn('signalAllAcceptedCredentials failed', err);
+      return false;
+    });
+  }
+
+  function syncUserDetails() {
+    if (!canSync() || !signalSupported('signalCurrentUserDetails')) return Promise.resolve(false);
+    if (!state.user.name) return Promise.resolve(false);
+    return window.PublicKeyCredential.signalCurrentUserDetails({
+      rpId: RP_ID,
+      userId: state.user.userId,
+      name: state.user.name,
+      displayName: state.user.displayName || state.user.name
+    }).then(function () { return true; }, function (err) {
+      console.warn('signalCurrentUserDetails failed', err);
+      return false;
+    });
+  }
+
+  // ---------------------------------------------------------------------------
+  // Rendering
+  // ---------------------------------------------------------------------------
+
+  var dateFmt = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
+  var relFmt = typeof Intl.RelativeTimeFormat === 'function'
+    ? new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })
+    : null;
+
+  function parseDate(iso) {
+    if (!iso) return null;
+    var d = new Date(iso);
+    return isNaN(d.getTime()) ? null : d;
+  }
+
+  function relative(d) {
+    var diff = (d.getTime() - Date.now()) / 1000;
+    var abs = Math.abs(diff);
+    if (!relFmt || abs > 30 * 86400) return dateFmt.format(d);
+    if (abs < 60) return 'just now';
+    if (abs < 3600) return relFmt.format(Math.round(diff / 60), 'minute');
+    if (abs < 86400) return relFmt.format(Math.round(diff / 3600), 'hour');
+    return relFmt.format(Math.round(diff / 86400), 'day');
+  }
+
+  function setStatus(message, isError) {
+    els.status.textContent = message || '';
+    els.status.classList.toggle('is-error', !!isError);
+  }
+
+  function showOnly(which) {
+    els.loading.hidden = which !== 'loading';
+    els.error.hidden = which !== 'error';
+    els.empty.hidden = which !== 'empty';
+    els.list.hidden = which !== 'list';
+  }
+
+  function render() {
+    if (state.passkeys.length === 0) {
+      els.list.replaceChildren();
+      showOnly('empty');
+      return;
+    }
+    var frag = document.createDocumentFragment();
+    state.passkeys.forEach(function (pk) {
+      var node = els.template.content.firstElementChild.cloneNode(true);
+      node.dataset.id = pk.id;
+      var name = pk.name || 'Unnamed passkey';
+      node.querySelector('.passkey-name').textContent = name;
+      node.querySelector('.badge-current').hidden = !pk.currentSession;
+      node.querySelector('.badge-synced').hidden = !pk.backedUp;
+      node.querySelector('.passkey-provider').textContent = pk.providerName || '';
+
+      var created = parseDate(pk.createdAt);
+      node.querySelector('.passkey-created').textContent = created ? 'Added ' + dateFmt.format(created) : '';
+      var used = parseDate(pk.lastUsedAt);
+      node.querySelector('.passkey-used').textContent = used ? 'Last used ' + relative(used) : 'Never used';
+
+      var renameBtn = node.querySelector('[data-action="rename"]');
+      var deleteBtn = node.querySelector('[data-action="delete"]');
+      renameBtn.setAttribute('aria-label', 'Rename ' + name);
+      deleteBtn.setAttribute('aria-label', 'Delete ' + name);
+      frag.appendChild(node);
+    });
+    els.list.replaceChildren(frag);
+    showOnly('list');
+  }
+
+  function findPasskey(id) {
+    return state.passkeys.filter(function (p) { return p.id === id; })[0] || null;
+  }
+
+  function itemNode(id) {
+    var nodes = els.list.querySelectorAll('.passkey-item');
+    for (var i = 0; i < nodes.length; i++) if (nodes[i].dataset.id === id) return nodes[i];
+    return null;
+  }
+
+  // ---------------------------------------------------------------------------
+  // Loading
+  // ---------------------------------------------------------------------------
+
+  function isBackendMissing(err) {
+    // No API on this host (static hosting) -> preview mode.
+    return err && (err.status === 0 || err.status === 404 || err.status === 405 ||
+      (err.status === 200 && /Unexpected response/.test(err.message)));
+  }
+
+  function load() {
+    showOnly('loading');
+    setStatus('');
+    return Promise.all([api().getUser(), api().list()])
+      .catch(function (err) {
+        if (!state.demo && isBackendMissing(err)) {
+          state.demo = true;
+          els.demoBanner.hidden = false;
+          return Promise.all([demoApi.getUser(), demoApi.list()]);
+        }
+        throw err;
+      })
+      .then(function (results) {
+        state.user = results[0] || {};
+        state.passkeys = Array.isArray(results[1]) ? results[1] : [];
+        if (state.user.displayName || state.user.name) {
+          els.greeting.textContent = 'Hi ' + (state.user.displayName || state.user.name) +
+            ' — manage how you sign in to The Daily Grind.';
+        }
+        els.syncUnsupported.hidden = state.demo || signalSupported('signalAllAcceptedCredentials');
+        render();
+        // Reconcile the browser's passkey list with the server on every visit,
+        // so passkeys removed elsewhere (e.g. on another device) disappear too.
+        syncAcceptedCredentials();
+        syncUserDetails();
+      })
+      .catch(function (err) {
+        if (err && err.status === 401) return;
+        els.errorText.textContent = (err && err.message) || "We couldn't load your passkeys.";
+        showOnly('error');
+      });
+  }
+
+  // ---------------------------------------------------------------------------
+  // Rename
+  // ---------------------------------------------------------------------------
+
+  function validateName(raw) {
+    var name = raw.replace(/\s+/g, ' ').trim();
+    if (!name) return { error: 'Please enter a name.' };
+    if (name.length > NAME_MAX) return { error: 'Names can be up to ' + NAME_MAX + ' characters.' };
+    var dup = state.passkeys.some(function (p) {
+      return p.id !== state.renameTarget.id && (p.name || '').toLowerCase() === name.toLowerCase();
+    });
+    if (dup) return { error: 'You already have a passkey with that name.' };
+    return { name: name };
+  }
+
+  function openRename(pk) {
+    state.renameTarget = pk;
+    els.renameInput.value = pk.name || '';
+    els.renameError.textContent = '';
+    els.renameSubmit.disabled = false;
+    els.renameDialog.showModal();
+    els.renameInput.select();
+  }
+
+  function submitRename(e) {
+    e.preventDefault();
+    var pk = state.renameTarget;
+    if (!pk) return;
+    var result = validateName(els.renameInput.value);
+    if (result.error) {
+      els.renameError.textContent = result.error;
+      els.renameInput.focus();
+      return;
+    }
+    if (result.name === pk.name) {
+      els.renameDialog.close();
+      return;
+    }
+    els.renameSubmit.disabled = true;
+    els.renameError.textContent = '';
+    api().rename(pk.id, result.name).then(function (updated) {
+      var target = findPasskey(pk.id);
+      if (target) {
+        if (updated && typeof updated === 'object' && updated.id === pk.id) {
+          Object.assign(target, updated);
+        } else {
+          target.name = result.name;
+        }
+      }
+      els.renameDialog.close();
+      render();
+      setStatus('Passkey renamed to “' + result.name + '”.');
+      focusItem(pk.id, 'rename');
+    }, function (err) {
+      if (err && err.status === 404) {
+        els.renameDialog.close();
+        return handleMissing(pk);
+      }
+      els.renameError.textContent = (err && err.message) || 'Could not rename passkey.';
+      els.renameSubmit.disabled = false;
+    });
+  }
+
+  // ---------------------------------------------------------------------------
+  // Delete
+  // ---------------------------------------------------------------------------
+
+  function openDelete(pk) {
+    state.deleteTarget = pk;
+    els.deleteName.textContent = pk.name || 'this passkey';
+    els.deleteLastWarning.hidden = state.passkeys.length > 1;
+    els.deleteCurrentWarning.hidden = !pk.currentSession;
+    els.deleteError.textContent = '';
+    els.deleteSubmit.disabled = false;
+    els.deleteDialog.showModal();
+    // Default focus on the safe choice.
+    els.deleteDialog.querySelector('[data-close]').focus();
+  }
+
+  function removeLocally(id) {
+    var idx = state.passkeys.findIndex(function (p) { return p.id === id; });
+    var next = idx + 1 < state.passkeys.length ? state.passkeys[idx + 1] : state.passkeys[idx - 1];
+    state.passkeys = state.passkeys.filter(function (p) { return p.id !== id; });
+    return next ? next.id : null;
+  }
+
+  function afterRemoval(pk, nextId, message) {
+    render();
+    syncAcceptedCredentials().then(function (synced) {
+      var suffix = synced
+        ? ' Your browser’s passkey list has been updated.'
+        : state.demo ? '' : ' Also remove it from your device’s passkey settings.';
+      setStatus(message + suffix);
+    });
+    setStatus(message);
+    if (nextId) focusItem(nextId, 'delete');
+    else els.heading.focus();
+  }
+
+  // The passkey was already removed server-side (e.g. from another device).
+  function handleMissing(pk) {
+    var nextId = removeLocally(pk.id);
+    afterRemoval(pk, nextId, '“' + (pk.name || 'Passkey') + '” was already removed.');
+  }
+
+  function submitDelete(e) {
+    e.preventDefault();
+    var pk = state.deleteTarget;
+    if (!pk) return;
+    els.deleteSubmit.disabled = true;
+    els.deleteError.textContent = '';
+    var node = itemNode(pk.id);
+    if (node) node.classList.add('is-busy');
+    api().remove(pk.id).then(function () {
+      els.deleteDialog.close();
+      var nextId = removeLocally(pk.id);
+      afterRemoval(pk, nextId, '“' + (pk.name || 'Passkey') + '” was deleted.');
+    }, function (err) {
+      if (node) node.classList.remove('is-busy');
+      if (err && err.status === 404) {
+        els.deleteDialog.close();
+        return handleMissing(pk);
+      }
+      els.deleteError.textContent = (err && err.message) || 'Could not delete passkey.';
+      els.deleteSubmit.disabled = false;
+    });
+  }
+
+  function focusItem(id, action) {
+    var node = itemNode(id);
+    var btn = node && node.querySelector('[data-action="' + action + '"]');
+    if (btn) btn.focus();
+  }
+
+  // ---------------------------------------------------------------------------
+  // Init
+  // ---------------------------------------------------------------------------
+
+  function init() {
+    els = {
+      status: $('status'),
+      loading: $('passkeys-loading'),
+      error: $('passkeys-error'),
+      errorText: $('passkeys-error-text'),
+      empty: $('passkeys-empty'),
+      list: $('passkey-list'),
+      template: $('passkey-item-template'),
+      demoBanner: $('demo-banner'),
+      syncUnsupported: $('sync-unsupported'),
+      greeting: $('account-greeting'),
+      heading: $('passkeys-heading'),
+      renameDialog: $('rename-dialog'),
+      renameForm: $('rename-form'),
+      renameInput: $('rename-input'),
+      renameError: $('rename-error'),
+      renameSubmit: $('rename-submit'),
+      deleteDialog: $('delete-dialog'),
+      deleteForm: $('delete-form'),
+      deleteName: $('delete-name'),
+      deleteLastWarning: $('delete-last-warning'),
+      deleteCurrentWarning: $('delete-current-warning'),
+      deleteError: $('delete-error'),
+      deleteSubmit: $('delete-submit')
+    };
+    els.heading.setAttribute('tabindex', '-1');
+
+    els.list.addEventListener('click', function (e) {
+      var btn = e.target.closest('button[data-action]');
+      if (!btn) return;
+      var item = btn.closest('.passkey-item');
+      var pk = item && findPasskey(item.dataset.id);
+      if (!pk) return;
+      if (btn.dataset.action === 'rename') openRename(pk);
+      else if (btn.dataset.action === 'delete') openDelete(pk);
+    });
+
+    els.renameForm.addEventListener('submit', submitRename);
+    els.renameInput.addEventListener('input', function () { els.renameError.textContent = ''; });
+    els.deleteForm.addEventListener('submit', submitDelete);
+
+    [els.renameDialog, els.deleteDialog].forEach(function (dlg) {
+      dlg.querySelector('[data-close]').addEventListener('click', function () { dlg.close(); });
