+/**
+ * Small subset of the community AAGUID registry
+ * (github.com/passkeydeveloper/passkey-authenticator-aaguids), used purely as
+ * a UX hint for naming the provider of each passkey. Never use it for
+ * security decisions.
+ */
+export interface PasskeyProvider {
+  name: string;
+  /** Tailwind classes for the provider badge. */
+  badge: string;
+}
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+const providers: Record<string, PasskeyProvider> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', badge: 'bg-blue-100 text-blue-800' },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain', badge: 'bg-gray-200 text-gray-800' },
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': { name: 'iCloud Keychain (Managed)', badge: 'bg-gray-200 text-gray-800' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', badge: 'bg-sky-100 text-sky-800' },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden', badge: 'bg-indigo-100 text-indigo-800' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello', badge: 'bg-cyan-100 text-cyan-800' },
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': { name: 'Windows Hello', badge: 'bg-cyan-100 text-cyan-800' },
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': { name: 'Windows Hello', badge: 'bg-cyan-100 text-cyan-800' },
+  '531126d6-e717-415c-9320-3d9aa6981239': { name: 'Dashlane', badge: 'bg-emerald-100 text-emerald-800' },
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': { name: 'YubiKey 5 Series', badge: 'bg-lime-100 text-lime-800' },
+};
+
+export function getProvider(aaguid: string): PasskeyProvider {
+  if (aaguid === ZERO_AAGUID) return { name: 'Unknown passkey provider', badge: 'bg-gray-100 text-gray-700' };
+  return providers[aaguid] ?? { name: 'Unknown passkey provider', badge: 'bg-gray-100 text-gray-700' };
+}
diff --git a/src/lib/account.ts b/src/lib/account.ts
new file mode 100644
index 0000000..d1e8802
--- /dev/null
+++ b/src/lib/account.ts
@@ -0,0 +1,175 @@
+
+/**
+ * Session-backed account + passkey store.
+ *
+ * The DevTools Times has no first-party user database (sign-in is delegated to
+ * the remote `times_cdn` API), so the signed-in reader's profile and their
+ * registered passkeys live in the Astro session, just like the reading list.
+ * Swap these helpers for real DB calls when a persistent backend exists.
+ */
+
+type Session = NonNullable<import('astro').APIContext['session']>;
+
+export interface Account {
+  /** Account username (WebAuthn `user.name`). */
+  name: string;
+  /** Human-friendly name shown by password managers (WebAuthn `user.displayName`). */
+  displayName: string;
+  /** WebAuthn user handle as unpadded Base64URL. */
+  passkeyUserId: string;
+}
+
+export interface StoredPasskeyCredential {
+  /** Credential ID as unpadded Base64URL. */
+  id: string;
+  /** User-chosen nickname (defaults to the provider name). */
+  name: string;
+  aaguid: string;
+  /** Raw epoch milliseconds. */
+  registeredAt: number;
+  /** Raw epoch milliseconds, if the passkey has ever been used to sign in. */
+  lastUsedAt?: number;
+}
+
+export const MAX_NAME_LENGTH = 64;
+
+const ACCOUNT_KEY = 'account';
+const PASSKEYS_KEY = 'passkeys';
+
+/**
+ * Relying Party ID that passkeys were registered against. Prefer an explicit
+ * configuration; otherwise fall back to the host the server is answering on.
+ * The client always receives this value from the server and never derives it
+ * from `window.location`.
+ */
+export function getRpId(url: URL): string {
+  return import.meta.env.PASSKEY_RP_ID || process.env.PASSKEY_RP_ID || url.hostname;
+}
+
+function randomBase64Url(bytes: number): string {
+  const buf = new Uint8Array(bytes);
+  crypto.getRandomValues(buf);
+  return Buffer.from(buf).toString('base64url');
+}
+
+/** Normalize a user-supplied name: trim, collapse whitespace, cap length. */
+export function sanitizeName(value: unknown): string | null {
+  if (typeof value !== 'string') return null;
+  const cleaned = value.replace(/\s+/g, ' ').trim();
+  if (!cleaned || cleaned.length > MAX_NAME_LENGTH) return null;
+  return cleaned;
+}
+
+export async function getAccount(session: Session | undefined): Promise<Account | null> {
+  if (!session) return null;
+  return ((await session.get(ACCOUNT_KEY)) as Account | undefined) ?? null;
+}
+
+export async function signIn(session: Session, username: string): Promise<Account> {
+  const existing = await getAccount(session);
+  if (existing && existing.name === username) return existing;
+
+  const account: Account = {
+    name: username,
+    displayName: username,
+    passkeyUserId: randomBase64Url(16),
+  };
+  // A new identity on this session gets a fresh credential list.
+  await session.regenerate();
+  await session.set(ACCOUNT_KEY, account);
+  await session.set(PASSKEYS_KEY, seedPasskeys());
+  return account;
+}
+
+export async function signOut(session: Session): Promise<void> {
+  session.destroy();
+}
+
+export async function updateAccount(
+  session: Session,
+  account: Account,
+  changes: Pick<Account, 'displayName'>,
+): Promise<Account> {
+  const updated = { ...account, ...changes };
+  await session.set(ACCOUNT_KEY, updated);
+  return updated;
+}
+
+export async function listPasskeys(session: Session): Promise<StoredPasskeyCredential[]> {
+  const stored = (await session.get(PASSKEYS_KEY)) as StoredPasskeyCredential[] | undefined;
+  return [...(stored ?? [])].sort((a, b) => b.registeredAt - a.registeredAt);
+}
+
+export async function renamePasskey(
+  session: Session,
+  id: string,
+  name: string,
+): Promise<StoredPasskeyCredential | null> {
+  const passkeys = await listPasskeys(session);
+  const target = passkeys.find((p) => p.id === id);
+  if (!target) return null;
+  target.name = name;
+  await session.set(PASSKEYS_KEY, passkeys);
+  return target;
+}
+
+export async function deletePasskey(session: Session, id: string): Promise<boolean> {
+  const passkeys = await listPasskeys(session);
+  const remaining = passkeys.filter((p) => p.id !== id);
+  if (remaining.length === passkeys.length) return false;
+  await session.set(PASSKEYS_KEY, remaining);
+  return true;
+}
+
+/**
+ * Demo credentials so the management UI has something to show. IDs are real
+ * unpadded Base64URL strings, as required by the WebAuthn Signal API.
+ */
+function seedPasskeys(): StoredPasskeyCredential[] {
+  const day = 24 * 60 * 60 * 1000;
+  const now = Date.now();
+  return [
+    {
+      id: randomBase64Url(32),
+      name: 'Google Password Manager',
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      registeredAt: now - 120 * day,
+      lastUsedAt: now - 2 * day,
+    },
+    {
+      id: randomBase64Url(32),
+      name: 'iCloud Keychain',
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+      registeredAt: now - 45 * day,
+      lastUsedAt: now - 9 * day,
+    },
+    {
+      id: randomBase64Url(32),
+      name: 'Old security key',
+      aaguid: 'cb69481e-8ff7-4039-93ec-0a2729a154a8',
+      registeredAt: now - 400 * day,
+    },
+  ];
+}
+
+export function json(body: unknown, status = 200): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+/**
+ * Requires a JSON body. Because `checkOrigin` is disabled in astro.config, this
+ * forces a CORS preflight for cross-site requests and acts as CSRF protection.
+ */
+export async function readJson(request: Request): Promise<Record<string, unknown> | null> {
+  if (!request.headers.get('content-type')?.includes('application/json')) return null;
+  try {
+    const body = await request.json();
+    return body && typeof body === 'object' ? body : null;
+  } catch {
+    return null;
+  }
+}
+
