@@ -0,0 +1,52 @@
+---
+import Layout from '../layouts/Layout.astro';
+import PasskeyManager from '../components/PasskeyManager';
+import { getAccount } from '../lib/account';
+
+const baseUrl = import.meta.env.BASE_URL;
+const account = await getAccount(Astro.session);
+
+if (!account) {
+  return Astro.redirect(`${baseUrl}signin?next=account`);
+}
+
+Astro.response.headers.set('Cache-Control', 'no-store');
+---
+
+<Layout title="Account settings | The DevTools Times">
+  <div class="mx-auto max-w-3xl px-4 py-12 sm:px-6 lg:px-8">
+    <div class="mb-8 flex flex-wrap items-end justify-between gap-4 border-b border-gray-300 pb-4">
+      <div>
+        <h1 class="text-3xl font-bold text-gray-900">Account settings</h1>
+        <p class="mt-1 text-sm text-gray-600">Manage your profile and how you sign in to The DevTools Times.</p>
+      </div>
+      <button
+        type="button"
+        id="sign-out"
+        data-api={`${baseUrl}api/session`}
+        data-home={baseUrl}
+        class="rounded-md border border-gray-300 px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50"
+      >
+        Sign out
+      </button>
+    </div>
+    <PasskeyManager
+      client:load
+      baseUrl={baseUrl}
+      username={account.name}
+      initialDisplayName={account.displayName}
+    />
+  </div>
+</Layout>
+
+<script>
+  document.addEventListener('astro:page-load', () => {
+    const button = document.getElementById('sign-out');
+    if (!button || button.dataset.bound) return;
+    button.dataset.bound = 'true';
+    button.addEventListener('click', async () => {
+      await fetch(button.dataset.api!, { method: 'DELETE' });
+      window.location.assign(button.dataset.home!);
+    });
+  });
+</script>
diff --git a/src/pages/api/account/passkeys/[id].ts b/src/pages/api/account/passkeys/[id].ts
new file mode 100644
index 0000000..57a9f6a
--- /dev/null
+++ b/src/pages/api/account/passkeys/[id].ts
@@ -0,0 +1,39 @@
+import type { APIRoute } from 'astro';
+import {
+  deletePasskey,
+  getAccount,
+  getRpId,
+  json,
+  listPasskeys,
+  readJson,
+  renamePasskey,
+  sanitizeName,
+} from '../../../../lib/account';
+
+export const PATCH: APIRoute = async ({ params, request, session }) => {
+  const account = await getAccount(session);
+  if (!account || !session) return json({ error: 'Not signed in.' }, 401);
+
+  const body = await readJson(request);
+  const name = sanitizeName(body?.name);
+  if (!name) return json({ error: 'Passkey name must be 1–64 characters.' }, 400);
+
+  const updated = await renamePasskey(session, params.id ?? '', name);
+  if (!updated) return json({ error: 'Passkey not found.' }, 404);
+  return json(updated);
+};
+
+export const DELETE: APIRoute = async ({ params, session, url }) => {
+  const account = await getAccount(session);
+  if (!account || !session) return json({ error: 'Not signed in.' }, 401);
+
+  const removed = await deletePasskey(session, params.id ?? '');
+  if (!removed) return json({ error: 'Passkey not found.' }, 404);
+
+  // Return the remaining list so the client can sync it with the authenticator.
+  return json({
+    rpId: getRpId(url),
+    userId: account.passkeyUserId,
+    credentials: await listPasskeys(session),
+  });
+};
