+import type { APIRoute } from 'astro';
+import { getAccount, getRpId, json, readJson, sanitizeName, updateAccount } from '../../../lib/account';
+
+export const GET: APIRoute = async ({ session, url }) => {
+  const account = await getAccount(session);
+  if (!account) return json({ error: 'Not signed in.' }, 401);
+  return json({ name: account.name, displayName: account.displayName, rpId: getRpId(url), userId: account.passkeyUserId });
+};
+
+export const PUT: APIRoute = async ({ request, session, url }) => {
+  const account = await getAccount(session);
+  if (!account || !session) return json({ error: 'Not signed in.' }, 401);
+
+  const body = await readJson(request);
+  const displayName = sanitizeName(body?.displayName);
+  if (!displayName) return json({ error: 'Display name must be 1–64 characters.' }, 400);
+
+  const updated = await updateAccount(session, account, { displayName });
+  return json({ name: updated.name, displayName: updated.displayName, rpId: getRpId(url), userId: updated.passkeyUserId });
+};
diff --git a/src/pages/api/session.ts b/src/pages/api/session.ts
new file mode 100644
