+++ b/src/pages/api/session.ts
@@ -0,0 +1,21 @@
+import type { APIRoute } from 'astro';
+import { json, readJson, sanitizeName, signIn, signOut } from '../../lib/account';
+
+/**
+ * Records the signed-in reader in the local session after the remote login
+ * API has accepted their credentials.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) return json({ error: 'Sessions are unavailable.' }, 500);
+  const body = await readJson(request);
+  const username = sanitizeName(body?.username);
+  if (!username) return json({ error: 'A valid username is required.' }, 400);
+
+  const account = await signIn(session, username);
+  return json({ name: account.name, displayName: account.displayName });
+};
+
+export const DELETE: APIRoute = async ({ session }) => {
+  if (session) await signOut(session);
+  return json({ success: true });
+};
