diff --git a/src/components/PasskeyManager.tsx b/src/components/PasskeyManager.tsx
new file mode 100644
index 0000000..8665d69
--- /dev/null
+++ b/src/components/PasskeyManager.tsx
@@ -0,0 +1,498 @@
+import React, { useCallback, useEffect, useRef, useState } from 'react';
+import { KeyIcon, PencilSquareIcon, TrashIcon, CloudIcon, DevicePhoneMobileIcon } from '@heroicons/react/24/outline';
+
+interface Passkey {
+  id: string;
+  name: string;
+  createdAt: string;
+  lastUsedAt: string | null;
+  transports: string[];
+  backupEligible: boolean;
+  backedUp: boolean;
+}
+
+interface PasskeyListResponse {
+  rpId: string;
+  userId: string | null;
+  username: string;
+  passkeys: Passkey[];
+}
+
+type Notice = { kind: 'success' | 'error' | 'info'; text: string } | null;
+
+const MAX_NAME_LENGTH = 64;
+const apiBase = `${import.meta.env.BASE_URL.replace(/\/?$/, '/')}api/account/passkeys`;
+
+// ---------------------------------------------------------------------------
+// WebAuthn helpers
+// ---------------------------------------------------------------------------
+
+function bufferToBase64Url(buffer: ArrayBuffer): string {
+  const bytes = new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+function base64UrlToBuffer(value: string): ArrayBuffer {
+  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
+  const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
+  const binary = atob(padded);
+  const bytes = new Uint8Array(binary.length);
+  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
+  return bytes.buffer;
+}
+
+function webAuthnSupported(): boolean {
+  return typeof window !== 'undefined' && typeof window.PublicKeyCredential !== 'undefined' && !!navigator.credentials;
+}
+
+function parseCreationOptions(json: any): PublicKeyCredentialCreationOptions {
+  const PKC = window.PublicKeyCredential as any;
+  if (typeof PKC.parseCreationOptionsFromJSON === 'function') {
+    return PKC.parseCreationOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: base64UrlToBuffer(json.challenge),
+    user: { ...json.user, id: base64UrlToBuffer(json.user.id) },
+    excludeCredentials: (json.excludeCredentials ?? []).map((c: any) => ({
+      ...c,
+      id: base64UrlToBuffer(c.id),
+    })),
+  };
+}
+
+function serializeRegistration(credential: PublicKeyCredential) {
+  const response = credential.response as AuthenticatorAttestationResponse;
+  const publicKey = response.getPublicKey?.();
+  const authenticatorData = response.getAuthenticatorData?.();
+  if (!publicKey || !authenticatorData) {
+    throw new Error('This browser could not provide the passkey public key. Please try a different browser.');
+  }
+  return {
+    id: credential.id,
+    rawId: bufferToBase64Url(credential.rawId),
+    type: credential.type,
+    response: {
+      clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+      attestationObject: bufferToBase64Url(response.attestationObject),
+      authenticatorData: bufferToBase64Url(authenticatorData),
+      publicKey: bufferToBase64Url(publicKey),
+      publicKeyAlgorithm: response.getPublicKeyAlgorithm(),
+      transports: response.getTransports?.() ?? [],
+    },
+  };
+}
+
+/**
+ * WebAuthn Signal API: tells the browser / password manager which credentials
+ * the site still accepts so removed passkeys stop being offered, and keeps the
+ * stored account name current. Silently no-ops where unsupported.
+ */
+async function signalAcceptedCredentials(rpId: string, userId: string, ids: string[]): Promise<boolean> {
+  const PKC = window.PublicKeyCredential as any;
+  if (typeof PKC?.signalAllAcceptedCredentials !== 'function') return false;
+  try {
+    await PKC.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds: ids });
+    return true;
+  } catch (err) {
+    console.warn('[passkeys] signalAllAcceptedCredentials failed', err);
+    return false;
+  }
+}
+
+async function signalUserDetails(rpId: string, userId: string, username: string): Promise<void> {
+  const PKC = window.PublicKeyCredential as any;
+  if (typeof PKC?.signalCurrentUserDetails !== 'function') return;
+  try {
+    await PKC.signalCurrentUserDetails({ rpId, userId, name: username, displayName: username });
+  } catch (err) {
+    console.warn('[passkeys] signalCurrentUserDetails failed', err);
+  }
+}
+
+function suggestPasskeyName(): string {
+  const uaData = (navigator as any).userAgentData;
+  const ua = navigator.userAgent;
+  let platform: string | undefined = uaData?.platform;
+  if (!platform) {
+    if (/iPhone|iPad|iPod/.test(ua)) platform = 'iOS';
+    else if (/Android/.test(ua)) platform = 'Android';
+    else if (/Mac OS X/.test(ua)) platform = 'macOS';
+    else if (/Windows/.test(ua)) platform = 'Windows';
+    else if (/CrOS/.test(ua)) platform = 'ChromeOS';
+    else if (/Linux/.test(ua)) platform = 'Linux';
+  }
+  let browser = 'Browser';
+  if (/Edg\//.test(ua)) browser = 'Edge';
+  else if (/Firefox\//.test(ua)) browser = 'Firefox';
+  else if (/Chrome\//.test(ua)) browser = 'Chrome';
+  else if (/Safari\//.test(ua)) browser = 'Safari';
+  return platform ? `${browser} on ${platform}` : browser;
+}
+
+function formatDate(iso: string | null): string {
+  if (!iso) return 'Never';
+  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+}
+
+async function readError(res: Response, fallback: string): Promise<string> {
+  try {
+    const data = await res.json();
+    return data?.error || fallback;
+  } catch {
+    return fallback;
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Component
+// ---------------------------------------------------------------------------
+
+export default function PasskeyManager() {
+  const [data, setData] = useState<PasskeyListResponse | null>(null);
+  const [loading, setLoading] = useState(true);
+  const [notice, setNotice] = useState<Notice>(null);
+  const [supported, setSupported] = useState(true);
+  const [creating, setCreating] = useState(false);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [editName, setEditName] = useState('');
+  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
+  const [busyId, setBusyId] = useState<string | null>(null);
+  const editInputRef = useRef<HTMLInputElement>(null);
+
+  const syncAuthenticator = useCallback(async (list: PasskeyListResponse) => {
+    if (!list.userId) return false;
+    const ok = await signalAcceptedCredentials(list.rpId, list.userId, list.passkeys.map((p) => p.id));
+    await signalUserDetails(list.rpId, list.userId, list.username);
+    return ok;
+  }, []);
+
+  const load = useCallback(async () => {
+    setLoading(true);
+    try {
+      const res = await fetch(apiBase, { credentials: 'same-origin' });
+      if (!res.ok) throw new Error(await readError(res, 'Could not load your passkeys.'));
+      const list: PasskeyListResponse = await res.json();
+      setData(list);
+      // Reconcile the browser's view of our credentials on every visit, so
+      // passkeys removed elsewhere (e.g. on another device) disappear here too.
+      void syncAuthenticator(list);
+    } catch (err: any) {
+      setNotice({ kind: 'error', text: err.message || 'Could not load your passkeys.' });
+    } finally {
+      setLoading(false);
+    }
+  }, [syncAuthenticator]);
+
+  useEffect(() => {
+    setSupported(webAuthnSupported());
+    void load();
+  }, [load]);
+
+  useEffect(() => {
+    if (editingId) editInputRef.current?.focus();
+  }, [editingId]);
+
+  const handleCreate = async () => {
+    setNotice(null);
+    setCreating(true);
+    try {
+      const optionsRes = await fetch(`${apiBase}/options`, {
+        method: 'POST',
+        credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json' },
+        body: '{}',
+      });
+      if (!optionsRes.ok) throw new Error(await readError(optionsRes, 'Could not start passkey registration.'));
+      const optionsJson = await optionsRes.json();
+
+      let credential: PublicKeyCredential | null;
+      try {
+        credential = (await navigator.credentials.create({
+          publicKey: parseCreationOptions(optionsJson),
+        })) as PublicKeyCredential | null;
+      } catch (err: any) {
+        if (err?.name === 'NotAllowedError') {
+          setNotice({ kind: 'info', text: 'Passkey creation was cancelled.' });
+          return;
+        }
+        if (err?.name === 'InvalidStateError') {
+          setNotice({ kind: 'info', text: 'This authenticator already has a passkey for your account.' });
+          return;
+        }
+        throw err;
+      }
+      if (!credential) throw new Error('No passkey was created.');
+
+      const verifyRes = await fetch(apiBase, {
+        method: 'POST',
+        credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ credential: serializeRegistration(credential), name: suggestPasskeyName() }),
+      });
+      if (!verifyRes.ok) throw new Error(await readError(verifyRes, 'Could not save your passkey.'));
+      const { passkey } = await verifyRes.json();
+
+      setData((prev) => (prev ? { ...prev, passkeys: [...prev.passkeys, passkey] } : prev));
+      setNotice({ kind: 'success', text: `Passkey “${passkey.name}” added. You can rename it below.` });
+      setEditingId(passkey.id);
+      setEditName(passkey.name);
+    } catch (err: any) {
+      setNotice({ kind: 'error', text: err.message || 'Something went wrong while adding your passkey.' });
+    } finally {
+      setCreating(false);
+    }
+  };
+
+  const startEditing = (passkey: Passkey) => {
+    setConfirmDeleteId(null);
+    setEditingId(passkey.id);
+    setEditName(passkey.name);
+  };
+
+  const handleRename = async (e: React.FormEvent, passkey: Passkey) => {
+    e.preventDefault();
+    const name = editName.replace(/\s+/g, ' ').trim();
+    if (!name) {
+      setNotice({ kind: 'error', text: 'Passkey name cannot be empty.' });
+      return;
+    }
+    if (name === passkey.name) {
+      setEditingId(null);
+      return;
+    }
+    setBusyId(passkey.id);
+    setNotice(null);
+    try {
+      const res = await fetch(`${apiBase}/${encodeURIComponent(passkey.id)}`, {
+        method: 'PATCH',
+        credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ name }),
+      });
+      if (!res.ok) throw new Error(await readError(res, 'Could not rename the passkey.'));
+      const { passkey: updated } = await res.json();
+      setData((prev) =>
+        prev ? { ...prev, passkeys: prev.passkeys.map((p) => (p.id === updated.id ? updated : p)) } : prev,
+      );
+      setEditingId(null);
+      setNotice({ kind: 'success', text: `Passkey renamed to “${updated.name}”.` });
+    } catch (err: any) {
+      setNotice({ kind: 'error', text: err.message });
+    } finally {
+      setBusyId(null);
+    }
+  };
+
+  const handleDelete = async (passkey: Passkey) => {
+    setBusyId(passkey.id);
+    setNotice(null);
+    try {
+      const res = await fetch(`${apiBase}/${encodeURIComponent(passkey.id)}`, {
+        method: 'DELETE',
+        credentials: 'same-origin',
+      });
+      if (!res.ok) throw new Error(await readError(res, 'Could not remove the passkey.'));
+      const result: { rpId: string; userId: string | null; allAcceptedCredentialIds: string[] } = await res.json();
+      setData((prev) => (prev ? { ...prev, passkeys: prev.passkeys.filter((p) => p.id !== passkey.id) } : prev));
+      setConfirmDeleteId(null);
+
+      const synced = result.userId
+        ? await signalAcceptedCredentials(result.rpId, result.userId, result.allAcceptedCredentialIds)
+        : false;
+      setNotice({
+        kind: 'success',
+        text: synced
+          ? `Passkey “${passkey.name}” removed. Your browser has been told to stop offering it.`
+          : `Passkey “${passkey.name}” removed. Your browser doesn't support automatic cleanup, so you may also want to delete it from your password manager or device settings.`,
+      });
+    } catch (err: any) {
+      setNotice({ kind: 'error', text: err.message });
+    } finally {
+      setBusyId(null);
+    }
+  };
+
+  const passkeys = data?.passkeys ?? [];
+
+  return (
+    <section aria-labelledby="passkeys-heading" className="bg-white border border-gray-200 rounded-lg shadow-sm">
+      <div className="p-6 border-b border-gray-200 flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
+        <div>
+          <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900 flex items-center gap-2">
+            <KeyIcon className="w-5 h-5" aria-hidden="true" />
+            Passkeys
+          </h2>
+          <p className="mt-1 text-sm text-gray-600 max-w-xl">
+            Passkeys let you sign in with your fingerprint, face, screen lock, or a security key instead of a
+            password. Give each one a name so you can tell them apart.
+          </p>
+        </div>
+        <button
+          type="button"
+          onClick={handleCreate}
+          disabled={!supported || creating || loading}
+          className="shrink-0 py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-60 disabled:cursor-not-allowed"
+        >
+          {creating ? 'Waiting for authenticator…' : 'Add a passkey'}
+        </button>
+      </div>
+
+      {!supported && (
+        <p className="mx-6 mt-4 p-3 text-sm text-yellow-800 bg-yellow-50 rounded-lg">
+          This browser doesn't support passkeys. You can still rename or remove existing passkeys.
+        </p>
+      )}
+
+      <div aria-live="polite">
+        {notice && (
+          <div
+            role={notice.kind === 'error' ? 'alert' : 'status'}
+            className={`mx-6 mt-4 p-3 text-sm rounded-lg ${
+              notice.kind === 'error'
+                ? 'text-red-700 bg-red-100'
+                : notice.kind === 'success'
+                  ? 'text-green-700 bg-green-100'
+                  : 'text-gray-700 bg-gray-100'
+            }`}
+          >
+            {notice.text}
+          </div>
+        )}
+      </div>
+
+      <div className="p-6">
+        {loading ? (
+          <p className="text-sm text-gray-500">Loading your passkeys…</p>
+        ) : passkeys.length === 0 ? (
+          <div className="text-center py-8 border-2 border-dashed border-gray-200 rounded-lg">
+            <KeyIcon className="mx-auto w-8 h-8 text-gray-400" aria-hidden="true" />
+            <p className="mt-2 text-sm font-medium text-gray-900">No passkeys yet</p>
+            <p className="text-sm text-gray-500">Add one to sign in faster and more securely.</p>
+          </div>
+        ) : (
+          <ul className="divide-y divide-gray-200 border border-gray-200 rounded-lg">
+            {passkeys.map((passkey) => {
+              const isEditing = editingId === passkey.id;
+              const isConfirming = confirmDeleteId === passkey.id;
+              const isBusy = busyId === passkey.id;
+              const SourceIcon = passkey.backedUp ? CloudIcon : DevicePhoneMobileIcon;
+              return (
+                <li key={passkey.id} className="p-4 flex flex-col md:flex-row md:items-center gap-3">
+                  <SourceIcon className="hidden md:block w-6 h-6 text-gray-500 shrink-0" aria-hidden="true" />
+                  <div className="flex-1 min-w-0">
+                    {isEditing ? (
+                      <form onSubmit={(e) => handleRename(e, passkey)} className="flex flex-col sm:flex-row gap-2">
+                        <label htmlFor={`passkey-name-${passkey.id}`} className="sr-only">
+                          Passkey name
+                        </label>
+                        <input
+                          ref={editInputRef}
+                          id={`passkey-name-${passkey.id}`}
+                          type="text"
+                          value={editName}
+                          maxLength={MAX_NAME_LENGTH}
+                          onChange={(e) => setEditName(e.target.value)}
+                          onKeyDown={(e) => {
+                            if (e.key === 'Escape') setEditingId(null);
+                          }}
+                          required
+                          className="flex-1 px-3 py-1.5 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+                        />
+                        <div className="flex gap-2">
+                          <button
+                            type="submit"
+                            disabled={isBusy}
+                            className="py-1.5 px-3 text-sm font-medium rounded-md text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-60"
+                          >
+                            {isBusy ? 'Saving…' : 'Save'}
+                          </button>
+                          <button
+                            type="button"
+                            onClick={() => setEditingId(null)}
+                            className="py-1.5 px-3 text-sm font-medium rounded-md text-gray-700 bg-white border border-gray-300 hover:bg-gray-50"
+                          >
+                            Cancel
+                          </button>
+                        </div>
+                      </form>
+                    ) : (
+                      <>
+                        <p className="font-semibold text-gray-900 truncate">{passkey.name}</p>
+                        <p className="text-xs text-gray-500 mt-0.5">
+                          Added {formatDate(passkey.createdAt)} · Last used {formatDate(passkey.lastUsedAt)}
+                          {passkey.backedUp
+                            ? ' · Synced across your devices'
+                            : passkey.backupEligible
+                              ? ' · Can sync across devices'
+                              : ' · Stored on this device or security key'}
+                        </p>
+                      </>
+                    )}
+                  </div>
+
+                  {!isEditing && (
+                    <div className="flex items-center gap-2 shrink-0">
+                      {isConfirming ? (
+                        <>
+                          <span className="text-sm text-gray-700">Remove this passkey?</span>
+                          <button
+                            type="button"
+                            onClick={() => handleDelete(passkey)}
+                            disabled={isBusy}
+                            className="py-1.5 px-3 text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 disabled:opacity-60"
+                          >
+                            {isBusy ? 'Removing…' : 'Remove'}
+                          </button>
+                          <button
+                            type="button"
+                            onClick={() => setConfirmDeleteId(null)}
+                            disabled={isBusy}
+                            className="py-1.5 px-3 text-sm font-medium rounded-md text-gray-700 bg-white border border-gray-300 hover:bg-gray-50"
+                          >
+                            Cancel
+                          </button>
+                        </>
+                      ) : (
+                        <>
+                          <button
+                            type="button"
+                            onClick={() => startEditing(passkey)}
+                            className="inline-flex items-center gap-1 py-1.5 px-3 text-sm font-medium rounded-md text-gray-700 bg-white border border-gray-300 hover:bg-gray-50"
+                            aria-label={`Rename passkey ${passkey.name}`}
+                          >
+                            <PencilSquareIcon className="w-4 h-4" aria-hidden="true" />
+                            Rename
+                          </button>
+                          <button
+                            type="button"
+                            onClick={() => {
+                              setEditingId(null);
+                              setConfirmDeleteId(passkey.id);
+                            }}
+                            className="inline-flex items-center gap-1 py-1.5 px-3 text-sm font-medium rounded-md text-red-700 bg-white border border-red-200 hover:bg-red-50"
+                            aria-label={`Remove passkey ${passkey.name}`}
+                          >
+                            <TrashIcon className="w-4 h-4" aria-hidden="true" />
+                            Remove
+                          </button>
+                        </>
+                      )}
+                    </div>
+                  )}
+                </li>
+              );
+            })}
+          </ul>
+        )}
+
+        <p className="mt-4 text-xs text-gray-500">
+          When you remove a passkey here, supported browsers and password managers are notified so they stop
+          offering it at sign-in. Otherwise, remove it manually from your device's passkey settings.
+        </p>
+      </div>
+    </section>
+  );
+}
diff --git a/src/components/SignInForm.tsx b/src/components/SignInForm.tsx
index a7c52b6..0727c9d 100644
--- a/src/components/SignInForm.tsx
