+import React, { useState } from 'react';
+
+interface Props {
+  className?: string;
+}
+
+export default function SignOutButton({ className }: Props) {
+  const [pending, setPending] = useState(false);
+  const baseUrl = import.meta.env.BASE_URL.replace(/\/?$/, '/');
+
+  const signOut = async () => {
+    setPending(true);
+    try {
+      await fetch(`${baseUrl}api/auth/logout`, { method: 'POST', credentials: 'same-origin' });
+    } finally {
+      window.location.assign(baseUrl);
+    }
+  };
+
+  return (
+    <button
+      type="button"
+      onClick={signOut}
+      disabled={pending}
+      data-skip-tracking="true"
+      className={
+        className ??
+        'py-2 px-4 rounded-md text-sm font-medium text-gray-700 bg-white border border-gray-300 hover:bg-gray-50 disabled:opacity-60'
+      }
+    >
+      {pending ? 'Signing out…' : 'Sign out'}
+    </button>
+  );
+}
diff --git a/src/lib/auth.ts b/src/lib/auth.ts
new file mode 100644
