--- /dev/null
+++ b/src/lib/auth.ts
@@ -0,0 +1,52 @@
+export interface SessionUser {
+  username: string;
+  signedInAt: string;
+}
+
+type SessionLike = {
+  get: (key: string) => Promise<any>;
+} | undefined;
+
+export async function getSessionUser(session: SessionLike): Promise<SessionUser | null> {
+  const user = await session?.get('user');
+  if (user && typeof user.username === 'string' && user.username.length > 0) {
+    return user as SessionUser;
+  }
+  return null;
+}
+
+export function json(body: unknown, status = 200): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+/**
+ * Basic CSRF protection for state-changing API routes. Astro's built-in
+ * `checkOrigin` is disabled for this site, so we require JSON bodies (which
+ * force a CORS preflight for cross-site requests) and, when the browser sends
+ * an Origin header, require it to match the request's host.
+ */
+export function rejectCrossSite(request: Request, { requireJson = true } = {}): Response | null {
+  const origin = request.headers.get('origin');
+  if (origin) {
+    let originHost: string | null = null;
+    try {
+      originHost = new URL(origin).host;
+    } catch {
+      originHost = null;
+    }
+    const requestHost = request.headers.get('host') ?? new URL(request.url).host;
+    if (originHost !== requestHost) {
+      return json({ error: 'Cross-site request rejected' }, 403);
+    }
+  }
+  if (requireJson) {
+    const contentType = request.headers.get('content-type') ?? '';
+    if (!contentType.toLowerCase().startsWith('application/json')) {
+      return json({ error: 'Expected application/json' }, 415);
+    }
+  }
+  return null;
+}
diff --git a/src/lib/passkeyStore.ts b/src/lib/passkeyStore.ts
new file mode 100644
index 0000000..894a787
--- /dev/null
+++ b/src/lib/passkeyStore.ts
@@ -0,0 +1,123 @@
+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+import { toBase64Url } from './webauthn';
+
+export interface StoredPasskey {
+  /** Credential ID (base64url). */
+  id: string;
+  /** SubjectPublicKeyInfo DER public key (base64url). */
+  publicKey: string;
+  /** COSE algorithm identifier. */
+  algorithm: number;
+  transports: string[];
+  /** Reader-chosen label shown in account settings. */
+  name: string;
+  createdAt: string;
+  lastUsedAt: string | null;
+  /** Whether the credential is eligible for / currently synced across devices. */
+  backupEligible: boolean;
+  backedUp: boolean;
+}
+
+interface StoredUser {
+  /** WebAuthn user handle (base64url, 32 random bytes). */
+  userId: string;
+  passkeys: StoredPasskey[];
+}
+
+interface StoreData {
+  users: Record<string, StoredUser>;
+}
+
+const STORE_PATH = path.resolve(process.env.PASSKEY_STORE_PATH ?? '.data/passkeys.json');
+
+let cache: StoreData | null = null;
+// Serialize all mutations so concurrent requests can't clobber each other.
+let queue: Promise<unknown> = Promise.resolve();
+
+async function load(): Promise<StoreData> {
+  if (cache) return cache;
+  try {
+    const raw = await fs.readFile(STORE_PATH, 'utf8');
+    const parsed = JSON.parse(raw);
+    cache = parsed && typeof parsed === 'object' && parsed.users ? parsed : { users: {} };
+  } catch (err: any) {
+    if (err?.code !== 'ENOENT') {
+      console.error('[passkeys] Failed to read store, starting empty:', err);
+    }
+    cache = { users: {} };
+  }
+  return cache!;
+}
+
+async function persist(data: StoreData): Promise<void> {
+  await fs.mkdir(path.dirname(STORE_PATH), { recursive: true });
+  const tmp = `${STORE_PATH}.${process.pid}.tmp`;
+  await fs.writeFile(tmp, JSON.stringify(data, null, 2), 'utf8');
+  await fs.rename(tmp, STORE_PATH);
+}
+
+function mutate<T>(fn: (data: StoreData) => T | Promise<T>): Promise<T> {
+  const run = queue.then(async () => {
+    const data = await load();
+    const result = await fn(data);
+    await persist(data);
+    return result;
+  });
+  queue = run.catch(() => undefined);
+  return run;
+}
+
+/** Returns the user's record, creating a stable WebAuthn user handle if needed. */
+export function ensureUser(username: string): Promise<StoredUser> {
+  return mutate((data) => {
+    let user = data.users[username];
+    if (!user) {
+      user = { userId: toBase64Url(randomBytes(32)), passkeys: [] };
+      data.users[username] = user;
+    }
+    return structuredClone(user);
+  });
+}
+
+export async function getUser(username: string): Promise<StoredUser | null> {
+  await queue;
+  const data = await load();
+  const user = data.users[username];
+  return user ? structuredClone(user) : null;
+}
+
+/** Credential IDs must be globally unique across all accounts. */
+async function credentialExists(data: StoreData, id: string): Promise<boolean> {
+  return Object.values(data.users).some((u) => u.passkeys.some((p) => p.id === id));
+}
+
+export function addPasskey(username: string, passkey: StoredPasskey): Promise<StoredPasskey | 'duplicate'> {
+  return mutate(async (data) => {
+    if (await credentialExists(data, passkey.id)) return 'duplicate' as const;
+    const user = data.users[username];
+    if (!user) throw new Error('Unknown user');
+    user.passkeys.push(passkey);
+    return structuredClone(passkey);
+  });
+}
+
+export function renamePasskey(username: string, id: string, name: string): Promise<StoredPasskey | null> {
+  return mutate((data) => {
+    const passkey = data.users[username]?.passkeys.find((p) => p.id === id);
+    if (!passkey) return null;
+    passkey.name = name;
+    return structuredClone(passkey);
+  });
+}
+
+export function deletePasskey(username: string, id: string): Promise<boolean> {
+  return mutate((data) => {
+    const user = data.users[username];
+    if (!user) return false;
+    const before = user.passkeys.length;
+    user.passkeys = user.passkeys.filter((p) => p.id !== id);
+    return user.passkeys.length !== before;
+  });
+}
diff --git a/src/lib/webauthn.ts b/src/lib/webauthn.ts
new file mode 100644
index 0000000..bdb6709
--- /dev/null
+++ b/src/lib/webauthn.ts
@@ -0,0 +1,152 @@
+import { createHash, createPublicKey, randomBytes, timingSafeEqual } from 'node:crypto';
+
+export const RP_NAME = 'The DevTools Times';
+export const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+export const MAX_PASSKEY_NAME_LENGTH = 64;
+
+export function toBase64Url(buf: Uint8Array): string {
+  return Buffer.from(buf).toString('base64url');
+}
+
+export function fromBase64Url(value: unknown): Buffer {
+  if (typeof value !== 'string' || !/^[A-Za-z0-9_-]*={0,2}$/.test(value)) {
+    throw new WebAuthnError('Malformed base64url value');
+  }
+  return Buffer.from(value, 'base64url');
+}
+
+export class WebAuthnError extends Error {}
+
+export function newChallenge(): string {
+  return toBase64Url(randomBytes(32));
+}
+
+/** The relying party ID is the bare hostname the site is served from. */
+export function getRpId(request: Request): string {
+  return new URL(request.url).hostname;
+}
+
+export function normalizePasskeyName(raw: unknown): string | null {
+  if (typeof raw !== 'string') return null;
+  const name = raw.replace(/\s+/g, ' ').trim();
+  if (name.length === 0 || name.length > MAX_PASSKEY_NAME_LENGTH) return null;
+  return name;
+}
+
+export interface RegistrationInput {
+  id: string;
+  clientDataJSON: string;
+  authenticatorData: string;
+  publicKey: string;
+  publicKeyAlgorithm: number;
+  transports?: string[];
+}
+
+export interface VerifiedRegistration {
+  id: string;
+  publicKey: string;
+  algorithm: number;
+  transports: string[];
+  backupEligible: boolean;
+  backedUp: boolean;
+}
+
+const SUPPORTED_ALGORITHMS = new Set([-7, -8, -257]);
+const KNOWN_TRANSPORTS = new Set(['ble', 'hybrid', 'internal', 'nfc', 'smart-card', 'usb']);
+
+function sameBytes(a: Buffer, b: Buffer): boolean {
+  return a.length === b.length && timingSafeEqual(a, b);
+}
+
+/**
+ * Verifies a WebAuthn registration response created with `attestation: "none"`.
+ * We rely on the browser-provided helpers (`getAuthenticatorData()` /
+ * `getPublicKey()`) instead of decoding the CBOR attestation object, and check
+ * the client data, RP ID hash, flags, and credential ID binding ourselves.
+ */
+export function verifyRegistration(
+  input: RegistrationInput,
+  { expectedChallenge, rpId }: { expectedChallenge: string; rpId: string },
+): VerifiedRegistration {
+  const clientDataBytes = fromBase64Url(input.clientDataJSON);
+  let clientData: any;
+  try {
+    clientData = JSON.parse(clientDataBytes.toString('utf8'));
+  } catch {
+    throw new WebAuthnError('Invalid client data');
+  }
+
+  if (clientData.type !== 'webauthn.create') {
+    throw new WebAuthnError('Unexpected ceremony type');
+  }
+  if (
+    typeof clientData.challenge !== 'string' ||
+    !sameBytes(fromBase64Url(clientData.challenge), fromBase64Url(expectedChallenge))
+  ) {
+    throw new WebAuthnError('Challenge mismatch');
+  }
+
+  let origin: URL;
+  try {
+    origin = new URL(clientData.origin);
+  } catch {
+    throw new WebAuthnError('Invalid origin');
+  }
+  const isLocal = origin.hostname === 'localhost' || origin.hostname === '127.0.0.1';
+  if (origin.hostname !== rpId || (origin.protocol !== 'https:' && !isLocal)) {
+    throw new WebAuthnError('Origin mismatch');
+  }
+  if (clientData.crossOrigin === true) {
+    throw new WebAuthnError('Cross-origin registration is not allowed');
+  }
+
+  const authData = fromBase64Url(input.authenticatorData);
+  if (authData.length < 37) throw new WebAuthnError('Authenticator data too short');
+
+  const rpIdHash = createHash('sha256').update(rpId).digest();
+  if (!sameBytes(authData.subarray(0, 32), rpIdHash)) {
+    throw new WebAuthnError('RP ID mismatch');
+  }
+
+  const flags = authData[32];
+  const userPresent = (flags & 0x01) !== 0;
+  const backupEligible = (flags & 0x08) !== 0;
+  const backedUp = (flags & 0x10) !== 0;
+  const attestedData = (flags & 0x40) !== 0;
+  if (!userPresent) throw new WebAuthnError('User presence required');
+  if (!attestedData) throw new WebAuthnError('Missing attested credential data');
+
+  // authData: rpIdHash(32) | flags(1) | signCount(4) | aaguid(16) | credIdLen(2) | credId
+  const credIdLenOffset = 37 + 16;
+  if (authData.length < credIdLenOffset + 2) throw new WebAuthnError('Truncated credential data');
+  const credIdLen = authData.readUInt16BE(credIdLenOffset);
+  const credIdStart = credIdLenOffset + 2;
+  if (authData.length < credIdStart + credIdLen) throw new WebAuthnError('Truncated credential ID');
+  const credentialId = authData.subarray(credIdStart, credIdStart + credIdLen);
+  if (!sameBytes(credentialId, fromBase64Url(input.id))) {
+    throw new WebAuthnError('Credential ID mismatch');
+  }
+
+  if (!SUPPORTED_ALGORITHMS.has(input.publicKeyAlgorithm)) {
+    throw new WebAuthnError('Unsupported public key algorithm');
+  }
+  const spki = fromBase64Url(input.publicKey);
+  try {
+    createPublicKey({ key: spki, format: 'der', type: 'spki' });
+  } catch {
+    throw new WebAuthnError('Invalid public key');
+  }
+
+  const transports = Array.isArray(input.transports)
+    ? input.transports.filter((t): t is string => typeof t === 'string' && KNOWN_TRANSPORTS.has(t))
+    : [];
+
+  return {
+    id: toBase64Url(credentialId),
+    publicKey: toBase64Url(spki),
+    algorithm: input.publicKeyAlgorithm,
+    transports,
+    backupEligible,
+    backedUp,
+  };
+}
