diff --git a/src/pages/api/account/passkeys/[id].ts b/src/pages/api/account/passkeys/[id].ts
new file mode 100644
index 0000000..6cd0785
--- /dev/null
+++ b/src/pages/api/account/passkeys/[id].ts
@@ -0,0 +1,52 @@
+import type { APIRoute } from 'astro';
+import { getSessionUser, json, rejectCrossSite } from '../../../../lib/auth';
+import { deletePasskey, getUser, renamePasskey } from '../../../../lib/passkeyStore';
+import { getRpId, normalizePasskeyName, MAX_PASSKEY_NAME_LENGTH } from '../../../../lib/webauthn';
+import { toPublicPasskey } from './_shared';
+
+/** Renames a passkey. */
+export const PATCH: APIRoute = async ({ request, session, params }) => {
+  const rejected = rejectCrossSite(request);
+  if (rejected) return rejected;
+
+  const user = await getSessionUser(session);
+  if (!user) return json({ error: 'Not signed in' }, 401);
+
+  let body: any;
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid JSON body' }, 400);
+  }
+  const name = normalizePasskeyName(body?.name);
+  if (!name) {
+    return json({ error: `Name must be between 1 and ${MAX_PASSKEY_NAME_LENGTH} characters.` }, 400);
+  }
+
+  const updated = await renamePasskey(user.username, params.id ?? '', name);
+  if (!updated) return json({ error: 'Passkey not found' }, 404);
+  return json({ passkey: toPublicPasskey(updated) });
+};
+
+/**
+ * Removes a passkey. The response includes the remaining credential IDs so the
+ * client can call `PublicKeyCredential.signalAllAcceptedCredentials()` and let
+ * the browser/password manager hide the deleted credential.
+ */
+export const DELETE: APIRoute = async ({ request, session, params }) => {
+  const rejected = rejectCrossSite(request, { requireJson: false });
+  if (rejected) return rejected;
+
+  const user = await getSessionUser(session);
+  if (!user) return json({ error: 'Not signed in' }, 401);
+
+  const removed = await deletePasskey(user.username, params.id ?? '');
+  if (!removed) return json({ error: 'Passkey not found' }, 404);
+
+  const record = await getUser(user.username);
+  return json({
+    rpId: getRpId(request),
+    userId: record?.userId ?? null,
+    allAcceptedCredentialIds: (record?.passkeys ?? []).map((p) => p.id),
+  });
+};
