diff --git a/src/pages/api/account/passkeys/index.ts b/src/pages/api/account/passkeys/index.ts
new file mode 100644
index 0000000..75b14ba
--- /dev/null
+++ b/src/pages/api/account/passkeys/index.ts
@@ -0,0 +1,97 @@
+import type { APIRoute } from 'astro';
+import { getSessionUser, json, rejectCrossSite } from '../../../../lib/auth';
+import { addPasskey, ensureUser, getUser } from '../../../../lib/passkeyStore';
+import {
+  WebAuthnError,
+  getRpId,
+  normalizePasskeyName,
+  verifyRegistration,
+} from '../../../../lib/webauthn';
+import { toPublicPasskey } from './_shared';
+
+/** Lists the signed-in reader's passkeys plus the IDs needed for Signal API calls. */
+export const GET: APIRoute = async ({ request, session }) => {
+  const user = await getSessionUser(session);
+  if (!user) return json({ error: 'Not signed in' }, 401);
+
+  const record = await getUser(user.username);
+  return json({
+    rpId: getRpId(request),
+    userId: record?.userId ?? null,
+    username: user.username,
+    passkeys: (record?.passkeys ?? []).map(toPublicPasskey),
+  });
+};
+
+/** Completes a passkey registration started via `./options`. */
+export const POST: APIRoute = async ({ request, session }) => {
+  const rejected = rejectCrossSite(request);
+  if (rejected) return rejected;
+
+  const user = await getSessionUser(session);
+  if (!user || !session) return json({ error: 'Not signed in' }, 401);
+
+  const pending = await session.get('passkeyRegistration');
+  // Challenges are single-use regardless of outcome.
+  session.delete('passkeyRegistration');
+  if (
+    !pending ||
+    pending.username !== user.username ||
+    typeof pending.challenge !== 'string' ||
+    Date.now() > pending.expiresAt
+  ) {
+    return json({ error: 'Registration expired. Please try again.' }, 400);
+  }
+
+  let body: any;
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid JSON body' }, 400);
+  }
+
+  const credential = body?.credential;
+  const response = credential?.response;
+  if (!credential || !response || credential.type !== 'public-key') {
+    return json({ error: 'Missing credential' }, 400);
+  }
+
+  const rpId = getRpId(request);
+  if (pending.rpId !== rpId) {
+    return json({ error: 'Registration expired. Please try again.' }, 400);
+  }
+
+  let verified;
+  try {
+    verified = verifyRegistration(
+      {
+        id: credential.id,
+        clientDataJSON: response.clientDataJSON,
+        authenticatorData: response.authenticatorData,
+        publicKey: response.publicKey,
+        publicKeyAlgorithm: response.publicKeyAlgorithm,
+        transports: response.transports,
+      },
+      { expectedChallenge: pending.challenge, rpId },
+    );
+  } catch (err) {
+    if (err instanceof WebAuthnError) {
+      return json({ error: `Passkey verification failed: ${err.message}` }, 400);
+    }
+    throw err;
+  }
+
+  await ensureUser(user.username);
+  const name = normalizePasskeyName(body?.name) ?? 'Passkey';
+  const saved = await addPasskey(user.username, {
+    ...verified,
+    name,
+    createdAt: new Date().toISOString(),
+    lastUsedAt: null,
+  });
+  if (saved === 'duplicate') {
+    return json({ error: 'This passkey is already registered.' }, 409);
+  }
+
+  return json({ passkey: toPublicPasskey(saved) }, 201);
+};
