+
+const UPSTREAM_LOGIN_URL = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login';
+
+/**
+ * Proxies sign-in to the upstream auth service so the server can establish a
+ * session for the reader. Upstream status codes and bodies are passed through
+ * unchanged so the form can keep surfacing upstream error codes.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  const rejected = rejectCrossSite(request);
+  if (rejected) return rejected;
+
+  let body: any;
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid JSON body' }, 400);
+  }
+  const username = typeof body?.username === 'string' ? body.username.trim() : '';
+  const password = typeof body?.password === 'string' ? body.password : '';
+  if (!username || !password) {
+    return json({ error: 'Username and password are required' }, 400);
+  }
+
+  let upstream: Response;
+  try {
+    upstream = await fetch(UPSTREAM_LOGIN_URL, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+  } catch {
+    return json({ error: 'Sign-in service unavailable' }, 502);
+  }
+
+  let data: any = {};
+  try {
+    data = await upstream.json();
+  } catch {
+    data = {};
+  }
+
+  if (upstream.ok && session) {
+    // Rotate the session ID on privilege change to prevent session fixation.
+    await session.regenerate();
+    session.set('user', { username, signedInAt: new Date().toISOString() });
+  }
+
+  return json(data, upstream.status);
+};
