+            return;
+          }
+          setStatus('Your passkey was created. You can now use it to sign in.', 'success');
+        } catch (err) {
+          console.error('Passkey verification request failed:', err);
+          await signalUnknown(rpId, encodedResponse.id);
+          setStatus('We couldn’t verify your new passkey. Please try again.', 'error');
+        }
+      } finally {
+        inProgress = false;
+        registerButton.disabled = false;
+        registerButton.removeAttribute('aria-busy');
+      }
+    }
+
+    // Gate the UI: only enable the button where passkeys are supported.
+    (async () => {
+      const caps = await getPasskeyCapabilities();
+      if (!window.isSecureContext || !caps.passkeyPlatformAuthenticator || !caps.conditionalGet) {
+        registerButton.disabled = true;
+        setStatus('Passkeys aren’t supported on this browser or device.');
+        return;
+      }
+      registerButton.disabled = false;
+      registerButton.addEventListener('click', registerPasskey);
+    })();
+  </script>
