+// The Daily Grind — "My Account" passkey UI.
+//
+// Calls the native WebAuthn browser APIs directly. Polyfills (served from our
+// own origin) fill in getClientCapabilities(), parse*OptionsFromJSON() and
+// PublicKeyCredential.prototype.toJSON() where the browser lacks them.
+//
+// Backend contract (JSON, same-origin, cookie session) — see PASSKEYS.md.
+import '/vendor/webauthn-polyfills-0.1.7.js';
+
+const $ = (id) => document.getElementById(id);
+
+const els = {
+  openButton: $('account-open'),
+  dialog: $('account-dialog'),
+  title: $('account-title'),
+  logoutLink: $('logout-link'),
+  views: {
+    loading: $('view-loading'),
+    signedOut: $('view-signed-out'),
+    signedIn: $('view-signed-in'),
+  },
+  signinForm: $('signin-form'),
+  signinButton: $('signin-button'),
+  signinStatus: $('signin-status'),
+  signupForm: $('signup-form'),
+  signupButton: $('signup-button'),
+  signupStatus: $('signup-status'),
+  unsupported: $('passkey-unsupported'),
+  profileForm: $('profile-form'),
+  profileDisplayName: $('profile-display-name'),
+  profileEmail: $('profile-email'),
+  profileSave: $('profile-save'),
+  profileStatus: $('profile-status'),
+  passkeyList: $('passkey-list'),
+  passkeysStatus: $('passkeys-status'),
+  createPasskey: $('create-passkey'),
+  createUnsupported: $('create-passkey-unsupported'),
+  signoutButton: $('signout-button'),
+  renameDialog: $('rename-dialog'),
+  renameForm: $('rename-form'),
+  renameInput: $('rename-input'),
+  renameCancel: $('rename-cancel'),
+  deleteDialog: $('delete-dialog'),
+  deleteDesc: $('delete-desc'),
+  itemTemplate: $('passkey-item-template'),
+};
+
+const state = {
+  user: null, // { name, displayName } when signed in
+  capabilities: {},
+  autofillController: null,
+};
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+async function api(path, { method = 'GET', body } = {}) {
+  return fetch(path, {
+    method,
+    credentials: 'same-origin',
+    headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+}
+
+async function apiJSON(path, options) {
+  const response = await api(path, options);
+  if (!response.ok) {
+    throw new Error(await readError(response));
+  }
+  return response.json();
+}
+
+async function readError(response) {
+  try {
+    const data = await response.json();
+    if (data && typeof data.error === 'string') return data.error;
+  } catch {
+    /* non-JSON body */
+  }
+  return `Request failed (${response.status}).`;
+}
+
+function setStatus(el, message, tone = '') {
+  el.textContent = message;
+  if (tone) el.dataset.tone = tone;
+  else delete el.dataset.tone;
+}
+
+function setBusy(button, busy) {
+  button.disabled = busy;
+  button.setAttribute('aria-busy', String(busy));
+}
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, length % 4 !== 1.
+function isValidBase64Url(value) {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const dateTimeFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+
+const FALLBACK_ICON =
+  'data:image/svg+xml,' +
+  encodeURIComponent(
+    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#4e342e" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="8" r="4"/><path d="M10.8 10.8 20 20m-4-4 2-2m-4.5-.5 2-2"/></svg>'
+  );
+
+// Provider icons come from the AAGUID registry as data: URIs (or https URLs).
+function safeIconSrc(src) {
+  if (typeof src !== 'string') return FALLBACK_ICON;
+  if (/^data:image\/(png|svg\+xml|jpeg|webp);/i.test(src) || src.startsWith('https://')) return src;
+  return FALLBACK_ICON;
+}
+
+function webauthnSupported() {
+  return typeof window.PublicKeyCredential === 'function' && 'credentials' in navigator;
+}
+
+async function loadCapabilities() {
+  if (!webauthnSupported() || !PublicKeyCredential.getClientCapabilities) return {};
+  try {
+    return await PublicKeyCredential.getClientCapabilities();
+  } catch {
+    return {};
+  }
+}
+
+// --- Signal API (progressive enhancement; failures are non-fatal) ----------
+
+async function signalUnknownCredential(rpId, credentialId) {
+  if (!webauthnSupported() || !PublicKeyCredential.signalUnknownCredential) return;
+  if (!rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId });
+  } catch (e) {
+    console.warn('signalUnknownCredential sync warning:', e);
+  }
+}
+
+async function signalAllAcceptedCredentials(rpId, userId, credentials) {
+  if (!webauthnSupported() || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+  const allAcceptedCredentialIds = credentials.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !allAcceptedCredentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and Base64URL IDs are required.');
+    return;
+  }
+  try {
+    // rpId always comes from the server — never window.location.hostname.
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+async function signalCurrentUserDetails(rpId, userId, name, displayName) {
+  if (!webauthnSupported() || !PublicKeyCredential.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// View switching
+// ---------------------------------------------------------------------------
+
+function showView(name) {
+  for (const [key, el] of Object.entries(els.views)) {
+    el.hidden = key !== name;
+  }
+  els.title.textContent = name === 'signedIn' && state.user
+    ? `Hi, ${state.user.displayName || state.user.name}`
+    : name === 'signedOut'
+      ? 'Sign in to The Daily Grind'
+      : 'My Account';
+  els.logoutLink.hidden = name !== 'signedIn';
+}
+
+async function enterSignedIn(user) {
+  state.user = user;
+  abortAutofill();
+  els.profileDisplayName.value = user.displayName ?? '';
+  els.profileEmail.value = user.name ?? '';
+  setStatus(els.profileStatus, '');
+  showView('signedIn');
+  await loadPasskeys();
+}
+
+function enterSignedOut() {
+  state.user = null;
+  els.passkeyList.replaceChildren();
+  showView('signedOut');
+  startConditionalSignIn();
+}
+
+// ---------------------------------------------------------------------------
+// Sign in (conditional mediation autofill + explicit button)
+// ---------------------------------------------------------------------------
+
+function abortAutofill() {
+  if (state.autofillController) {
+    state.autofillController.abort();
+    state.autofillController = null;
+  }
+}
+
+async function fetchSignInOptions() {
+  const optionsJSON = await apiJSON('/api/signin/options', { method: 'POST', body: {} });
+  return PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+}
+
+// Sends an assertion to the server. Returns true on success.
+async function verifySignIn(credential, publicKey) {
+  const encoded = credential.toJSON();
+  let response;
+  try {
+    response = await api('/api/signin/verify', { method: 'POST', body: encoded });
+  } catch (err) {
+    console.error('Sign-in verification request failed:', err);
+    setStatus(els.signinStatus, "We couldn't reach the server. Check your connection and try again.", 'error');
+    return false;
+  }
+
+  if (response.ok) {
+    const { user } = await response.json();
+    setStatus(els.signinStatus, '');
+    await enterSignedIn(user);
+    return true;
+  }
+
+  if (response.status === 404) {
+    // The passkey isn't on our server (e.g. deleted). Ask the password
+    // manager to hide it. We are unauthenticated here, as required.
+    await signalUnknownCredential(publicKey.rpId, encoded.id);
+    setStatus(
+      els.signinStatus,
+      "That passkey isn't linked to a Daily Grind account any more. Try another passkey or create an account.",
+      'error'
+    );
+  } else {
+    setStatus(els.signinStatus, await readError(response), 'error');
+  }
+  return false;
+}
+
+async function startConditionalSignIn() {
+  if (state.user || state.capabilities.conditionalGet !== true) return;
+  abortAutofill();
+  const controller = new AbortController();
+  state.autofillController = controller;
+
+  let publicKey;
+  try {
+    publicKey = await fetchSignInOptions();
+  } catch (err) {
+    console.warn('Could not prepare passkey autofill:', err);
+    return;
+  }
+  if (controller.signal.aborted) return;
+
+  let credential;
+  try {
+    credential = await navigator.credentials.get({
+      publicKey,
+      signal: controller.signal,
+      mediation: 'conditional',
+    });
+  } catch (err) {
+    if (err.name === 'NotAllowedError' || err.name === 'AbortError') return;
+    console.warn('Passkey autofill unavailable:', err);
+    return;
+  }
+  if (state.autofillController === controller) state.autofillController = null;
+  if (!credential) return;
+
+  const ok = await verifySignIn(credential, publicKey);
+  if (!ok) startConditionalSignIn();
+}
+
+async function signInWithButton(event) {
+  event.preventDefault();
+  // Abort the pending autofill request so the two prompts don't collide.
+  abortAutofill();
+  const controller = new AbortController();
+  state.autofillController = controller;
+
+  setBusy(els.signinButton, true);
+  setStatus(els.signinStatus, '');
+  try {
+    let publicKey;
+    try {
+      publicKey = await fetchSignInOptions();
+    } catch (err) {
+      setStatus(els.signinStatus, err.message, 'error');
+      return;
+    }
+
+    let credential;
+    try {
+      credential = await navigator.credentials.get({ publicKey, signal: controller.signal });
+    } catch (err) {
+      if (err.name === 'NotAllowedError') {
+        setStatus(els.signinStatus, 'Sign-in was cancelled.');
+      } else if (err.name === 'SecurityError') {
+        setStatus(els.signinStatus, 'Passkeys are not available on this site configuration.', 'error');
+      } else if (err.name !== 'AbortError') {
+        setStatus(els.signinStatus, 'Something went wrong signing in. Please try again.', 'error');
+      }
+      startConditionalSignIn(); // re-arm autofill suggestions
+      return;
+    }
+
+    if (state.autofillController === controller) state.autofillController = null;
+    const ok = await verifySignIn(credential, publicKey);
+    if (!ok) startConditionalSignIn();
+  } finally {
+    setBusy(els.signinButton, false);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Registration (new account + adding a passkey to an existing account)
+// ---------------------------------------------------------------------------
+
+/**
+ * Runs navigator.credentials.create() and server verification.
+ * Returns the server's JSON response on success, or null.
+ */
+async function createAndVerifyPasskey({ optionsPath, optionsBody, verifyPath, statusEl }) {
+  let publicKey;
+  try {
+    const optionsJSON = await apiJSON(optionsPath, { method: 'POST', body: optionsBody });
+    publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(optionsJSON);
+  } catch (err) {
+    setStatus(statusEl, err.message, 'error');
+    return null;
+  }
+
+  let credential;
+  try {
+    credential = await navigator.credentials.create({ publicKey });
+  } catch (err) {
+    if (err.name === 'InvalidStateError') {
+      setStatus(statusEl, 'You already have a passkey for this account in this password manager.', 'error');
+    } else if (err.name === 'NotAllowedError') {
+      setStatus(statusEl, 'Passkey creation was cancelled.');
+    } else if (err.name === 'SecurityError') {
+      setStatus(statusEl, 'Passkeys are not available on this site configuration.', 'error');
+    } else if (err.name !== 'AbortError') {
+      setStatus(statusEl, 'Something went wrong creating your passkey. Please try again.', 'error');
+    }
+    return null; // standard WebAuthn cancellations: nothing to signal
+  }
+
+  const encoded = credential.toJSON();
+  try {
+    const response = await api(verifyPath, { method: 'POST', body: encoded });
+    if (!response.ok) {
+      // The provider saved a passkey the server rejected — remove the orphan.
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      setStatus(statusEl, await readError(response), 'error');
+      return null;
+    }
+    return await response.json();
+  } catch (err) {
+    console.error('Passkey verification request failed:', err);
+    await signalUnknownCredential(publicKey.rp.id, encoded.id);
+    setStatus(statusEl, "We couldn't reach the server. Check your connection and try again.", 'error');
+    return null;
+  }
+}
+
+async function signUp(event) {
+  event.preventDefault();
+  if (!els.signupForm.reportValidity()) return;
+  const data = new FormData(els.signupForm);
+  const name = String(data.get('name')).trim();
+  const displayName = String(data.get('displayName')).trim();
+
+  // A pending conditional get() would block create().
+  abortAutofill();
+  setBusy(els.signupButton, true);
+  setStatus(els.signupStatus, 'Follow the prompt to save your passkey…');
+  try {
+    const result = await createAndVerifyPasskey({
+      optionsPath: '/api/signup/options',
+      optionsBody: { name, displayName },
+      verifyPath: '/api/signup/verify',
+      statusEl: els.signupStatus,
+    });
+    if (result?.user) {
+      els.signupForm.reset();
+      setStatus(els.signupStatus, '');
+      await enterSignedIn(result.user);
+      setStatus(els.passkeysStatus, 'Welcome! Your account and passkey are ready.', 'success');
+    } else {
+      startConditionalSignIn();
+    }
+  } finally {
+    setBusy(els.signupButton, false);
+  }
+}
+
+async function addPasskey() {
+  setBusy(els.createPasskey, true);
+  setStatus(els.passkeysStatus, 'Follow the prompt to save your passkey…');
+  try {
+    const result = await createAndVerifyPasskey({
+      optionsPath: '/api/passkeys/options',
+      optionsBody: {},
+      verifyPath: '/api/passkeys/verify',
+      statusEl: els.passkeysStatus,
+    });
+    if (result) {
+      await loadPasskeys();
+      setStatus(els.passkeysStatus, 'Passkey created.', 'success');
+    }
+  } finally {
+    setBusy(els.createPasskey, false);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Reauthentication (before sensitive changes)
+// ---------------------------------------------------------------------------
+
+/**
+ * Asks the signed-in user to confirm with one of *their* passkeys.
+ * The server limits allowCredentials to the user's credentials and checks the
+ * returned credential belongs to the session user. Returns true on success.
+ */
+async function reauthenticate(statusEl) {
+  abortAutofill();
+  let publicKey;
+  try {
+    const optionsJSON = await apiJSON('/api/reauth/options', { method: 'POST', body: {} });
+    publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+  } catch (err) {
+    setStatus(statusEl, err.message, 'error');
+    return false;
+  }
+
+  if (!publicKey.allowCredentials?.length) {
+    setStatus(statusEl, 'Add a passkey to your account before making this change.', 'error');
+    return false;
+  }
+
+  setStatus(statusEl, 'Confirm it’s you with your passkey…');
+  let credential;
+  try {
+    credential = await navigator.credentials.get({ publicKey });
+  } catch (err) {
+    if (err.name === 'NotAllowedError') {
+      setStatus(statusEl, 'Verification was cancelled, so nothing was changed.');
+    } else {
+      setStatus(statusEl, 'We couldn’t verify it’s you. Nothing was changed.', 'error');
+    }
+    return false;
+  }
+
+  const encoded = credential.toJSON();
+  try {
+    const response = await api('/api/reauth/verify', { method: 'POST', body: encoded });
+    if (response.ok) return true;
+    if (response.status === 404) {
+      await signalUnknownCredential(publicKey.rpId, encoded.id);
+    }
+    setStatus(statusEl, await readError(response), 'error');
+  } catch (err) {
+    console.error('Reauthentication request failed:', err);
+    setStatus(statusEl, "We couldn't reach the server. Nothing was changed.", 'error');
+  }
+  return false;
+}
+
+// ---------------------------------------------------------------------------
+// Passkey management
+// ---------------------------------------------------------------------------
+
+let passkeys = [];
+
+async function loadPasskeys() {
+  let data;
+  try {
+    data = await apiJSON('/api/passkeys');
+  } catch (err) {
+    setStatus(els.passkeysStatus, `Couldn't load your passkeys. ${err.message}`, 'error');
+    return;
+  }
+  passkeys = Array.isArray(data.credentials) ? data.credentials : [];
+  renderPasskeys();
+  // Keep password managers in sync with the server's list.
+  await signalAllAcceptedCredentials(data.rpId, data.userId, passkeys);
+}
+
+function renderPasskeys() {
+  if (passkeys.length === 0) {
+    const empty = document.createElement('li');
+    empty.className = 'empty-state';
+    empty.textContent = 'No passkeys found. Create one to sign in faster next time.';
+    els.passkeyList.replaceChildren(empty);
+    return;
+  }
+
+  const items = passkeys.map((cred) => {
+    const node = els.itemTemplate.content.firstElementChild.cloneNode(true);
+    node.dataset.id = cred.id;
+
+    node.querySelector('.passkey-icon').src = safeIconSrc(cred.providerIcon);
+
+    const name = cred.name || 'Unnamed passkey';
+    const nameEl = node.querySelector('.passkey-name');
+    nameEl.textContent = name;
+    const badge = document.createElement('span');
+    badge.className = 'passkey-badge';
+    badge.textContent = cred.credentialDeviceType === 'multiDevice' || cred.credentialBackedUp
+      ? 'Synced'
+      : 'This device only';
+    nameEl.append(badge);
+
+    node.querySelector('.passkey-registered').textContent = cred.registeredAt
+      ? `Created ${dateFormat.format(new Date(cred.registeredAt))}`
+      : '';
+    node.querySelector('.passkey-last-used').textContent = cred.lastUsedAt
+      ? `Last used ${dateTimeFormat.format(new Date(cred.lastUsedAt))}`
+      : 'Not used yet';
+
+    node.querySelector('[data-action="rename"]').setAttribute('aria-label', `Rename ${name}`);
+    node.querySelector('[data-action="delete"]').setAttribute('aria-label', `Delete ${name}`);
+    return node;
+  });
+  els.passkeyList.replaceChildren(...items);
+}
+
+let pendingRenameId = null;
+
+function openRename(cred) {
+  pendingRenameId = cred.id;
+  els.renameInput.value = cred.name || '';
+  els.renameDialog.showModal();
+  els.renameInput.select();
+}
+
+async function submitRename(event) {
+  event.preventDefault();
+  if (!els.renameForm.reportValidity() || !pendingRenameId) return;
+  const id = pendingRenameId;
+  const name = els.renameInput.value.trim();
+  els.renameDialog.close();
+  pendingRenameId = null;
+
+  // Renaming a passkey is a server-side label only; no Signal API call.
+  try {
+    await apiJSON(`/api/passkeys/${encodeURIComponent(id)}`, { method: 'PUT', body: { name } });
+    await loadPasskeys();
+    setStatus(els.passkeysStatus, 'Passkey renamed.', 'success');
+  } catch (err) {
+    setStatus(els.passkeysStatus, `Couldn't rename the passkey. ${err.message}`, 'error');
+  }
+}
+
+let pendingDeleteId = null;
+
+function openDelete(cred) {
+  pendingDeleteId = cred.id;
+  const others = passkeys.length - 1;
+  els.deleteDesc.textContent =
+    `“${cred.name || 'This passkey'}” will no longer sign you in. ` +
+    (others > 0
+      ? `You'll still have ${others} other passkey${others === 1 ? '' : 's'}.`
+      : 'This is your last passkey — you will need another way to sign in.') +
+    ' You’ll be asked to confirm it’s you first.';
+  els.deleteDialog.showModal();
+}
+
+async function onDeleteDialogClose() {
+  const choice = els.deleteDialog.returnValue;
+  els.deleteDialog.returnValue = '';
+  const id = pendingDeleteId;
+  pendingDeleteId = null;
+  if (choice !== 'delete' || !id) return;
+
+  // Sensitive action: verify the user first.
+  if (!(await reauthenticate(els.passkeysStatus))) return;
+
+  try {
+    await apiJSON(`/api/passkeys/${encodeURIComponent(id)}`, { method: 'DELETE' });
+    // loadPasskeys() re-syncs the remaining IDs via signalAllAcceptedCredentials().
+    await loadPasskeys();
+    setStatus(els.passkeysStatus, 'Passkey deleted.', 'success');
+  } catch (err) {
+    setStatus(els.passkeysStatus, `Couldn't delete the passkey. ${err.message}`, 'error');
+  }
+}
+
+function onPasskeyListClick(event) {
+  const button = event.target.closest('button[data-action]');
+  if (!button) return;
+  const id = button.closest('.passkey-item')?.dataset.id;
+  const cred = passkeys.find((c) => c.id === id);
+  if (!cred) return;
+  if (button.dataset.action === 'rename') openRename(cred);
+  if (button.dataset.action === 'delete') openDelete(cred);
+}
+
+// ---------------------------------------------------------------------------
+// Profile updates
+// ---------------------------------------------------------------------------
+
+async function saveProfile(event) {
+  event.preventDefault();
+  if (!els.profileForm.reportValidity()) return;
+  const name = els.profileEmail.value.trim();
+  const displayName = els.profileDisplayName.value.trim();
+
+  if (name === state.user.name && displayName === state.user.displayName) {
+    setStatus(els.profileStatus, 'No changes to save.');
+    return;
+  }
+
+  setBusy(els.profileSave, true);
+  try {
+    if (!(await reauthenticate(els.profileStatus))) return;
+
+    let updated;
+    try {
+      updated = await apiJSON('/api/user', { method: 'PUT', body: { name, displayName } });
+    } catch (err) {
+      setStatus(els.profileStatus, `Couldn't save your profile. ${err.message}`, 'error');
+      return;
+    }
+
+    state.user = { name: updated.name, displayName: updated.displayName };
+    els.profileEmail.value = updated.name;
+    els.profileDisplayName.value = updated.displayName;
+    showView('signedIn');
+    setStatus(els.profileStatus, 'Profile updated.', 'success');
+
+    // Update the account name shown in the user's password manager.
+    await signalCurrentUserDetails(updated.rpId, updated.userId, updated.name, updated.displayName);
+  } finally {
+    setBusy(els.profileSave, false);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Session
+// ---------------------------------------------------------------------------
+
+async function signOut() {
+  setBusy(els.signoutButton, true);
+  try {
+    await api('/api/signout', { method: 'POST', body: {} });
+  } catch (err) {
+    console.warn('Sign-out request failed:', err);
+  } finally {
+    setBusy(els.signoutButton, false);
+  }
+  enterSignedOut();
+}
+
+async function loadSession() {
+  try {
+    const response = await api('/api/session');
+    if (response.ok) {
+      const { user } = await response.json();
+      if (user) {
+        await enterSignedIn(user);
+        return;
+      }
+    }
+  } catch (err) {
+    console.warn('Session check failed:', err);
+  }
+  enterSignedOut();
+}
+
+function applyCapabilityGates() {
+  const caps = state.capabilities;
+  const supported = webauthnSupported();
+
+  // New-account registration and sign-in need platform passkeys + autofill.
+  const canSignUp = supported && caps.passkeyPlatformAuthenticator === true && caps.conditionalGet === true;
+  els.signupButton.disabled = !canSignUp;
+  els.signinButton.disabled = !supported;
+  els.unsupported.hidden = canSignUp;
+
+  // Management "Create a passkey": hide when platform passkeys are unavailable.
+  const canAdd = supported && caps.passkeyPlatformAuthenticator === true;
+  els.createPasskey.hidden = !canAdd;
+  els.createUnsupported.hidden = canAdd;
+}
+
+async function init() {
+  els.openButton.addEventListener('click', () => els.dialog.showModal());
+  els.signinForm.addEventListener('submit', signInWithButton);
+  els.signupForm.addEventListener('submit', signUp);
+  els.createPasskey.addEventListener('click', addPasskey);
+  els.passkeyList.addEventListener('click', onPasskeyListClick);
+  els.renameForm.addEventListener('submit', submitRename);
+  els.renameCancel.addEventListener('click', () => els.renameDialog.close());
+  els.renameDialog.addEventListener('close', () => { pendingRenameId = null; });
+  els.deleteDialog.addEventListener('close', onDeleteDialogClose);
+  els.profileForm.addEventListener('submit', saveProfile);
+  els.signoutButton.addEventListener('click', signOut);
+
+  // Deep link: /#account opens the panel (replaces the old /account link).
+  if (location.hash === '#account') els.dialog.showModal();
+
+  state.capabilities = await loadCapabilities();
+  applyCapabilityGates();
+  await loadSession();
+}
+
+init();
