+// "My Account" UI: passkey registration, sign-in (button + autofill), saved
+// passkey management, profile updates and reauthentication for sensitive actions.
+
+import * as rp from './relying-party.js';
+import {
+  createPasskey,
+  describeError,
+  getCapabilities,
+  getPasskey,
+  isAbort,
+  signalAllAcceptedCredentials,
+  signalCurrentUserDetails,
+  signalUnknownCredential,
+} from './webauthn.js';
+
+const $ = (sel, root = document) => root.querySelector(sel);
+
+const el = {
+  dialog: $('#account-dialog'),
+  body: $('#account-dialog .account-body'),
+  accountLink: $('#account-link'),
+  sessionLink: $('#session-link'),
+  unsupported: $('#account-unsupported'),
+  status: $('#account-status'),
+  signedOut: $('#view-signed-out'),
+  signedIn: $('#view-signed-in'),
+  tabSignin: $('#tab-signin'),
+  tabRegister: $('#tab-register'),
+  panelSignin: $('#panel-signin'),
+  panelRegister: $('#panel-register'),
+  signinForm: $('#signin-form'),
+  registerForm: $('#register-form'),
+  profileForm: $('#profile-form'),
+  avatar: $('#account-avatar'),
+  greeting: $('#account-greeting'),
+  email: $('#account-email'),
+  passkeyList: $('#passkey-list'),
+  addPasskeyBtn: $('#add-passkey-btn'),
+  deleteAccountBtn: $('#delete-account-btn'),
+  sessionInfo: $('#session-info'),
+  reauthSheet: $('#reauth-sheet'),
+  reauthTitle: $('#reauth-title'),
+  reauthDesc: $('#reauth-desc'),
+  reauthError: $('#reauth-error'),
+  reauthConfirm: $('[data-action="reauth-confirm"]'),
+  toast: $('#toast'),
+};
+
+const state = {
+  caps: { webauthn: false, conditionalGet: false, platformAuthenticator: false },
+  tab: 'signin',
+  conditional: null, // AbortController for the pending autofill request
+  reauth: null, // { resolve, needsPasskey, returnFocus }
+  renamingId: null,
+};
+
+// ---------------------------------------------------------------------------
+// Small UI helpers
+// ---------------------------------------------------------------------------
+
+function showStatus(type, message) {
+  el.status.className = `notice ${type}`;
+  el.status.textContent = message;
+  el.status.hidden = false;
+}
+
+function clearStatus() {
+  el.status.hidden = true;
+  el.status.textContent = '';
+}
+
+let toastTimer;
+function toast(message) {
+  el.toast.textContent = message;
+  el.toast.hidden = false;
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => (el.toast.hidden = true), 4000);
+}
+
+function setBusy(button, busy) {
+  if (!button) return;
+  if (busy) {
+    button.dataset.idleHtml ??= button.innerHTML;
+    if (button.dataset.busyLabel) button.textContent = button.dataset.busyLabel;
+    button.disabled = true;
+    button.setAttribute('aria-busy', 'true');
+  } else {
+    if (button.dataset.idleHtml != null) button.innerHTML = button.dataset.idleHtml;
+    delete button.dataset.idleHtml;
+    button.disabled = !state.caps.webauthn && button.dataset.requiresPasskeys === 'true';
+    button.removeAttribute('aria-busy');
+  }
+}
+
+function firstName(name) {
+  return String(name ?? '').trim().split(/\s+/)[0] || 'there';
+}
+
+function initials(name) {
+  const parts = String(name ?? '').trim().split(/\s+/).filter(Boolean);
+  return ((parts[0]?.[0] ?? '') + (parts.length > 1 ? parts[parts.length - 1][0] : '')).toUpperCase() || '☕';
+}
+
+const dateFmt = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
+const rtf = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
+
+function relativeTime(ts) {
+  const seconds = Math.round((ts - Date.now()) / 1000);
+  const units = [
+    ['year', 31536000],
+    ['month', 2592000],
+    ['week', 604800],
+    ['day', 86400],
+    ['hour', 3600],
+    ['minute', 60],
+  ];
+  for (const [unit, size] of units) {
+    if (Math.abs(seconds) >= size) return rtf.format(Math.round(seconds / size), unit);
+  }
+  return 'just now';
+}
+
+const FIELD_FOR_ERROR = {
+  invalid_name: 'displayName',
+  invalid_email: 'email',
+  email_taken: 'email',
+  invalid_phone: 'phone',
+};
+
+function focusFieldForError(form, err) {
+  const name = FIELD_FOR_ERROR[err?.code];
+  if (name) form.elements[name]?.focus();
+}
+
+// ---------------------------------------------------------------------------
+// Dialog + navigation
+// ---------------------------------------------------------------------------
+
+function openAccount(tab) {
+  if (tab) state.tab = tab;
+  if (!el.dialog.open) el.dialog.showModal();
+  render();
+}
+
+function closeAccount() {
+  if (el.dialog.open) el.dialog.close();
+}
+
+function updateNav(session) {
+  if (session) {
+    el.sessionLink.textContent = 'Logout';
+    el.sessionLink.dataset.state = 'signed-in';
+    el.sessionLink.href = '#logout';
+    el.accountLink.textContent = `My Account (${firstName(session.user.displayName)})`;
+  } else {
+    el.sessionLink.textContent = 'Sign in';
+    el.sessionLink.dataset.state = 'signed-out';
+    el.sessionLink.href = '#account';
+    el.accountLink.textContent = 'My Account';
+  }
+}
+
+function render() {
+  const session = rp.getSession();
+  updateNav(session);
+  el.unsupported.hidden = state.caps.webauthn;
+
+  if (session) {
+    abortConditionalUI();
+    el.signedOut.hidden = true;
+    el.signedIn.hidden = false;
+    renderProfile(session);
+    renderPasskeys();
+  } else {
+    el.signedIn.hidden = true;
+    el.signedOut.hidden = false;
+    renderTabs();
+  }
+}
+
+function renderTabs() {
+  const signin = state.tab === 'signin';
+  el.tabSignin.setAttribute('aria-selected', String(signin));
+  el.tabRegister.setAttribute('aria-selected', String(!signin));
+  el.tabSignin.tabIndex = signin ? 0 : -1;
+  el.tabRegister.tabIndex = signin ? -1 : 0;
+  el.panelSignin.hidden = !signin;
+  el.panelRegister.hidden = signin;
+  if (signin && el.dialog.open) startConditionalUI();
+  else abortConditionalUI();
+}
+
+function setTab(tab, { focus = false } = {}) {
+  state.tab = tab;
+  clearStatus();
+  renderTabs();
+  if (focus) (tab === 'signin' ? el.tabSignin : el.tabRegister).focus();
+}
+
+function renderProfile(session) {
+  const { user } = session;
+  el.avatar.textContent = initials(user.displayName);
+  el.greeting.textContent = `Hi, ${firstName(user.displayName)}!`;
+  el.email.textContent = user.email;
+  // Don't clobber in-progress edits.
+  if (!el.profileForm.contains(document.activeElement)) {
+    el.profileForm.elements.displayName.value = user.displayName;
+    el.profileForm.elements.email.value = user.email;
+    el.profileForm.elements.phone.value = user.phone ?? '';
+  }
+  el.sessionInfo.textContent = `Signed in ${relativeTime(session.signedInAt)}`;
+}
+
+// ---------------------------------------------------------------------------
+// Passkey list
+// ---------------------------------------------------------------------------
+
+const KEY_ICON =
+  '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="8" cy="15" r="4"/><path d="M10.85 12.15 19 4m-3 3 2 2m-5-1 2 2"/></svg>';
+
+function renderPasskeys() {
+  let passkeys;
+  try {
+    passkeys = rp.listPasskeys();
+  } catch {
+    return;
+  }
+  el.passkeyList.replaceChildren(...passkeys.map((pk) => passkeyItem(pk, passkeys.length)));
+  if (state.renamingId) $(`[data-rename-input]`, el.passkeyList)?.focus();
+}
+
+function passkeyItem(pk, total) {
+  const li = document.createElement('li');
+  li.className = 'passkey-item';
+  li.dataset.id = pk.id;
+
+  const icon = document.createElement('div');
+  icon.className = 'passkey-icon';
+  icon.innerHTML = KEY_ICON;
+
+  const body = document.createElement('div');
+  body.className = 'passkey-body';
+
+  if (state.renamingId === pk.id) {
+    const form = document.createElement('form');
+    form.className = 'rename-form';
+    const input = document.createElement('input');
+    input.type = 'text';
+    input.value = pk.name;
+    input.maxLength = 48;
+    input.required = true;
+    input.dataset.renameInput = '';
+    input.setAttribute('aria-label', 'Passkey name');
+    const save = document.createElement('button');
+    save.type = 'submit';
+    save.className = 'btn-ghost';
+    save.textContent = 'Save';
+    const cancel = document.createElement('button');
+    cancel.type = 'button';
+    cancel.className = 'btn-ghost';
+    cancel.textContent = 'Cancel';
+    cancel.addEventListener('click', () => {
+      state.renamingId = null;
+      renderPasskeys();
+    });
+    input.addEventListener('keydown', (e) => {
+      if (e.key === 'Escape') {
+        e.preventDefault();
+        e.stopPropagation();
+        cancel.click();
+      }
+    });
+    form.addEventListener('submit', (e) => {
+      e.preventDefault();
+      try {
+        const updated = rp.renamePasskey(pk.id, input.value);
+        state.renamingId = null;
+        renderPasskeys();
+        showStatus('success', `Passkey renamed to “${updated.name}”.`);
+      } catch (err) {
+        showStatus('error', describeError(err));
+        input.focus();
+      }
+    });
+    form.append(input, save, cancel);
+    body.append(form);
+  } else {
+    const name = document.createElement('div');
+    name.className = 'passkey-name';
+    name.textContent = pk.name;
+    if (pk.usedThisSession) {
+      const badge = document.createElement('span');
+      badge.className = 'badge';
+      badge.textContent = 'Used this session';
+      name.append(badge);
+    }
+    const meta1 = document.createElement('div');
+    meta1.className = 'passkey-meta';
+    meta1.textContent = `Created ${dateFmt.format(pk.createdAt)} · Last used ${relativeTime(pk.lastUsedAt)}`;
+    const meta2 = document.createElement('div');
+    meta2.className = 'passkey-meta';
+    const details = [];
+    if (pk.provider && pk.provider !== pk.name) details.push(pk.provider);
+    details.push(pk.backedUp ? 'Synced across your devices' : 'Saved on one device');
+    meta2.textContent = details.join(' · ');
+    body.append(name, meta1, meta2);
+  }
+
+  const actions = document.createElement('div');
+  actions.className = 'passkey-actions';
+  if (state.renamingId !== pk.id) {
+    const rename = document.createElement('button');
+    rename.type = 'button';
+    rename.className = 'btn-ghost';
+    rename.textContent = 'Rename';
+    rename.setAttribute('aria-label', `Rename passkey ${pk.name}`);
+    rename.addEventListener('click', () => {
+      state.renamingId = pk.id;
+      renderPasskeys();
+    });
+
+    const remove = document.createElement('button');
+    remove.type = 'button';
+    remove.className = 'btn-ghost danger';
+    remove.textContent = 'Remove';
+    remove.setAttribute('aria-label', `Remove passkey ${pk.name}`);
+    if (total <= 1) {
+      remove.disabled = true;
+      remove.title = 'Add another passkey before removing your only one.';
+    }
+    remove.addEventListener('click', () => removePasskey(pk));
+    actions.append(rename, remove);
+  }
+
+  li.append(icon, body, actions);
+  return li;
+}
+
+// ---------------------------------------------------------------------------
+// Sign-in
+// ---------------------------------------------------------------------------
+
+async function startConditionalUI() {
+  if (!state.caps.conditionalGet || state.conditional || rp.getSession()) return;
+  const controller = new AbortController();
+  state.conditional = controller;
+  try {
+    const options = await rp.startAuthentication();
+    const credential = await getPasskey(options, { mediation: 'conditional', signal: controller.signal });
+    await completeSignIn(credential);
+  } catch (err) {
+    if (isAbort(err) || controller.signal.aborted) return;
+    handleAuthError(err);
+    if (state.conditional === controller) state.conditional = null;
+    // Re-arm autofill after server-side rejections (e.g. a removed passkey).
+    if (err?.name === 'RPError' && el.dialog.open && state.tab === 'signin') startConditionalUI();
+  } finally {
+    if (state.conditional === controller) state.conditional = null;
+  }
+}
+
+function abortConditionalUI() {
+  if (state.conditional) {
+    state.conditional.abort();
+    state.conditional = null;
+  }
+}
+
+async function signInWithButton(event) {
+  event.preventDefault();
+  const button = event.submitter ?? $('button[type="submit"]', el.signinForm);
+  abortConditionalUI();
+  clearStatus();
+  setBusy(button, true);
+  try {
+    const options = await rp.startAuthentication();
+    const credential = await getPasskey(options);
+    await completeSignIn(credential);
+  } catch (err) {
+    if (!isAbort(err)) handleAuthError(err);
+  } finally {
+    setBusy(button, false);
+    if (!rp.getSession() && el.dialog.open && state.tab === 'signin') startConditionalUI();
+  }
+}
+
+async function completeSignIn(credential) {
+  const { user } = await rp.finishAuthentication(credential);
+  syncProviderWithAccount(user);
+  el.signinForm.reset();
+  render();
+  showStatus('success', `Welcome back, ${firstName(user.displayName)}!`);
+  toast(`Signed in as ${user.email}`);
+}
+
+function handleAuthError(err) {
+  if (err?.code === 'unknown_credential' && err.credentialId) {
+    signalUnknownCredential(rp.getRpId(), err.credentialId);
+  }
+  showStatus('error', describeError(err, 'get'));
+}
+
+/** Tell the passkey provider which passkeys and user details are current. */
+function syncProviderWithAccount(user) {
+  try {
+    const ids = rp.listPasskeys().map((p) => p.id);
+    signalAllAcceptedCredentials(rp.getRpId(), user.id, ids);
+    signalCurrentUserDetails(rp.getRpId(), user.id, user.email, user.displayName);
+  } catch {
+    /* not signed in */
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Registration
+// ---------------------------------------------------------------------------
+
+async function register(event) {
+  event.preventDefault();
+  const form = el.registerForm;
+  const button = event.submitter ?? $('button[type="submit"]', form);
+  const data = Object.fromEntries(new FormData(form));
+  abortConditionalUI();
+  clearStatus();
+  setBusy(button, true);
+  try {
+    const options = await rp.startRegistration(data);
+    const credential = await createPasskey(options);
+    const { user } = await rp.finishRegistration(credential);
+    form.reset();
+    state.tab = 'signin';
+    render();
+    showStatus(
+      'success',
+      `Welcome to The Daily Grind, ${firstName(user.displayName)}! Your account is ready and your passkey is saved — use it next time you sign in.`,
+    );
+    toast('Account created');
+  } catch (err) {
+    if (isAbort(err)) return;
+    showStatus('error', describeError(err, 'create'));
+    focusFieldForError(form, err);
+  } finally {
+    setBusy(button, false);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Reauthentication
+// ---------------------------------------------------------------------------
+
+/**
+ * Ask the user to confirm a sensitive action. Prompts for a passkey unless the
+ * session was verified within the reauth window (or `requireFresh` is set).
+ * Resolves `true` when confirmed, `false` when cancelled.
+ */
+function confirmIdentity({ title = 'Confirm it’s you', message, confirmLabel, danger = false, requireFresh = false }) {
+  const needsPasskey = requireFresh || !rp.isRecentlyVerified();
+  if (!needsPasskey && !confirmLabel) return Promise.resolve(true);
+  if (state.reauth) closeReauth(false);
+
+  el.reauthTitle.textContent = title;
+  el.reauthDesc.textContent = needsPasskey
+    ? `${message} For your security, confirm it’s you with one of your passkeys.`
+    : message;
+  el.reauthError.hidden = true;
+  el.reauthConfirm.textContent = needsPasskey ? 'Continue with passkey' : confirmLabel;
+  el.reauthConfirm.dataset.busyLabel = 'Waiting for your passkey…';
+  el.reauthConfirm.classList.toggle('btn-danger', danger);
+
+  const returnFocus = document.activeElement;
+  el.body.inert = true;
+  el.reauthSheet.hidden = false;
+  el.reauthConfirm.focus();
+
+  return new Promise((resolve) => {
+    state.reauth = { resolve, needsPasskey, returnFocus };
+  });
+}
+
+async function onReauthConfirm() {
+  const pending = state.reauth;
+  if (!pending) return;
+  if (!pending.needsPasskey) return closeReauth(true);
+
+  el.reauthError.hidden = true;
+  setBusy(el.reauthConfirm, true);
+  try {
+    const options = await rp.startReauthentication();
+    const credential = await getPasskey(options);
+    await rp.finishReauthentication(credential);
+    if (state.reauth === pending) closeReauth(true);
+  } catch (err) {
+    if (state.reauth !== pending) return;
+    if (err?.code === 'unknown_credential' && err.credentialId) signalUnknownCredential(rp.getRpId(), err.credentialId);
+    el.reauthError.textContent = describeError(err, 'get');
+    el.reauthError.hidden = false;
+  } finally {
+    setBusy(el.reauthConfirm, false);
+  }
+}
+
+function closeReauth(result) {
+  const pending = state.reauth;
+  state.reauth = null;
+  el.reauthSheet.hidden = true;
+  el.body.inert = false;
+  if (pending) {
+    if (pending.returnFocus?.isConnected) pending.returnFocus.focus();
+    pending.resolve(result);
+  }
+}
+
+/** Confirm identity, then run `action`; retries once if the server demands fresh verification. */
+async function runSensitive(prompt, action) {
+  if (!(await confirmIdentity(prompt))) return { cancelled: true };
+  try {
+    return { result: await action() };
+  } catch (err) {
+    if (err?.code !== 'reauth_required') throw err;
+    if (!(await confirmIdentity({ ...prompt, requireFresh: true }))) return { cancelled: true };
+    return { result: await action() };
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Account management
+// ---------------------------------------------------------------------------
+
+async function saveProfile(event) {
+  event.preventDefault();
+  const form = el.profileForm;
+  const button = event.submitter ?? $('button[type="submit"]', form);
+  const data = Object.fromEntries(new FormData(form));
+  const session = rp.getSession();
+  if (!session) return render();
+
+  const emailChanged = String(data.email).trim().toLowerCase() !== session.user.email;
+  clearStatus();
+  setBusy(button, true);
+  try {
+    const outcome = emailChanged
+      ? await runSensitive(
+          { message: `You’re changing your email to ${String(data.email).trim()}.` },
+          () => rp.updateProfile(data),
+        )
+      : { result: rp.updateProfile(data) };
+    if (outcome.cancelled) {
+      showStatus('info', 'Your profile wasn’t changed.');
+      return;
+    }
+    const user = outcome.result;
+    // Update the name shown in passkey pickers/password managers.
+    signalCurrentUserDetails(rp.getRpId(), user.id, user.email, user.displayName);
+    document.activeElement?.blur?.();
+    render();
+    showStatus(
+      'success',
+      emailChanged
+        ? 'Profile updated. Your passkeys will now show your new email address.'
+        : 'Profile updated.',
+    );
+  } catch (err) {
+    showStatus('error', describeError(err));
+    focusFieldForError(form, err);
+  } finally {
+    setBusy(button, false);
+  }
+}
+
+async function addPasskey() {
+  const button = el.addPasskeyBtn;
+  clearStatus();
+  setBusy(button, true);
+  try {
+    const options = await rp.startAddPasskey();
+    const credential = await createPasskey(options);
+    const pk = await rp.finishAddPasskey(credential);
+    renderPasskeys();
+    showStatus('success', `Passkey “${pk.name}” created. You can now sign in with it.`);
+  } catch (err) {
+    if (!isAbort(err)) showStatus('error', describeError(err, 'create'));
+  } finally {
+    setBusy(button, false);
+  }
+}
+
+async function removePasskey(pk) {
+  clearStatus();
+  try {
+    if (rp.listPasskeys().length <= 1) {
+      showStatus('error', 'You can’t remove your only passkey — you’d be locked out. Add another passkey first.');
+      return;
+    }
+    const outcome = await runSensitive(
+      {
+        title: 'Remove passkey?',
+        message: `“${pk.name}” will no longer work for signing in to The Daily Grind.`,
+        confirmLabel: 'Remove passkey',
+        danger: true,
+      },
+      () => rp.deletePasskey(pk.id),
+    );
+    if (outcome.cancelled) return;
+    const session = rp.getSession();
+    if (session) signalAllAcceptedCredentials(rp.getRpId(), session.user.id, outcome.result.remainingCredentialIds);
+    renderPasskeys();
+    showStatus(
+      'success',
+      `Removed “${pk.name}”. If it still appears in your password manager, you can delete it there too.`,
+    );
+  } catch (err) {
+    showStatus('error', describeError(err));
+  }
+}
+
+async function deleteAccount() {
+  clearStatus();
+  try {
+    const outcome = await runSensitive(
+      {
+        title: 'Delete your account?',
+        message: 'This permanently deletes your profile, rewards and all saved passkeys. This can’t be undone.',
+        confirmLabel: 'Delete account',
+        danger: true,
+        requireFresh: true,
+      },
+      () => rp.deleteAccount(),
+    );
+    if (outcome.cancelled) return;
+    // Ask passkey providers to hide every passkey for this account.
+    signalAllAcceptedCredentials(rp.getRpId(), outcome.result.userId, []);
+    state.tab = 'signin';
+    render();
+    showStatus('info', 'Your account has been deleted. We’re sorry to see you go!');
+  } catch (err) {
+    showStatus('error', describeError(err));
+  }
+}
+
+function signOut({ keepOpen = true } = {}) {
+  rp.signOut();
+  state.tab = 'signin';
+  state.renamingId = null;
+  if (keepOpen && el.dialog.open) {
+    render();
+    showStatus('info', 'You’ve been signed out.');
+  } else {
+    render();
+  }
+  toast('You’ve been signed out');
+}
+
+// ---------------------------------------------------------------------------
+// Wiring
+// ---------------------------------------------------------------------------
+
+function bindEvents() {
+  el.accountLink.addEventListener('click', (e) => {
+    e.preventDefault();
+    openAccount();
+  });
+
+  el.sessionLink.addEventListener('click', (e) => {
+    e.preventDefault();
+    if (rp.getSession()) signOut({ keepOpen: false });
+    else openAccount('signin');
+  });
+
+  el.dialog.addEventListener('click', (e) => {
+    const action = e.target.closest('[data-action]')?.dataset.action;
+    if (action === 'close') closeAccount();
+    else if (action === 'show-register') setTab('register', { focus: true });
+    else if (action === 'sign-out') signOut();
+    else if (action === 'reauth-cancel') closeReauth(false);
+    else if (action === 'reauth-confirm') onReauthConfirm();
+    else if (e.target === el.dialog) closeAccount(); // backdrop click
+  });
+
+  el.dialog.addEventListener('cancel', (e) => {
+    if (state.reauth) {
+      e.preventDefault();
+      closeReauth(false);
+    }
+  });
+
+  el.dialog.addEventListener('close', () => {
+    abortConditionalUI();
+    closeReauth(false);
+    clearStatus();
+    state.renamingId = null;
+    if (location.hash === '#account') history.replaceState(null, '', location.pathname + location.search);
+  });
+
+  el.tabSignin.addEventListener('click', () => setTab('signin'));
+  el.tabRegister.addEventListener('click', () => setTab('register'));
+  for (const tab of [el.tabSignin, el.tabRegister]) {
+    tab.addEventListener('keydown', (e) => {
+      if (['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(e.key)) {
+        e.preventDefault();
+        setTab(state.tab === 'signin' ? 'register' : 'signin', { focus: true });
+      }
+    });
+  }
+
+  el.signinForm.addEventListener('submit', signInWithButton);
+  el.registerForm.addEventListener('submit', register);
+  el.profileForm.addEventListener('submit', saveProfile);
+  el.addPasskeyBtn.addEventListener('click', addPasskey);
+  el.deleteAccountBtn.addEventListener('click', deleteAccount);
+
+  // Keep multiple tabs in sync (sign-in/out, passkey changes).
+  window.addEventListener('storage', (e) => {
+    if (e.key?.startsWith('dailygrind.')) render();
+  });
+
+  window.addEventListener('hashchange', () => {
+    if (location.hash === '#account') openAccount();
+  });
+}
+
+async function init() {
+  bindEvents();
+  state.caps = await getCapabilities();
+  if (!state.caps.webauthn) {
+    for (const button of el.dialog.querySelectorAll(
+      '#signin-form button[type="submit"], #register-form button[type="submit"], #add-passkey-btn, [data-action="reauth-confirm"]',
+    )) {
+      button.dataset.requiresPasskeys = 'true';
+      button.disabled = true;
+    }
+  }
+  render();
+  if (location.hash === '#account') openAccount();
+}
+
+init();
