+// In-browser WebAuthn Relying Party for The Daily Grind.
+//
+// The site is currently a static page with no backend, so this module plays the
+// role of the server: it issues single-use challenges, verifies attestation and
+// assertion responses (client data, RP ID hash, user presence/verification flags,
+// signatures and signature counters), and owns accounts, passkeys and sessions.
+//
+// Each exported function maps 1:1 to an HTTP endpoint (noted in the comments) and
+// only exchanges JSON-serialisable data, so it can be replaced with `fetch()`
+// calls to a real server without touching the UI. In production these checks
+// MUST run server-side — anything stored in the browser can be tampered with.
+
+import {
+  b64urlDecode,
+  b64urlEncode,
+  bytesEqual,
+  bytesToUuid,
+  concatBytes,
+  randomBytes,
+  sha256,
+} from './encoding.js';
+
+const DB_KEY = 'dailygrind.rp.v1';
+const SESSION_KEY = 'dailygrind.session.v1';
+const RP_NAME = 'The Daily Grind';
+const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+const CEREMONY_TIMEOUT_MS = 3 * 60 * 1000;
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+
+const ALG_ES256 = -7;
+const ALG_RS256 = -257;
+const SUPPORTED_ALGS = [ALG_ES256, ALG_RS256];
+
+// Friendly names for common passkey providers, keyed by AAGUID.
+// Source: https://github.com/passkeydeveloper/passkey-authenticator-aaguids
+const KNOWN_PROVIDERS = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+};
+
+export class RPError extends Error {
+  constructor(code, message, details = {}) {
+    super(message);
+    this.name = 'RPError';
+    this.code = code;
+    Object.assign(this, details);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Storage
+// ---------------------------------------------------------------------------
+
+function emptyDb() {
+  return { users: {}, credentials: {} };
+}
+
+function loadDb() {
+  try {
+    const db = JSON.parse(localStorage.getItem(DB_KEY));
+    if (db && typeof db.users === 'object' && typeof db.credentials === 'object') return db;
+  } catch {
+    /* fall through */
+  }
+  return emptyDb();
+}
+
+function saveDb(db) {
+  localStorage.setItem(DB_KEY, JSON.stringify(db));
+}
+
+function loadSession() {
+  try {
+    const s = JSON.parse(localStorage.getItem(SESSION_KEY));
+    if (s && s.userId) return s;
+  } catch {
+    /* fall through */
+  }
+  return null;
+}
+
+function saveSession(session) {
+  if (session) localStorage.setItem(SESSION_KEY, JSON.stringify(session));
+  else localStorage.removeItem(SESSION_KEY);
+}
+
+// Challenges live only in memory: a reload invalidates any in-flight ceremony.
+const challenges = new Map();
+
+function issueChallenge(purpose, data = {}) {
+  const now = Date.now();
+  for (const [key, rec] of challenges) if (rec.expiresAt < now) challenges.delete(key);
+  const challenge = b64urlEncode(randomBytes(32));
+  challenges.set(challenge, { purpose, expiresAt: now + CHALLENGE_TTL_MS, ...data });
+  return challenge;
+}
+
+function consumeChallenge(challenge, purpose) {
+  const record = challenges.get(challenge);
+  challenges.delete(challenge);
+  if (!record || record.purpose !== purpose) {
+    throw new RPError('invalid_challenge', 'This request is no longer valid. Please try again.');
+  }
+  if (record.expiresAt < Date.now()) {
+    throw new RPError('expired_challenge', 'This request timed out. Please try again.');
+  }
+  return record;
+}
+
+function rpId() {
+  return location.hostname;
+}
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+function normaliseEmail(email) {
+  return String(email ?? '').trim().toLowerCase();
+}
+
+function validateProfile({ displayName, email, phone }) {
+  const name = String(displayName ?? '').trim();
+  const mail = normaliseEmail(email);
+  const tel = String(phone ?? '').trim();
+  if (!name) throw new RPError('invalid_name', 'Please enter your name.');
+  if (name.length > 64) throw new RPError('invalid_name', 'Name must be 64 characters or fewer.');
+  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(mail)) throw new RPError('invalid_email', 'Please enter a valid email address.');
+  if (tel && !/^[+()\-.\s\d]{7,20}$/.test(tel)) throw new RPError('invalid_phone', 'Please enter a valid phone number.');
+  return { displayName: name, email: mail, phone: tel };
+}
+
+function findUserByEmail(db, email) {
+  return Object.values(db.users).find((u) => u.email === email) ?? null;
+}
+
+function credentialsForUser(db, userId) {
+  return Object.values(db.credentials).filter((c) => c.userId === userId);
+}
+
+function descriptorFor(cred) {
+  return { type: 'public-key', id: cred.id, transports: cred.transports ?? [] };
+}
+
+function publicUser(user) {
+  if (!user) return null;
+  const { id, email, displayName, phone, createdAt, updatedAt } = user;
+  return { id, email, displayName, phone, createdAt, updatedAt };
+}
+
+function publicCredential(cred, session) {
+  return {
+    id: cred.id,
+    name: cred.name,
+    provider: cred.provider,
+    createdAt: cred.createdAt,
+    lastUsedAt: cred.lastUsedAt,
+    backupEligible: cred.backupEligible,
+    backedUp: cred.backedUp,
+    transports: cred.transports,
+    authenticatorAttachment: cred.authenticatorAttachment,
+    usedThisSession: session?.credentialId === cred.id,
+  };
+}
+
+function parseAuthenticatorData(bytes) {
+  if (bytes.length < 37) throw new RPError('invalid_response', 'Malformed authenticator data.');
+  const flagsByte = bytes[32];
+  const flags = {
+    up: !!(flagsByte & 0x01),
+    uv: !!(flagsByte & 0x04),
+    be: !!(flagsByte & 0x08),
+    bs: !!(flagsByte & 0x10),
+    at: !!(flagsByte & 0x40),
+    ed: !!(flagsByte & 0x80),
+  };
+  const signCount = new DataView(bytes.buffer, bytes.byteOffset + 33, 4).getUint32(0, false);
+  const parsed = { rpIdHash: bytes.slice(0, 32), flags, signCount };
+  if (flags.at) {
+    if (bytes.length < 55) throw new RPError('invalid_response', 'Malformed attested credential data.');
+    parsed.aaguid = bytesToUuid(bytes.slice(37, 53));
+    const idLength = (bytes[53] << 8) | bytes[54];
+    parsed.credentialId = bytes.slice(55, 55 + idLength);
+  }
+  return parsed;
+}
+
+function parseClientData(b64) {
+  const raw = b64urlDecode(b64);
+  let data;
+  try {
+    data = JSON.parse(new TextDecoder().decode(raw));
+  } catch {
+    throw new RPError('invalid_response', 'Malformed client data.');
+  }
+  return { raw, data };
+}
+
+async function verifyCommon({ clientDataJSON, authenticatorData }, expectedType, purpose) {
+  const clientData = parseClientData(clientDataJSON);
+  if (clientData.data.type !== expectedType) {
+    throw new RPError('invalid_response', 'Unexpected WebAuthn ceremony type.');
+  }
+  const record = consumeChallenge(clientData.data.challenge, purpose);
+  if (clientData.data.origin !== location.origin) {
+    throw new RPError('invalid_origin', 'This passkey request came from an unexpected origin.');
+  }
+  if (clientData.data.crossOrigin === true) {
+    throw new RPError('invalid_origin', 'Cross-origin passkey requests are not allowed.');
+  }
+
+  const authDataBytes = b64urlDecode(authenticatorData);
+  const authData = parseAuthenticatorData(authDataBytes);
+  if (!bytesEqual(authData.rpIdHash, await sha256(rpId()))) {
+    throw new RPError('invalid_rp', 'This passkey belongs to a different website.');
+  }
+  if (!authData.flags.up) throw new RPError('user_not_present', 'User presence was not confirmed.');
+  if (!authData.flags.uv) {
+    throw new RPError('user_not_verified', 'Your device did not verify you (PIN, fingerprint or face). Please try again.');
+  }
+  if (authData.flags.bs && !authData.flags.be) {
+    throw new RPError('invalid_response', 'Inconsistent backup flags.');
+  }
+  return { record, clientData, authData, authDataBytes };
+}
+
+function derToRawEcdsa(der, size = 32) {
+  let i = 0;
+  const fail = () => {
+    throw new RPError('invalid_signature', 'Malformed signature.');
+  };
+  if (der[i++] !== 0x30) fail();
+  const seqLen = der[i++];
+  if (seqLen & 0x80) i += seqLen & 0x7f;
+  const readInt = () => {
+    if (der[i++] !== 0x02) fail();
+    const len = der[i++];
+    let v = der.slice(i, i + len);
+    i += len;
+    while (v.length > size && v[0] === 0) v = v.slice(1);
+    if (v.length > size) fail();
+    const out = new Uint8Array(size);
+    out.set(v, size - v.length);
+    return out;
+  };
+  return concatBytes(readInt(), readInt());
+}
+
+function importParamsFor(alg) {
+  if (alg === ALG_ES256) return { name: 'ECDSA', namedCurve: 'P-256' };
+  if (alg === ALG_RS256) return { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' };
+  throw new RPError('unsupported_algorithm', 'This passkey uses an unsupported algorithm.');
+}
+
+async function importPublicKey(spkiB64, alg) {
+  try {
+    return await crypto.subtle.importKey('spki', b64urlDecode(spkiB64), importParamsFor(alg), false, ['verify']);
+  } catch (err) {
+    if (err instanceof RPError) throw err;
+    throw new RPError('invalid_public_key', 'The passkey public key could not be read.');
+  }
+}
+
+async function verifySignature(cred, signatureB64, signedData) {
+  const key = await importPublicKey(cred.publicKey, cred.alg);
+  let signature = b64urlDecode(signatureB64);
+  let params = { name: 'RSASSA-PKCS1-v1_5' };
+  if (cred.alg === ALG_ES256) {
+    signature = derToRawEcdsa(signature);
+    params = { name: 'ECDSA', hash: 'SHA-256' };
+  }
+  return crypto.subtle.verify(params, key, signature, signedData);
+}
+
+function defaultPasskeyName(provider, attachment, existing) {
+  let base = provider ?? (attachment === 'cross-platform' ? 'Security key' : 'Passkey');
+  const taken = new Set(existing.map((c) => c.name));
+  if (!taken.has(base)) return base;
+  let n = 2;
+  while (taken.has(`${base} (${n})`)) n++;
+  return `${base} (${n})`;
+}
+
+async function verifyAndStoreRegistration(credential, purpose) {
+  const response = credential?.response ?? {};
+  if (credential?.type !== 'public-key' || !response.clientDataJSON || !response.authenticatorData) {
+    throw new RPError('invalid_response', 'Malformed registration response.');
+  }
+  const { record, authData } = await verifyCommon(response, 'webauthn.create', purpose);
+
+  if (!authData.flags.at || !authData.credentialId) {
+    throw new RPError('invalid_response', 'Registration response is missing credential data.');
+  }
+  if (b64urlEncode(authData.credentialId) !== credential.id || credential.rawId !== credential.id) {
+    throw new RPError('invalid_response', 'Credential ID mismatch.');
+  }
+  const alg = response.publicKeyAlgorithm;
+  if (!SUPPORTED_ALGS.includes(alg) || !response.publicKey) {
+    throw new RPError('unsupported_algorithm', 'This passkey uses an unsupported algorithm.');
+  }
+  await importPublicKey(response.publicKey, alg); // ensure the key is usable before storing
+
+  const db = loadDb();
+  if (db.credentials[credential.id]) {
+    throw new RPError('credential_exists', 'This passkey is already registered.');
+  }
+
+  const now = Date.now();
+  let user;
+  if (purpose === 'register') {
+    if (findUserByEmail(db, record.profile.email)) {
+      throw new RPError('email_taken', 'An account with this email already exists. Try signing in instead.');
+    }
+    user = { id: record.userId, ...record.profile, createdAt: now, updatedAt: now };
+    db.users[user.id] = user;
+  } else {
+    user = db.users[record.userId];
+    if (!user) throw new RPError('no_account', 'Your account could not be found.');
+  }
+
+  const provider = KNOWN_PROVIDERS[authData.aaguid] ?? null;
+  const stored = {
+    id: credential.id,
+    userId: user.id,
+    publicKey: response.publicKey,
+    alg,
+    signCount: authData.signCount,
+    transports: Array.isArray(response.transports) ? response.transports : [],
+    aaguid: authData.aaguid,
+    provider,
+    authenticatorAttachment: credential.authenticatorAttachment ?? null,
+    backupEligible: authData.flags.be,
+    backedUp: authData.flags.bs,
+    name: defaultPasskeyName(provider, credential.authenticatorAttachment, credentialsForUser(db, user.id)),
+    createdAt: now,
+    lastUsedAt: now,
+  };
+  db.credentials[stored.id] = stored;
+  saveDb(db);
+  return { user, credential: stored };
+}
+
+async function verifyAssertion(credential, purpose) {
+  const response = credential?.response ?? {};
+  if (credential?.type !== 'public-key' || !response.clientDataJSON || !response.authenticatorData || !response.signature) {
+    throw new RPError('invalid_response', 'Malformed sign-in response.');
+  }
+
+  const db = loadDb();
+  const stored = db.credentials[credential.id];
+  if (!stored) {
+    // Consume the challenge so it can't be replayed, then report the unknown ID
+    // so the client can ask the passkey provider to hide it.
+    try {
+      consumeChallenge(parseClientData(response.clientDataJSON).data.challenge, purpose);
+    } catch {
+      /* ignore */
+    }
+    throw new RPError('unknown_credential', "This passkey isn't linked to an account here anymore. It may have been removed.", {
+      credentialId: credential.id,
+    });
+  }
+
+  const { record, clientData, authData, authDataBytes } = await verifyCommon(response, 'webauthn.get', purpose);
+
+  if (response.userHandle && response.userHandle !== stored.userId) {
+    throw new RPError('user_mismatch', 'This passkey does not belong to that account.');
+  }
+  if (record.userId && record.userId !== stored.userId) {
+    throw new RPError('user_mismatch', 'Please use a passkey for the account you are signed in to.');
+  }
+
+  const signedData = concatBytes(authDataBytes, await sha256(clientData.raw));
+  if (!(await verifySignature(stored, response.signature, signedData))) {
+    throw new RPError('invalid_signature', 'The passkey signature could not be verified.');
+  }
+
+  if ((authData.signCount !== 0 || stored.signCount !== 0) && authData.signCount <= stored.signCount) {
+    throw new RPError('cloned_authenticator', 'This passkey failed a security check. Please use a different passkey.');
+  }
+
+  stored.signCount = authData.signCount;
+  stored.backedUp = authData.flags.bs;
+  stored.lastUsedAt = Date.now();
+  saveDb(db);
+
+  const user = db.users[stored.userId];
+  if (!user) throw new RPError('no_account', 'The account for this passkey no longer exists.', { credentialId: stored.id });
+  return { user, credential: stored };
+}
+
+function requireSession() {
+  const session = loadSession();
+  const db = loadDb();
+  if (!session || !db.users[session.userId]) {
+    saveSession(null);
+    throw new RPError('not_signed_in', 'Please sign in to continue.');
+  }
+  return { session, db, user: db.users[session.userId] };
+}
+
+function requireRecentVerification(session) {
+  if (Date.now() - (session.verifiedAt ?? 0) > REAUTH_WINDOW_MS) {
+    throw new RPError('reauth_required', 'Please confirm it’s you to continue.');
+  }
+}
+
+function startSession(userId, credentialId) {
+  const now = Date.now();
+  const session = { userId, credentialId, signedInAt: now, verifiedAt: now };
+  saveSession(session);
+  return session;
+}
+
+function creationOptions({ challenge, user, excludeCredentials }) {
+  return {
+    rp: { id: rpId(), name: RP_NAME },
+    user: { id: user.id, name: user.email, displayName: user.displayName },
+    challenge,
+    pubKeyCredParams: SUPPORTED_ALGS.map((alg) => ({ type: 'public-key', alg })),
+    timeout: CEREMONY_TIMEOUT_MS,
+    excludeCredentials,
+    authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'required' },
+    attestation: 'none',
+    hints: [],
+    extensions: { credProps: true },
+  };
+}
+
+// ---------------------------------------------------------------------------
+// Public API ("endpoints")
+// ---------------------------------------------------------------------------
+
+export function getRpId() {
+  return rpId();
+}
+
+/** POST /api/passkeys/register/options — start creating a new account. */
+export async function startRegistration(profileInput) {
+  const profile = validateProfile(profileInput);
+  const db = loadDb();
+  if (findUserByEmail(db, profile.email)) {
+    throw new RPError('email_taken', 'An account with this email already exists. Try signing in instead.');
+  }
+  const userId = b64urlEncode(randomBytes(32));
+  const challenge = issueChallenge('register', { userId, profile });
+  return creationOptions({ challenge, user: { id: userId, ...profile }, excludeCredentials: [] });
+}
+
+/** POST /api/passkeys/register/verify — finish creating a new account. */
+export async function finishRegistration(credential) {
+  const { user, credential: stored } = await verifyAndStoreRegistration(credential, 'register');
+  startSession(user.id, stored.id);
+  return { user: publicUser(user) };
+}
+
+/** POST /api/passkeys/authenticate/options — start signing in (discoverable). */
+export async function startAuthentication() {
+  return {
+    challenge: issueChallenge('authenticate'),
+    rpId: rpId(),
+    timeout: CEREMONY_TIMEOUT_MS,
+    userVerification: 'required',
+    allowCredentials: [],
+  };
+}
+
+/** POST /api/passkeys/authenticate/verify — finish signing in. */
+export async function finishAuthentication(credential) {
+  const { user, credential: stored } = await verifyAssertion(credential, 'authenticate');
+  startSession(user.id, stored.id);
+  return { user: publicUser(user) };
+}
+
+/** POST /api/passkeys/reauthenticate/options — confirm identity for a sensitive action. */
+export async function startReauthentication() {
+  const { db, user } = requireSession();
+  return {
+    challenge: issueChallenge('reauthenticate', { userId: user.id }),
+    rpId: rpId(),
+    timeout: CEREMONY_TIMEOUT_MS,
+    userVerification: 'required',
+    allowCredentials: credentialsForUser(db, user.id).map(descriptorFor),
+  };
+}
+
+/** POST /api/passkeys/reauthenticate/verify */
+export async function finishReauthentication(credential) {
+  const { session } = requireSession();
+  const { credential: stored } = await verifyAssertion(credential, 'reauthenticate');
+  saveSession({ ...session, verifiedAt: Date.now(), credentialId: stored.id });
+  return { ok: true };
+}
+
+/** GET /api/session */
+export function getSession() {
+  try {
+    const { session, user } = requireSession();
+    return {
+      user: publicUser(user),
+      signedInAt: session.signedInAt,
+      verifiedAt: session.verifiedAt,
+      recentlyVerified: Date.now() - (session.verifiedAt ?? 0) <= REAUTH_WINDOW_MS,
+    };
+  } catch {
+    return null;
+  }
+}
+
+/** POST /api/logout */
+export function signOut() {
+  saveSession(null);
+}
+
+/** GET /api/passkeys */
+export function listPasskeys() {
+  const { session, db, user } = requireSession();
+  return credentialsForUser(db, user.id)
+    .sort((a, b) => b.createdAt - a.createdAt)
+    .map((c) => publicCredential(c, session));
+}
+
+/** POST /api/passkeys/options — add another passkey to the signed-in account. */
+export async function startAddPasskey() {
+  const { db, user } = requireSession();
+  const challenge = issueChallenge('add-passkey', { userId: user.id });
+  return creationOptions({
+    challenge,
+    user,
+    excludeCredentials: credentialsForUser(db, user.id).map(descriptorFor),
+  });
+}
+
+/** POST /api/passkeys */
+export async function finishAddPasskey(credential) {
+  const { session } = requireSession();
+  const { credential: stored } = await verifyAndStoreRegistration(credential, 'add-passkey');
+  if (stored.userId !== session.userId) throw new RPError('user_mismatch', 'Account mismatch.');
+  return publicCredential(stored, session);
+}
+
+/** PATCH /api/passkeys/:id */
+export function renamePasskey(id, name) {
+  const { session, db, user } = requireSession();
+  const cred = db.credentials[id];
+  if (!cred || cred.userId !== user.id) throw new RPError('not_found', 'Passkey not found.');
+  const trimmed = String(name ?? '').trim();
+  if (!trimmed) throw new RPError('invalid_name', 'Passkey name can’t be empty.');
+  if (trimmed.length > 48) throw new RPError('invalid_name', 'Passkey name must be 48 characters or fewer.');
+  cred.name = trimmed;
+  saveDb(db);
+  return publicCredential(cred, session);
+}
+
+/** DELETE /api/passkeys/:id — requires recent reauthentication. */
+export function deletePasskey(id) {
+  const { session, db, user } = requireSession();
+  const cred = db.credentials[id];
+  if (!cred || cred.userId !== user.id) throw new RPError('not_found', 'Passkey not found.');
+  if (credentialsForUser(db, user.id).length <= 1) {
+    throw new RPError('last_passkey', 'You can’t remove your only passkey — you’d be locked out. Add another passkey first.');
+  }
+  requireRecentVerification(session);
+  delete db.credentials[id];
+  saveDb(db);
+  return { remainingCredentialIds: credentialsForUser(db, user.id).map((c) => c.id) };
+}
+
+/** PATCH /api/account — changing the email requires recent reauthentication. */
+export function updateProfile(input) {
+  const { session, db, user } = requireSession();
+  const profile = validateProfile(input);
+  if (profile.email !== user.email) {
+    requireRecentVerification(session);
+    const other = findUserByEmail(db, profile.email);
+    if (other && other.id !== user.id) throw new RPError('email_taken', 'That email is already used by another account.');
+  }
+  Object.assign(user, profile, { updatedAt: Date.now() });
+  saveDb(db);
+  return publicUser(user);
+}
+
+/** DELETE /api/account — requires recent reauthentication. */
+export function deleteAccount() {
+  const { session, db, user } = requireSession();
+  requireRecentVerification(session);
+  for (const cred of credentialsForUser(db, user.id)) delete db.credentials[cred.id];
+  delete db.users[user.id];
+  saveDb(db);
+  saveSession(null);
+  return { userId: user.id };
+}
+
+/** Whether a sensitive action can proceed without another passkey prompt. */
+export function isRecentlyVerified() {
+  return getSession()?.recentlyVerified ?? false;
+}
