+// Browser-side WebAuthn helpers: feature detection, JSON <-> binary option
+// conversion, credential serialisation, the Signal API and friendly errors.
+
+import { b64urlDecode, b64urlEncode } from './encoding.js';
+
+const PKC = typeof window !== 'undefined' ? window.PublicKeyCredential : undefined;
+
+export function isWebAuthnSupported() {
+  return !!(PKC && navigator.credentials && typeof navigator.credentials.create === 'function' && window.isSecureContext);
+}
+
+export async function getCapabilities() {
+  const caps = { webauthn: isWebAuthnSupported(), conditionalGet: false, platformAuthenticator: false };
+  if (!caps.webauthn) return caps;
+  try {
+    if (typeof PKC.getClientCapabilities === 'function') {
+      const c = await PKC.getClientCapabilities();
+      caps.conditionalGet = !!c.conditionalGet;
+      caps.platformAuthenticator = !!(c.userVerifyingPlatformAuthenticator ?? c.passkeyPlatformAuthenticator);
+      return caps;
+    }
+  } catch {
+    /* fall back to legacy checks */
+  }
+  try {
+    caps.conditionalGet = !!(await PKC.isConditionalMediationAvailable?.());
+  } catch {
+    /* ignore */
+  }
+  try {
+    caps.platformAuthenticator = !!(await PKC.isUserVerifyingPlatformAuthenticatorAvailable?.());
+  } catch {
+    /* ignore */
+  }
+  return caps;
+}
+
+function decodeDescriptors(list = []) {
+  return list.map((d) => ({ ...d, id: b64urlDecode(d.id) }));
+}
+
+function toCreationOptions(json) {
+  if (typeof PKC.parseCreationOptionsFromJSON === 'function') {
+    try {
+      return PKC.parseCreationOptionsFromJSON(json);
+    } catch {
+      /* fall back to manual conversion */
+    }
+  }
+  const { hints, ...rest } = json;
+  return {
+    ...rest,
+    ...(hints?.length ? { hints } : {}),
+    challenge: b64urlDecode(json.challenge),
+    user: { ...json.user, id: b64urlDecode(json.user.id) },
+    excludeCredentials: decodeDescriptors(json.excludeCredentials),
+  };
+}
+
+function toRequestOptions(json) {
+  if (typeof PKC.parseRequestOptionsFromJSON === 'function') {
+    try {
+      return PKC.parseRequestOptionsFromJSON(json);
+    } catch {
+      /* fall back to manual conversion */
+    }
+  }
+  return {
+    ...json,
+    challenge: b64urlDecode(json.challenge),
+    allowCredentials: decodeDescriptors(json.allowCredentials),
+  };
+}
+
+function encodeOptional(buf) {
+  return buf ? b64urlEncode(buf) : undefined;
+}
+
+function registrationToJSON(cred) {
+  const r = cred.response;
+  if (typeof r.getAuthenticatorData !== 'function' || typeof r.getPublicKey !== 'function') {
+    throw new PasskeyError('unsupported', 'Your browser is too old to create passkeys. Please update it and try again.');
+  }
+  const publicKey = r.getPublicKey();
+  if (!publicKey) {
+    throw new PasskeyError('unsupported', 'Your passkey provider used an algorithm we don’t support yet.');
+  }
+  return {
+    id: cred.id,
+    rawId: b64urlEncode(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? null,
+    clientExtensionResults: cred.getClientExtensionResults?.() ?? {},
+    response: {
+      clientDataJSON: b64urlEncode(r.clientDataJSON),
+      attestationObject: b64urlEncode(r.attestationObject),
+      authenticatorData: b64urlEncode(r.getAuthenticatorData()),
+      publicKey: b64urlEncode(publicKey),
+      publicKeyAlgorithm: r.getPublicKeyAlgorithm(),
+      transports: r.getTransports?.() ?? [],
+    },
+  };
+}
+
+function assertionToJSON(cred) {
+  const r = cred.response;
+  return {
+    id: cred.id,
+    rawId: b64urlEncode(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? null,
+    clientExtensionResults: cred.getClientExtensionResults?.() ?? {},
+    response: {
+      clientDataJSON: b64urlEncode(r.clientDataJSON),
+      authenticatorData: b64urlEncode(r.authenticatorData),
+      signature: b64urlEncode(r.signature),
+      userHandle: encodeOptional(r.userHandle),
+    },
+  };
+}
+
+export class PasskeyError extends Error {
+  constructor(code, message) {
+    super(message);
+    this.name = 'PasskeyError';
+    this.code = code;
+  }
+}
+
+/** Run navigator.credentials.create() and return a JSON-serialisable result. */
+export async function createPasskey(optionsJSON) {
+  if (!isWebAuthnSupported()) throw new PasskeyError('unsupported', 'Passkeys aren’t supported in this browser.');
+  const cred = await navigator.credentials.create({ publicKey: toCreationOptions(optionsJSON) });
+  if (!cred) throw new PasskeyError('cancelled', 'Passkey creation was cancelled.');
+  return registrationToJSON(cred);
+}
+
+/**
+ * Run navigator.credentials.get(). Pass `mediation: 'conditional'` together with
+ * an AbortSignal to power passkey autofill on an `autocomplete="… webauthn"` field.
+ */
+export async function getPasskey(optionsJSON, { mediation, signal } = {}) {
+  if (!isWebAuthnSupported()) throw new PasskeyError('unsupported', 'Passkeys aren’t supported in this browser.');
+  const request = { publicKey: toRequestOptions(optionsJSON) };
+  if (mediation) request.mediation = mediation;
+  if (signal) request.signal = signal;
+  const cred = await navigator.credentials.get(request);
+  if (!cred) throw new PasskeyError('cancelled', 'Sign-in was cancelled.');
+  return assertionToJSON(cred);
+}
+
+// --- Signal API: keep passkey providers in sync with our records ------------
+
+export function signalUnknownCredential(rpId, credentialId) {
+  PKC?.signalUnknownCredential?.({ rpId, credentialId }).catch(() => {});
+}
+
+export function signalAllAcceptedCredentials(rpId, userId, allAcceptedCredentialIds) {
+  PKC?.signalAllAcceptedCredentials?.({ rpId, userId, allAcceptedCredentialIds }).catch(() => {});
+}
+
+export function signalCurrentUserDetails(rpId, userId, name, displayName) {
+  PKC?.signalCurrentUserDetails?.({ rpId, userId, name, displayName }).catch(() => {});
+}
+
+// --- Errors ------------------------------------------------------------------
+
+export function isAbort(err) {
+  return err?.name === 'AbortError';
+}
+
+export function describeError(err, context = 'generic') {
+  if (!err) return 'Something went wrong. Please try again.';
+  if (err.name === 'RPError' || err.name === 'PasskeyError') return err.message;
+  switch (err.name) {
+    case 'NotAllowedError':
+      return context === 'create'
+        ? 'Passkey creation was cancelled or timed out.'
+        : 'The passkey request was cancelled or timed out.';
+    case 'InvalidStateError':
+      return context === 'create'
+        ? 'A passkey for this account already exists on this device or password manager.'
+        : 'That passkey can’t be used right now. Please try another.';
+    case 'SecurityError':
+      return 'Passkeys can’t be used on this address. Make sure you’re on the official Daily Grind site over HTTPS.';
+    case 'NotSupportedError':
+      return 'Your device doesn’t support the type of passkey we need.';
+    case 'AbortError':
+      return 'The passkey request was interrupted.';
+    case 'ConstraintError':
+      return 'Your device couldn’t verify you (PIN, fingerprint or face lock may not be set up).';
+    default:
+      console.error(err);
+      return 'Something went wrong with your passkey. Please try again.';
+  }
+}

