+
+interface PasskeyList {
+  rpId: string;
+  userId: string;
+  reauthExpiresAt: number;
+  credentials: Passkey[];
+}
+
+interface Props {
+  username: string;
+  displayName: string;
+}
+
+type SensitiveAction = { kind: 'create' } | { kind: 'delete'; passkey: Passkey };
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+const formatDate = (epoch?: number) => (epoch ? dateFormat.format(new Date(epoch)) : null);
+
+const buttonPrimary =
+  'inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-60 disabled:cursor-not-allowed';
+const buttonSecondary =
+  'inline-flex items-center justify-center gap-2 py-2 px-3 rounded-md text-sm font-medium text-gray-800 border border-gray-300 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-60 disabled:cursor-not-allowed';
+const buttonDanger =
+  'inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md shadow-sm text-sm font-medium text-white bg-red-700 hover:bg-red-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-700 disabled:opacity-60 disabled:cursor-not-allowed';
+const inputClass =
+  'w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500';
+
+export default function AccountSettings({ username, displayName: initialDisplayName }: Props) {
+  const [list, setList] = useState<PasskeyList | null>(null);
+  const [loadError, setLoadError] = useState<string | null>(null);
+  const [message, setMessage] = useState<string | null>(null);
+  const [error, setError] = useState<string | null>(null);
+  const [passkeySupported, setPasskeySupported] = useState<boolean | null>(null);
+  const [webauthnAvailable, setWebauthnAvailable] = useState(false);
+
+  const [displayName, setDisplayName] = useState(initialDisplayName);
+  const [displayNameDraft, setDisplayNameDraft] = useState(initialDisplayName);
+  const [savingProfile, setSavingProfile] = useState(false);
+
+  const [renamingId, setRenamingId] = useState<string | null>(null);
+  const [renameDraft, setRenameDraft] = useState('');
+
+  const [pendingAction, setPendingAction] = useState<SensitiveAction | null>(null);
+  const [creating, setCreating] = useState(false);
+
+  const profileHeadingId = useId();
+  const passkeysHeadingId = useId();
+
+  const loadPasskeys = useCallback(async (): Promise<PasskeyList | null> => {
+    const res = await fetch(`${import.meta.env.BASE_URL}api/passkeys`, { credentials: 'same-origin' });
+    if (res.status === 401) {
+      window.location.assign(`${import.meta.env.BASE_URL}signin`);
+      return null;
+    }
+    if (!res.ok) {
+      setLoadError(await readError(res, 'Could not load your passkeys.'));
+      return null;
+    }
+    const data = (await res.json()) as PasskeyList;
+    setList(data);
+    setLoadError(null);
+    return data;
+  }, []);
+
+  /** Keeps password managers in sync with the server's list of valid passkeys. */
+  const syncAccepted = (data: PasskeyList | null) => {
+    if (data) signalAllAcceptedCredentials(data.rpId, data.userId, data.credentials.map((c) => c.id));
+  };
+
+  useEffect(() => {
+    loadPasskeys().then(syncAccepted);
+    loadWebAuthn().then(async (PKC) => {
+      setWebauthnAvailable(Boolean(PKC));
+      // Feature-detect a platform authenticator before promoting passkeys on this device.
+      const caps = await getCapabilities();
+      setPasskeySupported(Boolean(caps.passkeyPlatformAuthenticator));
+    });
+    const params = new URLSearchParams(window.location.search);
+    if (params.get('passkey') === 'created') setMessage('Passkey created. You can now sign in with it.');
+  }, [loadPasskeys]);
+
+  const reauthIsFresh = () => !!list && list.reauthExpiresAt > Date.now();
+
+  // ---------- Profile ----------
+
+  const handleProfileSubmit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setMessage(null);
+    setSavingProfile(true);
+    try {
+      const res = await postJSON('/auth/user', { displayName: displayNameDraft }, 'PUT');
+      if (!res.ok) {
+        setError(await readError(res, 'Could not update your display name.'));
+        return;
+      }
+      const updated = await res.json();
+      setDisplayName(updated.displayName);
+      setDisplayNameDraft(updated.displayName);
+      setMessage('Display name updated.');
+      // Update the account details shown by password managers for this site's passkeys.
+      await signalCurrentUserDetails(updated.rpId, updated.userId, updated.name, updated.displayName);
+    } finally {
+      setSavingProfile(false);
+    }
+  };
+
+  // ---------- Passkeys ----------
+
+  const doCreatePasskey = async () => {
+    setError(null);
+    setMessage(null);
+    setCreating(true);
+    const result = await registerPasskey('manage');
+    setCreating(false);
+    if (result.status === 'created') {
+      setMessage('Passkey created.');
+      await loadPasskeys();
+    } else if (result.status === 'error') {
+      if (result.code === 403) {
+        await loadPasskeys();
+        setPendingAction({ kind: 'create' });
+        return;
+      }
+      setError(result.message);
+    }
+  };
+
+  const doDeletePasskey = async (passkey: Passkey): Promise<boolean> => {
+    setError(null);
+    setMessage(null);
+    const res = await postJSON(`/passkeys/${encodeURIComponent(passkey.id)}`, undefined, 'DELETE');
+    if (res.status === 403) {
+      await loadPasskeys();
+      return false; // reauth window lapsed; dialog stays open and asks again
+    }
+    if (!res.ok) {
+      setError(await readError(res, 'Could not delete the passkey.'));
+      return true;
+    }
+    setMessage(
+      `“${passkey.name}” was removed from your account. It may also disappear from your password manager.`,
+    );
+    syncAccepted(await loadPasskeys());
+    return true;
+  };
+
+  const startRename = (passkey: Passkey) => {
+    setRenamingId(passkey.id);
+    setRenameDraft(passkey.name);
+  };
+
+  const handleRenameSubmit = async (e: React.FormEvent, passkey: Passkey) => {
+    e.preventDefault();
+    setError(null);
+    setMessage(null);
+    const res = await postJSON(`/passkeys/${encodeURIComponent(passkey.id)}`, { name: renameDraft }, 'PATCH');
+    if (!res.ok) {
+      setError(await readError(res, 'Could not rename the passkey.'));
+      return;
+    }
+    setRenamingId(null);
+    setMessage('Passkey renamed.');
+    await loadPasskeys();
+  };
+
+  const handleSignOut = async () => {
+    await postJSON('/auth/logout');
+    window.location.assign(import.meta.env.BASE_URL);
+  };
+
+  const passkeys = list?.credentials ?? [];
+
+  return (
+    <div className="max-w-3xl mx-auto space-y-8">
+      <div className="flex flex-wrap items-center justify-between gap-4">
+        <h1 className="text-3xl font-bold text-gray-900">Account settings</h1>
+        <button type="button" onClick={handleSignOut} className={buttonSecondary}>
+          Sign out
+        </button>
+      </div>
+
+      <div aria-live="polite" className="space-y-2">
+        {message && <p className="p-3 text-sm text-green-800 bg-green-100 rounded-lg">{message}</p>}
+      </div>
+      {error && (
+        <p className="p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+          {error}
+        </p>
+      )}
+
+      {/* Profile */}
+      <section aria-labelledby={profileHeadingId} className="p-6 bg-white border border-gray-200 rounded-lg shadow-sm">
+        <h2 id={profileHeadingId} className="text-xl font-semibold text-gray-900">
+          Profile
+        </h2>
+        <dl className="mt-4 text-sm">
+          <dt className="font-medium text-gray-700">Username</dt>
+          <dd className="mt-1 text-gray-900">{username}</dd>
+        </dl>
+        <form onSubmit={handleProfileSubmit} className="mt-4 flex flex-col sm:flex-row sm:items-end gap-3">
+          <div className="flex-1">
+            <label htmlFor="display-name" className="block text-sm font-medium text-gray-700 mb-1">
+              Display name
+            </label>
+            <input
+              id="display-name"
+              name="displayName"
+              autoComplete="name"
+              maxLength={64}
+              required
+              value={displayNameDraft}
+              onChange={(e) => setDisplayNameDraft(e.target.value)}
+              aria-describedby="display-name-hint"
+              className={inputClass}
+            />
+          </div>
+          <button
+            type="submit"
+            className={buttonPrimary}
+            disabled={savingProfile || displayNameDraft.trim() === displayName}
+          >
+            {savingProfile ? 'Saving...' : 'Save'}
+          </button>
+        </form>
+        <p id="display-name-hint" className="mt-2 text-xs text-gray-500">
+          Shown in your password manager when you choose a passkey for The DevTools Times.
+        </p>
+      </section>
+
+      {/* Passkeys */}
+      <section aria-labelledby={passkeysHeadingId} className="p-6 bg-white border border-gray-200 rounded-lg shadow-sm">
+        <div className="flex flex-wrap items-start justify-between gap-4">
+          <div>
+            <h2 id={passkeysHeadingId} className="text-xl font-semibold text-gray-900">
+              Passkeys
+            </h2>
+            <p className="mt-1 text-sm text-gray-600">
+              Sign in with your fingerprint, face, screen lock, or a security key instead of a password.
+            </p>
+          </div>
+          {webauthnAvailable && (
+            <button
+              type="button"
+              className={buttonPrimary}
+              disabled={creating || !list}
+              onClick={() => (reauthIsFresh() ? doCreatePasskey() : setPendingAction({ kind: 'create' }))}
+            >
+              <PlusIcon className="h-5 w-5" aria-hidden="true" />
+              {creating ? 'Creating...' : 'Create a passkey'}
+            </button>
+          )}
+        </div>
+
+        {passkeySupported === false && (
+          <p className="mt-4 p-3 text-sm text-amber-900 bg-amber-50 border border-amber-200 rounded-md">
+            {webauthnAvailable
+              ? 'This device has no built-in passkey support, but you can still add a security key or use a phone.'
+              : 'Passkeys aren’t supported in this browser. Keep your password strong and unique.'}
+          </p>
+        )}
+
+        {loadError && (
+          <p className="mt-4 text-sm text-red-700" role="alert">
+            {loadError}
+          </p>
+        )}
+
+        {list && passkeys.length === 0 && (
+          <div className="mt-6 p-6 text-center border border-dashed border-gray-300 rounded-md">
+            <KeyIcon className="mx-auto h-8 w-8 text-gray-400" aria-hidden="true" />
+            <p className="mt-2 text-sm text-gray-600">No passkeys yet.</p>
+          </div>
+        )}
+
+        {passkeys.length > 0 && (
+          <ul className="mt-6 divide-y divide-gray-200 border-y border-gray-200">
+            {passkeys.map((passkey) => {
+              const lastUsed = formatDate(passkey.lastUsedAt);
+              const renameInputId = `rename-${passkey.id}`;
+              return (
+                <li key={passkey.id} className="py-4 flex flex-col sm:flex-row sm:items-center gap-4">
+                  <div className="flex items-center gap-3 flex-1 min-w-0">
+                    {passkey.providerIcon ? (
+                      <img src={passkey.providerIcon} alt="" width={32} height={32} className="h-8 w-8 shrink-0" />
+                    ) : (
+                      <KeyIcon className="h-8 w-8 shrink-0 text-gray-500" aria-hidden="true" />
+                    )}
+                    <div className="min-w-0 flex-1">
+                      {renamingId === passkey.id ? (
+                        <form onSubmit={(e) => handleRenameSubmit(e, passkey)} className="flex flex-wrap items-center gap-2">
+                          <label htmlFor={renameInputId} className="sr-only">
+                            Passkey name
+                          </label>
+                          <input
+                            id={renameInputId}
+                            value={renameDraft}
+                            onChange={(e) => setRenameDraft(e.target.value)}
+                            maxLength={64}
+                            required
+                            autoFocus
+                            autoComplete="off"
+                            className={`${inputClass} max-w-xs`}
+                          />
+                          <button type="submit" className={buttonPrimary}>
+                            Save
+                          </button>
+                          <button type="button" className={buttonSecondary} onClick={() => setRenamingId(null)}>
+                            Cancel
+                          </button>
+                        </form>
+                      ) : (
+                        <p className="font-medium text-gray-900 truncate">{passkey.name}</p>
+                      )}
+                      <p className="mt-1 text-xs text-gray-600">
+                        Created {formatDate(passkey.registeredAt)}
+                        {' · '}
+                        {lastUsed ? `Last used ${lastUsed}` : 'Never used'}
+                      </p>
+                      <p className="mt-1 text-xs text-gray-500">
+                        {passkey.credentialBackedUp ? 'Synced across your devices' : 'Stored on one device or security key'}
+                      </p>
+                    </div>
+                  </div>
+                  {renamingId !== passkey.id && (
+                    <div className="flex gap-2 sm:shrink-0">
+                      <button type="button" className={buttonSecondary} onClick={() => startRename(passkey)}>
+                        <PencilSquareIcon className="h-4 w-4" aria-hidden="true" />
+                        Rename<span className="sr-only"> {passkey.name}</span>
+                      </button>
+                      <button
+                        type="button"
+                        className={`${buttonSecondary} text-red-700`}
+                        onClick={() => setPendingAction({ kind: 'delete', passkey })}
+                      >
+                        <TrashIcon className="h-4 w-4" aria-hidden="true" />
+                        Delete<span className="sr-only"> {passkey.name}</span>
+                      </button>
+                    </div>
+                  )}
+                </li>
+              );
+            })}
+          </ul>
+        )}
+      </section>
+
+      <SensitiveActionDialog
+        action={pendingAction}
+        needsReauth={!reauthIsFresh()}
+        canUsePasskey={webauthnAvailable && passkeys.length > 0}
+        onReauthenticated={(reauthExpiresAt) => setList((l) => (l ? { ...l, reauthExpiresAt } : l))}
+        onConfirm={async (action) => {
+          if (action.kind === 'create') {
+            setPendingAction(null);
+            await doCreatePasskey();
+          } else if (await doDeletePasskey(action.passkey)) {
+            setPendingAction(null);
+          }
+        }}
+        onClose={() => setPendingAction(null)}
+      />
+    </div>
+  );
+}
+
+/**
+ * Modal that (1) reauthenticates the user if their last sign-in is stale —
+ * with a passkey restricted to their own credentials, or their password —
+ * and (2) asks for explicit confirmation of the sensitive action.
+ */
+function SensitiveActionDialog({
+  action,
+  needsReauth,
+  canUsePasskey,
+  onReauthenticated,
+  onConfirm,
+  onClose,
+}: {
+  action: SensitiveAction | null;
+  needsReauth: boolean;
+  canUsePasskey: boolean;
+  onReauthenticated: (reauthExpiresAt: number) => void;
+  onConfirm: (action: SensitiveAction) => Promise<void>;
+  onClose: () => void;
+}) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const titleId = useId();
+  const descId = useId();
+  const passwordId = useId();
+  const abortRef = useRef<AbortController | null>(null);
+  const [password, setPassword] = useState('');
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (action && !dialog.open) {
+      setPassword('');
+      setError(null);
+      dialog.showModal();
+    } else if (!action && dialog.open) {
+      dialog.close();
+    }
+  }, [action]);
+
+  const handleClose = () => {
+    abortRef.current?.abort();
+    abortRef.current = null;
+    setBusy(false);
+    onClose();
+  };
+
+  const verifyWithPasskey = async () => {
+    setError(null);
+    setBusy(true);
+    abortRef.current?.abort();
+    abortRef.current = new AbortController();
+    const result = await getPasskeyAssertion({
+      optionsPath: '/reauth/options',
+      verifyPath: '/reauth/verify',
+      signal: abortRef.current.signal,
+      // The user is signed in, so a 404 here must not prune credentials from their provider.
+      signalUnknownOn404: false,
+    });
+    setBusy(false);
+    if (result.status === 'ok') onReauthenticated(result.data.reauthExpiresAt);
+    else if (result.status === 'error') setError(result.message);
+  };
+
+  const verifyWithPassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy(true);
+    try {
+      const res = await postJSON('/reauth/password', { password });
+      if (!res.ok) {
+        setError(await readError(res, 'Verification failed.'));
+        return;
+      }
+      const data = await res.json();
+      setPassword('');
+      onReauthenticated(data.reauthExpiresAt);
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const confirm = async () => {
+    if (!action) return;
+    setError(null);
+    setBusy(true);
+    try {
+      await onConfirm(action);
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const isDelete = action?.kind === 'delete';
+  const passkeyName = action?.kind === 'delete' ? action.passkey.name : '';
+  const title = needsReauth ? 'Verify it’s you' : isDelete ? 'Delete this passkey?' : 'Create a passkey';
+  const description = needsReauth
+    ? isDelete
+      ? `To protect your account, confirm your identity before deleting “${passkeyName}”.`
+      : 'To protect your account, confirm your identity before adding a new passkey.'
+    : isDelete
+      ? `You won’t be able to sign in with “${passkeyName}” anymore. Also remove it from your password manager if it doesn’t disappear automatically.`
+      : 'Your browser will ask where to save the passkey — this device, your phone, or a security key.';
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={titleId}
+      aria-describedby={descId}
+      onClose={handleClose}
+      className="m-auto w-[min(28rem,calc(100%-2rem))] rounded-lg p-0 shadow-xl backdrop:bg-black/50"
+    >
+      <div className="p-6">
+        <div className="flex items-center gap-3">
+          {needsReauth ? (
+            <ShieldCheckIcon className="h-7 w-7 text-gray-800" aria-hidden="true" />
+          ) : isDelete ? (
+            <TrashIcon className="h-7 w-7 text-red-700" aria-hidden="true" />
+          ) : (
+            <KeyIcon className="h-7 w-7 text-gray-800" aria-hidden="true" />
+          )}
+          <h1 id={titleId} className="text-lg font-semibold text-gray-900">
+            {title}
+          </h1>
+        </div>
+        <p id={descId} className="mt-3 text-sm text-gray-600">
+          {description}
+        </p>
+
+        {error && (
+          <p className="mt-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+            {error}
+          </p>
+        )}
+
+        {needsReauth ? (
+          <div className="mt-5 space-y-4">
+            {canUsePasskey && (
+              <button type="button" className={`${buttonPrimary} w-full`} onClick={verifyWithPasskey} disabled={busy} autoFocus>
+                <KeyIcon className="h-5 w-5" aria-hidden="true" />
+                Verify with a passkey
+              </button>
+            )}
+            <form onSubmit={verifyWithPassword} className="space-y-3">
+              <div>
+                <label htmlFor={passwordId} className="block text-sm font-medium text-gray-700 mb-1">
+                  {canUsePasskey ? 'Or enter your password' : 'Password'}
+                </label>
+                <input
+                  id={passwordId}
+                  type="password"
+                  autoComplete="current-password"
+                  required
+                  value={password}
+                  onChange={(e) => setPassword(e.target.value)}
+                  autoFocus={!canUsePasskey}
+                  className={inputClass}
+                />
+              </div>
+              <div className="flex justify-end gap-2">
+                <button type="button" className={buttonSecondary} onClick={() => dialogRef.current?.close()}>
+                  Cancel
+                </button>
+                <button type="submit" className={canUsePasskey ? buttonSecondary : buttonPrimary} disabled={busy}>
+                  Verify password
+                </button>
+              </div>
+            </form>
+          </div>
