diff --git a/src/lib/auth/aaguid.ts b/src/lib/auth/aaguid.ts
new file mode 100644
index 0000000..81449d9
--- /dev/null
+++ b/src/lib/auth/aaguid.ts
@@ -0,0 +1,43 @@
+/**
+ * Maps authenticator AAGUIDs to passkey provider names/icons using the
+ * community registry. This is used ONLY as a UX hint in the management list —
+ * never for any security decision (platform AAGUIDs are not attested).
+ */
+const REGISTRY_URL =
+  'https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/refs/heads/main/combined_aaguid.json';
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+const CACHE_TTL_MS = 24 * 60 * 60 * 1000;
+
+type Registry = Record<string, { name: string; icon_light?: string; icon_dark?: string }>;
+
+let registry: Registry | null = null;
+let fetchedAt = 0;
+let inflight: Promise<Registry | null> | null = null;
+
+async function loadRegistry(): Promise<Registry | null> {
+  if (registry && Date.now() - fetchedAt < CACHE_TTL_MS) return registry;
+  inflight ??= (async () => {
+    try {
+      const res = await fetch(REGISTRY_URL, { signal: AbortSignal.timeout(4000) });
+      if (!res.ok) return registry;
+      registry = (await res.json()) as Registry;
+      fetchedAt = Date.now();
+      return registry;
+    } catch {
+      return registry; // keep any stale copy; lookups degrade gracefully
+    } finally {
+      inflight = null;
+    }
+  })();
+  return inflight;
+}
+
+export async function lookupProvider(aaguid: string): Promise<{ name: string; icon?: string }> {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return { name: 'Passkey' };
+  }
+  const reg = await loadRegistry();
+  const entry = reg?.[aaguid];
+  return { name: entry?.name ?? 'Passkey', icon: entry?.icon_light };
+}
