--- /dev/null
+++ b/src/lib/auth/config.ts
@@ -0,0 +1,29 @@
+/**
+ * Relying Party configuration.
+ *
+ * Set PASSKEY_RP_ID (e.g. "astro-news-pytrpecapa-uc.a.run.app") and
+ * PASSKEY_ORIGINS (comma separated, e.g. "https://astro-news-pytrpecapa-uc.a.run.app")
+ * in production. When unset, the values fall back to the host the request was
+ * served from (Astro resolves forwarded hosts listed in `security.allowedDomains`),
+ * which keeps `http://localhost` development working.
+ *
+ * The RP ID is always decided on the server and handed to the client inside
+ * WebAuthn options / API responses — the client never derives it itself.
+ */
+export const RP_NAME = 'The DevTools Times';
+
+/** Remote service that owns username/password accounts. */
+export const AUTH_API_BASE = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+/** Sensitive actions require a sign-in or reauthentication within this window. */
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+
+export function getRpId(url: URL): string {
+  return process.env.PASSKEY_RP_ID || url.hostname;
+}
+
+export function getExpectedOrigins(url: URL): string[] {
+  const configured = process.env.PASSKEY_ORIGINS?.split(',').map((o) => o.trim()).filter(Boolean);
+  if (configured?.length) return configured;
+  return [url.origin];
+}
diff --git a/src/lib/auth/session.ts b/src/lib/auth/session.ts
