+++ b/src/lib/auth/session.ts
@@ -0,0 +1,65 @@
+import type { AstroSession } from 'astro';
+import { REAUTH_WINDOW_MS } from './config';
+import { getUser, type StoredPasskeyCredential, type StoredUser } from './store';
+
+export function json(body: unknown, status = 200): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export function errorResponse(error: string, status: number): Response {
+  return json({ error }, status);
+}
+
+/** Returns the signed-in user, or undefined. */
+export async function getSessionUser(session: AstroSession | undefined): Promise<StoredUser | undefined> {
+  const username = (await session?.get('user')) as string | undefined;
+  if (!username) return undefined;
+  return getUser(username);
+}
+
+/** Starts an authenticated session (rotating the session ID to prevent fixation). */
+export async function startSession(session: AstroSession | undefined, username: string): Promise<void> {
+  if (!session) throw new Error('Sessions are not configured');
+  await session.regenerate();
+  session.set('user', username);
+  // A fresh sign-in counts as a recent authentication for sensitive actions.
+  session.set('authenticatedAt', Date.now());
+}
+
+export async function markReauthenticated(session: AstroSession | undefined): Promise<void> {
+  session?.set('authenticatedAt', Date.now());
+}
+
+export async function getReauthExpiry(session: AstroSession | undefined): Promise<number> {
+  const at = ((await session?.get('authenticatedAt')) as number | undefined) ?? 0;
+  return at + REAUTH_WINDOW_MS;
+}
+
+export async function hasRecentAuth(session: AstroSession | undefined): Promise<boolean> {
+  return (await getReauthExpiry(session)) > Date.now();
+}
+
+/** Public shape of a credential (never expose public keys or counters). */
+export function toPublicCredential(c: StoredPasskeyCredential) {
+  return {
+    id: c.id,
+    name: c.name,
+    providerIcon: c.providerIcon,
+    aaguid: c.aaguid,
+    credentialDeviceType: c.credentialDeviceType,
+    credentialBackedUp: c.credentialBackedUp,
+    registeredAt: c.registeredAt,
+    lastUsedAt: c.lastUsedAt,
+  };
+}
+
+export async function readJson<T = Record<string, unknown>>(request: Request): Promise<T> {
+  try {
+    return (await request.json()) as T;
+  } catch {
+    return {} as T;
+  }
+}
diff --git a/src/lib/auth/store.ts b/src/lib/auth/store.ts
new file mode 100644
index 0000000..ff745ff
--- /dev/null
+++ b/src/lib/auth/store.ts
@@ -0,0 +1,130 @@
+/**
+ * Minimal persistent store for local user profiles and passkey credentials.
+ *
+ * Passwords are still owned by the remote Times auth service; this store only
+ * keeps the data needed for WebAuthn (user handles and credential public keys).
+ * Data is persisted as JSON on disk so it survives restarts of the Node server.
+ */
+import { randomBytes } from 'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import { dirname, resolve } from 'node:path';
+
+export interface StoredUser {
+  /** Login username (also the WebAuthn `user.name`). */
+  username: string;
+  /** Human-friendly name shown in passkey account pickers. */
+  displayName: string;
+  /** Opaque, random, unpadded Base64URL WebAuthn user handle. */
+  passkeyUserId: string;
+  createdAt: number;
+}
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL credential ID
+  passkeyUserId: string; // Owning user's WebAuthn user handle
+  credentialPublicKey: string; // Base64URL COSE public key
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerIcon?: string;
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+interface Database {
+  users: Record<string, StoredUser>; // keyed by username
+  credentials: Record<string, StoredPasskeyCredential>; // keyed by credential id
+}
+
+const DATA_FILE = resolve(process.env.PASSKEY_DATA_FILE ?? '.data/passkeys.json');
+
+let cache: Database | null = null;
+let writeQueue: Promise<void> = Promise.resolve();
+
+async function load(): Promise<Database> {
+  if (cache) return cache;
+  try {
+    const raw = await readFile(DATA_FILE, 'utf8');
+    const parsed = JSON.parse(raw) as Partial<Database>;
+    cache = { users: parsed.users ?? {}, credentials: parsed.credentials ?? {} };
+  } catch {
+    cache = { users: {}, credentials: {} };
+  }
+  return cache;
+}
+
+function persist(db: Database): Promise<void> {
+  // Serialize writes and write atomically via a temp file + rename.
+  writeQueue = writeQueue
+    .catch(() => {})
+    .then(async () => {
+      await mkdir(dirname(DATA_FILE), { recursive: true });
+      const tmp = `${DATA_FILE}.${process.pid}.tmp`;
+      await writeFile(tmp, JSON.stringify(db, null, 2), 'utf8');
+      await rename(tmp, DATA_FILE);
+    });
+  return writeQueue;
+}
+
+export async function getUser(username: string): Promise<StoredUser | undefined> {
+  const db = await load();
+  return db.users[username];
+}
+
+export async function getUserByPasskeyUserId(passkeyUserId: string): Promise<StoredUser | undefined> {
+  const db = await load();
+  return Object.values(db.users).find((u) => u.passkeyUserId === passkeyUserId);
+}
+
+/** Returns the local profile for a username, creating it on first sign-in. */
+export async function ensureUser(username: string): Promise<StoredUser> {
+  const db = await load();
+  const existing = db.users[username];
+  if (existing) return existing;
+  const user: StoredUser = {
+    username,
+    displayName: username,
+    passkeyUserId: randomBytes(32).toString('base64url'),
+    createdAt: Date.now(),
+  };
+  db.users[username] = user;
+  await persist(db);
+  return user;
+}
+
+export async function updateUserDisplayName(username: string, displayName: string): Promise<StoredUser | undefined> {
+  const db = await load();
+  const user = db.users[username];
+  if (!user) return undefined;
+  user.displayName = displayName;
+  await persist(db);
+  return user;
+}
+
+export async function listCredentials(passkeyUserId: string): Promise<StoredPasskeyCredential[]> {
+  const db = await load();
+  return Object.values(db.credentials)
+    .filter((c) => c.passkeyUserId === passkeyUserId)
+    .sort((a, b) => b.registeredAt - a.registeredAt);
+}
+
+export async function getCredential(id: string): Promise<StoredPasskeyCredential | undefined> {
+  const db = await load();
+  return db.credentials[id];
+}
+
+export async function saveCredential(cred: StoredPasskeyCredential): Promise<void> {
+  const db = await load();
+  db.credentials[cred.id] = cred;
+  await persist(db);
+}
+
+export async function deleteCredential(id: string): Promise<void> {
+  const db = await load();
+  delete db.credentials[id];
+  await persist(db);
+}
diff --git a/src/lib/auth/webauthn.ts b/src/lib/auth/webauthn.ts
new file mode 100644
index 0000000..0561d92
--- /dev/null
+++ b/src/lib/auth/webauthn.ts
@@ -0,0 +1,75 @@
+import {
+  generateAuthenticationOptions,
+  verifyAuthenticationResponse,
+  type AuthenticationResponseJSON,
+} from '@simplewebauthn/server';
+import { getExpectedOrigins, getRpId } from './config';
+import { saveCredential, type StoredPasskeyCredential } from './store';
+
+const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+export interface PendingChallenge {
+  challenge: string;
+  expiresAt: number;
+  userVerification?: 'required' | 'preferred';
+  conditional?: boolean;
+}
+
+export function newPending(challenge: string, extra: Partial<PendingChallenge> = {}): PendingChallenge {
+  return { challenge, expiresAt: Date.now() + CHALLENGE_TTL_MS, ...extra };
+}
+
+export function isPendingValid(p: PendingChallenge | undefined): p is PendingChallenge {
+  return !!p && typeof p.challenge === 'string' && p.expiresAt > Date.now();
+}
+
+export function toBytes(base64url: string): Uint8Array<ArrayBuffer> {
+  return new Uint8Array(Buffer.from(base64url, 'base64url'));
+}
+
+export async function buildRequestOptions(
+  url: URL,
+  allow: StoredPasskeyCredential[] = [],
+  userVerification: 'required' | 'preferred' = 'preferred',
+) {
+  return generateAuthenticationOptions({
+    rpID: getRpId(url),
+    allowCredentials: allow.map((c) => ({ id: c.id, transports: c.transports })),
+    userVerification,
+  });
+}
+
+/**
+ * Verifies an assertion against a stored credential and persists the new
+ * counter / backup state / last-used timestamp. Throws on failure.
+ */
+export async function verifyAssertion(
+  url: URL,
+  response: AuthenticationResponseJSON,
+  pending: PendingChallenge,
+  cred: StoredPasskeyCredential,
+): Promise<void> {
+  const { verified, authenticationInfo } = await verifyAuthenticationResponse({
+    response,
+    expectedChallenge: pending.challenge,
+    expectedOrigin: getExpectedOrigins(url),
+    expectedRPID: getRpId(url),
+    credential: {
+      id: cred.id,
+      publicKey: toBytes(cred.credentialPublicKey),
+      counter: cred.counter,
+      transports: cred.transports,
+    },
+    // UV level comes from the server session, never from the client.
+    requireUserVerification: pending.userVerification === 'required',
+  });
+  if (!verified) throw new Error('Passkey verification failed.');
+
+  await saveCredential({
+    ...cred,
+    counter: authenticationInfo.newCounter,
+    credentialBackedUp: authenticationInfo.credentialBackedUp,
+    credentialDeviceType: authenticationInfo.credentialDeviceType,
+    lastUsedAt: Date.now(),
+  });
+}
diff --git a/src/lib/webauthn-client.ts b/src/lib/webauthn-client.ts
new file mode 100644
index 0000000..bda24ac
--- /dev/null
+++ b/src/lib/webauthn-client.ts
@@ -0,0 +1,228 @@
+/**
+ * Browser-side WebAuthn helpers shared by the sign-in, sign-up, and account UIs.
+ * Uses the native WebAuthn APIs directly; `webauthn-polyfills` only backfills
+ * JSON (de)serialization and getClientCapabilities() where they are missing.
+ */
+
+export const API_BASE = `${import.meta.env.BASE_URL}api`;
+
+export interface ClientCapabilities {
+  conditionalGet?: boolean;
+  conditionalCreate?: boolean;
+  passkeyPlatformAuthenticator?: boolean;
+  [key: string]: boolean | undefined;
+}
+
+/** Static WebAuthn methods that may be missing from older DOM typings. */
+interface PKCStatic {
+  getClientCapabilities?: () => Promise<ClientCapabilities>;
+  parseCreationOptionsFromJSON: (json: unknown) => PublicKeyCredentialCreationOptions;
+  parseRequestOptionsFromJSON: (json: unknown) => PublicKeyCredentialRequestOptions;
+  signalUnknownCredential?: (opts: { rpId: string; credentialId: string }) => Promise<void>;
+  signalAllAcceptedCredentials?: (opts: { rpId: string; userId: string; allAcceptedCredentialIds: string[] }) => Promise<void>;
+  signalCurrentUserDetails?: (opts: { rpId: string; userId: string; name: string; displayName: string }) => Promise<void>;
+}
+
+type JSONCredential = { id: string; [key: string]: unknown };
+
+let ready: Promise<PKCStatic | null> | null = null;
+
+/** Loads polyfills (client only) and resolves to PublicKeyCredential, or null if WebAuthn is unsupported. */
+export function loadWebAuthn(): Promise<PKCStatic | null> {
+  ready ??= (async () => {
+    if (typeof window === 'undefined' || !window.PublicKeyCredential || !window.isSecureContext) return null;
+    try {
+      await import('webauthn-polyfills');
+    } catch (err) {
+      console.warn('WebAuthn polyfills failed to load:', err);
+    }
+    return window.PublicKeyCredential as unknown as PKCStatic;
+  })();
+  return ready;
+}
+
+export async function getCapabilities(): Promise<ClientCapabilities> {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.getClientCapabilities) return {};
+  try {
+    return await PKC.getClientCapabilities();
+  } catch {
+    return {};
+  }
+}
+
+/** Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, length % 4 !== 1. */
+export function isValidBase64Url(value: unknown): value is string {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+export function toJSONCredential(credential: Credential): JSONCredential {
+  return (credential as PublicKeyCredential & { toJSON(): JSONCredential }).toJSON();
+}
+
+export async function postJSON(path: string, body?: unknown, method = 'POST'): Promise<Response> {
+  return fetch(`${API_BASE}${path}`, {
+    method,
+    credentials: 'same-origin',
+    headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+}
+
+export async function readError(response: Response, fallback: string): Promise<string> {
+  const data = await response.json().catch(() => ({}));
+  return (data && (data.error as string)) || fallback;
+}
+
+// ---------- Signal API (progressive enhancement; failures are non-fatal) ----------
+
+export async function signalUnknownCredential(rpId: string | undefined, credentialId: string): Promise<void> {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.signalUnknownCredential || !rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    await PKC.signalUnknownCredential({ rpId, credentialId });
+  } catch (err) {
+    console.warn('signalUnknownCredential sync warning:', err);
+  }
+}
+
+export async function signalAllAcceptedCredentials(rpId: string, userId: string, credentialIds: string[]): Promise<void> {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.signalAllAcceptedCredentials) return;
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL IDs are required.');
+    return;
+  }
+  try {
+    await PKC.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds: credentialIds });
+  } catch (err) {
+    console.warn('signalAllAcceptedCredentials sync warning:', err);
+  }
+}
+
+export async function signalCurrentUserDetails(rpId: string, userId: string, name: string, displayName: string): Promise<void> {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PKC.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (err) {
+    console.warn('signalCurrentUserDetails sync warning:', err);
+  }
+}
+
+// ---------- Registration ----------
+
+export type RegisterResult =
+  | { status: 'created'; credential: unknown }
+  | { status: 'cancelled' }
+  | { status: 'error'; message: string; code?: number };
+
+/**
+ * Creates a passkey for the signed-in user.
+ * `mode`: "promotion" (platform only), "conditional" (silent after password sign-in), or "manage".
+ */
+export async function registerPasskey(mode: 'promotion' | 'conditional' | 'manage'): Promise<RegisterResult> {
+  const PKC = await loadWebAuthn();
+  if (!PKC) return { status: 'error', message: 'Passkeys are not supported in this browser.' };
+
+  const optionsRes = await postJSON('/passkeys/registration-options', {
+    promotion: mode === 'promotion',
+    conditional: mode === 'conditional',
+  });
+  if (!optionsRes.ok) {
+    return { status: 'error', message: await readError(optionsRes, 'Could not start passkey creation.'), code: optionsRes.status };
+  }
+  const publicKey = PKC.parseCreationOptionsFromJSON(await optionsRes.json());
+
+  let credential: Credential | null;
+  try {
+    credential = await navigator.credentials.create({
+      publicKey,
+      ...(mode === 'conditional' && { mediation: 'conditional' as CredentialMediationRequirement }),
+    });
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (mode === 'conditional' || name === 'NotAllowedError' || name === 'AbortError') {
+      return { status: 'cancelled' }; // user dismissed, timed out, or silent create declined
+    }
+    if (name === 'InvalidStateError') {
+      return { status: 'error', message: 'A passkey for this account already exists in this password manager.' };
+    }
+    if (name === 'SecurityError') {
+      return { status: 'error', message: 'Passkeys are not available on this site configuration.' };
+    }
+    return { status: 'error', message: 'Passkey creation failed. Please try again.' };
+  }
+  if (!credential) return { status: 'cancelled' };
+
+  const encoded = toJSONCredential(credential);
+  try {
+    const verifyRes = await postJSON('/passkeys/registration-verify', encoded);
+    if (!verifyRes.ok) {
+      // Server rejected the credential: tell the provider so no orphaned passkey lingers.
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      return { status: 'error', message: await readError(verifyRes, 'Passkey could not be saved.') };
+    }
+    const data = await verifyRes.json();
+    return { status: 'created', credential: data.credential };
+  } catch {
+    await signalUnknownCredential(publicKey.rp.id, encoded.id);
+    return { status: 'error', message: 'Network error while saving your passkey.' };
+  }
+}
+
+// ---------- Authentication / reauthentication ----------
+
+export type AssertionResult =
+  | { status: 'ok'; data: any }
+  | { status: 'cancelled' }
+  | { status: 'error'; message: string };
+
+/**
+ * Runs a passkey assertion against the given options/verify endpoints.
+ * Pass `mediation: 'conditional'` for form autofill.
+ */
+export async function getPasskeyAssertion(opts: {
+  optionsPath: string;
+  verifyPath: string;
+  signal?: AbortSignal;
+  mediation?: CredentialMediationRequirement;
+  /** Only call signalUnknownCredential on 404 when the user is unauthenticated. */
+  signalUnknownOn404?: boolean;
+}): Promise<AssertionResult> {
+  const PKC = await loadWebAuthn();
+  if (!PKC) return { status: 'error', message: 'Passkeys are not supported in this browser.' };
+
+  const optionsRes = await postJSON(opts.optionsPath);
+  if (!optionsRes.ok) return { status: 'error', message: await readError(optionsRes, 'Could not start passkey verification.') };
+  const publicKey = PKC.parseRequestOptionsFromJSON(await optionsRes.json());
+
+  let credential: Credential | null;
+  try {
+    credential = await navigator.credentials.get({ publicKey, signal: opts.signal, mediation: opts.mediation });
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    console.warn('Passkey request failed:', err);
+    return { status: 'error', message: 'Passkey verification failed. Please try again.' };
+  }
+  if (!credential) return { status: 'cancelled' };
+
+  const encoded = toJSONCredential(credential);
+  try {
+    const verifyRes = await postJSON(opts.verifyPath, encoded);
+    if (!verifyRes.ok) {
+      if (verifyRes.status === 404 && opts.signalUnknownOn404) {
+        await signalUnknownCredential(publicKey.rpId, encoded.id);
+      }
+      return { status: 'error', message: await readError(verifyRes, 'Passkey verification failed.') };
+    }
+    return { status: 'ok', data: await verifyRes.json() };
+  } catch {
+    return { status: 'error', message: 'Network error while verifying your passkey.' };
+  }
+}
