diff --git a/src/pages/api/auth/register.ts b/src/pages/api/auth/register.ts
new file mode 100644
index 0000000..626bc4c
--- /dev/null
+++ b/src/pages/api/auth/register.ts
@@ -0,0 +1,31 @@
+import type { APIRoute } from 'astro';
+import { AUTH_API_BASE } from '../../../lib/auth/config';
+import { errorResponse, json, readJson, startSession } from '../../../lib/auth/session';
+import { ensureUser } from '../../../lib/auth/store';
+
+/**
+ * Account sign-up. Proxies the remote Times auth service and signs the new
+ * user in so they can immediately be offered a passkey.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  const { username, password } = await readJson<{ username?: string; password?: string }>(request);
+  if (!username || !password) return errorResponse('Username and password are required.', 400);
+
+  let upstream: Response;
+  try {
+    upstream = await fetch(`${AUTH_API_BASE}/register`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+  } catch {
+    return errorResponse('The sign-up service is unavailable. Please try again later.', 502);
+  }
+
+  const data = await upstream.json().catch(() => ({}));
+  if (!upstream.ok) return json(data, upstream.status);
+
+  const user = await ensureUser(username);
+  await startSession(session, user.username);
+  return json({ user: { name: user.username, displayName: user.displayName } });
+};
