+import type { APIRoute } from 'astro';
+import { getRpId } from '../../../lib/auth/config';
+import { errorResponse, getSessionUser, json, readJson } from '../../../lib/auth/session';
+import { updateUserDisplayName } from '../../../lib/auth/store';
+
+const profile = (user: { username: string; displayName: string; passkeyUserId: string }, url: URL) => ({
+  name: user.username,
+  displayName: user.displayName,
+  rpId: getRpId(url),
+  userId: user.passkeyUserId,
+});
+
+export const GET: APIRoute = async ({ session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return errorResponse('Not signed in.', 401);
+  return json(profile(user, url));
+};
+
+/** Updates the display name; the client then syncs it to passkey providers. */
+export const PUT: APIRoute = async ({ request, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return errorResponse('Not signed in.', 401);
+
+  const { displayName } = await readJson<{ displayName?: string }>(request);
+  const trimmed = displayName?.trim();
+  if (!trimmed || trimmed.length > 64) return errorResponse('Display name must be 1–64 characters.', 400);
+
+  const updated = await updateUserDisplayName(user.username, trimmed);
+  if (!updated) return errorResponse('User not found.', 404);
+  return json(profile(updated, url));
+};
