+import type { APIRoute } from 'astro';
+import { errorResponse, getSessionUser, hasRecentAuth, json, readJson, toPublicCredential } from '../../../lib/auth/session';
+import { deleteCredential, getCredential, saveCredential } from '../../../lib/auth/store';
+
+async function ownedCredential(session: Parameters<typeof getSessionUser>[0], id: string | undefined) {
+  const user = await getSessionUser(session);
+  if (!user) return { error: errorResponse('Not signed in.', 401) };
+  const cred = id ? await getCredential(id) : undefined;
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return { error: errorResponse('Passkey not found.', 404) };
+  }
+  return { user, cred };
+}
+
+/** Renames a passkey (server-side label only). */
+export const PATCH: APIRoute = async ({ params, request, session }) => {
+  const { cred, error } = await ownedCredential(session, params.id);
+  if (error) return error;
+
+  const { name } = await readJson<{ name?: string }>(request);
+  const trimmed = name?.trim();
+  if (!trimmed || trimmed.length > 64) return errorResponse('Name must be 1–64 characters.', 400);
+
+  const updated = { ...cred, name: trimmed };
+  await saveCredential(updated);
+  return json({ credential: toPublicCredential(updated) });
+};
+
+/** Deletes a passkey. Sensitive: requires a recent sign-in or reauthentication. */
+export const DELETE: APIRoute = async ({ params, session }) => {
+  const { cred, error } = await ownedCredential(session, params.id);
+  if (error) return error;
+  if (!(await hasRecentAuth(session))) {
+    return errorResponse('Please verify your identity to delete a passkey.', 403);
+  }
+  await deleteCredential(cred.id);
+  return json({ success: true });
+};
