+import type { APIRoute } from 'astro';
+import type { AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { errorResponse, json, readJson, startSession } from '../../../lib/auth/session';
+import { getCredential, getUserByPasskeyUserId } from '../../../lib/auth/store';
+import { isPendingValid, verifyAssertion, type PendingChallenge } from '../../../lib/auth/webauthn';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const pending = (await session!.get('authentication')) as PendingChallenge | undefined;
+  session!.delete('authentication');
+  if (!isPendingValid(pending)) return errorResponse('Sign-in expired. Please try again.', 400);
+
+  const response = await readJson<AuthenticationResponseJSON>(request);
+  if (!response?.id) return errorResponse('Malformed passkey response.', 400);
+
+  // 404 lets the client signal the provider that this passkey is unknown.
+  const cred = await getCredential(response.id);
+  if (!cred) return errorResponse('This passkey is not registered with The DevTools Times.', 404);
+  const user = await getUserByPasskeyUserId(cred.passkeyUserId);
+  if (!user) return errorResponse('This passkey is not registered with The DevTools Times.', 404);
+  if (response.response?.userHandle && response.response.userHandle !== cred.passkeyUserId) {
+    return errorResponse('Passkey does not match its account.', 400);
+  }
+
+  try {
+    await verifyAssertion(url, response, pending, cred);
+  } catch (err) {
+    return errorResponse(`Passkey sign-in failed: ${(err as Error).message}`, 400);
+  }
+
+  await startSession(session, user.username);
+  return json({ user: { name: user.username, displayName: user.displayName } });
+};
