+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { getRpId, RP_NAME } from '../../../lib/auth/config';
+import { errorResponse, getSessionUser, hasRecentAuth, json, readJson } from '../../../lib/auth/session';
+import { listCredentials } from '../../../lib/auth/store';
+import { newPending, toBytes } from '../../../lib/auth/webauthn';
+
+/**
+ * Creation options for a signed-in user.
+ * - `promotion: true`   → post sign-up/sign-in promotion, platform authenticators only.
+ * - `conditional: true` → automatic (conditional create) after a password sign-in.
+ * - neither             → account settings, security keys allowed too.
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return errorResponse('Not signed in.', 401);
+  if (!(await hasRecentAuth(session))) {
+    return errorResponse('Please verify your identity to add a passkey.', 403);
+  }
+
+  const { promotion = false, conditional = false } = await readJson<{ promotion?: boolean; conditional?: boolean }>(request);
+  const existing = await listCredentials(user.passkeyUserId);
+
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: getRpId(url),
+    userID: toBytes(user.passkeyUserId),
+    userName: user.username,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    excludeCredentials: existing.map((c) => ({ id: c.id, transports: c.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...((promotion || conditional) && { authenticatorAttachment: 'platform' as const }),
+    },
+  });
+
+  session!.set('registration', newPending(options.challenge, { conditional: Boolean(conditional) }));
+  return json(options);
+};
