+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse, type RegistrationResponseJSON } from '@simplewebauthn/server';
+import { lookupProvider } from '../../../lib/auth/aaguid';
+import { getExpectedOrigins, getRpId } from '../../../lib/auth/config';
+import { errorResponse, getSessionUser, json, readJson, toPublicCredential } from '../../../lib/auth/session';
+import { getCredential, saveCredential } from '../../../lib/auth/store';
+import { isPendingValid, type PendingChallenge } from '../../../lib/auth/webauthn';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return errorResponse('Not signed in.', 401);
+
+  const pending = (await session!.get('registration')) as PendingChallenge | undefined;
+  session!.delete('registration'); // challenges are single use
+  if (!isPendingValid(pending)) return errorResponse('Registration expired. Please try again.', 400);
+
+  const response = await readJson<RegistrationResponseJSON>(request);
+
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: getExpectedOrigins(url),
+      expectedRPID: getRpId(url),
+      // Options used userVerification: "preferred", so UV must not be required here.
+      requireUserVerification: false,
+      // Conditional create may legitimately omit user presence; explicit creates may not.
+      requireUserPresence: !pending.conditional,
+    });
+  } catch (err) {
+    return errorResponse(`Passkey registration failed: ${(err as Error).message}`, 400);
+  }
+  if (!verification.verified) return errorResponse('Passkey registration could not be verified.', 400);
+
+  const info = verification.registrationInfo;
+  if (await getCredential(info.credential.id)) {
+    return errorResponse('This passkey is already registered.', 409);
+  }
+
+  const provider = await lookupProvider(info.aaguid);
+  const stored = {
+    id: info.credential.id,
+    passkeyUserId: user.passkeyUserId,
+    credentialPublicKey: Buffer.from(info.credential.publicKey).toString('base64url'),
+    credentialType: 'public-key' as const,
+    credentialDeviceType: info.credentialDeviceType,
+    credentialBackedUp: info.credentialBackedUp,
+    aaguid: info.aaguid,
+    providerIcon: provider.icon,
+    name: provider.name,
+    transports: response.response?.transports ?? info.credential.transports ?? [],
+    registeredAt: Date.now(),
+    counter: info.credential.counter,
+  };
+  await saveCredential(stored);
+  return json({ credential: toPublicCredential(stored) });
+};
