+import type { APIRoute } from 'astro';
+import { AUTH_API_BASE } from '../../../lib/auth/config';
+import { errorResponse, getReauthExpiry, getSessionUser, json, markReauthenticated, readJson } from '../../../lib/auth/session';
+
+/** Password fallback for reauthentication (e.g. accounts without passkeys). */
+export const POST: APIRoute = async ({ request, session }) => {
+  const user = await getSessionUser(session);
+  if (!user) return errorResponse('Not signed in.', 401);
+
+  const { password } = await readJson<{ password?: string }>(request);
+  if (!password) return errorResponse('Password is required.', 400);
+
+  let upstream: Response;
+  try {
+    upstream = await fetch(`${AUTH_API_BASE}/login`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username: user.username, password }),
+    });
+  } catch {
+    return errorResponse('The sign-in service is unavailable. Please try again later.', 502);
+  }
+  if (!upstream.ok) {
+    const data = await upstream.json().catch(() => ({}));
+    return errorResponse(`Verification failed: ${data.error || 'Incorrect password'}`, 401);
+  }
+
+  await markReauthenticated(session);
+  return json({ success: true, reauthExpiresAt: await getReauthExpiry(session) });
+};
