+import type { APIRoute } from 'astro';
+import type { AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { errorResponse, getReauthExpiry, getSessionUser, json, markReauthenticated, readJson } from '../../../lib/auth/session';
+import { getCredential } from '../../../lib/auth/store';
+import { isPendingValid, verifyAssertion, type PendingChallenge } from '../../../lib/auth/webauthn';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return errorResponse('Not signed in.', 401);
+
+  const pending = (await session!.get('reauth')) as PendingChallenge | undefined;
+  session!.delete('reauth');
+  if (!isPendingValid(pending)) return errorResponse('Verification expired. Please try again.', 400);
+
+  const response = await readJson<AuthenticationResponseJSON>(request);
+  const cred = response?.id ? await getCredential(response.id) : undefined;
+  if (!cred) return errorResponse('This passkey is not registered.', 404);
+  // The passkey must belong to the user who is currently signed in.
+  if (cred.passkeyUserId !== user.passkeyUserId) {
+    return errorResponse('This passkey belongs to a different account.', 403);
+  }
+
+  try {
+    await verifyAssertion(url, response, pending, cred);
+  } catch (err) {
+    return errorResponse(`Verification failed: ${(err as Error).message}`, 400);
+  }
+
+  await markReauthenticated(session);
+  return json({ success: true, reauthExpiresAt: await getReauthExpiry(session) });
+};
