@@ -0,0 +1,389 @@
+import React, { useEffect, useRef, useState } from 'react';
+import {
+  CheckIcon,
+  CloudIcon,
+  DevicePhoneMobileIcon,
+  PencilIcon,
+  PlusIcon,
+  ShieldCheckIcon,
+  TrashIcon,
+  XMarkIcon,
+} from '@heroicons/react/24/outline';
+import {
+  ApiError,
+  createPasskey,
+  describeError,
+  passkeysSupported,
+  removePasskey,
+  renamePasskey,
+  routes,
+  signOut,
+} from '../../lib/auth/client';
+import type { AccountSummary, PublicPasskey } from '../../lib/auth/client';
+import ReauthDialog from './ReauthDialog';
+import { Alert, PasskeyIcon } from './ui';
+
+const dateFormat = new Intl.DateTimeFormat('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+
+function formatRelative(iso: string | null) {
+  if (!iso) return 'Never';
+  const diff = Date.now() - new Date(iso).getTime();
+  const minutes = Math.round(diff / 60000);
+  if (minutes < 1) return 'Just now';
+  if (minutes < 60) return `${minutes} min ago`;
+  const hours = Math.round(minutes / 60);
+  if (hours < 24) return `${hours} hr ago`;
+  const days = Math.round(hours / 24);
+  if (days < 7) return `${days} day${days === 1 ? '' : 's'} ago`;
+  return dateFormat.format(new Date(iso));
+}
+
+interface PendingReauth {
+  reason: string;
+  retry: () => Promise<void>;
+}
+
+export default function AccountSettings({ initial }: { initial: AccountSummary }) {
+  const [account, setAccount] = useState(initial);
+  const [supportsPasskeys, setSupportsPasskeys] = useState(true);
+  const [error, setError] = useState<string | null>(null);
+  const [notice, setNotice] = useState<string | null>(null);
+  const [adding, setAdding] = useState(false);
+  const [busyId, setBusyId] = useState<string | null>(null);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [editName, setEditName] = useState('');
+  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
+  const [highlightId, setHighlightId] = useState<string | null>(null);
+  const [reauth, setReauth] = useState<PendingReauth | null>(null);
+  const editInput = useRef<HTMLInputElement>(null);
+
+  const { user, passkeys } = account;
+
+  useEffect(() => {
+    setSupportsPasskeys(passkeysSupported());
+    const params = new URLSearchParams(window.location.search);
+    if (params.get('passkey') === 'created') {
+      setNotice('Passkey created. Next time, just choose your passkey to sign in.');
+      const latest = initial.passkeys[initial.passkeys.length - 1];
+      if (latest) setHighlightId(latest.id);
+      params.delete('passkey');
+      const qs = params.toString();
+      window.history.replaceState(null, '', `${window.location.pathname}${qs ? `?${qs}` : ''}`);
+    }
+  }, [initial.passkeys]);
+
+  useEffect(() => {
+    if (editingId) editInput.current?.focus();
+  }, [editingId]);
+
+  const reset = () => {
+    setError(null);
+    setNotice(null);
+  };
+
+  /**
+   * Runs a sensitive action. If the server says the sign-in is too old, ask the
+   * user to re-authenticate and then retry the action automatically.
+   */
+  const runSensitive = async (reason: string, action: () => Promise<void>) => {
+    try {
+      await action();
+    } catch (err) {
+      if (err instanceof ApiError && err.code === 'REAUTH_REQUIRED') {
+        setReauth({ reason, retry: action });
+        return;
+      }
+      const message = describeError(err);
+      if (message) setError(message);
+    }
+  };
+
+  const handleReauthSuccess = async () => {
+    const pending = reauth;
+    setReauth(null);
+    if (!pending) return;
+    try {
+      await pending.retry();
+    } catch (err) {
+      const message = describeError(err);
+      if (message) setError(message);
+    }
+  };
+
+  const updatePasskeyInState = (pk: PublicPasskey) =>
+    setAccount((prev) => ({ ...prev, passkeys: prev.passkeys.map((p) => (p.id === pk.id ? pk : p)) }));
+
+  const handleAdd = async () => {
+    reset();
+    setAdding(true);
+    await runSensitive('add a passkey', async () => {
+      const result = await createPasskey();
+      setAccount(result.account);
+      setHighlightId(result.passkey.id);
+      setNotice(`“${result.passkey.name}” was added. You can now use it to sign in.`);
+    });
+    setAdding(false);
+  };
+
+  const startRename = (pk: PublicPasskey) => {
+    reset();
+    setConfirmDeleteId(null);
+    setEditingId(pk.id);
+    setEditName(pk.name);
+  };
+
+  const submitRename = async (e: React.FormEvent) => {
+    e.preventDefault();
+    if (!editingId) return;
+    reset();
+    setBusyId(editingId);
+    try {
+      const { passkey } = await renamePasskey(editingId, editName);
+      updatePasskeyInState(passkey);
+      setEditingId(null);
+    } catch (err) {
+      setError(describeError(err));
+    } finally {
+      setBusyId(null);
+    }
+  };
+
+  const handleDelete = async (pk: PublicPasskey) => {
