+      setConfirmDeleteId(null);
+      setNotice(`“${pk.name}” was removed. You may also want to delete it from your password manager or device.`);
+    });
+    setBusyId(null);
+  };
+
+  const handleSignOut = async () => {
+    try {
+      await signOut();
+    } finally {
+      window.location.assign(routes.home);
