+      </section>
+
+      {/* Passkeys */}
+      <section aria-labelledby="passkeys-heading" className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm">
+        <div className="flex flex-wrap items-start justify-between gap-4">
+          <div>
+            <h2 id="passkeys-heading" className="flex items-center gap-2 text-lg font-semibold text-gray-900">
+              <PasskeyIcon /> Passkeys
+            </h2>
+            <p className="mt-1 max-w-md text-sm text-gray-600">
+              Passkeys let you sign in with your fingerprint, face, or screen lock. They’re safer than passwords and
+              can’t be phished.
+            </p>
+          </div>
+          {supportsPasskeys && (
+            <button
+              type="button"
