+            <ShieldCheckIcon className="mx-auto h-8 w-8 text-gray-400" />
+            <p className="mt-2 text-sm font-medium text-gray-900">No passkeys yet</p>
+            <p className="mt-1 text-sm text-gray-500">Create one to skip your password next time you sign in.</p>
+          </div>
+        ) : (
+          <ul className="mt-6 divide-y divide-gray-200 border-y border-gray-200">
+            {passkeys.map((pk) => (
+              <li
+                key={pk.id}
+                className={`flex flex-col gap-3 py-4 sm:flex-row sm:items-center transition-colors ${
