+                          value={editName}
+                          onChange={(e) => setEditName(e.target.value)}
+                          onKeyDown={(e) => e.key === 'Escape' && setEditingId(null)}
+                          maxLength={64}
+                          required
+                          className="min-w-0 flex-1 rounded-md border border-gray-300 px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
+                        />
+                        <button
+                          type="submit"
+                          disabled={busyId === pk.id}
+                          className="rounded p-1 text-green-700 hover:bg-green-50"
+                          aria-label="Save name"
+                        >
+                          <CheckIcon className="h-5 w-5" />
+                        </button>
+                        <button
+                          type="button"
+                          onClick={() => setEditingId(null)}
+                          className="rounded p-1 text-gray-500 hover:bg-gray-100"
+                          aria-label="Cancel rename"
+                        >
+                          <XMarkIcon className="h-5 w-5" />
