+                        <button
+                          type="button"
+                          onClick={() => startRename(pk)}
+                          className="inline-flex items-center gap-1 rounded-md border border-gray-300 px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50"
