+                          <PencilIcon className="h-4 w-4" /> Rename
+                        </button>
+                        <button
+                          type="button"
+                          onClick={() => {
+                            reset();
+                            setConfirmDeleteId(pk.id);
+                          }}
+                          disabled={isLastSignInMethod}
+                          title={isLastSignInMethod ? 'Add another passkey before removing your only one.' : undefined}
+                          className="inline-flex items-center gap-1 rounded-md border border-gray-300 px-3 py-1.5 text-sm font-medium text-red-700 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-50"
+                        >
