+                      </>
+                    )}
+                  </div>
+                )}
+              </li>
+            ))}
+          </ul>
+        )}
+
+        {isLastSignInMethod && passkeys.length === 1 && (
+          <p className="mt-3 text-xs text-gray-500">
+            This is your only way to sign in. Add a passkey on another device before removing it.
+          </p>
+        )}
+        <p className="mt-4 text-xs text-gray-500">
+          Adding or removing a passkey may ask you to confirm it’s you.
+        </p>
+      </section>
+
+      {/* Session */}
+      <section aria-labelledby="session-heading" className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm">
+        <h2 id="session-heading" className="text-lg font-semibold text-gray-900">
+          Session
+        </h2>
+        <div className="mt-4 flex flex-wrap items-center justify-between gap-4">
+          <p className="text-sm text-gray-600">Sign out of The DevTools Times on this device.</p>
+          <button
+            type="button"
+            onClick={handleSignOut}
+            className="rounded-md border border-gray-300 px-3 py-2 text-sm font-medium text-gray-900 hover:bg-gray-50"
+          >
+            Sign out
+          </button>
+        </div>
+      </section>
