+      <ReauthDialog
+        open={reauth !== null}
+        username={user.username}
+        hasPasskeys={passkeys.length > 0}
+        hasPassword={user.hasPassword}
+        reason={reauth?.reason ?? 'continue'}
+        onSuccess={handleReauthSuccess}
+        onCancel={() => setReauth(null)}
+      />
+    </div>
+  );
+}
