@@ -0,0 +1,129 @@
+import React, { useEffect, useRef, useState } from 'react';
+import { describeError, reauthenticateWithPasskey, reauthenticateWithPassword } from '../../lib/auth/client';
+import { Alert, Divider, PasskeyIcon, inputClass, primaryButtonClass, secondaryButtonClass } from './ui';
+
+interface Props {
+  open: boolean;
+  username: string;
+  hasPasskeys: boolean;
+  hasPassword: boolean;
+  /** Short description of what the user is about to do. */
+  reason: string;
+  onSuccess: () => void;
+  onCancel: () => void;
+}
+
+/**
+ * Asks the signed-in user to prove it's still them before a sensitive change,
+ * using one of their passkeys (preferred) or their password.
+ */
+export default function ReauthDialog({ open, username, hasPasskeys, hasPassword, reason, onSuccess, onCancel }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [busy, setBusy] = useState<'passkey' | 'password' | null>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (open && !dialog.open) {
+      setPassword('');
+      setError(null);
+      dialog.showModal();
+    } else if (!open && dialog.open) {
+      dialog.close();
+    }
+  }, [open]);
+
+  const verifyWithPasskey = async () => {
+    setError(null);
+    setBusy('passkey');
+    try {
+      await reauthenticateWithPasskey();
+      onSuccess();
+    } catch (err) {
+      const message = describeError(err);
+      setError(message ?? 'Passkey verification was cancelled.');
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const verifyWithPassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy('password');
+    try {
+      await reauthenticateWithPassword(password);
+      onSuccess();
+    } catch (err) {
+      setError(describeError(err));
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      onCancel={(e) => {
+        e.preventDefault();
+        onCancel();
+      }}
+      aria-labelledby="reauth-title"
+      className="m-auto w-full max-w-sm rounded-lg border border-gray-200 p-0 shadow-xl backdrop:bg-gray-900/50"
+    >
+      <div className="p-6">
+        <h2 id="reauth-title" className="text-lg font-bold text-gray-900">
+          Confirm it’s you
+        </h2>
+        <p className="mt-1 text-sm text-gray-600">
+          To {reason}, please verify your identity as <span className="font-medium text-gray-900">{username}</span>.
+        </p>
+
+        <div className="mt-5">
+          {error && <Alert kind="error">{error}</Alert>}
+
+          {hasPasskeys && (
+            <button type="button" onClick={verifyWithPasskey} disabled={busy !== null} className={secondaryButtonClass}>
+              <PasskeyIcon />
+              {busy === 'passkey' ? 'Waiting for passkey…' : 'Use your passkey'}
+            </button>
+          )}
+
+          {hasPasskeys && hasPassword && <Divider label="or" />}
+
+          {hasPassword && (
+            <form onSubmit={verifyWithPassword} className="space-y-3">
+              {/* Hidden username helps password managers fill the right entry. */}
+              <input type="text" name="username" autoComplete="username" value={username} readOnly hidden />
+              <label htmlFor="reauth-password" className="block text-sm font-medium text-gray-700">
+                Password
+              </label>
+              <input
+                id="reauth-password"
+                type="password"
+                autoComplete="current-password"
+                value={password}
+                onChange={(e) => setPassword(e.target.value)}
+                required
+                className={inputClass}
+              />
+              <button type="submit" disabled={busy !== null} className={primaryButtonClass}>
+                {busy === 'password' ? 'Checking…' : 'Continue'}
+              </button>
+            </form>
+          )}
+
+          <button
+            type="button"
+            onClick={onCancel}
+            className="mt-4 w-full text-center text-sm font-medium text-gray-600 hover:text-gray-900"
+          >
+            Cancel
+          </button>
+        </div>
+      </div>
+    </dialog>
+  );
+}
