+import React from 'react';
+
+export const inputClass =
+  'w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500';
+
+export const primaryButtonClass =
+  'w-full py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75 disabled:cursor-not-allowed';
+
+export const secondaryButtonClass =
+  'w-full inline-flex items-center justify-center gap-2 py-2 px-4 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-900 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75 disabled:cursor-not-allowed';
+
+export function Alert({ kind, children }: { kind: 'error' | 'success' | 'info'; children: React.ReactNode }) {
+  const styles = {
+    error: 'text-red-700 bg-red-100',
+    success: 'text-green-700 bg-green-100',
+    info: 'text-blue-800 bg-blue-50',
+  }[kind];
+  return (
+    <div className={`mb-4 p-3 text-sm rounded-lg ${styles}`} role={kind === 'error' ? 'alert' : 'status'}>
+      {children}
+    </div>
+  );
+}
+
+/** The FIDO Alliance passkey glyph. */
+export function PasskeyIcon({ className = 'w-5 h-5' }: { className?: string }) {
+  return (
+    <svg className={className} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
+      <circle cx="10.5" cy="6" r="4.5" />
+      <path d="M2 18.5c0-3.6 3.4-6 7.5-6 1.2 0 2.3.2 3.3.6a5.5 5.5 0 0 0 .2 8.4H3.5A1.5 1.5 0 0 1 2 20v-1.5Z" />
+      <path
+        fillRule="evenodd"
+        d="M17.5 12a3.5 3.5 0 0 0-1.25 6.77V22l1.25 1.25L19 21.75l-1-1 1-1-.75-.98A3.5 3.5 0 0 0 17.5 12Zm0 1.75a1 1 0 1 0 0 2 1 1 0 0 0 0-2Z"
+        clipRule="evenodd"
+      />
+    </svg>
+  );
+}
+
+export function Divider({ label }: { label: string }) {
+  return (
+    <div className="relative my-6" aria-hidden="true">
+      <div className="absolute inset-0 flex items-center">
+        <div className="w-full border-t border-gray-200" />
+      </div>
+      <div className="relative flex justify-center text-xs uppercase tracking-wide">
+        <span className="bg-white px-2 text-gray-500">{label}</span>
+      </div>
+    </div>
+  );
+}
+
+export function Card({ title, children }: { title: string; children: React.ReactNode }) {
+  return (
+    <div className="max-w-md mx-auto mt-10 p-6 bg-white border border-gray-200 rounded-lg shadow-sm">
+      <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">{title}</h2>
+      {children}
+    </div>
+  );
+}
