+/**
+ * Browser-side helpers for password + passkey authentication.
+ */
+import {
+  WebAuthnError,
+  browserSupportsWebAuthn,
+  browserSupportsWebAuthnAutofill,
+  sendSignal,
+  startAuthentication,
+  startRegistration,
+  WebAuthnAbortService,
+} from '@simplewebauthn/browser';
+import type { AccountSummary, PublicPasskey } from './server';
+
+export type { AccountSummary, PublicPasskey };
+
+const BASE = import.meta.env.BASE_URL.endsWith('/') ? import.meta.env.BASE_URL : `${import.meta.env.BASE_URL}/`;
+
+export const routes = {
+  home: BASE,
+  signIn: `${BASE}signin`,
+  signUp: `${BASE}signup`,
+  account: `${BASE}account`,
+};
+
+export class ApiError extends Error {
+  constructor(message: string, public status: number, public code?: string, public data: Record<string, any> = {}) {
+    super(message);
+  }
+}
+
+export async function api<T = any>(path: string, init: { method?: string; body?: unknown } = {}): Promise<T> {
+  const res = await fetch(`${BASE}api/${path}`, {
+    method: init.method ?? (init.body === undefined ? 'GET' : 'POST'),
+    headers: init.body === undefined ? undefined : { 'Content-Type': 'application/json' },
+    body: init.body === undefined ? undefined : JSON.stringify(init.body),
+    credentials: 'same-origin',
+  });
+  const data = await res.json().catch(() => ({}));
+  if (!res.ok) throw new ApiError(data.error || `Request failed (${res.status})`, res.status, data.code, data);
+  return data as T;
+}
+
+/* ------------------------------------------------------------ capability */
+
+export function passkeysSupported() {
+  return typeof window !== 'undefined' && browserSupportsWebAuthn();
+}
+
+export function autofillSupported() {
+  return browserSupportsWebAuthnAutofill();
+}
+
+/** Whether the browser supports automatic passkey upgrades (conditional create). */
+export async function conditionalCreateSupported(): Promise<boolean> {
+  try {
+    const PKC = (window as any).PublicKeyCredential;
+    if (!PKC?.getClientCapabilities) return false;
+    const caps = await PKC.getClientCapabilities();
+    return Boolean(caps?.conditionalCreate);
+  } catch {
+    return false;
+  }
+}
+
+/** Turns WebAuthn / API failures into a short, user-facing message. Returns null for silent cancellations. */
+export function describeError(err: unknown): string | null {
+  if (err instanceof ApiError) return err.message;
+  if (err instanceof WebAuthnError) {
+    switch (err.code) {
+      case 'ERROR_CEREMONY_ABORTED':
+        return null;
+      case 'ERROR_AUTHENTICATOR_PREVIOUSLY_REGISTERED':
+        return 'This device already has a passkey for your account.';
+      case 'ERROR_INVALID_DOMAIN':
+      case 'ERROR_INVALID_RP_ID':
+        return 'Passkeys aren’t available on this domain.';
+      default:
+        break;
+    }
+  }
+  const name = (err as any)?.name;
+  if (name === 'NotAllowedError' || name === 'AbortError') return null; // user cancelled or timed out
+  if (name === 'InvalidStateError') return 'This device already has a passkey for your account.';
+  return (err as any)?.message || 'Something went wrong. Please try again.';
+}
+
+/* --------------------------------------------------------------- signals */
+
+async function safeSignal(fn: () => Promise<unknown>) {
+  try {
+    await fn();
+  } catch {
+    /* Signal API is best-effort and not supported everywhere. */
+  }
+}
+
+export function signalUnknownCredential(rpID: string, credentialID: string) {
+  return safeSignal(() => sendSignal({ signalName: 'unknownCredential', rpID, credentialID }));
+}
+
+export function signalAccepted(rpID: string, userID: string, ids: string[]) {
+  return safeSignal(() => sendSignal({ signalName: 'allAcceptedCredentials', rpID, userID, allAcceptedCredentialIDs: ids }));
+}
+
+export function signalUserDetails(rpID: string, userID: string, userName: string) {
+  return safeSignal(() => sendSignal({ signalName: 'currentUserDetails', rpID, userID, userName, userDisplayName: userName }));
+}
+
+/* ---------------------------------------------------------- authentication */
+
+interface AuthVerifyResult {
+  account: AccountSummary;
+  signal: { rpID: string; userId: string; username: string; allAcceptedCredentialIds: string[] };
+}
+
+async function runAuthentication(purpose: 'authenticate' | 'reauthenticate', useBrowserAutofill = false) {
+  const optionsJSON = await api('auth/passkey/authenticate/options', { body: { purpose } });
+  const response = await startAuthentication({ optionsJSON, useBrowserAutofill });
+  try {
+    const result = await api<AuthVerifyResult>('auth/passkey/authenticate/verify', { body: { response } });
+    const { rpID, userId, username, allAcceptedCredentialIds } = result.signal;
+    void signalAccepted(rpID, userId, allAcceptedCredentialIds);
+    void signalUserDetails(rpID, userId, username);
+    return result;
+  } catch (err) {
+    if (err instanceof ApiError && err.code === 'UNKNOWN_CREDENTIAL' && err.data.rpID && err.data.credentialId) {
+      void signalUnknownCredential(err.data.rpID, err.data.credentialId);
+    }
+    throw err;
+  }
+}
+
+/** Sign in with a discoverable passkey. Set `autofill` for conditional UI. */
+export function signInWithPasskey({ autofill = false } = {}) {
+  return runAuthentication('authenticate', autofill);
+}
+
+/** Confirm the signed-in user's identity with one of their passkeys. */
+export function reauthenticateWithPasskey() {
+  return runAuthentication('reauthenticate');
+}
+
+export function reauthenticateWithPassword(password: string) {
+  return api('auth/password/reauthenticate', { body: { password } });
+}
+
+export function cancelPendingCeremony() {
+  WebAuthnAbortService.cancelCeremony();
+}
+
+/* ------------------------------------------------------------ registration */
+
+interface RegisterResult {
+  passkey: PublicPasskey;
+  account: AccountSummary;
+}
+
+async function runRegistration(body: Record<string, unknown>, { automatic = false, name }: { automatic?: boolean; name?: string } = {}) {
+  const optionsJSON = await api('auth/passkey/register/options', { body });
+  const response = await startRegistration({ optionsJSON, useAutoRegister: automatic });
+  const result = await api<RegisterResult>('auth/passkey/register/verify', { body: { response, name } });
+  const { rpID, user, passkeys } = result.account;
+  void signalAccepted(rpID, user.id, passkeys.map((p) => p.id));
+  void signalUserDetails(rpID, user.id, user.username);
+  return result;
+}
+
+/** Create a brand-new account that uses a passkey instead of a password. */
+export function signUpWithPasskey(username: string) {
+  return runRegistration({ username });
+}
+
+/** Add a passkey to the signed-in account. */
+export function createPasskey(name?: string) {
+  return runRegistration({}, { name });
+}
+
+/**
+ * Silently offer a passkey right after a password sign-in (conditional create).
+ * Resolves to the new passkey, or null if the browser declined / doesn't support it.
+ */
+export async function tryAutomaticPasskeyUpgrade(): Promise<PublicPasskey | null> {
+  if (!passkeysSupported() || !(await conditionalCreateSupported())) return null;
+  try {
+    const { passkey } = await runRegistration({}, { automatic: true });
+    return passkey;
+  } catch {
+    return null;
+  }
+}
+
+/* -------------------------------------------------------------- management */
+
+export function getAccount() {
+  return api<AccountSummary | { user: null }>('auth/session');
+}
+
+export function renamePasskey(id: string, name: string) {
+  return api<{ passkey: PublicPasskey }>(`auth/passkeys/${encodeURIComponent(id)}`, { method: 'PATCH', body: { name } });
+}
+
+export async function removePasskey(id: string) {
+  const result = await api<{ deletedId: string; account: AccountSummary }>(`auth/passkeys/${encodeURIComponent(id)}`, { method: 'DELETE' });
+  const { rpID, user, passkeys } = result.account;
+  void signalAccepted(rpID, user.id, passkeys.map((p) => p.id));
+  return result;
+}
+
+export function signOut() {
+  return api('auth/session', { method: 'DELETE' });
+}
+
+/** Read a same-site redirect target from `?next=`, falling back to the account page. */
+export function nextUrl(fallback = routes.account) {
+  if (typeof window === 'undefined') return fallback;
+  const next = new URLSearchParams(window.location.search).get('next');
+  if (next && next.startsWith('/') && !next.startsWith('//')) return next;
+  return fallback;
+}
diff --git a/src/lib/auth/server.ts b/src/lib/auth/server.ts
new file mode 100644
index 0000000..1aacfe4
--- /dev/null
+++ b/src/lib/auth/server.ts
@@ -0,0 +1,192 @@
+/**
+ * Shared server-side helpers for authentication: relying-party configuration,
+ * session handling, re-authentication windows and JSON responses.
+ */
+import type { APIContext, AstroGlobal } from 'astro';
+import type { PasskeyRecord, UserRecord } from './store';
+import { findUserById, listPasskeys } from './store';
+import { providerNameForAaguid } from './aaguids';
+
+export const RP_NAME = 'The DevTools Times';
+
+/** How long a sign-in or re-authentication counts as "recent" for sensitive actions. */
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+/** How long a WebAuthn challenge stays valid. */
+export const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+export const EXTERNAL_AUTH_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+export interface AuthSession {
+  userId: string;
+  username: string;
+  method: 'password' | 'passkey';
+  authenticatedAt: number;
+  /** Last time the user proved presence again (passkey or password). */
+  reauthenticatedAt?: number;
+}
+
+export type ChallengePurpose = 'register' | 'signup' | 'authenticate' | 'reauthenticate';
+
+export interface PendingChallenge {
+  challenge: string;
+  purpose: ChallengePurpose;
+  expiresAt: number;
+  /** For registration: the user handle the credential will be bound to. */
+  userId?: string;
+  /** For passkey-first sign-up: the username being claimed. */
+  username?: string;
+}
+
+type Ctx = Pick<APIContext, 'url' | 'session' | 'request'> | AstroGlobal;
+
+/**
+ * The relying party ID and accepted origins. Defaults to the host serving the
+ * request (Astro resolves X-Forwarded-Host for the domains listed in
+ * `security.allowedDomains`). Override with `PASSKEY_RP_ID` and a
+ * comma-separated `PASSKEY_ORIGINS` when running behind another proxy.
+ */
+export function relyingParty(ctx: Pick<APIContext, 'url'>) {
+  const rpID = process.env.PASSKEY_RP_ID || ctx.url.hostname;
+  const origins = process.env.PASSKEY_ORIGINS
+    ? process.env.PASSKEY_ORIGINS.split(',').map((o) => o.trim()).filter(Boolean)
+    : [ctx.url.origin];
+  return { rpID, origins, rpName: RP_NAME };
+}
+
+export function json(body: unknown, init: number | ResponseInit = 200) {
+  const resInit = typeof init === 'number' ? { status: init } : init;
+  return new Response(JSON.stringify(body), {
+    ...resInit,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...(resInit.headers ?? {}) },
+  });
+}
+
+export function errorResponse(status: number, code: string, message: string, extra: Record<string, unknown> = {}) {
+  return json({ error: message, code, ...extra }, status);
+}
+
+export async function readJson<T = any>(request: Request): Promise<T> {
+  try {
+    return (await request.json()) as T;
+  } catch {
+    return {} as T;
+  }
+}
+
+/* --------------------------------------------------------------- session */
+
+export async function getAuth(ctx: Ctx): Promise<AuthSession | null> {
+  const auth = (await ctx.session?.get('auth')) as AuthSession | undefined;
+  return auth ?? null;
+}
+
+/** Returns the signed-in user's record, or null if unauthenticated / stale. */
+export async function getCurrentUser(ctx: Ctx): Promise<{ auth: AuthSession; user: UserRecord } | null> {
+  const auth = await getAuth(ctx);
+  if (!auth) return null;
+  const user = await findUserById(auth.userId);
+  if (!user) return null;
+  return { auth, user };
+}
+
+export async function signIn(ctx: Ctx, user: UserRecord, method: AuthSession['method']) {
+  if (!ctx.session) throw new Error('Sessions are not available.');
+  // Prevent session fixation: issue a fresh session ID on privilege change.
+  await ctx.session.regenerate();
+  const now = Date.now();
+  const auth: AuthSession = {
+    userId: user.id,
+    username: user.username,
+    method,
+    authenticatedAt: now,
+    reauthenticatedAt: now,
+  };
+  ctx.session.set('auth', auth);
+  ctx.session.delete('passkeyChallenge');
+  return auth;
+}
+
+export async function markReauthenticated(ctx: Ctx, auth: AuthSession) {
+  const next = { ...auth, reauthenticatedAt: Date.now() };
+  ctx.session?.set('auth', next);
+  return next;
+}
+
+export function signOut(ctx: Ctx) {
+  ctx.session?.destroy();
+}
+
+export function isRecentlyAuthenticated(auth: AuthSession) {
+  const last = Math.max(auth.authenticatedAt, auth.reauthenticatedAt ?? 0);
+  return Date.now() - last < REAUTH_WINDOW_MS;
+}
+
+export function reauthRequired() {
+  return errorResponse(403, 'REAUTH_REQUIRED', 'Please confirm it’s you to continue.');
+}
+
+export function unauthenticated() {
+  return errorResponse(401, 'UNAUTHENTICATED', 'You need to sign in first.');
+}
+
+/* ------------------------------------------------------------ challenges */
+
+export function saveChallenge(ctx: Ctx, pending: Omit<PendingChallenge, 'expiresAt'>) {
+  ctx.session?.set('passkeyChallenge', { ...pending, expiresAt: Date.now() + CHALLENGE_TTL_MS });
+}
+
+/** Retrieves and consumes the pending challenge (single use). */
+export async function takeChallenge(ctx: Ctx, purposes: ChallengePurpose[]): Promise<PendingChallenge | null> {
+  const pending = (await ctx.session?.get('passkeyChallenge')) as PendingChallenge | undefined;
+  ctx.session?.delete('passkeyChallenge');
+  if (!pending || !purposes.includes(pending.purpose) || pending.expiresAt < Date.now()) return null;
+  return pending;
+}
+
+/* ------------------------------------------------------------ serialisers */
+
+export function publicPasskey(pk: PasskeyRecord) {
+  return {
+    id: pk.id,
+    name: pk.name,
+    provider: providerNameForAaguid(pk.aaguid),
+    createdAt: pk.createdAt,
+    lastUsedAt: pk.lastUsedAt,
+    synced: pk.backedUp,
+    deviceType: pk.deviceType,
+    transports: pk.transports,
+  };
+}
+
+export type PublicPasskey = ReturnType<typeof publicPasskey>;
+
+export async function accountSummary(ctx: Pick<APIContext, 'url'>, auth: AuthSession, user: UserRecord) {
+  const passkeys = await listPasskeys(user.id);
+  return {
+    user: {
+      id: user.id,
+      username: user.username,
+      hasPassword: user.hasPassword,
+      createdAt: user.createdAt,
+    },
+    session: {
+      method: auth.method,
+      authenticatedAt: auth.authenticatedAt,
+      recentlyAuthenticated: isRecentlyAuthenticated(auth),
+    },
+    rpID: relyingParty(ctx).rpID,
+    passkeys: passkeys.map(publicPasskey),
+  };
+}
+
+export type AccountSummary = Awaited<ReturnType<typeof accountSummary>>;
+
+/** Username rules shared by passkey-first sign-up. */
+export function validateUsername(raw: unknown): string | null {
+  if (typeof raw !== 'string') return 'Username is required.';
+  const username = raw.trim();
+  if (username.length < 3) return 'Username must be at least 3 characters.';
+  if (username.length > 64) return 'Username must be at most 64 characters.';
+  if (!/^[\w.@+-]+$/.test(username)) return 'Username may only contain letters, numbers and . _ @ + -';
+  return null;
+}
diff --git a/src/lib/auth/store.ts b/src/lib/auth/store.ts
new file mode 100644
index 0000000..097ec9e
--- /dev/null
+++ b/src/lib/auth/store.ts
@@ -0,0 +1,181 @@
+/**
+ * Minimal persistent store for local user records and their passkeys.
+ *
+ * Password verification is delegated to the external Times API, but passkeys
+ * are a first-party feature of this app, so we keep the WebAuthn credential
+ * data (public keys, counters, metadata) on our own server. Data is written to
+ * a JSON file so it survives restarts; the location can be overridden with the
+ * `PASSKEY_DB_PATH` environment variable.
+ */
+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+
+export interface UserRecord {
+  /** Opaque, random WebAuthn user handle (base64url). Never the username. */
+  id: string;
+  username: string;
+  /** Whether the user can also sign in with a password via the Times API. */
+  hasPassword: boolean;
+  createdAt: string;
+}
+
+export interface PasskeyRecord {
+  /** Credential ID (base64url). */
+  id: string;
+  userId: string;
+  /** COSE public key (base64url). */
+  publicKey: string;
+  counter: number;
+  transports: string[];
+  deviceType: 'singleDevice' | 'multiDevice';
+  backedUp: boolean;
+  aaguid: string;
+  /** User-editable label. */
+  name: string;
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+interface Database {
+  users: UserRecord[];
+  passkeys: PasskeyRecord[];
+}
+
+const DB_PATH = process.env.PASSKEY_DB_PATH ?? path.join(process.cwd(), '.data', 'passkeys.json');
+
+let cache: Database | null = null;
+// Serialise all writes so concurrent requests can't clobber each other.
+let queue: Promise<unknown> = Promise.resolve();
+
+async function load(): Promise<Database> {
+  if (cache) return cache;
+  try {
+    const raw = await fs.readFile(DB_PATH, 'utf8');
+    const parsed = JSON.parse(raw) as Partial<Database>;
+    cache = { users: parsed.users ?? [], passkeys: parsed.passkeys ?? [] };
+  } catch (err: any) {
+    if (err?.code !== 'ENOENT') console.error('[passkeys] Failed to read store, starting empty:', err);
+    cache = { users: [], passkeys: [] };
+  }
+  return cache;
+}
+
+async function persist(db: Database) {
+  await fs.mkdir(path.dirname(DB_PATH), { recursive: true });
+  const tmp = `${DB_PATH}.${process.pid}.tmp`;
+  await fs.writeFile(tmp, JSON.stringify(db, null, 2), 'utf8');
+  await fs.rename(tmp, DB_PATH);
+}
+
+function mutate<T>(fn: (db: Database) => T): Promise<T> {
+  const run = queue.then(async () => {
+    const db = await load();
+    const result = fn(db);
+    await persist(db);
+    return result;
+  });
+  queue = run.catch(() => undefined);
+  return run;
+}
+
+const normalise = (username: string) => username.trim().toLowerCase();
+
+export function newUserHandle(): string {
+  return randomBytes(32).toString('base64url');
+}
+
+/* ----------------------------------------------------------------- users */
+
+export async function findUserById(id: string) {
+  const db = await load();
+  return db.users.find((u) => u.id === id) ?? null;
+}
+
+export async function findUserByUsername(username: string) {
+  const db = await load();
+  const key = normalise(username);
+  return db.users.find((u) => normalise(u.username) === key) ?? null;
+}
+
+export function createUser(input: { id?: string; username: string; hasPassword: boolean }) {
+  return mutate((db) => {
+    const key = normalise(input.username);
+    const existing = db.users.find((u) => normalise(u.username) === key);
+    if (existing) {
+      // Never merge a password identity into a passkey-only account (or vice
+      // versa): the external API's user with the same name may be someone else.
+      if (existing.hasPassword !== input.hasPassword) throw new UsernameConflictError();
+      return existing;
+    }
+    const user: UserRecord = {
+      id: input.id ?? newUserHandle(),
+      username: input.username.trim(),
+      hasPassword: input.hasPassword,
+      createdAt: new Date().toISOString(),
+    };
+    db.users.push(user);
+    return user;
+  });
+}
+
+export class UsernameConflictError extends Error {
+  constructor() {
+    super('This username belongs to a passkey account. Sign in with your passkey instead.');
+  }
+}
+
+/**
+ * Look up (or lazily create) the local record for a password-authenticated
+ * user. Throws `UsernameConflictError` if the name is held by a passkey-only
+ * account.
+ */
+export async function ensurePasswordUser(username: string) {
+  const existing = await findUserByUsername(username);
+  if (existing) {
+    if (!existing.hasPassword) throw new UsernameConflictError();
+    return existing;
+  }
+  return createUser({ username, hasPassword: true });
+}
+
+/* -------------------------------------------------------------- passkeys */
+
+export async function listPasskeys(userId: string) {
+  const db = await load();
+  return db.passkeys
+    .filter((p) => p.userId === userId)
+    .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
+}
+
+export async function findPasskey(id: string) {
+  const db = await load();
+  return db.passkeys.find((p) => p.id === id) ?? null;
+}
+
+export function addPasskey(passkey: PasskeyRecord) {
+  return mutate((db) => {
+    if (db.passkeys.some((p) => p.id === passkey.id)) {
+      throw new Error('This passkey is already registered.');
+    }
+    db.passkeys.push(passkey);
+    return passkey;
+  });
+}
+
+export function updatePasskey(id: string, userId: string, patch: Partial<Pick<PasskeyRecord, 'name' | 'counter' | 'lastUsedAt' | 'backedUp' | 'deviceType'>>) {
+  return mutate((db) => {
+    const pk = db.passkeys.find((p) => p.id === id && p.userId === userId);
+    if (!pk) return null;
+    Object.assign(pk, patch);
+    return pk;
+  });
+}
+
+export function deletePasskey(id: string, userId: string) {
+  return mutate((db) => {
+    const before = db.passkeys.length;
+    db.passkeys = db.passkeys.filter((p) => !(p.id === id && p.userId === userId));
+    return db.passkeys.length !== before;
+  });
+}
