+---
+import Layout from '../layouts/Layout.astro';
+import AccountSettings from '../components/auth/AccountSettings';
+import { accountSummary, getCurrentUser } from '../lib/auth/server';
+
+const current = await getCurrentUser(Astro);
+if (!current) {
+  const next = encodeURIComponent(`${import.meta.env.BASE_URL.replace(/\/?$/, '/')}account`);
+  return Astro.redirect(`${import.meta.env.BASE_URL.replace(/\/?$/, '/')}signin?next=${next}`);
