+Astro.response.headers.set('Cache-Control', 'no-store');
+const summary = await accountSummary(Astro, current.auth, current.user);
+---
+
+<Layout title="Account settings | The DevTools Times">
+  <div class="py-12 px-4 sm:px-6 lg:px-8">
+    <AccountSettings client:load initial={summary} />
+  </div>
+</Layout>
diff --git a/src/pages/api/auth/passkey/authenticate/options.ts b/src/pages/api/auth/passkey/authenticate/options.ts
new file mode 100644
index 0000000..1742974
--- /dev/null
+++ b/src/pages/api/auth/passkey/authenticate/options.ts
@@ -0,0 +1,44 @@
+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import {
+  errorResponse,
+  getCurrentUser,
+  json,
+  readJson,
+  relyingParty,
+  saveChallenge,
+  unauthenticated,
+} from '../../../../../lib/auth/server';
+import { listPasskeys } from '../../../../../lib/auth/store';
+
+/**
+ * Creates WebAuthn authentication options.
+ *
+ * - `purpose: "authenticate"` (default): discoverable-credential sign-in, used
+ *   both for the explicit button and for passkey autofill (conditional UI).
+ * - `purpose: "reauthenticate"`: the signed-in user confirms their identity
+ *   with one of *their* passkeys before a sensitive action.
+ */
+export const POST: APIRoute = async (ctx) => {
+  const { rpID } = relyingParty(ctx);
+  const { purpose = 'authenticate' } = await readJson<{ purpose?: 'authenticate' | 'reauthenticate' }>(ctx.request);
+
+  if (purpose === 'reauthenticate') {
+    const current = await getCurrentUser(ctx);
+    if (!current) return unauthenticated();
+    const passkeys = await listPasskeys(current.user.id);
+    if (passkeys.length === 0) return errorResponse(400, 'NO_PASSKEYS', 'This account has no passkeys yet.');
+
+    const options = await generateAuthenticationOptions({
+      rpID,
+      allowCredentials: passkeys.map((pk) => ({ id: pk.id, transports: pk.transports })),
+      userVerification: 'required',
+    });
+    saveChallenge(ctx, { challenge: options.challenge, purpose: 'reauthenticate', userId: current.user.id });
+    return json(options);
+  }
+
+  const options = await generateAuthenticationOptions({ rpID, userVerification: 'preferred' });
+  saveChallenge(ctx, { challenge: options.challenge, purpose: 'authenticate' });
+  return json(options);
+};
diff --git a/src/pages/api/auth/passkey/authenticate/verify.ts b/src/pages/api/auth/passkey/authenticate/verify.ts
new file mode 100644
index 0000000..be64aef
--- /dev/null
+++ b/src/pages/api/auth/passkey/authenticate/verify.ts
@@ -0,0 +1,95 @@
+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse } from '@simplewebauthn/server';
+import type { AuthenticationResponseJSON } from '@simplewebauthn/server';
+import {
+  accountSummary,
+  errorResponse,
+  getCurrentUser,
+  json,
+  markReauthenticated,
+  readJson,
+  relyingParty,
+  signIn,
+  takeChallenge,
+} from '../../../../../lib/auth/server';
+import { findPasskey, findUserById, listPasskeys, updatePasskey } from '../../../../../lib/auth/store';
+
+export const POST: APIRoute = async (ctx) => {
+  const { rpID, origins } = relyingParty(ctx);
+  const body = await readJson<{ response?: AuthenticationResponseJSON }>(ctx.request);
+  const response = body.response;
+  if (!response?.id) return errorResponse(400, 'INVALID_INPUT', 'Missing authentication response.');
+
+  const pending = await takeChallenge(ctx, ['authenticate', 'reauthenticate']);
+  if (!pending) return errorResponse(400, 'CHALLENGE_EXPIRED', 'The passkey request expired. Please try again.');
+
+  const passkey = await findPasskey(response.id);
+  if (!passkey) {
+    // Let the client tell the passkey provider this credential is gone
+    // (PublicKeyCredential.signalUnknownCredential).
+    return errorResponse(404, 'UNKNOWN_CREDENTIAL', 'This passkey isn’t registered with The DevTools Times. It may have been removed.', {
+      credentialId: response.id,
+      rpID,
+    });
+  }
+
+  const user = await findUserById(passkey.userId);
+  if (!user) return errorResponse(404, 'UNKNOWN_CREDENTIAL', 'This passkey’s account no longer exists.', { credentialId: response.id, rpID });
+
+  const userHandle = response.response.userHandle;
+  if (userHandle && userHandle !== user.id) {
+    return errorResponse(400, 'VERIFICATION_FAILED', 'Passkey does not match this account.');
+  }
+
+  let current = null;
+  if (pending.purpose === 'reauthenticate') {
+    current = await getCurrentUser(ctx);
+    if (!current || current.user.id !== user.id || pending.userId !== user.id) {
+      return errorResponse(403, 'WRONG_ACCOUNT', 'Please use a passkey for the account you’re signed in to.');
+    }
+  }
+
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      credential: {
+        id: passkey.id,
+        publicKey: new Uint8Array(Buffer.from(passkey.publicKey, 'base64url')),
+        counter: passkey.counter,
+        transports: passkey.transports,
+      },
+      requireUserVerification: pending.purpose === 'reauthenticate',
+    });
+  } catch (err: any) {
+    return errorResponse(400, 'VERIFICATION_FAILED', err?.message || 'Could not verify the passkey.');
+  }
+  if (!verification.verified) return errorResponse(400, 'VERIFICATION_FAILED', 'Could not verify the passkey.');
+
+  const { newCounter, credentialBackedUp, credentialDeviceType } = verification.authenticationInfo;
+  await updatePasskey(passkey.id, user.id, {
+    counter: newCounter,
+    backedUp: credentialBackedUp,
+    deviceType: credentialDeviceType,
+    lastUsedAt: new Date().toISOString(),
+  });
+
+  const auth = pending.purpose === 'reauthenticate'
+    ? await markReauthenticated(ctx, current!.auth)
+    : await signIn(ctx, user, 'passkey');
+
+  const passkeys = await listPasskeys(user.id);
+  return json({
+    account: await accountSummary(ctx, auth, user),
+    // Data for the WebAuthn Signal API so providers can stay in sync.
+    signal: {
+      rpID,
+      userId: user.id,
+      username: user.username,
+      allAcceptedCredentialIds: passkeys.map((pk) => pk.id),
+    },
+  });
+};
