@@ -0,0 +1,68 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import {
+  errorResponse,
+  getCurrentUser,
+  isRecentlyAuthenticated,
+  json,
+  reauthRequired,
+  readJson,
+  relyingParty,
+  saveChallenge,
+  validateUsername,
+} from '../../../../../lib/auth/server';
+import { findUserByUsername, listPasskeys, newUserHandle } from '../../../../../lib/auth/store';
+
+/**
+ * Creates WebAuthn registration options.
+ *
+ * - Signed in: adds a passkey to the current account (requires a recent sign-in
+ *   or re-authentication).
+ * - Signed out with `{ username }`: passkey-first sign-up for a new account.
+ */
+export const POST: APIRoute = async (ctx) => {
+  const { rpID, rpName } = relyingParty(ctx);
+  const body = await readJson<{ username?: string }>(ctx.request);
+  const current = await getCurrentUser(ctx);
+
+  let userId: string;
+  let username: string;
+  let excludeCredentials: { id: string; transports?: string[] }[] = [];
+  let purpose: 'register' | 'signup';
+
+  if (current) {
+    if (!isRecentlyAuthenticated(current.auth)) return reauthRequired();
+    purpose = 'register';
+    userId = current.user.id;
+    username = current.user.username;
+    excludeCredentials = (await listPasskeys(userId)).map((pk) => ({ id: pk.id, transports: pk.transports }));
+  } else {
+    const invalid = validateUsername(body.username);
+    if (invalid) return errorResponse(400, 'INVALID_USERNAME', invalid);
+    username = body.username!.trim();
+    if (await findUserByUsername(username)) {
+      return errorResponse(409, 'USERNAME_TAKEN', 'That username is already taken. Sign in instead, or choose another one.');
+    }
+    purpose = 'signup';
+    userId = newUserHandle();
+  }
+
+  const options = await generateRegistrationOptions({
+    rpName,
+    rpID,
+    userName: username,
+    userDisplayName: username,
+    userID: new Uint8Array(Buffer.from(userId, 'base64url')),
+    attestationType: 'none',
+    excludeCredentials,
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+    },
+    extensions: { credProps: true } as any,
+  });
+
+  saveChallenge(ctx, { challenge: options.challenge, purpose, userId, username });
+  return json(options);
+};
diff --git a/src/pages/api/auth/passkey/register/verify.ts b/src/pages/api/auth/passkey/register/verify.ts
new file mode 100644
index 0000000..4419626
--- /dev/null
+++ b/src/pages/api/auth/passkey/register/verify.ts
@@ -0,0 +1,90 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import type { RegistrationResponseJSON } from '@simplewebauthn/server';
+import {
+  accountSummary,
+  errorResponse,
+  getCurrentUser,
+  json,
+  publicPasskey,
+  readJson,
+  relyingParty,
+  signIn,
+  takeChallenge,
+} from '../../../../../lib/auth/server';
+import { addPasskey, createUser, findUserById, findUserByUsername } from '../../../../../lib/auth/store';
+import type { PasskeyRecord } from '../../../../../lib/auth/store';
+import { providerNameForAaguid } from '../../../../../lib/auth/aaguids';
+
+export const POST: APIRoute = async (ctx) => {
+  const { rpID, origins } = relyingParty(ctx);
+  const body = await readJson<{ response?: RegistrationResponseJSON; name?: string }>(ctx.request);
+  if (!body.response) return errorResponse(400, 'INVALID_INPUT', 'Missing registration response.');
+
+  const pending = await takeChallenge(ctx, ['register', 'signup']);
+  if (!pending?.userId || !pending.username) {
+    return errorResponse(400, 'CHALLENGE_EXPIRED', 'The passkey request expired. Please try again.');
+  }
+
+  const current = await getCurrentUser(ctx);
+  if (pending.purpose === 'register' && current?.user.id !== pending.userId) {
+    return errorResponse(403, 'SESSION_CHANGED', 'Your session changed. Please try again.');
+  }
+
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response: body.response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      // UV is "preferred": automatic passkey upgrades (conditional create)
+      // don't perform user verification, and the user is already signed in.
+      requireUserVerification: false,
+    });
+  } catch (err: any) {
+    return errorResponse(400, 'VERIFICATION_FAILED', err?.message || 'Could not verify the passkey.');
+  }
+  if (!verification.verified) return errorResponse(400, 'VERIFICATION_FAILED', 'Could not verify the passkey.');
+
+  const info = verification.registrationInfo;
+
+  let user;
+  if (pending.purpose === 'signup') {
+    if (await findUserByUsername(pending.username)) {
+      return errorResponse(409, 'USERNAME_TAKEN', 'That username was just taken. Please choose another one.');
+    }
+    user = await createUser({ id: pending.userId, username: pending.username, hasPassword: false });
+  } else {
+    user = await findUserById(pending.userId);
+    if (!user) return errorResponse(404, 'UNKNOWN_USER', 'Account not found.');
+  }
+
+  const transports = info.credential.transports ?? body.response.response.transports ?? [];
+  const isSecurityKey = transports.some((t) => t === 'usb' || t === 'nfc') && !transports.includes('internal');
+  const fallbackName = providerNameForAaguid(info.aaguid) ?? (isSecurityKey ? 'Security key' : 'Passkey');
+  const requestedName = typeof body.name === 'string' ? body.name.trim().slice(0, 64) : '';
+
+  const record: PasskeyRecord = {
+    id: info.credential.id,
+    userId: user.id,
+    publicKey: Buffer.from(info.credential.publicKey).toString('base64url'),
+    counter: info.credential.counter,
+    transports,
+    deviceType: info.credentialDeviceType,
+    backedUp: info.credentialBackedUp,
+    aaguid: info.aaguid,
+    name: requestedName || fallbackName,
+    createdAt: new Date().toISOString(),
+    lastUsedAt: null,
+  };
+
+  try {
+    await addPasskey(record);
+  } catch (err: any) {
+    return errorResponse(409, 'DUPLICATE_PASSKEY', err?.message || 'This passkey is already registered.');
+  }
+
+  const auth = pending.purpose === 'signup' ? await signIn(ctx, user, 'passkey') : current!.auth;
+  return json({ passkey: publicPasskey(record), account: await accountSummary(ctx, auth, user) });
+};
diff --git a/src/pages/api/auth/passkeys/[id].ts b/src/pages/api/auth/passkeys/[id].ts
new file mode 100644
