@@ -0,0 +1,48 @@
+import type { APIRoute } from 'astro';
+import {
+  accountSummary,
+  errorResponse,
+  getCurrentUser,
+  isRecentlyAuthenticated,
+  json,
+  publicPasskey,
+  reauthRequired,
+  readJson,
+  unauthenticated,
+} from '../../../../lib/auth/server';
+import { deletePasskey, findPasskey, listPasskeys, updatePasskey } from '../../../../lib/auth/store';
+
+/** Rename a passkey. */
+export const PATCH: APIRoute = async (ctx) => {
+  const current = await getCurrentUser(ctx);
+  if (!current) return unauthenticated();
+
+  const { name } = await readJson<{ name?: string }>(ctx.request);
+  const trimmed = typeof name === 'string' ? name.trim() : '';
+  if (!trimmed) return errorResponse(400, 'INVALID_INPUT', 'Name cannot be empty.');
+  if (trimmed.length > 64) return errorResponse(400, 'INVALID_INPUT', 'Name must be at most 64 characters.');
+
+  const updated = await updatePasskey(ctx.params.id!, current.user.id, { name: trimmed });
+  if (!updated) return errorResponse(404, 'NOT_FOUND', 'Passkey not found.');
+  return json({ passkey: publicPasskey(updated) });
+};
+
+/** Delete a passkey. Sensitive: requires a recent sign-in or re-authentication. */
+export const DELETE: APIRoute = async (ctx) => {
+  const current = await getCurrentUser(ctx);
+  if (!current) return unauthenticated();
+
+  const id = ctx.params.id!;
+  const passkey = await findPasskey(id);
+  if (!passkey || passkey.userId !== current.user.id) return errorResponse(404, 'NOT_FOUND', 'Passkey not found.');
+
+  if (!isRecentlyAuthenticated(current.auth)) return reauthRequired();
+
+  const passkeys = await listPasskeys(current.user.id);
+  if (!current.user.hasPassword && passkeys.length <= 1) {
+    return errorResponse(400, 'LAST_CREDENTIAL', 'You can’t remove your only passkey because your account has no password. Add another passkey first.');
+  }
+
+  await deletePasskey(id, current.user.id);
+  return json({ deletedId: id, account: await accountSummary(ctx, current.auth, current.user) });
+};
