@@ -0,0 +1,20 @@
+import { EXTERNAL_AUTH_API } from '../../../../lib/auth/server';
+
+/**
+ * Forwards a credential check to the external Times auth API. Password
+ * verification stays with that service; this app only mirrors the result into
+ * its own session so passkeys can be attached to the account.
+ */
+export async function callExternalAuth(endpoint: 'login' | 'register', username: string, password: string) {
+  try {
+    const response = await fetch(`${EXTERNAL_AUTH_API}/${endpoint}`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+    const data = await response.json().catch(() => ({}));
+    return { ok: response.ok, status: response.status, data: data as Record<string, any> };
+  } catch {
+    return { ok: false, status: 502, data: { error: 'The sign-in service is unreachable. Please try again later.' } };
+  }
+}
