+import type { APIRoute } from 'astro';
+import { errorResponse, getCurrentUser, json, markReauthenticated, readJson, unauthenticated } from '../../../../lib/auth/server';
+import { callExternalAuth } from './_external';
+
+/** Confirm the signed-in user's identity again with their password. */
+export const POST: APIRoute = async (ctx) => {
+  const current = await getCurrentUser(ctx);
+  if (!current) return unauthenticated();
+  if (!current.user.hasPassword) {
+    return errorResponse(400, 'NO_PASSWORD', 'This account has no password. Use a passkey instead.');
+  }
+  const { password } = await readJson<{ password?: string }>(ctx.request);
+  if (!password) return errorResponse(400, 'INVALID_INPUT', 'Password is required.');
+
+  const result = await callExternalAuth('login', current.user.username, password);
+  if (!result.ok) {
+    return errorResponse(401, 'REAUTH_FAILED', `Password check failed: ${result.data.error || 'Unknown error'}`);
+  }
+  await markReauthenticated(ctx, current.auth);
+  return json({ ok: true });
+};
