+import type { APIRoute } from 'astro';
+import { errorResponse, json, readJson, signIn } from '../../../../lib/auth/server';
+import { UsernameConflictError, ensurePasswordUser, findUserByUsername } from '../../../../lib/auth/store';
+import { callExternalAuth } from './_external';
+
+export const POST: APIRoute = async (ctx) => {
+  const { username, password } = await readJson<{ username?: string; password?: string }>(ctx.request);
+  if (!username || !password) return errorResponse(400, 'INVALID_INPUT', 'Username and password are required.');
+
+  const existing = await findUserByUsername(username);
+  if (existing && !existing.hasPassword) {
+    return errorResponse(409, 'USERNAME_TAKEN', new UsernameConflictError().message);
+  }
+
+  const result = await callExternalAuth('register', username, password);
+  if (!result.ok) return json(result.data, result.status);
+
+  // Sign the new user straight in so we can offer to create a passkey.
+  let user;
+  try {
+    user = await ensurePasswordUser(username);
+  } catch (err) {
+    if (err instanceof UsernameConflictError) return errorResponse(409, 'USERNAME_TAKEN', err.message);
+    throw err;
+  }
+  await signIn(ctx, user, 'password');
+  return json({ ...result.data, username: user.username });
+};
