--- /dev/null
+++ b/components/drink-card.js
@@ -0,0 +1,120 @@
+// <drink-card> — server-rendered via Declarative Shadow DOM, hydrated in place.
+//
+// The HTML already contains each card's shadow root (styles + markup), so the
+// browser paints the finished card before this script runs. On upgrade we
+// reuse that existing shadow root and only attach behaviour; nothing is
+// re-rendered.
+
+const STORAGE_KEY = 'daily-grind:favorite-drinks';
+
+// Polyfill for browsers without native Declarative Shadow DOM support.
+if (!HTMLTemplateElement.prototype.hasOwnProperty('shadowRootMode')) {
+  document.querySelectorAll('template[shadowrootmode]').forEach((template) => {
+    const host = template.parentNode;
+    if (!host || host.shadowRoot) return;
+    const root = host.attachShadow({ mode: template.getAttribute('shadowrootmode') });
+    root.appendChild(template.content);
+    template.remove();
+  });
+}
+
+const readFavorites = () => {
+  try {
+    return new Set(JSON.parse(localStorage.getItem(STORAGE_KEY)) || []);
+  } catch {
+    return new Set();
+  }
+};
+
+const writeFavorites = (favorites) => {
+  try {
+    localStorage.setItem(STORAGE_KEY, JSON.stringify([...favorites]));
+  } catch {
+    /* storage unavailable (private mode, quota) — state stays in-memory */
+  }
+};
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['favorite'];
+
+  #internals = this.attachInternals();
+  #button = null;
+
+  connectedCallback() {
+    // A declarative shadow root is exposed through ElementInternals before
+    // (and regardless of) attachShadow. Only build one if the element was
+    // created client-side without server markup.
+    const root = this.#internals.shadowRoot ?? this.#renderClientSide();
+
+    this.#button = root.querySelector('.fav');
+    if (!this.#button) return;
+    this.#button.addEventListener('click', this.#onToggle);
+
+    // Restore persisted state by flipping attributes only.
+    if (readFavorites().has(this.drinkId)) this.favorite = true;
+    else this.#sync();
+  }
+
+  disconnectedCallback() {
+    this.#button?.removeEventListener('click', this.#onToggle);
+  }
+
+  attributeChangedCallback() {
+    this.#sync();
+  }
+
+  get drinkId() {
+    return this.getAttribute('drink-id') || '';
+  }
+
+  get favorite() {
+    return this.hasAttribute('favorite');
+  }
+
+  set favorite(value) {
+    this.toggleAttribute('favorite', Boolean(value));
+  }
+
+  #onToggle = () => {
+    this.favorite = !this.favorite;
+
+    const favorites = readFavorites();
+    if (this.favorite) favorites.add(this.drinkId);
+    else favorites.delete(this.drinkId);
+    writeFavorites(favorites);
+
+    this.dispatchEvent(
+      new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { drinkId: this.drinkId, favorite: this.favorite },
+      }),
+    );
+  };
+
+  #sync() {
+    if (!this.#button) return;
+    const on = this.favorite;
+    const name = this.querySelector('[slot="name"]')?.textContent.trim() || 'drink';
+    this.#button.setAttribute('aria-pressed', String(on));
+    this.#button.setAttribute('aria-label', `${on ? 'Remove' : 'Add'} ${name} ${on ? 'from' : 'to'} favorites`);
+    this.#button.title = on ? 'Remove from favorites' : 'Add to favorites';
+    if (on) this.#internals.states?.add('favorite');
+    else this.#internals.states?.delete('favorite');
+  }
+
+  // Fallback for cards created with document.createElement('drink-card'):
+  // clone the shadow markup from an existing server-rendered card.
+  #renderClientSide() {
+    const root = this.attachShadow({ mode: 'open' });
+    const source = document.querySelector('drink-card')?.shadowRoot;
+    if (source && source !== root) {
+      root.innerHTML = source.innerHTML;
+      const link = root.querySelector('.details');
+      if (link && this.hasAttribute('href')) link.href = this.getAttribute('href');
+    }
+    return root;
+  }
+}
+
+customElements.define('drink-card', DrinkCard);
