+# Security & privacy response headers for The Daily Grind.
+# Format: Netlify / Cloudflare Pages "_headers". Port the same values to
+# nginx/Express/CDN config if you host elsewhere. The CSP must stay in sync
+# with the <meta http-equiv="Content-Security-Policy"> in index.html; the
+# header is authoritative and also carries frame-ancestors and report-to,
+# which can't be set from a meta tag.
+
+/*
+  Strict-Transport-Security: max-age=31536000; includeSubDomains
+  Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; manifest-src 'self'; form-action 'self'; base-uri 'none'; object-src 'none'; frame-ancestors 'none'; require-trusted-types-for 'script'; trusted-types 'none'; upgrade-insecure-requests; report-to csp
+  Reporting-Endpoints: csp="/api/security-reports", default="/api/security-reports"
+  Connection-Allowlist-Report-Only: (response-origin "https://globalprivacycontrol.org"); report-to=csp
+  Referrer-Policy: same-origin
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), autoplay=(), bluetooth=(), browsing-topics=(), camera=(), display-capture=(), encrypted-media=(), gamepad=(), geolocation=(), gyroscope=(), hid=(), identity-credentials-get=(), idle-detection=(), local-fonts=(), magnetometer=(), microphone=(), midi=(), payment=(), publickey-credentials-get=(self), screen-wake-lock=(), serial=(), usb=(), xr-spatial-tracking=()
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin-allow-popups
+  Cross-Origin-Resource-Policy: same-origin
+  X-DNS-Prefetch-Control: off
+  X-Permitted-Cross-Domain-Policies: none
+
+# HTML can show signed-in state, so shared caches must never store it.
+/
+  Cache-Control: private, no-cache
+/index.html
+  Cache-Control: private, no-cache
+
+# Static assets have no personal data and can be cached publicly.
+/css/*
+  Cache-Control: public, max-age=3600
+/js/*
+  Cache-Control: public, max-age=3600
+/assets/*
+  Cache-Control: public, max-age=86400
+
+/.well-known/gpc.json
+  Content-Type: application/json
+  Access-Control-Allow-Origin: *
+  Cross-Origin-Resource-Policy: cross-origin
+
+# Logout is handled by the application server. It must:
+#   - accept POST only (405 for GET), and validate a CSRF token and/or
+#     reject requests where Sec-Fetch-Site is "cross-site"
+#   - invalidate the session server-side
+#   - respond with:
+#       Clear-Site-Data: "cookies", "storage", "cache"
+#       Cache-Control: no-store
+#
+# Session cookies (set by the app server) must use:
+#   Set-Cookie: __Host-session=<opaque id>; Path=/; Secure; HttpOnly; SameSite=Lax
