@@ -0,0 +1,217 @@
+/**
+ * The Daily Grind: client-side privacy safeguards.
+ *
+ * Rules this file follows:
+ *  - It sends nothing over the network. CSP has connect-src 'none', so
+ *    fetch/XHR/sendBeacon are blocked anyway.
+ *  - It reads or writes no cookies and never stores PII or tokens in Web
+ *    Storage.
+ *  - It never writes untrusted strings to HTML sinks. It only uses
+ *    textContent, which is compatible with `trusted-types 'none'`.
+ *  - It does no fingerprinting or UA sniffing. Only feature detection.
+ */
+(() => {
+  'use strict';
+
+  /* ------------------------------------------------------------------ *
+   * 1. Data minimization: scrub sensitive query parameters from the URL.
+   *
+   * Marketing links, password-reset emails and misconfigured forms often
+   * put emails, tokens or click IDs in the query string. Left alone, they
+   * sit in browser history, get bookmarked or shared, and can leak
+   * through the Referer header. Strip them from the visible URL straight
+   * away. The server has already received the request, so nothing
+   * functional depends on them staying in the address bar.
+   * ------------------------------------------------------------------ */
+  const SENSITIVE_PARAMS = [
+    // Personal data
+    /^e?-?mail$/i, /^email[_-]?address$/i, /^phone$/i, /^name$/i,
+    /^(first|last)[_-]?name$/i, /^address$/i, /^zip$/i, /^postcode$/i,
+    // Credentials and session material
+    /token/i, /^code$/i, /^auth/i, /^session/i, /^sid$/i, /^key$/i,
+    /^password$/i, /^otp$/i,
+    // Cross-site tracking identifiers
+    /^utm_/i, /^fbclid$/i, /^gclid$/i, /^gbraid$/i, /^wbraid$/i,
+    /^msclkid$/i, /^dclid$/i, /^mc_eid$/i, /^_hsenc$/i, /^_hsmi$/i,
+    /^igshid$/i, /^yclid$/i, /^twclid$/i, /^ttclid$/i, /^li_fat_id$/i,
+  ];
+
+  const scrubUrl = () => {
+    const url = new URL(window.location.href);
+    let changed = false;
+    for (const key of [...url.searchParams.keys()]) {
+      if (SENSITIVE_PARAMS.some((re) => re.test(key))) {
+        url.searchParams.delete(key);
+        changed = true;
+      }
+    }
+    if (changed) {
+      window.history.replaceState(window.history.state, '', url);
+    }
+  };
+
+  /* ------------------------------------------------------------------ *
+   * 2. Respect user privacy signals (Global Privacy Control).
+   *
+   * GPC is a legally recognized opt-out under CCPA/CPRA and several other
+   * US state laws. This site has no sale/share trackers, but showing
+   * that the signal was received makes our behavior transparent. Any
+   * future optional integration MUST call `DailyGrindPrivacy.allows()`
+   * before loading.
+   * ------------------------------------------------------------------ */
+  const gpcEnabled = navigator.globalPrivacyControl === true;
+
+  const showPrivacySignal = () => {
+    if (!gpcEnabled) return;
+    const status = document.getElementById('privacy-signal');
+    if (status) {
+      status.textContent =
+        'Global Privacy Control detected: we will not sell or share your personal information.';
+      status.hidden = false;
+    }
+    const dialogNote = document.getElementById('privacy-info-gpc');
+    if (dialogNote) {
+      const strong = document.createElement('strong');
+      strong.textContent = ' Your browser is sending this signal now, and we are honoring it.';
+      dialogNote.append(strong);
+    }
+  };
+
+  /* ------------------------------------------------------------------ *
+   * 3. Transparency dialog ("Your privacy on this page").
+   * ------------------------------------------------------------------ */
+  const setUpPrivacyDialog = () => {
+    const dialog = document.getElementById('privacy-info');
+    const opener = document.getElementById('privacy-info-open');
+    if (!(dialog instanceof HTMLDialogElement) || !opener) return;
+
+    // Only show the trigger once JS can actually open the dialog.
+    for (const el of document.querySelectorAll('.js-only')) el.hidden = false;
+
+    opener.addEventListener('click', () => dialog.showModal());
+
+    // Fallback light dismiss for browsers without `closedby="any"`.
+    if (!('closedBy' in HTMLDialogElement.prototype)) {
+      dialog.addEventListener('click', (event) => {
+        if (event.target !== dialog) return;
+        const r = dialog.getBoundingClientRect();
+        const inside =
+          event.clientX >= r.left && event.clientX <= r.right &&
+          event.clientY >= r.top && event.clientY <= r.bottom;
+        if (!inside) dialog.close();
+      });
+    }
+  };
+
+  /* ------------------------------------------------------------------ *
+   * 4. Secure data handling on logout.
+   *
+   * The server is responsible for invalidating the session and sending
+   * `Clear-Site-Data: "cookies", "storage", "cache"`. As a client-side
+   * belt-and-braces (and for browsers or proxies that drop that header),
+   * clear any same-origin Web Storage before the POST is sent.
+   * ------------------------------------------------------------------ */
+  const setUpLogout = () => {
+    for (const form of document.querySelectorAll('form.logout-form')) {
+      form.addEventListener('submit', () => {
+        try {
+          window.sessionStorage.clear();
+          window.localStorage.clear();
+        } catch {
+          // Storage may be unavailable (e.g. blocked by user settings).
+        }
+      });
+    }
+  };
+
+  /* ------------------------------------------------------------------ *
+   * 5. Third-party audit (runtime guardrail).
+   *
+   * Every resource on this page should be first-party. Watch resource
+   * timing entries and CSP violations and warn in the console when
+   * anything else appears, for example a rogue browser extension
+   * injection, a teammate pasting in a tracking snippet, or a CSS file
+   * that suddenly references a CDN. Only the origin is logged, never the
+   * full URL, so paths and query strings carrying PII stay out of the
+   * logs. Nothing is sent anywhere. Server-side CSP reporting covers
+   * production telemetry (see _headers → Reporting-Endpoints).
+   * ------------------------------------------------------------------ */
+  const ALLOWED_ORIGINS = new Set([window.location.origin]);
+  const reported = new Set();
+
+  const safeOrigin = (value) => {
+    try {
+      return new URL(value, window.location.href).origin;
+    } catch {
+      return 'unknown';
+    }
+  };
+
+  const flagThirdParty = (origin, how) => {
+    const key = `${how}:${origin}`;
+    if (reported.has(key)) return;
+    reported.add(key);
+    console.warn(
+      `[privacy-audit] Unexpected third-party ${how}: ${origin}. ` +
+        'Every new third party needs a privacy review (see PRIVACY.md) before it can ship.'
+    );
+  };
+
+  const setUpThirdPartyAudit = () => {
+    if ('PerformanceObserver' in window) {
+      const observer = new PerformanceObserver((list) => {
+        for (const entry of list.getEntries()) {
+          const origin = safeOrigin(entry.name);
+          if (origin.startsWith('http') && !ALLOWED_ORIGINS.has(origin)) {
+            flagThirdParty(origin, `request (${entry.initiatorType})`);
+          }
+        }
+      });
+      try {
+        observer.observe({ type: 'resource', buffered: true });
+      } catch {
+        // Older engines without `type` support. Nothing to audit.
+      }
+    }
+
+    document.addEventListener('securitypolicyviolation', (event) => {
+      const origin = event.blockedURI.startsWith('http')
+        ? safeOrigin(event.blockedURI)
+        : event.blockedURI; // e.g. "inline", "eval", "trusted-types-sink"
+      flagThirdParty(origin, `CSP violation [${event.effectiveDirective}]`);
+    });
+  };
+
+  /* ------------------------------------------------------------------ *
+   * Public API for future integrations: a single, auditable gate.
+   * Every optional purpose is OFF by default (privacy by default) and
+   * stays off whenever GPC is on.
+   * ------------------------------------------------------------------ */
+  const OPTIONAL_PURPOSES = Object.freeze(['analytics', 'marketing', 'personalization']);
+
+  window.DailyGrindPrivacy = Object.freeze({
+    gpc: gpcEnabled,
+    purposes: OPTIONAL_PURPOSES,
+    /**
+     * Returns false for every purpose. No optional integration exists, so
+     * none is allowed. When one is added, it needs an opt-in consent flow,
+     * and 'analytics'/'marketing' must still return false while
+     * `gpcEnabled` is true.
+     */
+    allows: (_purpose) => false,
+  });
+
+  scrubUrl();
+  setUpThirdPartyAudit();
+
+  const init = () => {
+    showPrivacySignal();
+    setUpPrivacyDialog();
+    setUpLogout();
+  };
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init, { once: true });
+  } else {
+    init();
+  }
+})();
