+#!/bin/sh
+# Download the hero stock photo once, at build/deploy time, so it can be
+# served from our own origin. Visitors' browsers then never contact the
+# image CDN, which would otherwise see their IP, user agent and referrer.
+# Photo: Unsplash (https://unsplash.com/photos/1495474472287-4d71bcdd2085),
+# Unsplash License.
+set -eu
+cd "$(dirname "$0")/.."
+mkdir -p assets/img
+for w in 800 1600; do
+  curl --fail --silent --show-error --location \
+    --output "assets/img/hero-coffee-$w.jpg" \
+    "https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=$w&q=75&fm=jpg"
+done
+echo "Hero images saved to assets/img/"

