@@ -0,0 +1,135 @@
+// Security & privacy response headers for The Daily Grind.
+//
+// The CSP is derived from privacy/third-parties.json so an origin can only be
+// contacted by the browser if it has been through a third-party review.
+
+import { readFileSync } from 'node:fs';
+import { extname } from 'node:path';
+
+const registry = JSON.parse(
+  readFileSync(new URL('./third-parties.json', import.meta.url), 'utf8'),
+);
+
+export const approvedVendors = registry.vendors.filter((v) => v.status === 'approved');
+
+/** Directives every policy starts from: deny by default, allow only first party. */
+const BASE_DIRECTIVES = {
+  'default-src': ["'none'"],
+  'script-src': ["'self'"],
+  'style-src': ["'self'"],
+  'img-src': ["'self'"],
+  'font-src': ["'self'"],
+  'connect-src': ["'self'"],
+  'manifest-src': ["'self'"],
+  'media-src': ["'none'"],
+  'frame-src': ["'none'"],
+  'worker-src': ["'none'"],
+  'object-src': ["'none'"],
+  'base-uri': ["'none'"],
+  'form-action': ["'self'"],
+  'frame-ancestors': ["'none'"],
+  // Only DOM APIs that cannot execute strings are used; forbid HTML/script sinks entirely.
+  'require-trusted-types-for': ["'script'"],
+  'trusted-types': ["'none'"],
+};
+
+/** Directives that are ignored (and warned about) when delivered via <meta>. */
+const HEADER_ONLY_DIRECTIVES = new Set(['frame-ancestors', 'report-uri', 'report-to', 'sandbox']);
+
+/**
+ * @param {{ production?: boolean, forMeta?: boolean }} [opts]
+ * @returns {string}
+ */
+export function buildContentSecurityPolicy({ production = false, forMeta = false } = {}) {
+  /** @type {Record<string, string[]>} */
+  const directives = structuredClone(BASE_DIRECTIVES);
+
+  for (const vendor of approvedVendors) {
+    for (const directive of vendor.cspDirectives) {
+      directives[directive] ??= [];
+      if (!directives[directive].includes(vendor.origin)) directives[directive].push(vendor.origin);
+    }
+  }
+
+  const parts = Object.entries(directives)
+    .filter(([name]) => !(forMeta && HEADER_ONLY_DIRECTIVES.has(name)))
+    .map(([name, values]) => `${name} ${values.join(' ')}`);
+
+  // Would break plain-http localhost development, so only in production.
+  if (production) parts.push('upgrade-insecure-requests');
+
+  return parts.join('; ');
+}
+
+/** Disable every powerful / tracking-capable browser feature the site does not use. */
+export const PERMISSIONS_POLICY = [
+  'accelerometer=()',
+  'ambient-light-sensor=()',
+  'attribution-reporting=()',
+  'autoplay=()',
+  'bluetooth=()',
+  'browsing-topics=()',
+  'camera=()',
+  'display-capture=()',
+  'encrypted-media=()',
+  'geolocation=()',
+  'gyroscope=()',
+  'hid=()',
+  'identity-credentials-get=()',
+  'idle-detection=()',
+  'interest-cohort=()',
+  'join-ad-interest-group=()',
+  'local-fonts=()',
+  'magnetometer=()',
+  'microphone=()',
+  'midi=()',
+  'payment=()',
+  'private-state-token-issuance=()',
+  'private-state-token-redemption=()',
+  'publickey-credentials-get=()',
+  'run-ad-auction=()',
+  'screen-wake-lock=()',
+  'serial=()',
+  'usb=()',
+  'xr-spatial-tracking=()',
+].join(', ');
+
+/**
+ * Headers applied to every static file response (CSP is applied separately to
+ * all responses, including errors).
+ *
+ * @param {{ production?: boolean, filePath?: string }} [opts]
+ * @returns {Record<string, string>}
+ */
+export function buildSecurityHeaders({ production = false, filePath = '' } = {}) {
+  const ext = extname(filePath).toLowerCase();
+  const isDocument = ext === '.html' || ext === '';
+
+  /** @type {Record<string, string>} */
+  const headers = {
+    // Never send full URLs (which may contain order IDs, search terms…) to other origins.
+    'Referrer-Policy': 'same-origin',
+    'Permissions-Policy': PERMISSIONS_POLICY,
+    'X-Content-Type-Options': 'nosniff',
+    'X-Frame-Options': 'DENY',
+    'Cross-Origin-Opener-Policy': 'same-origin',
+    'Cross-Origin-Resource-Policy': 'same-origin',
+    'Origin-Agent-Cluster': '?1',
+    'X-DNS-Prefetch-Control': 'off',
+    'X-Permitted-Cross-Domain-Policies': 'none',
+    // Pages show signed-in navigation: never store them in shared caches.
+    'Cache-Control': isDocument ? 'private, no-cache' : 'public, max-age=3600',
+  };
+
+  if (ext === '.json' || ext === '.txt') {
+    // /.well-known/* files must be readable by user agents & scanners on any origin.
+    headers['Cross-Origin-Resource-Policy'] = 'cross-origin';
+    headers['Access-Control-Allow-Origin'] = '*';
+  }
+
+  if (production) {
+    headers['Strict-Transport-Security'] = 'max-age=63072000; includeSubDomains; preload';
+  }
+
+  return headers;
+}
