+{
+  "$comment": "Registry of every third-party origin the site may contact. This file is the single source of truth: the Content-Security-Policy is generated from it (privacy/security-headers.mjs) and `pnpm audit:privacy` fails if public/ references any origin not approved here. Adding a vendor requires a privacy review (see docs/PRIVACY_BY_DESIGN.md#third-party-review-checklist).",
+  "lastReviewed": "2026-11-22",
+  "reviewIntervalDays": 90,
+  "vendors": [
+    {
+      "id": "unsplash-images",
+      "name": "Unsplash image CDN (imgix)",
+      "origin": "https://images.unsplash.com",
+      "status": "approved",
+      "cspDirectives": ["img-src"],
+      "purpose": "Homepage hero photograph (static image only).",
+      "consentCategory": "necessary",
+      "loadsScript": false,
+      "setsCookies": false,
+      "dataShared": [
+        "IP address (inherent to any HTTP request)",
+        "User-Agent and Accept headers",
+        "Requested image URL (identical for all visitors)"
+      ],
+      "dataNotShared": [
+        "Referrer / page URL (Referrer-Policy: same-origin + referrerpolicy=\"no-referrer\")",
+        "Cookies or credentials (crossorigin=\"anonymous\")",
+        "Account, order, or location data"
+      ],
+      "privacyPolicy": "https://unsplash.com/privacy",
+      "mitigation": "Self-host the image under /assets/img/ and remove this entry; the origin then disappears from the CSP automatically."
+    }
+  ],
+  "rejected": [
+    {
+      "name": "Google Fonts",
+      "reason": "Leaks visitor IP to Google on every page view; the system font stack is used instead."
+    },
+    {
+      "name": "Google Analytics / Meta Pixel / session replay tools",
+      "reason": "Cross-site tracking identifiers with no essential purpose. If first-party analytics are ever needed they must be cookieless, aggregate-only, and gated behind the `analytics` consent category."
+    },
+    {
+      "name": "Embedded maps / social widgets",
+      "reason": "Third-party iframes set cookies on load. Link out to the provider instead (frame-src 'none')."
+    }
+  ]
+}
