--- /dev/null
+++ b/public/assets/js/privacy.js
@@ -0,0 +1,319 @@
+/*!
+ * The Daily Grind — client-side privacy controls.
+ *
+ * Privacy by design / by default:
+ *  - Every optional data category is OFF until the visitor opts in.
+ *  - Global Privacy Control (GPC) and Do Not Track are honored as a binding
+ *    opt-out of analytics & marketing; they cannot be overridden in the UI.
+ *  - Tracking parameters (utm_*, gclid, fbclid…) are stripped from the URL so
+ *    they are not persisted in history, bookmarks, or shared links.
+ *  - Known third-party tracking identifiers left over from elsewhere are purged
+ *    unless the matching consent exists.
+ *  - The stored choice contains no identifier, only a day-granularity date, and
+ *    expires after 180 days.
+ *  - No network requests are made by this script; no HTML is parsed from
+ *    strings (compatible with `require-trusted-types-for 'script'`).
+ */
+(function () {
+  'use strict';
+
+  var STORAGE_KEY = 'dg.privacy.v1';
+  var SCHEMA_VERSION = 1;
+  var RETENTION_DAYS = 180;
+  var OPTIONAL_CATEGORIES = ['preferences', 'analytics', 'marketing'];
+  // Categories a GPC / DNT signal opts the visitor out of ("sale/share" & tracking).
+  var SIGNAL_LOCKED_CATEGORIES = ['analytics', 'marketing'];
+
+  var TRACKING_PARAMS = [
+    /^utm_/i, /^gclid$/i, /^gbraid$/i, /^wbraid$/i, /^dclid$/i, /^fbclid$/i,
+    /^msclkid$/i, /^ttclid$/i, /^twclid$/i, /^li_fat_id$/i, /^igshid$/i,
+    /^mc_(cid|eid)$/i, /^_hs(enc|mi)$/i, /^mkt_tok$/i, /^yclid$/i, /^_ga$/i, /^_gl$/i,
+    /^oly_(anon|enc)_id$/i, /^vero_(conv|id)$/i, /^s_cid$/i, /^ref_src$/i,
+  ];
+
+  // Identifier cookies / storage keys set by common ad & analytics vendors,
+  // mapped to the consent category that would be required to keep them.
+  var TRACKER_IDENTIFIERS = [
+    { pattern: /^(_ga|_gid|_gat|__utm[a-z]|_hj|ajs_|amplitude_|mp_|_pk_|_clck|_clsk)/, category: 'analytics' },
+    { pattern: /^(_fbp|_fbc|_gcl_|_uet|_tt_|_ttp|_pin_|IDE$|test_cookie$|li_|_rdt_)/, category: 'marketing' },
+  ];
+
+  // ---------------------------------------------------------------------------
+  // Signals
+  // ---------------------------------------------------------------------------
+
+  var signals = {
+    gpc: navigator.globalPrivacyControl === true,
+    dnt: navigator.doNotTrack === '1' || window.doNotTrack === '1',
+  };
+  var signalOptOut = signals.gpc || signals.dnt;
+
+  // ---------------------------------------------------------------------------
+  // Data minimization: strip tracking parameters from the address bar
+  // ---------------------------------------------------------------------------
+
+  function stripTrackingParams() {
+    if (!window.URL || !window.history || !history.replaceState) return;
+    var url = new URL(window.location.href);
+    var removed = false;
+    Array.from(url.searchParams.keys()).forEach(function (key) {
+      if (TRACKING_PARAMS.some(function (re) { return re.test(key); })) {
+        url.searchParams.delete(key);
+        removed = true;
+      }
+    });
+    if (removed) history.replaceState(history.state, '', url.pathname + url.search + url.hash);
+  }
+
+  // ---------------------------------------------------------------------------
+  // Consent storage (local only, minimal, expiring)
+  // ---------------------------------------------------------------------------
+
+  var memoryStore = null; // fallback when storage is unavailable / blocked
+
+  function storage() {
+    try {
+      var s = window.localStorage;
+      var probe = STORAGE_KEY + '.probe';
+      s.setItem(probe, '1');
+      s.removeItem(probe);
+      return s;
+    } catch (e) {
+      return null;
+    }
+  }
+
+  function today() {
+    return new Date().toISOString().slice(0, 10); // YYYY-MM-DD — no time-of-day precision
+  }
+
+  function defaultChoices() {
+    var choices = {};
+    OPTIONAL_CATEGORIES.forEach(function (c) { choices[c] = false; });
+    return choices;
+  }
+
+  /** Apply signals on top of any stored/selected choices. */
+  function enforceSignals(choices) {
+    if (signalOptOut) {
+      SIGNAL_LOCKED_CATEGORIES.forEach(function (c) { choices[c] = false; });
+    }
+    return choices;
+  }
+
+  /** Accept only known boolean keys from storage — never trust stored shape. */
+  function sanitize(raw) {
+    var clean = defaultChoices();
+    if (raw && typeof raw === 'object') {
+      OPTIONAL_CATEGORIES.forEach(function (c) { clean[c] = raw[c] === true; });
+    }
+    return clean;
+  }
+
+  function readRecord() {
+    var s = storage();
+    var text = s ? s.getItem(STORAGE_KEY) : memoryStore;
+    if (!text) return null;
+    try {
+      var record = JSON.parse(text);
+      var ageDays = (Date.now() - Date.parse(record.decidedOn)) / 86400000;
+      if (record.v !== SCHEMA_VERSION || !(ageDays >= 0 && ageDays <= RETENTION_DAYS)) {
+        clearRecord(); // expired or outdated: re-ask instead of assuming consent
+        return null;
+      }
+      return { decidedOn: record.decidedOn, choices: sanitize(record.choices) };
+    } catch (e) {
+      clearRecord();
+      return null;
+    }
+  }
+
+  function writeRecord(choices) {
+    var text = JSON.stringify({ v: SCHEMA_VERSION, decidedOn: today(), choices: sanitize(choices) });
+    var s = storage();
+    if (s) s.setItem(STORAGE_KEY, text);
+    else memoryStore = text;
+  }
+
+  function clearRecord() {
+    var s = storage();
+    if (s) s.removeItem(STORAGE_KEY);
+    memoryStore = null;
+  }
+
+  var record = readRecord();
+  var choices = enforceSignals(record ? record.choices : defaultChoices());
+
+  // ---------------------------------------------------------------------------
+  // Purge tracking identifiers the visitor has not consented to
+  // ---------------------------------------------------------------------------
+
+  function requiredCategory(name) {
+    for (var i = 0; i < TRACKER_IDENTIFIERS.length; i++) {
+      if (TRACKER_IDENTIFIERS[i].pattern.test(name)) return TRACKER_IDENTIFIERS[i].category;
+    }
+    return null;
+  }
+
+  function expireCookie(name) {
+    var parts = window.location.hostname.split('.');
+    var domains = [''];
+    for (var i = 0; i < parts.length - 1; i++) domains.push('; domain=.' + parts.slice(i).join('.'));
+    var paths = ['/', window.location.pathname];
+    domains.forEach(function (domain) {
+      paths.forEach(function (path) {
+        document.cookie = name + '=; Max-Age=0; path=' + path + domain + '; SameSite=Lax';
+      });
+    });
+  }
+
+  function purgeUnconsentedIdentifiers() {
+    document.cookie.split(';').forEach(function (pair) {
+      var name = pair.split('=')[0].trim();
+      var category = name && requiredCategory(name);
+      if (category && !choices[category]) expireCookie(name);
+    });
+
+    ['localStorage', 'sessionStorage'].forEach(function (storeName) {
+      try {
+        var store = window[storeName]; // property access itself throws when storage is blocked
+        for (var i = store.length - 1; i >= 0; i--) {
+          var key = store.key(i);
+          var category = key && requiredCategory(key);
+          if (category && !choices[category]) store.removeItem(key);
+        }
+      } catch (e) { /* storage blocked — nothing to purge */ }
+    });
+
+    // Preferences withdrawn: remove first-party preference data too.
+    if (!choices.preferences) {
+      try {
+        for (var j = localStorage.length - 1; j >= 0; j--) {
+          var k = localStorage.key(j);
+          if (k && k.indexOf('dg.pref.') === 0) localStorage.removeItem(k);
+        }
+      } catch (e) { /* ignore */ }
+    }
+  }
+
+  // ---------------------------------------------------------------------------
+  // Public API for future first-party features
+  // ---------------------------------------------------------------------------
+
+  var listeners = [];
+
+  function snapshot() {
+    var copy = {};
+    OPTIONAL_CATEGORIES.forEach(function (c) { copy[c] = choices[c]; });
+    copy.necessary = true;
+    return copy;
+  }
+
+  function notify() {
+    var detail = snapshot();
+    listeners.forEach(function (l) {
+      if (detail[l.category]) {
+        try { l.callback(detail); } catch (e) { /* isolate listener errors */ }
+      }
+    });
+    document.dispatchEvent(new CustomEvent('dailygrind:consentchange', { detail: detail }));
+  }
+
+  function setChoices(next) {
+    choices = enforceSignals(sanitize(next));
+    writeRecord(choices);
+    purgeUnconsentedIdentifiers();
+    notify();
+  }
+
+  window.DailyGrindPrivacy = Object.freeze({
+    /** @param {'necessary'|'preferences'|'analytics'|'marketing'} category */
+    hasConsent: function (category) {
+      return category === 'necessary' || choices[category] === true;
+    },
+    /**
+     * Run `callback` once consent for `category` is (or becomes) granted.
+     * Any optional feature MUST be initialised through this hook.
+     */
+    onConsent: function (category, callback) {
+      if (typeof callback !== 'function') return;
+      if (category === 'necessary' || choices[category]) {
+        callback(snapshot());
+      } else {
+        listeners.push({ category: category, callback: callback });
+      }
+    },
+    getChoices: snapshot,
+    signals: Object.freeze({ gpc: signals.gpc, dnt: signals.dnt }),
+    /** Withdraw everything and delete the stored record (right to erasure on-device). */
+    reset: function () {
+      choices = enforceSignals(defaultChoices());
+      clearRecord();
+      purgeUnconsentedIdentifiers();
+      notify();
+    },
+  });
+
+  // ---------------------------------------------------------------------------
+  // UI wiring (progressive enhancement — markup lives in index.html)
+  // ---------------------------------------------------------------------------
+
+  function initUi() {
+    var dialog = document.getElementById('privacy-dialog');
+    var form = document.getElementById('privacy-form');
+    var openButton = document.getElementById('privacy-choices-open');
+    var gpcStatus = document.getElementById('gpc-status');
+    var lockNote = document.getElementById('gpc-lock-note');
+
+    if (gpcStatus && signals.gpc) gpcStatus.hidden = false;
+    if (!dialog || !form || !openButton || typeof dialog.showModal !== 'function') return;
+
+    function syncForm() {
+      OPTIONAL_CATEGORIES.forEach(function (c) {
+        var input = form.elements.namedItem(c);
+        if (!input) return;
+        input.checked = choices[c];
+        if (signalOptOut && input.hasAttribute('data-gpc-locked')) input.disabled = true;
+      });
+      if (lockNote) lockNote.hidden = !signalOptOut;
+    }
+
+    openButton.hidden = false;
+    openButton.addEventListener('click', function () {
+      syncForm();
+      dialog.showModal();
+    });
+
+    dialog.addEventListener('close', function () {
+      var action = dialog.returnValue;
+      if (action === 'reject') {
+        setChoices(defaultChoices());
+      } else if (action === 'save') {
+        var next = {};
+        OPTIONAL_CATEGORIES.forEach(function (c) {
+          var input = form.elements.namedItem(c);
+          next[c] = !!(input && input.checked);
+        });
+        setChoices(next);
+      }
+      // Escape / cancel: keep existing choices unchanged.
+      dialog.returnValue = '';
+      openButton.focus();
+    });
+  }
+
+  // ---------------------------------------------------------------------------
+  // Boot
+  // ---------------------------------------------------------------------------
+
+  stripTrackingParams();
+  purgeUnconsentedIdentifiers();
+  // A signal received after an earlier opt-in overrides the stored choice.
+  if (record && signalOptOut) writeRecord(choices);
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initUi);
+  } else {
+    initUi();
+  }
+})();
