+#!/usr/bin/env node
+// Privacy & third-party audit for public/. Zero dependencies.
+//
+//   pnpm audit:privacy
+//
+// Fails (exit 1) when the published site:
+//  - loads a resource from an origin not approved in privacy/third-parties.json
+//  - uses insecure http:// resources or javascript: URLs
+//  - contains inline scripts, inline styles or inline event handlers (CSP bypasses)
+//  - has a <meta> CSP that drifted from the generated policy
+//  - links to other sites without rel="noopener noreferrer"
+//  - submits personal data via GET or exposes a GET logout link
+//  - publishes dotfiles other than /.well-known/
+// Warns when the vendor review is overdue or an approved vendor is unused.
+
+import { readdirSync, readFileSync, statSync } from 'node:fs';
+import { join, relative, extname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { approvedVendors, buildContentSecurityPolicy } from '../privacy/security-headers.mjs';
+
+const ROOT = fileURLToPath(new URL('../', import.meta.url));
+const PUBLIC = join(ROOT, 'public');
+const registry = JSON.parse(readFileSync(join(ROOT, 'privacy/third-parties.json'), 'utf8'));
+
+const errors = [];
+const warnings = [];
+const usedOrigins = new Set();
+const approvedOrigins = new Set(approvedVendors.map((v) => v.origin));
+
+const fail = (file, msg) => errors.push(`${relative(ROOT, file)}: ${msg}`);
+const warn = (file, msg) => warnings.push(`${relative(ROOT, file)}: ${msg}`);
+
+function walk(dir) {
+  return readdirSync(dir).flatMap((name) => {
+    const full = join(dir, name);
+    if (name.startsWith('.') && !(dir === PUBLIC && name === '.well-known')) {
+      fail(full, 'dotfile in public/ would be served (server allows dotfiles for /.well-known only)');
+      return [];
+    }
+    return statSync(full).isDirectory() ? walk(full) : [full];
+  });
+}
+
+function originOf(url) {
+  try {
+    return new URL(url.startsWith('//') ? `https:${url}` : url).origin;
+  } catch {
+    return null;
+  }
+}
+
+function checkResourceUrl(file, url, context) {
+  const value = url.trim();
+  if (/^javascript:/i.test(value)) return fail(file, `javascript: URL in ${context}`);
+  if (/^http:\/\//i.test(value)) return fail(file, `insecure http:// resource in ${context}: ${value}`);
+  if (!/^(https:)?\/\//i.test(value)) return; // first-party / relative / data:
+  const origin = originOf(value);
+  if (!origin) return fail(file, `unparseable URL in ${context}: ${value}`);
+  usedOrigins.add(origin);
+  if (!approvedOrigins.has(origin)) {
+    fail(file, `unapproved third-party origin ${origin} in ${context} — add a reviewed entry to privacy/third-parties.json or self-host`);
+  }
+}
+
+function auditHtml(file, source) {
+  const html = source.replace(/<!--[\s\S]*?-->/g, '');
+
+  for (const [, attrs, body] of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)) {
+    if (!/\bsrc\s*=/i.test(attrs) && body.trim()) fail(file, 'inline <script> (move to /assets/js)');
+  }
+  for (const [, css] of html.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)) {
+    fail(file, 'inline <style> element (move to /assets/css)');
+    auditCss(file, css);
+  }
+  for (const [, css] of html.matchAll(/\sstyle\s*=\s*"([^"]*)"/gi)) {
+    fail(file, 'inline style="" attribute');
+    auditCss(file, css);
+  }
+  for (const [, handler] of html.matchAll(/<[^>]+\s(on[a-z]+)\s*=/gi)) {
+    fail(file, `inline event handler ${handler}= (use addEventListener)`);
+  }
+
+  // Resource-loading attributes on any element except <a> (navigations are checked below).
+  for (const [tag] of html.matchAll(/<(?!a\b)[a-z][^>]*>/gi)) {
+    const name = tag.match(/^<([a-z0-9-]+)/i)[1].toLowerCase();
+    for (const [, attr, value] of tag.matchAll(/\s(src|href|action|poster|data|formaction)\s*=\s*"([^"]*)"/gi)) {
+      checkResourceUrl(file, value.replaceAll('&amp;', '&'), `<${name} ${attr}>`);
+    }
+    for (const [, set] of tag.matchAll(/\ssrcset\s*=\s*"([^"]*)"/gi)) {
+      for (const candidate of set.split(',')) {
+        checkResourceUrl(file, candidate.trim().split(/\s+/)[0].replaceAll('&amp;', '&'), `<${name} srcset>`);
+      }
+    }
+    if (name === 'img' && /\bsrc\s*=\s*"(https:)?\/\//i.test(tag) && !/referrerpolicy\s*=\s*"no-referrer"/i.test(tag)) {
+      fail(file, 'third-party <img> without referrerpolicy="no-referrer"');
+    }
+  }
+
+  // Outbound links: allowed, but must not leak the opener or the referrer.
+  for (const [tag, href] of html.matchAll(/<a\b[^>]*\shref\s*=\s*"([^"]*)"[^>]*>/gi)) {
+    if (/^javascript:/i.test(href)) fail(file, `javascript: link ${href}`);
+    if (/^(https?:)?\/\//i.test(href)) {
+      const rel = (tag.match(/\srel\s*=\s*"([^"]*)"/i) || [])[1] || '';
+      if (!/\bnoopener\b/.test(rel) || !/\bnoreferrer\b/.test(rel)) {
+        fail(file, `external link ${href} needs rel="noopener noreferrer"`);
+      }
+    }
+    if (/^\/logout\b/.test(href)) fail(file, 'logout must be a POST form, not a GET link (prefetch / CSRF)');
+  }
+
+  // Personal data must never be sent in a query string.
+  for (const [form, attrs, body] of html.matchAll(/<form\b([^>]*)>([\s\S]*?)<\/form>/gi)) {
+    const method = ((attrs.match(/\smethod\s*=\s*"([^"]*)"/i) || [])[1] || 'get').toLowerCase();
+    const sensitive = /type\s*=\s*"(password|email|tel)"|autocomplete\s*=\s*"(cc-|email|tel|street|postal|bday)/i.test(body);
+    if (method === 'get' && sensitive) fail(file, `form sends personal data via GET: ${form.slice(0, 60)}…`);
+    for (const [input] of body.matchAll(/<input\b[^>]*type\s*=\s*"password"[^>]*>/gi)) {
+      if (!/autocomplete\s*=/i.test(input)) fail(file, 'password input without autocomplete="current-password|new-password"');
+    }
+  }
+
+  // <meta> CSP must match the policy generated from the vendor registry.
+  const meta = html.match(/<meta\s+http-equiv\s*=\s*"Content-Security-Policy"\s+content\s*=\s*"([^"]*)"/i);
+  const expected = buildContentSecurityPolicy({ forMeta: true });
+  if (!meta) fail(file, `missing <meta> CSP; expected: ${expected}`);
+  else if (meta[1] !== expected) fail(file, `<meta> CSP drifted from generated policy.\n    expected: ${expected}\n    actual:   ${meta[1]}`);
+
+  if (!/<meta\s+name\s*=\s*"referrer"/i.test(html)) fail(file, 'missing <meta name="referrer">');
+}
+
+function auditCss(file, css) {
+  const source = css.replace(/\/\*[\s\S]*?\*\//g, '');
+  for (const [, , url] of source.matchAll(/url\(\s*(['"]?)([^'")]+)\1\s*\)/gi)) checkResourceUrl(file, url, 'CSS url()');
+  for (const [, url] of source.matchAll(/@import\s+(?:url\()?\s*['"]?([^'")\s;]+)/gi)) checkResourceUrl(file, url, 'CSS @import');
+}
+
+function auditJs(file, js) {
+  const source = js.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');
+  for (const [, url] of source.matchAll(/['"`]((?:https?:)?\/\/[^'"`\s]+)['"`]/g)) checkResourceUrl(file, url, 'script string');
+  if (/\b(eval|new\s+Function)\s*\(/.test(source)) fail(file, 'eval / new Function');
+  if (/\.(innerHTML|outerHTML)\s*=|insertAdjacentHTML|document\.write/.test(source)) {
+    fail(file, 'HTML string sink (blocked by Trusted Types; use DOM APIs)');
+  }
+  if (/\b(sendBeacon|fetch|XMLHttpRequest|WebSocket|EventSource)\b/.test(source)) {
+    warn(file, 'script performs network requests — confirm they are first-party and consent-gated');
+  }
+}
+
+for (const file of walk(PUBLIC)) {
+  const ext = extname(file).toLowerCase();
+  const text = ['.html', '.css', '.js', '.mjs'].includes(ext) ? readFileSync(file, 'utf8') : null;
+  if (ext === '.html') auditHtml(file, text);
+  else if (ext === '.css') auditCss(file, text);
+  else if (ext === '.js' || ext === '.mjs') auditJs(file, text);
+}
+
+for (const vendor of approvedVendors) {
+  if (!usedOrigins.has(vendor.origin)) {
+    warn(join(ROOT, 'privacy/third-parties.json'), `approved vendor "${vendor.id}" is unused — remove it to shrink the CSP`);
+  }
+  for (const field of ['purpose', 'dataShared', 'privacyPolicy', 'consentCategory']) {
+    if (!vendor[field]) fail(join(ROOT, 'privacy/third-parties.json'), `vendor "${vendor.id}" missing "${field}"`);
+  }
+}
+
+const dueDate = new Date(registry.lastReviewed);
+dueDate.setUTCDate(dueDate.getUTCDate() + (registry.reviewIntervalDays ?? 90));
+if (Date.now() > dueDate.getTime()) {
+  warn(join(ROOT, 'privacy/third-parties.json'), `third-party review overdue since ${dueDate.toISOString().slice(0, 10)}`);
+}
+
+console.log(`Third-party origins in use: ${[...usedOrigins].join(', ') || 'none'}`);
+for (const w of warnings) console.warn(`⚠ ${w}`);
+for (const e of errors) console.error(`✗ ${e}`);
+if (errors.length) {
+  console.error(`\nPrivacy audit failed with ${errors.length} error(s).`);
+  process.exit(1);
+}
+console.log(`✓ Privacy audit passed${warnings.length ? ` with ${warnings.length} warning(s)` : ''}.`);
