+// Static server for The Daily Grind with privacy & security headers.
+// Usage: pnpm start   (NODE_ENV=production enables HSTS + upgrade-insecure-requests)
+
+import { fileURLToPath } from 'node:url';
+import statikk from 'statikk';
+import { buildContentSecurityPolicy, buildSecurityHeaders } from './privacy/security-headers.mjs';
+
+const production = process.env.NODE_ENV === 'production';
+
+const { url } = await statikk({
+  // Only public/ is served — source, docs and config files are never exposed.
+  root: fileURLToPath(new URL('./public/', import.meta.url)),
+  port: process.env.PORT || 11222,
+  csp: buildContentSecurityPolicy({ production }),
+  // Required for /.well-known/. Safe because the root contains no other dotfiles
+  // (enforced by `pnpm audit:privacy`).
+  dotfiles: 'allow',
+  setHeaders(res, filePath) {
+    for (const [name, value] of Object.entries(buildSecurityHeaders({ production, filePath }))) {
+      res.setHeader(name, value);
+    }
+  },
+});
+
+console.log(`The Daily Grind serving at ${url}`);

