+---
+/**
+ * Privacy-by-design consent banner + third-party script loader.
+ *
+ * - Analytics is OFF by default and only loads after an explicit opt-in.
+ * - Global Privacy Control (Sec-GPC / navigator.globalPrivacyControl) is
+ *   honoured as a binding opt-out; the banner isn't shown to those users.
+ * - Third-party scripts never load on pages marked `data-sensitive`
+ *   (sign-in / sign-up), even when consent was given.
+ * - "Decline" is exactly as prominent as "Allow" (no dark patterns), and the
+ *   choice can be changed at any time via any `[data-open-privacy-preferences]`
+ *   control (e.g. the footer link).
+ * - Only the choice itself ("granted" / "denied") is stored, locally, in the
+ *   browser. No identifiers are created.
+ */
+const baseUrl = import.meta.env.BASE_URL;
+---
+
+<section
+  id="privacy-consent"
+  aria-labelledby="privacy-consent-title"
+  hidden
+  transition:persist
+  class="fixed inset-x-0 bottom-0 z-[100] border-t border-gray-300 bg-white p-4 shadow-lg md:p-6"
+>
+  <div class="mx-auto flex max-w-4xl flex-col gap-4 md:flex-row md:items-end">
+    <div class="text-sm text-gray-700">
+      <h2 id="privacy-consent-title" class="mb-1 text-base font-bold text-gray-900">
+        Your privacy choices
+      </h2>
+      <p>
+        We'd like to use an optional analytics service that records which links and buttons
+        are clicked (the element type, its visible label and a timestamp) so we can improve the
+        site. It is operated by a third party and is <strong>off unless you allow it</strong>.
+        It never runs on sign-in or sign-up pages. Declining doesn't limit anything on the site.
+      </p>
+      <p class="mt-1">
+        <a href={`${baseUrl}legal/privacy`} class="underline">Read our privacy policy</a>. You can
+        change your choice any time via “Manage Privacy Preferences” in the footer.
+      </p>
+    </div>
+    <div class="flex shrink-0 gap-3">
+      <button
+        type="button"
+        data-consent-choice="denied"
+        data-skip-tracking="true"
+        class="rounded border border-gray-900 bg-white px-4 py-2 text-sm font-semibold text-gray-900 hover:bg-gray-100"
+      >
+        Decline analytics
+      </button>
+      <button
+        type="button"
+        data-consent-choice="granted"
+        data-skip-tracking="true"
+        class="rounded border border-gray-900 bg-white px-4 py-2 text-sm font-semibold text-gray-900 hover:bg-gray-100"
+      >
+        Allow analytics
+      </button>
+    </div>
+  </div>
+</section>
+
+<script>
+  const STORAGE_KEY = 'dt-privacy-consent-analytics';
+  const ANALYTICS_SRC =
+    'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/lib/analytics-client.js';
+
+  type Choice = 'granted' | 'denied';
+
+  const hasGPC = () => (navigator as Navigator & { globalPrivacyControl?: boolean }).globalPrivacyControl === true;
+
+  function readChoice(): Choice | null {
+    if (hasGPC()) return 'denied';
+    try {
+      const value = localStorage.getItem(STORAGE_KEY);
+      return value === 'granted' || value === 'denied' ? value : null;
+    } catch {
+      return null;
+    }
+  }
+
+  function writeChoice(choice: Choice) {
+    try {
+      localStorage.setItem(STORAGE_KEY, choice);
+    } catch {
+      /* storage unavailable: the choice applies to this page view only */
+    }
+  }
+
+  const isSensitivePage = () => document.body.hasAttribute('data-sensitive');
+  const analyticsLoaded = () => document.querySelector('script[data-third-party="analytics"]') !== null;
+
+  function loadAnalytics() {
+    if (analyticsLoaded() || isSensitivePage() || readChoice() !== 'granted') return;
+    const script = document.createElement('script');
+    script.src = ANALYTICS_SRC;
+    script.async = true;
+    // Don't leak the current URL (path / query) to the third party.
+    script.referrerPolicy = 'no-referrer';
+    script.dataset.thirdParty = 'analytics';
+    document.head.append(script);
+  }
+
+  function banner() {
+    return document.getElementById('privacy-consent');
+  }
+
+  function showBanner() {
+    const el = banner();
+    if (el) el.hidden = false;
+  }
+
+  function hideBanner() {
+    const el = banner();
+    if (el) el.hidden = true;
+  }
+
+  function applyChoice(choice: Choice) {
+    writeChoice(choice);
+    hideBanner();
+    if (choice === 'granted') {
+      loadAnalytics();
+    } else if (analyticsLoaded()) {
+      // A loaded third-party script can't be unloaded; reload so it is gone immediately.
+      location.reload();
+    }
+  }
+
+  document.addEventListener('click', (event) => {
+    const target = event.target as Element | null;
+    const choiceButton = target?.closest<HTMLElement>('[data-consent-choice]');
+    if (choiceButton) {
+      applyChoice(choiceButton.dataset.consentChoice as Choice);
+      return;
+    }
+    const opener = target?.closest('[data-open-privacy-preferences]');
+    if (opener) {
+      event.preventDefault();
+      if (hasGPC()) {
+        alert('Your browser sends a Global Privacy Control signal, so optional analytics stays off.');
+        return;
+      }
+      showBanner();
+      banner()?.querySelector<HTMLElement>('[data-consent-choice="denied"]')?.focus();
+    }
+  });
+
+  function onPageLoad() {
+    if (isSensitivePage()) {
+      hideBanner();
+      // A client-side navigation would carry an already-loaded third-party script
+      // (and its global listeners) onto this page; start a clean document instead.
+      if (analyticsLoaded()) location.reload();
+      return;
+    }
+    if (readChoice() === null) showBanner();
+    else hideBanner();
+    loadAnalytics();
+  }
+
+  // Runs on the initial load and after every client-side navigation.
+  document.addEventListener('astro:page-load', onPageLoad);
+</script>
