+import React from 'react';
+
+const base = (import.meta.env.BASE_URL as string).replace(/\/?$/, '/');
+
+/** Plain-language notice shown where credentials are collected. */
+export default function AuthPrivacyNotice({ mode }: { mode: 'signin' | 'signup' }) {
+  return (
+    <div className="mt-6 text-xs text-gray-600 space-y-2" id={`${mode}-privacy-notice`}>
+      <p>
+        <strong>What we collect:</strong>{' '}
+        {mode === 'signup'
+          ? 'only a username and a password. We never ask for your real name, email address, or phone number. Please choose a username that doesn’t identify you.'
+          : 'only the username and password you type here, so we can check who you are.'}
+      </p>
+      <p>
+        <strong>Where it goes:</strong> straight from your browser to our account service on Google
+        Cloud, over an encrypted connection. We don&rsquo;t send the page address or cookies with it,
+        and we don&rsquo;t run analytics or ad scripts on this page.
+      </p>
+      <p>
+        Learn more in our{' '}
+        <a href={`${base}legal/privacy`} className="underline" data-skip-tracking="true">
+          Privacy Policy
+        </a>
+        {mode === 'signup' && (
+          <>
+            {' '}and{' '}
+            <a href={`${base}legal/terms`} className="underline" data-skip-tracking="true">
+              Terms of Service
+            </a>
+          </>
+        )}
+        .
+      </p>
+    </div>
+  );
+}
