+---
+/**
+ * Privacy-by-design consent manager.
+ *
+ * - No optional third-party script loads until the visitor explicitly opts in.
+ * - Browser opt-out signals (Global Privacy Control / Do Not Track) count as
+ *   a refusal and are never overridden by a stored or default choice.
+ * - The choice lives in localStorage only, so it is never sent to any server.
+ * - Optional scripts never load on pages that handle credentials.
+ */
+const baseUrl = import.meta.env.BASE_URL;
+const privacyUrl = `${baseUrl.replace(/\/?$/, '/')}legal/privacy`;
+---
+
+<div
+  id="consent-manager"
+  transition:persist
+  hidden
+  role="dialog"
+  aria-modal="false"
+  aria-labelledby="consent-title"
+  aria-describedby="consent-description"
+  class="fixed inset-x-0 bottom-0 z-50 border-t border-gray-300 bg-white shadow-lg"
+>
+  <div class="mx-auto max-w-4xl p-4 sm:p-6 text-sm text-gray-800">
+    <h2 id="consent-title" class="text-base font-bold mb-2">Your privacy choices</h2>
+    <p id="consent-description" class="mb-3">
+      We only use what we need to run The DevTools Times. With your permission, we would also
+      like to use an optional analytics service. If you allow it, the service records the text of
+      the links and buttons you click, along with a timestamp, and sends them to a third-party
+      server (Google Cloud). We don't use it on sign-in or sign-up pages, and it never gets the
+      contents of form fields. You can change your choice at any time with
+      "Manage Privacy Preferences" at the bottom of each page.
+      <a href={privacyUrl} class="underline" data-skip-tracking="true">Read our privacy policy</a>.
+    </p>
+
+    <fieldset class="mb-4 space-y-2">
+      <legend class="sr-only">Categories</legend>
+      <label class="flex items-start gap-2">
+        <input type="checkbox" checked disabled class="mt-1" />
+        <span><strong>Strictly necessary</strong>: lets the site work, for example by remembering your reading list. You can't turn this off.</span>
+      </label>
+      <label class="flex items-start gap-2">
+        <input type="checkbox" id="consent-analytics" class="mt-1" />
+        <span><strong>Analytics</strong> (optional, off by default): measures which links and buttons people click.</span>
