+  const analyticsBox = document.getElementById('consent-analytics') as HTMLInputElement;
+  const gpcNote = document.getElementById('consent-gpc-note') as HTMLElement;
+
+  function openBanner(focus = true) {
+    const consent = readConsent();
+    analyticsBox.checked = !!consent?.analytics && !optOutSignal;
+    analyticsBox.disabled = optOutSignal;
