new file mode 100644
index 0000000..a9b895a
--- /dev/null
+++ b/src/components/authClient.ts
@@ -0,0 +1,40 @@
+/**
+ * Shared helpers for the sign-in / sign-up forms.
+ *
+ * Privacy by design:
+ * - Send only the username and password: no device, location, or tracking data.
+ * - Never send the page URL (Referer) or ambient cookies to the auth service.
+ * - Don't let the browser or intermediaries cache credential requests or responses.
+ */
+export const AUTH_SERVICE_ORIGIN = 'https://us-central1-web-devrel-apps.cloudfunctions.net';
+const AUTH_BASE = `${AUTH_SERVICE_ORIGIN}/times_cdn/api`;
+
+export type AuthResult = { ok: true; data: unknown } | { ok: false; code?: string };
+
+export async function postCredentials(
+  endpoint: 'login' | 'register',
+  username: string,
+  password: string,
+): Promise<AuthResult> {
+  const response = await fetch(`${AUTH_BASE}/${endpoint}`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    // Data minimization: exactly the two fields the service needs.
+    body: JSON.stringify({ username: username.trim(), password }),
+    credentials: 'omit',
+    referrerPolicy: 'no-referrer',
+    cache: 'no-store',
+  });
+
+  let data: any = null;
+  try {
+    data = await response.json();
+  } catch {
+    /* non-JSON body */
+  }
+
+  if (!response.ok) {
+    return { ok: false, code: typeof data?.error === 'string' ? data.error : undefined };
+  }
+  return { ok: true, data };
+}
