+    const statusEl = document.getElementById('auth-status');
+    const accountLink = document.getElementById('account-link');
+
+    let signedIn = false;
+    let isAuthenticating = false;
+    let pendingIntent = null;              // { href, el, signinOnly }
+    let conditionalAbort = null;
+
+    // ---------- Shared helpers ----------
+
+    const announce = (msg) => { statusEl.textContent = ''; requestAnimationFrame(() => { statusEl.textContent = msg; }); };
+
+    function setSignedIn(user) {
+      signedIn = Boolean(user);
+      document.body.dataset.signedIn = String(signedIn);
+      for (const el of document.querySelectorAll('[data-when]')) {
+        el.hidden = el.dataset.when !== (signedIn ? 'signed-in' : 'signed-out');
+      }
+    }
+
+    async function getCapabilities() {
+      if (!window.PublicKeyCredential?.getClientCapabilities) return {};
+      try { return (await PublicKeyCredential.getClientCapabilities()) ?? {}; } catch { return {}; }
+    }
+
+    async function fetchRequestOptions() {
+      const res = await fetch(API.options, { method: 'POST', credentials: 'same-origin' });
+      if (!res.ok) throw new Error('Could not start sign-in');
+      return PublicKeyCredential.parseRequestOptionsFromJSON(await res.json());
+    }
+
+    async function postJSON(url, body) {
+      return fetch(url, {
+        method: 'POST',
+        credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify(body),
+      });
+    }
+
+    async function verifyPasskey(cred, publicKey) {
+      const encoded = cred.toJSON();
+      const res = await postJSON(API.verify, encoded);
+      if (res.status === 404) {
+        // Passkey was deleted server-side: tell the password manager to hide it.
+        if (PublicKeyCredential.signalUnknownCredential) {
+          await PublicKeyCredential.signalUnknownCredential({
