+        if (dialog.open) showError(err.message);
+      }
+    }
+
+    async function openSignInDialog() {
+      showError('');
+      form.reset();
+      const caps = await getCapabilities();
+      passkeyBtn.hidden = !window.PublicKeyCredential;
+      passkeyBtn.previousElementSibling.hidden = passkeyBtn.hidden;
+      if (caps.conditionalGet) startConditionalAutofill();
