+      announce('Sign-in dialog opened.');
+    }
+
+    passkeyBtn.addEventListener('click', async () => {
+      conditionalAbort?.abort();
+      showError('');
+      let publicKey, cred;
+      try {
+        publicKey = await fetchRequestOptions();
+        cred = await navigator.credentials.get({ publicKey }); // modal prompt: allows QR / security key
+      } catch (err) {
+        if (err.name !== 'NotAllowedError' && err.name !== 'AbortError') showError('Passkey sign-in isn’t available right now.');
+        startConditionalAutofill(); // re-arm autofill after cancel
+        return;
+      }
+      try {
+        completeSignIn(await verifyPasskey(cred, publicKey));
+      } catch (err) {
+        showError(err.message);
+        startConditionalAutofill();
+      }
+    });
+
+    form.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      showError('');
+      if (!form.checkValidity()) {
+        showError('Enter your email and password.');
+        form.querySelector(':invalid')?.focus();
+        return;
+      }
+      const submitBtn = form.querySelector('[type="submit"]');
+      submitBtn.disabled = true;
+      try {
+        const user = await verifyPassword(form.username.value.trim(), form.password.value);
+        // Offer to save to the browser so next visit can use one-tap Immediate UI.
+        if ('PasswordCredential' in window) {
+          navigator.credentials.store(new PasswordCredential(form)).catch(() => {});
+        }
+        completeSignIn(user);
+      } catch (err) {
+        showError(err.message);
+        form.password.select();
+      } finally {
+        submitBtn.disabled = false;
+      }
+    });
+
+    dialog.addEventListener('close', () => {
+      conditionalAbort?.abort();
+      if (!signedIn) pendingIntent = null;
+    });
+
+    // Light-dismiss fallback where <dialog closedby> isn't supported.
