+    }
+
+    // Invoker commands (command="close") polyfill only where missing.
+    if (!('commandForElement' in HTMLButtonElement.prototype)) {
+      dialog.querySelector('[command="close"]').addEventListener('click', () => dialog.close());
+    }
+
+    // ---------- Finish: continue what the user was doing ----------
+
+    function completeSignIn(user) {
+      setSignedIn(user);
+      const intent = pendingIntent;
+      pendingIntent = null;
+      if (dialog.open) dialog.close();
+      const name = user?.name ? `, ${user.name}` : '';
+
+      if (!intent || intent.signinOnly) {
+        // Stay on the page; the "Sign in" link is now hidden, so move focus somewhere that still exists.
+        accountLink.focus();
+        announce(`Welcome back${name}! You're signed in.`);
+        return;
+      }
+      announce(`Welcome back${name}! Taking you to ${intent.el.textContent.trim()}.`);
+      location.assign(intent.href);
+    }
+
+    // ---------- Intercept auth-gated links (Rewards, My Account, Order Now, Sign in) ----------
+
+    document.addEventListener('click', async (event) => {
+      const link = event.target.closest('a[data-requires-auth]');
+      if (!link || signedIn) return; // signed-in users navigate normally
+      // Let modified clicks (new tab, etc.) behave natively.
+      if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+
+      event.preventDefault();
+      if (isAuthenticating) return;
+      isAuthenticating = true;
+      pendingIntent = { href: link.href, el: link, signinOnly: link.hasAttribute('data-signin-only') };
+
+      try {
+        // Must run inside this click (transient user activation).
+        completeSignIn(await signInImmediately());
+      } catch (err) {
+        // NotAllowedError: no saved credentials on this device, user dismissed, or unsupported.
+        // Any other failure: still keep them on the page with the inline sign-in.
