+        if (err.name !== 'NotAllowedError') showError(err.message || 'Something went wrong. Please sign in below.');
+      } finally {
+        isAuthenticating = false;
+      }
+    });
+
+    // ---------- Initial session state ----------
+
+    try {
+      const res = await fetch(API.session, { credentials: 'same-origin' });
+      setSignedIn(res.ok ? ((await res.json()).user ?? {}) : null);
+    } catch {
+      setSignedIn(null);
+    }
+  </script>
+
