+        passwordLogin: '/api/auth/login',           // POST { username, password } -> { name }
+        passkeyOptions: '/api/auth/passkey/options', // POST -> PublicKeyCredentialRequestOptions (JSON, base64url)
+        passkeyVerify: '/api/auth/passkey/verify',   // POST credential JSON -> { name }
+        logout: '/api/auth/logout'                  // POST
+      };
+
+      const $ = (id) => document.getElementById(id);
+      const dialog = $('signin-dialog');
+      const form = $('signin-form');
+      const usernameInput = $('signin-username');
+      const passwordInput = $('signin-password');
+      const errorBox = $('signin-error');
+      const submitBtn = $('signin-submit');
+      const passkeyBtn = $('passkey-btn');
+      const contextText = $('signin-context');
+
+      const state = {
+        user: null,          // { name } when signed in
+        pendingHref: null,   // where the user was heading when prompted
+        conditionalAbort: null
+      };
+
+      const supportsPasskeys = typeof window.PublicKeyCredential === 'function' && !!navigator.credentials;
+      const supportsPasswordCredential = typeof window.PasswordCredential === 'function' && !!navigator.credentials;
+
+      /* ---------- helpers ---------- */
+
+      const b64urlToBuf = (s) => {
+        const pad = '='.repeat((4 - (s.length % 4)) % 4);
+        const bin = atob((s + pad).replace(/-/g, '+').replace(/_/g, '/'));
+        return Uint8Array.from(bin, (c) => c.charCodeAt(0)).buffer;
+      };
+      const bufToB64url = (buf) => {
+        let bin = '';
+        new Uint8Array(buf).forEach((b) => { bin += String.fromCharCode(b); });
+        return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+      };
+
+      async function postJSON(url, body) {
+        const res = await fetch(url, {
+          method: 'POST',
+          credentials: 'same-origin',
+          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+          body: body === undefined ? undefined : JSON.stringify(body)
+        });
+        const data = await res.json().catch(() => ({}));
+        if (!res.ok) throw new Error(data.message || 'Sign-in failed. Please try again.');
+        return data;
+      }
+
+      function showError(msg) {
+        errorBox.textContent = msg;
+        errorBox.hidden = !msg;
+      }
+
+      function setBusy(busy) {
+        submitBtn.disabled = busy;
+        passkeyBtn.disabled = busy;
+        submitBtn.textContent = busy ? 'Signing in…' : 'Sign In';
+      }
+
+      /* ---------- UI state ---------- */
+
+      function renderAuthState() {
+        const signedIn = !!state.user;
+        document.querySelectorAll('[data-auth]').forEach((el) => {
+          el.hidden = (el.dataset.auth === 'signed-in') !== signedIn;
+        });
+        $('account-greeting').textContent = signedIn && state.user.name ? `Hi, ${state.user.name}` : '';
+      }
+
+      function onSignedIn(user) {
+        state.user = user || { name: '' };
+        renderAuthState();
+        abortConditional();
+        const dest = state.pendingHref;
+        state.pendingHref = null;
+        if (dialog.open) dialog.close();
+        // Continue to wherever the customer was heading.
+        if (dest) window.location.assign(dest);
+      }
+
+      /* ---------- passkeys (WebAuthn) ---------- */
+
+      async function getPasskeyOptions() {
+        const opts = await postJSON(API.passkeyOptions);
+        const pk = opts.publicKey || opts;
+        return {
+          ...pk,
+          challenge: b64urlToBuf(pk.challenge),
+          allowCredentials: (pk.allowCredentials || []).map((c) => ({ ...c, id: b64urlToBuf(c.id) })),
+          userVerification: pk.userVerification || 'preferred'
+        };
+      }
+
+      function serializeAssertion(cred) {
+        const r = cred.response;
+        return {
+          id: cred.id,
+          rawId: bufToB64url(cred.rawId),
+          type: cred.type,
+          authenticatorAttachment: cred.authenticatorAttachment || null,
+          response: {
+            clientDataJSON: bufToB64url(r.clientDataJSON),
+            authenticatorData: bufToB64url(r.authenticatorData),
+            signature: bufToB64url(r.signature),
+            userHandle: r.userHandle ? bufToB64url(r.userHandle) : null
+          },
+          clientExtensionResults: cred.getClientExtensionResults ? cred.getClientExtensionResults() : {}
+        };
+      }
+
+      function abortConditional() {
+        if (state.conditionalAbort) {
+          state.conditionalAbort.abort();
+          state.conditionalAbort = null;
+        }
+      }
+
+      // Passkey autofill: saved passkeys appear in the email field's autofill menu.
+      async function startConditionalPasskey() {
+        if (!supportsPasskeys || !PublicKeyCredential.isConditionalMediationAvailable) return;
+        try {
+          if (!(await PublicKeyCredential.isConditionalMediationAvailable())) return;
+          abortConditional();
+          const controller = new AbortController();
+          state.conditionalAbort = controller;
+          const publicKey = await getPasskeyOptions();
+          const cred = await navigator.credentials.get({
+            mediation: 'conditional',
+            publicKey,
+            signal: controller.signal
+          });
+          if (!cred) return;
+          setBusy(true);
+          onSignedIn(await postJSON(API.passkeyVerify, serializeAssertion(cred)));
+        } catch (err) {
+          if (err.name !== 'AbortError' && err.name !== 'NotAllowedError') {
+            showError(err.message || 'Passkey sign-in failed.');
+          }
+        } finally {
+          setBusy(false);
+        }
+      }
+
+      // Explicit "Sign in with a passkey" button.
+      async function passkeySignIn() {
+        abortConditional();
+        showError('');
+        setBusy(true);
+        try {
+          const publicKey = await getPasskeyOptions();
+          const cred = await navigator.credentials.get({ publicKey, mediation: 'required' });
+          if (!cred) throw new Error('No passkey was selected.');
+          onSignedIn(await postJSON(API.passkeyVerify, serializeAssertion(cred)));
+        } catch (err) {
+          showError(err.name === 'NotAllowedError'
+            ? 'Passkey sign-in was cancelled. You can try again or use your password.'
+            : (err.message || 'Passkey sign-in failed.'));
+          if (dialog.open) startConditionalPasskey();
+        } finally {
+          setBusy(false);
+        }
+      }
+
+      /* ---------- passwords ---------- */
+
+      async function passwordSignIn(username, password, { storeCredential } = { storeCredential: true }) {
+        const user = await postJSON(API.passwordLogin, { username, password });
+        // Offer to save / update the password in the browser's password manager.
+        if (storeCredential && supportsPasswordCredential) {
+          try {
+            await navigator.credentials.store(new PasswordCredential({ id: username, password, name: user.name || username }));
+          } catch (_) { /* non-fatal */ }
+        }
+        return user;
+      }
+
+      // Try a saved password straight from the browser's credential manager (Chromium).
+      async function trySavedPassword() {
+        if (!supportsPasswordCredential) return false;
+        try {
+          const cred = await navigator.credentials.get({ password: true, mediation: 'optional' });
+          if (!cred || cred.type !== 'password') return false;
+          usernameInput.value = cred.id;
+          passwordInput.value = cred.password;
+          setBusy(true);
+          onSignedIn(await passwordSignIn(cred.id, cred.password, { storeCredential: false }));
+          return true;
+        } catch (err) {
+          if (err.name !== 'NotAllowedError' && err.name !== 'AbortError') showError(err.message);
+          return false;
+        } finally {
+          setBusy(false);
+        }
+      }
+
+      form.addEventListener('submit', async (e) => {
+        e.preventDefault();
+        showError('');
+        const username = usernameInput.value.trim();
+        const password = passwordInput.value;
+        if (!username || !password) {
+          showError('Please enter your email and password.');
+          (username ? passwordInput : usernameInput).focus();
+          return;
+        }
+        abortConditional();
+        setBusy(true);
+        try {
+          onSignedIn(await passwordSignIn(username, password));
+        } catch (err) {
+          showError(err.message);
+          passwordInput.select();
+          startConditionalPasskey();
+        } finally {
+          setBusy(false);
+        }
+      });
+
+      /* ---------- dialog ---------- */
+
+      function openSignIn(href, label) {
+        state.pendingHref = href || null;
+        contextText.textContent = label
+          ? `Sign in to continue to ${label}. Use a saved passkey or password — you'll stay right here.`
+          : 'Sign in with a saved passkey or password.';
+        showError('');
+        passwordInput.value = '';
+        if (typeof dialog.showModal === 'function') {
+          if (!dialog.open) dialog.showModal();
+        } else {
+          // Very old browsers without <dialog>: fall back to the full login page.
+          window.location.assign('/login' + (href ? '?next=' + encodeURIComponent(href) : ''));
+          return;
+        }
+        usernameInput.focus();
+        startConditionalPasskey();
+      }
+
+      dialog.addEventListener('close', () => {
+        abortConditional();
+        state.pendingHref = null;
+        setBusy(false);
+      });
+      $('signin-close').addEventListener('click', () => dialog.close());
+      dialog.addEventListener('click', (e) => { if (e.target === dialog) dialog.close(); });
+      passkeyBtn.addEventListener('click', passkeySignIn);
+
+      // Intercept links that need an account.
+      document.addEventListener('click', async (e) => {
+        if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
