+        if (!link || state.user) return;
+        e.preventDefault();
+        const isSignInLink = link.id === 'signin-link';
+        const href = isSignInLink ? null : link.getAttribute('href');
+        const label = isSignInLink ? '' : link.dataset.requiresAuth;
+        state.pendingHref = href;
+        // A saved password may sign them in silently without any form at all.
+        if (await trySavedPassword()) return;
+        openSignIn(href, label);
+      });
+
+      $('logout-link').addEventListener('click', async (e) => {
+        e.preventDefault();
+        try { await postJSON(API.logout); } catch (_) { /* ignore */ }
+        if (navigator.credentials && navigator.credentials.preventSilentAccess) {
+          try { await navigator.credentials.preventSilentAccess(); } catch (_) { /* ignore */ }
+        }
+        state.user = null;
+        renderAuthState();
+      });
+
+      /* ---------- init ---------- */
+
+      if (supportsPasskeys) {
+        passkeyBtn.hidden = false;
+        $('signin-divider').hidden = false;
+      }
+
+      fetch(API.session, { credentials: 'same-origin', headers: { Accept: 'application/json' } })
+        .then((r) => (r.ok ? r.json() : null))
+        .then((data) => {
+          if (data && data.authenticated) state.user = { name: data.name || '' };
+          renderAuthState();
+        })
+        .catch(renderAuthState);
+    })();
+  </script>
+
