diff --git a/public/app.js b/public/app.js
new file mode 100644
index 0000000..08d673a
--- /dev/null
+++ b/public/app.js
@@ -0,0 +1,106 @@
+// Newsletter signup. Requests can only go to our own origin: the server sends
+// Connection-Allowlist and Content-Security-Policy headers. If a request is
+// blocked or the network fails, fetch() rejects with a TypeError, and we show
+// the customer a message instead of failing silently.
+
+const ENDPOINT = '/api/newsletter';
+const TIMEOUT_MS = 10_000;
+
+const form = document.getElementById('newsletter-form');
+const status = document.getElementById('newsletter-status');
+const email = document.getElementById('newsletter-email');
+const emailError = document.getElementById('newsletter-email-error');
+const submitButton = form?.querySelector('button[type="submit"]');
+
+function setStatus(state, message) {
+  status.dataset.state = state;
+  status.textContent = message;
+}
+
+function showEmailError(message) {
+  emailError.textContent = message;
+  email.setAttribute('aria-invalid', 'true');
+}
+
+function clearEmailError() {
+  emailError.textContent = '';
+  email.removeAttribute('aria-invalid');
+}
+
+function validateEmail() {
+  if (email.validity.valueMissing) {
+    showEmailError('Please enter your email address.');
+    return false;
+  }
+  if (email.validity.typeMismatch || email.validity.tooLong) {
+    showEmailError('Please enter a valid email address, like name@example.com.');
+    return false;
+  }
+  clearEmailError();
+  return true;
+}
+
+if (form) {
+  // Clear errors while the user types, and validate once they leave the field.
+  email.addEventListener('input', () => {
+    if (email.validity.valid) clearEmailError();
+  });
+  email.addEventListener('blur', () => {
+    if (email.value) validateEmail();
+  });
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+
+    if (!validateEmail()) {
+      email.focus();
+      return;
+    }
+
+    submitButton.disabled = true;
+    setStatus('pending', 'Signing you up…');
+
+    try {
+      const response = await fetch(ENDPOINT, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+        body: JSON.stringify(Object.fromEntries(new FormData(form))),
+        credentials: 'same-origin',
+        signal: AbortSignal.timeout(TIMEOUT_MS),
+      });
+
+      let payload = null;
+      try {
+        payload = await response.json();
+      } catch {
+        // Non-JSON body (e.g. a proxy error page). Handled below.
+      }
+
+      if (response.ok) {
+        setStatus('success', payload?.message ?? "Thanks! You're on the list.");
+        form.reset();
+        clearEmailError();
+      } else if (response.status === 400 && payload?.field === 'email') {
+        showEmailError(payload.message);
+        setStatus('error', payload.message);
+        email.focus();
+      } else if (response.status === 429) {
+        setStatus('error', 'Too many attempts. Please wait a minute and try again.');
+      } else {
+        setStatus('error', "Sorry, we couldn't sign you up right now. Please try again later.");
+      }
+    } catch (error) {
+      // TypeError: offline, server unreachable, or blocked by the
+      // connection policy. TimeoutError: no response in time.
+      const timedOut = error?.name === 'TimeoutError';
+      setStatus(
+        'error',
+        timedOut
+          ? 'The request took too long. Please check your connection and try again.'
+          : "We couldn't reach our server, so your signup didn't go through. Please check your connection and try again.",
+      );
+    } finally {
+      submitButton.disabled = false;
+    }
+  });
+}
