index 0000000..ca9fa6d
--- /dev/null
+++ b/server.js
@@ -0,0 +1,370 @@
+// Small dependency-free server for The Daily Grind homepage.
+//
+// It serves the static site and the newsletter API, and sends response
+// headers that stop the page from talking to anything except:
+//   - our own origin (the page, its assets, and the /api/* endpoints)
+//   - https://images.unsplash.com (the hero photo)
+// So even if a script gets injected, it can't send customer data elsewhere.
+
+import { createServer } from 'node:http';
+import { readFile, appendFile, mkdir } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const ROOT = path.dirname(fileURLToPath(import.meta.url));
+const PUBLIC_DIR = path.join(ROOT, 'public');
+const DATA_DIR = path.join(ROOT, 'data');
+const SUBSCRIBERS_FILE = path.join(DATA_DIR, 'subscribers.jsonl');
+
+const PORT = Number(process.env.PORT) || 11222;
+const HOST = process.env.HOST || '0.0.0.0';
+const MAX_BODY_BYTES = 8 * 1024;
+const MAX_REPORT_BYTES = 64 * 1024;
+
+// ---------------------------------------------------------------------------
+// Outbound-connection policy
+// ---------------------------------------------------------------------------
+
+// The only third-party origin the page may contact. Origin-only, with no
+// trailing slash, so every path on the host matches.
+const ALLOWED_EXTERNAL_ORIGINS = ['https://images.unsplash.com'];
+
+const REPORT_ENDPOINT_NAME = 'security';
+const REPORT_PATH = '/api/security-reports';
+
+// Connection-Allowlist (Chrome/Edge 152+) is enforced at the network layer.
+// It covers fetch, XHR, beacons, subresources, navigations, resource hints
+// (dns-prefetch/preconnect), WebSockets, and WebRTC. It must be an RFC 9651
+// inner list: unquoted `response-origin` plus double-quoted URL patterns.
+// Redirects and WebRTC are blocked by default.
+const CONNECTION_ALLOWLIST =
+  `(response-origin ${ALLOWED_EXTERNAL_ORIGINS.map((o) => `"${o}"`).join(' ')})` +
+  `; report-to=${REPORT_ENDPOINT_NAME}`;
+
+// CSP is the fallback for browsers without Connection-Allowlist and a second
+// layer for those that support it. connect-src/form-action allow only our
+// origin. img-src adds Unsplash. Scripts and styles must be our own files, so
+// injected inline <script>/<style> won't run.
+const CONTENT_SECURITY_POLICY = [
+  "default-src 'self'",
+  "script-src 'self'",
+  "style-src 'self'",
+  `img-src 'self' ${ALLOWED_EXTERNAL_ORIGINS.join(' ')}`,
+  "font-src 'self'",
+  "connect-src 'self'",
+  "form-action 'self'",
+  "worker-src 'self'",
+  "manifest-src 'self'",
+  "media-src 'self'",
+  "frame-src 'none'",
+  "object-src 'none'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  "require-trusted-types-for 'script'",
+  "trusted-types 'none'",
+  `report-to ${REPORT_ENDPOINT_NAME}`,
+  `report-uri ${REPORT_PATH}`, // for browsers without the Reporting API (Firefox)
+].join('; ');
+
+// These headers only apply to documents and worker scripts.
+const POLICY_DESTS = new Set(['document', 'iframe', 'worker', 'sharedworker', 'serviceworker']);
+
+function applySecurityHeaders(req, res, { isDocument }) {
+  res.setHeader('Vary', 'Sec-Fetch-Dest');
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
+  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+  res.setHeader('X-Frame-Options', 'DENY');
+  res.setHeader(
+    'Permissions-Policy',
+    'camera=(), microphone=(), geolocation=(), payment=(), usb=(), browsing-topics=()',
+  );
+
+  const dest = String(req.headers['sec-fetch-dest'] || '').toLowerCase();
+  // Old browsers don't send Sec-Fetch-Dest, so if the header is missing,
+  // fall back to the response type.
+  if (isDocument || POLICY_DESTS.has(dest)) {
+    res.setHeader('Reporting-Endpoints', `${REPORT_ENDPOINT_NAME}="${REPORT_PATH}"`);
+    res.setHeader('Connection-Allowlist', CONNECTION_ALLOWLIST);
+    res.setHeader('Content-Security-Policy', CONTENT_SECURITY_POLICY);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Static files (fixed list only, so no path traversal)
+// ---------------------------------------------------------------------------
+
+const STATIC_FILES = new Map([
+  ['/', { file: 'index.html', type: 'text/html; charset=utf-8', document: true }],
+  ['/index.html', { file: 'index.html', type: 'text/html; charset=utf-8', document: true }],
+  ['/styles.css', { file: 'styles.css', type: 'text/css; charset=utf-8' }],
+  ['/app.js', { file: 'app.js', type: 'text/javascript; charset=utf-8' }],
+]);
+
+async function serveStatic(req, res, entry) {
+  try {
+    const body = await readFile(path.join(PUBLIC_DIR, entry.file));
+    applySecurityHeaders(req, res, { isDocument: !!entry.document });
+    res.writeHead(200, {
+      'Content-Type': entry.type,
+      'Content-Length': body.length,
+      'Cache-Control': entry.document ? 'no-cache' : 'public, max-age=300',
+    });
+    res.end(req.method === 'HEAD' ? undefined : body);
+  } catch (err) {
+    console.error('Static file error:', err);
+    sendHtml(req, res, 500, 'Something went wrong', 'Please try again shortly.');
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+function escapeHtml(value) {
+  return String(value).replace(/[&<>"']/g, (c) => ({
+    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
+  })[c]);
+}
+
+function sendJson(req, res, status, data) {
+  const body = JSON.stringify(data);
+  applySecurityHeaders(req, res, { isDocument: false });
+  res.writeHead(status, {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Content-Length': Buffer.byteLength(body),
+    'Cache-Control': 'no-store',
+  });
+  res.end(body);
+}
+
+// Plain HTML response for no-JS form posts. We render a page instead of a
+// 303 redirect because Connection-Allowlist blocks redirects by default.
+function sendHtml(req, res, status, title, message) {
+  const body = `<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>${escapeHtml(title)} | The Daily Grind</title>
+  <link rel="stylesheet" href="/styles.css">
+</head>
+<body>
+  <main class="container">
+    <section class="newsletter">
+      <h1>${escapeHtml(title)}</h1>
+      <p>${escapeHtml(message)}</p>
+      <a class="btn" href="/">Back to the homepage</a>
+    </section>
+  </main>
+</body>
+</html>`;
+  applySecurityHeaders(req, res, { isDocument: true });
+  res.writeHead(status, {
+    'Content-Type': 'text/html; charset=utf-8',
+    'Content-Length': Buffer.byteLength(body),
+    'Cache-Control': 'no-store',
+  });
+  res.end(body);
+}
+
+class HttpError extends Error {
+  constructor(status, message) {
+    super(message);
+    this.status = status;
+  }
+}
+
+function readBody(req, limit) {
+  return new Promise((resolve, reject) => {
+    const declared = Number(req.headers['content-length']);
+    if (declared > limit) {
+      reject(new HttpError(413, 'Request body too large.'));
+      req.resume();
+      return;
+    }
+    const chunks = [];
+    let size = 0;
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > limit) {
+        reject(new HttpError(413, 'Request body too large.'));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+// Basic per-IP rate limit for the signup endpoint.
+const RATE_WINDOW_MS = 60_000;
+const RATE_MAX = 5;
+const rateBuckets = new Map();
+
+function isRateLimited(ip) {
+  const now = Date.now();
+  const bucket = rateBuckets.get(ip);
+  if (!bucket || now - bucket.start > RATE_WINDOW_MS) {
+    rateBuckets.set(ip, { start: now, count: 1 });
+    return false;
+  }
+  bucket.count += 1;
+  return bucket.count > RATE_MAX;
+}
+
+setInterval(() => {
+  const now = Date.now();
+  for (const [ip, bucket] of rateBuckets) {
+    if (now - bucket.start > RATE_WINDOW_MS) rateBuckets.delete(ip);
+  }
+}, RATE_WINDOW_MS).unref();
+
+// ---------------------------------------------------------------------------
+// Newsletter API
+// ---------------------------------------------------------------------------
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+async function handleNewsletter(req, res) {
+  const contentType = String(req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
+  const isJson = contentType === 'application/json';
+  const isForm = contentType === 'application/x-www-form-urlencoded';
+
+  const reply = (status, data, title) =>
+    isJson
+      ? sendJson(req, res, status, data)
+      : sendHtml(req, res, status, title ?? (status < 400 ? "You're subscribed!" : 'Signup failed'), data.message);
+
+  if (!isJson && !isForm) {
+    return sendJson(req, res, 415, { ok: false, message: 'Unsupported content type.' });
+  }
+
+  // Cross-site requests can't subscribe people.
+  const site = req.headers['sec-fetch-site'];
+  if (site && site !== 'same-origin' && site !== 'none') {
+    return reply(403, { ok: false, message: 'Cross-site requests are not allowed.' });
+  }
+
+  if (isRateLimited(req.socket.remoteAddress || 'unknown')) {
+    return reply(429, { ok: false, message: 'Too many attempts. Please wait a minute and try again.' });
+  }
+
+  let fields;
+  try {
+    const raw = await readBody(req, MAX_BODY_BYTES);
+    fields = isJson ? JSON.parse(raw || '{}') : Object.fromEntries(new URLSearchParams(raw));
+    if (!fields || typeof fields !== 'object' || Array.isArray(fields)) throw new Error('bad shape');
+  } catch (err) {
+    const status = err instanceof HttpError ? err.status : 400;
+    return reply(status, { ok: false, message: 'We could not read your signup. Please try again.' });
+  }
+
+  // Honeypot filled in: probably a bot. Pretend it worked.
+  if (typeof fields.website === 'string' && fields.website.trim() !== '') {
+    return reply(200, { ok: true, message: "Thanks! You're on the list." });
+  }
+
+  const email = typeof fields.email === 'string' ? fields.email.trim().toLowerCase() : '';
+  const name = typeof fields.name === 'string' ? fields.name.trim().slice(0, 80) : '';
+
+  if (!email || email.length > 254 || !EMAIL_RE.test(email)) {
+    return reply(400, {
+      ok: false,
+      field: 'email',
+      message: 'Please enter a valid email address, like name@example.com.',
+    });
+  }
+
+  try {
+    await mkdir(DATA_DIR, { recursive: true });
+    await appendFile(
+      SUBSCRIBERS_FILE,
+      JSON.stringify({ email, name, subscribedAt: new Date().toISOString() }) + '\n',
+      { mode: 0o600 },
+    );
+  } catch (err) {
+    console.error('Failed to store subscriber:', err);
+    return reply(500, { ok: false, message: "Sorry, we couldn't sign you up right now. Please try again later." });
+  }
+
+  return reply(201, {
+    ok: true,
+    message: name ? `Thanks, ${name}! You're on the list.` : "Thanks! You're on the list.",
+  });
+}
+
+// Receives Connection-Allowlist and CSP violation reports. A blocked
+// connection may mean someone injected a script, so log it.
+async function handleSecurityReport(req, res) {
+  try {
+    const raw = await readBody(req, MAX_REPORT_BYTES);
+    const parsed = JSON.parse(raw);
+    const reports = Array.isArray(parsed) ? parsed : [parsed];
+    for (const report of reports) {
+      console.warn('[security-report]', JSON.stringify(report));
+    }
+  } catch {
+    // Ignore malformed reports.
+  }
+  res.writeHead(204, { 'Cache-Control': 'no-store' });
+  res.end();
+}
+
+// ---------------------------------------------------------------------------
+// Router
+// ---------------------------------------------------------------------------
+
+const server = createServer(async (req, res) => {
+  let pathname;
+  try {
+    pathname = new URL(req.url, 'http://localhost').pathname;
+  } catch {
+    res.writeHead(400).end();
+    return;
+  }
+
+  try {
+    if (pathname === '/api/newsletter') {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        return sendJson(req, res, 405, { ok: false, message: 'Method not allowed.' });
+      }
+      return await handleNewsletter(req, res);
+    }
+
+    if (pathname === REPORT_PATH) {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        res.writeHead(405).end();
+        return;
+      }
+      return await handleSecurityReport(req, res);
+    }
+
+    const entry = STATIC_FILES.get(pathname);
+    if (entry && (req.method === 'GET' || req.method === 'HEAD')) {
+      return await serveStatic(req, res, entry);
+    }
+    if (entry) {
+      res.setHeader('Allow', 'GET, HEAD');
+      return sendHtml(req, res, 405, 'Method not allowed', 'That request method is not supported here.');
+    }
+
+    return sendHtml(req, res, 404, 'Page not found', "We couldn't find that page.");
+  } catch (err) {
+    console.error('Unhandled request error:', err);
+    if (!res.headersSent) {
+      sendHtml(req, res, 500, 'Something went wrong', 'Please try again shortly.');
+    } else {
+      res.destroy();
+    }
+  }
+});
+
+server.listen(PORT, HOST, () => {
+  console.log(`The Daily Grind is serving on http://${HOST}:${PORT}`);
+});

