+'use strict';
+
+(function () {
+  var form = document.getElementById('newsletter-form');
+  var status = document.getElementById('newsletter-status');
+  if (!form || !status) return;
+
+  var input = form.querySelector('input[name="email"]');
+  var button = form.querySelector('button[type="submit"]');
+  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+  var MESSAGES = {
+    ok: "Thanks! You're on the list. Watch your inbox for fresh brews.",
+    invalid: 'Please enter a valid email address.',
+    blocked: "Sorry, we couldn't send your request. Please refresh the page and try again.",
+    network: "We couldn't reach our server. Check your connection and try again.",
+    server: 'Something went wrong on our end. Please try again in a moment.'
+  };
+
+  function show(message, kind) {
+    status.textContent = message;
+    status.className = 'newsletter-status ' + (kind === 'success' ? 'is-success' : 'is-error');
+    status.hidden = false;
+  }
+
+  // If anything on the page tries to reach a host our Content-Security-Policy
+  // doesn't allow, the browser blocks it. Tell the customer rather than failing silently.
+  var blockedRecently = false;
+  document.addEventListener('securitypolicyviolation', function (e) {
+    var directive = e.effectiveDirective || e.violatedDirective || '';
+    if (directive.indexOf('connect-src') === 0 || directive.indexOf('form-action') === 0) {
+      blockedRecently = true;
+      show(MESSAGES.blocked, 'error');
+    }
+  });
+
+  // Fallback for no-JS submissions that were redirected back with a result.
+  var params = new URLSearchParams(window.location.search);
+  var result = params.get('newsletter');
+  if (result && MESSAGES[result]) {
+    show(MESSAGES[result], result === 'ok' ? 'success' : 'error');
+    params.delete('newsletter');
+    var qs = params.toString();
+    history.replaceState(null, '', window.location.pathname + (qs ? '?' + qs : '') + window.location.hash);
+  }
+
+  form.addEventListener('submit', function (event) {
+    event.preventDefault();
+    var email = input.value.trim();
+
+    if (!EMAIL_RE.test(email)) {
+      show(MESSAGES.invalid, 'error');
+      input.focus();
+      return;
+    }
+
+    button.disabled = true;
+    blockedRecently = false;
+
+    fetch(form.getAttribute('action'), {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
+      credentials: 'same-origin',
+      body: JSON.stringify({ email: email })
+    })
+      .then(function (res) {
+        return res.json().catch(function () { return {}; }).then(function (data) {
+          if (res.ok) {
+            show(MESSAGES.ok, 'success');
+            form.reset();
+          } else if (res.status === 400) {
+            show(data.error || MESSAGES.invalid, 'error');
+          } else {
+            show(MESSAGES.server, 'error');
+          }
+        });
+      })
+      .catch(function () {
+        // fetch rejects both on network failure and when CSP blocks the request.
+        show(blockedRecently ? MESSAGES.blocked : MESSAGES.network, 'error');
+      })
+      .then(function () {
+        button.disabled = false;
+      });
+  });
+})();
