@@ -0,0 +1,234 @@
+'use strict';
+
+// Small zero-dependency server for The Daily Grind homepage.
+// Serves the static site from ./public with strict security headers and
+// accepts newsletter signups at POST /api/newsletter.
+
+const http = require('node:http');
+const fs = require('node:fs');
+const fsp = require('node:fs/promises');
+const path = require('node:path');
+
+const PORT = Number(process.env.PORT) || 11222;
+const HOST = process.env.HOST || '0.0.0.0';
+const PUBLIC_DIR = path.join(__dirname, 'public');
+const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
+const SUBSCRIBERS_FILE = path.join(DATA_DIR, 'subscribers.jsonl');
+const MAX_BODY_BYTES = 4 * 1024;
+
+// The page may only talk to our own origin, plus load photos from Unsplash.
+// No inline scripts/styles are allowed, so an injected <script> or handler
+// attribute won't run, and anything that does run can't fetch/XHR/beacon/
+// WebSocket or submit forms to another host.
+const CSP = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "font-src 'self'",
+  "connect-src 'self'",
+  "form-action 'self'",
+  "manifest-src 'self'",
+  "media-src 'none'",
+  "object-src 'none'",
+  "frame-src 'none'",
+  "worker-src 'none'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+].join('; ');
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': CSP,
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'X-Frame-Options': 'DENY',
+  'Cross-Origin-Opener-Policy': 'same-origin',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
+  'X-DNS-Prefetch-Control': 'off',
+};
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon',
+  '.webp': 'image/webp',
+  '.txt': 'text/plain; charset=utf-8',
+};
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+// --- Subscriber storage -----------------------------------------------------
+
+const subscribers = new Set();
+try {
+  for (const line of fs.readFileSync(SUBSCRIBERS_FILE, 'utf8').split('\n')) {
+    if (!line.trim()) continue;
+    try {
+      subscribers.add(JSON.parse(line).email);
+    } catch { /* skip malformed line */ }
+  }
+} catch (err) {
+  if (err.code !== 'ENOENT') throw err;
+}
+
+async function addSubscriber(email) {
+  if (subscribers.has(email)) return;
+  await fsp.mkdir(DATA_DIR, { recursive: true });
+  const record = JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n';
+  await fsp.appendFile(SUBSCRIBERS_FILE, record, { encoding: 'utf8', mode: 0o600 });
+  subscribers.add(email);
+}
+
+// --- Helpers ----------------------------------------------------------------
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, { ...SECURITY_HEADERS, ...headers });
+  res.end(body);
+}
+
+function sendJson(res, status, obj) {
+  send(res, status, JSON.stringify(obj), {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Cache-Control': 'no-store',
+  });
+}
+
+function redirect(res, location) {
+  send(res, 303, '', { Location: location, 'Cache-Control': 'no-store' });
+}
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+// Reject cross-site POSTs (basic CSRF protection): browsers always send
+// Origin on POST, and it must match the host the page was served from.
+function isSameOrigin(req) {
+  const origin = req.headers.origin;
+  if (!origin) return req.headers['sec-fetch-site'] !== 'cross-site';
+  try {
+    return new URL(origin).host === req.headers.host;
+  } catch {
+    return false;
+  }
+}
+
+// --- Routes -----------------------------------------------------------------
+
+async function handleNewsletter(req, res) {
+  const contentType = (req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
+  const wantsJson = contentType === 'application/json' ||
+    (req.headers.accept || '').includes('application/json');
+  const fail = (status, code, message) =>
+    wantsJson ? sendJson(res, status, { ok: false, error: message }) : redirect(res, `/?newsletter=${code}#newsletter-title`);
+
+  if (!isSameOrigin(req)) return fail(403, 'blocked', 'Cross-origin requests are not allowed.');
+
+  let email;
+  try {
+    const raw = await readBody(req);
+    if (contentType === 'application/json') {
+      email = JSON.parse(raw).email;
+    } else if (contentType === 'application/x-www-form-urlencoded') {
+      email = new URLSearchParams(raw).get('email');
+    } else {
+      return fail(415, 'server', 'Unsupported content type.');
+    }
+  } catch (err) {
+    if (err.status === 413) return fail(413, 'invalid', 'Request too large.');
+    return fail(400, 'invalid', 'Please enter a valid email address.');
+  }
+
+  email = typeof email === 'string' ? email.trim().toLowerCase() : '';
+  if (!email || email.length > 254 || !EMAIL_RE.test(email)) {
+    return fail(400, 'invalid', 'Please enter a valid email address.');
+  }
+
+  try {
+    await addSubscriber(email);
+  } catch (err) {
+    console.error('Failed to save subscriber:', err);
+    return fail(500, 'server', 'Could not save your signup.');
+  }
+
+  return wantsJson ? sendJson(res, 200, { ok: true }) : redirect(res, '/?newsletter=ok#newsletter-title');
+}
+
+async function serveStatic(req, res, pathname) {
+  let rel;
+  try {
+    rel = decodeURIComponent(pathname);
+  } catch {
+    return send(res, 400, 'Bad Request', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+  if (rel.endsWith('/')) rel += 'index.html';
+
+  const filePath = path.resolve(PUBLIC_DIR, '.' + path.posix.normalize(rel));
+  if (!filePath.startsWith(PUBLIC_DIR + path.sep) || rel.includes('\0')) {
+    return send(res, 404, 'Not Found', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+
+  try {
+    const stat = await fsp.stat(filePath);
+    if (!stat.isFile()) throw Object.assign(new Error('not a file'), { code: 'ENOENT' });
+    const ext = path.extname(filePath).toLowerCase();
+    const headers = {
+      'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
+      'Content-Length': stat.size,
+      'Cache-Control': ext === '.html' ? 'no-cache' : 'public, max-age=3600',
+    };
+    if (req.method === 'HEAD') return send(res, 200, undefined, headers);
+    res.writeHead(200, { ...SECURITY_HEADERS, ...headers });
+    fs.createReadStream(filePath).on('error', () => res.destroy()).pipe(res);
+  } catch (err) {
+    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
+      return send(res, 404, 'Not Found', { 'Content-Type': 'text/plain; charset=utf-8' });
+    }
+    throw err;
+  }
+}
+
+const server = http.createServer(async (req, res) => {
+  try {
+    const { pathname } = new URL(req.url, 'http://localhost');
+
+    if (pathname === '/api/newsletter') {
+      if (req.method !== 'POST') return send(res, 405, 'Method Not Allowed', { Allow: 'POST' });
+      return await handleNewsletter(req, res);
+    }
+
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      return send(res, 405, 'Method Not Allowed', { Allow: 'GET, HEAD' });
+    }
+    return await serveStatic(req, res, pathname);
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) send(res, 500, 'Internal Server Error', { 'Content-Type': 'text/plain; charset=utf-8' });
+    else res.destroy();
+  }
+});
+
+server.listen(PORT, HOST, () => {
+  console.log(`The Daily Grind is brewing at http://${HOST}:${PORT}`);
+});

