+  <script>
+    (() => {
+      const listPage = document.getElementById("list-page");
+      const detailPage = document.getElementById("detail-page");
+      const listHeading = document.getElementById("list-heading");
+      const hero = document.getElementById("hero");
+      const title = document.getElementById("title");
+      const description = document.getElementById("detail-description");
+      const notes = document.getElementById("detail-notes");
+      const backButton = detailPage.querySelector(".back");
+      const baseTitle = document.title;
+      const cards = [...document.querySelectorAll(".thumbnail")];
+
+      const findCard = (id) => cards.find((card) => card.dataset.id === id);
+
+      // Wrap a DOM update in a view transition when supported.
+      function transition(update) {
+        if (!document.startViewTransition) {
+          update();
+          return Promise.resolve();
+        }
+        return document.startViewTransition(update).finished;
+      }
+
+      function populateDetail(card) {
+        const img = card.querySelector("img");
+        hero.src = img.currentSrc || img.src;
+        hero.alt = img.alt;
+        title.textContent = card.querySelector(".title").textContent.trim();
+        description.textContent = card.querySelector(".summary").textContent.trim();
+        notes.textContent = card.querySelector(".notes").textContent.trim();
+      }
+
+      function showDetail(card) {
+        // Clear any stale selection so only one element carries each name.
+        cards.forEach((c) => c.classList.remove("selected"));
+        card.classList.add("selected");
+        populateDetail(card);
+
+        transition(() => {
+          listPage.hidden = true;
+          detailPage.hidden = false;
+          document.title = `${title.textContent} | ${baseTitle}`;
+          detailPage.scrollIntoView({ block: "start" });
+        }).finally(() => title.focus({ preventScroll: true }));
+      }
+
+      function showList() {
+        if (!detailPage.hidden) {
+          const selected = cards.find((c) => c.classList.contains("selected"));
+          transition(() => {
+            detailPage.hidden = true;
+            listPage.hidden = false;
+            document.title = baseTitle;
+            (selected ?? listPage).scrollIntoView({ block: "nearest" });
+          }).finally(() => {
+            cards.forEach((c) => c.classList.remove("selected"));
+            const target = selected?.querySelector(".title button") ?? listHeading;
+            target.focus({ preventScroll: true });
+          });
+        }
+      }
+
+      // Keep the browser back/forward buttons in sync via the URL hash.
+      function route() {
+        const card = findCard(location.hash.slice(1));
+        if (card) showDetail(card);
+        else showList();
+      }
+
+      cards.forEach((card) => {
+        card.querySelector(".title button").addEventListener("click", () => {
+          history.pushState({ detail: true }, "", `#${card.dataset.id}`);
+          route();
+        });
+      });
+
+      backButton.addEventListener("click", () => {
+        if (history.state?.detail) history.back(); // popstate -> route()
+        else {
+          history.pushState(null, "", location.pathname + location.search);
+          route();
+        }
+      });
+
+      window.addEventListener("popstate", route);
+
+      // Deep link on load without animating.
+      const initial = findCard(location.hash.slice(1));
+      if (initial) {
+        populateDetail(initial);
+        initial.classList.add("selected");
+        listPage.hidden = true;
+        detailPage.hidden = false;
+        document.title = `${title.textContent} | ${baseTitle}`;
+      }
+    })();
+  </script>
