+      renderSafeHTML(preview, bodyInput.value);
+    });
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+      status.textContent = '';
+
+      const fields = [nameInput, bodyInput];
+      const invalid = fields.filter((f) => !validateField(f));
+      if (invalid.length > 0) {
+        invalid[0].focus();
+        return;
+      }
+
+      submitButton.disabled = true;
+
+      const data = new FormData(form);
+      const drink = data.get('drink');
+      reviews = [
+        ...reviews,
+        {
+          id: crypto.randomUUID(),
+          drink: drink in DRINKS ? drink : 'maple-oat-latte',
+          name: data.get('name').trim().slice(0, 60),
+          date: new Date().toISOString(),
+          // Stored raw; sanitized every time it is rendered.
+          html: data.get('review')
+        }
+      ];
+      saveReviews(reviews);
+      renderReviews();
+
+      const drinkName = DRINKS[drink] ?? 'your drink';
+      nameInput.value = '';
+      bodyInput.value = '';
+      preview.replaceChildren();
+      status.textContent = `Thanks! Your review of ${drinkName} has been posted.`;
+      submitButton.disabled = false;
+    });
+
+    renderReviews();
+  </script>
+
