+      // Native scrollspy via :target-current; mirror state to aria-current for assistive tech
+      const syncAriaCurrent = () => {
+        const current = document.querySelector('.nav-links a:target-current');
+        navLinks.forEach(link => {
+          if (link === current) link.setAttribute('aria-current', 'true');
+          else link.removeAttribute('aria-current');
+        });
+      };
+      syncAriaCurrent();
+      document.addEventListener('scrollend', syncAriaCurrent);
+    } else {
+      // Fallback: IntersectionObserver watching a thin band across the middle of the viewport
+      const visible = new Set();
+      const update = () => {
+        const atBottom =
+          window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2;
+        const active = atBottom && window.scrollY > 0 ? sections.at(-1) : sections.find(s => visible.has(s));
+        setCurrent(active ? navLinks[sections.indexOf(active)] : null);
+      };
