+/**
+ * <drink-card> — reusable menu card with encapsulated layout and styles.
+ *
+ * Content (light DOM, supplied by the page):
+ *   <span slot="title">…</span>   Drink name, rendered inside the card's <h3>.
+ *   (default slot)                Description text.
+ *
+ * Attributes:
+ *   action-href    URL for the card's action link.
+ *   action-label   Link text (default: "View Details").
+ *   limited        Boolean. When present, shows a "Limited" badge.
+ *                  Add/remove at any time (or set `card.limited = true/false`).
+ *
+ * Theming (optional, set on any ancestor):
+ *   --drink-card-bg, --drink-card-accent, --drink-card-accent-hover,
+ *   --drink-card-badge-bg, --drink-card-badge-fg, --drink-card-radius
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_bg: var(--drink-card-bg, #fff);
+    --_accent: var(--drink-card-accent, var(--primary, #4e342e));
+    --_accent-hover: var(--drink-card-accent-hover, #3e2723);
+    --_badge-bg: var(--drink-card-badge-bg, var(--accent, #ffab40));
+    --_badge-fg: var(--drink-card-badge-fg, #3e2723);
+    --_radius: var(--drink-card-radius, 8px);
+    display: block;
+  }
+  :host([hidden]) { display: none; }
+
+  .card {
+    position: relative;
+    box-sizing: border-box;
+    height: 100%;
+    margin: 0;
+    padding: 20px;
+    background: var(--_bg);
+    border-radius: var(--_radius);
+    box-shadow: 0 2px 5px rgb(0 0 0 / 0.1);
+    text-align: center;
+  }
+
+  h3 {
+    margin: 0 0 10px;
+    font-size: 1.17em;
+    color: var(--_accent);
