@@ -0,0 +1,172 @@
+/**
+ * <drink-card> — reusable menu card with an encapsulated layout.
+ *
+ * Attributes (all reactive, so the page can change them at any time):
+ *   heading       Drink name shown as the card title.
+ *   description   Short blurb under the title.
+ *   href          Destination of the action link.
+ *   action-label  Text of the action link (default: "View Details").
+ *   limited       Boolean. When present, shows the "Limited" badge.
+ *   badge-label   Optional custom badge text (default: "Limited").
+ *
+ * Styles live in a Shadow DOM, so global page CSS cannot leak into the card
+ * and the card's CSS cannot leak out. Theme colors are picked up through the
+ * page's CSS custom properties (--primary, --accent, --text), with fallbacks.
+ *
+ * Toggle the badge from the page:
+ *   card.limited = true;            // or card.setAttribute('limited', '')
+ *   card.limited = false;           // or card.removeAttribute('limited')
+ */
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <style>
+    :host {
+      display: block;
+      font: inherit;
+      color: var(--text, #3e2723);
+    }
+
+    :host([hidden]) {
+      display: none;
+    }
+
+    .card {
+      position: relative;
+      box-sizing: border-box;
+      height: 100%;
+      display: flex;
+      flex-direction: column;
+      align-items: center;
+      background: #fff;
+      padding: 20px;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+    }
+
+    .badge {
+      position: absolute;
+      top: 12px;
+      right: 12px;
+      padding: 2px 10px;
+      border-radius: 999px;
+      background: var(--accent, #ffab40);
+      color: var(--text, #3e2723);
+      font-size: 0.75rem;
+      font-weight: 700;
+      letter-spacing: 0.5px;
+      text-transform: uppercase;
+      line-height: 1.6;
+    }
+
+    [hidden] {
+      display: none !important;
+    }
+
+    h3 {
+      margin: 0 0 10px;
+      font-size: 1.17em;
+      color: var(--primary, #4e342e);
+    }
+
+    p {
+      margin: 0;
+      flex: 1;
+    }
+
+    .btn {
+      display: inline-block;
+      background: var(--primary, #4e342e);
+      color: #fff;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+
+    .btn:hover,
+    .btn:focus-visible {
+      background: #3e2723;
+    }
+
+    .btn:focus-visible {
+      outline: 2px solid var(--accent, #ffab40);
+      outline-offset: 2px;
+    }
+  </style>
+  <article class="card" part="card">
+    <span class="badge" part="badge" hidden></span>
+    <h3 part="heading"></h3>
+    <p part="description"></p>
+    <a class="btn" part="action"></a>
+  </article>
+`;
+
+class DrinkCard extends HTMLElement {
+  static get observedAttributes() {
+    return ['heading', 'description', 'href', 'action-label', 'limited', 'badge-label'];
+  }
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.appendChild(template.content.cloneNode(true));
+    this._els = {
+      badge: root.querySelector('.badge'),
+      heading: root.querySelector('h3'),
+      description: root.querySelector('p'),
+      action: root.querySelector('a'),
+    };
+  }
+
+  connectedCallback() {
+    this._render();
+  }
+
+  attributeChangedCallback() {
+    this._render();
+  }
+
+  get limited() {
+    return this.hasAttribute('limited');
+  }
+
+  set limited(value) {
+    this.toggleAttribute('limited', Boolean(value));
+  }
+
+  _render() {
+    const { badge, heading, description, action } = this._els;
+    const title = this.getAttribute('heading') || '';
+
+    // textContent (never innerHTML) so page-supplied values can't inject markup.
+    heading.textContent = title;
+    description.textContent = this.getAttribute('description') || '';
+
+    badge.textContent = this.getAttribute('badge-label') || 'Limited';
+    badge.hidden = !this.limited;
+
+    const href = this.getAttribute('href');
+    action.textContent = this.getAttribute('action-label') || 'View Details';
+    action.hidden = !href;
+    if (href) {
+      action.setAttribute('href', href);
+    } else {
+      action.removeAttribute('href');
+    }
+    // Give repeated "View Details" links a distinct accessible name.
+    if (title) {
+      action.setAttribute('aria-label', `${action.textContent}: ${title}`);
+    } else {
+      action.removeAttribute('aria-label');
+    }
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
+
+export { DrinkCard };
