+      const strengths = [
+        { name: 'Mild', description: 'Light and bright, with gentle citrus and floral notes.' },
+        { name: 'Medium', description: 'Balanced and smooth, with caramel sweetness.' },
+        { name: 'Bold', description: 'Full-bodied and rich, with dark chocolate depth.' },
+        { name: 'Extra Bold', description: 'Intense and smoky — maximum flavor, maximum kick.' }
