+      var labelsEl = document.getElementById('strength-labels');
+      var max = strengths.length - 1;
+      var labelButtons = [];
+
+      strengths.forEach(function (s, i) {
+        var pct = (i / max) * 100 + '%';
+
+        var tick = document.createElement('span');
+        tick.style.left = pct;
+        ticksEl.appendChild(tick);
