new file mode 100644
index 0000000..037de07
--- /dev/null
+++ b/src/lib/smsOtp.ts
@@ -0,0 +1,135 @@
+import { createHash, randomBytes, randomInt, timingSafeEqual } from 'node:crypto';
+
+/**
+ * In-memory SMS one-time passcode store.
+ *
+ * This is suitable for a single-instance deployment / demo. In production,
+ * persist challenges in a shared store (Redis, database) and plug a real SMS
+ * provider into `deliverSms`.
+ */
+
+export const OTP_LENGTH = 6;
+const OTP_TTL_MS = 5 * 60 * 1000;
+export const RESEND_COOLDOWN_MS = 30 * 1000;
+const MAX_ATTEMPTS = 5;
+
+interface Challenge {
+  phone: string;
+  codeHash: Buffer;
+  expiresAt: number;
+  attempts: number;
+}
+
+const challenges = new Map<string, Challenge>();
+const lastSentByPhone = new Map<string, number>();
+
+const hash = (value: string) => createHash('sha256').update(value).digest();
+
+function sweep(now = Date.now()) {
+  for (const [id, c] of challenges) if (c.expiresAt <= now) challenges.delete(id);
+  for (const [p, sentAt] of lastSentByPhone) if (now - sentAt > RESEND_COOLDOWN_MS) lastSentByPhone.delete(p);
+}
+
+/** Normalise user input to E.164 (`+` followed by 8–15 digits). Returns null if invalid. */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  const trimmed = input.trim();
+  const compact = trimmed.replace(/[\s().-]/g, '');
+  const e164 = compact.startsWith('00') ? `+${compact.slice(2)}` : compact;
+  return /^\+[1-9]\d{7,14}$/.test(e164) ? e164 : null;
+}
+
+export function maskPhone(phone: string): string {
+  return `${phone.slice(0, 3)}${'•'.repeat(Math.max(0, phone.length - 5))}${phone.slice(-2)}`;
+}
+
+/**
+ * Build an origin-bound SMS body. The last line must be `@<host> #<code>` so that
+ * the WebOTP API and `autocomplete="one-time-code"` autofill only offer the code
+ * on the matching domain.
+ */
+export function formatSms(code: string, domain: string): string {
+  return `Your DevTools Times verification code is ${code}.\n\n@${domain} #${code}`;
+}
+
+async function deliverSms(phone: string, body: string) {
+  // TODO: Replace with a real SMS provider integration (Twilio, Vonage, SNS, ...).
+  console.info(`[sms-otp] SMS to ${maskPhone(phone)}:\n${body}`);
+}
+
+export type StartResult =
+  | { ok: true; verificationId: string; expiresInSeconds: number; resendAfterSeconds: number }
+  | { ok: false; status: number; error: string; retryAfterSeconds?: number };
+
+export async function startVerification(phone: string, domain: string): Promise<StartResult> {
+  const now = Date.now();
+  sweep(now);
+
+  const lastSent = lastSentByPhone.get(phone);
+  if (lastSent && now - lastSent < RESEND_COOLDOWN_MS) {
+    const retryAfterSeconds = Math.ceil((RESEND_COOLDOWN_MS - (now - lastSent)) / 1000);
+    return {
+      ok: false,
+      status: 429,
+      error: `Please wait ${retryAfterSeconds} seconds before requesting another code.`,
+      retryAfterSeconds,
+    };
+  }
+
+  // Invalidate any outstanding challenge for this phone number.
+  for (const [id, c] of challenges) if (c.phone === phone) challenges.delete(id);
+
+  const code = randomInt(0, 10 ** OTP_LENGTH).toString().padStart(OTP_LENGTH, '0');
+  const verificationId = randomBytes(18).toString('base64url');
+  challenges.set(verificationId, {
+    phone,
+    codeHash: hash(code),
+    expiresAt: now + OTP_TTL_MS,
+    attempts: 0,
+  });
+  lastSentByPhone.set(phone, now);
+
+  await deliverSms(phone, formatSms(code, domain));
+
+  return {
+    ok: true,
+    verificationId,
+    expiresInSeconds: OTP_TTL_MS / 1000,
+    resendAfterSeconds: RESEND_COOLDOWN_MS / 1000,
+  };
+}
+
+export type CheckResult =
+  | { ok: true; phone: string }
+  | { ok: false; status: number; error: string };
+
+export function checkVerification(verificationId: unknown, code: unknown): CheckResult {
+  sweep();
+  if (typeof verificationId !== 'string' || typeof code !== 'string') {
+    return { ok: false, status: 400, error: 'Missing verification code.' };
+  }
+  const challenge = challenges.get(verificationId);
+  if (!challenge) {
+    return { ok: false, status: 410, error: 'This code has expired. Request a new code.' };
+  }
+  if (!new RegExp(`^\\d{${OTP_LENGTH}}$`).test(code)) {
+    return { ok: false, status: 400, error: `Enter the ${OTP_LENGTH}-digit code.` };
+  }
+
+  challenge.attempts += 1;
+  if (!timingSafeEqual(hash(code), challenge.codeHash)) {
+    const remaining = MAX_ATTEMPTS - challenge.attempts;
+    if (remaining <= 0) {
+      challenges.delete(verificationId);
+      return { ok: false, status: 429, error: 'Too many incorrect attempts. Request a new code.' };
+    }
+    return {
+      ok: false,
+      status: 400,
+      error: `That code is incorrect. ${remaining} ${remaining === 1 ? 'attempt' : 'attempts'} left.`,
+    };
+  }
+
+  challenges.delete(verificationId);
+  return { ok: true, phone: challenge.phone };
+}
