+import type { APIRoute } from 'astro';
+import { maskPhone, normalizePhone, startVerification } from '../../../lib/smsOtp';
+
+const json = (body: unknown, status = 200, headers: Record<string, string> = {}) =>
+  new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+
+export const POST: APIRoute = async ({ request }) => {
+  let payload: { phone?: unknown };
+  try {
+    payload = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const phone = normalizePhone(payload.phone);
+  if (!phone) {
+    return json(
+      { error: 'Enter a valid phone number including the country code, for example +1 555 123 4567.' },
+      400,
+    );
+  }
+
+  // The SMS must be bound to the host the user is on (no scheme, port or path).
+  const domain = import.meta.env.SMS_OTP_DOMAIN || new URL(request.url).hostname;
+  const result = await startVerification(phone, domain);
+
+  if (!result.ok) {
+    return json(
+      { error: result.error, retryAfterSeconds: result.retryAfterSeconds },
+      result.status,
+      result.retryAfterSeconds ? { 'Retry-After': String(result.retryAfterSeconds) } : {},
+    );
+  }
+
+  return json({
+    verificationId: result.verificationId,
+    maskedPhone: maskPhone(phone),
+    expiresInSeconds: result.expiresInSeconds,
+    resendAfterSeconds: result.resendAfterSeconds,
+  });
+};
