@@ -0,0 +1,106 @@
+import { createHash, randomInt, timingSafeEqual } from 'node:crypto';
+
+/** Length of the numeric one-time passcode. */
+export const OTP_LENGTH = 6;
+/** How long a passcode stays valid. */
+export const OTP_TTL_MS = 5 * 60 * 1000;
+/** Minimum wait between two SMS sends for the same session. */
+export const RESEND_COOLDOWN_MS = 30 * 1000;
+/** Max wrong guesses before the code is invalidated. */
+export const MAX_ATTEMPTS = 5;
+/** How long a successful verification may be used to register. */
+export const VERIFIED_TTL_MS = 15 * 60 * 1000;
+
+export const SESSION_KEY_PENDING = 'phoneOtp';
+export const SESSION_KEY_VERIFIED = 'phoneVerified';
+
+export interface PendingOtp {
+  phone: string;
+  codeHash: string;
+  expiresAt: number;
+  sentAt: number;
+  attempts: number;
+}
+
+export interface VerifiedPhone {
+  phone: string;
+  verifiedAt: number;
+}
+
+/**
+ * Normalises user input to E.164 (`+` followed by 8–15 digits).
+ * Accepts spaces, dashes, dots and parentheses; a leading `00` is treated as `+`.
+ * Returns `null` when the number is not plausibly valid.
+ */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  let s = input.trim().replace(/[\s().-]/g, '');
+  if (s.startsWith('00')) s = '+' + s.slice(2);
+  if (!/^\+[1-9]\d{7,14}$/.test(s)) return null;
+  return s;
+}
+
+/** Masks all but the last 2 digits, e.g. `+1 ••• ••• ••42`. */
+export function maskPhone(phone: string): string {
+  return phone.slice(0, -2).replace(/\d/g, '•').replace(/^\+•/, '+') + phone.slice(-2);
+}
+
+export function generateCode(): string {
+  return randomInt(0, 10 ** OTP_LENGTH).toString().padStart(OTP_LENGTH, '0');
+}
+
+export function hashCode(code: string, phone: string): string {
+  return createHash('sha256').update(`${phone}:${code}`).digest('hex');
+}
+
+export function codesMatch(code: string, phone: string, expectedHash: string): boolean {
+  const a = Buffer.from(hashCode(code, phone), 'hex');
+  const b = Buffer.from(expectedHash, 'hex');
+  return a.length === b.length && timingSafeEqual(a, b);
+}
+
+/**
+ * Builds an SMS body compatible with the WebOTP API / origin-bound one-time codes:
+ * the last line must be `@<host> #<code>` so supporting browsers can offer
+ * automatic extraction and the code is bound to this origin.
+ * See https://wicg.github.io/sms-one-time-codes/
+ */
+export function buildSmsBody(code: string, host: string): string {
+  return `${code} is your DevTools Times verification code. It expires in ${Math.round(
+    OTP_TTL_MS / 60000,
+  )} minutes.\n\n@${host} #${code}`;
+}
+
+/**
+ * Delivers an SMS. Uses Twilio when credentials are configured, otherwise logs the
+ * message to the server console (development fallback).
+ */
+export async function sendSms(to: string, body: string): Promise<void> {
+  const sid = process.env.TWILIO_ACCOUNT_SID;
+  const token = process.env.TWILIO_AUTH_TOKEN;
+  const from = process.env.TWILIO_FROM_NUMBER;
+
+  if (sid && token && from) {
+    const res = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`, {
+      method: 'POST',
+      headers: {
+        Authorization: 'Basic ' + Buffer.from(`${sid}:${token}`).toString('base64'),
+        'Content-Type': 'application/x-www-form-urlencoded',
+      },
+      body: new URLSearchParams({ To: to, From: from, Body: body }),
+    });
+    if (!res.ok) {
+      throw new Error(`SMS provider responded with ${res.status}`);
+    }
+    return;
+  }
+
+  console.info(`[sms:dev] to=${maskPhone(to)}\n${body}`);
+}
+
+export function json(data: unknown, status = 200, headers: Record<string, string> = {}): Response {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+}
