@@ -0,0 +1,80 @@
+import type { APIRoute } from 'astro';
+import {
+  OTP_LENGTH,
+  OTP_TTL_MS,
+  RESEND_COOLDOWN_MS,
+  SESSION_KEY_PENDING,
+  SESSION_KEY_VERIFIED,
+  buildSmsBody,
+  generateCode,
+  hashCode,
+  json,
+  maskPhone,
+  normalizePhone,
+  sendSms,
+  type PendingOtp,
+} from '../../../lib/phoneVerification';
+
+export const prerender = false;
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return json({ error: 'SESSION_UNAVAILABLE' }, 500);
+
+  let body: { phone?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'INVALID_REQUEST', message: 'Request body must be JSON.' }, 400);
+  }
+
+  const phone = normalizePhone(body.phone);
+  if (!phone) {
+    return json(
+      {
+        error: 'INVALID_PHONE',
+        message: 'Enter a valid phone number including the country code, e.g. +1 555 123 4567.',
+      },
+      400,
+    );
+  }
+
+  const now = Date.now();
+  const existing = (await session.get(SESSION_KEY_PENDING)) as PendingOtp | undefined;
+  if (existing && now - existing.sentAt < RESEND_COOLDOWN_MS) {
+    const retryAfter = Math.ceil((RESEND_COOLDOWN_MS - (now - existing.sentAt)) / 1000);
+    return json(
+      { error: 'RATE_LIMITED', message: `Please wait ${retryAfter}s before requesting another code.`, retryAfter },
+      429,
+      { 'Retry-After': String(retryAfter) },
+    );
+  }
+
+  const code = generateCode();
+  const host = process.env.SMS_OTP_HOST || url.hostname;
+
+  try {
+    await sendSms(phone, buildSmsBody(code, host));
+  } catch (err) {
+    console.error('[phone] SMS delivery failed', err);
+    return json({ error: 'SMS_FAILED', message: 'We could not send a text message. Please try again.' }, 502);
+  }
+
+  const pending: PendingOtp = {
+    phone,
+    codeHash: hashCode(code, phone),
+    expiresAt: now + OTP_TTL_MS,
+    sentAt: now,
+    attempts: 0,
+  };
+  session.set(SESSION_KEY_PENDING, pending);
+  session.delete(SESSION_KEY_VERIFIED);
+
+  return json({
+    ok: true,
+    phone,
+    maskedPhone: maskPhone(phone),
+    codeLength: OTP_LENGTH,
+    expiresIn: Math.round(OTP_TTL_MS / 1000),
+    resendIn: Math.round(RESEND_COOLDOWN_MS / 1000),
+  });
+};
