@@ -0,0 +1,66 @@
+import type { APIRoute } from 'astro';
+import {
+  MAX_ATTEMPTS,
+  OTP_LENGTH,
+  SESSION_KEY_PENDING,
+  SESSION_KEY_VERIFIED,
+  codesMatch,
+  json,
+  type PendingOtp,
+  type VerifiedPhone,
+} from '../../../lib/phoneVerification';
+
+export const prerender = false;
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) return json({ error: 'SESSION_UNAVAILABLE' }, 500);
+
+  let body: { code?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'INVALID_REQUEST', message: 'Request body must be JSON.' }, 400);
+  }
+
+  const code = typeof body.code === 'string' ? body.code.replace(/\D/g, '') : '';
+  if (code.length !== OTP_LENGTH) {
+    return json({ error: 'INVALID_CODE', message: `Enter the ${OTP_LENGTH}-digit code.` }, 400);
+  }
+
+  const pending = (await session.get(SESSION_KEY_PENDING)) as PendingOtp | undefined;
+  if (!pending) {
+    return json({ error: 'NO_PENDING_CODE', message: 'Request a new code to continue.' }, 400);
+  }
+
+  if (Date.now() > pending.expiresAt) {
+    session.delete(SESSION_KEY_PENDING);
+    return json({ error: 'CODE_EXPIRED', message: 'This code has expired. Request a new one.' }, 410);
+  }
+
+  if (!codesMatch(code, pending.phone, pending.codeHash)) {
+    pending.attempts += 1;
+    const remaining = MAX_ATTEMPTS - pending.attempts;
+    if (remaining <= 0) {
+      session.delete(SESSION_KEY_PENDING);
+      return json(
+        { error: 'TOO_MANY_ATTEMPTS', message: 'Too many incorrect attempts. Request a new code.' },
+        429,
+      );
+    }
+    session.set(SESSION_KEY_PENDING, pending);
+    return json(
+      {
+        error: 'WRONG_CODE',
+        message: `That code is incorrect. ${remaining} attempt${remaining === 1 ? '' : 's'} left.`,
+        attemptsRemaining: remaining,
+      },
+      400,
+    );
+  }
+
+  session.delete(SESSION_KEY_PENDING);
+  const verified: VerifiedPhone = { phone: pending.phone, verifiedAt: Date.now() };
+  session.set(SESSION_KEY_VERIFIED, verified);
+
+  return json({ ok: true, phone: pending.phone });
+};
