+import type { APIRoute } from 'astro';
+import {
+  SESSION_KEY_VERIFIED,
+  VERIFIED_TTL_MS,
+  json,
+  type VerifiedPhone,
+} from '../../lib/phoneVerification';
+
+export const prerender = false;
+
+const UPSTREAM_REGISTER_URL =
+  'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/register';
+
+/**
+ * Registers a user only after their phone number has been verified via SMS OTP
+ * in the current session, then forwards the request to the upstream service.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) return json({ error: 'SESSION_UNAVAILABLE' }, 500);
+
+  let body: { username?: unknown; password?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'INVALID_REQUEST', message: 'Request body must be JSON.' }, 400);
+  }
+
+  const verified = (await session.get(SESSION_KEY_VERIFIED)) as VerifiedPhone | undefined;
+  if (!verified || Date.now() - verified.verifiedAt > VERIFIED_TTL_MS) {
+    session.delete(SESSION_KEY_VERIFIED);
+    return json(
+      { error: 'PHONE_NOT_VERIFIED', message: 'Please verify your phone number before signing up.' },
+      403,
+    );
+  }
+
+  const { username, password } = body;
+  if (typeof username !== 'string' || typeof password !== 'string') {
+    return json({ error: 'INVALID_REQUEST', message: 'Username and password are required.' }, 400);
+  }
+
+  let upstream: Response;
+  try {
+    upstream = await fetch(UPSTREAM_REGISTER_URL, {
+      method: 'POST',
