+/**
+ * <drink-card> — an encapsulated Seasonal Favorites card.
+ *
+ * Theming (inherited custom properties — these cross the shadow boundary):
+ *   Site tokens read automatically: --primary, --secondary, --accent, --text, --light
+ *   Component overrides (set on any ancestor or on the card itself):
+ *     --drink-card-bg, --drink-card-fg, --drink-card-heading, --drink-card-accent,
+ *     --drink-card-radius, --drink-card-shadow, --drink-card-padding,
+ *     --drink-card-media-ratio
+ *
+ * Variants (host attribute):  variant="classic" (default) | "featured" | "limited"
+ * Optional badge text:        badge="New"
+ *
+ * Slots:
+ *   media   — an <img> (or <picture>) for the drink photo
+ *   title   — the drink name (e.g. <h3>)
+ *   (default) — description copy
+ *   price   — optional price / size tag
+ *   action  — call-to-action link(s)
+ *
+ * Parts (style with drink-card::part(name)):
+ *   surface, media, badge, content, footer
+ *
+ * Internal styles use cascade layers, lowest → highest priority:
+ *   reset, tokens, base, layout, variants, states
+ * Layout responds to the card's own inline size via a named container ("drink-card").
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(/* css */ `
+  @layer reset, tokens, base, layout, variants, states;
+
+  /* ── reset: neutralise UA defaults inside the shadow tree only ── */
+  @layer reset {
+    *, *::before, *::after { box-sizing: border-box; }
+    [hidden] { display: none !important; }
+  }
+
+  /* ── tokens: private aliases of public props, falling back to site theme ── */
+  @layer tokens {
+    :host {
+      /* Public props are never seeded on :host so they stay overridable from any ancestor. */
+      --_bg: var(--drink-card-bg, white);
+      --_fg: var(--drink-card-fg, var(--text, #3e2723));
+      --_heading: var(--drink-card-heading, var(--primary, #4e342e));
+      --_accent: var(--drink-card-accent, var(--accent, #ffab40));
+      --_muted: var(--secondary, #d7ccc8);
+      --_radius: var(--drink-card-radius, 8px);
+      --_shadow: var(--drink-card-shadow, 0 2px 5px rgb(0 0 0 / 0.1));
+      --_pad: var(--drink-card-padding, 20px);
+      --_ratio: var(--drink-card-media-ratio, 16 / 10);
+      --_border: transparent;
+    }
+  }
+
+  /* ── base: the host box and element defaults ── */
+  @layer base {
+    :host {
+      display: block; /* custom elements default to inline; containment needs a block box */
+      container: drink-card / inline-size;
+      color: var(--_fg);
+    }
+
+    .surface {
+      position: relative;
+      height: 100%;
+      display: grid;
+      background: var(--_bg);
+      border: 2px solid var(--_border);
+      border-radius: var(--_radius);
+      box-shadow: var(--_shadow);
+      overflow: clip;
+      text-align: center;
+    }
+
+    .media {
+      /* Themed placeholder shows if no image is slotted or it fails to load. */
+      background:
+        radial-gradient(circle at 30% 30%, var(--_accent) 0 12%, transparent 13%),
+        linear-gradient(135deg, var(--_heading), var(--_muted));
+      aspect-ratio: var(--_ratio);
+      overflow: hidden;
+    }
+    .media:not(.has-media) { display: none; }
+
+    ::slotted([slot="media"]) {
+      display: block;
+      width: 100%;
+      height: 100%;
+      object-fit: cover;
+    }
+
+    .content {
+      display: flex;
+      flex-direction: column;
+      gap: 0.5rem;
+      padding: var(--_pad);
+    }
+
+    ::slotted([slot="title"]) {
+      margin: 0;
+      color: var(--_heading);
+    }
+    ::slotted(p) { margin: 0; }
+
+    .footer {
+      display: flex;
+      flex-wrap: wrap;
+      align-items: center;
+      justify-content: center;
+      gap: 0.75rem;
+      margin-top: auto;
+      padding-top: 0.5rem;
+    }
+    .footer:not(.has-footer) { display: none; }
+
+    ::slotted([slot="price"]) {
+      font-weight: 700;
+      color: var(--_heading);
+    }
+
+    .badge {
+      position: absolute;
+      inset-block-start: 0.75rem;
+      inset-inline-start: 0.75rem;
+      z-index: 1;
+      padding: 0.2em 0.7em;
+      border-radius: 999px;
+      background: var(--_accent);
+      color: var(--primary, #4e342e);
+      font-size: 0.75rem;
+      font-weight: 700;
+      letter-spacing: 0.05em;
+      text-transform: uppercase;
+    }
+  }
+
+  /* ── layout: respond to the card's own width, not the viewport ── */
+  @layer layout {
+    /* Medium cards: tighten the image so text gets more room. */
+    @container drink-card (min-width: 22rem) {
+      .media { --_ratio: var(--drink-card-media-ratio, 16 / 8); }
+    }
+
+    /* Wide cards: media beside content, left-aligned copy. */
+    @container drink-card (min-width: 36rem) {
+      .surface:has(> .media.has-media) {
+        grid-template-columns: minmax(12rem, 2fr) 3fr;
+      }
+      .surface { text-align: start; }
+      .media { aspect-ratio: auto; height: 100%; min-height: 14rem; }
+      .content { justify-content: center; padding: calc(var(--_pad) * 1.5); }
+      .footer { justify-content: flex-start; }
+      ::slotted([slot="title"]) { font-size: 1.6rem; }
+    }
+
+    /* Very narrow cards: compact spacing. */
+    @container drink-card (max-width: 16rem) {
+      .content { padding: calc(var(--_pad) * 0.6); gap: 0.35rem; }
+      .badge { font-size: 0.65rem; }
+    }
+  }
+
+  /* ── variants: the component adjusts its own outer styling ── */
+  @layer variants {
+    :host([variant="featured"]) {
+      --_border: var(--_accent);
+      --_shadow: var(--drink-card-shadow, 0 8px 24px rgb(78 52 46 / 0.25));
+    }
+
+    :host([variant="limited"]) {
+      --_bg: var(--drink-card-bg, var(--primary, #4e342e));
+      --_fg: var(--drink-card-fg, var(--light, #fafafa));
+      --_heading: var(--drink-card-heading, var(--_accent));
+      --_border: var(--_accent);
+    }
+    :host([variant="limited"]) .surface { border-style: dashed; }
+  }
+
+  /* ── states: interaction feedback (highest internal priority) ── */
+  @layer states {
+    @media (prefers-reduced-motion: no-preference) {
+      .surface { transition: transform 0.2s ease, box-shadow 0.2s ease; }
+      :host(:hover) .surface { transform: translateY(-3px); }
+    }
+    :host(:hover) .surface,
+    :host(:focus-within) .surface {
+      box-shadow: 0 10px 28px rgb(62 39 35 / 0.22);
+    }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = /* html */ `
+  <article class="surface" part="surface">
+    <span class="badge" part="badge" hidden></span>
+    <div class="media" part="media"><slot name="media"></slot></div>
+    <div class="content" part="content">
+      <slot name="title"></slot>
+      <slot></slot>
+      <div class="footer" part="footer">
+        <slot name="price"></slot>
+        <slot name="action"></slot>
+      </div>
+    </div>
+  </article>
+`;
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['badge'];
+
+  #badge;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    root.append(template.content.cloneNode(true));
+    this.#badge = root.querySelector('.badge');
+
+    // Collapse media/footer regions when nothing is projected into them.
+    const media = root.querySelector('.media');
+    const footer = root.querySelector('.footer');
+    const sync = () => {
+      media.classList.toggle('has-media', this.#assigned('media'));
+      footer.classList.toggle('has-footer', this.#assigned('price') || this.#assigned('action'));
+    };
+    root.addEventListener('slotchange', sync);
+    sync();
+  }
+
+  #assigned(name) {
+    return this.shadowRoot.querySelector(`slot[name="${name}"]`).assignedElements().length > 0;
+  }
+
+  attributeChangedCallback(name, _old, value) {
+    if (name === 'badge') {
+      this.#badge.textContent = value ?? '';
+      this.#badge.hidden = !value;
+    }
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
