+    /* Page palette inherits through the shadow boundary; fall back to the
+       coffee defaults if the component is used on a page without them. */
+    --_primary: var(--primary, #4e342e);
+    --_secondary: var(--secondary, #d7ccc8);
+    --_accent: var(--accent, #ffab40);
+    --_text: var(--text, #3e2723);
+    --_light: var(--light, #fafafa);
+
+    /* Public hooks — override these on drink-card from the page. */
+    --_bg: var(--drink-card-bg, white);
+    --_fg: var(--drink-card-fg, var(--_text));
+    --_heading: var(--drink-card-heading, var(--_primary));
+    --_radius: var(--drink-card-radius, 8px);
+    --_shadow: var(--drink-card-shadow, 0 2px 5px rgba(0, 0, 0, 0.1));
+    --_shadow-hover: var(--drink-card-shadow-hover, 0 8px 18px rgba(62, 39, 35, 0.18));
+    --_pad: var(--drink-card-padding, 20px);
+    --_media-ratio: var(--drink-card-media-ratio, 16 / 10);
+    --_badge-bg: var(--drink-card-badge-bg, var(--_accent));
+    --_badge-fg: var(--drink-card-badge-fg, var(--_text));
+    --_btn-bg: var(--drink-card-button-bg, var(--_primary));
+    --_btn-fg: var(--drink-card-button-fg, white);
+    --_btn-bg-hover: var(--drink-card-button-bg-hover, #3e2723);
+    --_accent-edge: transparent;
+  }
+}
+
+/* ---------- base: host box + default look of internals & slotted content ---------- */
+@layer base {
+  /* Outer styling of the element itself. Page rules targeting drink-card
+     beat :host, so the page always has the last word. */
+  :host {
+    display: block;
+    container: drink-card / inline-size;
+    color: var(--_fg);
+    font: inherit;
+    border-radius: var(--_radius);
+    box-shadow: var(--_shadow);
+    background: var(--_bg);
+    overflow: hidden;
+    transition: box-shadow 0.25s ease, transform 0.25s ease;
+  }
+
+  .card {
+    position: relative;
+    height: 100%;
+    border-top: 4px solid var(--_accent-edge);
+    text-align: center;
+  }
+
+  .media {
+    position: relative;
+    aspect-ratio: var(--_media-ratio);
+    background: var(--_secondary);
+    overflow: hidden;
+  }
+
+  .badge {
+    position: absolute;
+    top: 12px;
+    left: 12px;
+    padding: 2px 10px;
+    border-radius: 999px;
+    background: var(--_badge-bg);
+    color: var(--_badge-fg);
+    font-size: 0.75rem;
+    font-weight: 700;
+    letter-spacing: 0.05em;
+    text-transform: uppercase;
+    z-index: 1;
+  }
+
+  .body { padding: var(--_pad); }
+  .title { margin-bottom: 10px; color: var(--_heading); }
+  .description { color: inherit; }
+  .footer { margin-top: 15px; }
+
+  /* Defaults for projected (light DOM) content. ::slotted rules lose to
+     the page's own selectors, so the page can restyle content freely. */
+  ::slotted(img), ::slotted(picture) {
+    display: block;
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+  }
+  ::slotted(h1), ::slotted(h2), ::slotted(h3), ::slotted(h4) {
+    color: inherit;
+    font-size: 1.2rem;
+    line-height: 1.3;
+  }
+  ::slotted(p) { margin: 0; }
+  ::slotted(a) {
+    display: inline-block;
+    background: var(--_btn-bg);
+    color: var(--_btn-fg);
+    padding: 10px 20px;
+    text-decoration: none;
+    border-radius: 5px;
+    transition: background 0.3s;
+  }
+  ::slotted(a:hover) { background: var(--_btn-bg-hover); }
+}
+
+/* ---------- layout: respond to the card's own width, not the viewport ---------- */
+@layer layout {
+  /* Very narrow cards: tighten spacing, drop the photo height. */
+  @container drink-card (max-width: 220px) {
+    .body { padding: calc(var(--_pad) * 0.6); }
+    .media { aspect-ratio: 4 / 3; }
+  }
+
+  /* Wide cards: switch to a side-by-side media/body layout. */
+  @container drink-card (min-width: 480px) {
+    .card {
+      display: grid;
+      grid-template-columns: minmax(200px, 2fr) 3fr;
+      text-align: start;
+    }
+    .media { aspect-ratio: auto; min-height: 100%; }
+    .body {
+      display: flex;
+      flex-direction: column;
+      justify-content: center;
+      padding: calc(var(--_pad) * 1.5);
+    }
+  }
+
+  /* Extra-wide cards: larger type. */
+  @container drink-card (min-width: 760px) {
+    .card { grid-template-columns: 1fr 1fr; }
+    .title { font-size: 1.25em; }
+    .description { font-size: 1.1rem; }
+  }
+}
+
+/* ---------- variants: the host adjusts its own outer styling ---------- */
+@layer variants {
+  :host([variant="featured"]) {
+    grid-column: 1 / -1;          /* span the full grid row */
+    --_accent-edge: var(--_accent);
+    --_shadow: 0 6px 16px rgba(62, 39, 35, 0.16);
+  }
+
+  :host([variant="bold"]) {
+    --_bg: var(--drink-card-bg, var(--_primary));
+    --_fg: var(--drink-card-fg, var(--_secondary));
+    --_heading: var(--drink-card-heading, var(--_accent));
+    --_btn-bg: var(--drink-card-button-bg, var(--_accent));
+    --_btn-fg: var(--drink-card-button-fg, var(--_text));
+    --_btn-bg-hover: var(--drink-card-button-bg-hover, #ffc677);
+  }
+
+  :host([variant="iced"]) {
+    --_bg: var(--drink-card-bg, linear-gradient(180deg, #ffffff 0%, #eef4f7 100%));
+    --_accent-edge: #90a4ae;
+    --_badge-bg: var(--drink-card-badge-bg, #cfe3ec);
+  }
+}
+
+/* ---------- states: interaction & preference overrides (highest tier) ---------- */
+@layer states {
+  :host(:hover), :host(:focus-within) {
+    box-shadow: var(--_shadow-hover);
+    transform: translateY(-2px);
+  }
+  :host(:focus-within) { outline: 2px solid var(--_accent); outline-offset: 2px; }
+
+  @media (prefers-reduced-motion: reduce) {
+    :host, ::slotted(a) { transition: none; }
+    :host(:hover), :host(:focus-within) { transform: none; }
+  }
+}
+`;
+
+const template = document.createElement('template');
+template.innerHTML = /* html */ `
+  <article class="card" part="card">
+    <div class="media" part="media">
+      <span class="badge" part="badge" hidden></span>
+      <slot name="media"></slot>
+    </div>
+    <div class="body" part="body">
+      <div class="title" part="title"><slot name="title"></slot></div>
+      <div class="description" part="description"><slot></slot></div>
+      <div class="footer" part="footer"><slot name="action"></slot></div>
+    </div>
+  </article>
+`;
+
+let sharedSheet = null;
+const supportsAdopted =
+  'adoptedStyleSheets' in Document.prototype && 'replaceSync' in CSSStyleSheet.prototype;
+if (supportsAdopted) {
+  sharedSheet = new CSSStyleSheet();
+  sharedSheet.replaceSync(css);
+}
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['badge'];
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    if (sharedSheet) {
+      root.adoptedStyleSheets = [sharedSheet];
+    } else {
+      const style = document.createElement('style');
+      style.textContent = css;
+      root.append(style);
+    }
+    root.append(template.content.cloneNode(true));
+    this._badge = root.querySelector('.badge');
+    this._media = root.querySelector('.media');
+    this._mediaSlot = root.querySelector('slot[name="media"]');
+    this._mediaSlot.addEventListener('slotchange', () => this._syncMedia());
+  }
+
+  connectedCallback() {
+    this._syncBadge();
+    this._syncMedia();
+  }
+
+  attributeChangedCallback() {
+    this._syncBadge();
+  }
+
+  _syncBadge() {
+    if (!this._badge) return;
+    const text = this.getAttribute('badge');
+    this._badge.textContent = text ?? '';
+    this._badge.hidden = !text;
+  }
+
+  _syncMedia() {
+    // Collapse the media area when no image is projected.
+    const hasMedia = this._mediaSlot.assignedNodes({ flatten: true }).length > 0;
+    this._media.hidden = !hasMedia;
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
+
+export { DrinkCard };
