+        output.replaceChildren();
+        const lines = markdown
+          .split('\n')
+          .map(l => l.trim())
+          .filter(Boolean)
+          .map(l => l.replace(/^([-*•]|\d+\.)\s+/, '').replace(/\*\*(.+?)\*\*/g, '$1').replace(/[*_`]/g, ''));
