+      const tablist = menu.querySelector('[role="tablist"]');
+      const tabs = [...tablist.querySelectorAll('[role="tab"]')];
+      const panelFor = tab => document.getElementById(tab.id.replace(/^tab-/, 'panel-'));
+
+      function select(selected, { scroll = true } = {}) {
+        for (const tab of tabs) {
+          const isSelected = tab === selected;
+          tab.ariaSelected = String(isSelected);
+          tab.toggleAttribute('focusgroupstart', isSelected);
+          const panel = panelFor(tab);
+          if (isSelected) {
+            panel.removeAttribute('hidden');
+            // Make the panel focusable only if it has no focusable content of its own
+            if (panel.querySelector('a, button, input, select, textarea')) panel.removeAttribute('tabindex');
+            else panel.tabIndex = 0;
+          } else {
+            panel.hidden = 'until-found';
+            panel.removeAttribute('tabindex');
+          }
+        }
+        // Scroll only the tab bar (not the page) so the selected tab, plus a peek of its neighbour, is visible
+        if (scroll) selected.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' });
+      }
+
+      // Selection follows focus (arrow keys via focusgroup) and click
+      tablist.addEventListener('focusin', e => {
+        const tab = e.target.closest('[role="tab"]');
+        if (tab && tab.ariaSelected !== 'true') select(tab);
+      });
+      tablist.addEventListener('click', e => {
+        const tab = e.target.closest('[role="tab"]');
+        if (tab) select(tab);
+      });
+
+      // Find-in-page revealing a hidden panel selects its tab
+      for (const tab of tabs) {
+        panelFor(tab).addEventListener('beforematch', () => select(tab));
+      }
