+  <script>
+    (function () {
+      var root = document.getElementById('coffee-menu');
+      if (!root) return;
+
+      var bar = root.querySelector('.tabs__bar');
+      var list = root.querySelector('.tabs__list');
+      var tabs = Array.prototype.slice.call(list.querySelectorAll('[role="tab"]'));
+      var prevBtn = root.querySelector('.tabs__scroll--prev');
+      var nextBtn = root.querySelector('.tabs__scroll--next');
+      var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
+      var EDGE = 48; // keep active tab clear of the fade / arrow buttons
+
+      function behavior() {
+        return reduceMotion.matches ? 'auto' : 'smooth';
+      }
+
+      // Horizontally scroll the tab list (never the page) so a tab is fully visible.
+      function revealTab(tab, instant) {
+        var listRect = list.getBoundingClientRect();
+        var tabRect = tab.getBoundingClientRect();
+        var left = tabRect.left - listRect.left + list.scrollLeft;
+        var right = left + tabRect.width;
+        var viewStart = list.scrollLeft + EDGE;
+        var viewEnd = list.scrollLeft + list.clientWidth - EDGE;
+        var target = null;
+
+        if (left < viewStart) target = left - EDGE;
+        else if (right > viewEnd) target = right - list.clientWidth + EDGE;
+        if (target === null) return;
+
+        list.scrollTo({ left: Math.max(0, target), behavior: instant ? 'auto' : behavior() });
+      }
+
+      function updateOverflow() {
+        var max = list.scrollWidth - list.clientWidth;
+        var overflowing = max > 1;
+        var canPrev = overflowing && list.scrollLeft > 1;
+        var canNext = overflowing && list.scrollLeft < max - 1;
+
+        bar.classList.toggle('fits', !overflowing);
+        bar.classList.toggle('can-scroll-prev', canPrev);
+        bar.classList.toggle('can-scroll-next', canNext);
+        prevBtn.hidden = !canPrev;
+        nextBtn.hidden = !canNext;
+      }
+
+      function selectTab(tab, opts) {
+        opts = opts || {};
+        tabs.forEach(function (t) {
+          var selected = t === tab;
+          t.setAttribute('aria-selected', selected ? 'true' : 'false');
+          t.tabIndex = selected ? 0 : -1;
+          var panel = document.getElementById(t.getAttribute('aria-controls'));
+          if (panel) panel.hidden = !selected;
+        });
+
+        if (opts.focus) tab.focus({ preventScroll: true });
+        revealTab(tab, opts.instant);
+
+        if (opts.updateHash && window.history && history.replaceState) {
+          history.replaceState(null, '', '#' + tab.id.replace(/^tab-/, 'menu-'));
+        }
+      }
+
+      list.addEventListener('click', function (e) {
+        var tab = e.target.closest('[role="tab"]');
+        if (tab) selectTab(tab, { updateHash: true });
+      });
+
+      // WAI-ARIA tabs pattern: automatic activation with arrow / Home / End keys.
+      list.addEventListener('keydown', function (e) {
+        var i = tabs.indexOf(document.activeElement);
+        if (i < 0) return;
+        var next = null;
+
+        switch (e.key) {
+          case 'ArrowRight': next = tabs[(i + 1) % tabs.length]; break;
+          case 'ArrowLeft': next = tabs[(i - 1 + tabs.length) % tabs.length]; break;
+          case 'Home': next = tabs[0]; break;
+          case 'End': next = tabs[tabs.length - 1]; break;
+          default: return;
+        }
+        e.preventDefault();
+        selectTab(next, { focus: true, updateHash: true });
+      });
+
+      function page(direction) {
+        list.scrollBy({ left: direction * list.clientWidth * 0.7, behavior: behavior() });
+      }
+      prevBtn.addEventListener('click', function () { page(-1); });
+      nextBtn.addEventListener('click', function () { page(1); });
+
+      // Translate vertical mouse-wheel into horizontal scrolling when the bar overflows.
+      list.addEventListener('wheel', function (e) {
+        if (Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;
+        var max = list.scrollWidth - list.clientWidth;
+        if (max <= 1) return;
+        var atStart = list.scrollLeft <= 0 && e.deltaY < 0;
+        var atEnd = list.scrollLeft >= max - 1 && e.deltaY > 0;
+        if (atStart || atEnd) return; // let the page scroll once we hit an edge
+        e.preventDefault();
+        list.scrollLeft += e.deltaY;
+      }, { passive: false });
+
+      var ticking = false;
+      list.addEventListener('scroll', function () {
+        if (ticking) return;
+        ticking = true;
+        requestAnimationFrame(function () {
+          ticking = false;
+          updateOverflow();
+        });
+      }, { passive: true });
+
+      function onResize() {
+        updateOverflow();
+        var active = list.querySelector('[aria-selected="true"]');
+        if (active) revealTab(active, true);
+      }
+
+      if ('ResizeObserver' in window) {
+        new ResizeObserver(onResize).observe(list);
+      } else {
+        window.addEventListener('resize', onResize);
+      }
+      if (document.fonts && document.fonts.ready) document.fonts.ready.then(onResize);
+
+      // Deep link support: #menu-espresso opens the Espresso tab.
+      function fromHash() {
+        var m = /^#menu-(.+)$/.exec(location.hash);
+        var tab = m && document.getElementById('tab-' + m[1]);
+        if (tab) selectTab(tab, { instant: true });
+      }
+      window.addEventListener('hashchange', fromHash);
+
+      fromHash();
+      updateOverflow();
+    })();
+  </script>
