new file mode 100644
index 0000000..0e14b54
--- /dev/null
+++ b/src/components/TranslateControl.tsx
@@ -0,0 +1,323 @@
+import { useEffect, useId, useMemo, useRef, useState } from 'react';
+import { LanguageIcon, ArrowRightIcon, ArrowUturnLeftIcon } from '@heroicons/react/24/outline';
+import {
+  collectTextNodes,
+  detectLanguage,
+  getPreferredTarget,
+  getTranslator,
+  isLanguageDetectorSupported,
+  isTranslatorSupported,
+  languageName,
+  languageOptions,
+  normalizeLanguage,
+  setPreferredTarget,
+  translatePreservingWhitespace,
+  translatorAvailability,
+} from '../utils/translation';
+
+interface Props {
+  /** id of the element whose text should be translated. */
+  targetId: string;
+  /** 'full' renders an inline toolbar (article pages); 'compact' an icon button with a popover (teasers). */
+  variant?: 'full' | 'compact';
+  /** Known language of the content. Used when auto-detection is unavailable. */
+  contentLanguage?: string;
+  /** Accessible name for what is being translated, e.g. the headline. */
+  label?: string;
+}
+
+type Support = 'checking' | 'supported' | 'unsupported';
+type Phase = 'idle' | 'working' | 'translated' | 'error';
+
+const AUTO = 'auto';
+const RTL_LANGUAGES = new Set(['ar', 'he']);
+const UNSUPPORTED_NOTE =
+  'On-device translation isn’t supported in this browser. Try a recent desktop version of Chrome or Edge.';
+
+interface Snapshot {
+  texts: Map<Text, string>;
+  lang: string | null;
+  dir: string | null;
+}
+
+export default function TranslateControl({ targetId, variant = 'full', contentLanguage = 'en', label }: Props) {
+  const popoverId = useId();
+  const sourceSelectId = useId();
+  const targetSelectId = useId();
+
+  const [support, setSupport] = useState<Support>('checking');
+  const [canDetect, setCanDetect] = useState(false);
+  const [source, setSource] = useState<string>(AUTO);
+  const [target, setTarget] = useState<string>('es');
+  const [phase, setPhase] = useState<Phase>('idle');
+  const [status, setStatus] = useState('');
+  const [progress, setProgress] = useState<number | null>(null);
+  const [translatedTo, setTranslatedTo] = useState<string | null>(null);
+
+  const snapshot = useRef<Snapshot | null>(null);
+  const abortRef = useRef<AbortController | null>(null);
+
+  // Feature detection must run client-side only (after hydration) to avoid SSR mismatches.
+  useEffect(() => {
+    const supported = isTranslatorSupported();
+    setSupport(supported ? 'supported' : 'unsupported');
+    const detect = isLanguageDetectorSupported();
+    setCanDetect(detect);
+    if (!detect) setSource(normalizeLanguage(contentLanguage) ?? 'en');
+    setTarget(getPreferredTarget(normalizeLanguage(contentLanguage) ?? 'en'));
+    return () => abortRef.current?.abort();
+  }, [contentLanguage]);
+
+  const options = useMemo(() => (support === 'checking' ? [] : languageOptions()), [support]);
+
+  function getRoot() {
+    return document.getElementById(targetId);
+  }
+
+  function takeSnapshot(root: HTMLElement): Snapshot {
+    if (!snapshot.current) {
+      const texts = new Map<Text, string>();
+      for (const node of collectTextNodes(root)) texts.set(node, node.nodeValue ?? '');
+      snapshot.current = { texts, lang: root.getAttribute('lang'), dir: root.getAttribute('dir') };
+    }
+    return snapshot.current;
+  }
+
+  function restoreOriginal() {
+    const root = getRoot();
+    const snap = snapshot.current;
+    if (!root || !snap) return;
+    for (const [node, text] of snap.texts) node.nodeValue = text;
+    snap.lang === null ? root.removeAttribute('lang') : root.setAttribute('lang', snap.lang);
+    snap.dir === null ? root.removeAttribute('dir') : root.setAttribute('dir', snap.dir);
+    root.removeAttribute('aria-busy');
+  }
+
+  function showOriginal() {
+    abortRef.current?.abort();
+    restoreOriginal();
+    setTranslatedTo(null);
+    setProgress(null);
+    setPhase('idle');
+    setStatus('Showing original text.');
+  }
+
+  function fail(message: string) {
+    getRoot()?.removeAttribute('aria-busy');
+    setProgress(null);
+    setPhase('error');
+    setStatus(message);
+  }
+
+  async function translate() {
+    const root = getRoot();
+    if (!root || support !== 'supported') return;
+
+    abortRef.current?.abort();
+    const controller = new AbortController();
+    abortRef.current = controller;
+    const { signal } = controller;
+
+    const snap = takeSnapshot(root);
+    // Always translate from the original text, never from a previous translation.
+    restoreOriginal();
+    setTranslatedTo(null);
+    setPreferredTarget(target);
+    setPhase('working');
+    setProgress(null);
+
+    try {
+      let from = source;
+      if (from === AUTO) {
+        setStatus('Detecting language…');
+        const sample = [...snap.texts.values()].join(' ');
+        from =
+          (await detectLanguage(sample, (p) => setProgress(p))) ??
+          normalizeLanguage(snap.lang ?? root.closest('[lang]')?.getAttribute('lang')) ??
+          normalizeLanguage(contentLanguage) ??
+          'en';
+        if (signal.aborted) return;
+        setProgress(null);
+      }
+
+      if (from === target) {
+        setPhase('idle');
+        setStatus(`This text is already in ${languageName(target)}.`);
+        return;
+      }
+
+      const availability = await translatorAvailability(from, target);
+      if (signal.aborted) return;
+      if (availability === 'unavailable') {
+        fail(`Translating ${languageName(from)} to ${languageName(target)} isn’t available on this device.`);
+        return;
+      }
+      if (availability !== 'available') {
+        setStatus(`Downloading ${languageName(from)} → ${languageName(target)} language pack…`);
+        setProgress(0);
+      }
+
+      const translator = await getTranslator(from, target, (p) => setProgress(p));
+      if (signal.aborted) return;
+
+      const nodes = [...snap.texts.keys()].filter((node) => root.contains(node));
+      root.setAttribute('aria-busy', 'true');
+      setStatus(`Translating to ${languageName(target)}…`);
+      setProgress(0);
+
+      for (let i = 0; i < nodes.length; i++) {
+        const node = nodes[i];
+        const translated = await translatePreservingWhitespace(translator, snap.texts.get(node) ?? '', signal);
+        if (signal.aborted) return;
+        node.nodeValue = translated;
+        // Mark the container with the target language as soon as text changes,
+        // so assistive tech pronounces it correctly.
+        if (i === 0) {
+          root.setAttribute('lang', target);
+          root.setAttribute('dir', RTL_LANGUAGES.has(target) ? 'rtl' : 'ltr');
+        }
+        setProgress((i + 1) / nodes.length);
+      }
+
+      root.removeAttribute('aria-busy');
+      setProgress(null);
+      setTranslatedTo(target);
+      setPhase('translated');
+      setStatus(`Translated from ${languageName(from)} to ${languageName(target)} on your device.`);
+    } catch (error) {
+      if (signal.aborted || (error instanceof DOMException && error.name === 'AbortError')) return;
+      restoreOriginal();
+      if (error instanceof DOMException && error.name === 'NotAllowedError') {
+        fail('Click “Translate” again to download the language pack.');
+      } else if (error instanceof DOMException && error.name === 'QuotaExceededError') {
+        fail('This text is too long to translate on this device.');
+      } else {
+        console.error('Translation failed', error);
+        fail('Translation failed. Please try again.');
+      }
+    }
+  }
+
+  const busy = phase === 'working';
+  const disabled = support !== 'supported' || busy;
+  const percent = progress === null ? null : Math.round(progress * 100);
+
+  const selects = (
+    <>
+      {variant === 'full' && (
+        <>
+          <label htmlFor={sourceSelectId} className="sr-only">
+            Translate from
+          </label>
+          <select
+            id={sourceSelectId}
+            value={source}
+            disabled={disabled}
+            onChange={(e) => setSource(e.target.value)}
+            className="translate-select"
+          >
+            {canDetect && <option value={AUTO}>Detect language</option>}
+            {options.map(({ code, name }) => (
+              <option key={code} value={code}>
+                {name}
+              </option>
+            ))}
+          </select>
+          <ArrowRightIcon aria-hidden="true" className="h-4 w-4 text-gray-400 shrink-0" />
+        </>
+      )}
+      <label htmlFor={targetSelectId} className={variant === 'full' ? 'sr-only' : 'text-xs font-semibold text-gray-700'}>
+        Translate to
+      </label>
+      <select
+        id={targetSelectId}
+        value={target}
+        disabled={disabled}
+        onChange={(e) => setTarget(e.target.value)}
+        className="translate-select"
+      >
+        {options.map(({ code, name }) => (
+          <option key={code} value={code}>
+            {name}
+          </option>
+        ))}
+      </select>
+    </>
+  );
+
+  const actions = (
+    <>
+      <button
+        type="button"
+        onClick={translate}
+        disabled={disabled || translatedTo === target}
+        className="translate-button bg-gray-800 text-white hover:bg-gray-700"
+      >
+        {busy ? 'Translating…' : 'Translate'}
+      </button>
+      {(translatedTo || busy) && (
+        <button type="button" onClick={showOriginal} className="translate-button text-gray-700 hover:bg-gray-100">
+          <ArrowUturnLeftIcon aria-hidden="true" className="h-4 w-4" />
+          Show original
+        </button>
+      )}
+    </>
+  );
+
+  const statusLine = (
+    <div role="status" className="text-xs text-gray-600 min-h-4">
+      {support === 'unsupported' ? UNSUPPORTED_NOTE : status}
+      {busy && percent !== null && (
+        <progress max={100} value={percent} className="translate-progress" aria-label="Translation progress">
+          {percent}%
+        </progress>
+      )}
+    </div>
+  );
+
+  if (variant === 'compact') {
+    return (
+      <div translate="no" data-no-translate>
+        <button
+          type="button"
+          popoverTarget={popoverId}
+          aria-label={label ? `Translate “${label}”` : 'Translate'}
+          title={translatedTo ? `Translated to ${languageName(translatedTo)}` : 'Translate on device'}
+          className="p-1 rounded"
+        >
+          <LanguageIcon className={`h-5 w-5 ${translatedTo ? 'text-amber-400' : 'text-gray-400 hover:text-gray-600'}`} />
+        </button>
+        <div id={popoverId} popover="auto" className="translate-popover">
+          <div className="flex flex-col gap-2">
+            <p className="text-sm font-semibold text-gray-900 flex items-center gap-1">
+              <LanguageIcon aria-hidden="true" className="h-4 w-4" />
+              Translate teaser
+            </p>
+            <div className="flex items-center gap-2">{selects}</div>
+            <div className="flex flex-wrap items-center gap-2">{actions}</div>
+            {statusLine}
+          </div>
+        </div>
+      </div>
+    );
+  }
+
+  return (
+    <section
+      translate="no"
+      data-no-translate
+      aria-label="Translate article"
+      className="flex flex-col gap-2 rounded-md border border-gray-200 bg-gray-50 px-3 py-2 mb-6"
+    >
+      <div className="flex flex-wrap items-center gap-2">
+        <span className="flex items-center gap-1 text-sm font-semibold text-gray-800 mr-1">
+          <LanguageIcon aria-hidden="true" className="h-5 w-5" />
+          Translate
+        </span>
+        {selects}
+        {actions}
+      </div>
+      {statusLine}
+    </section>
+  );
+}
