+/**
+ * Helpers around the browser's built-in, on-device Translator and
+ * LanguageDetector APIs (Chrome / Edge desktop). Everything here is
+ * client-only — never call these during SSR.
+ */
+
+/** Language codes supported by Chrome's Translator implementation. */
+export const TRANSLATOR_LANGUAGES = [
+  'ar', 'bg', 'bn', 'cs', 'da', 'de', 'el', 'en', 'es', 'fi', 'fr', 'he', 'hi',
+  'hr', 'hu', 'id', 'it', 'ja', 'kn', 'ko', 'lt', 'mr', 'nl', 'no', 'pl', 'pt',
+  'ro', 'ru', 'sk', 'sl', 'sv', 'ta', 'te', 'th', 'tr', 'uk', 'vi', 'zh', 'zh-Hant',
+] as const;
+
+const TARGET_STORAGE_KEY = 'devtools-times:translate-target';
+const SAMPLE_LENGTH = 1200;
+
+let displayNames: Intl.DisplayNames | undefined;
+
+/** Human-readable name for a BCP 47 code, in the page's UI language. */
+export function languageName(code: string): string {
+  try {
+    displayNames ??= new Intl.DisplayNames([document.documentElement.lang || 'en'], { type: 'language' });
+    return displayNames.of(code) ?? code;
+  } catch {
+    return code;
+  }
+}
+
+/** Sorted list of `{ code, name }` for building <select> options. */
+export function languageOptions(): { code: string; name: string }[] {
+  return TRANSLATOR_LANGUAGES.map((code) => ({ code, name: languageName(code) })).sort((a, b) =>
+    a.name.localeCompare(b.name),
+  );
+}
+
+export const isTranslatorSupported = () => typeof self !== 'undefined' && 'Translator' in self;
+export const isLanguageDetectorSupported = () => typeof self !== 'undefined' && 'LanguageDetector' in self;
+
+/** Map an arbitrary BCP 47 tag to the closest code the Translator supports. */
+export function normalizeLanguage(tag: string | undefined | null): string | undefined {
+  if (!tag) return undefined;
+  const lower = tag.toLowerCase();
+  if (lower === 'zh-hant' || lower === 'zh-tw' || lower === 'zh-hk' || lower === 'zh-mo') return 'zh-Hant';
+  if (lower === 'nb' || lower === 'nn') return 'no';
+  if (lower === 'iw') return 'he';
+  const base = lower.split('-')[0];
+  return (TRANSLATOR_LANGUAGES as readonly string[]).includes(base) ? base : undefined;
+}
+
+/** Remembered target language, else the reader's browser language, else Spanish. */
+export function getPreferredTarget(sourceHint = 'en'): string {
+  try {
+    const stored = normalizeLanguage(localStorage.getItem(TARGET_STORAGE_KEY));
+    if (stored) return stored;
+  } catch {
+    /* storage unavailable */
+  }
+  for (const tag of navigator.languages ?? [navigator.language]) {
+    const code = normalizeLanguage(tag);
+    if (code && code !== sourceHint) return code;
+  }
+  return sourceHint === 'es' ? 'en' : 'es';
+}
+
+export function setPreferredTarget(code: string) {
+  try {
+    localStorage.setItem(TARGET_STORAGE_KEY, code);
+  } catch {
+    /* storage unavailable */
+  }
+}
+
+type ProgressCallback = (fraction: number) => void;
+
+function monitorWith(onProgress?: ProgressCallback) {
+  return (m: AICreateMonitor) => {
+    m.addEventListener('downloadprogress', (e) => onProgress?.(e.loaded));
+  };
+}
+
+// Translator instances are shared across every island on the page (they all
+// import this module), so a language pair is only created/downloaded once.
+const translators = new Map<string, Promise<TranslatorInstance>>();
+
+export async function translatorAvailability(sourceLanguage: string, targetLanguage: string): Promise<AIAvailability> {
+  if (!globalThis.Translator) return 'unavailable';
+  return globalThis.Translator.availability({ sourceLanguage, targetLanguage });
+}
+
+/**
+ * Must be called from (or shortly after) a user gesture when the pair is
+ * 'downloadable' / 'downloading'. Identical options are passed to
+ * availability() and create().
+ */
+export function getTranslator(
+  sourceLanguage: string,
+  targetLanguage: string,
+  onProgress?: ProgressCallback,
+): Promise<TranslatorInstance> {
+  const key = `${sourceLanguage}→${targetLanguage}`;
+  let pending = translators.get(key);
+  if (!pending) {
+    if (!globalThis.Translator) return Promise.reject(new Error('Translator API not supported'));
+    pending = globalThis.Translator.create({ sourceLanguage, targetLanguage, monitor: monitorWith(onProgress) });
+    pending.catch(() => translators.delete(key));
+    translators.set(key, pending);
+  }
+  return pending;
+}
+
+let detector: Promise<LanguageDetectorInstance> | undefined;
+
+/**
+ * Detect the language of `text` on-device. Returns undefined when the API is
+ * missing, unavailable, or not confident enough — callers fall back to the
+ * document language.
+ */
+export async function detectLanguage(text: string, onProgress?: ProgressCallback): Promise<string | undefined> {
+  const api = globalThis.LanguageDetector;
+  if (!api) return undefined;
+  try {
+    if (!detector) {
+      if ((await api.availability()) === 'unavailable') return undefined;
+      detector = api.create({ monitor: monitorWith(onProgress) });
+      detector.catch(() => (detector = undefined));
+    }
+    const [top] = await (await detector).detect(text.slice(0, SAMPLE_LENGTH));
+    if (!top || top.confidence < 0.5 || top.detectedLanguage === 'und') return undefined;
+    return normalizeLanguage(top.detectedLanguage);
+  } catch {
+    return undefined;
+  }
+}
+
+/* ------------------------------------------------------------------------ */
+/* DOM text translation                                                      */
+/* ------------------------------------------------------------------------ */
+
+const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'CODE', 'PRE', 'TEXTAREA', 'SVG']);
+
+/**
+ * Collect the translatable text nodes inside `root`. Translating per text
+ * node keeps links, emphasis, and other inline markup intact.
+ */
+export function collectTextNodes(root: Element): Text[] {
+  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      const parent = node.parentElement;
+      if (!parent || !node.nodeValue?.trim()) return NodeFilter.FILTER_REJECT;
+      if (SKIP_TAGS.has(parent.tagName.toUpperCase())) return NodeFilter.FILTER_REJECT;
+      if (parent.closest('[translate="no"], [data-no-translate]')) return NodeFilter.FILTER_REJECT;
+      return NodeFilter.FILTER_ACCEPT;
+    },
+  });
+  const nodes: Text[] = [];
+  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
+  return nodes;
+}
+
+/** Translate a string, preserving its leading/trailing whitespace. */
+export async function translatePreservingWhitespace(
+  translator: TranslatorInstance,
+  text: string,
+  signal?: AbortSignal,
+): Promise<string> {
+  const match = text.match(/^(\s*)([\s\S]*?)(\s*)$/);
+  if (!match || !match[2]) return text;
+  const translated = await translator.translate(match[2], { signal });
+  return match[1] + translated + match[3];
+}

