+import React, { useCallback, useEffect, useRef, useState } from 'react';
+import { LanguageIcon, XMarkIcon } from '@heroicons/react/24/outline';
+import {
+  SUPPORTED_LANGUAGES,
+  detectSourceLanguage,
+  getAvailability,
+  getSavedTarget,
+  getTranslator,
+  isTranslationSupported,
+  languageName,
+  restoreOriginal,
+  saveTarget,
+  translatePage,
+} from '../utils/translation';
+
+type Status =
+  | { kind: 'idle' }
+  | { kind: 'downloading'; progress: number }
+  | { kind: 'translating'; done: number; total: number }
+  | { kind: 'translated' }
+  | { kind: 'error'; message: string };
+
+export default function TranslateButton() {
+  const [supported, setSupported] = useState<boolean | null>(null);
+  const [open, setOpen] = useState(false);
+  const [sourceLang, setSourceLang] = useState('en');
+  const [targetLang, setTargetLang] = useState<string | null>(null);
+  const [status, setStatus] = useState<Status>({ kind: 'idle' });
+  const abortRef = useRef<AbortController | null>(null);
+  const containerRef = useRef<HTMLDivElement>(null);
+
+  const run = useCallback(async (source: string, target: string | null, persist = true) => {
+    abortRef.current?.abort();
+    restoreOriginal();
+    setTargetLang(target);
+    if (persist) saveTarget(target);
+
+    if (!target || target === source) {
+      setStatus({ kind: 'idle' });
+      return;
+    }
+
+    const controller = new AbortController();
+    abortRef.current = controller;
+    try {
+      const availability = await getAvailability(source, target);
+      if (availability === 'unavailable') {
+        throw new Error(
+          `Translating from ${languageName(source, 'en')} to ${languageName(target, 'en')} isn't available on this device.`,
+        );
+      }
+      if (availability !== 'available') setStatus({ kind: 'downloading', progress: 0 });
+      const translator = await getTranslator(source, target, (progress) => {
+        if (!controller.signal.aborted) setStatus({ kind: 'downloading', progress });
+      });
+      if (controller.signal.aborted) return;
+      await translatePage(translator, target, {
+        signal: controller.signal,
+        onProgress: (done, total) => setStatus({ kind: 'translating', done, total }),
+      });
+      if (!controller.signal.aborted) setStatus({ kind: 'translated' });
+    } catch (err) {
+      if (controller.signal.aborted) return;
+      console.error('On-device translation failed:', err);
+      restoreOriginal();
+      setStatus({
+        kind: 'error',
+        message:
+          err instanceof Error && err.message
+            ? err.message
+            : 'Translation failed. Please try again.',
+      });
+    }
+  }, []);
+
+  // Detect support + source language, then re-apply a saved preference when the
+  // model is already on the device (no download → no user gesture needed).
+  useEffect(() => {
+    const ok = isTranslationSupported();
+    setSupported(ok);
+    if (!ok) return;
+    let cancelled = false;
+    (async () => {
+      const source = await detectSourceLanguage();
+      if (cancelled) return;
+      setSourceLang(source);
+      const saved = getSavedTarget();
+      if (!saved || saved === source) return;
+      setTargetLang(saved);
+      if ((await getAvailability(source, saved)) === 'available' && !cancelled) {
+        run(source, saved, false);
+      }
+    })();
+    return () => {
+      cancelled = true;
+      abortRef.current?.abort();
+    };
+  }, [run]);
+
+  // Close on outside click / Escape.
+  useEffect(() => {
+    if (!open) return;
+    const onPointer = (e: PointerEvent) => {
+      if (!containerRef.current?.contains(e.target as Node)) setOpen(false);
+    };
+    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setOpen(false);
+    document.addEventListener('pointerdown', onPointer);
+    document.addEventListener('keydown', onKey);
+    return () => {
+      document.removeEventListener('pointerdown', onPointer);
+      document.removeEventListener('keydown', onKey);
+    };
+  }, [open]);
+
+  const busy = status.kind === 'downloading' || status.kind === 'translating';
+  const isTranslated = status.kind === 'translated' || status.kind === 'translating';
+  const targets = SUPPORTED_LANGUAGES.filter((l) => l !== sourceLang);
+
+  return (
+    <div ref={containerRef} className="relative">
+      <button
+        type="button"
+        onClick={() => setOpen((o) => !o)}
+        className={`p-1 flex items-center gap-1 hover:text-amber-400 ${isTranslated ? 'text-amber-500' : 'text-gray-600'}`}
+        aria-haspopup="dialog"
+        aria-expanded={open}
+        aria-label="Translate articles"
+        title="Translate articles"
+      >
+        {busy ? (
+          <span className="w-5 h-5 border-2 border-amber-400 border-t-transparent rounded-full animate-spin" />
+        ) : (
+          <LanguageIcon className="h-6 w-6" />
+        )}
+        {targetLang && isTranslated && (
+          <span className="text-xs font-semibold uppercase">{targetLang}</span>
+        )}
+      </button>
+
+      {open && (
+        <div
+          role="dialog"
+          aria-label="Translate articles"
+          className="absolute left-0 top-full mt-2 w-72 bg-white border border-gray-200 rounded-md shadow-lg z-50 p-4 text-sm"
+        >
+          <div className="flex items-start justify-between mb-3">
+            <div>
+              <p className="font-semibold text-gray-900">Translate articles</p>
+              <p className="text-xs text-gray-500">Runs on your device — nothing is sent to a server.</p>
+            </div>
+            <button type="button" onClick={() => setOpen(false)} className="text-gray-400 hover:text-gray-700" aria-label="Close">
+              <XMarkIcon className="h-5 w-5" />
+            </button>
+          </div>
+
+          {supported === false ? (
+            <p className="text-gray-700">
+              Your browser doesn't support on-device translation. Try a recent version of Chrome on desktop.
+            </p>
+          ) : (
+            <>
+              <p className="text-xs text-gray-500 mb-1">
+                From <span className="font-semibold text-gray-700">{languageName(sourceLang, 'en')}</span>
+              </p>
+              <label className="block text-xs text-gray-500 mb-1" htmlFor="translate-target">
+                To
+              </label>
+              <select
+                id="translate-target"
+                className="w-full border border-gray-300 rounded px-2 py-1.5 bg-white text-gray-900 focus:outline-none focus:ring-2 focus:ring-amber-400"
+                value={targetLang && targetLang !== sourceLang ? targetLang : ''}
+                onChange={(e) => run(sourceLang, e.target.value || null)}
+              >
+                <option value="">Original ({languageName(sourceLang)})</option>
+                {targets.map((code) => (
+                  <option key={code} value={code}>
+                    {languageName(code)}
+                    {languageName(code) !== languageName(code, 'en') ? ` — ${languageName(code, 'en')}` : ''}
+                  </option>
+                ))}
+              </select>
+
+              <div className="mt-3 min-h-[1.25rem]" aria-live="polite">
+                {status.kind === 'downloading' && (
+                  <div>
+                    <p className="text-xs text-gray-600 mb-1">
+                      Downloading language model… {Math.round(status.progress * 100)}%
+                    </p>
+                    <div className="h-1.5 bg-gray-200 rounded">
+                      <div className="h-1.5 bg-amber-400 rounded transition-all" style={{ width: `${status.progress * 100}%` }} />
+                    </div>
+                  </div>
+                )}
+                {status.kind === 'translating' && (
+                  <p className="text-xs text-gray-600">
+                    Translating… {status.done}/{status.total}
+                  </p>
+                )}
+                {status.kind === 'translated' && targetLang && (
+                  <p className="text-xs text-green-700">Translated to {languageName(targetLang, 'en')}.</p>
+                )}
+                {status.kind === 'idle' && targetLang && targetLang !== sourceLang && (
+                  <button
+                    type="button"
+                    onClick={() => run(sourceLang, targetLang)}
+                    className="w-full bg-amber-400 text-gray-900 text-xs font-semibold py-2 px-3 rounded hover:bg-amber-300"
+                  >
+                    Translate to {languageName(targetLang, 'en')}
+                  </button>
+                )}
+                {status.kind === 'error' && <p className="text-xs text-red-700">{status.message}</p>}
+              </div>
+
+              {(isTranslated || busy) && (
+                <button
+                  type="button"
+                  onClick={() => run(sourceLang, null)}
+                  className="mt-3 w-full bg-gray-800 text-white text-xs font-semibold py-2 px-3 rounded hover:bg-gray-700"
+                >
+                  Show original
+                </button>
+              )}
+            </>
+          )}
+        </div>
+      )}
+    </div>
+  );
+}
