+/**
+ * On-device translation helpers built on Chrome's built-in AI APIs
+ * (Translator API + Language Detector API). Everything runs locally in the
+ * browser; no text is sent to a server.
+ *
+ * Content opts in with a `data-translate` attribute. Every text node inside
+ * such an element is translated in place, so inline markup (links, bold, …)
+ * is preserved. Original strings are kept so the page can be restored.
+ */
+
+export type Availability = 'unavailable' | 'downloadable' | 'downloading' | 'available';
+
+interface CreateMonitor {
+  addEventListener(type: 'downloadprogress', listener: (e: { loaded: number }) => void): void;
+}
+
+interface TranslatorInstance {
+  translate(input: string, options?: { signal?: AbortSignal }): Promise<string>;
+  destroy?(): void;
+}
+
+interface TranslatorStatic {
+  availability(options: { sourceLanguage: string; targetLanguage: string }): Promise<Availability>;
+  create(options: {
+    sourceLanguage: string;
+    targetLanguage: string;
+    signal?: AbortSignal;
+    monitor?: (m: CreateMonitor) => void;
+  }): Promise<TranslatorInstance>;
+}
+
+interface LanguageDetectorStatic {
+  availability(): Promise<Availability>;
+  create(options?: { monitor?: (m: CreateMonitor) => void }): Promise<{
+    detect(input: string): Promise<{ detectedLanguage: string; confidence: number }[]>;
+  }>;
+}
+
+const TRANSLATABLE_SELECTOR = '[data-translate]';
+const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'CODE', 'PRE', 'KBD', 'SAMP', 'TEXTAREA', 'NOSCRIPT']);
+const STORAGE_KEY = 'devtools-times:translate-target';
+
+export const SUPPORTED_LANGUAGES = [
+  'en', 'es', 'fr', 'de', 'it', 'pt', 'nl', 'pl', 'sv', 'tr', 'ru', 'uk',
+  'ar', 'hi', 'bn', 'id', 'vi', 'th', 'ja', 'ko', 'zh', 'zh-Hant',
+] as const;
+
+function getTranslatorApi(): TranslatorStatic | undefined {
+  return (globalThis as any).Translator;
+}
+
+function getDetectorApi(): LanguageDetectorStatic | undefined {
+  return (globalThis as any).LanguageDetector;
+}
+
+export function isTranslationSupported(): boolean {
+  return typeof window !== 'undefined' && !!getTranslatorApi();
+}
+
+export function languageName(code: string, displayIn?: string): string {
+  try {
+    const name = new Intl.DisplayNames([displayIn ?? code], { type: 'language' }).of(code);
+    if (name) return name.charAt(0).toLocaleUpperCase(displayIn ?? code) + name.slice(1);
+  } catch {
+    /* fall through */
+  }
+  return code;
+}
+
+export function getSavedTarget(): string | null {
