+
+// ---------------------------------------------------------------------------
+// Translation
+// ---------------------------------------------------------------------------
+
+const translatorCache = new Map<string, Promise<TranslatorInstance>>();
+
+export async function getAvailability(sourceLanguage: string, targetLanguage: string): Promise<Availability> {
+  const api = getTranslatorApi();
+  if (!api) return 'unavailable';
+  try {
+    return await api.availability({ sourceLanguage, targetLanguage });
+  } catch {
+    return 'unavailable';
+  }
+}
+
+/**
+ * Get (or create) a translator for a language pair. Must be called from a
+ * user gesture if the model still needs to be downloaded.
+ */
+export function getTranslator(
+  sourceLanguage: string,
+  targetLanguage: string,
+  onDownloadProgress?: (fraction: number) => void,
+): Promise<TranslatorInstance> {
+  const api = getTranslatorApi();
+  if (!api) return Promise.reject(new Error('Translator API not supported'));
+  const key = `${sourceLanguage}->${targetLanguage}`;
+  let pending = translatorCache.get(key);
+  if (!pending) {
+    pending = api.create({
+      sourceLanguage,
+      targetLanguage,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => onDownloadProgress?.(e.loaded));
+      },
+    });
+    pending.catch(() => translatorCache.delete(key));
+    translatorCache.set(key, pending);
+  }
