+
+/**
+ * Translate every `[data-translate]` element on the page in place.
+ * Text nodes are processed in document order and updated progressively.
+ */
+export async function translatePage(
+  translator: TranslatorInstance,
+  targetLanguage: string,
+  options: { signal?: AbortSignal; onProgress?: (done: number, total: number) => void } = {},
+): Promise<void> {
+  const { signal, onProgress } = options;
+  const roots = getRoots();
+  const jobs = roots.flatMap((root) => collectTextNodes(root).map((node) => ({ root, node })));
+  const memo = new Map<string, Promise<string>>();
+  let done = 0;
+  onProgress?.(done, jobs.length);
+
+  for (const { root, node } of jobs) {
+    if (signal?.aborted) throw signal.reason ?? new DOMException('Aborted', 'AbortError');
+    const orig = originalText(node);
+    // Keep surrounding whitespace intact; translate only the meaningful part.
+    const [, lead, core, trail] = /^(\s*)([\s\S]*?)(\s*)$/.exec(orig)!;
+    let result = memo.get(core);
+    if (!result) {
+      result = translator.translate(core, { signal });
+      memo.set(core, result);
+    }
+    const translated = await result;
+    if (signal?.aborted) throw signal.reason ?? new DOMException('Aborted', 'AbortError');
+    if (!node.isConnected) continue;
+    if (!originals.has(node)) originals.set(node, orig);
+    node.data = lead + translated + trail;
+    setRootLang(root, targetLanguage);
+    root.setAttribute('data-translated', targetLanguage);
+    onProgress?.(++done, jobs.length);
+  }
+}

