+// Server-side verification of Email Verification Protocol (EVP) tokens.
+//
+// The browser submits `EVT~KB-JWT` (an SD-JWT presentation) in the hidden
+// `autocomplete="email-verification-token"` field. This module checks the whole
+// trust chain before the relying party treats the email address as verified:
+//   1. DNS delegation:   _email-verification.<domain> TXT  ->  iss
+//   2. Issuer metadata:  ${iss}/.well-known/email-verification  ->  jwks_uri
+//   3. EVT signature:    signed by the issuer, fresh, typ ev+sd-jwt
+//   4. KB-JWT:           signed by the browser key in cnf.jwk, bound to our
+//                        origin (aud) and the single-use session nonce
+//   5. Claims:           email_verified === true, email matches the form value
+//
+// Any failure throws; callers must fall back to a normal verification email.
+
+import { createHash } from 'node:crypto';
+import dns from 'node:dns/promises';
+import { SdJwt, SdJwtInstance } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+// draft-hardt-email-verification specifies RFC 9864 'Ed25519' and 'ES256'.
+// TODO: drop 'EdDSA' once issuers and Chrome Origin Trial builds finish moving to 'Ed25519'.
+const ALLOWED_ALGS = ['Ed25519', 'EdDSA', 'ES256'];
+const normalizeAlg = (alg) => (alg === 'Ed25519' ? 'EdDSA' : alg);
+
+const MAX_TOKEN_LENGTH = 16 * 1024;
+const NETWORK_TIMEOUT_MS = 5000;
+const JWKS_CACHE_TTL_MS = 10 * 60 * 1000;
+
+const hasher = (data, alg) =>
+  new Uint8Array(createHash(alg === 'sha-256' ? 'sha256' : alg).update(data).digest());
+
+/** Remote JWKS instances cached per jwks_uri so jose's own key caching is reused. */
+const jwksCache = new Map();
+
+function getRemoteJwks(jwksUri) {
+  const cached = jwksCache.get(jwksUri);
+  if (cached && cached.expires > Date.now()) return cached.jwks;
+  const jwks = createRemoteJWKSet(new URL(jwksUri), { timeoutDuration: NETWORK_TIMEOUT_MS });
+  jwksCache.set(jwksUri, { jwks, expires: Date.now() + JWKS_CACHE_TTL_MS });
+  return jwks;
+}
+
+/** `iss` must be a bare https origin: no port, path, query, or trailing slash. */
+function assertIssuerShape(iss) {
+  let url;
+  try {
+    url = new URL(iss);
+  } catch {
+    throw new Error('EVT iss is not a URL.');
+  }
+  if (url.protocol !== 'https:' || url.port !== '' || url.origin !== iss) {
+    throw new Error(`EVT iss "${iss}" is not a bare https origin.`);
+  }
+}
+
+async function assertDnsDelegation(domain, iss) {
+  let records;
+  try {
+    records = (await dns.resolveTxt(`_email-verification.${domain}`)).map((r) => r.join(''));
+  } catch (err) {
+    throw new Error(`No _email-verification TXT record for "${domain}" (${err.code ?? err.message}).`);
+  }
+  const delegated = records.some(
+    (txt) => txt.startsWith('iss=') && `https://${txt.slice(4).trim()}` === iss,
+  );
+  if (!delegated) throw new Error(`Issuer "${iss}" is not delegated via DNS for "${domain}".`);
+}
+
+async function loadIssuerJwks(iss) {
+  const discoveryUrl = new URL('/.well-known/email-verification', iss);
+  const res = await fetch(discoveryUrl, {
+    redirect: 'error',
+    signal: AbortSignal.timeout(NETWORK_TIMEOUT_MS),
+    headers: { accept: 'application/json' },
+  });
+  if (!res.ok) throw new Error(`Issuer metadata request failed with HTTP ${res.status}.`);
+  const metadata = await res.json();
