index 0000000..5464c0c
--- /dev/null
+++ b/server/server.mjs
@@ -0,0 +1,321 @@
+// The Daily Grind web server.
+//
+// GET  /                       Homepage with the rewards sign-up form. Each render
+//                              gets a fresh single-use Email Verification nonce.
+// POST /api/rewards/signup     Creates the rewards account. If the browser attached a
+//                              valid Email Verification Token, the email address is
+//                              marked verified right away and no email is sent.
+//                              Otherwise it falls back to a verification email.
+//
+// Environment:
+//   PORT                  Port to listen on (default 11222)
+//   RP_ORIGIN             Public origin users load the site from, used as the KB-JWT
+//                         audience (default http://localhost:$PORT)
+//   ORIGIN_TRIAL_TOKEN    Chrome Origin Trial token for Email Verification
+
+import { createServer } from 'node:http';
+import { randomBytes, scrypt, timingSafeEqual } from 'node:crypto';
+import { readFile } from 'node:fs/promises';
+import { promisify } from 'node:util';
+import { fileURLToPath } from 'node:url';
+import { verifyEmailVerificationToken } from './email-verification.mjs';
+
+const scryptAsync = promisify(scrypt);
+
+const PORT = Number(process.env.PORT) || 11222;
+const RP_ORIGIN = (process.env.RP_ORIGIN || `http://localhost:${PORT}`).replace(/\/+$/, '');
+const ORIGIN_TRIAL_TOKEN = process.env.ORIGIN_TRIAL_TOKEN || '';
+const SECURE_COOKIES = RP_ORIGIN.startsWith('https://');
+
+const SESSION_COOKIE = SECURE_COOKIES ? '__Host-dg_sid' : 'dg_sid';
+const SESSION_TTL_MS = 30 * 60 * 1000;
+const NONCE_TTL_MS = 10 * 60 * 1000;
+const MAX_BODY_BYTES = 32 * 1024;
+
+const TEMPLATE_PATH = fileURLToPath(new URL('../index.html', import.meta.url));
+const template = await readFile(TEMPLATE_PATH, 'utf8');
+
+// ---------------------------------------------------------------------------
+// Server-side session state. In-memory for this demo; swap for Redis or a DB
+// table in production (the nonce must be consumed atomically, e.g. GETDEL).
+// ---------------------------------------------------------------------------
+
+/** @type {Map<string, { expires: number, nonce?: string, nonceExpires?: number, flash?: object }>} */
+const sessions = new Map();
+
+setInterval(() => {
+  const now = Date.now();
+  for (const [sid, s] of sessions) if (s.expires < now) sessions.delete(sid);
+}, 60 * 1000).unref();
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const i = part.indexOf('=');
+    if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
+  }
+  return out;
+}
+
+function getSession(req, res) {
+  const sid = parseCookies(req.headers.cookie)[SESSION_COOKIE];
+  let session = sid && sessions.get(sid);
+  let id = sid;
+  if (!session || session.expires < Date.now()) {
+    id = randomBytes(32).toString('base64url');
+    session = { expires: 0 };
+    sessions.set(id, session);
+    res.setHeader(
+      'Set-Cookie',
+      `${SESSION_COOKIE}=${id}; Path=/; HttpOnly; SameSite=Lax${SECURE_COOKIES ? '; Secure' : ''}; Max-Age=${SESSION_TTL_MS / 1000}`,
+    );
+  }
+  session.expires = Date.now() + SESSION_TTL_MS;
+  return session;
+}
+
+/** Issue a fresh nonce for this form render (replacing any previous one). */
+function issueNonce(session) {
+  session.nonce = randomBytes(32).toString('base64url');
+  session.nonceExpires = Date.now() + NONCE_TTL_MS;
+  return session.nonce;
+}
+
+/** Read and delete the nonce in one synchronous step so it can only be used once. */
+function consumeNonce(session) {
+  const { nonce, nonceExpires } = session;
+  delete session.nonce;
+  delete session.nonceExpires;
+  return nonce && nonceExpires > Date.now() ? nonce : null;
+}
+
+// ---------------------------------------------------------------------------
+// Accounts. In-memory for this demo; replace with your user store.
+// ---------------------------------------------------------------------------
+
+/** @type {Map<string, { id: string, name: string, email: string, passwordHash: string, emailVerified: boolean, emailVerifiedVia?: string, createdAt: string }>} */
+const accounts = new Map();
+
+async function hashPassword(password) {
+  const salt = randomBytes(16);
+  const key = await scryptAsync(password.normalize('NFKC'), salt, 64);
+  return `scrypt$${salt.toString('base64url')}$${key.toString('base64url')}`;
+}
+
+// Exported for a future sign-in route.
+export async function checkPassword(password, stored) {
+  const [, salt, key] = stored.split('$');
+  const expected = Buffer.from(key, 'base64url');
+  const actual = await scryptAsync(password.normalize('NFKC'), Buffer.from(salt, 'base64url'), expected.length);
+  return timingSafeEqual(actual, expected);
+}
+
+/**
+ * Fallback for browsers without Email Verification support, users signed out of
+ * their email provider, non-participating domains, or failed tokens.
+ * TODO: wire up to the transactional email provider.
+ */
+async function sendTraditionalVerificationEmail(email, { existingAccount = false } = {}) {
+  console.info(
+    existingAccount
+      ? `[signup] would email ${email}: "you already have a rewards account"`
+      : `[signup] would email ${email}: verification link`,
+  );
+}
+
+// ---------------------------------------------------------------------------
+// Rendering
+// ---------------------------------------------------------------------------
+
+const escapeHtml = (s) =>
+  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
+
+const FLASH_MESSAGES = {
+  verified: (f) => ({
+    tone: 'success',
+    title: `Welcome to Grind Rewards, ${f.name}!`,
+    body: `Your email address ${f.email} is confirmed, so there's nothing to check in your inbox. Your first drink reward is already on its way.`,
+  }),
+  pending: (f) => ({
+    tone: 'info',
+    title: 'Check your inbox',
+    body: `We sent a confirmation link to ${f.email}. Open it to finish setting up your rewards account.`,
+  }),
+  exists: (f) => ({
+    tone: 'info',
+    title: 'You already have a rewards account',
+    body: `${f.email} is already a Grind Rewards member. Sign in from My Account to see your stars.`,
+  }),
+  invalid: () => ({
+    tone: 'error',
+    title: 'We couldn’t create your account',
+    body: 'Check that you entered your name, a valid email address, and a password that meets the requirements, then try again.',
+  }),
+};
+
+function renderStatus(flash) {
+  const make = flash && FLASH_MESSAGES[flash.kind];
+  if (!make) return '';
+  const m = make(flash);
+  return `<div class="signup-status signup-status--${m.tone}" role="status" tabindex="-1" id="signup-status">
+          <p class="signup-status__title">${escapeHtml(m.title)}</p>
+          <p>${escapeHtml(m.body)}</p>
+        </div>`;
+}
+
+function renderHome(session) {
+  const flash = session.flash;
+  delete session.flash;
+  return template
+    .replaceAll('{{EVT_NONCE}}', escapeHtml(issueNonce(session)))
+    .replace('{{SIGNUP_STATUS}}', renderStatus(flash))
+    .replace('{{SIGNUP_NAME}}', escapeHtml(flash?.kind === 'invalid' ? flash.name ?? '' : ''))
+    .replace('{{SIGNUP_EMAIL}}', escapeHtml(flash?.kind === 'invalid' ? flash.email ?? '' : ''));
+}
+
+// ---------------------------------------------------------------------------
+// Request handling
+// ---------------------------------------------------------------------------
+
+const BASE_HEADERS = {
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'X-Frame-Options': 'DENY',
+};
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, { ...BASE_HEADERS, ...headers });
+  res.end(body);
+}
+
+function redirect(res, location) {
+  send(res, 303, '', { Location: location, 'Cache-Control': 'no-store' });
+}
+
+async function readForm(req) {
+  const type = (req.headers['content-type'] || '').split(';')[0].trim();
+  if (type !== 'application/x-www-form-urlencoded') return null;
+  let size = 0;
+  const chunks = [];
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > MAX_BODY_BYTES) throw Object.assign(new Error('Body too large'), { status: 413 });
+    chunks.push(chunk);
+  }
+  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
+}
+
+/** Reject cross-site form posts (SameSite=Lax already blocks the cookie; this is defense in depth). */
+function isSameOrigin(req) {
+  const origin = req.headers.origin;
+  if (origin) return origin === RP_ORIGIN;
+  return req.headers['sec-fetch-site'] ? req.headers['sec-fetch-site'] === 'same-origin' : true;
+}
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+const PASSWORD_RE = /^(?=.*\d)(?=.*\p{Ll})(?=.*\p{Lu})(?=.*[^\p{L}\d]).{8,128}$/u;
+
+async function handleSignup(req, res) {
+  if (!isSameOrigin(req)) return send(res, 403, 'Forbidden', { 'Content-Type': 'text/plain' });
+
+  const session = getSession(req, res);
+  // Consume the nonce first, whatever happens next, so a token can never be replayed.
+  const expectedNonce = consumeNonce(session);
+
+  const form = await readForm(req);
+  if (!form) return send(res, 415, 'Unsupported Media Type', { 'Content-Type': 'text/plain' });
+
+  const name = String(form.get('name') || '').trim().slice(0, 100);
+  const email = String(form.get('email') || '').trim();
+  const password = String(form.get('new-password') || '');
+  const rawToken = String(form.get('email-verification-token') || '').trim();
+
+  if (!name || email.length > 254 || !EMAIL_RE.test(email) || !PASSWORD_RE.test(password)) {
+    session.flash = { kind: 'invalid', name, email };
+    return redirect(res, '/#rewards-signup');
+  }
+
+  // Fast path: browser-provided proof that the user controls this email address.
+  let verified = null;
+  if (rawToken && expectedNonce) {
+    try {
+      verified = await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail: email,
+        expectedNonce,
+        expectedAudience: RP_ORIGIN,
+      });
+    } catch (err) {
+      console.warn('[signup] email verification token rejected:', err.message);
+    }
+  }
+
+  const key = email.toLowerCase();
+  const existing = accounts.get(key);
+
+  if (existing) {
+    // Only reveal that the account exists to someone who proved they own the address.
+    if (verified) {
+      session.flash = { kind: 'exists', email };
+    } else {
+      await sendTraditionalVerificationEmail(email, { existingAccount: true });
+      session.flash = { kind: 'pending', email };
+    }
+    return redirect(res, '/#rewards-signup');
+  }
+
+  accounts.set(key, {
+    id: randomBytes(16).toString('hex'),
+    name,
+    email,
+    passwordHash: await hashPassword(password),
+    emailVerified: Boolean(verified),
+    emailVerifiedVia: verified ? `evp:${verified.issuer}` : undefined,
+    createdAt: new Date().toISOString(),
+  });
+
+  if (verified) {
+    console.info(`[signup] ${email} verified by ${verified.issuer}; no verification email sent`);
+    session.flash = { kind: 'verified', name, email };
+  } else {
+    await sendTraditionalVerificationEmail(email);
+    session.flash = { kind: 'pending', email };
+  }
+  return redirect(res, '/#rewards-signup');
+}
+
+const server = createServer(async (req, res) => {
+  try {
+    const { pathname } = new URL(req.url, RP_ORIGIN);
+
+    if (pathname === '/' || pathname === '/index.html') {
+      if (req.method !== 'GET' && req.method !== 'HEAD') {
+        return send(res, 405, 'Method Not Allowed', { Allow: 'GET, HEAD' });
+      }
+      const session = getSession(req, res);
+      const headers = {
+        'Content-Type': 'text/html; charset=utf-8',
+        // The page embeds a single-use nonce; never let caches or bfcache reuse it.
+        'Cache-Control': 'no-store',
+      };
+      if (ORIGIN_TRIAL_TOKEN) headers['Origin-Trial'] = ORIGIN_TRIAL_TOKEN;
+      const html = renderHome(session);
+      return send(res, 200, req.method === 'HEAD' ? '' : html, headers);
+    }
+
+    if (pathname === '/api/rewards/signup') {
+      if (req.method !== 'POST') return send(res, 405, 'Method Not Allowed', { Allow: 'POST' });
+      return await handleSignup(req, res);
+    }
+
+    send(res, 404, 'Not Found', { 'Content-Type': 'text/plain' });
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) send(res, err.status || 500, err.status ? err.message : 'Internal Server Error', { 'Content-Type': 'text/plain' });
+    else res.end();
+  }
+});
+
+server.listen(PORT, () => {
+  console.info(`The Daily Grind listening on :${PORT} (RP origin ${RP_ORIGIN})`);
+});

