+// Rewards sign-up: confirms the email address in the browser using the
+// Email Verification Protocol (no passcode or magic-link email is sent).
+(() => {
+  'use strict';
+  const form = document.getElementById('rewards-signup');
+  if (!form) return;
+  const emailInput = form.querySelector('#rs-email');
+  const statusEl = form.querySelector('#rs-email-status');
+  const formMsg = form.querySelector('#rs-form-message');
+  const submitBtn = form.querySelector('button[type="submit"]');
+  const success = document.getElementById('rewards-success');
+
+  let verifiedEmail = null;
+  let verifying = false;
+
+  function setStatus(state, text) {
+    statusEl.dataset.state = state;
+    statusEl.textContent = text;
+  }
+
+  async function refreshNonce() {
+    try {
+      const res = await fetch('/api/rewards/email-verification/nonce', { credentials: 'same-origin', cache: 'no-store' });
+      if (!res.ok) throw new Error();
+      const { nonce } = await res.json();
+      // Supporting browsers read the nonce from the email input and bind it into the token.
+      emailInput.nonce = nonce;
+      emailInput.setAttribute('nonce', nonce);
+    } catch {
+      /* verification simply won't be available */
+    }
+  }
+
+  emailInput.addEventListener('emailverified', async (event) => {
+    const token = event.presentationToken;
+    if (!token) return;
+    verifying = true;
+    setStatus('pending', 'Confirming your email with your provider…');
+    try {
+      const res = await fetch('/api/rewards/email-verification/verify', {
+        method: 'POST',
+        credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ token }),
+      });
+      const data = await res.json().catch(() => ({}));
+      if (res.ok && data.verified) {
+        verifiedEmail = data.email.toLowerCase();
+        if (emailInput.value.trim().toLowerCase() !== verifiedEmail) emailInput.value = data.email;
+        setStatus('verified', `✓ ${data.email} confirmed — no code needed.`);
+      } else {
+        verifiedEmail = null;
+        setStatus('error', data.error || 'We couldn’t confirm this email.');
+      }
+    } catch {
+      verifiedEmail = null;
+      setStatus('error', 'Network error while confirming your email.');
+    } finally {
+      verifying = false;
+      refreshNonce(); // nonces are single-use
+    }
+  });
+
+  emailInput.addEventListener('input', () => {
+    if (verifiedEmail && emailInput.value.trim().toLowerCase() !== verifiedEmail) {
+      verifiedEmail = null;
+      setStatus('idle', 'Email changed — pick your address from the browser’s suggestions to confirm it instantly.');
+    }
+  });
+
+  function showFieldErrors(fields = {}) {
+    form.querySelectorAll('.field-error').forEach((el) => { el.textContent = ''; });
+    form.querySelectorAll('[aria-invalid]').forEach((el) => el.removeAttribute('aria-invalid'));
+    for (const [name, msg] of Object.entries(fields)) {
+      const el = form.querySelector(`[data-error-for="${name}"]`);
+      if (el) el.textContent = msg;
+      const input = form.elements[name];
+      if (input) input.setAttribute('aria-invalid', 'true');
+    }
+  }
+
+  form.addEventListener('submit', async (e) => {
+    e.preventDefault();
+    if (verifying) return;
+    formMsg.textContent = '';
+    showFieldErrors();
+    if (!form.reportValidity()) return;
+
+    submitBtn.disabled = true;
+    submitBtn.textContent = 'Creating account…';
+    const fd = new FormData(form);
+    try {
+      const res = await fetch('/api/rewards/signup', {
+        method: 'POST',
+        credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          name: fd.get('name'),
+          email: fd.get('email'),
+          password: fd.get('password'),
+          birthday: fd.get('birthday') || null,
+          marketingOptIn: fd.get('marketingOptIn') === 'on',
+          acceptTerms: fd.get('acceptTerms') === 'on',
+        }),
+      });
+      const data = await res.json().catch(() => ({}));
+      if (!res.ok) {
+        showFieldErrors(data.fields);
+        formMsg.textContent = data.error || 'Sign-up failed. Please try again.';
+        return;
+      }
+      form.hidden = true;
+      success.hidden = false;
+      success.querySelector('[data-name]').textContent = data.name;
+      success.querySelector('[data-member]').textContent = data.memberNumber;
+      success.querySelector('[data-points]').textContent = data.points;
+      success.querySelector('[data-verified]').textContent = data.emailVerified
+        ? `Your email (${data.email}) is confirmed.`
+        : `We couldn’t confirm ${data.email} automatically in this browser — you can confirm it later from My Account.`;
+      success.focus();
+    } catch {
+      formMsg.textContent = 'Network error. Please try again.';
+    } finally {
+      submitBtn.disabled = false;
+      submitBtn.textContent = 'Join Daily Grind Rewards';
+    }
+  });
+
+  refreshNonce();
+})();
