@@ -0,0 +1,334 @@
+// Server-side verifier for the browser Email Verification Protocol (EVP).
+//
+// Flow: the page puts a server-issued nonce on <input type="email" autocomplete="email">.
+// When the customer picks an address, a supporting browser looks up the email domain's
+// issuer (DNS TXT `_email-verification.<domain>` -> `iss=<issuer>`), obtains an SD-JWT
+// from that issuer bound to a browser-held key, appends a Key-Binding JWT carrying our
+// origin + nonce, and fires an `emailverified` event with the presentation token.
+// No passcode or magic-link email is ever sent.
+//
+// This module verifies that token end-to-end:
+//   1. DNS delegation: the email's domain names the issuer that signed the token.
+//   2. Issuer signature: SD-JWT verifies against the issuer's published JWKS.
+//   3. Key binding: KB-JWT verifies against cnf.jwk, with aud == our origin,
+//      nonce == the one we issued to this session, fresh iat, matching sd_hash.
+'use strict';
+
+const crypto = require('node:crypto');
+const dns = require('node:dns').promises;
+const net = require('node:net');
+
+const ALGS = {
+  ES256: { hash: 'sha256', kty: 'EC', crv: 'P-256', dsaEncoding: 'ieee-p1363' },
+  ES384: { hash: 'sha384', kty: 'EC', crv: 'P-384', dsaEncoding: 'ieee-p1363' },
+  RS256: { hash: 'sha256', kty: 'RSA' },
+  PS256: { hash: 'sha256', kty: 'RSA', padding: crypto.constants.RSA_PKCS1_PSS_PADDING, saltLength: 32 },
+  EdDSA: { hash: null, kty: 'OKP', crv: 'Ed25519' },
+};
+
+const SD_JWT_TYP = 'evp+sd-jwt';
+const KB_JWT_TYP = 'kb+jwt';
+const MAX_TOKEN_LENGTH = 16 * 1024;
+const MAX_FETCH_BYTES = 64 * 1024;
+const FETCH_TIMEOUT_MS = 5000;
+const KB_MAX_AGE_S = 300;        // key-binding JWT must be minted within 5 minutes
+const ISSUANCE_MAX_AGE_S = 3600; // issuer token at most 1 hour old
+const CLOCK_SKEW_S = 60;
+const METADATA_TTL_MS = 10 * 60 * 1000;
+
+class EmailVerificationError extends Error {
+  constructor(code, message) {
+    super(message);
+    this.code = code;
+  }
+}
+
+const fail = (code, msg) => { throw new EmailVerificationError(code, msg); };
+
+function b64urlDecode(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) fail('malformed', 'Invalid base64url segment');
+  return Buffer.from(str, 'base64url');
+}
+
+function b64urlJson(str) {
+  try {
+    const v = JSON.parse(b64urlDecode(str).toString('utf8'));
+    if (!v || typeof v !== 'object' || Array.isArray(v)) throw new Error();
+    return v;
+  } catch (e) {
+    if (e instanceof EmailVerificationError) throw e;
+    return fail('malformed', 'Invalid JWT JSON segment');
+  }
+}
+
+function parseJwt(jwt) {
+  const parts = jwt.split('.');
+  if (parts.length !== 3) fail('malformed', 'JWT must have three parts');
+  return {
+    header: b64urlJson(parts[0]),
+    payload: b64urlJson(parts[1]),
+    signingInput: Buffer.from(`${parts[0]}.${parts[1]}`, 'ascii'),
+    signature: b64urlDecode(parts[2]),
+  };
+}
+
+function verifyJwtSignature(parsed, jwk, allowedAlgs) {
+  const alg = parsed.header.alg;
+  const spec = Object.prototype.hasOwnProperty.call(ALGS, alg) ? ALGS[alg] : null;
+  if (!spec || !allowedAlgs.includes(alg)) fail('bad_alg', `Unsupported JWT alg: ${alg}`);
+  if (!jwk || typeof jwk !== 'object' || jwk.kty !== spec.kty) fail('bad_key', 'Key type does not match alg');
+  if (spec.crv && jwk.crv !== spec.crv) fail('bad_key', 'Key curve does not match alg');
+  if (jwk.d || jwk.p || jwk.q) fail('bad_key', 'Private key material not allowed');
+
+  let key;
+  try {
+    // Only pass public members so stray fields can't change key interpretation.
+    const pub = { kty: jwk.kty };
+    for (const k of ['crv', 'x', 'y', 'n', 'e']) if (jwk[k] !== undefined) pub[k] = jwk[k];
+    key = crypto.createPublicKey({ key: pub, format: 'jwk' });
+  } catch {
+    fail('bad_key', 'Unusable public key');
+  }
+  if (spec.kty === 'RSA' && key.asymmetricKeyDetails.modulusLength < 2048) fail('bad_key', 'RSA key too small');
+
+  const opts = { key };
+  if (spec.dsaEncoding) opts.dsaEncoding = spec.dsaEncoding;
+  if (spec.padding) { opts.padding = spec.padding; opts.saltLength = spec.saltLength; }
+  let ok = false;
+  try {
+    ok = crypto.verify(spec.hash, parsed.signingInput, opts, parsed.signature);
+  } catch {
+    ok = false;
+  }
+  if (!ok) fail('bad_signature', 'JWT signature verification failed');
+}
+
+function splitEmail(email) {
+  if (typeof email !== 'string' || email.length > 254) return null;
+  const at = email.lastIndexOf('@');
+  if (at < 1 || at === email.length - 1) return null;
+  const domain = email.slice(at + 1).toLowerCase();
+  if (!isValidHostname(domain)) return null;
+  return { local: email.slice(0, at), domain };
+}
+
+function isValidHostname(host) {
+  return typeof host === 'string' && host.length <= 253 &&
+    /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,61}[a-z0-9]$/i.test(host);
+}
+
+function isPrivateAddress(ip) {
+  if (net.isIPv4(ip)) {
+    const [a, b] = ip.split('.').map(Number);
+    return a === 0 || a === 10 || a === 127 || (a === 100 && b >= 64 && b <= 127) ||
+      (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) ||
+      (a === 192 && b === 168) || (a === 198 && (b === 18 || b === 19)) || a >= 224;
+  }
+  const v = ip.toLowerCase();
+  if (v.startsWith('::ffff:')) return isPrivateAddress(v.slice(7));
+  return v === '::' || v === '::1' || v.startsWith('fc') || v.startsWith('fd') ||
+    v.startsWith('fe8') || v.startsWith('fe9') || v.startsWith('fea') || v.startsWith('feb') || v.startsWith('ff');
+}
+
+// Default network implementations; tests inject fakes.
+async function defaultResolveTxt(name) {
+  try {
+    return await dns.resolveTxt(name);
+  } catch {
+    return [];
+  }
+}
+
+async function defaultFetchJson(url) {
+  const u = new URL(url);
+  if (u.protocol !== 'https:' || !isValidHostname(u.hostname) || u.port) fail('bad_issuer', 'Issuer URLs must be https on a public hostname');
+  // Guard against SSRF to internal hosts via attacker-controlled DNS.
+  const addrs = await dns.lookup(u.hostname, { all: true }).catch(() => []);
+  if (!addrs.length || addrs.some((a) => isPrivateAddress(a.address))) fail('bad_issuer', 'Issuer host is not publicly routable');
+
+  const res = await fetch(u, {
+    redirect: 'error',
+    headers: { accept: 'application/json' },
+    signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
+  }).catch(() => fail('issuer_unreachable', `Could not fetch ${u.origin}${u.pathname}`));
+  if (!res.ok) fail('issuer_unreachable', `Issuer returned HTTP ${res.status}`);
+
+  const reader = res.body.getReader();
+  const chunks = [];
+  let size = 0;
+  for (;;) {
+    const { done, value } = await reader.read();
+    if (done) break;
+    size += value.byteLength;
+    if (size > MAX_FETCH_BYTES) { reader.cancel(); fail('issuer_unreachable', 'Issuer response too large'); }
+    chunks.push(value);
+  }
+  try {
+    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
+  } catch {
+    return fail('issuer_unreachable', 'Issuer returned invalid JSON');
+  }
+}
+
+function createEmailVerifier({
+  origin,
+  resolveTxt = defaultResolveTxt,
+  fetchJson = defaultFetchJson,
+  now = () => Date.now(),
+} = {}) {
+  if (!origin) throw new Error('createEmailVerifier requires the site origin (KB-JWT audience)');
+  const expectedAud = new URL(origin).origin;
+  const metadataCache = new Map();
+
+  async function issuerForDomain(domain) {
+    const records = await resolveTxt(`_email-verification.${domain}`);
+    const issuers = new Set();
+    for (const chunks of records) {
+      const txt = Array.isArray(chunks) ? chunks.join('') : String(chunks);
+      const m = /^iss=(.+)$/.exec(txt.trim());
+      if (m) issuers.add(m[1].trim().toLowerCase());
+    }
+    if (issuers.size !== 1) fail('no_issuer', `No unique email verification issuer delegated for ${domain}`);
+    const [iss] = issuers;
+    if (!isValidHostname(iss)) fail('bad_issuer', 'Delegated issuer is not a valid hostname');
+    return iss;
+  }
+
+  async function issuerKeys(iss) {
+    const cached = metadataCache.get(iss);
+    if (cached && cached.expires > now()) return cached.value;
+
+    const meta = await fetchJson(`https://${iss}/.well-known/email-verification`);
+    if (!meta || typeof meta.jwks_uri !== 'string') fail('bad_issuer', 'Issuer metadata missing jwks_uri');
+    let jwksUrl;
+    try { jwksUrl = new URL(meta.jwks_uri); } catch { fail('bad_issuer', 'Invalid jwks_uri'); }
+    if (jwksUrl.protocol !== 'https:' || jwksUrl.hostname.toLowerCase() !== iss) {
+      fail('bad_issuer', 'jwks_uri must be https on the issuer host');
+    }
+    const jwks = await fetchJson(jwksUrl.href);
+    if (!jwks || !Array.isArray(jwks.keys)) fail('bad_issuer', 'Issuer JWKS malformed');
+    const supported = Array.isArray(meta.signing_alg_values_supported)
+      ? meta.signing_alg_values_supported.filter((a) => a in ALGS)
+      : Object.keys(ALGS);
+
+    const value = { keys: jwks.keys, algs: supported };
+    metadataCache.set(iss, { value, expires: now() + METADATA_TTL_MS });
+    return value;
+  }
+
+  function resolveDisclosures(payload, disclosures) {
+    // Selectively-disclosed claims: each disclosure is b64url(JSON [salt, name, value]),
+    // and its digest must appear in payload._sd.
+    const claims = Object.assign(Object.create(null), payload);
+    delete claims._sd;
+    delete claims._sd_alg;
+    if (!disclosures.length) return claims;
+    if ((payload._sd_alg || 'sha-256') !== 'sha-256') fail('malformed', 'Unsupported _sd_alg');
+    const digests = new Set(Array.isArray(payload._sd) ? payload._sd : []);
+    for (const d of disclosures) {
+      const digest = crypto.createHash('sha256').update(d, 'ascii').digest('base64url');
+      if (!digests.has(digest)) fail('malformed', 'Disclosure not referenced by issuer');
+      digests.delete(digest); // no duplicates
+      let arr;
+      try { arr = JSON.parse(b64urlDecode(d).toString('utf8')); } catch { fail('malformed', 'Bad disclosure'); }
+      if (!Array.isArray(arr) || arr.length !== 3 || typeof arr[1] !== 'string') fail('malformed', 'Bad disclosure');
+      const name = arr[1];
+      if (['iss', 'iat', 'exp', 'nbf', 'cnf', '_sd', '_sd_alg', '__proto__'].includes(name) || Object.hasOwn(claims, name)) {
+        fail('malformed', `Disclosure may not set ${name}`);
+      }
+      claims[name] = arr[2];
+    }
+    return claims;
+  }
+
+  /**
+   * Verify a presentation token. Returns { email, issuer } on success, throws
+   * EmailVerificationError otherwise.
+   * @param {string} token   SD-JWT~[disclosures~]KB-JWT from the `emailverified` event
+   * @param {string} nonce   nonce this server issued to the session
+   */
+  async function verify(token, nonce) {
+    if (typeof token !== 'string' || !token || token.length > MAX_TOKEN_LENGTH) fail('malformed', 'Missing or oversized token');
+    if (typeof nonce !== 'string' || !nonce) fail('bad_nonce', 'No nonce issued for this session');
+
+    const segments = token.split('~');
+    if (segments.length < 2) fail('malformed', 'Token is not an SD-JWT+KB presentation');
+    const kbJwt = segments.pop();
+    const [issuerJwt, ...disclosures] = segments;
+    if (!kbJwt) fail('malformed', 'Key-binding JWT missing');
+    if (disclosures.some((d) => !d)) fail('malformed', 'Empty disclosure');
+
+    const sd = parseJwt(issuerJwt);
+    const kb = parseJwt(kbJwt);
+    const nowS = Math.floor(now() / 1000);
+
+    // --- Issuer token claims (checked before any network I/O) ---
+    if (sd.header.typ !== SD_JWT_TYP) fail('malformed', 'Unexpected SD-JWT typ');
+    const claims = resolveDisclosures(sd.payload, disclosures);
+    const { iss, iat, exp, cnf } = sd.payload;
+    if (typeof iss !== 'string' || !iss) fail('malformed', 'Missing iss');
+    if (typeof iat !== 'number' || iat > nowS + CLOCK_SKEW_S || iat < nowS - ISSUANCE_MAX_AGE_S) fail('expired', 'Issuer token is stale');
+    if (exp !== undefined && (typeof exp !== 'number' || exp < nowS - CLOCK_SKEW_S)) fail('expired', 'Issuer token expired');
+    if (!cnf || typeof cnf.jwk !== 'object') fail('malformed', 'Missing cnf.jwk');
+    if (claims.email_verified !== true) fail('unverified', 'Issuer did not assert email_verified');
+    const email = claims.email;
+    const parts = splitEmail(email);
+    if (!parts) fail('malformed', 'Token email is invalid');
+
+    // --- Key binding: proves the presenter holds the key, for *our* origin and nonce ---
+    if (kb.header.typ !== KB_JWT_TYP) fail('malformed', 'Unexpected KB-JWT typ');
+    verifyJwtSignature(kb, cnf.jwk, ['ES256', 'ES384', 'EdDSA', 'RS256', 'PS256']);
+    if (kb.payload.aud !== expectedAud) fail('bad_audience', 'Token was not minted for this site');
+    if (typeof kb.payload.nonce !== 'string' || !timingSafeEqualStr(kb.payload.nonce, nonce)) fail('bad_nonce', 'Nonce mismatch');
+    const kbIat = kb.payload.iat;
+    if (typeof kbIat !== 'number' || kbIat > nowS + CLOCK_SKEW_S || kbIat < nowS - KB_MAX_AGE_S) fail('expired', 'Key-binding JWT is stale');
+    const sdHash = crypto.createHash('sha256').update(`${segments.join('~')}~`, 'ascii').digest('base64url');
+    if (kb.payload.sd_hash !== sdHash) fail('malformed', 'sd_hash does not match presentation');
+
+    // --- DNS delegation: email domain must authorize this issuer ---
+    const delegated = await issuerForDomain(parts.domain);
+    const issHost = issuerHost(iss);
+    if (issHost !== delegated) fail('bad_issuer', 'Token issuer is not authorized for the email domain');
+
+    // --- Issuer signature ---
+    const { keys, algs } = await issuerKeys(delegated);
+    const kid = sd.header.kid;
+    const candidates = keys.filter((k) => k && (kid === undefined || k.kid === kid) &&
+      (k.use === undefined || k.use === 'sig'));
+    if (!candidates.length) fail('bad_key', 'No issuer key matches kid');
+    let lastErr;
+    for (const jwk of candidates) {
+      try {
+        verifyJwtSignature(sd, jwk, algs);
+        return { email: `${parts.local}@${parts.domain}`, issuer: delegated };
+      } catch (e) {
+        lastErr = e;
+      }
+    }
+    throw lastErr;
+  }
+
+  return { verify };
+}
+
+function issuerHost(iss) {
+  // `iss` may be a bare hostname or an https URL.
+  if (/^https:\/\//i.test(iss)) {
+    try {
+      const u = new URL(iss);
+      if (u.pathname !== '/' || u.port || u.search || u.hash) return null;
+      return u.hostname.toLowerCase();
+    } catch {
+      return null;
+    }
+  }
+  return iss.toLowerCase();
+}
+
+function timingSafeEqualStr(a, b) {
+  const ab = Buffer.from(a);
+  const bb = Buffer.from(b);
+  return ab.length === bb.length && crypto.timingSafeEqual(ab, bb);
+}
+
+module.exports = { createEmailVerifier, EmailVerificationError, isPrivateAddress, splitEmail };
