+'use strict';
+// Minimal JSON-file member store. Swap for a real database in production.
+const fs = require('node:fs');
+const path = require('node:path');
+const crypto = require('node:crypto');
+
+function createMemberStore(file) {
+  let members = [];
+  try {
+    members = JSON.parse(fs.readFileSync(file, 'utf8'));
+  } catch {
+    members = [];
+  }
+  let writing = Promise.resolve();
+
+  function persist() {
+    const data = JSON.stringify(members, null, 2);
+    writing = writing.then(async () => {
+      await fs.promises.mkdir(path.dirname(file), { recursive: true });
+      const tmp = `${file}.${process.pid}.tmp`;
+      await fs.promises.writeFile(tmp, data, { mode: 0o600 });
+      await fs.promises.rename(tmp, file);
+    });
+    return writing;
+  }
+
+  return {
+    findByEmail(email) {
+      const key = email.toLowerCase();
+      return members.find((m) => m.emailKey === key) || null;
+    },
+    async create({ name, email, passwordHash, birthday, marketingOptIn, emailVerified, emailIssuer }) {
+      const member = {
+        id: crypto.randomUUID(),
+        memberNumber: `DG-${crypto.randomInt(10_000_000, 99_999_999)}`,
+        name,
+        email,
+        emailKey: email.toLowerCase(),
+        passwordHash,
+        birthday: birthday || null,
+        marketingOptIn: !!marketingOptIn,
+        emailVerified: !!emailVerified,
+        emailVerifiedAt: emailVerified ? new Date().toISOString() : null,
+        emailVerificationMethod: emailVerified ? 'email-verification-protocol' : null,
+        emailIssuer: emailIssuer || null,
+        points: 50, // welcome bonus
+        createdAt: new Date().toISOString(),
+      };
+      members.push(member);
+      await persist();
+      return member;
+    },
+  };
+}
+
+function hashPassword(password) {
+  const salt = crypto.randomBytes(16);
+  const hash = crypto.scryptSync(password, salt, 64, { N: 16384, r: 8, p: 1 });
+  return `scrypt$16384$8$1$${salt.toString('base64')}$${hash.toString('base64')}`;
+}
+
+module.exports = { createMemberStore, hashPassword };
