@@ -0,0 +1,236 @@
+'use strict';
+// The Daily Grind web server: serves the homepage and the rewards sign-up API.
+//
+//   GET  /api/rewards/email-verification/nonce   -> issue a session-bound nonce for the email input
+//   POST /api/rewards/email-verification/verify  -> verify the browser's EVP presentation token
+//   POST /api/rewards/signup                      -> create the rewards account
+//
+// Env: PORT (default 11222), PUBLIC_ORIGIN (default http://localhost:PORT — must be the exact
+// origin customers load the site from; it is the audience the browser binds tokens to),
+// DATA_DIR (default ./data), TRUST_PROXY=1 to read client IP from X-Forwarded-For.
+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+const crypto = require('node:crypto');
+const { createEmailVerifier, EmailVerificationError, splitEmail } = require('./lib/email-verification');
+const { createMemberStore, hashPassword } = require('./lib/member-store');
+
+const PORT = Number(process.env.PORT) || 11222;
+const PUBLIC_ORIGIN = new URL(process.env.PUBLIC_ORIGIN || `http://localhost:${PORT}`).origin;
+const SECURE_COOKIES = PUBLIC_ORIGIN.startsWith('https://');
+const ROOT = __dirname;
+const ASSETS_DIR = path.join(ROOT, 'assets');
+const DATA_DIR = process.env.DATA_DIR || path.join(ROOT, 'data');
+const SESSION_TTL_MS = 15 * 60 * 1000;
+const NONCE_TTL_MS = 5 * 60 * 1000;
+const MAX_BODY = 32 * 1024;
+const COOKIE = SECURE_COOKIES ? '__Host-dg_signup' : 'dg_signup';
+
+const verifier = createEmailVerifier({ origin: PUBLIC_ORIGIN });
+const members = createMemberStore(path.join(DATA_DIR, 'members.json'));
+
+// ---- sessions (in-memory; sign-up state only) ----
+const sessions = new Map();
+setInterval(() => {
+  const t = Date.now();
+  for (const [id, s] of sessions) if (s.expires < t) sessions.delete(id);
+}, 60_000).unref();
+
+function getSession(req, res, create) {
+  const sid = parseCookies(req.headers.cookie)[COOKIE];
+  let s = sid && sessions.get(sid);
+  if (s && s.expires < Date.now()) { sessions.delete(sid); s = null; }
+  if (!s && create) {
+    const id = crypto.randomBytes(32).toString('base64url');
+    s = { id, nonce: null, nonceExpires: 0, verified: null };
+    sessions.set(id, s);
+    res.setHeader('Set-Cookie', `${COOKIE}=${id}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${SESSION_TTL_MS / 1000}${SECURE_COOKIES ? '; Secure' : ''}`);
+  }
+  if (s) s.expires = Date.now() + SESSION_TTL_MS;
+  return s || null;
+}
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const i = part.indexOf('=');
+    if (i > 0) out[part.slice(0, i).trim()] = part.slice(i + 1).trim();
+  }
+  return out;
+}
+
+// ---- rate limiting (fixed window per IP + bucket) ----
+const hits = new Map();
+setInterval(() => hits.clear(), 60_000).unref();
+function rateLimited(req, bucket, limit) {
+  const ip = process.env.TRUST_PROXY === '1'
+    ? String(req.headers['x-forwarded-for'] || '').split(',')[0].trim() || req.socket.remoteAddress
+    : req.socket.remoteAddress;
+  const key = `${bucket}:${ip}`;
+  const n = (hits.get(key) || 0) + 1;
+  hits.set(key, n);
+  return n > limit;
+}
+
+// ---- helpers ----
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' https://images.unsplash.com data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'X-Frame-Options': 'DENY',
+};
+
+function send(res, status, body, type = 'application/json; charset=utf-8') {
+  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
+  res.writeHead(status, { ...SECURITY_HEADERS, 'Content-Type': type, 'Cache-Control': 'no-store' });
+  res.end(payload);
+}
+
+function readJson(req) {
+  return new Promise((resolve, reject) => {
+    if (!/^application\/json\b/i.test(req.headers['content-type'] || '')) return reject(Object.assign(new Error('Expected JSON'), { status: 415 }));
+    let size = 0;
+    const chunks = [];
+    req.on('data', (c) => {
+      size += c.length;
+      if (size > MAX_BODY) { reject(Object.assign(new Error('Body too large'), { status: 413 })); req.destroy(); return; }
+      chunks.push(c);
+    });
+    req.on('end', () => {
+      try {
+        const v = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+        if (!v || typeof v !== 'object' || Array.isArray(v)) throw new Error();
+        resolve(v);
+      } catch {
+        reject(Object.assign(new Error('Invalid JSON'), { status: 400 }));
+      }
+    });
+    req.on('error', reject);
+  });
+}
+
+// CSRF defence for state-changing requests: require our exact Origin.
+function sameOrigin(req) {
+  return req.headers.origin === PUBLIC_ORIGIN;
+}
+
+const MIME = { '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.webp': 'image/webp' };
+
+function serveFile(res, file) {
+  fs.readFile(file, (err, buf) => {
+    if (err) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
+    const type = path.extname(file) === '.html' ? 'text/html; charset=utf-8' : MIME[path.extname(file)];
+    if (!type) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
+    res.writeHead(200, { ...SECURITY_HEADERS, 'Content-Type': type, 'Cache-Control': 'public, max-age=300' });
+    res.end(buf);
+  });
+}
+
+// ---- handlers ----
+function issueNonce(req, res) {
+  if (rateLimited(req, 'nonce', 30)) return send(res, 429, { error: 'Too many requests' });
+  const s = getSession(req, res, true);
+  s.nonce = crypto.randomBytes(24).toString('base64url');
+  s.nonceExpires = Date.now() + NONCE_TTL_MS;
+  send(res, 200, { nonce: s.nonce, expiresIn: NONCE_TTL_MS / 1000 });
+}
+
+async function verifyEmail(req, res) {
+  if (!sameOrigin(req)) return send(res, 403, { error: 'Cross-origin request rejected' });
+  if (rateLimited(req, 'verify', 10)) return send(res, 429, { error: 'Too many verification attempts' });
+  const s = getSession(req, res, false);
+  if (!s || !s.nonce || s.nonceExpires < Date.now()) return send(res, 400, { error: 'Verification session expired. Please re-enter your email.', code: 'bad_nonce' });
+
+  const body = await readJson(req);
+  // Nonces are single-use: consume before verifying so a token can't be replayed or brute-forced.
+  const nonce = s.nonce;
+  s.nonce = null;
+  s.verified = null;
+  try {
+    const { email, issuer } = await verifier.verify(body.token, nonce);
+    s.verified = { email, issuer, at: Date.now() };
+    return send(res, 200, { verified: true, email });
+  } catch (e) {
+    if (e instanceof EmailVerificationError) {
+      return send(res, 400, { verified: false, code: e.code, error: 'We could not confirm this email address with your email provider.' });
+    }
+    throw e;
+  }
+}
+
+async function signup(req, res) {
+  if (!sameOrigin(req)) return send(res, 403, { error: 'Cross-origin request rejected' });
+  if (rateLimited(req, 'signup', 5)) return send(res, 429, { error: 'Too many sign-up attempts. Try again in a minute.' });
+  const body = await readJson(req);
+
+  const name = typeof body.name === 'string' ? body.name.trim() : '';
+  const email = typeof body.email === 'string' ? body.email.trim() : '';
+  const password = typeof body.password === 'string' ? body.password : '';
+  const birthday = typeof body.birthday === 'string' && body.birthday ? body.birthday : null;
+  const errors = {};
+  if (!name || name.length > 80) errors.name = 'Please enter your name (up to 80 characters).';
+  const parts = splitEmail(email);
+  if (!parts || !/^[^\s@]+$/.test(parts.local)) errors.email = 'Please enter a valid email address.';
+  if (password.length < 10 || password.length > 128) errors.password = 'Password must be 10–128 characters.';
+  if (birthday && (!/^\d{4}-\d{2}-\d{2}$/.test(birthday) || Number.isNaN(Date.parse(birthday)))) errors.birthday = 'Invalid date.';
+  if (body.acceptTerms !== true) errors.acceptTerms = 'Please accept the Rewards terms.';
+  if (Object.keys(errors).length) return send(res, 422, { error: 'Please fix the highlighted fields.', fields: errors });
+
+  const normalized = `${parts.local}@${parts.domain}`;
+  const s = getSession(req, res, false);
+  const verified = !!(s && s.verified && s.verified.email.toLowerCase() === normalized.toLowerCase());
+  if (body.requireVerified === true && !verified) {
+    return send(res, 400, { error: 'Your email address has not been confirmed.', code: 'not_verified' });
+  }
+
+  if (members.findByEmail(normalized)) {
+    return send(res, 409, { error: 'An account with this email already exists. Try signing in instead.' });
+  }
+  const member = await members.create({
+    name,
+    email: normalized,
+    passwordHash: hashPassword(password),
+    birthday,
+    marketingOptIn: body.marketingOptIn === true,
+    emailVerified: verified,
+    emailIssuer: verified ? s.verified.issuer : null,
+  });
+  if (s) { s.verified = null; s.nonce = null; }
+
+  send(res, 201, {
+    memberNumber: member.memberNumber,
+    name: member.name,
+    email: member.email,
+    emailVerified: member.emailVerified,
+    points: member.points,
+  });
+}
+
+// ---- router ----
+const server = http.createServer(async (req, res) => {
+  try {
+    const url = new URL(req.url, PUBLIC_ORIGIN);
+    const p = url.pathname;
+    if (req.method === 'GET' && p === '/api/rewards/email-verification/nonce') return issueNonce(req, res);
+    if (req.method === 'POST' && p === '/api/rewards/email-verification/verify') return await verifyEmail(req, res);
+    if (req.method === 'POST' && p === '/api/rewards/signup') return await signup(req, res);
+    if (p.startsWith('/api/')) return send(res, 404, { error: 'Not found' });
+    if (req.method !== 'GET' && req.method !== 'HEAD') return send(res, 405, 'Method not allowed', 'text/plain; charset=utf-8');
+
+    if (p === '/' || p === '/index.html') return serveFile(res, path.join(ROOT, 'index.html'));
+    if (p.startsWith('/assets/')) {
+      let rel;
+      try { rel = decodeURIComponent(p.slice('/assets'.length)); } catch { rel = ''; }
+      const file = path.resolve(ASSETS_DIR, '.' + rel);
+      if (!file.startsWith(ASSETS_DIR + path.sep)) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
+      return serveFile(res, file);
+    }
+    send(res, 404, 'Not found', 'text/plain; charset=utf-8');
+  } catch (e) {
+    if (e && e.status) return send(res, e.status, { error: e.message });
+    console.error(e);
+    if (!res.headersSent) send(res, 500, { error: 'Something went wrong' });
+  }
+});
+
+server.listen(PORT, () => console.log(`The Daily Grind listening on ${PORT} (origin ${PUBLIC_ORIGIN})`));
diff --git a/test/email-verification.test.js b/test/email-verification.test.js
new file mode 100644
index 0000000..142f604
--- /dev/null
+++ b/test/email-verification.test.js
@@ -0,0 +1,84 @@
+'use strict';
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const crypto = require('node:crypto');
+const { createEmailVerifier, isPrivateAddress } = require('../lib/email-verification');
+
+const ORIGIN = 'https://dailygrind.example';
+const ISSUER = 'issuer.mail.example';
+const b64 = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
+
+function sign(header, payload, privateKey) {
+  const input = `${b64(header)}.${b64(payload)}`;
+  const alg = header.alg;
+  const sig = alg === 'EdDSA'
+    ? crypto.sign(null, Buffer.from(input), privateKey)
+    : crypto.sign('sha256', Buffer.from(input), { key: privateKey, dsaEncoding: 'ieee-p1363' });
+  return `${input}.${sig.toString('base64url')}`;
+}
+
+const issuerKeys = crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' });
+const issuerJwk = { ...issuerKeys.publicKey.export({ format: 'jwk' }), kid: 'k1', use: 'sig', alg: 'ES256' };
+const browserKeys = crypto.generateKeyPairSync('ed25519');
+const browserJwk = browserKeys.publicKey.export({ format: 'jwk' });
+
+function makeToken(o = {}) {
+  const now = Math.floor(Date.now() / 1000);
+  const sdJwt = sign(
+    { alg: 'ES256', kid: 'k1', typ: o.typ || 'evp+sd-jwt' },
+    { iss: o.iss || ISSUER, iat: o.iat ?? now, cnf: { jwk: browserJwk }, email: o.email || 'Ada@Example.com', email_verified: o.emailVerified ?? true },
+    o.issuerKey || issuerKeys.privateKey,
+  );
+  const sdHash = crypto.createHash('sha256').update(`${sdJwt}~`).digest('base64url');
+  const kb = sign(
+    { alg: 'EdDSA', typ: 'kb+jwt' },
+    { aud: o.aud || ORIGIN, nonce: o.nonce || 'nonce-123', iat: o.kbIat ?? now, sd_hash: o.sdHash || sdHash },
+    o.browserKey || browserKeys.privateKey,
+  );
+  return `${sdJwt}~${kb}`;
+}
+
+function verifier(overrides = {}) {
+  return createEmailVerifier({
+    origin: ORIGIN,
+    resolveTxt: async (name) => (name === '_email-verification.example.com' ? [[`iss=${ISSUER}`]] : []),
+    fetchJson: async (url) => {
+      if (url === `https://${ISSUER}/.well-known/email-verification`) {
+        return { issuance_endpoint: `https://${ISSUER}/issue`, jwks_uri: `https://${ISSUER}/jwks.json`, signing_alg_values_supported: ['ES256'] };
+      }
+      if (url === `https://${ISSUER}/jwks.json`) return { keys: [issuerJwk] };
+      throw new Error(`unexpected fetch ${url}`);
+    },
+    ...overrides,
+  });
+}
+
+const rejects = (p, code) => assert.rejects(p, (e) => e.code === code);
+
+test('accepts a valid presentation and normalises the domain', async () => {
+  assert.deepEqual(await verifier().verify(makeToken(), 'nonce-123'), { email: 'Ada@example.com', issuer: ISSUER });
+});
+
+test('rejects wrong nonce', () => rejects(verifier().verify(makeToken(), 'other'), 'bad_nonce'));
+test('rejects token minted for another site', () => rejects(verifier().verify(makeToken({ aud: 'https://evil.example' }), 'nonce-123'), 'bad_audience'));
+test('rejects stale key binding', () => rejects(verifier().verify(makeToken({ kbIat: Math.floor(Date.now() / 1000) - 3600 }), 'nonce-123'), 'expired'));
+test('rejects KB-JWT not signed by cnf key', () => rejects(verifier().verify(makeToken({ browserKey: crypto.generateKeyPairSync('ed25519').privateKey }), 'nonce-123'), 'bad_signature'));
+test('rejects mismatched sd_hash', () => rejects(verifier().verify(makeToken({ sdHash: 'x' }), 'nonce-123'), 'malformed'));
+test('rejects issuer token forged with another key', () => rejects(verifier().verify(makeToken({ issuerKey: crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' }).privateKey }), 'nonce-123'), 'bad_signature'));
+test('rejects email_verified=false', () => rejects(verifier().verify(makeToken({ emailVerified: false }), 'nonce-123'), 'unverified'));
+test('rejects issuer not delegated by the email domain', () => rejects(verifier().verify(makeToken({ iss: 'evil-issuer.example' }), 'nonce-123'), 'bad_issuer'));
+test('rejects domain with no DNS delegation', () => rejects(verifier().verify(makeToken({ email: 'a@other.example' }), 'nonce-123'), 'no_issuer'));
+test('rejects wrong typ', () => rejects(verifier().verify(makeToken({ typ: 'JWT' }), 'nonce-123'), 'malformed'));
+test('rejects alg none / garbage', async () => {
+  const none = `${b64({ alg: 'none', typ: 'evp+sd-jwt' })}.${b64({})}.`;
+  await rejects(verifier().verify(`${none}~${none}`, 'nonce-123'), 'malformed');
+  await rejects(verifier().verify('not-a-token', 'nonce-123'), 'malformed');
+});
+test('rejects jwks_uri on a different host', () => rejects(verifier({
+  fetchJson: async () => ({ jwks_uri: 'https://attacker.example/jwks.json' }),
+}).verify(makeToken(), 'nonce-123'), 'bad_issuer'));
+
+test('private address detection', () => {
+  for (const ip of ['127.0.0.1', '10.1.2.3', '169.254.169.254', '192.168.0.1', '::1', 'fd00::1', '::ffff:10.0.0.1']) assert.ok(isPrivateAddress(ip), ip);
+  for (const ip of ['8.8.8.8', '2606:4700::1111']) assert.ok(!isPrivateAddress(ip), ip);
+});

