+        }).join(', '));
+
+        var legend = document.createElement('ul');
+        legend.className = 'legend';
+        legend.setAttribute('aria-hidden', 'true');
+
+        var a = 0;
+        CATS.forEach(function (c, i) {
+          var pct = Math.round(vals[i] / total * 100);
