@@ -0,0 +1,115 @@
+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Visually Stable Mixed Fonts</title>
+  <style>
+    :root {
+      color-scheme: light dark;
+    }
+
+    body {
+      margin: 0;
+      padding: 2rem;
+      font-family: system-ui, sans-serif;
+      line-height: 1.5;
+      max-width: 60rem;
+      margin-inline: auto;
+    }
+
+    section {
+      margin-block: 2rem;
+      padding: 1.5rem;
+      border: 1px solid color-mix(in srgb, currentColor 25%, transparent);
+      border-radius: 0.75rem;
+    }
+
+    h2 {
+      margin-block-start: 0;
+      font-size: 1.25rem;
+    }
+
+    /* 1. Mixed fonts: normalize x-height automatically.
+       `from-font` reads the x-height ratio of the primary (Georgia) font and
+       applies it to descendants, so inline monospace code matches visually. */
+    #mixed-fonts-container {
+      font-family: Georgia, "Times New Roman", serif;
+      font-size: 1.125rem;
+      font-size-adjust: from-font;
+    }
+
+    #mixed-fonts-container code {
+      font-family: ui-monospace, "Courier New", Courier, monospace;
+      /* Reset the UA's shrunken monospace size so font-size-adjust does the work */
+      font-size: 1em;
+      padding: 0.1em 0.3em;
+      border-radius: 0.25em;
+      background: color-mix(in srgb, currentColor 10%, transparent);
+    }
+
+    /* 2. Independent theme: not a descendant of the primary font, so lock its
+       proportions with an explicit numeric x-height / font-size ratio. */
+    #independent-theme-container {
+      font-family: "Times New Roman", Times, serif;
+      font-size: 1.125rem;
+      /* Match the x-height ratio of a Verdana-like primary font */
+      font-size-adjust: 0.545;
