+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8" />
+  <meta name="viewport" content="width=device-width, initial-scale=1" />
+  <title>font-size-adjust Demo</title>
+  <style>
+    :root {
+      color-scheme: light dark;
+      font-family: Georgia, "Times New Roman", serif;
+      line-height: 1.6;
+    }
+
+    body {
+      max-width: 48rem;
+      margin: 3rem auto;
+      padding: 0 1.5rem;
+    }
+
+    section {
+      padding: 1.25rem 1.5rem;
+      margin-block: 1.5rem;
+      border: 1px solid color-mix(in srgb, currentColor 20%, transparent);
+      border-radius: 0.75rem;
+    }
+
+    h2 { margin-top: 0; }
+
+    code {
+      font-family: "Courier New", Courier, ui-monospace, monospace;
+      padding: 0.1em 0.3em;
+      border-radius: 0.25em;
+      background: color-mix(in srgb, currentColor 10%, transparent);
+    }
+
+    /*
+     * Mixed fonts: normalize visual (x-)height automatically.
+     * `from-font` reads the ex-height/font-size ratio of the first available
+     * primary font and applies it to every fallback/inline font, so the
+     * monospace <code> runs match the x-height of the surrounding serif text.
+     * The keyword value is inherited as the *computed number*, so descendants
+     * (including <code>) are scaled to the same aspect.
+     */
+    #mixed-fonts-container {
+      font-size-adjust: from-font;
+    }
+
+    /*
+     * Independent theme: lock proportions with an explicit metric + number.
+     * Every font inside resolves so that its x-height is exactly 0.5 × font-size,
+     * regardless of which font in the stack actually loads.
+     */
+    #independent-theme-container {
+      font-family: Verdana, "Trebuchet MS", system-ui, sans-serif;
+      font-size-adjust: ex-height 0.5;
+      background: color-mix(in srgb, #4f46e5 12%, Canvas);
+      border-color: #4f46e5;
+    }
+
+    #independent-theme-container code {
+      font-family: "Courier New", ui-monospace, monospace;
+    }
+
+    @supports not (font-size-adjust: from-font) {
+      .support-note { display: block; }
+    }
+    .support-note {
+      display: none;
+      font-size: 0.875rem;
+      opacity: 0.75;
+    }
+  </style>
+</head>
+<body>
+  <h1>Normalizing mixed fonts with <code>font-size-adjust</code></h1>
+
+  <section id="mixed-fonts-container">
+    <h2>Mixed font families</h2>
+    <p>
+      This paragraph is set in a serif face, but it embeds inline code such as
+      <code>const visualHeight = fontSize * aspect;</code> and
+      <code>font-size-adjust: from-font</code>. Thanks to
+      <code>font-size-adjust: from-font</code>, the monospace runs are scaled so
+      their lowercase letters sit at the same x-height as the surrounding text,
+      instead of looking noticeably smaller or larger.
+    </p>
+  </section>
+
+  <section id="independent-theme-container">
+    <h2>Independent theme</h2>
+    <p>
+      This container uses its own font stack and pins proportions with
+      <code>font-size-adjust: ex-height 0.5</code>. Whichever font in the stack
+      ends up rendering — Verdana, a fallback, or the inline
+      <code>monospace</code> — its x-height is locked to exactly half the
+      font size, keeping the theme's visual rhythm stable.
+    </p>
+  </section>
+
+  <p class="support-note">
+    Your browser doesn't support the modern <code>font-size-adjust</code>
+    syntax, so fonts render at their natural proportions.
+  </p>
+</body>
+</html>

