+/**
+ * <coffee-card> — a menu item card with an optional image, price, call-to-action
+ * link and a "favorite" toggle.
+ *
+ * Light DOM API (slots):
+ *   slot="media"   an <img> (decorative or with alt text)
+ *   slot="title"   the item heading (e.g. <h3>)
+ *   (default)      description content
+ *   slot="action"  a link/button such as "View details"
+ *
+ * Attributes:
+ *   item-id     stable id used to persist the favorite state (localStorage)
+ *   price       numeric price, formatted with Intl.NumberFormat
+ *   currency    ISO currency code (default "USD")
+ *   category    free-form category, used by <coffee-filter>
+ *   favorited   boolean, reflects the favorite toggle
+ *
+ * Events:
+ *   favorite-change  { detail: { id, name, favorited } } — bubbles, composed
+ *
+ * Theming: --dg-primary, --dg-accent, --dg-surface, --dg-radius, --dg-shadow
+ * Parts:   card, media, body, price, favorite
+ */
+
+const STORAGE_KEY = 'daily-grind:favorites';
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_primary-strong: var(--dg-primary-strong, #3e2723);
+    --_accent: var(--dg-accent, #ffab40);
+    --_surface: var(--dg-surface, #fff);
+    --_radius: var(--dg-radius, 8px);
+    --_shadow: var(--dg-shadow, 0 2px 5px rgb(0 0 0 / 0.1));
+
+    display: block;
+    container-type: inline-size;
+  }
+  :host([hidden]) { display: none; }
+
+  article {
+    position: relative;
+    display: flex;
+    flex-direction: column;
+    block-size: 100%;
+    overflow: hidden;
+    background: var(--_surface);
+    border-radius: var(--_radius);
+    box-shadow: var(--_shadow);
+    transition: box-shadow 0.2s, translate 0.2s;
+  }
+  article:hover { box-shadow: 0 8px 20px rgb(0 0 0 / 0.15); }
+  @media (prefers-reduced-motion: no-preference) {
+    article:hover { translate: 0 -2px; }
+  }
+
+  .media {
+    aspect-ratio: 4 / 3;
+    background: var(--dg-secondary, #d7ccc8);
+  }
+  .media[hidden] { display: none; }
+  ::slotted([slot="media"]) {
+    display: block;
+    inline-size: 100%;
+    block-size: 100%;
+    object-fit: cover;
+  }
+
+  .body {
+    display: flex;
+    flex-direction: column;
+    flex: 1;
+    gap: 0.5rem;
+    padding: 1.25rem;
+    text-align: center;
+  }
+  ::slotted([slot="title"]) {
+    margin: 0;
+    color: var(--_primary);
+    font-size: 1.25rem;
+  }
+  ::slotted(:not([slot])) { margin: 0; }
+
+  .price {
+    margin: 0;
+    font-weight: 700;
+    color: var(--_primary);
+  }
+  .price:empty { display: none; }
+
+  footer {
+    margin-block-start: auto;
+    padding-block-start: 0.5rem;
+  }
+  ::slotted([slot="action"]) {
+    display: inline-block;
+    background: var(--_primary);
+    color: #fff;
+    padding: 10px 20px;
+    border-radius: 5px;
+    text-decoration: none;
+    transition: background 0.3s;
+  }
+  ::slotted([slot="action"]:hover) { background: var(--_primary-strong); }
+  ::slotted([slot="action"]:focus-visible) {
+    outline: 3px solid var(--_accent);
+    outline-offset: 2px;
+  }
+
+  .favorite {
+    position: absolute;
+    inset-block-start: 0.75rem;
+    inset-inline-end: 0.75rem;
+    display: grid;
+    place-items: center;
+    inline-size: 2.75rem;
+    block-size: 2.75rem;
+    padding: 0;
+    border: 0;
+    border-radius: 50%;
+    background: rgb(255 255 255 / 0.92);
+    color: var(--_primary);
+    box-shadow: 0 1px 4px rgb(0 0 0 / 0.2);
+    cursor: pointer;
+    font: inherit;
+  }
+  .favorite:focus-visible {
+    outline: 3px solid var(--_accent);
+    outline-offset: 2px;
+  }
+  .favorite svg {
+    inline-size: 1.4rem;
+    block-size: 1.4rem;
+    fill: transparent;
+    stroke: currentColor;
+    stroke-width: 2;
+    transition: fill 0.2s, scale 0.2s;
+  }
+  .favorite[aria-pressed="true"] { color: #c62828; }
+  .favorite[aria-pressed="true"] svg { fill: currentColor; }
+  @media (prefers-reduced-motion: no-preference) {
+    .favorite:active svg { scale: 0.85; }
+  }
+  /* Without media the button sits over the body text; reserve space. */
+  article.no-media .body { padding-block-start: 3.5rem; }
+
+  .vh {
+    position: absolute;
+    inline-size: 1px;
+    block-size: 1px;
+    overflow: hidden;
+    clip-path: inset(50%);
+    white-space: nowrap;
+  }
+
+  @media (forced-colors: active) {
+    .favorite { border: 1px solid ButtonText; }
+    .favorite[aria-pressed="true"] svg { fill: ButtonText; }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <article part="card" class="no-media">
+    <div class="media" part="media" hidden><slot name="media"></slot></div>
+    <div class="body" part="body">
+      <slot name="title"></slot>
+      <slot></slot>
+      <p class="price" part="price"></p>
+      <footer><slot name="action"></slot></footer>
+    </div>
+    <button type="button" class="favorite" part="favorite" aria-pressed="false">
+      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
+        <path d="M12 21s-7.5-4.6-9.6-9.2C.9 8.4 3 4.5 6.7 4.5c2.1 0 3.6 1.1 5.3 3 1.7-1.9 3.2-3 5.3-3 3.7 0 5.8 3.9 4.3 7.3C19.5 16.4 12 21 12 21z"/>
+      </svg>
+      <span class="vh"></span>
+    </button>
+  </article>
+`;
+
+function readFavorites() {
+  try {
+    return new Set(JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]'));
+  } catch {
+    return new Set();
+  }
+}
+
+function writeFavorite(id, on) {
+  try {
+    const favorites = readFavorites();
+    on ? favorites.add(id) : favorites.delete(id);
+    localStorage.setItem(STORAGE_KEY, JSON.stringify([...favorites]));
+  } catch {
+    /* Storage unavailable (private mode, quota) — state stays in-memory. */
+  }
+}
+
+export class CoffeeCard extends HTMLElement {
+  static observedAttributes = ['price', 'currency', 'favorited'];
+
+  #button;
+  #label;
+  #price;
+  #titleSlot;
+  #actionSlot;
+  #mediaSlot;
+  #media;
+  #article;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    root.append(template.content.cloneNode(true));
+
+    this.#button = root.querySelector('.favorite');
+    this.#label = root.querySelector('.vh');
+    this.#price = root.querySelector('.price');
+    this.#titleSlot = root.querySelector('slot[name="title"]');
+    this.#actionSlot = root.querySelector('slot[name="action"]');
+    this.#mediaSlot = root.querySelector('slot[name="media"]');
+    this.#media = root.querySelector('.media');
+    this.#article = root.querySelector('article');
+
+    this.#button.addEventListener('click', () => this.toggleFavorite());
+    this.#titleSlot.addEventListener('slotchange', () => this.#syncLabels());
+    this.#actionSlot.addEventListener('slotchange', () => this.#syncLabels());
+    this.#mediaSlot.addEventListener('slotchange', () => {
+      const hasMedia = this.#mediaSlot.assignedElements().length > 0;
+      this.#media.hidden = !hasMedia;
+      this.#article.classList.toggle('no-media', !hasMedia);
+    });
+  }
+
+  connectedCallback() {
+    // Restore persisted state (idempotent; may run on every insertion).
+    if (this.itemId && readFavorites().has(this.itemId)) {
+      this.toggleAttribute('favorited', true);
+    }
+    this.#renderPrice();
+    this.#renderFavorite();
+    this.#syncLabels();
+  }
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal === newVal) return;
+    if (name === 'favorited') this.#renderFavorite();
+    else this.#renderPrice();
+  }
+
+  get itemId() { return this.getAttribute('item-id') ?? ''; }
+  set itemId(v) { this.setAttribute('item-id', v); }
+
+  get price() {
+    const n = parseFloat(this.getAttribute('price'));
+    return Number.isFinite(n) ? n : null;
+  }
+  set price(v) {
+    v == null ? this.removeAttribute('price') : this.setAttribute('price', String(v));
+  }
+
+  get category() { return this.getAttribute('category') ?? ''; }
+  set category(v) { this.setAttribute('category', v); }
+
+  get favorited() { return this.hasAttribute('favorited'); }
+  set favorited(on) { this.toggleAttribute('favorited', Boolean(on)); }
+
+  /** The item's display name, taken from the slotted title. */
+  get name() {
+    return this.#titleSlot.assignedElements()[0]?.textContent.trim() ?? '';
+  }
+
+  toggleFavorite(force = !this.favorited) {
+    this.favorited = force;
+    if (this.itemId) writeFavorite(this.itemId, force);
+    this.dispatchEvent(new CustomEvent('favorite-change', {
+      bubbles: true,
+      composed: true,
