+      this.#price.textContent = '';
+      return;
+    }
+    const currency = this.getAttribute('currency') || 'USD';
+    try {
+      this.#price.textContent = new Intl.NumberFormat(document.documentElement.lang || undefined, {
+        style: 'currency',
+        currency,
+      }).format(price);
+    } catch {
+      this.#price.textContent = String(price);
+    }
+  }
+
+  #syncLabels() {
+    const name = this.name;
+    // Static accessible name; the pressed state is conveyed by aria-pressed.
+    this.#label.textContent = name ? `Favorite ${name}` : 'Favorite';
+
+    // Give generic "View details" links context from the card title so each
+    // link is distinguishable out of context (WCAG 2.4.4). Both nodes live in
+    // the same (light DOM) tree, so element references resolve.
+    const title = this.#titleSlot.assignedElements()[0];
+    for (const action of this.#actionSlot.assignedElements()) {
+      if (!title || action.hasAttribute('aria-describedby')) continue;
+      if ('ariaDescribedByElements' in Element.prototype) {
