@@ -0,0 +1,201 @@
+/**
+ * <coffee-filter> — lays out its child items in a responsive grid and offers a
+ * native radio group to filter them by their `category` attribute.
+ *
+ * Usage:
+ *   <coffee-filter label="Filter drinks" noun="drinks">
+ *     <coffee-card category="hot">…</coffee-card>
+ *     <coffee-card category="iced">…</coffee-card>
+ *   </coffee-filter>
+ *
+ * Attributes:
+ *   label   legend for the filter group (default "Filter")
+ *   noun    plural noun used in the result announcement (default "items")
+ *   value   currently selected category ("all" or a category); reflected
+ *
+ * Events:
+ *   change  fired when the user picks a different filter (bubbles)
+ *
+ * Theming: --dg-primary, --dg-accent, --dg-grid-min, --dg-gap
+ * Parts:   controls, option, grid, status
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_accent: var(--dg-accent, #ffab40);
+    display: block;
+  }
+  :host([hidden]) { display: none; }
+
+  fieldset {
+    display: flex;
+    flex-wrap: wrap;
+    justify-content: center;
+    gap: 0.5rem;
+    margin: 0 0 0.5rem;
+    padding: 0;
+    border: 0;
+  }
+  legend {
+    inline-size: 100%;
+    margin-block-end: 0.5rem;
+    padding: 0;
+    text-align: center;
+    font-weight: 600;
+  }
+
+  label {
+    position: relative;
+    display: inline-flex;
+    align-items: center;
+    min-block-size: 2.75rem;
+    padding: 0.4rem 1.1rem;
+    border: 2px solid var(--_primary);
+    border-radius: 999px;
+    color: var(--_primary);
+    background: transparent;
+    cursor: pointer;
+    font-size: 0.95rem;
+    transition: background 0.2s, color 0.2s;
+  }
+  label:hover { background: color-mix(in srgb, var(--_primary) 10%, transparent); }
+  label:has(:checked) {
+    background: var(--_primary);
+    color: #fff;
+  }
+  label:has(:focus-visible) {
+    outline: 3px solid var(--_accent);
+    outline-offset: 2px;
+  }
+  /* Keep the native radio for semantics and keyboard support, visually hidden. */
+  input {
+    position: absolute;
+    inset: 0;
+    margin: 0;
+    opacity: 0;
+    cursor: pointer;
+  }
+
+  .status {
+    margin: 0 0 1rem;
+    text-align: center;
+    font-size: 0.9rem;
+    color: color-mix(in srgb, currentColor 75%, transparent);
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--dg-grid-min, 250px)), 1fr));
+    gap: var(--dg-gap, 20px);
+  }
+
+  @media (forced-colors: active) {
+    label:has(:checked) { outline: 2px solid Highlight; }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <fieldset part="controls">
+    <legend></legend>
+  </fieldset>
+  <p class="status" part="status" role="status"></p>
+  <div class="grid" part="grid"><slot></slot></div>
+`;
+
+const capitalize = (s) => s.charAt(0).toUpperCase() + s.slice(1);
+
+export class CoffeeFilter extends HTMLElement {
+  static observedAttributes = ['label', 'value'];
+
+  #fieldset;
+  #legend;
+  #status;
+  #slot;
+  #categories = [];
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    root.append(template.content.cloneNode(true));
+
+    this.#fieldset = root.querySelector('fieldset');
+    this.#legend = root.querySelector('legend');
+    this.#status = root.querySelector('.status');
+    this.#slot = root.querySelector('slot');
+
+    this.#slot.addEventListener('slotchange', () => this.#update());
+    this.#fieldset.addEventListener('change', (e) => {
+      this.value = e.target.value;
+      this.dispatchEvent(new Event('change', { bubbles: true }));
+    });
+  }
+
+  connectedCallback() {
+    this.#legend.textContent = this.getAttribute('label') || 'Filter';
+    this.#update();
+  }
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal === newVal) return;
+    if (name === 'label') this.#legend.textContent = newVal || 'Filter';
+    else this.#update();
+  }
+
+  get value() { return this.getAttribute('value') || 'all'; }
+  set value(v) { this.setAttribute('value', v); }
+
+  get #items() {
+    return this.#slot.assignedElements();
+  }
+
+  #update() {
+    const items = this.#items;
+    const categories = [...new Set(items.map((el) => el.getAttribute('category')).filter(Boolean))];
+
+    // Only rebuild the radios when the set of categories actually changes, so
+    // a focused radio is never replaced underneath the user.
+    if (categories.join('|') !== this.#categories.join('|')) {
+      this.#categories = categories;
+      this.#renderOptions();
+    }
+
+    let value = this.value;
+    if (value !== 'all' && !categories.includes(value)) value = 'all';
+
+    for (const input of this.#fieldset.querySelectorAll('input')) {
+      input.checked = input.value === value;
+    }
+
+    let shown = 0;
+    for (const item of items) {
+      const match = value === 'all' || item.getAttribute('category') === value;
+      item.hidden = !match;
+      if (match) shown++;
+    }
+
+    const noun = this.getAttribute('noun') || 'items';
+    this.#status.textContent = `Showing ${shown} of ${items.length} ${noun}`;
+  }
+
+  #renderOptions() {
+    for (const label of this.#fieldset.querySelectorAll('label')) label.remove();
+    for (const category of ['all', ...this.#categories]) {
+      const label = document.createElement('label');
+      label.part = 'option';
+      const input = document.createElement('input');
+      input.type = 'radio';
+      input.name = 'category';
+      input.value = category;
+      label.append(input, category === 'all' ? 'All' : capitalize(category));
+      this.#fieldset.append(label);
+    }
+  }
+}
+
+if (!customElements.get('coffee-filter')) {
+  customElements.define('coffee-filter', CoffeeFilter);
+}
