+/**
+ * <site-nav> — sticky site header with a brand slot and a set of links that
+ * collapse into a disclosure menu when the component itself is narrow.
+ *
+ * Usage:
+ *   <site-nav label="Main">
+ *     <a slot="brand" href="/">The Daily Grind</a>
+ *     <a href="/menu">Menu</a>
+ *     <a href="/logout" data-variant="outline">Logout</a>
+ *   </site-nav>
+ *
+ * Attributes:
+ *   label  accessible name of the navigation landmark (default "Main")
+ *
+ * Theming: --dg-primary, --dg-accent
+ * Parts:   bar, toggle, menu
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_accent: var(--dg-accent, #ffab40);
+    display: block;
+    position: sticky;
+    inset-block-start: 0;
+    z-index: 1000;
+    container-type: inline-size;
+    background: var(--_primary);
+    color: #fff;
+  }
+  :host([hidden]) { display: none; }
+
+  nav {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    justify-content: space-between;
+    gap: 0.5rem 1.25rem;
+    padding: 1rem 5%;
+  }
+
+  ::slotted([slot="brand"]) {
+    color: inherit;
+    font-size: 1.5rem;
+    font-weight: bold;
+    letter-spacing: 1px;
+    text-decoration: none;
+    text-transform: uppercase;
+  }
+
+  .menu {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    gap: 0.5rem 1.25rem;
+  }
+
+  ::slotted(a:not([slot])) {
+    color: inherit;
+    font-size: 0.9rem;
+    text-decoration: none;
+    padding-block: 0.25rem;
+    transition: color 0.3s;
+  }
+  ::slotted(a:not([slot]):hover) { color: var(--_accent); }
+  ::slotted(a[aria-current="page"]) {
+    text-decoration: underline;
+    text-underline-offset: 0.3em;
+  }
+  ::slotted(a[data-variant="outline"]:not([slot])) {
+    border: 1px solid var(--_accent);
+    padding: 5px 12px;
+    border-radius: 4px;
+  }
+  ::slotted(a:focus-visible) {
+    outline: 3px solid var(--_accent);
+    outline-offset: 3px;
+  }
+
+  .toggle {
+    display: none;
+    align-items: center;
+    gap: 0.5rem;
+    min-block-size: 2.75rem;
+    padding: 0.4rem 0.9rem;
+    border: 1px solid currentColor;
+    border-radius: 4px;
+    background: transparent;
+    color: inherit;
+    font: inherit;
+    cursor: pointer;
+  }
+  .toggle:focus-visible {
+    outline: 3px solid var(--_accent);
+    outline-offset: 2px;
+  }
+  .toggle svg { inline-size: 1.25rem; block-size: 1.25rem; }
+  .toggle .bar { transition: rotate 0.2s, opacity 0.2s, translate 0.2s; transform-origin: center; transform-box: fill-box; }
+  .toggle[aria-expanded="true"] .top { rotate: 45deg; translate: 0 6px; }
+  .toggle[aria-expanded="true"] .mid { opacity: 0; }
+  .toggle[aria-expanded="true"] .bot { rotate: -45deg; translate: 0 -6px; }
+  @media (prefers-reduced-motion: reduce) {
+    .toggle .bar { transition: none; }
+  }
+
+  /* Collapse based on the space the component has, not the viewport. */
+  @container (max-width: 44rem) {
+    .toggle { display: inline-flex; }
+    .menu {
+      flex-basis: 100%;
+      flex-direction: column;
+      align-items: stretch;
+      gap: 0;
+      padding-block-start: 0.5rem;
+    }
+    .menu[hidden] { display: none; }
+    ::slotted(a:not([slot])) {
+      padding-block: 0.75rem;
+      border-block-start: 1px solid rgb(255 255 255 / 0.15);
+    }
+    ::slotted(a[data-variant="outline"]:not([slot])) {
+      margin-block-start: 0.75rem;
+      text-align: center;
+    }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <nav part="bar">
+    <slot name="brand"></slot>
+    <button type="button" class="toggle" part="toggle" aria-expanded="false" aria-controls="menu">
+      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="currentColor">
+        <rect class="bar top" x="3" y="5" width="18" height="2" rx="1"/>
+        <rect class="bar mid" x="3" y="11" width="18" height="2" rx="1"/>
+        <rect class="bar bot" x="3" y="17" width="18" height="2" rx="1"/>
+      </svg>
+      Menu
+    </button>
+    <div class="menu" part="menu" id="menu"><slot></slot></div>
+  </nav>
+`;
