+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    root.append(template.content.cloneNode(true));
+
+    this.#nav = root.querySelector('nav');
+    this.#toggle = root.querySelector('.toggle');
+    this.#menu = root.querySelector('.menu');
+
+    this.#toggle.addEventListener('click', () => this.toggle());
+    this.addEventListener('keydown', (e) => {
+      if (e.key === 'Escape' && this.open) {
+        this.toggle(false);
+        this.#toggle.focus();
+      }
+    });
+    // Close after choosing a link (useful for in-page anchors).
+    this.#menu.addEventListener('click', (e) => {
+      if (this.#collapsed && e.target.closest('a')) this.toggle(false);
+    });
+    // Close when focus leaves the component while the menu is expanded.
+    this.addEventListener('focusout', (e) => {
+      if (this.#collapsed && this.open && !this.contains(e.relatedTarget)
+          && !this.shadowRoot.contains(e.relatedTarget)) {
+        this.toggle(false);
+      }
+    });
+  }
+
+  connectedCallback() {
+    this.#nav.ariaLabel = this.getAttribute('label') || 'Main';
+    // Track whether the container query has collapsed the menu so the hidden
+    // state only applies in the compact layout.
+    this.#observer ??= new ResizeObserver(() => this.#syncCollapsed());
+    this.#observer.observe(this);
+    this.#syncCollapsed();
+  }
+
+  disconnectedCallback() {
+    this.#observer?.disconnect();
+  }
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal !== newVal) this.#nav.ariaLabel = newVal || 'Main';
+  }
