+  #syncCollapsed() {
+    const collapsed = getComputedStyle(this.#toggle).display !== 'none';
+    if (collapsed === this.#collapsed) return;
+    this.#collapsed = collapsed;
+    this.toggle(false);
+  }
+}
+
+if (!customElements.get('site-nav')) {
+  customElements.define('site-nav', SiteNav);
+}
