+  set open(value) {
+    const isOpen = Boolean(value);
+    this.#toggle.setAttribute('aria-expanded', String(isOpen));
+    this.#links.dataset.open = String(isOpen);
+    this.toggleAttribute('open', isOpen);
+  }
+
+  #onToggle = () => {
+    this.open = !this.open;
+    if (this.open) this.querySelector('[slot="links"]')?.focus();
+  };
+
+  #onLinkClick = (e) => {
+    if (this.#mq.matches && e.target.closest?.('a')) this.open = false;
+  };
+
+  #onKeydown = (e) => {
+    if (e.key === 'Escape' && this.open) {
+      this.open = false;
+      this.#toggle.focus();
+    }
+  };
+
+  #onDocumentClick = (e) => {
+    if (this.open && !e.composedPath().includes(this)) this.open = false;
+  };
+
+  #onBreakpoint = () => { this.open = false; };
+}
