+/**
+ * Shared constructable stylesheets adopted by every Daily Grind component.
+ * Design tokens are CSS custom properties, which inherit through shadow
+ * boundaries, so pages can theme components by overriding --dg-* on :root.
+ */
+const sheet = (css) => {
+  const s = new CSSStyleSheet();
+  s.replaceSync(css);
+  return s;
+};
+
+export const baseStyles = sheet(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_primary-dark: var(--dg-primary-dark, #3e2723);
+    --_secondary: var(--dg-secondary, #d7ccc8);
+    --_accent: var(--dg-accent, #ffab40);
+    --_text: var(--dg-text, #3e2723);
+    --_surface: var(--dg-surface, #ffffff);
+    --_radius: var(--dg-radius, 8px);
+    --_focus: var(--dg-focus-ring, 3px solid var(--_accent));
+    box-sizing: border-box;
+  }
+  :host([hidden]) { display: none !important; }
+  *, *::before, *::after { box-sizing: inherit; }
+
+  .visually-hidden {
+    position: absolute !important;
+    width: 1px; height: 1px;
+    padding: 0; margin: -1px;
+    overflow: hidden;
+    clip: rect(0 0 0 0);
+    white-space: nowrap;
+    border: 0;
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    *, *::before, *::after,
+    ::slotted(*) {
+      transition: none !important;
+      animation: none !important;
+    }
+  }
+`);
+
+/** Button look applied to slotted call-to-action links. */
+export const buttonCss = (selector) => `
+  ${selector} {
+    display: inline-block;
+    background: var(--_primary);
+    color: #fff;
+    padding: 10px 20px;
+    text-decoration: none;
+    border-radius: 5px;
+    font: inherit;
+    transition: background-color 0.3s;
+  }
+  ${selector}:hover { background: var(--_primary-dark); }
+  ${selector}:focus-visible { outline: var(--_focus); outline-offset: 3px; }
+`;
+
+let uid = 0;
+/** Ensure an element has an id (for ARIA references) and return it. */
+export const ensureId = (el, prefix = 'dg') => {
+  if (!el.id) el.id = `${prefix}-${++uid}`;
+  return el.id;
+};
