+import { useEffect } from 'react';
+import { useWebMCP } from 'use-webmcp-tool';
+
+interface Props {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  tags: string[];
+  readingTime?: number;
+  url: string;
+  /** id of the element wrapping the rendered article body. */
+  bodyId: string;
+}
+
+const HIGHLIGHT_NAME = 'article-find';
+const MAX_MATCHES = 20;
+const WORDS_PER_MINUTE = 230;
+
+function getBody(bodyId: string): HTMLElement | null {
+  return document.getElementById(bodyId);
+}
+
+function getBodyText(body: HTMLElement): string {
+  return (body.innerText || body.textContent || '').replace(/\n{3,}/g, '\n\n').trim();
+}
+
+function clearHighlights() {
+  if ('highlights' in CSS) CSS.highlights.delete(HIGHLIGHT_NAME);
+}
+
+/** Article-page WebMCP tools. Renders nothing. */
+export default function ArticleAgentTools(props: Props) {
+  const { slug, title, summary, author, date, category, tags, readingTime, url, bodyId } = props;
+
+  // Drop any find highlight when leaving the article.
+  useEffect(() => clearHighlights, []);
+
+  useWebMCP({
+    name: 'get_current_article',
+    description: 'Returns the article the reader is viewing, including its full text. Use to summarize, quote, or answer questions about it.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    execute() {
+      const body = getBody(bodyId);
+      if (!body) return { error: 'The article body is not available on this page.' };
+      const text = getBodyText(body);
+      const wordCount = text.split(/\s+/).filter(Boolean).length;
+      return {
+        slug,
+        title,
+        summary,
+        author,
+        publishedOn: date,
+        category,
+        tags,
+        url,
+        wordCount,
+        readingTimeMinutes: readingTime ?? Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE)),
+        headings: Array.from(body.querySelectorAll('h2, h3'), (heading) => heading.textContent?.trim() ?? ''),
+        text,
+      };
+    },
+  });
+
+  useWebMCP<{ text?: unknown }>({
+    name: 'find_in_article',
+    description: 'Finds a word or phrase in the article being viewed, highlights every occurrence, and scrolls the first one into view. Returns the surrounding passages.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        text: { type: 'string', description: 'Word or phrase to look for, matched case-insensitively.' },
+      },
+      required: ['text'],
+    },
+    annotations: { readOnlyHint: true },
+    execute({ text }) {
+      if (typeof text !== 'string' || !text.trim()) {
+        return { error: 'Pass a non-empty word or phrase to find.' };
+      }
+      const body = getBody(bodyId);
+      if (!body) return { error: 'The article body is not available on this page.' };
+
+      const needle = text.trim().toLowerCase();
+      const ranges: Range[] = [];
+      const passages: string[] = [];
+      let total = 0;
+
+      // Walk text nodes rather than rewriting markup so the DOM stays untouched.
+      const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT);
+      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
+        const content = node.textContent ?? '';
+        const haystack = content.toLowerCase();
+        for (let index = haystack.indexOf(needle); index !== -1; index = haystack.indexOf(needle, index + needle.length)) {
+          total++;
+          const range = new Range();
+          range.setStart(node, index);
+          range.setEnd(node, index + needle.length);
+          ranges.push(range);
+
+          if (passages.length < MAX_MATCHES) {
+            const block = node.parentElement?.closest('p, li, blockquote, h2, h3, h4, td') ?? node.parentElement;
+            const passage = block?.textContent?.trim() ?? content.trim();
+            if (!passages.includes(passage)) passages.push(passage);
+          }
+        }
+      }
+
+      clearHighlights();
+      if (total === 0) return { text, matchCount: 0, passages: [] };
+
+      if ('highlights' in CSS) {
+        CSS.highlights.set(HIGHLIGHT_NAME, new Highlight(...ranges));
+      }
+      const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
+      ranges[0].startContainer.parentElement?.scrollIntoView({
+        block: 'center',
+        behavior: reduceMotion ? 'auto' : 'smooth',
+      });
+
+      return { text, matchCount: total, passages };
+    },
+  });
+
+  return null;
+}
