diff --git a/src/components/SiteAgentTools.tsx b/src/components/SiteAgentTools.tsx
new file mode 100644
index 0000000..855109b
--- /dev/null
+++ b/src/components/SiteAgentTools.tsx
@@ -0,0 +1,101 @@
+import { useWebMCP } from 'use-webmcp-tool';
+import { navigate } from 'astro:transitions/client';
+import { articleUrl, fetchArticles } from '../utils/articles';
+import { fetchReadingList, setReadingListItem } from '../utils/readingList';
+
+interface Props {
+  categories: string[];
+}
+
+const BASE_URL = import.meta.env.BASE_URL;
+
+/**
+ * Site-wide WebMCP tools. Renders nothing; each tool is registered while this
+ * island is mounted and unregistered automatically when it unmounts.
+ */
+export default function SiteAgentTools({ categories }: Props) {
+  useWebMCP({
+    name: 'get_reading_list',
+    description: "Lists the articles the reader has saved to their reading list.",
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute(_args, { signal }) {
+      const [readingList, articles] = await Promise.all([fetchReadingList(signal), fetchArticles()]);
+      const saved = readingList.map((slug) => {
+        const article = articles.find((entry) => entry.slug === slug);
+        return { slug, title: article?.title ?? slug, summary: article?.summary ?? '', url: articleUrl(slug) };
+      });
+      return { count: saved.length, articles: saved };
+    },
+  });
+
+  useWebMCP<{ slug?: unknown }>({
+    name: 'remove_from_reading_list',
+    description: "Removes a saved article from the reader's reading list.",
+    inputSchema: {
+      type: 'object',
+      properties: {
+        slug: { type: 'string', description: 'Slug of the saved article, as returned by get_reading_list.' },
+      },
+      required: ['slug'],
+    },
+    async execute({ slug }, { signal }) {
+      if (typeof slug !== 'string' || !slug) {
+        return { error: 'Pass the slug of an article on the reading list.' };
+      }
+      const current = await fetchReadingList(signal);
+      if (!current.includes(slug)) {
+        return { error: `"${slug}" is not on the reading list.`, readingList: current };
+      }
+      const readingList = await setReadingListItem(slug, false, signal);
+      return { removed: slug, readingList };
+    },
+  });
+
+  useWebMCP<{ slug?: unknown }>({
+    name: 'open_article',
+    description: 'Opens an article from The DevTools Times so the reader can read it.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        slug: { type: 'string', description: 'Article slug, as returned by search_articles or get_reading_list.' },
+      },
+      required: ['slug'],
+    },
+    async execute({ slug }) {
+      const articles = await fetchArticles();
+      const article = articles.find((entry) => entry.slug === slug);
+      if (!article) {
+        return {
+          error: `No article with slug "${String(slug)}".`,
+          availableSlugs: articles.map((entry) => entry.slug),
+        };
+      }
+      await navigate(`${BASE_URL}articles/${article.slug}`);
+      return { opened: article.title, url: articleUrl(article.slug) };
+    },
+  });
+
+  useWebMCP<{ category?: unknown }>({
+    name: 'browse_category',
+    description: 'Opens the section page listing every article in a news category.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        category: { type: 'string', enum: categories, description: 'News section to open.' },
+      },
+      required: ['category'],
+    },
+    enabled: categories.length > 0,
+    async execute({ category }) {
+      const match = categories.find((entry) => entry.toLowerCase() === String(category).toLowerCase());
+      if (!match) {
+        return { error: `Unknown category "${String(category)}".`, categories };
+      }
+      await navigate(`${BASE_URL}category/${match.toLowerCase()}`);
+      return { opened: match };
+    },
+  });
+
+  return null;
+}
