@@ -0,0 +1,34 @@
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+}
+
+let articlesPromise: Promise<ArticleSummary[]> | null = null;
+
+/** Fetches the article index once per page and shares the result between callers. */
+export function fetchArticles(): Promise<ArticleSummary[]> {
+  articlesPromise ??= fetch(`${import.meta.env.BASE_URL}api/articles.json`)
+    .then((response) => {
+      if (!response.ok) throw new Error(`Article index request failed with status ${response.status}`);
+      return response.json() as Promise<ArticleSummary[]>;
+    })
+    .catch((error) => {
+      articlesPromise = null; // allow a retry on the next call
+      throw error;
+    });
+  return articlesPromise;
+}
+
+export function articleUrl(slug: string): string {
+  return new URL(`${import.meta.env.BASE_URL}articles/${slug}`, location.origin).href;
+}
+
+export function searchArticles<T extends ArticleSummary>(articles: T[], query: string): T[] {
+  const term = query.trim().toLowerCase();
+  if (!term) return [];
+  return articles.filter(
+    (article) => article.title.toLowerCase().includes(term) || article.summary.toLowerCase().includes(term),
+  );
+}
