--- /dev/null
+++ b/src/utils/readingList.ts
@@ -0,0 +1,41 @@
+const READING_LIST_ENDPOINT = `${import.meta.env.BASE_URL}api/reading-list.json`;
+
+/** Fired on `window` whenever the reading list changes, so every UI surface stays in sync. */
+export const READING_LIST_CHANGE_EVENT = 'readinglist:change';
+
+export type ReadingListChangeEvent = CustomEvent<{ readingList: string[] }>;
+
+export async function fetchReadingList(signal?: AbortSignal): Promise<string[]> {
+  const response = await fetch(READING_LIST_ENDPOINT, { signal });
+  if (!response.ok) throw new Error(`Reading list request failed with status ${response.status}`);
+  const data = await response.json();
+  return data.readingList ?? [];
+}
+
+/** Toggles a slug on the server-side reading list and broadcasts the new list. */
+export async function toggleReadingListItem(slug: string, signal?: AbortSignal): Promise<string[]> {
+  const response = await fetch(READING_LIST_ENDPOINT, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+    signal,
+  });
+  if (!response.ok) throw new Error(`Reading list update failed with status ${response.status}`);
+  const data = await response.json();
+  const readingList: string[] = data.readingList ?? [];
+  window.dispatchEvent(new CustomEvent(READING_LIST_CHANGE_EVENT, { detail: { readingList } }));
+  return readingList;
+}
+
+/** Idempotently saves (`saved: true`) or removes (`saved: false`) a slug. */
+export async function setReadingListItem(slug: string, saved: boolean, signal?: AbortSignal): Promise<string[]> {
+  const readingList = await fetchReadingList(signal);
+  if (readingList.includes(slug) === saved) return readingList;
+  return toggleReadingListItem(slug, signal);
+}
+
+export function onReadingListChange(listener: (readingList: string[]) => void): () => void {
+  const handler = (event: Event) => listener((event as ReadingListChangeEvent).detail.readingList);
+  window.addEventListener(READING_LIST_CHANGE_EVENT, handler);
+  return () => window.removeEventListener(READING_LIST_CHANGE_EVENT, handler);
+}
