+/**
+ * WebMCP declarative-form additions to SubmitEvent (not yet in lib.dom / webmcp-types).
+ * Browsers without WebMCP leave `agentInvoked` undefined and never call `respondWith`.
+ */
+export type AgentSubmitEvent = SubmitEvent & {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+};
+
+/** Spreadable WebMCP form attributes; unknown to React's DOM types, so cast. */
+export function toolFormAttributes(attrs: {
+  toolname: string;
+  tooldescription: string;
+  toolautosubmit?: boolean;
+}): Record<string, string> {
+  const { toolname, tooldescription, toolautosubmit } = attrs;
+  return {
+    toolname,
+    tooldescription,
+    ...(toolautosubmit ? { toolautosubmit: '' } : {}),
+  };
+}
