+---
+import Layout from '../layouts/Layout.astro';
+import ArticleTeaser from '../components/ArticleTeaser.astro';
+import { getCollection } from 'astro:content';
+import { searchArticles } from '../utils/search';
+
+const query = (Astro.url.searchParams.get('q') ?? '').trim();
+const category = (Astro.url.searchParams.get('category') ?? '').trim();
+
+const articles = await getCollection('articles');
+const categories = [...new Set(articles.map((article) => article.data.category))].sort();
+
+const results = query || category
+  ? searchArticles(
+      articles.map((article) => ({ ...article.data, slug: article.id, entry: article })),
+      query,
+      { category: category || null },
+    ).map((result) => result.entry)
+  : [];
+---
+
+<Layout title={query ? `Search: ${query} | The DevTools Times` : 'Search | The DevTools Times'}>
+  <section class="max-w-6xl mx-auto px-4 py-8 md:py-12">
+    <h1 class="text-3xl md:text-4xl font-brand text-gray-900 mb-6">Search</h1>
+
+    <form action={`${import.meta.env.BASE_URL}search`} method="get" role="search" class="flex flex-wrap gap-3 mb-8">
+      <label for="search-page-q" class="sr-only">Search terms</label>
+      <input
+        id="search-page-q"
+        type="search"
+        name="q"
+        value={query}
+        placeholder="Search for articles..."
+        class="flex-grow min-w-[12rem] p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-amber-400 focus:border-transparent"
+      />
+      <label for="search-page-category" class="sr-only">Category</label>
+      <select id="search-page-category" name="category" class="p-2 border border-gray-300 rounded-md">
+        <option value="">All categories</option>
+        {categories.map((c) => <option value={c} selected={c === category}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>)}
+      </select>
+      <button type="submit" class="bg-gray-800 text-white text-sm font-semibold py-2 px-4 rounded hover:bg-gray-700">Search</button>
+    </form>
+
+    {(query || category) && (
+      <p class="text-sm text-gray-600 mb-6" data-search-result-count={results.length}>
+        {results.length} {results.length === 1 ? 'result' : 'results'}
+        {query && <> for “{query}”</>}
+        {category && <> in {category}</>}
+      </p>
+    )}
+
+    {(query || category) && results.length === 0 && (
+      <p class="text-gray-500 text-center py-8">No articles matched your search.</p>
+    )}
+
+    <div class="grid md:grid-cols-3 gap-6">
+      {results.map((article) => <ArticleTeaser article={article} />)}
+    </div>
+  </section>
+</Layout>
diff --git a/src/scripts/webmcp.ts b/src/scripts/webmcp.ts
new file mode 100644
index 0000000..7f30963
--- /dev/null
+++ b/src/scripts/webmcp.ts
@@ -0,0 +1,601 @@
+/**
+ * WebMCP integration for The DevTools Times.
+ *
+ * Exposes the site's functionality to AI agents running in the browser:
+ *
+ * 1. Declarative tools: the search and reading-list <form>s in Header.astro carry
+ *    `toolname`/`tooldescription` attributes. When an agent submits one of them,
+ *    the SubmitEvent has `agentInvoked === true`; we intercept it and answer via
+ *    `event.respondWith()` with structured data instead of navigating.
+ *
+ * 2. Imperative tools: client-side article utilities registered with
+ *    `navigator.modelContext.registerTool()`. Site-wide tools are registered once;
+ *    article-page tools are (re)registered on every Astro page load so they always
+ *    reflect the article currently on screen (the site uses <ClientRouter />).
+ *
+ * Everything is feature-detected, so browsers without WebMCP are unaffected.
+ */
+import { navigate } from 'astro:transitions/client';
+import { searchArticles } from '../utils/search';
+import { dispatchReadingListChanged } from '../utils/reading-list-events';
+
+const BASE_URL = import.meta.env.BASE_URL;
+const DEFAULT_WORDS_PER_MINUTE = 230;
+const HIGHLIGHT_NAME = 'webmcp-find-in-article';
+
+// ---------------------------------------------------------------------------
+// Data helpers
+// ---------------------------------------------------------------------------
+
+interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+  category?: string;
+  author?: string;
+  date?: string;
+  readingTime?: number;
+  tags?: string[];
+}
+
+let articlesPromise: Promise<ArticleSummary[]> | null = null;
+
+function getArticles(): Promise<ArticleSummary[]> {
+  articlesPromise ??= fetch(`${BASE_URL}api/articles.json`)
+    .then((response) => {
+      if (!response.ok) throw new Error(`Failed to load articles (HTTP ${response.status})`);
+      return response.json() as Promise<ArticleSummary[]>;
+    })
+    .catch((error) => {
+      articlesPromise = null; // allow a retry on the next call
+      throw error;
+    });
+  return articlesPromise;
+}
+
+const articleUrl = (slug: string) => new URL(`${BASE_URL}articles/${slug}`, location.origin).href;
+
+function describeArticle(article: ArticleSummary) {
+  return {
+    slug: article.slug,
+    title: article.title,
+    summary: article.summary,
+    category: article.category,
+    author: article.author,
+    date: article.date,
+    readingTimeMinutes: article.readingTime,
+    url: articleUrl(article.slug),
+  };
+}
+
+async function fetchReadingList(): Promise<string[]> {
+  const response = await fetch(`${BASE_URL}api/reading-list.json`);
+  if (!response.ok) throw new Error(`Failed to load reading list (HTTP ${response.status})`);
+  const data = await response.json();
+  return data.readingList ?? [];
+}
+
+async function updateReadingList(slug: string, action: 'add' | 'remove' | 'toggle') {
+  const response = await fetch(`${BASE_URL}api/reading-list.json`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug, action }),
+  });
+  const data = await response.json();
+  if (!response.ok) throw new Error(data.error ?? `Failed to update reading list (HTTP ${response.status})`);
+  dispatchReadingListChanged(data.readingList);
+  return data as { readingList: string[]; slug: string; saved: boolean };
+}
+
+async function describeReadingList(readingList: string[]) {
+  const articles = await getArticles();
+  const bySlug = new Map(articles.map((article) => [article.slug, article]));
+  return readingList.map((slug) => {
+    const article = bySlug.get(slug);
+    return article ? describeArticle(article) : { slug, url: articleUrl(slug) };
+  });
+}
+
+// ---------------------------------------------------------------------------
+// Current-article DOM helpers (only meaningful on /articles/[slug])
+// ---------------------------------------------------------------------------
+
+function getArticleElements() {
+  const root = document.querySelector<HTMLElement>('[data-article]');
+  const body = root?.querySelector<HTMLElement>('[data-article-body]');
+  if (!root || !body) return null;
+  return { root, body };
+}
+
+function requireArticle() {
+  const elements = getArticleElements();
+  if (!elements) throw new Error('No article is open. Use open_article to navigate to an article first.');
+  return elements;
+}
+
+const countWords = (text: string) => (text.match(/[\p{L}\p{N}'’-]+/gu) ?? []).length;
+
+function getHeadings(body: HTMLElement) {
+  return Array.from(body.querySelectorAll<HTMLHeadingElement>('h1, h2, h3, h4, h5, h6')).map((heading, index) => {
+    heading.id ||= `section-${index + 1}-${slugify(heading.textContent ?? '')}`;
+    return { element: heading, level: Number(heading.tagName[1]), text: heading.textContent?.trim() ?? '', id: heading.id };
+  });
+}
+
+const slugify = (value: string) =>
+  value.toLowerCase().trim().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
+
+function readCurrentArticle() {
+  const { root, body } = requireArticle();
+  const text = body.innerText.trim();
+  return {
+    slug: root.dataset.articleSlug ?? '',
+    title: root.querySelector('[data-article-title]')?.textContent?.trim() ?? document.title,
+    summary: root.querySelector('[data-article-summary]')?.textContent?.trim() ?? '',
+    category: root.dataset.articleCategory,
+    author: root.dataset.articleAuthor,
+    date: root.dataset.articleDate,
+    url: location.href,
+    text,
+    body,
+  };
+}
+
+// ---------------------------------------------------------------------------
+// Tool plumbing
+// ---------------------------------------------------------------------------
+
+type ToolResult = { content: { type: 'text'; text: string }[]; isError?: boolean };
+
+const ok = (data: unknown): ToolResult => ({
+  content: [{ type: 'text', text: typeof data === 'string' ? data : JSON.stringify(data, null, 2) }],
+});
+
+const fail = (error: unknown): ToolResult => ({
+  content: [{ type: 'text', text: `Error: ${error instanceof Error ? error.message : String(error)}` }],
+  isError: true,
+});
+
+/** Wraps an execute function so thrown errors become MCP error results. */
+function tool(definition: Omit<ModelContextTool, 'execute'> & { execute: (input: any) => unknown }): ModelContextTool {
+  return {
+    ...definition,
+    async execute(input: any) {
+      try {
+        const result = await definition.execute(input ?? {});
+        return (result as ToolResult)?.content ? (result as ToolResult) : ok(result);
+      } catch (error) {
+        return fail(error);
+      }
+    },
+  };
+}
+
+/**
+ * Registers tools and returns a function that unregisters them. Supports both
+ * the AbortSignal-based API and older variants that return `{ unregister }` or
+ * expose `unregisterTool(name)`.
+ */
+function registerTools(modelContext: ModelContext, tools: ModelContextTool[]): () => void {
+  const controller = new AbortController();
+  const cleanups: (() => void)[] = [];
+  for (const definition of tools) {
+    try {
+      const registration = modelContext.registerTool(definition, { signal: controller.signal });
+      if (registration && typeof registration.unregister === 'function') {
+        cleanups.push(() => registration.unregister());
+      } else if (typeof modelContext.unregisterTool === 'function') {
+        cleanups.push(() => modelContext.unregisterTool!(definition.name));
+      }
+    } catch (error) {
+      console.warn(`[WebMCP] Failed to register tool "${definition.name}":`, error);
+    }
+  }
+  return () => {
+    controller.abort();
+    for (const cleanup of cleanups) {
+      try {
+        cleanup();
+      } catch {
+        /* already unregistered */
+      }
+    }
+  };
+}
+
+// ---------------------------------------------------------------------------
+// Site-wide imperative tools
+// ---------------------------------------------------------------------------
+
+const siteTools: ModelContextTool[] = [
+  tool({
+    name: 'list_articles',
+    description:
+      'List articles published on The DevTools Times, newest first. Optionally filter by category. Returns slug, title, summary, author, date, category and URL for each article, plus the list of available categories.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        category: { type: 'string', description: "Only return articles in this category (case-insensitive), e.g. 'sports'." },
+        limit: { type: 'integer', minimum: 1, maximum: 100, description: 'Maximum number of articles to return. Defaults to all.' },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ category, limit }: { category?: string; limit?: number }) {
+      const articles = await getArticles();
+      const categories = [...new Set(articles.map((article) => article.category).filter(Boolean))].sort();
+      let list = category
+        ? articles.filter((article) => article.category?.toLowerCase() === category.toLowerCase())
+        : [...articles];
+      list.sort((a, b) => (b.date ?? '').localeCompare(a.date ?? ''));
+      if (limit) list = list.slice(0, limit);
+      return { total: list.length, categories, articles: list.map(describeArticle) };
+    },
+  }),
+
+  tool({
+    name: 'get_reading_list',
+    description: "Get the articles currently saved in the reader's reading list.",
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const readingList = await fetchReadingList();
+      return { count: readingList.length, articles: await describeReadingList(readingList) };
+    },
+  }),
+
+  tool({
+    name: 'open_article',
+    description: 'Navigate the browser to an article on The DevTools Times so it can be read or used with the article tools.',
+    inputSchema: {
+      type: 'object',
+      properties: { slug: { type: 'string', description: 'Slug of the article to open (as returned by search_articles or list_articles).' } },
+      required: ['slug'],
+    },
+    async execute({ slug }: { slug: string }) {
+      const articles = await getArticles();
+      const article = articles.find((candidate) => candidate.slug === slug);
+      if (!article) throw new Error(`Unknown article slug "${slug}". Use search_articles or list_articles to find valid slugs.`);
+      const url = articleUrl(slug);
+      // Defer so the result is delivered before the page transition starts.
+      setTimeout(() => navigate(url), 0);
+      return { navigatingTo: url, title: article.title };
+    },
+  }),
+
+  tool({
+    name: 'get_page_context',
+    description:
+      'Describe the page currently open in the browser: URL, title, page type (home, article, category, search, other) and, on article pages, which article is shown.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    execute() {
+      const path = location.pathname.slice(BASE_URL.length - 1).replace(/\/+$/, '') || '/';
+      const article = getArticleElements();
+      const pageType = article
+        ? 'article'
+        : path === '/'
+          ? 'home'
+          : path.startsWith('/category/')
+            ? 'category'
+            : path.startsWith('/search')
+              ? 'search'
+              : 'other';
+      return {
+        url: location.href,
+        title: document.title,
+        pageType,
+        article: article ? { slug: article.root.dataset.articleSlug, title: article.root.querySelector('[data-article-title]')?.textContent?.trim() } : undefined,
+        searchQuery: pageType === 'search' ? new URLSearchParams(location.search).get('q') : undefined,
+      };
+    },
+  }),
+];
+
+// ---------------------------------------------------------------------------
+// Article-page imperative tools
+// ---------------------------------------------------------------------------
+
+function clearFindHighlight() {
+  CSS.highlights?.delete(HIGHLIGHT_NAME);
+}
+
+function findTextRanges(body: HTMLElement, query: string, caseSensitive: boolean) {
+  const needle = caseSensitive ? query : query.toLowerCase();
+  const ranges: Range[] = [];
+  const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT);
+  for (let node = walker.nextNode() as Text | null; node; node = walker.nextNode() as Text | null) {
+    const haystack = caseSensitive ? node.data : node.data.toLowerCase();
+    let index = haystack.indexOf(needle);
+    while (index !== -1) {
+      const range = document.createRange();
+      range.setStart(node, index);
+      range.setEnd(node, index + needle.length);
+      ranges.push(range);
+      index = haystack.indexOf(needle, index + needle.length);
+    }
+  }
+  return ranges;
+}
+
+function snippetFor(range: Range, radius = 60) {
+  const block = (range.startContainer.parentElement?.closest('p, li, h1, h2, h3, h4, h5, h6, blockquote, td') ??
+    range.startContainer.parentElement) as HTMLElement | null;
+  const text = block?.textContent ?? range.startContainer.textContent ?? '';
+  const match = range.toString();
+  const position = text.indexOf(match);
+  if (position === -1) return text.slice(0, radius * 2);
+  const start = Math.max(0, position - radius);
+  const end = Math.min(text.length, position + match.length + radius);
+  return `${start > 0 ? '…' : ''}${text.slice(start, end)}${end < text.length ? '…' : ''}`.replace(/\s+/g, ' ');
+}
+
+const articleTools: ModelContextTool[] = [
+  tool({
+    name: 'get_article_content',
+    description:
+      'Read the article currently open in the browser: title, summary, author, publication date, category, section outline and the full body text.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        includeBody: { type: 'boolean', description: 'Include the full body text. Defaults to true; set false to only get metadata and outline.' },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    execute({ includeBody = true }: { includeBody?: boolean }) {
+      const { body, text, ...article } = readCurrentArticle();
+      return {
+        ...article,
+        outline: getHeadings(body).map(({ level, text: heading, id }) => ({ level, heading, id })),
+        body: includeBody ? text : undefined,
+      };
+    },
+  }),
+
+  tool({
+    name: 'get_article_stats',
+    description:
+      'Compute reading statistics for the article currently open: word count, paragraph count, number of sections and estimated reading time.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        wordsPerMinute: {
+          type: 'integer',
+          minimum: 50,
+          maximum: 1000,
+          description: `Reading speed used for the time estimate. Defaults to ${DEFAULT_WORDS_PER_MINUTE}.`,
+        },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    execute({ wordsPerMinute = DEFAULT_WORDS_PER_MINUTE }: { wordsPerMinute?: number }) {
+      const { root, body } = requireArticle();
+      const words = countWords(body.innerText);
+      const minutes = words / wordsPerMinute;
+      return {
+        slug: root.dataset.articleSlug,
+        wordCount: words,
+        paragraphCount: body.querySelectorAll('p').length,
+        sectionCount: getHeadings(body).length,
+        wordsPerMinute,
+        estimatedReadingTimeMinutes: Math.max(1, Math.round(minutes)),
+        estimatedReadingTimeSeconds: Math.round(minutes * 60),
+        publisherReadingTimeMinutes: root.dataset.articleReadingTime ? Number(root.dataset.articleReadingTime) : undefined,
+      };
+    },
+  }),
+
+  tool({
+    name: 'find_in_article',
+    description:
+      'Find occurrences of a word or phrase in the article currently open. Returns surrounding text snippets for each match, highlights all matches on the page and scrolls the first (or chosen) match into view.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        query: { type: 'string', minLength: 1, description: 'Word or phrase to find.' },
+        caseSensitive: { type: 'boolean', description: 'Match case exactly. Defaults to false.' },
+        scrollToMatch: { type: 'integer', minimum: 1, description: '1-based index of the match to scroll into view. Defaults to 1.' },
+      },
+      required: ['query'],
+    },
+    execute({ query, caseSensitive = false, scrollToMatch = 1 }: { query: string; caseSensitive?: boolean; scrollToMatch?: number }) {
+      const { body } = requireArticle();
+      if (!query?.trim()) throw new Error('query must not be empty.');
+      clearFindHighlight();
+      const ranges = findTextRanges(body, query, caseSensitive);
+      if (ranges.length > 0) {
+        if (typeof Highlight !== 'undefined' && CSS.highlights) {
+          CSS.highlights.set(HIGHLIGHT_NAME, new Highlight(...ranges));
+        }
+        const target = ranges[Math.min(scrollToMatch, ranges.length) - 1];
+        target.startContainer.parentElement?.scrollIntoView({ behavior: 'smooth', block: 'center' });
+      }
+      return {
+        query,
+        matchCount: ranges.length,
+        matches: ranges.slice(0, 25).map((range, index) => ({ index: index + 1, snippet: snippetFor(range) })),
+        truncated: ranges.length > 25 || undefined,
+      };
+    },
+  }),
+
+  tool({
+    name: 'scroll_to_section',
+    description: 'Scroll the article currently open to a section heading. Use get_article_content to see the available sections.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        heading: { type: 'string', description: 'Section heading text (case-insensitive, partial match allowed) or heading id.' },
+      },
+      required: ['heading'],
+    },
+    execute({ heading }: { heading: string }) {
+      const { body } = requireArticle();
+      const headings = getHeadings(body);
+      const needle = heading.trim().toLowerCase();
+      const match =
+        headings.find((h) => h.id === heading || h.text.toLowerCase() === needle) ??
+        headings.find((h) => h.text.toLowerCase().includes(needle));
+      if (!match) {
+        throw new Error(
+          `No section matching "${heading}". Available sections: ${headings.map((h) => h.text).join(', ') || 'none'}.`,
+        );
+      }
+      match.element.scrollIntoView({ behavior: 'smooth', block: 'start' });
+      return { scrolledTo: match.text, id: match.id };
+    },
+  }),
+
+  tool({
+    name: 'share_article',
+    description:
+      'Get a shareable link for the article currently open, optionally with a pre-filled share URL for a social platform, and try to copy the link to the clipboard.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        platform: { type: 'string', enum: ['link', 'x', 'facebook', 'email'], description: "Where to share. Defaults to 'link'." },
+      },
+    },
+    async execute({ platform = 'link' }: { platform?: 'link' | 'x' | 'facebook' | 'email' }) {
+      const { title } = readCurrentArticle();
+      const url = location.origin + location.pathname;
+      const shareUrls: Record<string, string> = {
+        link: url,
+        x: `https://x.com/intent/post?url=${encodeURIComponent(url)}&text=${encodeURIComponent(title)}`,
+        facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`,
+        email: `mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(url)}`,
+      };
+      let copiedToClipboard = false;
+      try {
+        await navigator.clipboard.writeText(url);
+        copiedToClipboard = true;
+      } catch {
+        // Clipboard access may require focus/user activation; the link is still returned.
+      }
+      return { title, url, shareUrl: shareUrls[platform] ?? url, platform, copiedToClipboard };
+    },
+  }),
+
+  tool({
+    name: 'toggle_current_article_bookmark',
+    description: "Save the article currently open to the reader's reading list, or remove it.",
+    inputSchema: {
+      type: 'object',
+      properties: {
+        saved: { type: 'boolean', description: 'true to save the article, false to remove it. Omit to toggle.' },
+      },
+    },
+    async execute({ saved }: { saved?: boolean }) {
+      const { root } = requireArticle();
+      const slug = root.dataset.articleSlug!;
+      const result = await updateReadingList(slug, saved === undefined ? 'toggle' : saved ? 'add' : 'remove');
+      return { slug, saved: result.saved, readingListCount: result.readingList.length };
+    },
+  }),
+];
+
+// ---------------------------------------------------------------------------
+// Declarative form tools
+// ---------------------------------------------------------------------------
+
+async function handleSearchForm(form: HTMLFormElement) {
+  const data = new FormData(form);
+  const query = String(data.get('q') ?? '').trim();
+  const category = String(data.get('category') ?? '').trim() || null;
+  if (!query) throw new Error('Search query must not be empty.');
+  const results = searchArticles(await getArticles(), query, { category, limit: 20 });
+  const searchUrl = new URL(`${BASE_URL}search`, location.origin);
+  searchUrl.searchParams.set('q', query);
+  if (category) searchUrl.searchParams.set('category', category);
+  return {
+    query,
+    category,
+    resultCount: results.length,
+    results: results.map(describeArticle),
+    searchPageUrl: searchUrl.href,
+  };
+}
+
+async function handleReadingListForm(form: HTMLFormElement) {
+  const data = new FormData(form);
+  const slug = String(data.get('slug') ?? '');
+  const action = String(data.get('action') ?? 'toggle') as 'add' | 'remove' | 'toggle';
+  const result = await updateReadingList(slug, action);
+  return {
+    action,
+    slug,
+    saved: result.saved,
+    readingList: await describeReadingList(result.readingList),
+  };
+}
+
+const formHandlers: Record<string, (form: HTMLFormElement) => Promise<unknown>> = {
+  search_articles: handleSearchForm,
+  update_reading_list: handleReadingListForm,
+};
+
+function onSubmit(event: Event) {
+  const submitEvent = event as SubmitEvent;
+  const form = submitEvent.target;
+  if (!(form instanceof HTMLFormElement)) return;
+  const toolName = form.getAttribute('toolname');
+  const handler = toolName ? formHandlers[toolName] : undefined;
+  if (!handler) return;
+
+  if (submitEvent.agentInvoked && typeof submitEvent.respondWith === 'function') {
+    // Answer the agent directly with structured data; no navigation.
+    submitEvent.preventDefault();
+    submitEvent.respondWith(handler(form).then(ok, fail));
+    return;
+  }
+
+  // Human submission: the reading-list form is handled in-page so the rest of
+  // the UI updates without a reload. Search falls through to the search page.
+  if (toolName === 'update_reading_list') {
+    submitEvent.preventDefault();
+    handler(form).catch((error) => console.error('[WebMCP] Reading list update failed:', error));
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Bootstrap
+// ---------------------------------------------------------------------------
+
+function installHighlightStyle() {
+  if (document.getElementById('webmcp-highlight-style')) return;
+  const style = document.createElement('style');
+  style.id = 'webmcp-highlight-style';
+  style.textContent = `::highlight(${HIGHLIGHT_NAME}) { background-color: #fcd34d; color: inherit; }`;
+  document.head.append(style);
+}
+
+function init() {
+  // Capture phase on window so we run before Astro's ClientRouter form handler.
+  window.addEventListener('submit', onSubmit, true);
+
+  const modelContext = navigator.modelContext;
+  if (!modelContext?.registerTool) return;
+
+  registerTools(modelContext, siteTools);
+
+  let unregisterArticleTools: (() => void) | null = null;
+  const syncArticleTools = () => {
+    unregisterArticleTools?.();
+    unregisterArticleTools = null;
+    clearFindHighlight();
+    if (getArticleElements()) {
+      installHighlightStyle();
+      unregisterArticleTools = registerTools(modelContext, articleTools);
+    }
+  };
+
+  // `astro:page-load` fires on the initial load and after every client-side navigation.
+  document.addEventListener('astro:page-load', syncArticleTools);
+  syncArticleTools(); // in case the initial page-load event fired before this module ran
+  document.addEventListener('astro:before-swap', () => {
+    unregisterArticleTools?.();
+    unregisterArticleTools = null;
+  });
+}
+
+init();
