+/** Broadcast whenever the reading list changes so all mounted UI can resync. */
+export const READING_LIST_CHANGED = 'reading-list:changed';
+
+export interface ReadingListChangedDetail {
+  readingList: string[];
+}
+
+export function dispatchReadingListChanged(readingList: string[]) {
+  window.dispatchEvent(
+    new CustomEvent<ReadingListChangedDetail>(READING_LIST_CHANGED, { detail: { readingList } }),
+  );
+}
+
+export function onReadingListChanged(callback: (readingList: string[]) => void) {
+  const listener = (event: Event) => callback((event as CustomEvent<ReadingListChangedDetail>).detail.readingList);
+  window.addEventListener(READING_LIST_CHANGED, listener);
+  return () => window.removeEventListener(READING_LIST_CHANGED, listener);
+}
