+/**
+ * Shared, framework-agnostic article search used by both the server-rendered
+ * search page and the client-side WebMCP tools.
+ */
+export interface SearchableArticle {
+  slug: string;
+  title: string;
+  summary: string;
+  category?: string;
+  author?: string;
+  tags?: string[];
+}
+
+export interface SearchOptions {
+  category?: string | null;
+  limit?: number;
+}
+
+const normalize = (value: string) => value.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
+
+/**
+ * Ranks articles against a free-text query. Every whitespace-separated term
+ * must match somewhere; title matches score highest, then tags/category/author,
+ * then summary.
+ */
+export function searchArticles<T extends SearchableArticle>(
+  articles: T[],
+  query: string,
+  { category, limit }: SearchOptions = {},
+): T[] {
+  const terms = normalize(query).split(/\s+/).filter(Boolean);
+  const wantedCategory = category ? normalize(category) : null;
+
+  const scored: { article: T; score: number }[] = [];
+  for (const article of articles) {
+    if (wantedCategory && normalize(article.category ?? '') !== wantedCategory) continue;
+
+    const title = normalize(article.title);
+    const summary = normalize(article.summary);
+    const meta = normalize([article.category, article.author, ...(article.tags ?? [])].filter(Boolean).join(' '));
+
+    let score = 0;
+    let allTermsMatch = true;
+    for (const term of terms) {
+      const termScore = (title.includes(term) ? 5 : 0) + (meta.includes(term) ? 3 : 0) + (summary.includes(term) ? 1 : 0);
+      if (termScore === 0) {
+        allTermsMatch = false;
+        break;
+      }
+      score += termScore;
+    }
+    if (!allTermsMatch) continue;
+    scored.push({ article, score });
+  }
+
+  scored.sort((a, b) => b.score - a.score);
+  const results = scored.map((entry) => entry.article);
+  return typeof limit === 'number' && limit > 0 ? results.slice(0, limit) : results;
+}
